-- SQLite CHECK constraints translated to PostgreSQL-native expressions.
ALTER TABLE "schema_migrations" ADD CONSTRAINT "ck_schema_migrations_1" CHECK (status IN ('applied', 'rolled_back', 'failed')) NOT VALID;
ALTER TABLE "tenants" ADD CONSTRAINT "ck_tenants_1" CHECK (service_mode IN ('internal_only', 'public_service')) NOT VALID;
ALTER TABLE "tenants" ADD CONSTRAINT "ck_tenants_2" CHECK (status IN ('active', 'disabled')) NOT VALID;
ALTER TABLE "seed_runs" ADD CONSTRAINT "ck_seed_runs_1" CHECK (status IN ('applied', 'skipped', 'failed')) NOT VALID;
ALTER TABLE "users" ADD CONSTRAINT "ck_users_1" CHECK (status IN ('active', 'disabled')) NOT VALID;
ALTER TABLE "virtual_keys" ADD CONSTRAINT "ck_virtual_keys_1" CHECK (status IN ('active', 'disabled')) NOT VALID;
ALTER TABLE "virtual_keys" ADD CONSTRAINT "ck_virtual_keys_2" CHECK (environment IN ('dev', 'test', 'prod')) NOT VALID;
ALTER TABLE "models" ADD CONSTRAINT "ck_models_1" CHECK (status IN ('active', 'disabled')) NOT VALID;
ALTER TABLE "models" ADD CONSTRAINT "ck_models_2" CHECK (context_window >= 0) NOT VALID;
ALTER TABLE "models" ADD CONSTRAINT "ck_models_3" CHECK (input_price_per_1k >= 0) NOT VALID;
