on, '$.would_error_code') = 'null' OR ( json_type(payload_json, '$.would_error_code') = 'text' AND length(json_extract(payload_json, '$.would_error_code')) BETWEEN 1 AND 128 AND json_extract(payload_json, '$.would_error_code') OPERATOR(public.@@) 'gateway.*' ) ) AND json_type(payload_json, '$.checked_policy_count') = 'integer' AND (json_extract(payload_json, '$.checked_policy_count'))::NUMERIC BETWEEN 0 AND 200 AND json_type(payload_json, '$.runtime_compatible') IN ('true', 'false') AND json_type(payload_json, '$.coverage_complete') = 'false', FALSE )) NOT VALID;
