ange_kinds')='array' AND json_array_length(payload_json, '$.change_kinds') BETWEEN 1 AND 5 AND json_type(payload_json, '$.changed_routing_fields')='array' AND json_array_length(payload_json, '$.changed_routing_fields') BETWEEN 1 AND 8 AND ( json_type(payload_json, '$.previous_mode')='null' OR json_extract(payload_json, '$.previous_mode') IN ('fixed', 'cost_first', 'availability_first', 'quality_cost') ) AND json_extract(payload_json, '$.routing_mode') IN ('fixed', 'cost_first', 'availability_first', 'quality_cost') AND json_type(payload_json, '$.quality_cost_config')='object' AND json_remove( json_extract(payload_json, '$.quality_cost_config'), '$.quality_weight_bps', '$.cost_weight_bps', '$.latency_weight_bps', '$.quality_floor_bps', '$.minimum_sample_count' )='{}' AND json_type(payload_json, '$.quality_cost_config.quality_weight_bps')='integer' AND (json_extract(payload_json, '$.quality_cost_config.quality_weight_bps'))::NUMERIC BETWEEN 1 AND 10000 AND json_type(payload_json, '$.quality_cost_config.cost_weight_bps')='integer' AND (json_extract(payload_json, '$.quality_cost_config.cost_weight_bps'))::NUMERIC BETWEEN 0 AND 10000 AND json_type(payload_json, '$.quality_cost_config.latency_weight_bps')='integer' AND (json_extract(payload_json, '$.quality_cost_config.latency_weight_bps'))::NUMERIC BETWEEN 0 AND 10000 AND json_type(payload_json, '$.quality_cost_config.quality_floor_bps')='integer' AND (json_extract(payload_json, '$.quality_cost_config.quality_floor_bps'))::NUMERIC BETWEEN 1 AND 10000 AND json_type(payload_json, '$.quality_cost_config.minimum_sample_count')='integer' AND (json_extract(payload_json, '$.quality_cost_config.minimum_sample_count'))::NUMERIC BETWEEN 1 AND 10000 AND (json_extract(payload_json, '$.quality_cost_config.quality_weight_bps'))::NUMERIC + (json_extract(payload_json, '$.quality_cost_config.cost_weight_bps'))::NUMERIC + (json_extract(payload_json, '$.quality_cost_config.latency_weight_bps'))::NUMERIC=10000, FALSE ) )) NOT VALID;
