INSERT INTO "tenant_deletion_trigger_manifest" ("trigger_name", "source_table", "trigger_sql", "trigger_sha256") VALUES
('trg_access_token_grants_delete_prd118', 'access_token_grants', 'CREATE TRIGGER trg_access_token_grants_delete_prd118
BEFORE DELETE ON access_token_grants
BEGIN SELECT RAISE(ABORT,''access_token_grant_immutable''); END', '08ecdca23ed523e0563a7b96174366d3114279cd2c23abd5b69fef60bf4f46f2'),
('trg_access_token_grants_insert_prd118', 'access_token_grants', 'CREATE TRIGGER trg_access_token_grants_insert_prd118
BEFORE INSERT ON access_token_grants FOR EACH ROW
WHEN json_array_length(NEW.scopes_json)<1 OR NOT EXISTS(
  SELECT 1 FROM oauth_clients client
  JOIN service_accounts account
    ON account.service_account_id=client.service_account_id
   AND account.workspace_id=client.workspace_id AND account.tenant_id=client.tenant_id
  JOIN client_credentials credential
    ON credential.oauth_client_id=client.oauth_client_id
   AND credential.generation=NEW.credential_generation
  WHERE client.oauth_client_id=NEW.oauth_client_id
    AND account.service_account_id=NEW.service_account_id
    AND client.workspace_id=NEW.workspace_id AND client.tenant_id=NEW.tenant_id
    AND client.status=''active'' AND account.status=''active''
    AND credential.status IN(''active'',''grace''))
  OR EXISTS(SELECT 1 FROM json_each(NEW.scopes_json) requested
    WHERE requested.type!=''text'' OR NOT EXISTS(
      SELECT 1 FROM service_account_scopes assigned
      JOIN machine_permission_catalog catalog
        ON catalog.permission_code=assigned.permission_code AND catalog.status=''active''
      WHERE assigned.service_account_id=NEW.service_account_id
        AND assigned.permission_code=requested.value))
BEGIN SELECT RAISE(ABORT,''access_token_grant_owner_invalid''); END', 'b40d92bccbf40e63d3cc63d0457ec3b053aea5364084388a13fbe80c787da553'),
('trg_access_token_grants_update_prd118', 'access_token_grants', 'CREATE TRIGGER trg_access_token_grants_update_prd118
BEFORE UPDATE ON access_token_grants FOR EACH ROW
WHEN NEW.access_token_grant_id!=OLD.access_token_grant_id
  OR NEW.token_hash!=OLD.token_hash
  OR NEW.service_account_id!=OLD.service_account_id
  OR NEW.oauth_client_id!=OLD.oauth_client_id
  OR NEW.workspace_id!=OLD.workspace_id OR NEW.tenant_id!=OLD.tenant_id
  OR NEW.scopes_json!=OLD.scopes_json OR NEW.audience!=OLD.audience
  OR NEW.operator_permission_revision!=OLD.operator_permission_revision
  OR NEW.operator_authorization_fingerprint!=OLD.operator_authorization_fingerprint
  OR NEW.catalog_revision!=OLD.catalog_revision
  OR NEW.credential_generation!=OLD.credential_generation
  OR NEW.constraint_generation!=OLD.constraint_generation
  OR NEW.issued_at!=OLD.issued_at OR NEW.created_at!=OLD.created_at
  OR OLD.status=''revoked''
  OR (OLD.last_used_at IS NOT NULL AND (NEW.last_used_at IS NULL
      OR NEW.last_used_at<OLD.last_used_at))
  OR NEW.updated_at<OLD.updated_at
  OR NOT(
    (NEW.status=OLD.status AND NEW.expires_at=OLD.expires_at
      AND NEW.revoked_at IS OLD.revoked_at)
    OR(OLD.status=''active'' AND NEW.status=''active''
      AND NEW.expires_at<OLD.expires_at
      AND NEW.revoked_at IS OLD.revoked_at
      AND NEW.last_used_at IS OLD.last_used_at)
    OR(OLD.status=''active'' AND NEW.status=''revoked''
      AND NEW.expires_at=OLD.expires_at
      AND OLD.revoked_at IS NULL AND NEW.revoked_at IS NOT NULL
      AND NEW.last_used_at IS OLD.last_used_at))
BEGIN SELECT RAISE(ABORT,''access_token_grant_transition_invalid''); END', 'ebf5c920d6f0b71276b2c5dd06cffa76f4d7206873a9cffb9f02f5f6608c9a16'),
('trg_federation_links_delete_prd114', 'account_federation_links', 'CREATE TRIGGER trg_federation_links_delete_prd114 BEFORE DELETE ON account_federation_links
BEGIN SELECT RAISE(ABORT,''federation_link_immutable''); END', '86021e67c46be065c1074152c0f1992bf104bed7349a4e80e99079c0624e9d9e'),
('trg_federation_links_owner_prd114', 'account_federation_links', 'CREATE TRIGGER trg_federation_links_owner_prd114
BEFORE INSERT ON account_federation_links FOR EACH ROW
WHEN NOT EXISTS(SELECT 1 FROM workspace_memberships member
  WHERE member.workspace_membership_id=NEW.membership_id
    AND member.workspace_id=NEW.workspace_id AND member.tenant_id=NEW.tenant_id
    AND member.account_id=NEW.account_id AND member.status=''active''
    AND member.role_code!=''service_account'')
BEGIN SELECT RAISE(ABORT,''federation_link_owner_invalid''); END', 'e32c266723dd218148924c566cb950a12eb593f5921ee449fc686c58d5acf9a7'),
('trg_federation_links_update_prd114', 'account_federation_links', 'CREATE TRIGGER trg_federation_links_update_prd114
BEFORE UPDATE ON account_federation_links FOR EACH ROW
WHEN NEW.account_federation_link_id!=OLD.account_federation_link_id
  OR NEW.workspace_id!=OLD.workspace_id OR NEW.tenant_id!=OLD.tenant_id
  OR NEW.sso_connection_id!=OLD.sso_connection_id OR NEW.account_id!=OLD.account_id
  OR NEW.membership_id!=OLD.membership_id
  OR NEW.external_subject_hmac!=OLD.external_subject_hmac
  OR NEW.verified_email_hmac!=OLD.verified_email_hmac OR NEW.linked_at!=OLD.linked_at
  OR OLD.status!=''active'' OR NEW.status!=''disabled''
  OR NEW.revision!=OLD.revision+1 OR NEW.updated_at<=OLD.updated_at
BEGIN SELECT RAISE(ABORT,''federation_link_transition_invalid''); END', '16754240eb0ee0c2da6061112c1f0ca244aeb35833d4995d1847bb45af8c304e'),
('trg_account_identity_links_delete_prd091', 'account_identity_links', 'CREATE TRIGGER trg_account_identity_links_delete_prd091
BEFORE DELETE ON account_identity_links FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''identity_link_immutable''); END', 'd938c223a895924f5b39ad67bab999c58ed6c0ca3a91b4f2d7bc402ce3a8f485'),
('trg_account_identity_links_immutable_prd091', 'account_identity_links', 'CREATE TRIGGER trg_account_identity_links_immutable_prd091
BEFORE UPDATE ON account_identity_links FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''identity_link_immutable''); END', 'ee33af8eb76cad63b98dd02eb32bcc3a9f43f3c99086770927398dfc1f572d42'),
('trg_account_links_membership_backfill_prd094', 'account_identity_links', 'CREATE TRIGGER trg_account_links_membership_backfill_prd094
AFTER INSERT ON account_identity_links FOR EACH ROW
WHEN NEW.source_type=''legacy_user'' AND NEW.status=''active''
  AND NOT EXISTS(SELECT 1 FROM workspace_user_projection_claims claim
    WHERE claim.tenant_id=NEW.legacy_tenant_id AND claim.legacy_user_id=NEW.legacy_user_id
      AND claim.status=''pending'')
  AND NOT EXISTS(
    SELECT 1
    FROM membership_invitations membership_invitation
    JOIN invitations invitation
      ON invitation.tenant_id=membership_invitation.tenant_id
     AND invitation.invitation_id=membership_invitation.legacy_invitation_id
    JOIN users invited_user
      ON invited_user.tenant_id=invitation.tenant_id
     AND invited_user.user_id=NEW.legacy_user_id
    WHERE membership_invitation.status=''pending'' AND invitation.status=''pending''
      AND invitation.tenant_id=NEW.legacy_tenant_id
      AND lower(invitation.email)=lower(invited_user.email))
BEGIN
  INSERT OR IGNORE INTO workspace_memberships(
    workspace_membership_id,workspace_id,tenant_id,account_id,legacy_user_id,
    role_code,status,source,revision,created_by_account_id,updated_by_account_id,
    created_at,updated_at)
  SELECT ''wmb_''||lower(hex(randomblob(16))),binding.workspace_id,NEW.legacy_tenant_id,
    NEW.account_id,NEW.legacy_user_id,
    CASE WHEN user.role=''admin'' AND user.status=''active''
          AND NOT EXISTS(SELECT 1 FROM workspace_memberships current
            WHERE current.workspace_id=binding.workspace_id)
          AND workspace.creation_source!=''user_created'' THEN ''owner''
      WHEN user.role IN(''admin'',''ops_admin'') THEN ''admin''
      WHEN user.role=''developer'' THEN ''developer''
      WHEN user.role=''security_admin'' THEN ''security_admin''
      WHEN user.role=''finance_admin'' THEN ''finance_admin''
      ELSE ''viewer'' END,
    CASE WHEN user.status=''active'' THEN ''active'' ELSE ''disabled'' END,
    ''legacy_backfill'',1,NEW.account_id,NEW.account_id,user.created_at,user.updated_at
  FROM workspace_tenant_bindings binding
  JOIN workspaces workspace ON workspace.workspace_id=binding.workspace_id
  JOIN users user ON user.tenant_id=NEW.legacy_tenant_id
    AND user.user_id=NEW.legacy_user_id
  WHERE binding.tenant_id=NEW.legacy_tenant_id
    AND workspace.workspace_id NOT IN(
      SELECT conflict.workspace_id FROM workspace_membership_migration_conflicts conflict)
    AND NOT EXISTS(SELECT 1 FROM workspace_memberships current
      WHERE current.workspace_id=binding.workspace_id AND current.account_id=NEW.account_id);
END', 'ccd312268c66dc3c3798d67e2c069fcd7ff902e372e350f5d77d8f2cad0423ff'),
('trg_activation_checkpoints_delete_prd097', 'activation_checkpoints', 'CREATE TRIGGER trg_activation_checkpoints_delete_prd097
BEFORE DELETE ON activation_checkpoints FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''prd097.activation_checkpoint_immutable''); END', 'db7ef9bf4045d038152bcc52377c450b6da54b099ffb60151edf98d1423b2706'),
('trg_activation_checkpoints_update_prd097', 'activation_checkpoints', 'CREATE TRIGGER trg_activation_checkpoints_update_prd097
BEFORE UPDATE ON activation_checkpoints FOR EACH ROW
