('trg_adapter_contract_cases_immutable_delete_prd064', 'adapter_contract_cases', 'CREATE TRIGGER trg_adapter_contract_cases_immutable_delete_prd064
BEFORE DELETE ON adapter_contract_cases FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''adapter_contract_case_immutable''); END', '316a9a4272fdfe5b4b065ff52e14c641c3c9e1834a9592637e924be398506e60'),
('trg_adapter_contract_cases_immutable_update_prd064', 'adapter_contract_cases', 'CREATE TRIGGER trg_adapter_contract_cases_immutable_update_prd064
BEFORE UPDATE ON adapter_contract_cases FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''adapter_contract_case_immutable''); END', '6d11fb7344cb1cee43456ce78e1c2a5b59701c5b811623ddc9049f514e199ba5'),
('trg_adapter_contract_cases_owner_insert_prd064', 'adapter_contract_cases', 'CREATE TRIGGER trg_adapter_contract_cases_owner_insert_prd064
BEFORE INSERT ON adapter_contract_cases FOR EACH ROW
WHEN NOT EXISTS (
  SELECT 1 FROM adapter_contract_runs run
  WHERE run.tenant_id=NEW.tenant_id
    AND run.adapter_contract_run_id=NEW.adapter_contract_run_id
    AND unixepoch(NEW.created_at)>=unixepoch(run.completed_at)
    AND (
      NEW.status=''passed''
      OR NEW.failure_code=CASE NEW.case_kind
        WHEN ''request'' THEN ''adapter.contract_request_failed''
        WHEN ''non_stream'' THEN ''adapter.contract_non_stream_failed''
        WHEN ''stream'' THEN ''adapter.contract_stream_failed''
        WHEN ''error'' THEN ''adapter.contract_error_mapping_failed''
        WHEN ''usage'' THEN ''adapter.contract_usage_failed''
      END
      OR (run.suite_kind=''probe'' AND NEW.failure_code=''adapter.contract_probe_failed'')
    )
)
BEGIN SELECT RAISE(ABORT,''adapter_contract_case_owner_invalid''); END', '5771459f21172c2ae602bc3e670799ebff473c74a9b70962d9bf60ffdf968a82'),
('trg_adapter_contract_event_immutable_delete_prd064', 'adapter_contract_event_outbox', 'CREATE TRIGGER trg_adapter_contract_event_immutable_delete_prd064
BEFORE DELETE ON adapter_contract_event_outbox FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''adapter_contract_event_immutable''); END', 'f2e81584416c66e6817498ad297290a935876a25f1c355ffda87c032edaa61cc'),
('trg_adapter_contract_event_state_update_prd064', 'adapter_contract_event_outbox', 'CREATE TRIGGER trg_adapter_contract_event_state_update_prd064
BEFORE UPDATE ON adapter_contract_event_outbox FOR EACH ROW
WHEN NOT (
  NEW.rowid=OLD.rowid
  AND NEW.event_id=OLD.event_id AND NEW.tenant_id=OLD.tenant_id
  AND NEW.adapter_contract_run_id=OLD.adapter_contract_run_id
  AND NEW.created_at=OLD.created_at
  AND unixepoch(NEW.updated_at)>=unixepoch(OLD.updated_at)
  AND (
    (
      (
        (OLD.dispatch_status=''pending'' AND unixepoch(OLD.next_attempt_at)<=unixepoch(NEW.updated_at))
        OR (OLD.dispatch_status=''processing'' AND OLD.dispatch_attempts BETWEEN 1 AND 9
            AND unixepoch(OLD.lease_expires_at)<=unixepoch(NEW.updated_at))
      )
      AND NEW.dispatch_status=''processing''
      AND NEW.dispatch_attempts=OLD.dispatch_attempts+1
      AND NEW.next_attempt_at IS NULL AND NEW.dispatched_at IS NULL
      AND NEW.claim_token IS NOT NULL AND length(NEW.claim_token)=32
      AND NEW.claim_token NOT GLOB ''*[^0-9a-f]*''
      AND NEW.lease_owner_id IS NOT NULL AND length(NEW.lease_owner_id) BETWEEN 1 AND 128
      AND NEW.lease_owner_id NOT GLOB ''*[^A-Za-z0-9._:-]*''
      AND unixepoch(NEW.lease_expires_at)=unixepoch(NEW.updated_at)+30
      AND NEW.last_error_code IS NULL
    )
    OR (
      OLD.dispatch_status=''processing''
      AND NEW.dispatch_attempts=OLD.dispatch_attempts
      AND NEW.claim_token IS NULL AND NEW.lease_owner_id IS NULL AND NEW.lease_expires_at IS NULL
      AND (
        (
          unixepoch(OLD.lease_expires_at)>unixepoch(NEW.updated_at)
          AND (
            (NEW.dispatch_status=''dispatched'' AND NEW.dispatched_at=NEW.updated_at
              AND NEW.next_attempt_at IS NULL AND NEW.last_error_code IS NULL)
            OR (OLD.dispatch_attempts<10 AND NEW.dispatch_status=''pending''
              AND NEW.dispatched_at IS NULL AND NEW.last_error_code IS NOT NULL
              AND unixepoch(NEW.next_attempt_at)=unixepoch(NEW.updated_at)+CASE
                WHEN OLD.dispatch_attempts=1 THEN 5
                WHEN OLD.dispatch_attempts=2 THEN 30
                ELSE 300 END)
            OR (OLD.dispatch_attempts=10 AND NEW.dispatch_status=''failed''
              AND NEW.next_attempt_at IS NULL AND NEW.dispatched_at IS NULL
              AND NEW.last_error_code IS NOT NULL)
          )
        )
        OR (
          OLD.dispatch_attempts=10
          AND unixepoch(OLD.lease_expires_at)<=unixepoch(NEW.updated_at)
          AND NEW.dispatch_status=''failed'' AND NEW.next_attempt_at IS NULL
          AND NEW.dispatched_at IS NULL AND NEW.last_error_code IS NOT NULL
        )
      )
    )
  )
)
BEGIN SELECT RAISE(ABORT,''adapter_contract_event_state_invalid''); END', '850e1ec5cd5f532c341d579d3e035b1e27e5ecc1fcd2cf83028503c53e68d025'),
('trg_adapter_contract_event_validate_insert_prd064', 'adapter_contract_event_outbox', 'CREATE TRIGGER trg_adapter_contract_event_validate_insert_prd064
BEFORE INSERT ON adapter_contract_event_outbox FOR EACH ROW
WHEN NOT (
  NEW.dispatch_status=''pending'' AND NEW.dispatch_attempts=0
  AND NEW.next_attempt_at=NEW.created_at AND NEW.updated_at=NEW.created_at
  AND NEW.dispatched_at IS NULL AND NEW.claim_token IS NULL
  AND NEW.lease_owner_id IS NULL AND NEW.lease_expires_at IS NULL
  AND NEW.last_error_code IS NULL
  AND EXISTS (
    SELECT 1 FROM adapter_contract_runs run
    WHERE run.tenant_id=NEW.tenant_id
      AND run.adapter_contract_run_id=NEW.adapter_contract_run_id
      AND run.status=''failed'' AND run.failed_cases>0
  )
)
BEGIN SELECT RAISE(ABORT,''adapter_contract_event_invalid''); END', '3fedb16515ae6e6e928a96be9f33f0d75df7ba0d9e587928685b1ed8d31ebc15'),
('trg_adapter_contract_runs_failure_codes_insert_prd064', 'adapter_contract_runs', 'CREATE TRIGGER trg_adapter_contract_runs_failure_codes_insert_prd064
BEFORE INSERT ON adapter_contract_runs FOR EACH ROW
WHEN CASE
  WHEN json_valid(NEW.failure_codes_json)
    AND json_type(NEW.failure_codes_json)=''array''
    AND json_array_length(NEW.failure_codes_json) BETWEEN 0 AND 16
  THEN EXISTS (
      SELECT 1 FROM json_each(NEW.failure_codes_json) item
      WHERE item.type!=''text'' OR item.value NOT IN (
        ''adapter.contract_fixture_missing'',''adapter.contract_fixture_unexpected'',
        ''adapter.contract_fixture_invalid'',''adapter.contract_coverage_mismatch'',
        ''adapter.contract_request_failed'',''adapter.contract_non_stream_failed'',
        ''adapter.contract_stream_failed'',''adapter.contract_error_mapping_failed'',
        ''adapter.contract_usage_failed'',''adapter.contract_probe_failed''
      )
    )
    OR (SELECT COUNT(*) FROM json_each(NEW.failure_codes_json))!=(
      SELECT COUNT(DISTINCT value) FROM json_each(NEW.failure_codes_json)
    )
    OR NEW.failure_codes_json!=(
      SELECT json_group_array(value)
      FROM (
        SELECT value FROM json_each(NEW.failure_codes_json) ORDER BY value
      )
    )
  ELSE 1
END
BEGIN SELECT RAISE(ABORT,''adapter_contract_failure_codes_invalid''); END', '74d1e57002bd884dab98c8898725296d07424dc1fb952cf1eb91581555111374'),
('trg_adapter_contract_runs_immutable_delete_prd064', 'adapter_contract_runs', 'CREATE TRIGGER trg_adapter_contract_runs_immutable_delete_prd064
BEFORE DELETE ON adapter_contract_runs FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''adapter_contract_run_immutable''); END', 'dd669dca34fe777ed9dcf6d5668c055633a64a76c7dc0f5af7562983f1410bb8'),
('trg_adapter_contract_runs_immutable_update_prd064', 'adapter_contract_runs', 'CREATE TRIGGER trg_adapter_contract_runs_immutable_update_prd064
BEFORE UPDATE ON adapter_contract_runs FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''adapter_contract_run_immutable''); END', '54b9b0e910cb29e9bcc992b1e3f595ed317590bc94600d16539bf30d1c4b447e'),
('trg_adapter_contract_runs_owner_insert_prd064', 'adapter_contract_runs', 'CREATE TRIGGER trg_adapter_contract_runs_owner_insert_prd064
BEFORE INSERT ON adapter_contract_runs FOR EACH ROW
WHEN NOT EXISTS (
  SELECT 1
  FROM tenants tenant
  JOIN provider_adapter_catalog_activations activation
    ON activation.tenant_id=tenant.tenant_id AND activation.status=''active''
  WHERE tenant.tenant_id=NEW.tenant_id
    AND activation.catalog_version=NEW.catalog_version
    AND activation.catalog_hash=NEW.catalog_hash
)
BEGIN SELECT RAISE(ABORT,''adapter_contract_run_owner_invalid''); END', '20e68f493b79e1ab585f9faf7d6e802306b58e14d10671c63175b384e8652e08'),
('trg_approval_replays_delete_prd078', 'approval_action_replays', 'CREATE TRIGGER trg_approval_replays_delete_prd078
BEFORE DELETE ON approval_action_replays FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''approval_replay_immutable''); END', '42f57cbfc37849a8138c645a93196853601ff1aa74c8781c802d8dace3d2d98e'),
('trg_approval_replays_owner_insert_prd078', 'approval_action_replays', 'CREATE TRIGGER trg_approval_replays_owner_insert_prd078
BEFORE INSERT ON approval_action_replays FOR EACH ROW
WHEN NOT EXISTS(SELECT 1 FROM approval_decisions decision
  JOIN approval_tasks task ON task.tenant_id=decision.tenant_id
    AND task.approval_task_id=decision.approval_task_id
  JOIN users actor ON actor.tenant_id=task.tenant_id AND actor.user_id=NEW.actor_user_id
  WHERE decision.tenant_id=NEW.tenant_id
    AND decision.approval_decision_id=NEW.approval_decision_id
    AND decision.approval_task_id=NEW.approval_task_id
    AND decision.actor_type=''user'' AND decision.actor_id=NEW.actor_user_id
    AND decision.decision=NEW.action AND decision.reason_code=NEW.reason_code
    AND decision.revision_before=NEW.expected_revision AND actor.status=''active''
    AND NEW.created_at=decision.decided_at)
  OR EXISTS(SELECT 1 FROM approval_action_replays current
    WHERE current.approval_action_replay_id=NEW.approval_action_replay_id
      OR (current.tenant_id=NEW.tenant_id
        AND current.actor_user_id=NEW.actor_user_id
        AND current.hmac_key_version=NEW.hmac_key_version
        AND current.idempotency_key_hmac=NEW.idempotency_key_hmac
        -- BEGIN IMMEDIATE serializes writers. Retain expired history while
        -- rejecting a digest whose 24-hour replay window is still active.
        AND julianday(current.expires_at)>julianday(NEW.created_at))
      OR (NEW.rowid!=-1 AND current.rowid=NEW.rowid))
BEGIN SELECT RAISE(ABORT,''approval_replay_owner_mismatch''); END', 'dcfd8d03929242e69891f1aaa0481131c78b3adafeb7ba03a47bd1c7d65f197c'),
('trg_approval_replays_update_prd078', 'approval_action_replays', 'CREATE TRIGGER trg_approval_replays_update_prd078
BEFORE UPDATE ON approval_action_replays FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''approval_replay_immutable''); END', 'e7821b7c95c107243b7313a4aeab56f8ae989488368d5d297855178cb4e5d5fd'),
