('trg_approval_challenges_owner_insert_prd078', 'approval_step_up_challenges', 'CREATE TRIGGER trg_approval_challenges_owner_insert_prd078
BEFORE INSERT ON approval_step_up_challenges FOR EACH ROW
WHEN NEW.status!=''active'' OR NEW.created_at!=NEW.updated_at
