('trg_approval_tasks_owner_insert_prd078', 'approval_tasks', 'CREATE TRIGGER trg_approval_tasks_owner_insert_prd078
BEFORE INSERT ON approval_tasks FOR EACH ROW
WHEN NEW.status!=''pending'' OR NEW.state_revision!=1 OR NEW.writeback_status!=''pending''
  OR NEW.created_at!=NEW.updated_at
  OR NOT EXISTS(SELECT 1 FROM tenants tenant
    WHERE tenant.tenant_id=NEW.tenant_id AND tenant.status=''active'')
  OR (NEW.created_by_type=''user'' AND NOT EXISTS(SELECT 1 FROM users actor
    WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.created_by_id
      AND actor.status=''active''))
  OR (NEW.target_type=''budget_block_release'' AND NOT EXISTS(
    SELECT 1 FROM budget_blocks block JOIN budget_rules rule
      ON rule.tenant_id=block.tenant_id AND rule.budget_rule_id=block.budget_rule_id
    WHERE block.tenant_id=NEW.tenant_id AND block.budget_block_id=NEW.source_id
      AND block.budget_rule_id=NEW.target_id AND block.status=''active''))
  OR (NEW.target_type=''session_risk_action'' AND NOT EXISTS(
    SELECT 1 FROM session_risk_scores score
    WHERE score.tenant_id=NEW.tenant_id AND score.session_risk_score_id=NEW.target_id
      AND score.status IN(''high_risk'',''frozen'')))
  OR (NEW.target_type=''mcp_tool_invocation'' AND (
    NEW.mcp_invocation_id IS NULL OR NEW.mcp_invocation_id!=NEW.target_id
    OR NEW.source_id!=NEW.target_id OR NEW.created_by_type!=''user''
    OR (EXISTS(SELECT 1 FROM mcp_invocations invocation
          WHERE invocation.tenant_id=NEW.tenant_id
            AND invocation.mcp_invocation_id=NEW.mcp_invocation_id)
      AND NOT EXISTS(SELECT 1 FROM mcp_invocations invocation
        WHERE invocation.tenant_id=NEW.tenant_id
          AND invocation.mcp_invocation_id=NEW.mcp_invocation_id
          AND invocation.approval_task_id=NEW.approval_task_id
          AND invocation.requested_by=NEW.created_by_id
          AND invocation.status=''approval_pending''
          AND CAST(invocation.server_state_revision AS TEXT)||'':''
            ||CAST(invocation.credential_revision AS TEXT)||'':''
            ||CAST(invocation.schema_revision AS TEXT)||'':''
            ||CAST(invocation.policy_revision AS TEXT)=NEW.target_version
          AND invocation.policy_fingerprint=NEW.target_fingerprint
          AND invocation.risk_level=''high'' AND invocation.approval_required=1
          AND invocation.approval_deadline_at=NEW.expires_at))))
  OR EXISTS(SELECT 1 FROM approval_tasks current
    WHERE current.approval_task_id=NEW.approval_task_id
      OR (NEW.rowid!=-1 AND current.rowid=NEW.rowid))
BEGIN SELECT RAISE(ABORT,''approval_task_owner_mismatch''); END', 'bf70af8c0d7c90876c5b93734056c3d8ffeda29d808eaa7bdc3fb4e4c88a7048'),
('trg_approval_tasks_transition_prd078', 'approval_tasks', 'CREATE TRIGGER trg_approval_tasks_transition_prd078
BEFORE UPDATE ON approval_tasks FOR EACH ROW
WHEN NEW.rowid!=OLD.rowid OR NEW.approval_task_id!=OLD.approval_task_id
  OR NEW.tenant_id!=OLD.tenant_id OR NEW.source_type!=OLD.source_type
  OR NEW.source_id!=OLD.source_id OR NEW.target_type!=OLD.target_type
  OR NEW.target_id!=OLD.target_id OR NEW.target_action!=OLD.target_action
  OR NEW.target_reason_code IS NOT OLD.target_reason_code
  OR NEW.target_version!=OLD.target_version OR NEW.target_fingerprint!=OLD.target_fingerprint
  OR NEW.risk_level!=OLD.risk_level OR NEW.required_permission_code!=OLD.required_permission_code
  OR NEW.created_by_type!=OLD.created_by_type OR NEW.created_by_id!=OLD.created_by_id
  OR NEW.mcp_invocation_id IS NOT OLD.mcp_invocation_id
  OR NEW.expires_at!=OLD.expires_at OR NEW.create_hmac_key_version!=OLD.create_hmac_key_version
  OR NEW.create_idempotency_key_hmac!=OLD.create_idempotency_key_hmac
  OR NEW.create_intent_hmac!=OLD.create_intent_hmac
  OR NEW.source_request_id!=OLD.source_request_id OR NEW.source_trace_id!=OLD.source_trace_id
  OR NEW.created_at!=OLD.created_at
  OR (NEW.target_type=''mcp_tool_invocation'' AND NEW.decided_by_user_id IS NOT NULL
    AND EXISTS(SELECT 1 FROM mcp_invocations invocation
      WHERE invocation.tenant_id=NEW.tenant_id
        AND invocation.mcp_invocation_id=NEW.mcp_invocation_id
        AND invocation.requested_by=NEW.decided_by_user_id))
  OR NOT (
    (OLD.status=''pending'' AND NEW.status IN(''approved'',''rejected'')
      AND NEW.state_revision=OLD.state_revision+1
      AND NEW.decided_at=NEW.updated_at AND unixepoch(NEW.updated_at)>=unixepoch(OLD.updated_at)
      AND ((NEW.status=''approved'' AND NEW.resolution_reason=''approved''
          AND NEW.decided_by_user_id IS NOT NULL
          AND ((NEW.target_type IN(''budget_block_release'',''mcp_tool_invocation'')
              AND NEW.writeback_status=''completed'')
            OR (NEW.target_type=''session_risk_action'' AND NEW.writeback_status=''pending'')))
        OR (NEW.status=''rejected'' AND NEW.resolution_reason IN(''user_rejected'',''timeout'')
          AND NEW.writeback_status=''completed''
          AND ((NEW.resolution_reason=''user_rejected'' AND NEW.decided_by_user_id IS NOT NULL)
            OR (NEW.resolution_reason=''timeout'' AND NEW.decided_by_user_id IS NULL)))))
    OR (OLD.status=''approved'' AND NEW.status=''approved''
      AND OLD.target_type=''session_risk_action'' AND OLD.writeback_status=''pending''
      AND NEW.writeback_status IN(''completed'',''failed'')
      AND NEW.state_revision=OLD.state_revision
      AND NEW.resolution_reason=OLD.resolution_reason
      AND NEW.decided_by_user_id=OLD.decided_by_user_id
      AND NEW.decided_at=OLD.decided_at
      AND NEW.decision_request_id=OLD.decision_request_id
      AND NEW.decision_trace_id=OLD.decision_trace_id
      AND unixepoch(NEW.updated_at)>=unixepoch(OLD.updated_at))
  )
BEGIN SELECT RAISE(ABORT,''approval_task_transition_invalid''); END', 'f608215b433da6483ad89bc839ba1c8c8c815ed2ff23a1eb091608ca01b57e3b'),
('trg_approval_writebacks_delete_prd078', 'approval_writebacks', 'CREATE TRIGGER trg_approval_writebacks_delete_prd078
BEFORE DELETE ON approval_writebacks FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''approval_writeback_immutable''); END', '75815251da2cfe5934ee541aa3fe41da4f97a3c70e37dc776d2ecb16f4134c1b'),
('trg_approval_writebacks_owner_insert_prd078', 'approval_writebacks', 'CREATE TRIGGER trg_approval_writebacks_owner_insert_prd078
BEFORE INSERT ON approval_writebacks FOR EACH ROW
WHEN NEW.attempt_count!=0 OR NEW.lease_generation!=0 OR NEW.created_at!=NEW.updated_at
  OR NOT EXISTS(SELECT 1 FROM approval_tasks task JOIN approval_decisions decision
    ON decision.tenant_id=task.tenant_id AND decision.approval_task_id=task.approval_task_id
    WHERE task.tenant_id=NEW.tenant_id AND task.approval_task_id=NEW.approval_task_id
      AND decision.writeback_status=task.writeback_status
      AND ((decision.decision=''approve'' AND task.target_type=''budget_block_release''
          AND NEW.adapter_kind=''budget_block_release'' AND NEW.status=''completed''
          AND task.writeback_status=''completed'' AND NEW.completed_at=NEW.created_at)
        OR (decision.decision=''approve'' AND task.target_type=''session_risk_action''
          AND NEW.adapter_kind=''session_risk_store_sync'' AND NEW.status=''pending''
          AND task.writeback_status=''pending'' AND NEW.next_attempt_at=NEW.created_at
          AND EXISTS(SELECT 1 FROM session_risk_actions action
            WHERE action.tenant_id=NEW.tenant_id
              AND action.session_risk_action_id=NEW.target_fact_id
              AND action.session_risk_score_id=task.target_id
              AND action.state_revision=NEW.target_revision))
        OR (decision.decision=''approve'' AND task.target_type=''mcp_tool_invocation''
          AND NEW.adapter_kind=''mcp_invocation_enqueue'' AND NEW.status=''completed''
          AND task.writeback_status=''completed'' AND NEW.completed_at=NEW.created_at
          AND NEW.target_fact_id=task.mcp_invocation_id
          AND EXISTS(SELECT 1 FROM mcp_invocations invocation
            WHERE invocation.tenant_id=task.tenant_id
              AND invocation.mcp_invocation_id=task.mcp_invocation_id
              AND invocation.status=''queued''
              AND invocation.policy_revision=NEW.target_revision))
        OR (decision.decision IN(''reject'',''timeout'') AND NEW.adapter_kind=''no_effect''
          AND NEW.status=''completed'' AND task.writeback_status=''completed''
          AND NEW.completed_at=NEW.created_at)))
  OR EXISTS(SELECT 1 FROM approval_writebacks current
    WHERE current.approval_writeback_id=NEW.approval_writeback_id
      OR (NEW.rowid!=-1 AND current.rowid=NEW.rowid))
BEGIN SELECT RAISE(ABORT,''approval_writeback_owner_mismatch''); END', '5608205b86bd652b5fdf0e924aabf8aad25cc28ec19c6473332a36c8df0cdb25'),
('trg_approval_writebacks_task_progress_prd078', 'approval_writebacks', 'CREATE TRIGGER trg_approval_writebacks_task_progress_prd078
AFTER UPDATE OF status ON approval_writebacks FOR EACH ROW
WHEN NEW.status IN(''completed'',''failed'') AND OLD.status=''processing''
BEGIN
  -- 仅把同租户已批准任务的 pending 回写推进到 worker 终态，决策事实保持只追加。
  UPDATE approval_tasks SET writeback_status=NEW.status,updated_at=NEW.updated_at
  WHERE tenant_id=NEW.tenant_id AND approval_task_id=NEW.approval_task_id
    AND status=''approved'' AND writeback_status=''pending'';
END', 'e53b6ab5d1ca715c328e77c4430d64cea011d166eb01229e68399ddd46bcb412'),
('trg_approval_writebacks_transition_prd078', 'approval_writebacks', 'CREATE TRIGGER trg_approval_writebacks_transition_prd078
BEFORE UPDATE ON approval_writebacks FOR EACH ROW
WHEN NEW.rowid!=OLD.rowid OR NEW.approval_writeback_id!=OLD.approval_writeback_id
  OR NEW.tenant_id!=OLD.tenant_id OR NEW.approval_task_id!=OLD.approval_task_id
  OR NEW.adapter_kind!=OLD.adapter_kind OR NEW.target_fact_id IS NOT OLD.target_fact_id
  OR NEW.target_revision IS NOT OLD.target_revision OR NEW.created_at!=OLD.created_at
  OR OLD.adapter_kind!=''session_risk_store_sync''
  OR NEW.lease_generation!=OLD.lease_generation+1
  OR unixepoch(NEW.updated_at)<unixepoch(OLD.updated_at)
  OR NOT (
    (OLD.status=''pending'' AND NEW.status=''processing''
      AND NEW.attempt_count=OLD.attempt_count+1
      AND NEW.lease_owner_id IS NOT NULL AND length(NEW.lease_owner_id) BETWEEN 1 AND 160
      AND NEW.lease_token IS NOT NULL AND length(NEW.lease_token)=64
      AND NEW.lease_token NOT GLOB ''*[^0-9a-f]*''
      AND unixepoch(NEW.lease_expires_at)=unixepoch(NEW.updated_at)+90)
    OR (OLD.status=''processing'' AND NEW.status=''processing''
      AND unixepoch(NEW.updated_at)>=unixepoch(OLD.lease_expires_at)
      AND NEW.attempt_count=OLD.attempt_count+1 AND NEW.lease_token!=OLD.lease_token
      AND NEW.lease_owner_id IS NOT NULL AND length(NEW.lease_owner_id) BETWEEN 1 AND 160
      AND NEW.lease_token IS NOT NULL AND length(NEW.lease_token)=64
      AND NEW.lease_token NOT GLOB ''*[^0-9a-f]*''
      AND unixepoch(NEW.lease_expires_at)=unixepoch(NEW.updated_at)+90)
    OR (OLD.status=''processing'' AND NEW.status=''pending''
      AND NEW.attempt_count=OLD.attempt_count AND NEW.attempt_count<10
      AND NEW.last_error_code=''approval.writeback_unavailable''
      AND unixepoch(NEW.next_attempt_at)=unixepoch(NEW.updated_at)+CASE NEW.attempt_count
        WHEN 1 THEN 5 WHEN 2 THEN 30 ELSE 300 END)
    OR (OLD.status=''processing'' AND NEW.status=''completed''
      AND NEW.attempt_count=OLD.attempt_count AND NEW.completed_at=NEW.updated_at)
    OR (OLD.status=''processing'' AND NEW.status=''failed''
      AND NEW.attempt_count=10 AND NEW.last_error_code=''approval.writeback_unavailable'')
  )
BEGIN SELECT RAISE(ABORT,''approval_writeback_transition_invalid''); END', 'a47dca83f44d47ea672ff8c92ee67989f60ed765a17d3a14af87afc225e74954'),
('trg_assistant_audits_delete_prd077', 'assistant_audits', 'CREATE TRIGGER trg_assistant_audits_delete_prd077
BEFORE DELETE ON assistant_audits FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''assistant_audit_immutable''); END', 'd3464874722e890c1070e3bdbb819c1335efe4bdf012388475114040f566e1d8'),
('trg_assistant_audits_owner_insert_prd077', 'assistant_audits', 'CREATE TRIGGER trg_assistant_audits_owner_insert_prd077
BEFORE INSERT ON assistant_audits FOR EACH ROW
WHEN NOT EXISTS(
  SELECT 1 FROM assistant_queries query
  WHERE query.tenant_id=NEW.tenant_id
    AND query.assistant_query_id=NEW.assistant_query_id
    AND query.actor_user_id=NEW.actor_user_id
    AND query.actor_session_id=NEW.actor_session_id
    AND query.outcome=NEW.outcome
    AND query.claim_count=NEW.claim_count
    AND query.source_count=NEW.source_count
    AND query.redaction_count=NEW.redaction_count
    AND query.query_duration_ms=NEW.query_duration_ms
    AND query.operation_request_id=NEW.operation_request_id
    AND query.operation_trace_id=NEW.operation_trace_id
    AND query.execution_mode=NEW.execution_mode
    AND query.model_call_count=NEW.model_call_count
    AND query.model_input_tokens=NEW.model_input_tokens
    AND query.model_output_tokens=NEW.model_output_tokens
    AND query.model_cost_cny_micros=NEW.model_cost_cny_micros
    AND query.model_cost_status=NEW.model_cost_status
    AND query.created_at=NEW.created_at
    AND NEW.required_permissions_json=CASE query.query_type
      WHEN ''usage_statistics'' THEN
        ''["admin_assistant.query","billing.usage.read","dashboard.read"]''
      WHEN ''error_explanation'' THEN
        ''["admin_assistant.query","request_log.read"]''
      WHEN ''cost_advice'' THEN
        ''["admin_assistant.query","billing.anomaly.read","billing.budget.read",'' ||
        ''"billing.finops.read","billing.usage.read","dashboard.read","model_price.read"]''
      WHEN ''policy_explanation'' THEN CASE
        WHEN query.target_request_id IS NULL
          THEN ''["admin_assistant.query","policy.read"]''
        ELSE
          ''["admin_assistant.query","policy.read","request_explanation.read"]''
        END
      WHEN ''unknown'' THEN ''["admin_assistant.query"]''
    END
    AND (
      (query.outcome!=''answered'' AND NEW.source_types_json=''[]'')
      OR
      (
        query.outcome=''answered''
        AND json_array_length(NEW.source_types_json)=NEW.source_count
        AND NOT EXISTS(
          SELECT 1 FROM json_each(NEW.source_types_json) source
          WHERE source.type!=''text''
            OR source.value NOT IN(
              ''overview'',''request_logs'',''request_explanations'',''usage'',
              ''finops_ledger'',''budgets'',''cost_anomalies'',''model_prices'',
              ''policies'',''policy_snapshots''
            )
            OR (
              query.query_type=''usage_statistics''
              AND source.value NOT IN(''overview'',''usage'')
            )
            OR (
              query.query_type=''error_explanation''
              AND source.value!=''request_logs''
            )
            OR (
              query.query_type=''cost_advice''
              AND source.value NOT IN(
                ''overview'',''usage'',''finops_ledger'',''budgets'',
                ''cost_anomalies'',''model_prices''
              )
            )
            OR (
              query.query_type=''policy_explanation''
              AND source.value NOT IN(
                ''policies'',''policy_snapshots'',''request_explanations''
              )
            )
        )
      )
    )
)
OR EXISTS(
  SELECT 1 FROM json_each(NEW.required_permissions_json) left_value
  JOIN json_each(NEW.required_permissions_json) right_value
    ON right_value.key>left_value.key
   AND right_value.value<=left_value.value
)
OR EXISTS(
  SELECT 1 FROM json_each(NEW.source_types_json) left_value
  JOIN json_each(NEW.source_types_json) right_value
    ON right_value.key>left_value.key
   AND right_value.value<=left_value.value
)
OR EXISTS(
  SELECT 1 FROM assistant_audits current
  WHERE current.assistant_audit_id=NEW.assistant_audit_id
    OR current.assistant_event_id=NEW.assistant_event_id
    OR current.assistant_query_id=NEW.assistant_query_id
    OR current.audit_log_id=NEW.audit_log_id
    OR (NEW.rowid!=-1 AND current.rowid=NEW.rowid)
)
BEGIN SELECT RAISE(ABORT,''assistant_audit_owner_mismatch''); END', 'c66c15f04e66bd097694262f8f8a45351e80ee81883000eb460b03c076f92ec6'),
('trg_assistant_audits_rowid_insert_prd077', 'assistant_audits', 'CREATE TRIGGER trg_assistant_audits_rowid_insert_prd077
AFTER INSERT ON assistant_audits FOR EACH ROW WHEN NEW.rowid<0
BEGIN SELECT RAISE(ABORT,''assistant_audit_immutable''); END', '2c9eee8cd9a81a188af95076537d58f636635691751a6a1f8bd9501582ba35ce'),
('trg_assistant_audits_update_prd077', 'assistant_audits', 'CREATE TRIGGER trg_assistant_audits_update_prd077
BEFORE UPDATE ON assistant_audits FOR EACH ROW
WHEN NEW.rowid!=OLD.rowid
  OR NEW.assistant_audit_id!=OLD.assistant_audit_id
  OR NEW.assistant_event_id!=OLD.assistant_event_id
  OR NEW.tenant_id!=OLD.tenant_id
  OR NEW.assistant_query_id!=OLD.assistant_query_id
  OR NEW.actor_user_id!=OLD.actor_user_id
  OR NEW.actor_session_id!=OLD.actor_session_id
  OR NEW.audit_log_id!=OLD.audit_log_id
  OR NEW.required_permissions_json!=OLD.required_permissions_json
  OR NEW.source_types_json!=OLD.source_types_json
  OR NEW.permission_revision!=OLD.permission_revision
  OR NEW.authorization_fingerprint!=OLD.authorization_fingerprint
  OR NEW.answer_schema_version!=OLD.answer_schema_version
  OR NEW.outcome!=OLD.outcome
  OR NEW.claim_count!=OLD.claim_count
  OR NEW.source_count!=OLD.source_count
  OR NEW.redaction_count!=OLD.redaction_count
  OR NEW.query_duration_ms!=OLD.query_duration_ms
  OR NEW.operation_request_id!=OLD.operation_request_id
  OR NEW.operation_trace_id!=OLD.operation_trace_id
  OR NEW.execution_mode!=OLD.execution_mode
  OR NEW.model_call_count!=OLD.model_call_count
  OR NEW.model_input_tokens!=OLD.model_input_tokens
  OR NEW.model_output_tokens!=OLD.model_output_tokens
  OR NEW.model_cost_cny_micros!=OLD.model_cost_cny_micros
  OR NEW.model_cost_status!=OLD.model_cost_status
  OR NEW.created_at!=OLD.created_at
  OR unixepoch(NEW.updated_at)<=unixepoch(OLD.updated_at)
  OR NOT(
    (
      OLD.event_dispatch_status=''pending''
      AND NEW.event_dispatch_status=''processing''
      AND OLD.event_dispatch_attempts<10
      AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts+1
      AND unixepoch(OLD.event_next_attempt_at)<=unixepoch(NEW.updated_at)
      AND unixepoch(NEW.event_lease_expires_at)>unixepoch(NEW.updated_at)
    )
    OR
    (
      OLD.event_dispatch_status=''processing''
      AND NEW.event_dispatch_status=''processing''
      AND OLD.event_dispatch_attempts<10
      AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts+1
      AND NEW.event_claim_token!=OLD.event_claim_token
      AND unixepoch(OLD.event_lease_expires_at)<=unixepoch(NEW.updated_at)
      AND unixepoch(NEW.event_lease_expires_at)>unixepoch(NEW.updated_at)
    )
    OR
    (
      OLD.event_dispatch_status=''processing''
      AND NEW.event_dispatch_status=''processing''
      AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts
      AND NEW.event_next_attempt_at IS OLD.event_next_attempt_at
      AND NEW.event_claim_token=OLD.event_claim_token
      AND NEW.event_lease_owner_id=OLD.event_lease_owner_id
      AND NEW.event_last_error_code IS OLD.event_last_error_code
      AND NEW.event_dispatched_at IS OLD.event_dispatched_at
      AND unixepoch(NEW.updated_at)>unixepoch(OLD.updated_at)
      AND unixepoch(OLD.event_lease_expires_at)>unixepoch(NEW.updated_at)
      AND unixepoch(NEW.event_lease_expires_at)>unixepoch(OLD.event_lease_expires_at)
    )
    OR
    (
      OLD.event_dispatch_status=''processing''
      AND NEW.event_dispatch_status IN(''pending'',''dispatched'',''failed'')
      AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts
      AND unixepoch(OLD.event_lease_expires_at)>unixepoch(NEW.updated_at)
    )
    OR
    (
      OLD.event_dispatch_status=''processing''
      AND OLD.event_dispatch_attempts=10
      AND NEW.event_dispatch_status=''failed''
      AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts
      AND unixepoch(OLD.event_lease_expires_at)<=unixepoch(NEW.updated_at)
    )
    OR
    (
      OLD.event_dispatch_status IN(''pending'',''processing'')
      AND NEW.event_dispatch_status=''failed''
      AND NEW.event_dispatch_attempts=10
      AND (
        strftime(''%Y-%m-%dT%H:%M:%SZ'',OLD.updated_at) IS NOT OLD.updated_at
        OR (
          OLD.event_next_attempt_at IS NOT NULL
          AND strftime(''%Y-%m-%dT%H:%M:%SZ'',OLD.event_next_attempt_at)
              IS NOT OLD.event_next_attempt_at
        )
        OR (
          OLD.event_lease_expires_at IS NOT NULL
          AND strftime(''%Y-%m-%dT%H:%M:%SZ'',OLD.event_lease_expires_at)
              IS NOT OLD.event_lease_expires_at
        )
      )
    )
  )
BEGIN SELECT RAISE(ABORT,''assistant_audit_transition_invalid''); END', '95e8187b75d5b0166a6650aba91df78bd9e70f372287363adaac1cfa6ba61517'),
('trg_assistant_queries_delete_prd077', 'assistant_queries', 'CREATE TRIGGER trg_assistant_queries_delete_prd077
