  OR NEW.issued_at!=OLD.issued_at OR NEW.expires_at!=OLD.expires_at
BEGIN SELECT RAISE(ABORT,''batch_grant_immutable''); END', '558e3df2d32eb2495dc7e2346f06c594b71d4b7869bbed05c728a4535c6fd270'),
