      AND audit.actor_user_id=NEW.actor_user_id
      AND audit.request_id=NEW.request_id AND audit.trace_id=NEW.trace_id
      AND audit.created_at=NEW.created_at)
  OR NEW.payload_sha256!=metahub_sha256(NEW.payload_json)
