('trg_chat_messages_owner_insert_prd066', 'chat_messages', 'CREATE TRIGGER trg_chat_messages_owner_insert_prd066
BEFORE INSERT ON chat_messages FOR EACH ROW
WHEN NEW.status!=''in_flight'' OR NEW.completed_at IS NOT NULL
  OR julianday(NEW.started_at) IS NULL
  OR NOT EXISTS (
    SELECT 1 FROM chat_sessions session
    WHERE session.tenant_id=NEW.tenant_id
      AND session.chat_session_id=NEW.chat_session_id
      AND session.owner_user_id=NEW.owner_user_id
      AND session.status=''active''
      AND session.message_sequence=NEW.message_sequence
      AND julianday(session.expires_at)>julianday(NEW.started_at)
  )
  OR EXISTS (
    SELECT 1 FROM chat_messages current
    WHERE current.chat_message_id=NEW.chat_message_id
       OR current.webhook_event_id=NEW.webhook_event_id
       OR (NEW.rowid!=-1 AND current.rowid=NEW.rowid)
  )
BEGIN SELECT RAISE(ABORT,''chat_message_owner_mismatch''); END', 'f19e82a11cfffd7686fe4f2e445770511de452d1ada0dccb9f59237e0fb38120'),
('trg_chat_messages_state_update_prd066', 'chat_messages', 'CREATE TRIGGER trg_chat_messages_state_update_prd066
BEFORE UPDATE ON chat_messages FOR EACH ROW
WHEN OLD.status!=''in_flight'' OR NEW.status NOT IN (''succeeded'',''failed'')
  OR NEW.rowid!=OLD.rowid OR NEW.chat_message_id!=OLD.chat_message_id
  OR NEW.tenant_id!=OLD.tenant_id OR NEW.chat_session_id!=OLD.chat_session_id
  OR NEW.owner_user_id!=OLD.owner_user_id
  OR NEW.client_message_id!=OLD.client_message_id
  OR NEW.message_sequence!=OLD.message_sequence
  OR NEW.gateway_request_id!=OLD.gateway_request_id
  OR NEW.gateway_trace_id!=OLD.gateway_trace_id
  OR NEW.webhook_event_id!=OLD.webhook_event_id
  OR NEW.started_at!=OLD.started_at OR NEW.completed_at IS NULL
  OR julianday(NEW.completed_at) IS NULL
  OR julianday(NEW.completed_at)<julianday(OLD.started_at)
  OR (NEW.status=''succeeded'' AND NEW.error_code IS NOT NULL)
  OR (NEW.status=''failed'' AND NEW.error_code IS NULL)
BEGIN SELECT RAISE(ABORT,''chat_message_state_conflict''); END', '4769917c46034dff993534683e1db0640c3c516214e08df522b79032bd84483e'),
('trg_chat_prompt_invocations_delete_prd067', 'chat_prompt_template_invocations', 'CREATE TRIGGER trg_chat_prompt_invocations_delete_prd067
BEFORE DELETE ON chat_prompt_template_invocations FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''prompt_template_invocation_immutable''); END', 'a144abd63f130a5f4afcb571bfadb68cc84eda486247b3f31fe98d350df473c2'),
('trg_chat_prompt_invocations_owner_insert_prd067', 'chat_prompt_template_invocations', 'CREATE TRIGGER trg_chat_prompt_invocations_owner_insert_prd067
BEFORE INSERT ON chat_prompt_template_invocations FOR EACH ROW
WHEN NEW.status!=''in_flight'' OR NEW.failure_code IS NOT NULL OR NEW.completed_at IS NOT NULL
  OR NOT EXISTS (
    SELECT 1
    FROM prompt_template_versions version
    JOIN prompt_templates template
      ON template.tenant_id=version.tenant_id
     AND template.prompt_template_id=version.prompt_template_id
     AND template.current_version_id=version.prompt_template_version_id
     AND template.current_version_state=version.state
    JOIN chat_sessions chat_session
      ON chat_session.tenant_id=NEW.tenant_id
     AND chat_session.chat_session_id=NEW.chat_session_id
     AND chat_session.owner_user_id=NEW.actor_user_id
     AND chat_session.owner_auth_session_id=NEW.actor_auth_session_id
    JOIN chat_messages message
      ON message.tenant_id=chat_session.tenant_id
     AND message.chat_session_id=chat_session.chat_session_id
     AND message.chat_message_id=NEW.chat_message_id
     AND message.owner_user_id=NEW.actor_user_id
     AND message.gateway_request_id=NEW.gateway_request_id
     AND message.gateway_trace_id=NEW.gateway_trace_id
    WHERE version.tenant_id=NEW.tenant_id
      AND version.prompt_template_id=NEW.prompt_template_id
      AND version.prompt_template_version_id=NEW.prompt_template_version_id
      AND version.version_number=NEW.version_number AND version.state=''published''
      AND template.status=''active'' AND chat_session.status=''active''
      AND message.status=''in_flight''
      AND (
        version.project_scope=''all''
        OR EXISTS (
          SELECT 1 FROM prompt_template_version_projects binding
          WHERE binding.tenant_id=version.tenant_id
            AND binding.prompt_template_id=version.prompt_template_id
            AND binding.prompt_template_version_id=version.prompt_template_version_id
            AND binding.project_id=chat_session.project_id
        )
      )
  )
  OR EXISTS (
    SELECT 1 FROM chat_prompt_template_invocations current
    WHERE current.prompt_template_invocation_id=NEW.prompt_template_invocation_id
       OR (current.tenant_id=NEW.tenant_id
           AND current.chat_session_id=NEW.chat_session_id
           AND current.chat_message_id=NEW.chat_message_id)
       OR (NEW.rowid!=-1 AND current.rowid=NEW.rowid)
  )
BEGIN SELECT RAISE(ABORT,''prompt_template_invocation_owner_mismatch''); END', '9693800a3eca0990f160af1cd940870cf1978a78cd3d41cf1d6f9b2158bb76be'),
('trg_chat_prompt_invocations_state_update_prd067', 'chat_prompt_template_invocations', 'CREATE TRIGGER trg_chat_prompt_invocations_state_update_prd067
BEFORE UPDATE ON chat_prompt_template_invocations FOR EACH ROW
WHEN OLD.status!=''in_flight'' OR NEW.status NOT IN (''succeeded'',''failed'')
  OR NEW.rowid!=OLD.rowid
  OR NEW.prompt_template_invocation_id!=OLD.prompt_template_invocation_id
  OR NEW.tenant_id!=OLD.tenant_id OR NEW.prompt_template_id!=OLD.prompt_template_id
  OR NEW.prompt_template_version_id!=OLD.prompt_template_version_id
  OR NEW.version_number!=OLD.version_number OR NEW.chat_session_id!=OLD.chat_session_id
  OR NEW.chat_message_id!=OLD.chat_message_id OR NEW.actor_user_id!=OLD.actor_user_id
  OR NEW.actor_auth_session_id!=OLD.actor_auth_session_id
  OR NEW.gateway_request_id!=OLD.gateway_request_id
  OR NEW.gateway_trace_id!=OLD.gateway_trace_id OR NEW.created_at!=OLD.created_at
  OR NEW.completed_at IS NULL OR unixepoch(NEW.completed_at)<unixepoch(OLD.created_at)
  OR (NEW.status=''succeeded'' AND NEW.failure_code IS NOT NULL)
  OR (NEW.status=''failed'' AND NEW.failure_code IS NULL)
  OR NOT EXISTS (
    SELECT 1 FROM chat_messages message
    WHERE message.tenant_id=NEW.tenant_id
      AND message.chat_session_id=NEW.chat_session_id
      AND message.chat_message_id=NEW.chat_message_id
      AND message.owner_user_id=NEW.actor_user_id
      AND message.gateway_request_id=NEW.gateway_request_id
      AND message.gateway_trace_id=NEW.gateway_trace_id
      AND message.status=NEW.status AND message.completed_at=NEW.completed_at
      AND (
        (NEW.status=''succeeded'' AND message.error_code IS NULL)
        OR (NEW.status=''failed'' AND message.error_code=NEW.failure_code)
      )
  )
BEGIN SELECT RAISE(ABORT,''prompt_template_invocation_state_conflict''); END', '1d5dfdea9d251b8e17057234cd7d979894f25e6ec143d241d1ece215c9005729'),
('trg_chat_sessions_delete_prd066', 'chat_sessions', 'CREATE TRIGGER trg_chat_sessions_delete_prd066
BEFORE DELETE ON chat_sessions FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''chat_session_immutable''); END', '771e8e4d271957166a53c275c7e612c998eb5568248243e33a86f23a5bc39a12'),
('trg_chat_sessions_owner_insert_prd066', 'chat_sessions', 'CREATE TRIGGER trg_chat_sessions_owner_insert_prd066
BEFORE INSERT ON chat_sessions FOR EACH ROW
WHEN NEW.status!=''active'' OR NEW.message_sequence!=0 OR NEW.state_revision!=1
  OR NEW.cleared_at IS NOT NULL OR NEW.created_at IS NOT NEW.updated_at
  OR julianday(NEW.created_at) IS NULL OR julianday(NEW.expires_at) IS NULL
  OR julianday(NEW.expires_at)<=julianday(NEW.created_at)
  OR julianday(NEW.expires_at)>julianday(NEW.created_at,''+8 hours'')
  OR NOT EXISTS (
    SELECT 1 FROM users user
    WHERE user.tenant_id=NEW.tenant_id AND user.user_id=NEW.owner_user_id
      AND user.status=''active''
  )
  OR NOT EXISTS (
    SELECT 1 FROM sessions session
    WHERE session.tenant_id=NEW.tenant_id
      AND session.session_id=NEW.owner_auth_session_id
      AND session.user_id=NEW.owner_user_id AND session.status=''active''
      AND julianday(session.expires_at)>julianday(NEW.created_at)
  )
  OR NOT EXISTS (
    SELECT 1 FROM projects project
    WHERE project.tenant_id=NEW.tenant_id AND project.project_id=NEW.project_id
      AND project.status=''active''
  )
  OR NOT EXISTS (
    SELECT 1 FROM environments environment
    WHERE environment.tenant_id=NEW.tenant_id
      AND environment.environment_id=NEW.environment_id
      AND environment.status=''active''
  )
  OR NOT EXISTS (
    SELECT 1 FROM model_aliases alias
    JOIN environments environment
      ON environment.tenant_id=alias.tenant_id
     AND environment.environment_id=NEW.environment_id
    WHERE alias.tenant_id=NEW.tenant_id
      AND alias.model_alias_id=NEW.model_alias_id
      AND alias.alias=NEW.model_alias AND alias.status=''active''
      AND environment.status=''active''
      AND (alias.environment_id=NEW.environment_id
           OR (alias.environment_id IS NULL AND alias.environment=environment.code))
  )
  OR NOT EXISTS (
    SELECT 1 FROM virtual_keys virtual_key
    JOIN environments environment
      ON environment.tenant_id=virtual_key.tenant_id
     AND environment.environment_id=NEW.environment_id
    WHERE virtual_key.tenant_id=NEW.tenant_id
      AND virtual_key.virtual_key_id=NEW.virtual_key_id
      AND virtual_key.project_id=NEW.project_id
      AND virtual_key.status=''active'' AND environment.status=''active''
      AND (virtual_key.environment_id=NEW.environment_id
           OR (virtual_key.environment_id IS NULL
               AND virtual_key.environment=environment.code))
  )
  OR (
    SELECT COUNT(*) FROM virtual_keys virtual_key
    JOIN environments environment
      ON environment.tenant_id=virtual_key.tenant_id
     AND environment.environment_id=NEW.environment_id
    WHERE virtual_key.tenant_id=NEW.tenant_id
      AND virtual_key.project_id=NEW.project_id
      AND virtual_key.status=''active'' AND environment.status=''active''
      AND (virtual_key.environment_id=NEW.environment_id
           OR (virtual_key.environment_id IS NULL
               AND virtual_key.environment=environment.code))
  )!=1
  OR EXISTS (
    SELECT 1 FROM chat_sessions current
    WHERE current.chat_session_id=NEW.chat_session_id
       OR (NEW.rowid!=-1 AND current.rowid=NEW.rowid)
  )
BEGIN SELECT RAISE(ABORT,''chat_session_owner_mismatch''); END', 'ee55346fa566955f98dca1e67b9477579a05542aee79e7496d7a73d17ef57be2'),
('trg_chat_sessions_state_update_prd066', 'chat_sessions', 'CREATE TRIGGER trg_chat_sessions_state_update_prd066
BEFORE UPDATE ON chat_sessions FOR EACH ROW
WHEN OLD.status!=''active''
  OR NEW.rowid!=OLD.rowid OR NEW.chat_session_id!=OLD.chat_session_id
  OR NEW.tenant_id!=OLD.tenant_id OR NEW.owner_user_id!=OLD.owner_user_id
  OR NEW.owner_auth_session_id!=OLD.owner_auth_session_id
  OR NEW.project_id!=OLD.project_id OR NEW.environment_id!=OLD.environment_id
  OR NEW.model_alias_id!=OLD.model_alias_id OR NEW.model_alias!=OLD.model_alias
  OR NEW.virtual_key_id!=OLD.virtual_key_id OR NEW.expires_at!=OLD.expires_at
  -- 应用统一使用 UTC 秒；同一秒内 prepare/finalize 可共享时间文本，revision 仍防止倒退。
  OR NEW.created_at!=OLD.created_at OR NEW.updated_at<OLD.updated_at
  OR NEW.state_revision!=OLD.state_revision+1
  OR NEW.message_sequence NOT IN (OLD.message_sequence,OLD.message_sequence+1)
  OR NEW.status NOT IN (''active'',''cleared'',''expired'')
  OR (NEW.status=''active'' AND NEW.cleared_at IS NOT NULL)
  OR (NEW.status=''cleared'' AND NEW.cleared_at IS NULL)
  OR (NEW.status=''expired'' AND NEW.cleared_at IS NOT NULL)
BEGIN SELECT RAISE(ABORT,''chat_session_state_conflict''); END', '5815ef8bc9b498238e1f6a3eaa4810f47896198d4e9072be6e47f2ce02e46ee3'),
('trg_client_credentials_delete_prd118', 'client_credentials', 'CREATE TRIGGER trg_client_credentials_delete_prd118
BEFORE DELETE ON client_credentials
BEGIN SELECT RAISE(ABORT,''client_credential_immutable''); END', '37674e90ec8c45f6d3bddd5d5519f64f7e1dcc33fe813c7690fca2a0bec6d236'),
('trg_client_credentials_insert_prd118', 'client_credentials', 'CREATE TRIGGER trg_client_credentials_insert_prd118
BEFORE INSERT ON client_credentials FOR EACH ROW
WHEN NEW.status!=''active'' OR NOT EXISTS(
  SELECT 1 FROM oauth_clients client
  WHERE client.oauth_client_id=NEW.oauth_client_id
    AND client.workspace_id=NEW.workspace_id AND client.tenant_id=NEW.tenant_id
    AND client.status=''active'' AND (
      NEW.generation=client.credential_generation
      OR(NEW.generation=client.credential_generation+1
        AND NOT EXISTS(SELECT 1 FROM client_credentials active
          WHERE active.oauth_client_id=client.oauth_client_id AND active.status=''active'')
        AND EXISTS(SELECT 1 FROM client_credentials previous
          WHERE previous.oauth_client_id=client.oauth_client_id
            AND previous.generation=client.credential_generation
            AND previous.status=''grace''))))
BEGIN SELECT RAISE(ABORT,''client_credential_owner_invalid''); END', 'd4f026ef4151f372eb5fce7d2d230c8b7739268ecb3e711b612abec335d9c06d'),
('trg_client_credentials_update_prd118', 'client_credentials', 'CREATE TRIGGER trg_client_credentials_update_prd118
BEFORE UPDATE ON client_credentials FOR EACH ROW
WHEN NEW.client_credential_id!=OLD.client_credential_id
  OR NEW.oauth_client_id!=OLD.oauth_client_id
  OR NEW.workspace_id!=OLD.workspace_id OR NEW.tenant_id!=OLD.tenant_id
  OR NEW.generation!=OLD.generation OR NEW.secret_hash!=OLD.secret_hash
  OR NEW.secret_prefix!=OLD.secret_prefix OR NEW.expires_at!=OLD.expires_at
  OR NEW.created_at!=OLD.created_at OR OLD.status=''revoked''
  OR (OLD.last_used_at IS NOT NULL AND (NEW.last_used_at IS NULL
      OR NEW.last_used_at<OLD.last_used_at))
  OR NEW.updated_at<OLD.updated_at
  OR NOT(
    (NEW.status=OLD.status AND NEW.grace_expires_at IS OLD.grace_expires_at
      AND NEW.revoked_at IS OLD.revoked_at)
    OR(OLD.status=''active'' AND NEW.status=''grace''
      AND OLD.grace_expires_at IS NULL AND NEW.grace_expires_at IS NOT NULL
      AND NEW.revoked_at IS OLD.revoked_at AND NEW.last_used_at IS OLD.last_used_at)
    OR(OLD.status IN(''active'',''grace'') AND NEW.status=''revoked''
      AND NEW.grace_expires_at IS OLD.grace_expires_at
      AND OLD.revoked_at IS NULL AND NEW.revoked_at IS NOT NULL
      AND NEW.last_used_at IS OLD.last_used_at))
BEGIN SELECT RAISE(ABORT,''client_credential_transition_invalid''); END', 'ce1f45837be8cb068a5076cd4224a32415ad6385f26a0140895cc9f9c6ea109b'),
