('trg_environments_workspace_origin_prd093', 'environments', 'CREATE TRIGGER trg_environments_workspace_origin_prd093
AFTER INSERT ON environments FOR EACH ROW
BEGIN
  INSERT OR IGNORE INTO workspace_environment_origins(
    workspace_environment_origin_id,workspace_id,tenant_id,environment_id,origin,created_at)
  SELECT ''weo_''||substr(metahub_sha256(NEW.tenant_id||char(31)||NEW.environment_id),1,32),
    b.workspace_id,NEW.tenant_id,NEW.environment_id,''legacy_existing'',NEW.created_at
  FROM workspace_tenant_bindings b
  JOIN workspaces w ON w.workspace_id=b.workspace_id
  WHERE b.tenant_id=NEW.tenant_id AND w.creation_source!=''user_created'';
END', '091a8f03478745aa03ad44e8ef694242f810270aeb0d9a1a9804e6651e4ee770'),
('trg_policy_template_environment_delete_prd068', 'environments', 'CREATE TRIGGER trg_policy_template_environment_delete_prd068
BEFORE DELETE ON environments FOR EACH ROW
WHEN EXISTS (
  SELECT 1
  FROM policy_template_application_dependencies dependency
  JOIN policy_template_applications application
    ON application.tenant_id=dependency.tenant_id
   AND application.application_id=dependency.application_id
  WHERE dependency.tenant_id=OLD.tenant_id
    AND dependency.resource_type=''environment''
    AND dependency.resource_id=OLD.environment_id
    AND application.status=''applied''
)
BEGIN SELECT RAISE(ABORT,''policy_template_dependency_immutable''); END', '670a1e21554f72b1a52117ef300cce3185627dbd46e5ecd5549da3177de19839'),
('trg_policy_template_environment_update_prd068', 'environments', 'CREATE TRIGGER trg_policy_template_environment_update_prd068
BEFORE UPDATE ON environments FOR EACH ROW
WHEN EXISTS (
  SELECT 1
  FROM policy_template_application_dependencies dependency
  JOIN policy_template_applications application
    ON application.tenant_id=dependency.tenant_id
   AND application.application_id=dependency.application_id
  WHERE dependency.tenant_id=OLD.tenant_id
    AND dependency.resource_type=''environment''
    AND dependency.resource_id=OLD.environment_id
    AND application.status=''applied''
)
AND (
  NEW.rowid!=OLD.rowid OR NEW.environment_id!=OLD.environment_id
  OR NEW.tenant_id!=OLD.tenant_id OR NEW.code!=OLD.code
  OR (OLD.status!=''active'' AND NEW.status=''active'')
)
BEGIN SELECT RAISE(ABORT,''policy_template_dependency_immutable''); END', '6882d81f1aaee2a699ccd39c2b99752f6250fdacfbacac3e533184cca2991a02'),
