('trg_local_model_catalog_entries_owner_insert_prd084', 'local_model_catalog_entries', 'CREATE TRIGGER trg_local_model_catalog_entries_owner_insert_prd084
BEFORE INSERT ON local_model_catalog_entries FOR EACH ROW
