BEGIN SELECT RAISE(ABORT,''local_endpoint_immutable''); END', 'cb8ffe0bdb500477c5bce7c2e4e754f9629a31db8b5b8ac8b455eb317af9ad4c'),
('trg_local_model_endpoints_owner_insert_prd084', 'local_model_endpoints', 'CREATE TRIGGER trg_local_model_endpoints_owner_insert_prd084
BEFORE INSERT ON local_model_endpoints FOR EACH ROW
WHEN NEW.revision!=1 OR NEW.catalog_revision!=0 OR NEW.catalog_status!=''unknown''
  OR NEW.last_discovered_at IS NOT NULL OR NEW.last_catalog_error_code IS NOT NULL
  OR NEW.status!=''active''
  OR NOT EXISTS(SELECT 1 FROM providers provider
    WHERE provider.tenant_id=NEW.tenant_id AND provider.provider_id=NEW.provider_id
      AND provider.provider_type=''local_endpoint'' AND provider.status=''active'')
  OR NOT EXISTS(SELECT 1 FROM models model
    WHERE model.tenant_id=NEW.tenant_id AND model.model_id=NEW.initial_model_id
      AND model.provider_id=NEW.provider_id AND model.status=''active'')
  OR NOT EXISTS(SELECT 1 FROM users actor
    WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.created_by
      AND actor.status=''active'')
BEGIN SELECT RAISE(ABORT,''local_endpoint_owner_mismatch''); END', 'e7fbdb0fb911e3f550c0c303a98f1d302af3a693782b4182f4f836506c103d82'),
('trg_local_model_endpoints_update_prd084', 'local_model_endpoints', 'CREATE TRIGGER trg_local_model_endpoints_update_prd084
BEFORE UPDATE ON local_model_endpoints FOR EACH ROW
WHEN NEW.rowid!=OLD.rowid OR NEW.local_endpoint_id!=OLD.local_endpoint_id
  OR NEW.tenant_id!=OLD.tenant_id OR NEW.provider_id!=OLD.provider_id
  OR NEW.initial_model_id!=OLD.initial_model_id OR NEW.engine_kind!=OLD.engine_kind
  OR NEW.revision!=OLD.revision OR NEW.created_by!=OLD.created_by
  OR NEW.status!=OLD.status OR NEW.created_at!=OLD.created_at
  OR NEW.updated_at<OLD.updated_at
  OR NOT EXISTS(SELECT 1 FROM providers provider
    WHERE provider.tenant_id=NEW.tenant_id AND provider.provider_id=NEW.provider_id
      AND provider.provider_type=''local_endpoint'' AND provider.status=''active'')
  OR NOT EXISTS(SELECT 1 FROM models model
    WHERE model.tenant_id=NEW.tenant_id AND model.model_id=NEW.initial_model_id
      AND model.provider_id=NEW.provider_id)
  OR NOT(
    (NEW.catalog_revision=OLD.catalog_revision+1 AND NEW.catalog_status=''ready''
      AND NEW.last_discovered_at IS NOT NULL
      AND(OLD.last_discovered_at IS NULL OR NEW.last_discovered_at>=OLD.last_discovered_at)
      AND NEW.last_catalog_error_code IS NULL)
    OR(NEW.catalog_revision=OLD.catalog_revision AND NEW.catalog_status=''error''
      AND NEW.last_discovered_at IS OLD.last_discovered_at
      AND NEW.last_catalog_error_code IS NOT NULL))
BEGIN SELECT RAISE(ABORT,''local_endpoint_immutable''); END', '20c57830d94c2c25a9fead2230374cb6d9942a3919eaa16dc283727a69b6b391'),
('trg_machine_identity_audits_delete_prd118', 'machine_identity_audits', 'CREATE TRIGGER trg_machine_identity_audits_delete_prd118
BEFORE DELETE ON machine_identity_audits
BEGIN SELECT RAISE(ABORT,''machine_identity_audit_immutable''); END', 'fc11cd4ec2a79bc9dbebbda4d41dcad9ec0601dbb531d3683f497af9e03c7fa2'),
('trg_machine_identity_audits_insert_prd118', 'machine_identity_audits', 'CREATE TRIGGER trg_machine_identity_audits_insert_prd118
BEFORE INSERT ON machine_identity_audits FOR EACH ROW
WHEN NOT EXISTS(SELECT 1 FROM workspace_tenant_bindings binding
      WHERE binding.workspace_id=NEW.workspace_id AND binding.tenant_id=NEW.tenant_id)
  OR (NEW.subject_type=''human'' AND NOT EXISTS(
      SELECT 1 FROM workspace_memberships member
      WHERE member.workspace_id=NEW.workspace_id AND member.tenant_id=NEW.tenant_id
        AND member.account_id=NEW.subject_id AND member.status=''active''
        AND member.role_code!=''service_account''))
  OR (NEW.subject_type=''service_account'' AND NOT EXISTS(
      SELECT 1 FROM service_accounts account
      WHERE account.workspace_id=NEW.workspace_id AND account.tenant_id=NEW.tenant_id
        AND account.service_account_id=NEW.subject_id))
  OR NOT(
    (NEW.subject_type=''human'' AND NEW.outcome=''success''
      AND NEW.action_code=''service_account.created''
      AND NEW.resource_type=''service_account'' AND EXISTS(
        SELECT 1 FROM service_accounts account
        WHERE account.workspace_id=NEW.workspace_id AND account.tenant_id=NEW.tenant_id
          AND account.service_account_id=NEW.resource_id
          AND account.revision=NEW.resource_revision))
    OR(NEW.subject_type=''human'' AND NEW.outcome=''success''
      AND NEW.action_code=''oauth_client.created''
      AND NEW.resource_type=''oauth_client'' AND EXISTS(
        SELECT 1 FROM oauth_clients client
        WHERE client.workspace_id=NEW.workspace_id AND client.tenant_id=NEW.tenant_id
          AND client.oauth_client_id=NEW.resource_id
          AND client.revision=NEW.resource_revision))
    OR(NEW.subject_type=''human'' AND NEW.outcome=''success''
      AND NEW.action_code IN(
        ''service_account.credential_rotated'',''service_account.revoked'')
      AND NEW.resource_type=''service_account'' AND EXISTS(
        SELECT 1 FROM service_accounts account
        WHERE account.workspace_id=NEW.workspace_id AND account.tenant_id=NEW.tenant_id
          AND account.service_account_id=NEW.resource_id))
    OR(NEW.subject_type=''service_account'' AND NEW.outcome=''success''
      AND NEW.action_code=''oauth.token_issued''
      AND NEW.resource_type=''access_token_grant'' AND EXISTS(
        SELECT 1 FROM access_token_grants grant_record
        WHERE grant_record.workspace_id=NEW.workspace_id
          AND grant_record.tenant_id=NEW.tenant_id
          AND grant_record.service_account_id=NEW.subject_id
          AND grant_record.access_token_grant_id=NEW.resource_id))
    OR(NEW.subject_type=''service_account''
      AND NEW.action_code=''machine.provider_listed''
      AND NEW.resource_type=''provider_collection'' AND NEW.resource_id=''/providers'')
    OR(NEW.subject_type=''service_account''
      AND NEW.action_code=''machine.request_log_listed''
      AND NEW.resource_type=''request_log_collection''
      AND NEW.resource_id=''/request-logs'')
    OR(NEW.subject_type=''service_account''
      AND NEW.action_code=''machine.compliance_evidence_submitted''
      AND NEW.resource_type=''compliance_evidence_collection''
      AND NEW.resource_id=''/platform/compliance/evidence''))
BEGIN SELECT RAISE(ABORT,''machine_identity_audit_owner_invalid''); END', 'd105fe4a2832866bac75f05116459dc2f556915393a88319e6e842f0a83d9f1b'),
('trg_machine_identity_audits_update_prd118', 'machine_identity_audits', 'CREATE TRIGGER trg_machine_identity_audits_update_prd118
BEFORE UPDATE ON machine_identity_audits
