('trg_machine_identity_commands_delete_prd118', 'machine_identity_commands', 'CREATE TRIGGER trg_machine_identity_commands_delete_prd118
BEFORE DELETE ON machine_identity_commands
BEGIN SELECT RAISE(ABORT,''machine_identity_command_immutable''); END', 'd9952509182bc3e96a93a8c4d31a7bea18256e4ecf8c95548c6ea7f688396c1e'),
('trg_machine_identity_commands_insert_prd118', 'machine_identity_commands', 'CREATE TRIGGER trg_machine_identity_commands_insert_prd118
BEFORE INSERT ON machine_identity_commands FOR EACH ROW
WHEN NOT(
  (NEW.subject_type=''human'' AND EXISTS(
    SELECT 1 FROM workspace_memberships member
    WHERE member.workspace_id=NEW.workspace_id AND member.tenant_id=NEW.tenant_id
      AND member.account_id=NEW.subject_id AND member.status=''active''))
  OR(NEW.subject_type=''service_account'' AND EXISTS(
    SELECT 1 FROM service_accounts account
    WHERE account.workspace_id=NEW.workspace_id AND account.tenant_id=NEW.tenant_id
      AND account.service_account_id=NEW.subject_id)))
  OR NOT(
    (NEW.action_code IN(''service_account.create'',''service_account.revoke'')
      AND NEW.resource_type=''service_account'' AND NEW.result_generation=0
      AND EXISTS(SELECT 1 FROM service_accounts account
        WHERE account.workspace_id=NEW.workspace_id AND account.tenant_id=NEW.tenant_id
          AND account.service_account_id=NEW.resource_id
          AND account.revision=NEW.result_revision))
    OR(NEW.action_code IN(''oauth_client.create'',''oauth_client.rotate'')
      AND NEW.resource_type=''oauth_client'' AND NEW.result_generation>=1
      AND EXISTS(SELECT 1 FROM oauth_clients client
        WHERE client.workspace_id=NEW.workspace_id AND client.tenant_id=NEW.tenant_id
          AND client.oauth_client_id=NEW.resource_id
          AND client.revision=NEW.result_revision
          AND client.credential_generation=NEW.result_generation))
    OR(NEW.action_code=''oauth.token.issue'' AND NEW.subject_type=''service_account''
      AND NEW.resource_type=''access_token_grant'' AND NEW.result_generation>=1
      AND EXISTS(SELECT 1 FROM access_token_grants grant
        WHERE grant.workspace_id=NEW.workspace_id AND grant.tenant_id=NEW.tenant_id
          AND grant.access_token_grant_id=NEW.resource_id
          AND grant.service_account_id=NEW.subject_id
          AND grant.credential_generation=NEW.result_generation)))
BEGIN SELECT RAISE(ABORT,''machine_identity_command_owner_invalid''); END', '38f68ebaeab63ce182a0d66a33c94ecb07897e4be4c36209480fc0f48e716785'),
('trg_machine_identity_commands_update_prd118', 'machine_identity_commands', 'CREATE TRIGGER trg_machine_identity_commands_update_prd118
BEFORE UPDATE ON machine_identity_commands
BEGIN SELECT RAISE(ABORT,''machine_identity_command_immutable''); END', '990206aa15e3f9d774dfb9fbf8263827e3fb3d9aeff372bcd2ce4f4d651eaf45'),
('trg_machine_identity_outbox_delete_prd118', 'machine_identity_event_outbox', 'CREATE TRIGGER trg_machine_identity_outbox_delete_prd118
BEFORE DELETE ON machine_identity_event_outbox
BEGIN SELECT RAISE(ABORT,''machine_identity_outbox_immutable''); END', 'bc840f18052a94c4798ede19cd51f6593f9c985f9fd3502a57f5b1ee630a6f0f'),
('trg_machine_identity_outbox_insert_prd118', 'machine_identity_event_outbox', 'CREATE TRIGGER trg_machine_identity_outbox_insert_prd118
BEFORE INSERT ON machine_identity_event_outbox FOR EACH ROW
WHEN NOT EXISTS(
    SELECT 1 FROM machine_identity_audits audit
    JOIN service_accounts account
      ON account.workspace_id=audit.workspace_id AND account.tenant_id=audit.tenant_id
     AND account.service_account_id=NEW.aggregate_id
    WHERE audit.machine_identity_audit_id=NEW.machine_identity_audit_id
      AND audit.workspace_id=NEW.workspace_id AND audit.tenant_id=NEW.tenant_id
      AND audit.action_code=NEW.event_type AND audit.subject_type=''human''
      AND audit.resource_type=''service_account'' AND audit.resource_id=NEW.aggregate_id
      AND audit.outcome=''success'' AND audit.resource_revision=NEW.aggregate_revision)
  OR (SELECT COUNT(*) FROM json_each(NEW.payload_json))!=CASE NEW.event_type
      WHEN ''service_account.revoked'' THEN 3 ELSE 4 END
  OR EXISTS(SELECT 1 FROM json_each(NEW.payload_json) item
      WHERE item.key NOT IN(
        ''service_account_id'',''revision'',''status'',''constraint_generation'',
        ''credential_generation''))
  OR json_extract(NEW.payload_json,''$.service_account_id'')!=NEW.aggregate_id
  OR json_extract(NEW.payload_json,''$.revision'')!=NEW.aggregate_revision
  OR json_extract(NEW.payload_json,''$.status'') NOT IN(''active'',''revoked'')
  OR (NEW.event_type=''service_account.created'' AND (
      json_extract(NEW.payload_json,''$.status'')!=''active''
      OR json_type(NEW.payload_json,''$.constraint_generation'')!=''integer''
      OR json_type(NEW.payload_json,''$.credential_generation'') IS NOT NULL))
  OR (NEW.event_type=''service_account.credential_rotated'' AND (
      json_extract(NEW.payload_json,''$.status'')!=''active''
      OR json_type(NEW.payload_json,''$.credential_generation'')!=''integer''
      OR json_type(NEW.payload_json,''$.constraint_generation'') IS NOT NULL))
  OR (NEW.event_type=''service_account.revoked'' AND (
      json_extract(NEW.payload_json,''$.status'')!=''revoked''
      OR json_type(NEW.payload_json,''$.credential_generation'') IS NOT NULL
      OR json_type(NEW.payload_json,''$.constraint_generation'') IS NOT NULL))
BEGIN SELECT RAISE(ABORT,''machine_identity_outbox_owner_invalid''); END', '35b56f1f13ae0d328e548389593ccd3dd0d3adc62da1e2545f19c7f7322c67e3'),
('trg_machine_identity_outbox_update_prd118', 'machine_identity_event_outbox', 'CREATE TRIGGER trg_machine_identity_outbox_update_prd118
BEFORE UPDATE ON machine_identity_event_outbox FOR EACH ROW
WHEN NEW.machine_identity_outbox_id!=OLD.machine_identity_outbox_id
  OR NEW.machine_identity_audit_id!=OLD.machine_identity_audit_id
  OR NEW.workspace_id!=OLD.workspace_id OR NEW.tenant_id!=OLD.tenant_id
  OR NEW.event_type!=OLD.event_type OR NEW.aggregate_id!=OLD.aggregate_id
  OR NEW.aggregate_revision!=OLD.aggregate_revision OR NEW.payload_json!=OLD.payload_json
  OR NEW.created_at!=OLD.created_at OR NEW.updated_at<=OLD.updated_at
  OR NOT(
    (OLD.status=''pending'' AND NEW.status=''delivering''
      AND NEW.attempt_count=OLD.attempt_count+1
      AND NEW.next_attempt_at IS OLD.next_attempt_at)
    OR(OLD.status=''delivering'' AND NEW.status=''delivering''
      AND NEW.attempt_count=OLD.attempt_count
      AND NEW.next_attempt_at IS OLD.next_attempt_at
      AND NEW.lease_owner_id=OLD.lease_owner_id AND NEW.lease_token=OLD.lease_token
      AND NEW.lease_expires_at>OLD.lease_expires_at)
    OR(OLD.status=''delivering'' AND NEW.status=''delivered''
      AND NEW.attempt_count=OLD.attempt_count
      AND NEW.next_attempt_at IS OLD.next_attempt_at)
    OR(OLD.status=''delivering'' AND NEW.status IN(''pending'',''failed'')
      AND NEW.attempt_count=OLD.attempt_count
      AND NEW.next_attempt_at IS NOT NULL)
    OR(OLD.status=''failed'' AND NEW.status=''pending''
      AND NEW.attempt_count=OLD.attempt_count
      AND NEW.next_attempt_at IS NOT NULL))
BEGIN SELECT RAISE(ABORT,''machine_identity_outbox_transition_invalid''); END', 'ddd40f0219eacd5bd0df2d9bc7f866311c3b5cee65e67ad7061368e7137afd75'),
('trg_maintenance_delete_prd112', 'maintenance_windows', 'CREATE TRIGGER trg_maintenance_delete_prd112 BEFORE DELETE ON maintenance_windows
BEGIN SELECT RAISE(ABORT,''maintenance_immutable''); END', '73b1677b1a3b30bd76295e13eb1e37356ed98ac03218d904347f35a41c55bf59'),
('trg_maintenance_update_prd112', 'maintenance_windows', 'CREATE TRIGGER trg_maintenance_update_prd112
BEFORE UPDATE ON maintenance_windows FOR EACH ROW
WHEN NEW.maintenance_window_id!=OLD.maintenance_window_id
  OR NEW.workspace_id!=OLD.workspace_id OR NEW.tenant_id!=OLD.tenant_id
  OR NEW.public_reference!=OLD.public_reference OR NEW.title!=OLD.title
  OR NEW.public_message!=OLD.public_message OR NEW.visibility!=OLD.visibility
  OR NEW.affected_components_json!=OLD.affected_components_json
  OR NEW.affected_regions_json!=OLD.affected_regions_json
  OR NEW.starts_at!=OLD.starts_at OR NEW.ends_at!=OLD.ends_at
  OR NEW.created_by_operator_id!=OLD.created_by_operator_id OR NEW.created_at!=OLD.created_at
  OR NEW.revision!=OLD.revision+1 OR NEW.updated_at<=OLD.updated_at
  OR OLD.status IN(''completed'',''cancelled'')
  OR NOT(NEW.status=OLD.status
    OR(OLD.status=''planned'' AND NEW.status IN(''in_progress'',''cancelled''))
    OR(OLD.status=''in_progress'' AND NEW.status=''completed''))
BEGIN SELECT RAISE(ABORT,''maintenance_transition_invalid''); END', 'be7580ce8e10e697bed1ea6e1d4bcd8b34870dcaf29984e9e101b65c867ecfbe'),
('trg_mcp_attempts_delete_prd082', 'mcp_invocation_attempts', 'CREATE TRIGGER trg_mcp_attempts_delete_prd082
BEFORE DELETE ON mcp_invocation_attempts FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''mcp_attempt_immutable''); END', '63c4bc8c9409d0874b1c6ba7aec15acc1c4320d98197a0dd69c80245a45b3691'),
('trg_mcp_attempts_owner_insert_prd082', 'mcp_invocation_attempts', 'CREATE TRIGGER trg_mcp_attempts_owner_insert_prd082
BEFORE INSERT ON mcp_invocation_attempts FOR EACH ROW
WHEN NEW.status!=''processing'' OR NEW.error_code IS NOT NULL
  OR NEW.completed_at IS NOT NULL OR NEW.duration_ms IS NOT NULL
  OR NEW.response_bytes IS NOT NULL
  OR (NEW.attempt_kind=''probe'' AND NEW.request_bytes IS NOT NULL)
  OR (NEW.attempt_kind=''call'' AND NEW.request_bytes IS NULL)
  OR NOT EXISTS(SELECT 1 FROM mcp_invocations invocation
    WHERE invocation.tenant_id=NEW.tenant_id
      AND invocation.mcp_invocation_id=NEW.mcp_invocation_id
      AND invocation.lease_generation=NEW.lease_generation
      AND ((NEW.attempt_kind=''probe'' AND invocation.status=''probing''
          AND NEW.attempt_number=invocation.probe_attempt_count)
        OR (NEW.attempt_kind=''call'' AND invocation.status=''calling''
          AND NEW.attempt_number=invocation.call_attempt_count)))
  OR EXISTS(SELECT 1 FROM mcp_invocation_attempts current
    WHERE current.mcp_invocation_attempt_id=NEW.mcp_invocation_attempt_id
      OR (NEW.rowid!=-1 AND current.rowid=NEW.rowid))
BEGIN SELECT RAISE(ABORT,''mcp_attempt_owner_mismatch''); END', 'e30d94440e07725eab17056d18081b24275c87b27db91245ca1ba45c7a8b7b02'),
('trg_mcp_attempts_transition_prd082', 'mcp_invocation_attempts', 'CREATE TRIGGER trg_mcp_attempts_transition_prd082
BEFORE UPDATE ON mcp_invocation_attempts FOR EACH ROW
WHEN NEW.rowid!=OLD.rowid OR NEW.mcp_invocation_attempt_id!=OLD.mcp_invocation_attempt_id
  OR NEW.tenant_id!=OLD.tenant_id OR NEW.mcp_invocation_id!=OLD.mcp_invocation_id
  OR NEW.attempt_kind!=OLD.attempt_kind OR NEW.attempt_number!=OLD.attempt_number
  OR NEW.lease_generation!=OLD.lease_generation OR NEW.started_at!=OLD.started_at
  OR NEW.call_started_at IS NOT OLD.call_started_at
  OR (NEW.attempt_kind=''call'' AND NEW.request_bytes IS NULL)
  OR (NEW.attempt_kind=''probe'' AND OLD.request_bytes IS NOT NULL
    AND NEW.request_bytes IS NOT OLD.request_bytes)
  OR (NEW.attempt_kind=''probe'' AND NEW.status=''outcome_unknown'')
  OR (NEW.attempt_kind=''probe'' AND NEW.status=''failed''
    AND NEW.error_code NOT IN(''mcp.executor_disabled'',''mcp.arguments_blocked'',
      ''mcp.authorization_revoked'',''mcp.server_unavailable'',''mcp.state_conflict'',
      ''mcp.unavailable'',''mcp.network_blocked'',''mcp.sandbox_unavailable''))
  OR (NEW.attempt_kind=''call'' AND NEW.status IN(''failed'',''outcome_unknown'')
    AND NEW.error_code NOT IN(''mcp.tool_failed'',''mcp.result_blocked'',
      ''mcp.output_dlp_unavailable'',''mcp.result_invalid'',''mcp.outcome_unknown'',
      ''mcp.state_conflict'',''mcp.unavailable''))
  OR (NEW.status=''outcome_unknown'' AND NEW.error_code!=''mcp.outcome_unknown'')
  OR NOT EXISTS(
    SELECT 1 FROM mcp_invocations invocation
    WHERE invocation.tenant_id=OLD.tenant_id
      AND invocation.mcp_invocation_id=OLD.mcp_invocation_id
      AND invocation.lease_generation=OLD.lease_generation
      AND invocation.lease_owner_id IS NOT NULL
      AND invocation.lease_token IS NOT NULL
      AND unixepoch(NEW.completed_at)>=unixepoch(invocation.updated_at)
      AND ((OLD.attempt_kind=''probe'' AND invocation.status=''probing''
          AND invocation.probe_attempt_count=OLD.attempt_number)
        OR (OLD.attempt_kind=''call'' AND invocation.status=''calling''
          AND invocation.call_attempt_count=OLD.attempt_number))
      AND (
        unixepoch(NEW.completed_at)<unixepoch(invocation.lease_expires_at)
        OR (unixepoch(NEW.completed_at)>=unixepoch(invocation.lease_expires_at)
          AND ((OLD.attempt_kind=''probe'' AND NEW.status=''failed''
              AND NEW.error_code=''mcp.server_unavailable'')
            OR (OLD.attempt_kind=''call'' AND NEW.status=''outcome_unknown''
              AND NEW.error_code=''mcp.outcome_unknown'')))))
  OR OLD.status!=''processing'' OR NEW.status NOT IN(''succeeded'',''failed'',''outcome_unknown'')
BEGIN SELECT RAISE(ABORT,''mcp_attempt_transition_invalid''); END', 'c3cd0cea41b9ae4899c027f6a800ec44932adba2a797f086bc3631e4d63163fa'),
('trg_mcp_outbox_delete_prd082', 'mcp_invocation_event_outbox', 'CREATE TRIGGER trg_mcp_outbox_delete_prd082
BEFORE DELETE ON mcp_invocation_event_outbox FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''mcp_outbox_immutable''); END', 'ae09dfd7e09090abb17a96375715439bcec426ddaf6886baa484fbe996e193fb'),
('trg_mcp_outbox_owner_insert_prd082', 'mcp_invocation_event_outbox', 'CREATE TRIGGER trg_mcp_outbox_owner_insert_prd082
BEFORE INSERT ON mcp_invocation_event_outbox FOR EACH ROW
WHEN NEW.status!=''pending'' OR NEW.attempt_count!=0 OR NEW.lease_generation!=0
  OR NEW.next_attempt_at!=NEW.created_at OR NEW.created_at!=NEW.updated_at
  OR NEW.lease_owner_id IS NOT NULL OR NEW.lease_token IS NOT NULL
  OR NEW.lease_expires_at IS NOT NULL OR NEW.error_code IS NOT NULL
  OR NEW.delivered_at IS NOT NULL
  OR (NEW.subscription_snapshot_json IS NOT NULL
    AND NEW.snapshot_frozen_at!=NEW.created_at)
  OR NOT EXISTS(SELECT 1 FROM mcp_invocation_events event
    WHERE event.tenant_id=NEW.tenant_id
      AND event.mcp_invocation_event_id=NEW.mcp_invocation_event_id
      AND event.created_at=NEW.created_at)
  OR EXISTS(SELECT 1 FROM mcp_invocation_event_outbox current
    WHERE current.mcp_invocation_event_outbox_id=NEW.mcp_invocation_event_outbox_id
      OR (NEW.rowid!=-1 AND current.rowid=NEW.rowid))
BEGIN SELECT RAISE(ABORT,''mcp_outbox_owner_mismatch''); END', '5ce6d1535d24e457919aa277e4c542aa16458b7bc5f82bae8c894b78b68fa651'),
('trg_mcp_outbox_transition_prd082', 'mcp_invocation_event_outbox', 'CREATE TRIGGER trg_mcp_outbox_transition_prd082
BEFORE UPDATE ON mcp_invocation_event_outbox FOR EACH ROW
WHEN NEW.rowid!=OLD.rowid
  OR NEW.mcp_invocation_event_outbox_id!=OLD.mcp_invocation_event_outbox_id
  OR NEW.tenant_id!=OLD.tenant_id
  OR NEW.mcp_invocation_event_id!=OLD.mcp_invocation_event_id
  OR NEW.created_at!=OLD.created_at OR NEW.lease_generation!=OLD.lease_generation+1
  OR unixepoch(NEW.updated_at)<unixepoch(OLD.updated_at)
  OR (OLD.subscription_snapshot_json IS NOT NULL
    AND (NEW.subscription_snapshot_json IS NOT OLD.subscription_snapshot_json
      OR NEW.snapshot_frozen_at IS NOT OLD.snapshot_frozen_at))
  OR NOT ((OLD.status=''pending'' AND NEW.status=''processing''
      AND NEW.attempt_count=OLD.attempt_count+1
      AND unixepoch(NEW.updated_at)>=unixepoch(OLD.next_attempt_at)
      AND NEW.subscription_snapshot_json IS OLD.subscription_snapshot_json
      AND NEW.snapshot_frozen_at IS OLD.snapshot_frozen_at)
    OR (OLD.status=''processing'' AND NEW.status=''processing''
      AND unixepoch(NEW.updated_at)>=unixepoch(OLD.lease_expires_at)
      AND NEW.attempt_count=OLD.attempt_count+1 AND NEW.lease_token!=OLD.lease_token
      AND NEW.subscription_snapshot_json IS OLD.subscription_snapshot_json
      AND NEW.snapshot_frozen_at IS OLD.snapshot_frozen_at)
    OR (OLD.status=''processing'' AND NEW.status=''processing''
      AND unixepoch(NEW.updated_at)<unixepoch(OLD.lease_expires_at)
      AND NEW.attempt_count=OLD.attempt_count
      AND NEW.lease_owner_id=OLD.lease_owner_id AND NEW.lease_token!=OLD.lease_token
      AND unixepoch(NEW.lease_expires_at)>=unixepoch(OLD.lease_expires_at)
      AND ((OLD.subscription_snapshot_json IS NULL
          AND NEW.subscription_snapshot_json IS NOT NULL
          AND NEW.snapshot_frozen_at=NEW.updated_at)
        OR (NEW.subscription_snapshot_json IS OLD.subscription_snapshot_json
          AND NEW.snapshot_frozen_at IS OLD.snapshot_frozen_at)))
    OR (OLD.status=''processing'' AND NEW.status=''pending''
      AND unixepoch(NEW.updated_at)<unixepoch(OLD.lease_expires_at)
      AND NEW.attempt_count=OLD.attempt_count AND NEW.attempt_count<10
      AND NEW.error_code IS NULL
      AND NEW.subscription_snapshot_json IS OLD.subscription_snapshot_json
      AND NEW.snapshot_frozen_at IS OLD.snapshot_frozen_at)
    OR (OLD.status=''processing'' AND NEW.status IN(''succeeded'',''failed'')
      AND unixepoch(NEW.updated_at)<unixepoch(OLD.lease_expires_at)
      AND NEW.attempt_count=OLD.attempt_count
      AND NEW.subscription_snapshot_json IS OLD.subscription_snapshot_json
      AND NEW.snapshot_frozen_at IS OLD.snapshot_frozen_at)
    OR (OLD.status=''processing'' AND NEW.status=''failed''
      AND OLD.attempt_count=10 AND NEW.attempt_count=OLD.attempt_count
      AND unixepoch(NEW.updated_at)>=unixepoch(OLD.lease_expires_at)
      AND NEW.error_code=''webhook.delivery_unavailable''
      AND NEW.subscription_snapshot_json IS OLD.subscription_snapshot_json
      AND NEW.snapshot_frozen_at IS OLD.snapshot_frozen_at))
BEGIN SELECT RAISE(ABORT,''mcp_outbox_transition_invalid''); END', '4a4c5d04e60b6b75bf6a79011cd3b1db3b29947de25768c5b30e2c7d3c5ab7f7'),
('trg_mcp_events_delete_prd082', 'mcp_invocation_events', 'CREATE TRIGGER trg_mcp_events_delete_prd082
