('trg_mcp_network_revisions_owner_insert_prd083', 'mcp_network_policy_revisions', 'CREATE TRIGGER trg_mcp_network_revisions_owner_insert_prd083
BEFORE INSERT ON mcp_network_policy_revisions FOR EACH ROW
WHEN NOT EXISTS(SELECT 1 FROM mcp_servers server JOIN users actor
