('trg_mcp_credentials_owner_insert_prd082', 'mcp_server_credentials', 'CREATE TRIGGER trg_mcp_credentials_owner_insert_prd082
BEFORE INSERT ON mcp_server_credentials FOR EACH ROW
WHEN NEW.status!=''candidate'' OR NEW.activated_at IS NOT NULL OR NEW.rejected_at IS NOT NULL
  OR NOT EXISTS(SELECT 1 FROM mcp_servers server JOIN users actor
