('trg_mcp_tools_transition_prd082', 'mcp_tools', 'CREATE TRIGGER trg_mcp_tools_transition_prd082
BEFORE UPDATE ON mcp_tools FOR EACH ROW
WHEN NEW.rowid!=OLD.rowid OR NEW.mcp_tool_id!=OLD.mcp_tool_id
  OR NEW.tenant_id!=OLD.tenant_id OR NEW.mcp_server_id!=OLD.mcp_server_id
  OR NEW.remote_name!=OLD.remote_name OR NEW.created_by!=OLD.created_by
  OR NEW.created_at!=OLD.created_at OR unixepoch(NEW.updated_at)<unixepoch(OLD.updated_at)
  OR NOT EXISTS(SELECT 1 FROM users actor WHERE actor.tenant_id=NEW.tenant_id
    AND actor.user_id=NEW.updated_by AND actor.status=''active'')
  OR NOT (
    (NEW.schema_revision=OLD.schema_revision+1
      AND NEW.policy_revision=OLD.policy_revision+1 AND NEW.status=''review_required'')
    OR (NEW.schema_revision=OLD.schema_revision
      AND NEW.policy_revision=OLD.policy_revision+1
      AND NEW.input_schema_original_json=OLD.input_schema_original_json
      AND NEW.input_schema_original_sha256=OLD.input_schema_original_sha256
      AND NEW.input_schema_effective_json=OLD.input_schema_effective_json
      AND NEW.input_schema_effective_sha256=OLD.input_schema_effective_sha256
      AND NEW.output_schema_original_json IS OLD.output_schema_original_json
      AND NEW.output_schema_original_sha256 IS OLD.output_schema_original_sha256
      AND NEW.output_schema_effective_json IS OLD.output_schema_effective_json
      AND NEW.output_schema_effective_sha256 IS OLD.output_schema_effective_sha256
      AND NEW.annotations_json=OLD.annotations_json
      AND NEW.annotations_sha256=OLD.annotations_sha256)
    OR (NEW.schema_revision=OLD.schema_revision AND NEW.policy_revision=OLD.policy_revision
      AND NEW.title IS OLD.title AND NEW.description IS OLD.description
      AND NEW.input_schema_original_json=OLD.input_schema_original_json
      AND NEW.input_schema_original_sha256=OLD.input_schema_original_sha256
      AND NEW.input_schema_effective_json=OLD.input_schema_effective_json
      AND NEW.input_schema_effective_sha256=OLD.input_schema_effective_sha256
      AND NEW.output_schema_original_json IS OLD.output_schema_original_json
      AND NEW.output_schema_original_sha256 IS OLD.output_schema_original_sha256
      AND NEW.output_schema_effective_json IS OLD.output_schema_effective_json
      AND NEW.output_schema_effective_sha256 IS OLD.output_schema_effective_sha256
      AND NEW.annotations_json=OLD.annotations_json
      AND NEW.annotations_sha256=OLD.annotations_sha256
      AND NEW.risk_level=OLD.risk_level AND NEW.approval_required=OLD.approval_required
      AND NEW.approval_expires_seconds=OLD.approval_expires_seconds
      AND NEW.required_permission_codes_json=OLD.required_permission_codes_json
      AND NEW.result_redaction_pointers_json=OLD.result_redaction_pointers_json
      AND OLD.status IN(''active'',''review_required'') AND NEW.status=''disabled'')
    OR (NEW.schema_revision=OLD.schema_revision AND NEW.policy_revision=OLD.policy_revision
      AND NEW.title IS OLD.title AND NEW.description IS OLD.description
      AND NEW.input_schema_original_json=OLD.input_schema_original_json
      AND NEW.input_schema_original_sha256=OLD.input_schema_original_sha256
      AND NEW.input_schema_effective_json=OLD.input_schema_effective_json
      AND NEW.input_schema_effective_sha256=OLD.input_schema_effective_sha256
      AND NEW.output_schema_original_json IS OLD.output_schema_original_json
      AND NEW.output_schema_original_sha256 IS OLD.output_schema_original_sha256
      AND NEW.output_schema_effective_json IS OLD.output_schema_effective_json
      AND NEW.output_schema_effective_sha256 IS OLD.output_schema_effective_sha256
      AND NEW.annotations_json=OLD.annotations_json
      AND NEW.annotations_sha256=OLD.annotations_sha256
      AND NEW.risk_level=OLD.risk_level AND NEW.approval_required=OLD.approval_required
      AND NEW.approval_expires_seconds=OLD.approval_expires_seconds
      AND NEW.required_permission_codes_json=OLD.required_permission_codes_json
      AND NEW.result_redaction_pointers_json=OLD.result_redaction_pointers_json
      AND NEW.status=OLD.status
      AND unixepoch(NEW.updated_at)>=unixepoch(OLD.updated_at)
      AND EXISTS(
        SELECT 1 FROM mcp_server_operations operation
        JOIN mcp_server_sync_jobs job
          ON job.tenant_id=operation.tenant_id
          AND job.mcp_server_id=operation.mcp_server_id
          AND job.mcp_server_operation_id=operation.mcp_server_operation_id
        WHERE operation.tenant_id=NEW.tenant_id
          AND operation.mcp_server_id=NEW.mcp_server_id
          AND operation.operation_type=''refresh'' AND operation.status=''processing''
          AND operation.actor_user_id=NEW.updated_by
          AND job.job_type=''discover'' AND job.status=''processing''
          AND unixepoch(job.lease_expires_at)>unixepoch(NEW.updated_at)
          AND unixepoch(job.deadline_at)>unixepoch(NEW.updated_at)))
  )
  OR (NEW.status=''active'' AND NOT EXISTS(
    SELECT 1 FROM mcp_tool_role_grants role_grant
      WHERE role_grant.tenant_id=NEW.tenant_id AND role_grant.mcp_tool_id=NEW.mcp_tool_id
    UNION ALL
    SELECT 1 FROM mcp_tool_user_grants user_grant
      WHERE user_grant.tenant_id=NEW.tenant_id AND user_grant.mcp_tool_id=NEW.mcp_tool_id))
BEGIN SELECT RAISE(ABORT,''mcp_tool_transition_invalid''); END', '59cfb972701da39d236b1d110524f4cb7bca2111b4c107e8cd35fa638dc49f16'),
