('trg_model_aliases_prd047_owner_insert', 'model_aliases', 'CREATE TRIGGER trg_model_aliases_prd047_owner_insert
BEFORE INSERT ON model_aliases
FOR EACH ROW
WHEN
  NEW.environment_id IS NULL
  OR NOT EXISTS (
    SELECT 1 FROM environments e
    WHERE e.tenant_id=NEW.tenant_id
      AND e.environment_id=NEW.environment_id
      AND e.code=NEW.environment
  )
  OR NOT EXISTS (
    SELECT 1 FROM models m
    WHERE m.tenant_id=NEW.tenant_id AND m.model_id=NEW.default_model_id
  )
  OR (
    NEW.fallback_model_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM models m
      WHERE m.tenant_id=NEW.tenant_id AND m.model_id=NEW.fallback_model_id
    )
  )
  OR NEW.fallback_model_id IS NEW.default_model_id
BEGIN
  SELECT RAISE(ABORT, ''model_aliases.owner_graph_invalid'');
END', 'f1f50e64558c9af58002766287be5b7050b24bf1785a996c7110dd51f967e37d'),
('trg_model_aliases_prd047_owner_update', 'model_aliases', 'CREATE TRIGGER trg_model_aliases_prd047_owner_update
BEFORE UPDATE OF tenant_id, environment_id, environment, default_model_id, fallback_model_id
ON model_aliases
FOR EACH ROW
WHEN
  NEW.environment_id IS NULL
  OR NOT EXISTS (
    SELECT 1 FROM environments e
    WHERE e.tenant_id=NEW.tenant_id
      AND e.environment_id=NEW.environment_id
      AND e.code=NEW.environment
  )
  OR NOT EXISTS (
    SELECT 1 FROM models m
    WHERE m.tenant_id=NEW.tenant_id AND m.model_id=NEW.default_model_id
  )
  OR (
    NEW.fallback_model_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM models m
      WHERE m.tenant_id=NEW.tenant_id AND m.model_id=NEW.fallback_model_id
    )
  )
  OR NEW.fallback_model_id IS NEW.default_model_id
BEGIN
  SELECT RAISE(ABORT, ''model_aliases.owner_graph_invalid'');
END', 'da14287ad5eacc252627db20f3d5505a78448b0dff2bd1597aa710accea3f818'),
('trg_model_aliases_prd047_policy_insert', 'model_aliases', 'CREATE TRIGGER trg_model_aliases_prd047_policy_insert
AFTER INSERT ON model_aliases
FOR EACH ROW
BEGIN
  -- 新 Alias 仍创建 fixed Policy，质量配置只是休眠值，不能未经管理员显式启用影响流量。
  INSERT INTO model_alias_routing_policies(
    routing_policy_id, tenant_id, model_alias_id, routing_mode,
    quality_weight_bps, cost_weight_bps, latency_weight_bps,
    quality_floor_bps, minimum_sample_count,
    status, version, created_by, updated_by, created_at, updated_at
  )
  VALUES(
    ''rpol_'' || lower(hex(randomblob(16))), NEW.tenant_id, NEW.model_alias_id,
    ''fixed'', 5000, 3000, 2000, 6000, 20,
    ''enabled'', 1, NEW.created_by, NEW.created_by, NEW.created_at, NEW.updated_at
  );
END', '317275b4d848be10b05fd0c47117ba9ad1701f2e5951ad780fda1ce305cf2493'),
('trg_model_aliases_prd047_policy_update', 'model_aliases', 'CREATE TRIGGER trg_model_aliases_prd047_policy_update
AFTER UPDATE OF alias, environment, environment_id, status, default_model_id, fallback_model_id
ON model_aliases
FOR EACH ROW
WHEN
  NEW.alias IS NOT OLD.alias
  OR NEW.environment IS NOT OLD.environment
  OR NEW.environment_id IS NOT OLD.environment_id
  OR NEW.status IS NOT OLD.status
  OR NEW.default_model_id IS NOT OLD.default_model_id
  OR NEW.fallback_model_id IS NOT OLD.fallback_model_id
BEGIN
  -- Alias 图发生真实变化时只推进同租户 Policy 一次版本，保留既有 CAS 可见性合同。
  UPDATE model_alias_routing_policies
  SET version=version+1, updated_at=NEW.updated_at
  WHERE tenant_id=NEW.tenant_id AND model_alias_id=NEW.model_alias_id;
END', '8b298afb44831dc66736808f6741640053c2792b4410681dd95706238150833c'),
('trg_policy_template_model_alias_delete_prd068', 'model_aliases', 'CREATE TRIGGER trg_policy_template_model_alias_delete_prd068
BEFORE DELETE ON model_aliases FOR EACH ROW
WHEN EXISTS (
  SELECT 1
  FROM policy_template_application_dependencies dependency
  JOIN policy_template_applications application
    ON application.tenant_id=dependency.tenant_id
   AND application.application_id=dependency.application_id
  WHERE dependency.tenant_id=OLD.tenant_id
    AND dependency.resource_type=''model_alias''
    AND dependency.resource_id=OLD.model_alias_id
    AND application.status=''applied''
)
BEGIN SELECT RAISE(ABORT,''policy_template_dependency_immutable''); END', '4c1e0446d4f1a31e3f8e26d88430a866ced189f1de6818f4e3443f932645d537'),
('trg_policy_template_model_alias_insert_prd068', 'model_aliases', 'CREATE TRIGGER trg_policy_template_model_alias_insert_prd068
BEFORE INSERT ON model_aliases FOR EACH ROW
WHEN NEW.status=''active'' AND EXISTS (
  SELECT 1
  FROM policy_template_application_dependencies dependency
  JOIN policy_template_applications application
    ON application.tenant_id=dependency.tenant_id
   AND application.application_id=dependency.application_id
  JOIN policy_templates template
    ON template.tenant_id=application.tenant_id
   AND template.policy_template_id=application.policy_template_id
  WHERE dependency.tenant_id=NEW.tenant_id
    AND dependency.resource_type=''model_alias''
    AND dependency.resource_name=NEW.alias
    AND application.status=''applied''
    AND template.template_code=''domestic_models_only''
)
BEGIN SELECT RAISE(ABORT,''policy_template_dependency_immutable''); END', 'e04bd090115e48fc0d9bf76413a1d4c295a6488bb3af01a96cb5558306438b16'),
('trg_policy_template_model_alias_update_prd068', 'model_aliases', 'CREATE TRIGGER trg_policy_template_model_alias_update_prd068
BEFORE UPDATE ON model_aliases FOR EACH ROW
WHEN EXISTS (
  SELECT 1
  FROM policy_template_application_dependencies dependency
  JOIN policy_template_applications application
    ON application.tenant_id=dependency.tenant_id
   AND application.application_id=dependency.application_id
  WHERE dependency.tenant_id=OLD.tenant_id
    AND dependency.resource_type=''model_alias''
    AND dependency.resource_id=OLD.model_alias_id
    AND application.status=''applied''
)
AND (
  NEW.rowid!=OLD.rowid OR NEW.model_alias_id!=OLD.model_alias_id
  OR NEW.tenant_id!=OLD.tenant_id OR NEW.alias!=OLD.alias
  OR NEW.environment!=OLD.environment OR NEW.environment_id IS NOT OLD.environment_id
  OR NEW.default_model_id!=OLD.default_model_id
  OR NEW.fallback_model_id IS NOT OLD.fallback_model_id
  OR NEW.status!=OLD.status
)
BEGIN SELECT RAISE(ABORT,''policy_template_dependency_immutable''); END', 'c2beba153f0ce2fa461e7436545fcd54152b9fce66a638bba69f6e5a7643163f'),
('trg_model_experiments_delete_prd075', 'model_experiments', 'CREATE TRIGGER trg_model_experiments_delete_prd075
BEFORE DELETE ON model_experiments FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''experiment_immutable''); END', 'e2a9cbba98e4473efa68a457d068f245fcf47644ffad7ea1b899b6542df10879'),
('trg_model_experiments_feedback_fence_facts_prd075', 'model_experiments', 'CREATE TRIGGER trg_model_experiments_feedback_fence_facts_prd075
AFTER UPDATE OF feedback_fence_closed_at ON model_experiments FOR EACH ROW
WHEN OLD.feedback_fence_closed_at IS NULL AND NEW.feedback_fence_closed_at IS NOT NULL
BEGIN
  -- 迁移 model_experiments 的模板、租户投影或守卫事实；写入集合由事务和精确条件限定。
  UPDATE model_experiments
  SET facts_version=facts_version+1
  WHERE tenant_id=NEW.tenant_id AND experiment_id=NEW.experiment_id
    AND facts_version<9223372036854775807;
  SELECT CASE WHEN changes()!=1 THEN RAISE(ABORT,''experiment_facts_version_invalid'') END;
END', 'bfd9e2f15f687414ffadc0fad253a508064bbd192cad2589a3e938767d411153'),
('trg_model_experiments_finalization_update_prd075', 'model_experiments', 'CREATE TRIGGER trg_model_experiments_finalization_update_prd075
BEFORE UPDATE ON model_experiments FOR EACH ROW
WHEN NOT (
    (NEW.finalization_generation=OLD.finalization_generation
      AND NEW.finalization_owner_id IS OLD.finalization_owner_id
      AND NEW.finalization_lease_token IS OLD.finalization_lease_token
      AND NEW.finalization_lease_expires_at IS OLD.finalization_lease_expires_at
      AND (OLD.finalization_lease_token IS NULL OR (
        NEW.status=OLD.status
        AND NEW.assigned_count=OLD.assigned_count
        AND NEW.model_a_assigned_count=OLD.model_a_assigned_count
        AND NEW.model_b_assigned_count=OLD.model_b_assigned_count
        AND NEW.facts_version=OLD.facts_version
        AND NEW.feedback_fence_closed_at IS OLD.feedback_fence_closed_at
        AND NEW.sampling_ended_at IS OLD.sampling_ended_at
        AND NEW.feedback_deadline_at IS OLD.feedback_deadline_at
        AND NEW.settlement_deadline_at IS OLD.settlement_deadline_at
        AND NEW.completion_reason IS OLD.completion_reason
        AND NEW.completed_at IS OLD.completed_at
        AND NEW.updated_at=OLD.updated_at)))
    OR (
      OLD.status=''collecting_feedback'' AND NEW.status=''collecting_feedback''
      AND NEW.feedback_fence_closed_at IS NOT NULL
      AND NEW.finalization_generation=OLD.finalization_generation+1
      AND (OLD.finalization_lease_token IS NULL
        OR unixepoch(OLD.finalization_lease_expires_at)<=unixepoch(''now''))
      AND NEW.finalization_owner_id IS NOT NULL
      AND NEW.finalization_lease_token IS NOT NULL
      AND NEW.finalization_lease_expires_at IS NOT NULL
      AND unixepoch(NEW.finalization_lease_expires_at)>unixepoch(''now'')
      AND unixepoch(NEW.finalization_lease_expires_at)<=unixepoch(''now'')+300
      AND EXISTS(SELECT 1 FROM experiment_scheduler_tenants scheduler
        WHERE scheduler.tenant_id=NEW.tenant_id
          AND scheduler.lease_owner_id=NEW.finalization_owner_id
          AND scheduler.lease_token IS NOT NULL
          AND unixepoch(scheduler.lease_expires_at)>unixepoch(''now'')
          AND unixepoch(scheduler.lease_expires_at)
            >=unixepoch(NEW.finalization_lease_expires_at))
      AND (SELECT COUNT(*) FROM experiment_request_executions execution
        WHERE execution.tenant_id=NEW.tenant_id
          AND execution.experiment_id=NEW.experiment_id
          AND execution.status=''terminal'')=NEW.assigned_count
      AND (SELECT COUNT(*) FROM experiment_request_outcomes outcome
        WHERE outcome.tenant_id=NEW.tenant_id
          AND outcome.experiment_id=NEW.experiment_id)=NEW.assigned_count
      AND (SELECT COUNT(*) FROM experiment_usage_settlements settlement
        WHERE settlement.tenant_id=NEW.tenant_id
          AND settlement.experiment_id=NEW.experiment_id
          AND settlement.status!=''pending'')=NEW.assigned_count
    )
    OR (
      OLD.status=''collecting_feedback'' AND NEW.status=''completed''
      AND NEW.finalization_generation=OLD.finalization_generation
      AND OLD.finalization_owner_id IS NOT NULL
      AND OLD.finalization_lease_token IS NOT NULL
      AND unixepoch(OLD.finalization_lease_expires_at)>unixepoch(''now'')
      AND NEW.finalization_owner_id IS NULL
      AND NEW.finalization_lease_token IS NULL
      AND NEW.finalization_lease_expires_at IS NULL
      AND EXISTS(SELECT 1 FROM experiment_scheduler_tenants scheduler
        WHERE scheduler.tenant_id=OLD.tenant_id
          AND scheduler.lease_owner_id=OLD.finalization_owner_id
          AND scheduler.lease_token IS NOT NULL
          AND unixepoch(scheduler.lease_expires_at)>unixepoch(''now''))
    )
  )
BEGIN SELECT RAISE(ABORT,''experiment_finalization_state_invalid''); END', 'c5c2243e1c3f0032803141d554e589a4cc2c1ce65e65bc0ec9ff05048831a514'),
('trg_model_experiments_immutable_update_prd075', 'model_experiments', 'CREATE TRIGGER trg_model_experiments_immutable_update_prd075
BEFORE UPDATE ON model_experiments FOR EACH ROW
