  );
END', '28f607059acecdaf728bd1078d1e0b0b7aa06270f35c6c6476a9708fb67a39fb'),
('trg_policy_template_model_delete_prd068', 'models', 'CREATE TRIGGER trg_policy_template_model_delete_prd068
