  OR NEW.status NOT IN(''completed'',''cancelled'',''expired'',''superseded'')
BEGIN SELECT RAISE(ABORT,''owner_transfer_immutable''); END', '6d9f64405bd8d71cad3aab1a1ec7ce236ca5c65c3d568c326724b0c26fcd2066'),
