  OR NEW.tenant_id IS NOT OLD.tenant_id
  OR NEW.dsl_version IS NOT OLD.dsl_version
  OR NEW.created_by IS NOT OLD.created_by
  OR NEW.created_at IS NOT OLD.created_at
BEGIN
  SELECT RAISE(ABORT, ''policy_identity_immutable'');
END', '6125827e48be3d07980a48dbbf8491af714cbaf319fbfd539f0931742180b06c'),
('trg_policies_owner_insert', 'policies', 'CREATE TRIGGER trg_policies_owner_insert
BEFORE INSERT ON policies
FOR EACH ROW
WHEN
  NOT EXISTS (
    SELECT 1 FROM users u
    WHERE u.tenant_id = NEW.tenant_id AND u.user_id = NEW.created_by
  )
  OR NOT EXISTS (
    SELECT 1 FROM users u
    WHERE u.tenant_id = NEW.tenant_id AND u.user_id = NEW.updated_by
  )
BEGIN
  SELECT RAISE(ABORT, ''policy_owner_mismatch'');
END', 'a32454bd1a712b2c64cb5cbf5423b63d08b6eed7e8c264838206fbb382401b84'),
('trg_policies_owner_update', 'policies', 'CREATE TRIGGER trg_policies_owner_update
