END', '23c5f14424f97f2795ff487e2283fb7349b8719d85ced4dba041561668fece15'),
('trg_policies_version_increment', 'policies', 'CREATE TRIGGER trg_policies_version_increment
BEFORE UPDATE ON policies
FOR EACH ROW
WHEN typeof(NEW.version) != ''integer'' OR NEW.version != OLD.version + 1
