END', '4d8f652fdd9fa50c8117d21d6208685f96c6cfed81842f124fadad110dfb9ded'),
('trg_policy_template_generated_policy_delete_prd068', 'policies', 'CREATE TRIGGER trg_policy_template_generated_policy_delete_prd068
BEFORE DELETE ON policies FOR EACH ROW
WHEN EXISTS (
  SELECT 1 FROM policy_template_applications application
  WHERE application.tenant_id=OLD.tenant_id
    AND application.generated_policy_id=OLD.policy_id
)
BEGIN SELECT RAISE(ABORT,''policy_template_generated_policy_immutable''); END', '0927f92ffc0dbf3723dbab8f4bc95ac26c804dae2572cc0fdde5787fe5b13463'),
('trg_policy_template_generated_policy_update_prd068', 'policies', 'CREATE TRIGGER trg_policy_template_generated_policy_update_prd068
BEFORE UPDATE ON policies FOR EACH ROW
WHEN EXISTS (
  SELECT 1 FROM policy_template_applications application
  WHERE application.tenant_id=OLD.tenant_id
    AND application.generated_policy_id=OLD.policy_id
)
AND NOT EXISTS (
  SELECT 1 FROM policy_template_applications application
  WHERE application.tenant_id=OLD.tenant_id
    AND application.generated_policy_id=OLD.policy_id
    AND application.status=''rolled_back''
    AND OLD.status=''active'' AND OLD.version=1
    AND NEW.status=''disabled'' AND NEW.version=2
    AND NEW.rowid=OLD.rowid AND NEW.policy_id=OLD.policy_id
    AND NEW.tenant_id=OLD.tenant_id AND NEW.name=OLD.name
    AND NEW.description IS OLD.description AND NEW.priority=OLD.priority
    AND NEW.dsl_version=OLD.dsl_version AND NEW.created_by=OLD.created_by
    AND NEW.created_at=OLD.created_at
    AND NEW.updated_by=application.rollback_actor_user_id
    AND NEW.updated_at=application.rolled_back_at
    AND application.rolled_back_policy_version=NEW.version
  )
BEGIN SELECT RAISE(ABORT,''policy_template_generated_policy_immutable''); END', '6a3346b5f913d7e1eb18f8dc51e10935c723646efc8b2097fc3471952c63f6e9'),
('trg_policy_actions_identity_immutable', 'policy_actions', 'CREATE TRIGGER trg_policy_actions_identity_immutable
BEFORE UPDATE OF policy_action_id, tenant_id, policy_id, created_at ON policy_actions
