('trg_prompt_template_version_models_owner_insert_prd067', 'prompt_template_version_models', 'CREATE TRIGGER trg_prompt_template_version_models_owner_insert_prd067
BEFORE INSERT ON prompt_template_version_models FOR EACH ROW
WHEN NOT EXISTS (
    SELECT 1 FROM prompt_template_versions version
    WHERE version.tenant_id=NEW.tenant_id
