    WHERE current.version_model_id=NEW.version_model_id
       OR (current.tenant_id=NEW.tenant_id
           AND current.prompt_template_version_id=NEW.prompt_template_version_id
           AND current.model_alias_id=NEW.model_alias_id)
       OR (NEW.rowid!=-1 AND current.rowid=NEW.rowid)
  )
BEGIN SELECT RAISE(ABORT,''prompt_template_model_owner_mismatch''); END', '08650291691c5a43156d91a7ce74e29e6f252a9289cefd692e606272d40c2b77'),
('trg_prompt_template_version_models_update_prd067', 'prompt_template_version_models', 'CREATE TRIGGER trg_prompt_template_version_models_update_prd067
