('trg_request_feedback_tags_insert_prd049', 'request_feedbacks', 'CREATE TRIGGER trg_request_feedback_tags_insert_prd049
BEFORE INSERT ON request_feedbacks
FOR EACH ROW
WHEN
  EXISTS (
    SELECT 1 FROM json_each(NEW.tags_json) item
    WHERE item.type!=''text''
       OR item.value NOT IN (
         ''accurate'', ''relevant'', ''complete'', ''helpful'', ''clear'',
         ''inaccurate'', ''irrelevant'', ''incomplete'', ''unsafe'', ''slow''
       )
  )
  OR (SELECT COUNT(*) FROM json_each(NEW.tags_json))
     != (SELECT COUNT(DISTINCT value) FROM json_each(NEW.tags_json))
  OR NEW.tags_json != COALESCE((
    SELECT json_group_array(value)
    FROM (
      SELECT value
      FROM json_each(NEW.tags_json)
      ORDER BY CASE value
        WHEN ''accurate'' THEN 1 WHEN ''relevant'' THEN 2 WHEN ''complete'' THEN 3
        WHEN ''helpful'' THEN 4 WHEN ''clear'' THEN 5 WHEN ''inaccurate'' THEN 6
        WHEN ''irrelevant'' THEN 7 WHEN ''incomplete'' THEN 8 WHEN ''unsafe'' THEN 9
        WHEN ''slow'' THEN 10 ELSE 99 END
    )
  ), ''[]'')
  OR (
    EXISTS (SELECT 1 FROM json_each(NEW.tags_json) WHERE value=''accurate'')
    AND EXISTS (SELECT 1 FROM json_each(NEW.tags_json) WHERE value=''inaccurate'')
  )
  OR (
    EXISTS (SELECT 1 FROM json_each(NEW.tags_json) WHERE value=''relevant'')
    AND EXISTS (SELECT 1 FROM json_each(NEW.tags_json) WHERE value=''irrelevant'')
  )
  OR (
    EXISTS (SELECT 1 FROM json_each(NEW.tags_json) WHERE value=''complete'')
    AND EXISTS (SELECT 1 FROM json_each(NEW.tags_json) WHERE value=''incomplete'')
  )
BEGIN
  SELECT RAISE(ABORT, ''request_feedback_tags_invalid'');
END', '84dcfe2ef0cf02e965e73e7ca7fb694036c6425602ab039878cd658d43bf914a'),
('trg_request_feedbacks_experiment_attribution_prd075', 'request_feedbacks', 'CREATE TRIGGER trg_request_feedbacks_experiment_attribution_prd075
AFTER INSERT ON request_feedbacks FOR EACH ROW
BEGIN
  -- 迁移 experiment_feedback_attributions 的模板、租户投影或守卫事实；写入集合由事务和精确条件限定。
  INSERT INTO experiment_feedback_attributions(
    feedback_attribution_id,tenant_id,experiment_id,assignment_id,
    request_feedback_id,source_request_id,variant,rating,accepted,attributed_at,created_at
  )
  SELECT ''exfa_''||lower(hex(randomblob(16))),assignment.tenant_id,
    assignment.experiment_id,assignment.assignment_id,NEW.request_feedback_id,
    NEW.source_request_id,assignment.variant,NEW.rating,NEW.accepted,
    strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''),strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'')
  FROM experiment_assignments assignment
  JOIN model_experiments experiment
    ON experiment.tenant_id=assignment.tenant_id
   AND experiment.experiment_id=assignment.experiment_id
  WHERE assignment.tenant_id=NEW.tenant_id
    AND assignment.request_id=NEW.source_request_id
    AND assignment.model_id=NEW.model_id AND assignment.provider_id=NEW.provider_id
    AND experiment.feedback_collection_enabled=1
    AND experiment.feedback_fence_closed_at IS NULL
    AND experiment.status!=''completed''
    AND (experiment.sampling_ended_at IS NULL
      OR unixepoch(''now'')<unixepoch(experiment.feedback_deadline_at));
END', '96314ae5639cd71b4ed8e26b3250078fa3457a3b1e25ee5a0ef4a4b8d876eb61'),
('trg_request_log_queries_product_event_insert_prd085', 'request_log_query_events', 'CREATE TRIGGER trg_request_log_queries_product_event_insert_prd085
AFTER INSERT ON request_log_query_events FOR EACH ROW
BEGIN
  -- 每次权威查询审计记录生成一条租户内可追踪的日志查看事实。
  INSERT INTO product_events(
    product_event_id,tenant_id,event_type,actor_user_id,source_kind,source_id,
    operation_request_id,operation_trace_id,capture_mode,status,
    occurred_at,created_at,updated_at)
  SELECT
    ''pev_''||substr(metahub_sha256(json_array(
      NEW.tenant_id,''request_logs.viewed'',''request_log_query'',NEW.query_event_id)),1,32),
    NEW.tenant_id,''request_logs.viewed'',NEW.actor_user_id,
    ''request_log_query'',NEW.query_event_id,
    NEW.operation_request_id,NEW.operation_trace_id,''live'',''recorded'',NEW.executed_at,
    strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''),strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'')
  WHERE NOT EXISTS(SELECT 1 FROM product_events current
    WHERE current.tenant_id=NEW.tenant_id AND current.source_kind=''request_log_query''
      AND current.source_id=NEW.query_event_id
      AND current.event_type=''request_logs.viewed'');
END', '3ff88d20141a3684b2ce5a5138996a086fa467912bb790a16c6036abcce62ad5'),
('trg_request_log_query_events_conflict_insert_prd055', 'request_log_query_events', 'CREATE TRIGGER trg_request_log_query_events_conflict_insert_prd055
BEFORE INSERT ON request_log_query_events FOR EACH ROW
WHEN EXISTS (
  SELECT 1 FROM request_log_query_events current
  WHERE current.query_event_id=NEW.query_event_id OR current.event_id=NEW.event_id
    OR (NEW.rowid!=-1 AND current.rowid=NEW.rowid)
)
BEGIN SELECT RAISE(ABORT,''request_log_query_event_immutable''); END', '58a0228bfce5e304e278e2213bfdcf5b81703fc2b76301e755adc82f12736d36'),
('trg_request_log_query_events_immutable_delete_prd055', 'request_log_query_events', 'CREATE TRIGGER trg_request_log_query_events_immutable_delete_prd055
BEFORE DELETE ON request_log_query_events FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''request_log_query_event_immutable''); END', 'baf523eee7795c7c79a3db624440d43f0a513bed28996adca5024c79de6c9b82'),
('trg_request_log_query_events_keys_insert_prd055', 'request_log_query_events', 'CREATE TRIGGER trg_request_log_query_events_keys_insert_prd055
BEFORE INSERT ON request_log_query_events FOR EACH ROW
WHEN NOT (
  json_valid(NEW.filter_keys_json)
  AND CASE WHEN json_valid(NEW.filter_keys_json)
    THEN json_type(NEW.filter_keys_json) END=''array''
  AND (SELECT COUNT(*) FROM json_each(
    CASE WHEN json_valid(NEW.filter_keys_json) THEN NEW.filter_keys_json ELSE ''[]'' END
  ))<=28
  AND NOT EXISTS (
    SELECT 1 FROM json_each(
      CASE WHEN json_valid(NEW.filter_keys_json) THEN NEW.filter_keys_json ELSE ''[]'' END
    ) item
    WHERE item.type!=''text'' OR item.value NOT IN (
      ''request_id'',''trace_id'',''status'',''model'',''request_model'',''resolved_model'',
      ''provider_code'',''virtual_key_id'',''environment_id'',''project_id'',''application_id'',
      ''snapshot_version'',''error_code'',''created_from'',''created_to'',''latency_ms_min'',
      ''latency_ms_max'',''total_tokens_min'',''total_tokens_max'',''cost_amount_min'',
      ''cost_amount_max'',''currency'',''terminal_stage'',''output_safety_status'',
      ''output_safety_mode'',''output_safety_exposure'',''output_safety_billing''
    )
  )
  AND NOT EXISTS (
    SELECT 1
    FROM json_each(
      CASE WHEN json_valid(NEW.filter_keys_json) THEN NEW.filter_keys_json ELSE ''[]'' END
    ) earlier
    JOIN json_each(
      CASE WHEN json_valid(NEW.filter_keys_json) THEN NEW.filter_keys_json ELSE ''[]'' END
    ) later ON CAST(earlier.key AS INTEGER)<CAST(later.key AS INTEGER)
    WHERE CAST(earlier.value AS TEXT)>=CAST(later.value AS TEXT)
  )
)
BEGIN SELECT RAISE(ABORT,''request_log_query_event_keys_invalid''); END', '23cd018aef5dfab0eae322ec85aef939f42876e248beddf1bb9ba22fda29364f'),
('trg_request_log_query_events_owner_insert_prd055', 'request_log_query_events', 'CREATE TRIGGER trg_request_log_query_events_owner_insert_prd055
BEFORE INSERT ON request_log_query_events FOR EACH ROW
WHEN NOT EXISTS (
  SELECT 1 FROM users u WHERE u.user_id=NEW.actor_user_id AND u.tenant_id=NEW.tenant_id
)
OR NOT EXISTS (
  SELECT 1 FROM sessions s WHERE s.session_id=NEW.actor_session_id
    AND s.user_id=NEW.actor_user_id AND s.tenant_id=NEW.tenant_id
)
OR (NEW.saved_filter_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM saved_filters f WHERE f.saved_filter_id=NEW.saved_filter_id
    AND f.tenant_id=NEW.tenant_id AND f.owner_user_id=NEW.actor_user_id AND f.status=''active''
))
BEGIN SELECT RAISE(ABORT,''request_log_query_event_owner_invalid''); END', '990840803c7e48284849f48f3cc9a16ec48d19a46745d52117daaa5545d1152f'),
('trg_request_log_query_events_rowid_insert_prd055', 'request_log_query_events', 'CREATE TRIGGER trg_request_log_query_events_rowid_insert_prd055
AFTER INSERT ON request_log_query_events FOR EACH ROW WHEN NEW.rowid<0
BEGIN SELECT RAISE(ABORT,''request_log_query_event_immutable''); END', 'ba81202fd8aaf46ac61d374d26394412adbbb3e3d06ef6dc3d3a0a9031fe7a52'),
('trg_request_log_query_events_state_insert_prd055', 'request_log_query_events', 'CREATE TRIGGER trg_request_log_query_events_state_insert_prd055
BEFORE INSERT ON request_log_query_events FOR EACH ROW
WHEN NOT (
  NEW.event_dispatch_status=''pending'' AND NEW.event_dispatch_attempts=0
  AND NEW.event_next_attempt_at=NEW.created_at
  AND NEW.event_dispatched_at IS NULL AND NEW.event_claim_token IS NULL
  AND NEW.event_lease_owner_id IS NULL AND NEW.event_lease_expires_at IS NULL
  AND NEW.event_last_error_code IS NULL
  AND NEW.executed_at=NEW.created_at AND NEW.updated_at=NEW.created_at
)
BEGIN SELECT RAISE(ABORT,''request_log_query_event_state_invalid''); END', '97b70ea959bd3bfbdfe603c1b41133519b6c36f3a3f6ee2305ac556a1d4c344c'),
('trg_request_log_query_events_state_update_prd055', 'request_log_query_events', 'CREATE TRIGGER trg_request_log_query_events_state_update_prd055
BEFORE UPDATE ON request_log_query_events FOR EACH ROW
WHEN NOT (
  NEW.rowid=OLD.rowid AND NEW.query_event_id=OLD.query_event_id AND NEW.event_id=OLD.event_id
  AND NEW.tenant_id=OLD.tenant_id AND NEW.actor_user_id=OLD.actor_user_id
  AND NEW.actor_session_id=OLD.actor_session_id AND NEW.filter_version=OLD.filter_version
  AND NEW.filter_fingerprint=OLD.filter_fingerprint AND NEW.filter_keys_json=OLD.filter_keys_json
  AND NEW.saved_filter_id IS OLD.saved_filter_id AND NEW.sort_by=OLD.sort_by
  AND NEW.sort_direction=OLD.sort_direction AND NEW.query_limit=OLD.query_limit
  AND NEW.query_offset=OLD.query_offset AND NEW.matched_count=OLD.matched_count
  AND NEW.returned_count=OLD.returned_count AND NEW.has_more=OLD.has_more
  AND NEW.query_duration_ms=OLD.query_duration_ms
  AND NEW.operation_request_id=OLD.operation_request_id AND NEW.operation_trace_id=OLD.operation_trace_id
  AND NEW.executed_at=OLD.executed_at AND NEW.created_at=OLD.created_at
  AND unixepoch(NEW.updated_at)>unixepoch(OLD.updated_at)
  AND (
    (OLD.event_dispatch_status=''pending'' AND NEW.event_dispatch_status=''processing''
      AND OLD.event_dispatch_attempts BETWEEN 0 AND 9
      AND unixepoch(OLD.event_next_attempt_at)<=unixepoch(NEW.updated_at)
      AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts+1
      AND NEW.event_next_attempt_at IS NULL AND NEW.event_dispatched_at IS NULL
      AND length(NEW.event_claim_token) BETWEEN 16 AND 128
      AND length(NEW.event_lease_owner_id) BETWEEN 1 AND 128
      AND unixepoch(NEW.event_lease_expires_at)>unixepoch(NEW.updated_at)
      AND NEW.event_last_error_code IS NULL)
    OR (OLD.event_dispatch_status=''processing'' AND NEW.event_dispatch_status=''processing''
      AND OLD.event_dispatch_attempts BETWEEN 1 AND 9
      AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts+1
      AND unixepoch(OLD.event_lease_expires_at)<=unixepoch(NEW.updated_at)
      AND NEW.event_next_attempt_at IS NULL AND NEW.event_dispatched_at IS NULL
      AND length(NEW.event_claim_token) BETWEEN 16 AND 128
      AND length(NEW.event_lease_owner_id) BETWEEN 1 AND 128
      AND unixepoch(NEW.event_lease_expires_at)>unixepoch(NEW.updated_at)
      AND NEW.event_last_error_code IS NULL)
    OR (OLD.event_dispatch_status=''processing'' AND NEW.event_dispatch_status=''dispatched''
      AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts
      AND unixepoch(OLD.event_lease_expires_at)>unixepoch(NEW.updated_at)
      AND NEW.event_dispatched_at=NEW.updated_at AND NEW.event_next_attempt_at IS NULL
      AND NEW.event_claim_token IS NULL AND NEW.event_lease_owner_id IS NULL
      AND NEW.event_lease_expires_at IS NULL AND NEW.event_last_error_code IS NULL)
    OR (OLD.event_dispatch_status=''processing'' AND NEW.event_dispatch_status=''pending''
      AND OLD.event_dispatch_attempts BETWEEN 1 AND 9
      AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts
      AND unixepoch(OLD.event_lease_expires_at)>unixepoch(NEW.updated_at)
      AND unixepoch(NEW.event_next_attempt_at)>unixepoch(NEW.updated_at)
      AND NEW.event_dispatched_at IS NULL AND NEW.event_claim_token IS NULL
      AND NEW.event_lease_owner_id IS NULL AND NEW.event_lease_expires_at IS NULL
      AND NEW.event_last_error_code IS NOT NULL)
    OR (OLD.event_dispatch_status=''processing'' AND NEW.event_dispatch_status=''failed''
      AND OLD.event_dispatch_attempts=10 AND NEW.event_dispatch_attempts=10
      AND NEW.event_next_attempt_at IS NULL AND NEW.event_dispatched_at IS NULL
      AND NEW.event_claim_token IS NULL AND NEW.event_lease_owner_id IS NULL
      AND NEW.event_lease_expires_at IS NULL AND NEW.event_last_error_code IS NOT NULL)
  )
)
BEGIN SELECT RAISE(ABORT,''request_log_query_event_immutable''); END', '6b1fb2d43eaabdb0732f50c5d25e2f0b2d69a68680bbec0a185d42b41830d7ba'),
('trg_request_log_feedback_parent_conflict_insert_prd049', 'request_logs', 'CREATE TRIGGER trg_request_log_feedback_parent_conflict_insert_prd049
BEFORE INSERT ON request_logs FOR EACH ROW
WHEN EXISTS (
  SELECT 1 FROM request_logs current
  JOIN request_feedbacks feedback
    ON feedback.tenant_id=current.tenant_id
   AND feedback.source_request_id=current.request_id
  WHERE current.tenant_id=NEW.tenant_id AND current.request_id=NEW.request_id
    AND (current.virtual_key_id IS NOT NEW.virtual_key_id
      OR current.status IS NOT NEW.status OR current.model_id IS NOT NEW.model_id
      OR current.provider_id IS NOT NEW.provider_id OR current.project_id IS NOT NEW.project_id
      OR current.application_id IS NOT NEW.application_id
      OR current.environment_id IS NOT NEW.environment_id
      OR current.stream_session_id IS NOT NEW.stream_session_id
      OR current.stream_status IS NOT NEW.stream_status
      OR current.final_routing_attempt_id IS NOT NEW.final_routing_attempt_id
      OR current.routing_attempt_count IS NOT NEW.routing_attempt_count)
)
BEGIN SELECT RAISE(ABORT,''request_log_feedback_parent_immutable''); END', '63734e728696ee4ba24d3e63f7a4235c7cf6db821f13a34c6eb1ec96c263a49f'),
('trg_request_log_feedback_parent_conflict_update_prd049', 'request_logs', 'CREATE TRIGGER trg_request_log_feedback_parent_conflict_update_prd049
BEFORE UPDATE OF tenant_id, request_id ON request_logs
FOR EACH ROW
WHEN EXISTS (
  SELECT 1
  FROM request_logs target
  JOIN request_feedbacks feedback
    ON feedback.tenant_id=target.tenant_id
   AND feedback.source_request_id=target.request_id
  WHERE target.tenant_id=NEW.tenant_id
    AND target.request_id=NEW.request_id
    AND target.rowid != OLD.rowid
)
BEGIN
  SELECT RAISE(ABORT, ''request_log_feedback_parent_immutable'');
END', '1ad5f0c1aa3f141779d5b23f5933422917d4d494de945b31f6aa1600e1d18efb'),
('trg_request_log_feedback_parent_delete_prd049', 'request_logs', 'CREATE TRIGGER trg_request_log_feedback_parent_delete_prd049
BEFORE DELETE ON request_logs
FOR EACH ROW
WHEN EXISTS (
  SELECT 1 FROM request_feedbacks feedback
  WHERE feedback.tenant_id=OLD.tenant_id AND feedback.source_request_id=OLD.request_id
)
BEGIN
  SELECT RAISE(ABORT, ''request_log_feedback_parent_immutable'');
