END', '3aba596ba818e0f27fb633eb5c459256c9a979c33ff3cba3e2aae2bcacb68aaa'),
('trg_request_logs_claim_update', 'request_logs', 'CREATE TRIGGER trg_request_logs_claim_update
BEFORE UPDATE OF tenant_id, request_id, trace_id, virtual_key_id,
  snapshot_version, policy_snapshot_status
