BEFORE UPDATE ON response_cache_entry_tags FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''response_cache_entry_tag_immutable''); END', '6e5ae976e8bea77c84f57f9ef104f7dfb99e3d88add406ef39cc86d183b4fa71'),
('trg_response_cache_event_outbox_delete_prd076', 'response_cache_event_outbox', 'CREATE TRIGGER trg_response_cache_event_outbox_delete_prd076
BEFORE DELETE ON response_cache_event_outbox FOR EACH ROW
