)
BEGIN SELECT RAISE(ABORT,''response_cache_fill_tag_immutable''); END', '36f69c08696ed67e909177c1914bb18c27a6d36848f332726e0355655e67ef29'),
('trg_response_cache_fill_tags_owner_insert_prd076', 'response_cache_fill_tags', 'CREATE TRIGGER trg_response_cache_fill_tags_owner_insert_prd076
BEFORE INSERT ON response_cache_fill_tags FOR EACH ROW
WHEN NOT EXISTS(
    SELECT 1 FROM response_cache_fill_leases lease
    WHERE lease.tenant_id=NEW.tenant_id
      AND lease.response_cache_fill_lease_id=NEW.response_cache_fill_lease_id
      AND lease.hmac_key_version=NEW.hmac_key_version
  )
  OR NOT EXISTS(
    SELECT 1 FROM response_cache_tag_generations generation
    WHERE generation.tenant_id=NEW.tenant_id
      AND generation.hmac_key_version=NEW.hmac_key_version
      AND generation.tag_kind=NEW.tag_kind
      AND generation.tag_digest=NEW.tag_digest
      AND generation.generation=NEW.expected_generation
  )
BEGIN SELECT RAISE(ABORT,''response_cache_fill_tag_owner_mismatch''); END', '169f2917dcfca1c495836e3da50daa027f18eb9166110c42e13c8edc14efad33'),
('trg_response_cache_fill_tags_update_prd076', 'response_cache_fill_tags', 'CREATE TRIGGER trg_response_cache_fill_tags_update_prd076
