('trg_role_dashboard_configs_delete_prd065', 'role_dashboard_configs', 'CREATE TRIGGER trg_role_dashboard_configs_delete_prd065
BEFORE DELETE ON role_dashboard_configs FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''role_dashboard_config_immutable''); END', '9a391936301aa9daffb081db851aa9664d44aa2b3a82f89c52d18f2daf4ab5c7'),
('trg_role_dashboard_configs_insert_prd065', 'role_dashboard_configs', 'CREATE TRIGGER trg_role_dashboard_configs_insert_prd065
BEFORE INSERT ON role_dashboard_configs FOR EACH ROW
WHEN
  typeof(NEW.role_dashboard_config_id)!=''text''
  OR length(NEW.role_dashboard_config_id)!=36
  OR substr(NEW.role_dashboard_config_id,1,4)!=''rdc_''
  OR substr(NEW.role_dashboard_config_id,5) GLOB ''*[^0-9a-f]*''
  OR NEW.role_code NOT IN (
    ''admin'',''developer'',''viewer'',''finance_admin'',''security_admin'',''ops_admin''
  )
  OR NEW.default_view_code IS NOT CASE NEW.role_code
    WHEN ''admin'' THEN ''executive''
    WHEN ''developer'' THEN ''developer''
    WHEN ''viewer'' THEN ''executive''
    WHEN ''finance_admin'' THEN ''finance''
    WHEN ''security_admin'' THEN ''security''
    WHEN ''ops_admin'' THEN ''operations''
  END
  OR NEW.allowed_view_codes_json IS NOT CASE NEW.role_code
    WHEN ''admin'' THEN ''["executive","finance","security","developer","operations"]''
    WHEN ''developer'' THEN ''["developer","operations","executive"]''
    WHEN ''viewer'' THEN ''["executive"]''
    WHEN ''finance_admin'' THEN ''["finance","executive"]''
    WHEN ''security_admin'' THEN ''["security","executive"]''
    WHEN ''ops_admin'' THEN ''["operations","executive"]''
  END
  OR typeof(NEW.config_revision)!=''integer'' OR NEW.config_revision!=1
  OR NEW.status!=''active''
  OR NEW.created_at IS NOT NEW.updated_at
  OR EXISTS (
    SELECT 1 FROM role_dashboard_configs current
    WHERE current.role_dashboard_config_id=NEW.role_dashboard_config_id
       OR (current.tenant_id=NEW.tenant_id AND current.role_code=NEW.role_code)
       OR (NEW.rowid!=-1 AND current.rowid=NEW.rowid)
  )
BEGIN SELECT RAISE(ABORT,''role_dashboard_config_invalid''); END', 'd3653eaf3b5e995a24a00988bfa2010e04188e0d1cd33eb8d68d642e35d7b173'),
('trg_role_dashboard_configs_rowid_insert_prd065', 'role_dashboard_configs', 'CREATE TRIGGER trg_role_dashboard_configs_rowid_insert_prd065
AFTER INSERT ON role_dashboard_configs FOR EACH ROW WHEN NEW.rowid<0
BEGIN SELECT RAISE(ABORT,''role_dashboard_config_immutable''); END', 'c60e23839164ec3955cfb53c4032cefaed1fe539007a3e3e2f32ae7d3ac912c4'),
('trg_role_dashboard_configs_update_prd065', 'role_dashboard_configs', 'CREATE TRIGGER trg_role_dashboard_configs_update_prd065
BEFORE UPDATE ON role_dashboard_configs FOR EACH ROW
WHEN
  NEW.rowid!=OLD.rowid
  OR NEW.role_dashboard_config_id IS NOT OLD.role_dashboard_config_id
  OR NEW.tenant_id IS NOT OLD.tenant_id
  OR NEW.role_code IS NOT OLD.role_code
  OR NEW.created_at IS NOT OLD.created_at
  OR typeof(NEW.config_revision)!=''integer''
  OR NEW.config_revision!=OLD.config_revision+1
  OR unixepoch(NEW.updated_at)<=unixepoch(OLD.updated_at)
  OR (
    NEW.default_view_code IS OLD.default_view_code
    AND NEW.allowed_view_codes_json IS OLD.allowed_view_codes_json
    AND NEW.status IS OLD.status
  )
  OR CASE
    WHEN json_valid(NEW.allowed_view_codes_json) THEN CASE
      WHEN json_type(NEW.allowed_view_codes_json)=''array''
        AND json_array_length(NEW.allowed_view_codes_json) BETWEEN 1 AND 5
      THEN
        EXISTS (
          SELECT 1 FROM json_each(NEW.allowed_view_codes_json) item
          WHERE item.type!=''text''
             OR item.value NOT IN (
               ''executive'',''finance'',''security'',''developer'',''operations''
             )
        )
        OR (SELECT COUNT(*) FROM json_each(NEW.allowed_view_codes_json))
           !=(SELECT COUNT(DISTINCT value)
              FROM json_each(NEW.allowed_view_codes_json))
        OR NOT EXISTS (
          SELECT 1 FROM json_each(NEW.allowed_view_codes_json) item
          WHERE item.type=''text'' AND item.value=NEW.default_view_code
        )
      ELSE 1
    END
    ELSE 1
  END
BEGIN SELECT RAISE(ABORT,''role_dashboard_config_invalid''); END', '5c62acaf3a7dc787846f2c32ff968f1dd78435c12489150ab6028f4bb215a2e5'),
('trg_role_permission_events_delete_prd059', 'role_permission_events', 'CREATE TRIGGER trg_role_permission_events_delete_prd059
BEFORE DELETE ON role_permission_events FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''rbac_role_permission_event_immutable''); END', '0d1a743f2886b6b1e7ccb199a55a1acdbd6d31c88760efb336efcbbf0dbcfa73'),
('trg_role_permission_events_owner_insert_prd059', 'role_permission_events', 'CREATE TRIGGER trg_role_permission_events_owner_insert_prd059
BEFORE INSERT ON role_permission_events FOR EACH ROW
WHEN NOT EXISTS (
  SELECT 1 FROM roles role
  WHERE role.tenant_id=NEW.tenant_id AND role.role_id=NEW.role_id
    AND role.code!=''admin'' AND role.status=''active''
    AND role.permission_revision=NEW.after_revision
    AND role.matrix_sha256=NEW.after_sha256
)
OR NOT EXISTS (
  SELECT 1 FROM users actor
  WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.actor_user_id
    AND actor.status=''active'' AND actor.role=NEW.actor_role
)
OR NOT EXISTS (
  SELECT 1 FROM audit_logs audit
  WHERE audit.tenant_id=NEW.tenant_id AND audit.audit_log_id=NEW.audit_log_id
    AND audit.actor_user_id=NEW.actor_user_id AND audit.actor_role=NEW.actor_role
    AND audit.action=''role.permission_changed''
    AND audit.object_type=''role_permission'' AND audit.object_id=NEW.role_id
    AND audit.request_id=NEW.request_id AND audit.trace_id=NEW.trace_id
    AND audit.created_at=NEW.created_at
    AND json_extract(audit.before_summary_json,''$.permission_revision'')=NEW.before_revision
    AND json_extract(audit.before_summary_json,''$.matrix_sha256'')=NEW.before_sha256
    AND json_extract(audit.after_summary_json,''$.permission_revision'')=NEW.after_revision
    AND json_extract(audit.after_summary_json,''$.matrix_sha256'')=NEW.after_sha256
    AND json_extract(audit.after_summary_json,''$.permission_count'')=(
      SELECT COUNT(*) FROM role_permissions relation
      WHERE relation.tenant_id=NEW.tenant_id AND relation.role_id=NEW.role_id
    )
    AND json_extract(audit.before_summary_json,''$.permission_count'')=(
      SELECT COUNT(*) FROM role_permissions relation
      WHERE relation.tenant_id=NEW.tenant_id AND relation.role_id=NEW.role_id
    )-(SELECT COUNT(*) FROM json_each(NEW.added_permissions_json))
     +(SELECT COUNT(*) FROM json_each(NEW.removed_permissions_json))
)
OR NEW.delivery_status!=''pending'' OR NEW.last_error_code IS NOT NULL
OR NEW.dispatched_at IS NOT NULL OR NEW.updated_at!=NEW.created_at
OR (SELECT COUNT(*) FROM json_each(NEW.added_permissions_json))
  +(SELECT COUNT(*) FROM json_each(NEW.removed_permissions_json))=0
OR EXISTS (
  SELECT 1 FROM json_each(NEW.added_permissions_json) item
  WHERE item.type!=''text''
    OR NOT EXISTS (
      SELECT 1
      FROM rbac_role_permission_templates role_template
      JOIN roles role ON role.code=role_template.role_code
      WHERE role.tenant_id=NEW.tenant_id AND role.role_id=NEW.role_id
        AND role_template.permission_code=item.value
    )
    OR NOT EXISTS (
      SELECT 1
      FROM role_permissions relation
      JOIN permissions permission
        ON permission.tenant_id=relation.tenant_id
       AND permission.permission_id=relation.permission_id
      WHERE relation.tenant_id=NEW.tenant_id AND relation.role_id=NEW.role_id
        AND permission.code=item.value
    )
)
OR EXISTS (
  SELECT 1 FROM json_each(NEW.removed_permissions_json) item
  WHERE item.type!=''text''
    OR NOT EXISTS (
      SELECT 1
      FROM rbac_role_permission_templates role_template
      JOIN roles role ON role.code=role_template.role_code
      WHERE role.tenant_id=NEW.tenant_id AND role.role_id=NEW.role_id
        AND role_template.permission_code=item.value
    )
    OR EXISTS (
      SELECT 1
      FROM role_permissions relation
      JOIN permissions permission
        ON permission.tenant_id=relation.tenant_id
       AND permission.permission_id=relation.permission_id
      WHERE relation.tenant_id=NEW.tenant_id AND relation.role_id=NEW.role_id
        AND permission.code=item.value
    )
)
OR (SELECT COUNT(*) FROM json_each(NEW.added_permissions_json))
  !=(SELECT COUNT(DISTINCT value) FROM json_each(NEW.added_permissions_json))
OR (SELECT COUNT(*) FROM json_each(NEW.removed_permissions_json))
  !=(SELECT COUNT(DISTINCT value) FROM json_each(NEW.removed_permissions_json))
OR EXISTS (
  SELECT 1 FROM json_each(NEW.added_permissions_json) added
  JOIN json_each(NEW.removed_permissions_json) removed ON removed.value=added.value
)
OR EXISTS (
  SELECT 1 FROM json_each(NEW.added_permissions_json) item
  JOIN json_each(NEW.added_permissions_json) next ON next.key=item.key+1
  WHERE CAST(item.value AS TEXT)>=CAST(next.value AS TEXT)
)
OR EXISTS (
  SELECT 1 FROM json_each(NEW.removed_permissions_json) item
  JOIN json_each(NEW.removed_permissions_json) next ON next.key=item.key+1
  WHERE CAST(item.value AS TEXT)>=CAST(next.value AS TEXT)
)
OR (SELECT COUNT(*) FROM json_each(NEW.payload_json))!=9
OR EXISTS (
  SELECT 1 FROM json_each(NEW.payload_json) field
  WHERE field.key NOT IN (
    ''schema_version'',''role_id'',''role_code'',''before_revision'',''after_revision'',
    ''before_sha256'',''after_sha256'',''added_permissions'',''removed_permissions''
  )
)
OR json_extract(NEW.payload_json,''$.schema_version'')!=1
OR json_extract(NEW.payload_json,''$.role_id'')!=NEW.role_id
OR json_extract(NEW.payload_json,''$.before_revision'')!=NEW.before_revision
OR json_extract(NEW.payload_json,''$.after_revision'')!=NEW.after_revision
OR json_extract(NEW.payload_json,''$.before_sha256'')!=NEW.before_sha256
OR json_extract(NEW.payload_json,''$.after_sha256'')!=NEW.after_sha256
OR json(json_extract(NEW.payload_json,''$.added_permissions''))
  !=json(NEW.added_permissions_json)
OR json(json_extract(NEW.payload_json,''$.removed_permissions''))
  !=json(NEW.removed_permissions_json)
OR NOT EXISTS (
  SELECT 1 FROM roles role
  WHERE role.tenant_id=NEW.tenant_id AND role.role_id=NEW.role_id
    AND role.code=json_extract(NEW.payload_json,''$.role_code'')
)
OR EXISTS (
  SELECT 1 FROM role_permission_events current
  WHERE current.event_id=NEW.event_id
     OR (current.tenant_id=NEW.tenant_id AND current.actor_user_id=NEW.actor_user_id
         AND current.request_id=NEW.request_id)
     OR (NEW.rowid!=-1 AND current.rowid=NEW.rowid)
)
BEGIN SELECT RAISE(ABORT,''rbac_role_permission_event_invalid''); END', 'fc5ec7dd568d1df6da8703bdff0b15afb72cfc1c2569b728d3e78706b7b58f67'),
('trg_role_permission_events_rowid_insert_prd059', 'role_permission_events', 'CREATE TRIGGER trg_role_permission_events_rowid_insert_prd059
AFTER INSERT ON role_permission_events FOR EACH ROW WHEN NEW.rowid<0
BEGIN SELECT RAISE(ABORT,''rbac_role_permission_event_immutable''); END', '8e4c3fa0b37ac86b318fa510e01a2ee6696a757e74e33d6ce3dc2366bf3da4e9'),
('trg_role_permission_events_state_update_prd059', 'role_permission_events', 'CREATE TRIGGER trg_role_permission_events_state_update_prd059
BEFORE UPDATE ON role_permission_events FOR EACH ROW
WHEN NOT (
  OLD.delivery_status=''pending''
  AND NEW.delivery_status IN (''dispatched'',''failed'')
  AND NEW.event_id=OLD.event_id AND NEW.tenant_id=OLD.tenant_id
  AND NEW.role_id=OLD.role_id AND NEW.actor_user_id=OLD.actor_user_id
  AND NEW.actor_role=OLD.actor_role AND NEW.request_id=OLD.request_id
  AND NEW.before_revision=OLD.before_revision AND NEW.after_revision=OLD.after_revision
  AND NEW.before_sha256=OLD.before_sha256 AND NEW.after_sha256=OLD.after_sha256
  AND NEW.added_permissions_json=OLD.added_permissions_json
  AND NEW.removed_permissions_json=OLD.removed_permissions_json
  AND NEW.audit_log_id=OLD.audit_log_id AND NEW.trace_id=OLD.trace_id
  AND NEW.payload_json=OLD.payload_json AND NEW.created_at=OLD.created_at
  AND NEW.dispatched_at=NEW.updated_at
  AND unixepoch(NEW.updated_at)>=unixepoch(OLD.updated_at)
  AND (
    (NEW.delivery_status=''dispatched'' AND NEW.last_error_code IS NULL)
    OR
    (NEW.delivery_status=''failed''
      AND NEW.last_error_code=''webhook.delivery_unavailable'')
  )
)
BEGIN SELECT RAISE(ABORT,''rbac_role_permission_event_immutable''); END', '9e0bfba9fc6675b1d38d5da43b2cc52a526dafe5e77be35843bf60bfddb7a7dc'),
('trg_role_permissions_delete_prd059', 'role_permissions', 'CREATE TRIGGER trg_role_permissions_delete_prd059 BEFORE DELETE ON role_permissions FOR EACH ROW WHEN EXISTS(SELECT 1 FROM roles r WHERE r.tenant_id=OLD.tenant_id AND r.role_id=OLD.role_id AND r.code=''admin'') BEGIN SELECT RAISE(ABORT,''rbac_role_permission_immutable''); END', '3c8f673f17176a5db16d017fc6e738344ffbe6997f013af0c0b812e8f3ac06f7'),
('trg_role_permissions_owner_insert_prd059', 'role_permissions', 'CREATE TRIGGER trg_role_permissions_owner_insert_prd059 BEFORE INSERT ON role_permissions FOR EACH ROW WHEN NOT EXISTS(SELECT 1 FROM roles r JOIN permissions p ON p.tenant_id=r.tenant_id JOIN rbac_role_permission_templates t ON t.role_code=r.code AND t.permission_code=p.code WHERE r.tenant_id=NEW.tenant_id AND r.role_id=NEW.role_id AND r.status=''active'' AND p.permission_id=NEW.permission_id AND p.status=''active'') OR EXISTS(SELECT 1 FROM role_permissions x WHERE x.role_permission_id=NEW.role_permission_id OR(x.tenant_id=NEW.tenant_id AND x.role_id=NEW.role_id AND x.permission_id=NEW.permission_id) OR(NEW.rowid!=-1 AND x.rowid=NEW.rowid)) BEGIN SELECT RAISE(ABORT,''rbac_role_permission_owner_mismatch''); END', '2b7be74f662839c5963d0da393e21fa8ffb7655b53bd6adbe7c0e8f77ff84e63'),
('trg_role_permissions_rowid_insert_prd059', 'role_permissions', 'CREATE TRIGGER trg_role_permissions_rowid_insert_prd059
AFTER INSERT ON role_permissions FOR EACH ROW WHEN NEW.rowid<0
BEGIN SELECT RAISE(ABORT,''rbac_role_permission_immutable''); END', '0b2cb1fb338efa1544d99134b3502fef517cf569dd416335db79994f5802e1e7'),
