('trg_roles_matrix_update_prd059', 'roles', 'CREATE TRIGGER trg_roles_matrix_update_prd059 BEFORE UPDATE ON roles FOR EACH ROW WHEN OLD.code=''admin'' OR NEW.rowid!=OLD.rowid OR NEW.role_id!=OLD.role_id OR NEW.tenant_id!=OLD.tenant_id OR NEW.code!=OLD.code OR NEW.name!=OLD.name OR NEW.description!=OLD.description OR NEW.status!=OLD.status OR NEW.created_at!=OLD.created_at OR NEW.is_permission_immutable!=OLD.is_permission_immutable OR NEW.permission_revision!=OLD.permission_revision+1 OR NEW.matrix_sha256=OLD.matrix_sha256 OR length(NEW.matrix_sha256)!=64 OR NEW.matrix_sha256 GLOB ''*[^0-9a-f]*'' BEGIN SELECT RAISE(ABORT,''rbac_role_immutable''); END', 'bd1defd46583fd95b4d633a26c08729e2680976923c4068cadab6ac53fc441c7'),
('trg_roles_owner_insert_prd059', 'roles', 'CREATE TRIGGER trg_roles_owner_insert_prd059 BEFORE INSERT ON roles FOR EACH ROW WHEN NOT EXISTS(SELECT 1 FROM tenants WHERE tenant_id=NEW.tenant_id) OR NEW.code NOT IN(''admin'',''developer'',''viewer'',''finance_admin'',''security_admin'',''ops_admin'') OR NEW.permission_revision!=1 OR NEW.matrix_sha256!=CASE NEW.code WHEN ''admin'' THEN ''eb48d3c3fddfa76477ae5af3943449253af0581da445e3d5695f893258dba6b8'' WHEN ''developer'' THEN ''888796e8f30b282353452e012ba5132476a59ffb2509eded4cb44d8e8de5b686'' WHEN ''viewer'' THEN ''be55018029cd884b139e7e919a0f7052a94c8ca1ae5120fcb499e1b8754837af'' WHEN ''finance_admin'' THEN ''843de9cd51726438ebf668ab413a126b31c429a26b7ee306a394bca4435764fc'' WHEN ''security_admin'' THEN ''7bece4007f6bb8affcfa72d1db73ddc12b71d4bb85f874ad440736e63e596dbb'' WHEN ''ops_admin'' THEN ''bdab5bcae4741701f7171d1f08624f71306963dea15e99ccbde55028df2e6426'' END OR NEW.is_permission_immutable!=CASE WHEN NEW.code=''admin'' THEN 1 ELSE 0 END BEGIN SELECT RAISE(ABORT,''rbac_role_immutable''); END', '06116e48a3d2e98f196d1415f17ab8db5db49592ec97db1aaa87781954cab3fc'),
('trg_roles_rowid_insert_prd059', 'roles', 'CREATE TRIGGER trg_roles_rowid_insert_prd059
AFTER INSERT ON roles FOR EACH ROW WHEN NEW.rowid<0
BEGIN SELECT RAISE(ABORT,''rbac_role_immutable''); END', 'b2883b952217f97815a1696d9047b221ed319fe3bb00a5827440c871a5d9737f'),
('trg_routing_attempt_feedback_parent_conflict_insert_prd049', 'routing_attempts', 'CREATE TRIGGER trg_routing_attempt_feedback_parent_conflict_insert_prd049
BEFORE INSERT ON routing_attempts
FOR EACH ROW
WHEN EXISTS (
  SELECT 1
  FROM routing_attempts target
  JOIN request_logs request
    ON request.tenant_id=target.tenant_id
   AND request.request_id=target.request_id
   AND request.final_routing_attempt_id=target.routing_attempt_id
  JOIN request_feedbacks feedback
    ON feedback.tenant_id=request.tenant_id
   AND feedback.source_request_id=request.request_id
  WHERE target.routing_attempt_id=NEW.routing_attempt_id
     OR (
       target.tenant_id=NEW.tenant_id
       AND target.request_id=NEW.request_id
       AND target.attempt_sequence=NEW.attempt_sequence
     )
)
BEGIN
  SELECT RAISE(ABORT, ''routing_attempt_feedback_parent_immutable'');
END', '466fef94a81e218598a5756b19069ae255f2b90fdd1f2ae03b05f0cd151a4f38'),
('trg_routing_attempt_feedback_parent_conflict_update_prd049', 'routing_attempts', 'CREATE TRIGGER trg_routing_attempt_feedback_parent_conflict_update_prd049
BEFORE UPDATE OF routing_attempt_id, tenant_id, request_id, attempt_sequence ON routing_attempts
FOR EACH ROW
WHEN EXISTS (
  SELECT 1
  FROM routing_attempts target
  JOIN request_logs request
    ON request.tenant_id=target.tenant_id
   AND request.request_id=target.request_id
   AND request.final_routing_attempt_id=target.routing_attempt_id
  JOIN request_feedbacks feedback
    ON feedback.tenant_id=request.tenant_id
   AND feedback.source_request_id=request.request_id
  WHERE target.rowid != OLD.rowid
    AND (
      target.routing_attempt_id=NEW.routing_attempt_id
      OR (
        target.tenant_id=NEW.tenant_id
        AND target.request_id=NEW.request_id
        AND target.attempt_sequence=NEW.attempt_sequence
      )
    )
)
BEGIN
  SELECT RAISE(ABORT, ''routing_attempt_feedback_parent_immutable'');
END', '9c77686f87cc470459e5657bc867120e06aa0c31439d31b80b30f0bea9bcb038'),
('trg_routing_attempt_feedback_parent_delete_prd049', 'routing_attempts', 'CREATE TRIGGER trg_routing_attempt_feedback_parent_delete_prd049
BEFORE DELETE ON routing_attempts
FOR EACH ROW
WHEN EXISTS (
  SELECT 1
  FROM request_feedbacks feedback
  JOIN request_logs request
    ON request.tenant_id=feedback.tenant_id
   AND request.request_id=feedback.source_request_id
  WHERE request.final_routing_attempt_id=OLD.routing_attempt_id
    AND OLD.tenant_id=request.tenant_id
    AND OLD.request_id=request.request_id
)
BEGIN
  SELECT RAISE(ABORT, ''routing_attempt_feedback_parent_immutable'');
END', '48ffcc12a3bc2eeae70f2dd9fdde728e9fd724f8f648f63a401f79df7850d3dc'),
('trg_routing_attempt_feedback_parent_update_prd049', 'routing_attempts', 'CREATE TRIGGER trg_routing_attempt_feedback_parent_update_prd049
BEFORE UPDATE OF routing_attempt_id, tenant_id, request_id, status, model_id, provider_id
ON routing_attempts
FOR EACH ROW
WHEN EXISTS (
  SELECT 1
  FROM request_feedbacks feedback
  JOIN request_logs request
    ON request.tenant_id=feedback.tenant_id
   AND request.request_id=feedback.source_request_id
  WHERE request.final_routing_attempt_id=OLD.routing_attempt_id
    AND OLD.tenant_id=request.tenant_id
    AND OLD.request_id=request.request_id
)
AND (
  NEW.routing_attempt_id IS NOT OLD.routing_attempt_id
  OR NEW.tenant_id IS NOT OLD.tenant_id
  OR NEW.request_id IS NOT OLD.request_id
  OR NEW.status IS NOT OLD.status
  OR NEW.model_id IS NOT OLD.model_id
  OR NEW.provider_id IS NOT OLD.provider_id
)
BEGIN
  SELECT RAISE(ABORT, ''routing_attempt_feedback_parent_immutable'');
END', '413eba7af0997ccc4bfa7a76c3abefa80154d634907d1e2f2ed64530c0983d18'),
('trg_routing_attempt_local_event_prd084', 'routing_attempts', 'CREATE TRIGGER trg_routing_attempt_local_event_prd084
AFTER UPDATE OF status ON routing_attempts FOR EACH ROW
WHEN OLD.status=''started'' AND NEW.status IN(''succeeded'',''failed'')
  AND NEW.provider_call_status=''called''
  AND EXISTS(SELECT 1 FROM providers provider
    WHERE provider.tenant_id=NEW.tenant_id AND provider.provider_id=NEW.provider_id
      AND provider.provider_type=''local_endpoint'')
BEGIN
  INSERT INTO local_model_call_events(
    local_model_call_event_id,tenant_id,request_id,trace_id,routing_attempt_id,
    local_endpoint_id,provider_id,model_id,attempt_sequence,attempt_role,
    execution_status,outcome,error_code,error_category,http_status,retryable,
    latency_ms,usage_status,completed_at
  )
  SELECT ''lmce_''||substr(metahub_sha256(NEW.routing_attempt_id),1,32),
    NEW.tenant_id,NEW.request_id,NEW.trace_id,NEW.routing_attempt_id,
    endpoint.local_endpoint_id,NEW.provider_id,NEW.model_id,
    NEW.attempt_sequence,NEW.attempt_role,''called'',
    CASE WHEN NEW.error_code=''gateway.local_endpoint_outcome_unknown''
      THEN ''outcome_unknown'' ELSE NEW.status END,NEW.error_code,
    NEW.error_category,NEW.upstream_http_status,NEW.retryable,NEW.latency_ms,
    NEW.usage_status,NEW.completed_at
  FROM local_model_endpoints endpoint
  WHERE endpoint.tenant_id=NEW.tenant_id AND endpoint.provider_id=NEW.provider_id;
END', '893dbc0d32057eccf2409f6319c0e53cf1e5780a5423d9259d6e2593fd5b61c0'),
('trg_routing_attempt_local_fence_update_prd084', 'routing_attempts', 'CREATE TRIGGER trg_routing_attempt_local_fence_update_prd084
BEFORE UPDATE ON routing_attempts FOR EACH ROW
WHEN(
    EXISTS(SELECT 1 FROM providers provider
      WHERE provider.tenant_id=OLD.tenant_id AND provider.provider_id=OLD.provider_id
        AND provider.provider_type=''local_endpoint'')
    AND(NEW.rowid!=OLD.rowid OR NEW.routing_attempt_id!=OLD.routing_attempt_id
      OR NEW.tenant_id!=OLD.tenant_id OR NEW.request_id!=OLD.request_id
      OR NEW.trace_id!=OLD.trace_id OR NEW.model_alias_id IS NOT OLD.model_alias_id
      OR NEW.fallback_policy_id IS NOT OLD.fallback_policy_id
      OR NEW.fallback_policy_version IS NOT OLD.fallback_policy_version
      OR NEW.attempt_sequence!=OLD.attempt_sequence OR NEW.attempt_role!=OLD.attempt_role
      OR NEW.trigger_type!=OLD.trigger_type
      OR NEW.trigger_error_code IS NOT OLD.trigger_error_code
      OR NEW.model_id!=OLD.model_id OR NEW.internal_model_id!=OLD.internal_model_id
      OR NEW.provider_id!=OLD.provider_id OR NEW.provider_code!=OLD.provider_code
      OR(OLD.status=''started'' AND NEW.status=''failed''
        AND((NEW.provider_call_status=''called'' AND NEW.usage_status!=''unavailable'')
          OR(NEW.provider_call_status=''not_called''
            AND NEW.usage_status!=''not_applicable'')))
      OR NOT(
      (OLD.provider_call_status=''not_called''
        AND NEW.provider_call_status=''not_called''
        AND NEW.provider_call_started_at IS NULL)
      OR(OLD.provider_call_status=''not_called'' AND NEW.provider_call_status=''called''
        AND OLD.status=''started'' AND NEW.status=''started''
        AND OLD.provider_call_started_at IS NULL
        AND NEW.provider_call_started_at IS NOT NULL
        AND NEW.provider_call_started_at>=OLD.created_at)
      OR(OLD.provider_call_status=''called'' AND NEW.provider_call_status=''called''
        AND NEW.provider_call_started_at=OLD.provider_call_started_at)))
  )
  OR(
    NOT EXISTS(SELECT 1 FROM providers provider
      WHERE provider.tenant_id=OLD.tenant_id AND provider.provider_id=OLD.provider_id
        AND provider.provider_type=''local_endpoint'')
    AND(NEW.provider_call_status!=''not_applicable''
      OR NEW.provider_call_started_at IS NOT NULL))
BEGIN SELECT RAISE(ABORT,''routing_attempt_local_fence_invalid''); END', 'ac73f56319209fc4a0dfb2dafc7a8fc06c69de88c746422da2c9c2e3884bf44c'),
('trg_routing_attempt_local_owner_insert_prd084', 'routing_attempts', 'CREATE TRIGGER trg_routing_attempt_local_owner_insert_prd084
BEFORE INSERT ON routing_attempts FOR EACH ROW
WHEN(
    EXISTS(SELECT 1 FROM providers provider
      WHERE provider.tenant_id=NEW.tenant_id AND provider.provider_id=NEW.provider_id
        AND provider.provider_type=''local_endpoint'')
    AND(length(NEW.routing_attempt_id)!=36
      OR substr(NEW.routing_attempt_id,1,4)!=''rta_''
      OR substr(NEW.routing_attempt_id,5) GLOB ''*[^0-9a-f]*''
      OR NEW.status!=''started'' OR NEW.provider_call_status!=''not_called''
      OR NEW.provider_call_started_at IS NOT NULL
      OR NOT EXISTS(SELECT 1 FROM local_model_endpoints endpoint
        JOIN models model ON model.tenant_id=endpoint.tenant_id
          AND model.provider_id=endpoint.provider_id
        WHERE endpoint.tenant_id=NEW.tenant_id
          AND endpoint.provider_id=NEW.provider_id AND endpoint.status=''active''
          AND endpoint.local_endpoint_id IS NOT NULL AND model.model_id=NEW.model_id))
  )
  OR(
    NOT EXISTS(SELECT 1 FROM providers provider
      WHERE provider.tenant_id=NEW.tenant_id AND provider.provider_id=NEW.provider_id
        AND provider.provider_type=''local_endpoint'')
    AND(NEW.provider_call_status!=''not_applicable''
      OR NEW.provider_call_started_at IS NOT NULL))
BEGIN SELECT RAISE(ABORT,''routing_attempt_local_owner_mismatch''); END', 'e52800db7e484e0bfca9f73a8e645f24cf7d6d33b4785db19c034a76cddac0d8'),
('trg_routing_attempt_provider_error_fact_conflict_insert_prd056', 'routing_attempts', 'CREATE TRIGGER trg_routing_attempt_provider_error_fact_conflict_insert_prd056
BEFORE INSERT ON routing_attempts FOR EACH ROW
WHEN EXISTS (
  SELECT 1 FROM routing_attempts current
  JOIN provider_error_facts fact
    ON fact.tenant_id=current.tenant_id AND fact.routing_attempt_id=current.routing_attempt_id
  WHERE current.routing_attempt_id=NEW.routing_attempt_id
     OR (current.tenant_id=NEW.tenant_id AND current.request_id=NEW.request_id
         AND current.attempt_sequence=NEW.attempt_sequence)
     OR (NEW.rowid!=-1 AND current.rowid=NEW.rowid)
)
BEGIN SELECT RAISE(ABORT,''routing_attempt_provider_error_fact_immutable''); END', '1d9c6f95e9a176e0f1f7ccaedbaf1f2a515df852eeb7b808867ec604fc12c4f3'),
('trg_routing_attempt_provider_error_fact_delete_prd056', 'routing_attempts', 'CREATE TRIGGER trg_routing_attempt_provider_error_fact_delete_prd056
BEFORE DELETE ON routing_attempts FOR EACH ROW
WHEN EXISTS (
  SELECT 1 FROM provider_error_facts fact
  WHERE fact.tenant_id=OLD.tenant_id AND fact.routing_attempt_id=OLD.routing_attempt_id
)
BEGIN SELECT RAISE(ABORT,''routing_attempt_provider_error_fact_immutable''); END', 'd000ad8ddf1a81546806afd315d1904e282eb889adcbf5536e6a49cd82e661e2'),
('trg_routing_attempt_provider_error_fact_update_prd056', 'routing_attempts', 'CREATE TRIGGER trg_routing_attempt_provider_error_fact_update_prd056
BEFORE UPDATE ON routing_attempts FOR EACH ROW
WHEN EXISTS (
  SELECT 1 FROM provider_error_facts fact
  WHERE fact.tenant_id=OLD.tenant_id AND fact.routing_attempt_id=OLD.routing_attempt_id
)
AND (
  NEW.rowid IS NOT OLD.rowid
  OR NEW.routing_attempt_id IS NOT OLD.routing_attempt_id
  OR NEW.tenant_id IS NOT OLD.tenant_id OR NEW.request_id IS NOT OLD.request_id
  OR NEW.trace_id IS NOT OLD.trace_id OR NEW.model_alias_id IS NOT OLD.model_alias_id
  OR NEW.fallback_policy_id IS NOT OLD.fallback_policy_id
  OR NEW.fallback_policy_version IS NOT OLD.fallback_policy_version
  OR NEW.attempt_sequence IS NOT OLD.attempt_sequence OR NEW.attempt_role IS NOT OLD.attempt_role
  OR NEW.trigger_type IS NOT OLD.trigger_type OR NEW.trigger_error_code IS NOT OLD.trigger_error_code
  OR NEW.model_id IS NOT OLD.model_id OR NEW.internal_model_id IS NOT OLD.internal_model_id
  OR NEW.provider_id IS NOT OLD.provider_id OR NEW.provider_code IS NOT OLD.provider_code
  OR NEW.status IS NOT OLD.status OR NEW.error_code IS NOT OLD.error_code
  OR NEW.error_category IS NOT OLD.error_category
  OR NEW.upstream_http_status IS NOT OLD.upstream_http_status
  OR NEW.retryable IS NOT OLD.retryable OR NEW.latency_ms IS NOT OLD.latency_ms
  OR NEW.usage_status IS NOT OLD.usage_status OR NEW.usage_ledger_id IS NOT OLD.usage_ledger_id
  OR NEW.estimated_cost_cny IS NOT OLD.estimated_cost_cny
  OR NEW.created_at IS NOT OLD.created_at OR NEW.completed_at IS NOT OLD.completed_at
  OR NEW.updated_at IS NOT OLD.updated_at
)
BEGIN SELECT RAISE(ABORT,''routing_attempt_provider_error_fact_immutable''); END', 'be2ebd90ac32e66e0fb0916c95c2aae22567d1f5d77e76bbd0f45e2c75933ad1'),
('trg_routing_attempt_tenant_insert', 'routing_attempts', 'CREATE TRIGGER trg_routing_attempt_tenant_insert
BEFORE INSERT ON routing_attempts
FOR EACH ROW
BEGIN
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM models m
    WHERE m.model_id=NEW.model_id AND m.tenant_id=NEW.tenant_id
  ) THEN RAISE(ABORT, ''routing_attempt_model_tenant_mismatch'') END;
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM providers p
    WHERE p.provider_id=NEW.provider_id AND p.tenant_id=NEW.tenant_id
  ) THEN RAISE(ABORT, ''routing_attempt_provider_tenant_mismatch'') END;
  SELECT CASE WHEN NEW.model_alias_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM model_aliases a
    WHERE a.model_alias_id=NEW.model_alias_id AND a.tenant_id=NEW.tenant_id
  ) THEN RAISE(ABORT, ''routing_attempt_alias_tenant_mismatch'') END;
  SELECT CASE WHEN NEW.fallback_policy_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM fallback_policies fp
    WHERE fp.fallback_policy_id=NEW.fallback_policy_id AND fp.tenant_id=NEW.tenant_id
  ) THEN RAISE(ABORT, ''routing_attempt_policy_tenant_mismatch'') END;
END', 'cdbe90640953f81a6e1e54db42d4f4cc8402e66300ede03e82ce6a2ab80d40c8'),
('trg_routing_attempts_experiment_insert_prd075', 'routing_attempts', 'CREATE TRIGGER trg_routing_attempts_experiment_insert_prd075
BEFORE INSERT ON routing_attempts FOR EACH ROW
WHEN EXISTS(SELECT 1 FROM experiment_assignments assignment
    WHERE assignment.tenant_id=NEW.tenant_id AND assignment.request_id=NEW.request_id)
  AND NOT EXISTS(SELECT 1 FROM experiment_assignments assignment
    WHERE assignment.tenant_id=NEW.tenant_id AND assignment.request_id=NEW.request_id
      AND assignment.trace_id=NEW.trace_id AND assignment.model_id=NEW.model_id
      AND assignment.provider_id=NEW.provider_id AND assignment.provider_code=NEW.provider_code
      AND NEW.attempt_sequence=1 AND NEW.attempt_role=''primary''
      AND NEW.trigger_type=''initial'' AND NEW.fallback_policy_id IS NULL
      AND NEW.fallback_policy_version IS NULL)
BEGIN SELECT RAISE(ABORT,''experiment_attempt_owner_mismatch''); END', 'ee29a2e7bf24304b9f0016daf16605377308b9e846afad0dcdb7717ae33cf5cc'),
('trg_routing_attempts_experiment_update_prd075', 'routing_attempts', 'CREATE TRIGGER trg_routing_attempts_experiment_update_prd075
BEFORE UPDATE ON routing_attempts FOR EACH ROW
WHEN EXISTS(SELECT 1 FROM experiment_assignments assignment
