('trg_risk_acceptance_delete_prd137', 'security_risk_acceptances', 'CREATE TRIGGER trg_risk_acceptance_delete_prd137 BEFORE DELETE ON security_risk_acceptances
BEGIN SELECT RAISE(ABORT,''security_risk_acceptance_immutable''); END', 'b5b7ed8ad646a9bf69bcff8ff96d7f579edb44298de6013460e889106994582b'),
('trg_risk_acceptance_update_prd137', 'security_risk_acceptances', 'CREATE TRIGGER trg_risk_acceptance_update_prd137
BEFORE UPDATE ON security_risk_acceptances FOR EACH ROW
WHEN NEW.pen_test_finding_id!=OLD.pen_test_finding_id
  OR NEW.workspace_id!=OLD.workspace_id OR NEW.tenant_id!=OLD.tenant_id
  OR NEW.scope_sha256!=OLD.scope_sha256
  OR NEW.compensating_controls_json!=OLD.compensating_controls_json
  OR NEW.expires_at!=OLD.expires_at OR NEW.requested_at!=OLD.requested_at
  OR NEW.revision!=OLD.revision+1
  OR NOT((OLD.status=''pending_owner'' AND NEW.status=''pending_security'')
    OR(OLD.status=''pending_security'' AND NEW.status=''pending_platform'')
    OR(OLD.status=''pending_platform'' AND NEW.status IN(''active'',''revoked''))
    OR(OLD.status=''active'' AND NEW.status IN(''expired'',''revoked'')))
BEGIN SELECT RAISE(ABORT,''security_risk_acceptance_transition_invalid''); END', '4b039835fa27444c1bd4dc602c9ed34dd7cd2627ac0724ddd04fb5dab0ca4582'),
('trg_seed_runs_product_event_insert_prd085', 'seed_runs', 'CREATE TRIGGER trg_seed_runs_product_event_insert_prd085
AFTER INSERT ON seed_runs FOR EACH ROW
WHEN NEW.status=''applied'' AND NEW.tenant_id IS NOT NULL
BEGIN
  -- 新租户完成种子初始化后补齐唯一注册事实，不为重复种子生成第二条。
  INSERT INTO product_events(
    product_event_id,tenant_id,event_type,actor_user_id,source_kind,source_id,
    operation_request_id,operation_trace_id,capture_mode,status,
    occurred_at,created_at,updated_at)
  SELECT
    ''pev_''||substr(metahub_sha256(json_array(
      NEW.tenant_id,''tenant.registered'',''seed_run'',NEW.seed_run_id)),1,32),
    NEW.tenant_id,''tenant.registered'',NULL,''seed_run'',NEW.seed_run_id,NULL,NULL,
    ''backfill'',''recorded'',NEW.created_at,
    strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''),strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'')
  WHERE NOT EXISTS(SELECT 1 FROM product_events current
    WHERE current.tenant_id=NEW.tenant_id AND current.event_type=''tenant.registered'');
END', '988c669a002bda6bc2fd4ae37a57a877fd17c1d59fce0b81b0026fe5c3dbf09d'),
('trg_service_accounts_delete_prd118', 'service_accounts', 'CREATE TRIGGER trg_service_accounts_delete_prd118
BEFORE DELETE ON service_accounts
