('trg_service_accounts_update_prd118', 'service_accounts', 'CREATE TRIGGER trg_service_accounts_update_prd118
BEFORE UPDATE ON service_accounts FOR EACH ROW
WHEN NEW.service_account_id!=OLD.service_account_id
  OR NEW.workspace_id!=OLD.workspace_id OR NEW.tenant_id!=OLD.tenant_id
  OR NEW.name!=OLD.name OR NEW.display_name!=OLD.display_name
  OR NEW.scope_template!=OLD.scope_template OR NEW.catalog_revision!=OLD.catalog_revision
  OR NEW.constraint_sha256!=OLD.constraint_sha256
  OR NEW.ip_allowlist_json!=OLD.ip_allowlist_json
  OR NEW.mtls_fingerprint_sha256 IS NOT OLD.mtls_fingerprint_sha256
  OR NEW.token_ttl_seconds!=OLD.token_ttl_seconds
  OR NEW.created_by_account_id!=OLD.created_by_account_id OR NEW.created_at!=OLD.created_at
  OR NEW.revision NOT IN(OLD.revision,OLD.revision+1)
  OR NEW.constraint_generation NOT IN(OLD.constraint_generation,OLD.constraint_generation+1)
  OR (NEW.revision=OLD.revision AND NEW.constraint_generation!=OLD.constraint_generation)
  OR (NEW.revision=OLD.revision+1 AND NEW.constraint_generation!=OLD.constraint_generation+1)
  OR (NEW.revision=OLD.revision AND (NEW.status!=OLD.status
      OR NEW.updated_by_account_id!=OLD.updated_by_account_id
      OR NEW.revoked_at IS NOT OLD.revoked_at))
  OR (NEW.revision=OLD.revision+1 AND NOT(
      OLD.status IN(''active'',''disabled'') AND NEW.status=''revoked''
      AND OLD.revoked_at IS NULL AND NEW.revoked_at IS NOT NULL))
  OR (NEW.last_used_at IS NOT NULL AND OLD.last_used_at IS NOT NULL
      AND NEW.last_used_at<OLD.last_used_at)
  OR NEW.updated_at<OLD.updated_at
BEGIN SELECT RAISE(ABORT,''service_account_transition_invalid''); END', '5ceabe0fc61fc2af7e41a5eec97f4689c85d6c975a0dbbbc67157888f0e96269'),
('trg_session_risk_actions_delete_prd070', 'session_risk_actions', 'CREATE TRIGGER trg_session_risk_actions_delete_prd070
BEFORE DELETE ON session_risk_actions FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''session_risk_action_immutable''); END', 'de361bb1aa2a7e19355b5893a49c2a74a8687f2ea500219b6c1420fd4a53ab27'),
('trg_session_risk_actions_owner_insert_prd070', 'session_risk_actions', 'CREATE TRIGGER trg_session_risk_actions_owner_insert_prd070
BEFORE INSERT ON session_risk_actions FOR EACH ROW
WHEN NOT EXISTS (
  SELECT 1 FROM session_risk_scores score
  WHERE score.tenant_id=NEW.tenant_id
    AND score.session_risk_score_id=NEW.session_risk_score_id
    AND score.score=NEW.score_snapshot AND score.state_revision=NEW.state_revision
    AND score.status=NEW.status_after
)
  OR (NEW.session_risk_freeze_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM session_risk_freezes freeze
    WHERE freeze.tenant_id=NEW.tenant_id
      AND freeze.session_risk_freeze_id=NEW.session_risk_freeze_id
      AND freeze.source_session_risk_score_id=NEW.session_risk_score_id
      AND ((NEW.action IN (''freeze_session'',''release_session'')
          AND freeze.target_type=''session'')
        OR (NEW.action IN (''freeze_virtual_key'',''release_virtual_key'')
          AND freeze.target_type=''virtual_key''))
  ))
  OR (NEW.actor_type=''user'' AND NOT EXISTS (
    SELECT 1 FROM users actor
    WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.actor_id
      AND actor.status=''active''
  ))
  OR EXISTS (
    SELECT 1 FROM session_risk_actions current
    WHERE current.session_risk_action_id=NEW.session_risk_action_id
       OR (NEW.idempotency_key_digest IS NOT NULL
           AND current.tenant_id=NEW.tenant_id AND current.actor_id=NEW.actor_id
           AND current.digest_key_version=NEW.digest_key_version
           AND current.idempotency_key_digest=NEW.idempotency_key_digest
           -- BEGIN IMMEDIATE 串行化同库写入；只拒绝在 NEW.created_at 时仍有效的事实，
           -- 已过 24 小时的历史 action 保持 append-only，同时释放幂等键供新意图使用。
           AND julianday(current.idempotency_expires_at)>julianday(NEW.created_at))
       OR (NEW.rowid!=-1 AND current.rowid=NEW.rowid)
  )
BEGIN SELECT RAISE(ABORT,''session_risk_action_owner_mismatch''); END', '8fd6158613c9d4ef1902a32d6552e42424d23639b2ceac7d83ccd7411fc7fbd0'),
('trg_session_risk_actions_update_prd070', 'session_risk_actions', 'CREATE TRIGGER trg_session_risk_actions_update_prd070
BEFORE UPDATE ON session_risk_actions FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''session_risk_action_immutable''); END', 'e575b98b74ad7c9bb433c04a472cf8dda1185d2c477a2aab13360cf86737866b'),
('trg_session_risk_events_delete_prd070', 'session_risk_events', 'CREATE TRIGGER trg_session_risk_events_delete_prd070
BEFORE DELETE ON session_risk_events FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''session_risk_event_immutable''); END', '163b3a51eebf2da775901d86b421d5ea0ede134d4297c361230c868916d300e7'),
('trg_session_risk_events_owner_insert_prd070', 'session_risk_events', 'CREATE TRIGGER trg_session_risk_events_owner_insert_prd070
BEFORE INSERT ON session_risk_events FOR EACH ROW
WHEN NOT EXISTS (
  SELECT 1 FROM session_risk_scores score
  JOIN session_risk_actions action
    ON action.tenant_id=score.tenant_id
   AND action.session_risk_score_id=score.session_risk_score_id
  WHERE score.tenant_id=NEW.tenant_id
    AND score.session_risk_score_id=NEW.session_risk_score_id
    AND action.session_risk_action_id=NEW.session_risk_action_id
    AND score.scope_type=NEW.scope_type AND score.scope_key=NEW.scope_key
    AND score.status=NEW.status AND score.score=NEW.score
    AND score.score_scale=NEW.score_scale
    AND score.risky_turn_count=NEW.risky_turn_count
    AND score.jailbreak_count=NEW.jailbreak_count
    AND score.sensitive_count=NEW.sensitive_count
    AND score.tool_inducement_count=NEW.tool_inducement_count
    AND score.state_revision=NEW.state_revision
    AND score.threshold_version=NEW.threshold_version
    AND action.state_revision=NEW.state_revision
    AND action.actor_type=NEW.actor_type AND action.actor_id=NEW.actor_id
    AND action.source_request_id=NEW.source_request_id
    AND action.source_trace_id=NEW.source_trace_id
    AND action.created_at=NEW.occurred_at
)
  OR (NEW.session_risk_freeze_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM session_risk_freezes freeze
    WHERE freeze.tenant_id=NEW.tenant_id
      AND freeze.session_risk_freeze_id=NEW.session_risk_freeze_id
      AND freeze.source_session_risk_score_id=NEW.session_risk_score_id
      AND freeze.target_type=NEW.target_type
  ))
  OR EXISTS (
    SELECT 1 FROM session_risk_events current
    WHERE current.session_risk_event_id=NEW.session_risk_event_id
       OR (current.tenant_id=NEW.tenant_id
           AND current.session_risk_score_id=NEW.session_risk_score_id
           AND current.state_revision=NEW.state_revision)
       OR (NEW.rowid!=-1 AND current.rowid=NEW.rowid)
  )
BEGIN SELECT RAISE(ABORT,''session_risk_event_owner_mismatch''); END', '546bf7860b02dfa6597134e0b9e82109fb60549c8dae72416e5034624ba1d1dd'),
('trg_session_risk_events_security_source_prd081', 'session_risk_events', 'CREATE TRIGGER trg_session_risk_events_security_source_prd081
AFTER INSERT ON session_risk_events FOR EACH ROW
WHEN length(NEW.session_risk_event_id)=38
  AND substr(NEW.session_risk_event_id,1,6)=''srevt_''
  AND substr(NEW.session_risk_event_id,7) NOT GLOB ''*[^0-9a-f]*''
  AND NEW.risky_turn_count BETWEEN 1 AND 1000
  AND NEW.source_request_id NOT GLOB ''*[^A-Za-z0-9_.:-]*''
  AND NEW.source_trace_id NOT GLOB ''*[^A-Za-z0-9_.:-]*''
  AND NEW.session_risk_score_id NOT GLOB ''*[^A-Za-z0-9_.:-]*''
BEGIN
  INSERT INTO security_event_sources(
    security_event_source_id,tenant_id,source_event_type,source_object_id,category,
    severity,severity_score,action,outcome,resource_type,resource_id,
    source_request_id,source_trace_id,occurrence_count,occurred_at,created_at
  )
  SELECT ''sesrc_''||substr(NEW.session_risk_event_id,-32),NEW.tenant_id,
    ''security.session_high_risk'',NEW.session_risk_event_id,''session_risk'',
    CASE WHEN action.action IN(''freeze_session'',''freeze_virtual_key'') THEN ''critical''
      WHEN action.action=''high_risk'' THEN ''high'' ELSE ''medium'' END,
    CASE WHEN action.action IN(''freeze_session'',''freeze_virtual_key'') THEN 10
      WHEN action.action=''high_risk'' THEN 8 ELSE 4 END,
    action.action,CASE action.action WHEN ''high_risk'' THEN ''detected''
      WHEN ''freeze_session'' THEN ''frozen'' WHEN ''freeze_virtual_key'' THEN ''frozen''
      WHEN ''dismiss'' THEN ''resolved'' WHEN ''release_session'' THEN ''released''
      WHEN ''release_virtual_key'' THEN ''released'' ELSE ''expired'' END,
    ''session_risk_score'',NEW.session_risk_score_id,NEW.source_request_id,
    NEW.source_trace_id,NEW.risky_turn_count,NEW.occurred_at,NEW.occurred_at
  FROM session_risk_actions action
  WHERE action.tenant_id=NEW.tenant_id
    AND action.session_risk_action_id=NEW.session_risk_action_id;
END', '033e117c20bb1d5825120eda54f4beb8170fe7827b21c2c1b7ea15acc4960d6a'),
