  OR NEW.reporter_membership_id!=OLD.reporter_membership_id OR NEW.category!=OLD.category
  OR NEW.severity!=OLD.severity OR NEW.subject_ciphertext!=OLD.subject_ciphertext
  OR NEW.subject_key_version!=OLD.subject_key_version OR NEW.related_kind!=OLD.related_kind
  OR NEW.related_reference_hmac IS NOT OLD.related_reference_hmac
  OR NEW.sla_policy_version!=OLD.sla_policy_version
  OR NEW.authorization_fingerprint_sha256!=OLD.authorization_fingerprint_sha256
  OR NEW.created_at!=OLD.created_at OR NEW.revision!=OLD.revision+1
  OR NEW.updated_at<=OLD.updated_at
  OR NOT ((NEW.status=OLD.status)
    OR(OLD.status=''open'' AND NEW.status IN(''triaged'',''waiting_customer'',''waiting_platform'',''resolved''))
    OR(OLD.status=''triaged'' AND NEW.status IN(''waiting_customer'',''waiting_platform'',''resolved''))
    OR(OLD.status=''waiting_customer'' AND NEW.status IN(''triaged'',''waiting_platform'',''resolved''))
    OR(OLD.status=''waiting_platform'' AND NEW.status IN(''triaged'',''waiting_customer'',''resolved''))
    OR(OLD.status=''resolved'' AND NEW.status IN(''open'',''closed'')))
BEGIN SELECT RAISE(ABORT,''support_ticket_transition_invalid''); END', 'a1500f6412f0f45c602855e6fba81266d1e81646fe87ad38179fee9e568a873b'),
('trg_telemetry_policies_delete_prd109', 'telemetry_policies', 'CREATE TRIGGER trg_telemetry_policies_delete_prd109 BEFORE DELETE ON telemetry_policies
BEGIN SELECT RAISE(ABORT,''telemetry_policy_immutable''); END', '93b5281506c459786f38eae2749a8c7dedafbc3dcfdecfddd3fa5833bba6e059'),
('trg_telemetry_policies_update_prd109', 'telemetry_policies', 'CREATE TRIGGER trg_telemetry_policies_update_prd109 BEFORE UPDATE ON telemetry_policies
BEGIN SELECT RAISE(ABORT,''telemetry_policy_immutable''); END', '8240dfaec89980761a6ef17a386ce9750c16e5d9ff6847590e52b0374a98cbde'),
('trg_temporary_rate_limit_overrides_conflict_insert_prd053', 'temporary_rate_limit_overrides', 'CREATE TRIGGER trg_temporary_rate_limit_overrides_conflict_insert_prd053
BEFORE INSERT ON temporary_rate_limit_overrides
FOR EACH ROW
WHEN EXISTS (
  SELECT 1 FROM temporary_rate_limit_overrides current
  WHERE current.temporary_rate_limit_override_id=NEW.temporary_rate_limit_override_id
    OR (NEW.rowid!=-1 AND current.rowid=NEW.rowid)
    OR (current.tenant_id=NEW.tenant_id AND current.source_id=NEW.source_id)
    OR (current.tenant_id=NEW.tenant_id AND current.source_action_id=NEW.source_action_id)
    OR (NEW.release_action_id IS NOT NULL
      AND current.tenant_id=NEW.tenant_id
      AND current.release_action_id=NEW.release_action_id)
)
BEGIN
  SELECT RAISE(ABORT, ''temporary_rate_limit_override_immutable'');
END', '08234759a4f52c36258b065558be809fc52a86af8011b0ed2879f95990189a3b'),
('trg_temporary_rate_limit_overrides_immutable_delete_prd053', 'temporary_rate_limit_overrides', 'CREATE TRIGGER trg_temporary_rate_limit_overrides_immutable_delete_prd053
BEFORE DELETE ON temporary_rate_limit_overrides
FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, ''temporary_rate_limit_override_immutable'');
END', 'bc9c2848e444f5faaa11f96b54f4959ad7a92bccbbae2eb5af4625f3d16359ef'),
('trg_temporary_rate_limit_overrides_owner_insert_prd053', 'temporary_rate_limit_overrides', 'CREATE TRIGGER trg_temporary_rate_limit_overrides_owner_insert_prd053
BEFORE INSERT ON temporary_rate_limit_overrides
FOR EACH ROW
WHEN NOT EXISTS (
  SELECT 1
  FROM cost_anomalies anomaly
  JOIN virtual_keys key
    ON key.tenant_id=anomaly.tenant_id
   AND key.virtual_key_id=anomaly.virtual_key_id
  JOIN cost_anomaly_actions action
    ON action.tenant_id=anomaly.tenant_id
   AND action.cost_anomaly_id=anomaly.cost_anomaly_id
   AND action.cost_anomaly_action_id=NEW.source_action_id
  WHERE anomaly.tenant_id=NEW.tenant_id
    AND anomaly.cost_anomaly_id=NEW.source_id
    AND anomaly.scope_type=''virtual_key''
    AND anomaly.virtual_key_id=NEW.virtual_key_id
    AND anomaly.status IN (''open'', ''acknowledged'', ''mitigated'')
    AND key.status=''active''
    AND key.environment_id=anomaly.environment_id
    AND action.action_type=''apply_temporary_rate_limit''
    AND action.status_after=''mitigated''
    AND action.actor_user_id=NEW.created_by
    AND action.rpm_limit IS NEW.rpm_limit
    AND action.tpm_limit IS NEW.tpm_limit
    AND action.concurrency_limit IS NEW.concurrency_limit
    AND action.operation_request_id=NEW.operation_request_id
    AND action.operation_trace_id=NEW.operation_trace_id
    AND action.created_at=NEW.starts_at
    AND NEW.created_at=NEW.starts_at
    AND action.duration_minutes=(unixepoch(NEW.expires_at)-unixepoch(NEW.starts_at))/60
)
BEGIN
  SELECT RAISE(ABORT, ''temporary_rate_limit_override_owner_mismatch'');
END', '3e82a62237e6b6b218fa56cc949b52eef5d9f550d4e8cc2321076cec4c8f8f06'),
('trg_temporary_rate_limit_overrides_release_update_prd053', 'temporary_rate_limit_overrides', 'CREATE TRIGGER trg_temporary_rate_limit_overrides_release_update_prd053
BEFORE UPDATE ON temporary_rate_limit_overrides
FOR EACH ROW
WHEN NOT (
  OLD.status=''active'' AND NEW.status=''released''
  AND NEW.temporary_rate_limit_override_id=OLD.temporary_rate_limit_override_id
  AND NEW.tenant_id=OLD.tenant_id
  AND NEW.virtual_key_id=OLD.virtual_key_id
  AND NEW.source_type=OLD.source_type
  AND NEW.source_id=OLD.source_id
  AND NEW.source_action_id=OLD.source_action_id
  AND NEW.rpm_limit IS OLD.rpm_limit
  AND NEW.tpm_limit IS OLD.tpm_limit
  AND NEW.concurrency_limit IS OLD.concurrency_limit
  AND NEW.starts_at=OLD.starts_at
  AND NEW.expires_at=OLD.expires_at
  AND NEW.created_by=OLD.created_by
  AND NEW.operation_request_id=OLD.operation_request_id
  AND NEW.operation_trace_id=OLD.operation_trace_id
  AND NEW.created_at=OLD.created_at
  AND NEW.updated_at=NEW.released_at
  AND unixepoch(NEW.released_at)<unixepoch(OLD.expires_at)
  AND EXISTS (
    SELECT 1 FROM cost_anomaly_actions action
    WHERE action.tenant_id=OLD.tenant_id
      AND action.cost_anomaly_id=OLD.source_id
      AND action.cost_anomaly_action_id=NEW.release_action_id
      AND action.actor_user_id=NEW.released_by
      AND action.action_type=''release_temporary_rate_limit''
      AND action.target_override_id=OLD.temporary_rate_limit_override_id
      AND action.created_at=NEW.released_at
  )
)
BEGIN
  SELECT RAISE(ABORT, ''temporary_rate_limit_override_release_invalid'');
END', '6cb6fd0326187c8836fd9e8ce5be9c8caafb2609af93bf1d912ad33f081e9c84'),
('trg_temporary_rate_limit_overrides_rowid_insert_prd053', 'temporary_rate_limit_overrides', 'CREATE TRIGGER trg_temporary_rate_limit_overrides_rowid_insert_prd053
AFTER INSERT ON temporary_rate_limit_overrides
FOR EACH ROW
WHEN NEW.rowid<0
BEGIN
  SELECT RAISE(ABORT, ''temporary_rate_limit_override_immutable'');
END', 'd1dfdeb171fa0c9c1813888c54a24da21ba4b9c1ad12240c395b5d68969cdabb'),
('trg_tenant_data_operational_transition_prd096', 'tenant_data_states', 'CREATE TRIGGER trg_tenant_data_operational_transition_prd096
AFTER UPDATE OF lifecycle_status ON tenant_data_states FOR EACH ROW
WHEN NEW.lifecycle_status!=OLD.lifecycle_status
BEGIN
  UPDATE workspace_operational_states
  SET status=CASE WHEN NEW.lifecycle_status=''deleted''
      AND (SELECT status FROM tenants WHERE tenant_id=NEW.tenant_id)=''disabled''
      THEN ''deleted'' ELSE ''deletion_pending'' END,
    revision=revision+1,source=''data_lifecycle'',
    suspended_reason_code=NULL,suspended_by_operator_id=NULL,suspended_at=NULL,
    updated_at=NEW.updated_at
  WHERE tenant_id=NEW.tenant_id AND status!=''deleted'';
END', '6de0398df1ed63f26d07098cbadf899e8490253b6707c6c70aff22d9d4616e30'),
