     ''c11bed7d12ab2d388587377fd51e9ca4a1b7d4190dbf597432888c48462f365f'',
     strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''),strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'')),
    (NEW.tenant_id,''ptpl_customer_service_redaction'',''customer_service_redaction'',''客服脱敏'',
