('trg_tenants_rbac_initialize_prd059', 'tenants', 'CREATE TRIGGER trg_tenants_rbac_initialize_prd059 AFTER INSERT ON tenants FOR EACH ROW BEGIN
  INSERT INTO roles(role_id,tenant_id,code,name,description,status,created_at,updated_at,permission_revision,matrix_sha256,is_permission_immutable)
  SELECT ''role_''||lower(hex(randomblob(16))),NEW.tenant_id,c.role_code,c.role_code,''PRD-141 fixed role'',''active'',strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''),strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''),1,CASE c.role_code WHEN ''admin'' THEN ''eb48d3c3fddfa76477ae5af3943449253af0581da445e3d5695f893258dba6b8'' WHEN ''developer'' THEN ''888796e8f30b282353452e012ba5132476a59ffb2509eded4cb44d8e8de5b686'' WHEN ''viewer'' THEN ''be55018029cd884b139e7e919a0f7052a94c8ca1ae5120fcb499e1b8754837af'' WHEN ''finance_admin'' THEN ''843de9cd51726438ebf668ab413a126b31c429a26b7ee306a394bca4435764fc'' WHEN ''security_admin'' THEN ''7bece4007f6bb8affcfa72d1db73ddc12b71d4bb85f874ad440736e63e596dbb'' WHEN ''ops_admin'' THEN ''bdab5bcae4741701f7171d1f08624f71306963dea15e99ccbde55028df2e6426'' END,CASE WHEN c.role_code=''admin'' THEN 1 ELSE 0 END FROM(SELECT DISTINCT role_code FROM rbac_role_permission_templates)c;
  INSERT INTO permissions(permission_id,tenant_id,code,category,name,description,risk_level,catalog_revision,status,created_at,updated_at)
  SELECT ''perm_''||lower(hex(randomblob(16))),NEW.tenant_id,t.permission_code,t.category,t.name,t.description,t.risk_level,27,''active'',strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''),strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') FROM rbac_permission_templates t;
  INSERT INTO role_permissions(role_permission_id,tenant_id,role_id,permission_id,created_at,updated_at)
  SELECT ''rperm_''||lower(hex(randomblob(16))),NEW.tenant_id,r.role_id,p.permission_id,strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''),strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') FROM roles r JOIN rbac_role_permission_templates t ON t.role_code=r.code JOIN permissions p ON p.tenant_id=r.tenant_id AND p.code=t.permission_code WHERE r.tenant_id=NEW.tenant_id;
END', '08e24bf71bb8481babd472132dea2a0a7ca882b750ab9709c550f9c4a23c0a1a'),
('trg_tenants_role_dashboard_initialize_prd065', 'tenants', 'CREATE TRIGGER trg_tenants_role_dashboard_initialize_prd065
AFTER INSERT ON tenants FOR EACH ROW
BEGIN
  -- 新租户只投影固定六角色配置，延迟复合 FK 在事务提交时确认对应角色已初始化。
  INSERT INTO role_dashboard_configs(
    role_dashboard_config_id,tenant_id,role_code,default_view_code,
    allowed_view_codes_json,config_revision,status,created_at,updated_at
  )
  SELECT
    ''rdc_''||lower(hex(randomblob(16))),NEW.tenant_id,catalog.role_code,
    catalog.default_view_code,catalog.allowed_view_codes_json,1,''active'',
    strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''),strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'')
  FROM (
    SELECT ''admin'' AS role_code,''executive'' AS default_view_code,
           ''["executive","finance","security","developer","operations"]'' AS allowed_view_codes_json
    UNION ALL SELECT ''developer'',''developer'',''["developer","operations","executive"]''
    UNION ALL SELECT ''viewer'',''executive'',''["executive"]''
    UNION ALL SELECT ''finance_admin'',''finance'',''["finance","executive"]''
    UNION ALL SELECT ''security_admin'',''security'',''["security","executive"]''
    UNION ALL SELECT ''ops_admin'',''operations'',''["operations","executive"]''
  ) catalog;
END', '4a847c25cd6ec426e69e909587997069e54cdd8929288b12078f35db0142e35f'),
('trg_tenants_tenant_data_initialize_prd089', 'tenants', 'CREATE TRIGGER trg_tenants_tenant_data_initialize_prd089 AFTER INSERT ON tenants FOR EACH ROW
BEGIN
  INSERT INTO tenant_data_states(tenant_id,lifecycle_status,revision,cache_generation,active_deletion_request_id,updated_at)
  VALUES(NEW.tenant_id,''active'',1,0,NULL,strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''));
END', '0bb1423b7633adeb8389b8c6ce92c484509a06fc563cbd3c23ce127bad16bd95'),
('trg_tenants_workspace_backfill_prd093', 'tenants', 'CREATE TRIGGER trg_tenants_workspace_backfill_prd093
AFTER INSERT ON tenants FOR EACH ROW
WHEN NOT EXISTS(SELECT 1 FROM workspace_tenant_creation_claims c
  WHERE c.tenant_id=NEW.tenant_id AND c.status=''pending''
    AND c.expires_at>=strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''))
BEGIN
  INSERT INTO workspaces(
    workspace_id,kind,status,profile_state,creation_source,revision,
    created_by_account_id,created_at,updated_at)
  VALUES(
    ''wsp_''||substr(metahub_sha256(NEW.tenant_id),1,32),''organization'',
    ''migration_conflict'',''migration_conflict'',
    CASE WHEN NEW.slug=''default'' THEN ''legacy_bootstrap'' ELSE ''legacy_backfill'' END,
    1,NULL,NEW.created_at,NEW.updated_at);
  INSERT INTO workspace_tenant_bindings(
    workspace_tenant_binding_id,workspace_id,tenant_id,status,created_at)
  VALUES(''wtb_''||substr(metahub_sha256(NEW.tenant_id),1,32),
    ''wsp_''||substr(metahub_sha256(NEW.tenant_id),1,32),NEW.tenant_id,
    ''active'',NEW.created_at);
  INSERT INTO workspace_regions(
    workspace_region_id,workspace_id,tenant_id,region_code,
    residency_policy_version,status,created_at)
  VALUES(''wrg_''||substr(metahub_sha256(NEW.tenant_id),1,32),
    ''wsp_''||substr(metahub_sha256(NEW.tenant_id),1,32),NEW.tenant_id,
    ''cn-north-1'',''legacy-domestic-v1'',''active'',NEW.created_at);
  INSERT INTO organization_profiles(
    organization_profile_id,workspace_id,name,slug_normalized,profile_state,
    revision,created_at,updated_at)
  VALUES(''org_''||substr(metahub_sha256(NEW.tenant_id),1,32),
    ''wsp_''||substr(metahub_sha256(NEW.tenant_id),1,32),NEW.name,lower(NEW.slug),
    ''migration_conflict'',1,NEW.created_at,NEW.updated_at);
  INSERT INTO workspace_provisioning_jobs(
    workspace_provisioning_job_id,workspace_id,tenant_id,generation,status,
    attempt_count,error_code,next_attempt_at,created_at,updated_at)
  VALUES(''wpj_''||substr(metahub_sha256(NEW.tenant_id),1,32),
    ''wsp_''||substr(metahub_sha256(NEW.tenant_id),1,32),NEW.tenant_id,1,''failed'',0,
    ''workspace.migration_conflict'',NULL,NEW.created_at,NEW.updated_at);
  INSERT OR IGNORE INTO workspace_environment_origins(
    workspace_environment_origin_id,workspace_id,tenant_id,environment_id,origin,created_at)
  SELECT ''weo_''||substr(metahub_sha256(e.tenant_id||char(31)||e.environment_id),1,32),
    ''wsp_''||substr(metahub_sha256(e.tenant_id),1,32),e.tenant_id,e.environment_id,
    ''legacy_existing'',e.created_at
  FROM environments e WHERE e.tenant_id=NEW.tenant_id;
END', '42d86b29bf974eff645285fdfe40e473a6b85d77cc57b9c6db4140d7cf0a1957'),
('trg_uploaded_files_delete_prd072', 'uploaded_files', 'CREATE TRIGGER trg_uploaded_files_delete_prd072
BEFORE DELETE ON uploaded_files FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''file_immutable''); END', 'a4a876c1e41930bc6e4f4d4187d888d070bf1ffc76e0e1cfcf1abf6152928297'),
('trg_uploaded_files_owner_insert_prd072', 'uploaded_files', 'CREATE TRIGGER trg_uploaded_files_owner_insert_prd072
BEFORE INSERT ON uploaded_files FOR EACH ROW
WHEN NOT EXISTS (
  SELECT 1 FROM users user
  WHERE user.tenant_id=NEW.tenant_id AND user.user_id=NEW.uploaded_by
)
  OR EXISTS (
    SELECT 1 FROM uploaded_files current
    WHERE current.file_id=NEW.file_id
       OR (current.tenant_id=NEW.tenant_id AND current.file_id=NEW.file_id)
       OR (NEW.rowid!=-1 AND current.rowid=NEW.rowid)
  )
  OR NEW.status!=''processing''
BEGIN SELECT RAISE(ABORT,''file_owner_mismatch''); END', '61b4a99e07f91088b6baf6492f95d770d98d3ef2748d616cf2b4196c5214af77'),
('trg_uploaded_files_rowid_insert_prd072', 'uploaded_files', 'CREATE TRIGGER trg_uploaded_files_rowid_insert_prd072
AFTER INSERT ON uploaded_files FOR EACH ROW WHEN NEW.rowid<0
BEGIN SELECT RAISE(ABORT,''file_immutable''); END', '323430db0b872d5827401cc378809f3e04e7ca6cf89cd41f5c05d8f2e18832e9'),
('trg_uploaded_files_state_update_prd072', 'uploaded_files', 'CREATE TRIGGER trg_uploaded_files_state_update_prd072
BEFORE UPDATE ON uploaded_files FOR EACH ROW
WHEN NEW.rowid!=OLD.rowid OR NEW.file_id!=OLD.file_id OR NEW.tenant_id!=OLD.tenant_id
  OR NEW.uploaded_by!=OLD.uploaded_by OR NEW.source_request_id!=OLD.source_request_id
  OR NEW.source_trace_id!=OLD.source_trace_id
  OR NEW.original_name_ciphertext IS NOT OLD.original_name_ciphertext
  OR NEW.file_extension!=OLD.file_extension OR NEW.media_type!=OLD.media_type
  OR NEW.size_bytes!=OLD.size_bytes OR NEW.content_fingerprint!=OLD.content_fingerprint
  OR NEW.virus_scan_status!=OLD.virus_scan_status OR NEW.created_at!=OLD.created_at
  OR (OLD.status=''processing'' AND NEW.status NOT IN (''ready'',''blocked'',''failed''))
  OR (OLD.status!=''processing'' AND (
    NEW.status!=OLD.status OR NEW.dlp_scan_status!=OLD.dlp_scan_status
    OR NEW.dlp_action IS NOT OLD.dlp_action
    OR NEW.effective_dlp_rule_id IS NOT OLD.effective_dlp_rule_id
    OR NEW.match_count!=OLD.match_count
    OR NEW.ruleset_fingerprint IS NOT OLD.ruleset_fingerprint
    OR NEW.storage_backend IS NOT OLD.storage_backend
    OR NEW.original_object_key IS NOT OLD.original_object_key
    OR NEW.failure_error_code IS NOT OLD.failure_error_code
    OR NEW.updated_at!=OLD.updated_at OR NEW.completed_at IS NOT OLD.completed_at
  ))
BEGIN SELECT RAISE(ABORT,''file_state_immutable''); END', 'ed533e10a0e6b39485f92a9b651dc7e2df8b8cce55247aa0a626749c511fb143'),
