('trg_usage_export_jobs_status_transition', 'usage_export_jobs', 'CREATE TRIGGER trg_usage_export_jobs_status_transition
BEFORE UPDATE OF status ON usage_export_jobs
FOR EACH ROW
WHEN NOT (
  NEW.status = OLD.status
  OR (OLD.status = ''pending'' AND NEW.status = ''processing'')
  OR (OLD.status = ''processing'' AND NEW.status IN (''pending'', ''completed'', ''failed''))
  OR (OLD.status IN (''completed'', ''failed'') AND NEW.status = ''expired'')
)
BEGIN
  SELECT RAISE(ABORT, ''usage_export_job_status_transition_invalid'');
END', 'c268f025d5140ebd36882f5d735106bb3ac87485e811587076868ce7785c0f21'),
('trg_usage_export_ledger_sequences_immutable_delete', 'usage_export_ledger_sequences', 'CREATE TRIGGER trg_usage_export_ledger_sequences_immutable_delete
