('trg_usage_export_ledger_sequences_immutable_update', 'usage_export_ledger_sequences', 'CREATE TRIGGER trg_usage_export_ledger_sequences_immutable_update
BEFORE UPDATE ON usage_export_ledger_sequences
FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, ''usage_export_ledger_sequence_immutable'');
END', '5800f84ef95d68c5ddb7239a566916f17f88300a4618fd8b11a346965c81d41f'),
('trg_usage_export_ledger_sequences_owner_insert', 'usage_export_ledger_sequences', 'CREATE TRIGGER trg_usage_export_ledger_sequences_owner_insert
BEFORE INSERT ON usage_export_ledger_sequences
FOR EACH ROW
WHEN NOT EXISTS (
