END', '589ebd4b1e03d6edc2740087cf70d5c558f994149e59dbf79bf692d5b67d62eb'),
('trg_usage_ledger_export_append_only_delete', 'usage_ledger', 'CREATE TRIGGER trg_usage_ledger_export_append_only_delete
BEFORE DELETE ON usage_ledger
FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, ''usage_ledger_append_only'');
