('trg_usage_ledger_export_append_only_update', 'usage_ledger', 'CREATE TRIGGER trg_usage_ledger_export_append_only_update
BEFORE UPDATE ON usage_ledger
FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, ''usage_ledger_append_only'');
