('trg_usage_ledger_export_sequence_insert', 'usage_ledger', 'CREATE TRIGGER trg_usage_ledger_export_sequence_insert
AFTER INSERT ON usage_ledger
FOR EACH ROW
BEGIN
  -- 新 Usage 与导出序列保持同事务追加，避免导出水位漏记账本。
  INSERT INTO usage_export_ledger_sequences(tenant_id, usage_ledger_id)
  VALUES(NEW.tenant_id, NEW.usage_ledger_id);
END', 'e6d3a7da96d49580423e7c7d1f5573520c8b48c0322f1385e07f4bf8eaf3b51c'),
('trg_usage_ledger_finops_amount_insert_prd051', 'usage_ledger', 'CREATE TRIGGER trg_usage_ledger_finops_amount_insert_prd051
BEFORE INSERT ON usage_ledger
FOR EACH ROW
BEGIN
  SELECT CASE WHEN NOT json_valid(NEW.normalized_usage)
    OR json_type(NEW.normalized_usage)!=''object''
    THEN RAISE(ABORT, ''usage_finops_amount_invalid'') END;
  -- cache hit 的 FinOps owner 必须在事务外预生成，供 commit-unknown 精确回读；
  -- 普通 Provider Usage 禁止借用这两个私有投影字段改变既有随机 owner 合同。
  SELECT CASE WHEN NEW.usage_source=''response_cache'' AND (
      json_type(NEW.normalized_usage,''$.finops_ledger_entry_id'')!=''text''
      OR length(json_extract(NEW.normalized_usage,''$.finops_ledger_entry_id''))!=36
      OR substr(json_extract(NEW.normalized_usage,''$.finops_ledger_entry_id''),1,4)!=''fle_''
      OR substr(json_extract(NEW.normalized_usage,''$.finops_ledger_entry_id''),5)
           GLOB ''*[^0-9a-f]*''
      OR json_type(NEW.normalized_usage,''$.finops_event_id'')!=''text''
      OR length(json_extract(NEW.normalized_usage,''$.finops_event_id''))!=38
      OR substr(json_extract(NEW.normalized_usage,''$.finops_event_id''),1,6)!=''flevt_''
      OR substr(json_extract(NEW.normalized_usage,''$.finops_event_id''),7)
           GLOB ''*[^0-9a-f]*''
    ) THEN RAISE(ABORT, ''usage_finops_owner_mismatch'') END;
  SELECT CASE WHEN NEW.usage_source!=''response_cache'' AND (
      json_type(NEW.normalized_usage,''$.finops_ledger_entry_id'') IS NOT NULL
      OR json_type(NEW.normalized_usage,''$.finops_event_id'') IS NOT NULL
    ) THEN RAISE(ABORT, ''usage_finops_owner_mismatch'') END;
  SELECT CASE WHEN json_type(NEW.normalized_usage, ''$.cost_amount'') NOT IN (''text'')
      AND json_type(NEW.normalized_usage, ''$.cost_amount'') IS NOT NULL
    THEN RAISE(ABORT, ''usage_finops_amount_invalid'') END;
  SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM (
      SELECT
        value.amount_text,
        CASE WHEN instr(value.amount_text, ''.'')=0
          THEN value.amount_text
          ELSE substr(value.amount_text, 1, instr(value.amount_text, ''.'')-1)
        END AS integer_text,
        CASE WHEN instr(value.amount_text, ''.'')=0
          THEN '''' ELSE substr(value.amount_text, instr(value.amount_text, ''.'')+1)
        END AS fraction_text
      FROM (
        SELECT CASE
          WHEN json_type(NEW.normalized_usage, ''$.cost_amount'')=''text''
            THEN json_extract(NEW.normalized_usage, ''$.cost_amount'')
          ELSE printf(''%.6f'', NEW.cost_amount)
        END AS amount_text
      ) value
    ) parts
    WHERE parts.amount_text=''''
       OR parts.amount_text GLOB ''*[^0-9.]*''
       OR parts.integer_text=''''
       OR parts.integer_text GLOB ''*[^0-9]*''
       OR length(parts.integer_text) NOT BETWEEN 1 AND 10
       OR (length(parts.integer_text)>1 AND substr(parts.integer_text, 1, 1)=''0'')
       OR (
         instr(parts.amount_text, ''.'')>0
         AND (
           parts.fraction_text=''''
           OR parts.fraction_text GLOB ''*[^0-9]*''
           OR length(parts.fraction_text) NOT BETWEEN 1 AND 6
         )
       )
       OR instr(substr(parts.amount_text, instr(parts.amount_text, ''.'')+1), ''.'')>0
       OR CAST(parts.integer_text AS INTEGER) * 1000000
          + CASE WHEN parts.fraction_text=''''
              THEN 0
              ELSE CAST(substr(parts.fraction_text || ''000000'', 1, 6) AS INTEGER)
            END > 1000000000000000
  ) THEN RAISE(ABORT, ''usage_finops_amount_invalid'') END;
  SELECT CASE WHEN json_type(NEW.normalized_usage, ''$.cost_amount'')=''text''
    AND printf(''%.6f'', NEW.cost_amount) != (
      SELECT parts.integer_text || ''.'' || substr(parts.fraction_text || ''000000'', 1, 6)
      FROM (
        SELECT
          CASE WHEN instr(value.amount_text, ''.'')=0
            THEN value.amount_text
            ELSE substr(value.amount_text, 1, instr(value.amount_text, ''.'')-1)
          END AS integer_text,
          CASE WHEN instr(value.amount_text, ''.'')=0
            THEN '''' ELSE substr(value.amount_text, instr(value.amount_text, ''.'')+1)
          END AS fraction_text
        FROM (
          SELECT json_extract(NEW.normalized_usage, ''$.cost_amount'') AS amount_text
        ) value
      ) parts
    ) THEN RAISE(ABORT, ''usage_finops_amount_mismatch'') END;
  SELECT CASE WHEN NEW.currency NOT IN (''CNY'', ''USD'')
    THEN RAISE(ABORT, ''usage_finops_currency_invalid'') END;
  SELECT CASE WHEN json_type(NEW.normalized_usage, ''$.currency'') IS NOT NULL
    AND (
      json_type(NEW.normalized_usage, ''$.currency'')!=''text''
      OR json_extract(NEW.normalized_usage, ''$.currency'')!=NEW.currency
    ) THEN RAISE(ABORT, ''usage_finops_currency_invalid'') END;
  SELECT CASE WHEN NEW.currency=''CNY''
    AND json_type(NEW.normalized_usage, ''$.cost_amount'')=''text''
    AND (
      json_type(NEW.normalized_usage, ''$.cost_cny'')!=''text''
      OR json_extract(NEW.normalized_usage, ''$.cost_cny'')
        !=json_extract(NEW.normalized_usage, ''$.cost_amount'')
    ) THEN RAISE(ABORT, ''usage_finops_cny_mismatch'') END;
  SELECT CASE WHEN NEW.currency=''USD''
    AND json_type(NEW.normalized_usage, ''$.cost_cny'') NOT IN (''null'')
    AND json_type(NEW.normalized_usage, ''$.cost_cny'') IS NOT NULL
    THEN RAISE(ABORT, ''usage_finops_cny_unavailable'') END;
  SELECT CASE WHEN json_type(NEW.normalized_usage, ''$.posting_source'') IS NOT NULL
    AND (
      json_type(NEW.normalized_usage, ''$.posting_source'')!=''text''
      OR json_extract(NEW.normalized_usage, ''$.posting_source'')
        NOT IN (''direct'', ''spool_replay'')
    ) THEN RAISE(ABORT, ''usage_finops_posting_source_invalid'') END;
  SELECT CASE WHEN json_type(NEW.normalized_usage, ''$.price_snapshot_id'')=''text''
    AND json_extract(NEW.normalized_usage, ''$.price_snapshot_id'') IS NOT NEW.price_snapshot_id
    THEN RAISE(ABORT, ''usage_finops_snapshot_mismatch'') END;
  SELECT CASE WHEN json_type(NEW.normalized_usage, ''$.price_schema_version'')=''text''
    AND json_extract(NEW.normalized_usage, ''$.price_schema_version'') IS NOT NEW.price_schema_version
    THEN RAISE(ABORT, ''usage_finops_snapshot_mismatch'') END;
  -- 新 canonical Usage 的非零金额必须已经有可信版本快照；零价才允许自动补 unpriced-v1。
  SELECT CASE WHEN json_type(NEW.normalized_usage, ''$.cost_amount'')=''text''
    AND (
      SELECT CAST(parts.integer_text AS INTEGER) * 1000000
        + CASE WHEN parts.fraction_text=''''
            THEN 0 ELSE CAST(substr(parts.fraction_text || ''000000'', 1, 6) AS INTEGER) END
      FROM (
        SELECT
          CASE WHEN instr(value.amount_text, ''.'')=0
            THEN value.amount_text
            ELSE substr(value.amount_text, 1, instr(value.amount_text, ''.'')-1) END AS integer_text,
          CASE WHEN instr(value.amount_text, ''.'')=0
            THEN '''' ELSE substr(value.amount_text, instr(value.amount_text, ''.'')+1) END AS fraction_text
        FROM (
          SELECT json_extract(NEW.normalized_usage, ''$.cost_amount'') AS amount_text
        ) value
      ) parts
    )>0
    AND NOT EXISTS (
      SELECT 1 FROM price_snapshots snapshot
      WHERE snapshot.price_snapshot_id=NEW.price_snapshot_id
        AND snapshot.tenant_id=NEW.tenant_id
        AND snapshot.request_id=NEW.request_id
        AND snapshot.currency=NEW.currency
        AND NULLIF(trim(snapshot.price_schema_version), '''') IS NOT NULL
        AND snapshot.price_schema_version=NEW.price_schema_version
    ) THEN RAISE(ABORT, ''usage_finops_price_evidence_missing'') END;
END', 'a35b446a978ae9376c91d3725a011d9366fc498ef580cc16d8726aab67ebc741'),
('trg_usage_ledger_finops_conflict_insert_prd051', 'usage_ledger', 'CREATE TRIGGER trg_usage_ledger_finops_conflict_insert_prd051
BEFORE INSERT ON usage_ledger
FOR EACH ROW
WHEN EXISTS (
  SELECT 1 FROM usage_ledger current
  WHERE current.usage_ledger_id=NEW.usage_ledger_id
     OR (NEW.rowid!=-1 AND current.rowid=NEW.rowid)
)
BEGIN
  SELECT RAISE(ABORT, ''usage_ledger_append_only'');
END', '13c88395fcef466738d94f8b45130eb685e3836de631a10d492f09f61f4d5a21'),
('trg_usage_ledger_finops_owner_insert_prd051', 'usage_ledger', 'CREATE TRIGGER trg_usage_ledger_finops_owner_insert_prd051
BEFORE INSERT ON usage_ledger
FOR EACH ROW
WHEN NOT EXISTS (
  SELECT 1 FROM request_logs request
  WHERE request.tenant_id=NEW.tenant_id AND request.request_id=NEW.request_id
)
OR (
  NEW.price_snapshot_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM price_snapshots snapshot
    WHERE snapshot.price_snapshot_id=NEW.price_snapshot_id
      AND snapshot.tenant_id=NEW.tenant_id
      AND snapshot.request_id=NEW.request_id
      AND snapshot.currency=NEW.currency
  )
)
OR (
  NEW.model_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM models model
    WHERE model.model_id=NEW.model_id AND model.tenant_id=NEW.tenant_id
  )
)
OR (
  NEW.provider_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM providers provider
    WHERE provider.provider_id=NEW.provider_id AND provider.tenant_id=NEW.tenant_id
  )
)
OR (
  NEW.virtual_key_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM virtual_keys key
    WHERE key.virtual_key_id=NEW.virtual_key_id AND key.tenant_id=NEW.tenant_id
  )
)
OR (
  NEW.environment_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM environments environment
    WHERE environment.environment_id=NEW.environment_id
      AND environment.tenant_id=NEW.tenant_id
  )
)
OR (
  NEW.project_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM projects project
    WHERE project.project_id=NEW.project_id AND project.tenant_id=NEW.tenant_id
  )
)
OR (
  NEW.application_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM applications application
    WHERE application.application_id=NEW.application_id
      AND application.tenant_id=NEW.tenant_id
      AND (NEW.project_id IS NULL OR application.project_id=NEW.project_id)
  )
)
BEGIN
  SELECT RAISE(ABORT, ''usage_finops_owner_mismatch'');
END', 'baa3c928f106b4c5a85db7481d841cee2217088c2f37c40aac52fe3fca02222f'),
('trg_usage_ledger_finops_projection_insert_prd051', 'usage_ledger', 'CREATE TRIGGER trg_usage_ledger_finops_projection_insert_prd051
AFTER INSERT ON usage_ledger
FOR EACH ROW
BEGIN
  -- 缺失或不可信的价格快照只创建当前 Usage 专属证据，禁止借用当前模型价格回算历史金额。
  INSERT INTO price_snapshots(
    price_snapshot_id, tenant_id, request_id, model_id, provider_id, provider_code,
    currency, input_price_per_1k, output_price_per_1k, price_schema_version,
    billing_dimensions, provider_raw_mapping, source, status,
    created_at, updated_at, price_plan_id, effective_from
  )
  SELECT
    ''prs_'' || lower(hex(randomblob(16))),
    NEW.tenant_id,
    NEW.request_id,
    NEW.model_id,
    NEW.provider_id,
    NEW.provider_code,
    NEW.currency,
    CASE WHEN json_type(NEW.normalized_usage, ''$.cost_amount'') IS NULL
      THEN COALESCE((
        SELECT snapshot.input_price_per_1k FROM price_snapshots snapshot
        WHERE snapshot.price_snapshot_id=NEW.price_snapshot_id
      ), 0) ELSE 0 END,
    CASE WHEN json_type(NEW.normalized_usage, ''$.cost_amount'') IS NULL
      THEN COALESCE((
        SELECT snapshot.output_price_per_1k FROM price_snapshots snapshot
        WHERE snapshot.price_snapshot_id=NEW.price_snapshot_id
      ), 0) ELSE 0 END,
    CASE WHEN json_type(NEW.normalized_usage, ''$.cost_amount'') IS NULL
      THEN ''legacy-unversioned-v1'' ELSE ''unpriced-v1'' END,
    json_object(
      ''finops_usage_ledger_id'', NEW.usage_ledger_id,
      ''price_evidence_status'', CASE
        WHEN json_type(NEW.normalized_usage, ''$.cost_amount'') IS NULL
          THEN ''legacy_amount_only'' ELSE ''unpriced'' END
    ),
    ''{}'',
    CASE WHEN json_type(NEW.normalized_usage, ''$.cost_amount'') IS NULL
      THEN ''finops_legacy_backfill'' ELSE ''finops_unpriced'' END,
    ''active'',
    NEW.created_at,
    NEW.created_at,
    NULL,
    NEW.created_at
  WHERE NOT EXISTS (
    SELECT 1 FROM price_snapshots snapshot
    WHERE snapshot.price_snapshot_id=NEW.price_snapshot_id
      AND snapshot.tenant_id=NEW.tenant_id
      AND snapshot.request_id=NEW.request_id
      AND snapshot.currency=NEW.currency
      AND NULLIF(trim(snapshot.price_schema_version), '''') IS NOT NULL
      AND snapshot.price_schema_version=NEW.price_schema_version
  );

  -- 正式分录与新 Usage 在同一事务产生，唯一约束保证 tenant+Usage 只投影一次。
  INSERT INTO finops_ledger_entries(
    finops_ledger_entry_id, event_id, tenant_id, entry_type, direction,
    amount_micros, currency, normalized_cny_micros, cny_normalization_status,
    price_evidence_status, price_snapshot_source, posting_source, quota_type,
    usage_ledger_id, finops_adjustment_id, source_request_id, source_trace_id,
    operation_request_id, operation_trace_id, price_snapshot_id,
    price_schema_version, reversal_of_entry_id, actor_user_id,
    input_tokens, output_tokens, total_tokens, cache_tokens,
    model_id, provider_id, virtual_key_id, environment_id, project_id,
    application_id, estimated, status, created_at, updated_at
  )
  SELECT
    CASE WHEN NEW.usage_source=''response_cache''
      THEN json_extract(NEW.normalized_usage,''$.finops_ledger_entry_id'')
      ELSE ''fle_'' || lower(hex(randomblob(16))) END,
    CASE WHEN NEW.usage_source=''response_cache''
      THEN json_extract(NEW.normalized_usage,''$.finops_event_id'')
      ELSE ''flevt_'' || lower(hex(randomblob(16))) END,
    NEW.tenant_id,
    ''usage_charge'',
    ''debit'',
    amount.amount_micros,
    NEW.currency,
    CASE WHEN NEW.currency=''CNY''
      AND NOT (
        snapshot.source=''response_cache_reference''
        AND snapshot.price_schema_version=''unpriced-v1''
      ) THEN amount.amount_micros ELSE NULL END,
    CASE WHEN NEW.currency=''CNY''
      AND NOT (
        snapshot.source=''response_cache_reference''
        AND snapshot.price_schema_version=''unpriced-v1''
      ) THEN ''normalized'' ELSE ''unavailable'' END,
    CASE
      WHEN snapshot.source=''finops_unpriced'' THEN ''unpriced''
      WHEN snapshot.source=''finops_legacy_backfill'' THEN ''legacy_amount_only''
      WHEN snapshot.source=''response_cache_reference''
        AND snapshot.price_schema_version=''unpriced-v1'' THEN ''unpriced''
      ELSE ''priced''
    END,
    snapshot.source,
    CASE WHEN json_extract(NEW.normalized_usage, ''$.posting_source'')=''spool_replay''
      THEN ''spool_replay'' ELSE ''direct'' END,
    ''paid'',
    NEW.usage_ledger_id,
    NULL,
    NEW.request_id,
    request.trace_id,
    NEW.request_id,
    request.trace_id,
    snapshot.price_snapshot_id,
    snapshot.price_schema_version,
    NULL,
    NULL,
    NEW.input_tokens,
    NEW.output_tokens,
    NEW.total_tokens,
    NEW.cache_tokens,
    NEW.model_id,
    NEW.provider_id,
    NEW.virtual_key_id,
    NEW.environment_id,
    NEW.project_id,
    NEW.application_id,
    NEW.estimated,
    ''posted'',
    NEW.created_at,
    NEW.created_at
  FROM (
    SELECT
      CAST(parts.integer_text AS INTEGER) * 1000000
      + CASE WHEN parts.fraction_text=''''
          THEN 0 ELSE CAST(substr(parts.fraction_text || ''000000'', 1, 6) AS INTEGER) END
        AS amount_micros
    FROM (
      SELECT
        CASE WHEN instr(value.amount_text, ''.'')=0
          THEN value.amount_text
          ELSE substr(value.amount_text, 1, instr(value.amount_text, ''.'')-1) END AS integer_text,
        CASE WHEN instr(value.amount_text, ''.'')=0
          THEN '''' ELSE substr(value.amount_text, instr(value.amount_text, ''.'')+1) END AS fraction_text
      FROM (
        SELECT CASE
          WHEN json_type(NEW.normalized_usage, ''$.cost_amount'')=''text''
            THEN json_extract(NEW.normalized_usage, ''$.cost_amount'')
          ELSE printf(''%.6f'', NEW.cost_amount)
        END AS amount_text
      ) value
    ) parts
  ) amount
  JOIN request_logs request
    ON request.tenant_id=NEW.tenant_id AND request.request_id=NEW.request_id
  JOIN price_snapshots snapshot
    ON snapshot.tenant_id=NEW.tenant_id
   AND snapshot.price_snapshot_id=COALESCE(
     (
       SELECT trusted.price_snapshot_id FROM price_snapshots trusted
       WHERE trusted.price_snapshot_id=NEW.price_snapshot_id
         AND trusted.tenant_id=NEW.tenant_id
         AND trusted.request_id=NEW.request_id
         AND trusted.currency=NEW.currency
         AND NULLIF(trim(trusted.price_schema_version), '''') IS NOT NULL
         AND trusted.price_schema_version=NEW.price_schema_version
     ),
     (
       SELECT synthetic.price_snapshot_id FROM price_snapshots synthetic
       WHERE synthetic.tenant_id=NEW.tenant_id
         AND synthetic.source IN (''finops_unpriced'', ''finops_legacy_backfill'')
         AND json_extract(
           synthetic.billing_dimensions, ''$.finops_usage_ledger_id''
         )=NEW.usage_ledger_id
     )
   );
END', '8fc6a11c2d72ab5820dca9ea9c33e5ad93425d48760e48782c1d0890562a8ec6'),
('trg_usage_ledger_platform_meter_outbox_prd099', 'usage_ledger', 'CREATE TRIGGER trg_usage_ledger_platform_meter_outbox_prd099
AFTER INSERT ON usage_ledger FOR EACH ROW
BEGIN
  INSERT INTO platform_meter_outbox(
    meter_outbox_id,source_usage_ledger_id,status,attempt_count,created_at,updated_at)
  VALUES(''pmo_''||lower(hex(randomblob(16))),NEW.usage_ledger_id,''pending'',0,
    strftime(''%Y-%m-%dT%H:%M:%fZ'',''now''),strftime(''%Y-%m-%dT%H:%M:%fZ'',''now''));
END', 'e74ce049f76fb9688b5074816f61d62e635daa6218eff757b373b439996464d6'),
('trg_usage_routing_attempt_insert', 'usage_ledger', 'CREATE TRIGGER trg_usage_routing_attempt_insert
BEFORE INSERT ON usage_ledger
FOR EACH ROW
WHEN NEW.routing_attempt_id IS NOT NULL
BEGIN
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM routing_attempts ra
    WHERE ra.routing_attempt_id=NEW.routing_attempt_id
      AND ra.tenant_id=NEW.tenant_id
      AND ra.request_id=NEW.request_id
      AND ra.status=''succeeded''
  ) THEN RAISE(ABORT, ''usage_routing_attempt_mismatch'') END;
END', 'cd4ed26704bd0057ecb2f7c3f00799f7e6d2ea69e4d0b66c9d6c93841be3575a'),
('trg_users_identity_email_update_prd091', 'users', 'CREATE TRIGGER trg_users_identity_email_update_prd091
BEFORE UPDATE OF email ON users FOR EACH ROW WHEN NEW.email!=OLD.email
BEGIN SELECT RAISE(ABORT,''identity_email_change_requires_claim''); END', '53dc87f67d12360a7249ec4a9d08bd80c80c2426e205dea7b4bcce2da7230630'),
('trg_users_identity_insert_prd093', 'users', 'CREATE TRIGGER trg_users_identity_insert_prd093
AFTER INSERT ON users FOR EACH ROW
BEGIN
  INSERT INTO global_accounts(
    account_id,email_normalized,phone_e164,display_name,status,login_enabled,
    credential_revision,session_revision,mfa_state,failed_login_count,locked_until,
    last_login_at,created_at,updated_at)
  SELECT
    ''gac_''||substr(metahub_sha256(NEW.tenant_id||char(31)||NEW.user_id),1,32),
    lower(trim(NEW.email)),NULL,NEW.display_name,
    CASE WHEN length(trim(NEW.email))!=length(CAST(trim(NEW.email) AS BLOB))
        OR length(trim(NEW.email)) NOT BETWEEN 3 AND 320
        OR instr(trim(NEW.email),''@'')<=1
        OR instr(substr(trim(NEW.email),instr(trim(NEW.email),''@'')+1),''@'')>0
        OR instr(trim(NEW.email),'' '')>0
        OR metahub_password_hash_algorithm(NEW.password_hash) IS NULL
        OR (SELECT COUNT(*) FROM users x
          WHERE lower(trim(x.email))=lower(trim(NEW.email)))!=1
      THEN ''migration_conflict'' ELSE NEW.status END,
    CASE WHEN length(trim(NEW.email))=length(CAST(trim(NEW.email) AS BLOB))
        AND length(trim(NEW.email)) BETWEEN 3 AND 320
        AND instr(trim(NEW.email),''@'')>1
        AND instr(substr(trim(NEW.email),instr(trim(NEW.email),''@'')+1),''@'')=0
        AND instr(trim(NEW.email),'' '')=0
        AND metahub_password_hash_algorithm(NEW.password_hash) IS NOT NULL
        AND (SELECT COUNT(*) FROM users x
          WHERE lower(trim(x.email))=lower(trim(NEW.email)))=1
      THEN 1 ELSE 0 END,
    1,1,''not_enrolled'',NEW.failed_login_count,NEW.locked_until,NEW.last_login_at,
    NEW.created_at,NEW.updated_at
  WHERE NOT EXISTS(SELECT 1 FROM workspace_user_projection_claims c
    WHERE c.tenant_id=NEW.tenant_id AND c.legacy_user_id=NEW.user_id
      AND c.status=''pending'');

  INSERT INTO account_credentials(
    credential_id,account_id,credential_type,algorithm,secret_hash,status,version,
    created_at,updated_at,rotated_at)
  SELECT
    ''acr_''||substr(metahub_sha256(NEW.tenant_id||char(31)||NEW.user_id),1,32),
    ''gac_''||substr(metahub_sha256(NEW.tenant_id||char(31)||NEW.user_id),1,32),
    ''password'',coalesce(metahub_password_hash_algorithm(NEW.password_hash),''unknown''),
    NEW.password_hash,''active'',1,NEW.created_at,NEW.updated_at,NULL
  WHERE NOT EXISTS(SELECT 1 FROM workspace_user_projection_claims c
    WHERE c.tenant_id=NEW.tenant_id AND c.legacy_user_id=NEW.user_id
      AND c.status=''pending'');

  INSERT INTO account_identity_links(
    identity_link_id,account_id,source_type,legacy_tenant_id,legacy_user_id,status,linked_at)
  SELECT
    ''ail_''||substr(metahub_sha256(NEW.tenant_id||char(31)||NEW.user_id),1,32),
    ''gac_''||substr(metahub_sha256(NEW.tenant_id||char(31)||NEW.user_id),1,32),
    ''legacy_user'',NEW.tenant_id,NEW.user_id,''active'',NEW.created_at
  WHERE NOT EXISTS(SELECT 1 FROM workspace_user_projection_claims c
    WHERE c.tenant_id=NEW.tenant_id AND c.legacy_user_id=NEW.user_id
      AND c.status=''pending'');

  INSERT INTO account_identity_links(
    identity_link_id,account_id,source_type,legacy_tenant_id,legacy_user_id,status,linked_at)
  SELECT
    ''ail_''||substr(metahub_sha256(NEW.tenant_id||char(31)||NEW.user_id),1,32),
    c.account_id,''legacy_user'',NEW.tenant_id,NEW.user_id,''active'',NEW.created_at
  FROM workspace_user_projection_claims c
  WHERE c.tenant_id=NEW.tenant_id AND c.legacy_user_id=NEW.user_id
    AND c.status=''pending'';

  INSERT OR IGNORE INTO workspace_memberships(
    workspace_membership_id,workspace_id,tenant_id,account_id,legacy_user_id,
    role_code,status,source,revision,created_at,updated_at)
  SELECT ''wmb_''||substr(metahub_sha256(NEW.tenant_id),1,32),w.workspace_id,NEW.tenant_id,
    l.account_id,NEW.user_id,''owner'',''active'',''legacy_backfill'',1,NEW.created_at,NEW.updated_at
  FROM workspaces w
  JOIN workspace_tenant_bindings b ON b.workspace_id=w.workspace_id
  JOIN account_identity_links l ON l.legacy_tenant_id=NEW.tenant_id
    AND l.legacy_user_id=NEW.user_id AND l.status=''active''
  JOIN global_accounts a ON a.account_id=l.account_id
  WHERE b.tenant_id=NEW.tenant_id AND w.creation_source!=''user_created''
    AND NEW.role=''admin'' AND NEW.status=''active''
    AND a.status=''active'' AND a.login_enabled=1
    AND EXISTS(SELECT 1 FROM environments e WHERE e.tenant_id=NEW.tenant_id
      AND e.code=''dev'' AND e.status=''active'')
    AND NOT EXISTS(SELECT 1 FROM workspace_memberships existing
      WHERE existing.workspace_id=w.workspace_id);

  UPDATE workspaces
  SET status=''active'',profile_state=''confirmed'',created_by_account_id=(
      SELECT l.account_id FROM account_identity_links l
      WHERE l.legacy_tenant_id=NEW.tenant_id AND l.legacy_user_id=NEW.user_id),
      updated_at=NEW.updated_at
  WHERE workspace_id=''wsp_''||substr(metahub_sha256(NEW.tenant_id),1,32)
    AND creation_source!=''user_created''
    AND EXISTS(SELECT 1 FROM workspace_memberships m
      WHERE m.workspace_id=workspaces.workspace_id AND m.legacy_user_id=NEW.user_id);
  UPDATE organization_profiles SET profile_state=''confirmed'',updated_at=NEW.updated_at
  WHERE workspace_id=''wsp_''||substr(metahub_sha256(NEW.tenant_id),1,32)
    AND EXISTS(SELECT 1 FROM workspace_memberships m
      WHERE m.workspace_id=organization_profiles.workspace_id
        AND m.legacy_user_id=NEW.user_id);
  UPDATE workspace_provisioning_jobs
  SET status=''ready'',error_code=NULL,updated_at=NEW.updated_at
  WHERE tenant_id=NEW.tenant_id AND EXISTS(SELECT 1 FROM workspace_memberships m
    WHERE m.workspace_id=workspace_provisioning_jobs.workspace_id
      AND m.legacy_user_id=NEW.user_id);

  UPDATE global_accounts SET status=''migration_conflict'',login_enabled=0,updated_at=NEW.updated_at
  WHERE account_id IN(
    SELECT l.account_id FROM account_identity_links l JOIN users u
      ON u.tenant_id=l.legacy_tenant_id AND u.user_id=l.legacy_user_id
    WHERE lower(trim(u.email))=lower(trim(NEW.email))
  ) AND (SELECT COUNT(*) FROM users x
    WHERE lower(trim(x.email))=lower(trim(NEW.email)))>1
    AND NOT EXISTS(SELECT 1 FROM workspace_user_projection_claims c
      WHERE c.tenant_id=NEW.tenant_id AND c.legacy_user_id=NEW.user_id
        AND c.status=''pending'');

  INSERT OR IGNORE INTO identity_migration_conflicts(
    conflict_id,account_id,identifier_fingerprint,reason_code,status,detected_at)
  SELECT ''icf_''||substr(metahub_sha256(l.legacy_tenant_id||char(31)||l.legacy_user_id),1,32),
    l.account_id,metahub_sha256(lower(trim(NEW.email))),''duplicate_identifier'',''open'',
    strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'')
  FROM account_identity_links l JOIN users u
    ON u.tenant_id=l.legacy_tenant_id AND u.user_id=l.legacy_user_id
  WHERE lower(trim(u.email))=lower(trim(NEW.email))
    AND (SELECT COUNT(*) FROM users x
      WHERE lower(trim(x.email))=lower(trim(NEW.email)))>1
    AND NOT EXISTS(SELECT 1 FROM workspace_user_projection_claims c
      WHERE c.tenant_id=NEW.tenant_id AND c.legacy_user_id=NEW.user_id
        AND c.status=''pending'');

  INSERT OR IGNORE INTO identity_migration_conflicts(
    conflict_id,account_id,identifier_fingerprint,reason_code,status,detected_at)
  SELECT ''icf_''||substr(metahub_sha256(NEW.tenant_id||char(31)||NEW.user_id),1,32),
    ''gac_''||substr(metahub_sha256(NEW.tenant_id||char(31)||NEW.user_id),1,32),
    metahub_sha256(lower(trim(NEW.email))),
    CASE WHEN length(trim(NEW.email))!=length(CAST(trim(NEW.email) AS BLOB))
        THEN ''identifier_requires_claim''
      WHEN metahub_password_hash_algorithm(NEW.password_hash) IS NULL
        THEN ''credential_unrecognized''
      ELSE ''identifier_invalid'' END,
    ''open'',strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'')
  WHERE (SELECT status FROM global_accounts WHERE account_id=
    ''gac_''||substr(metahub_sha256(NEW.tenant_id||char(31)||NEW.user_id),1,32))
    =''migration_conflict''
    AND NOT EXISTS(SELECT 1 FROM workspace_user_projection_claims c
      WHERE c.tenant_id=NEW.tenant_id AND c.legacy_user_id=NEW.user_id
        AND c.status=''pending'');

  UPDATE workspace_user_projection_claims
  SET status=''consumed'',consumed_at=NEW.created_at
  WHERE tenant_id=NEW.tenant_id AND legacy_user_id=NEW.user_id AND status=''pending'';
END', '0e26ac0d51b336b2139be97445e610cb768ac794ed0eac69247beef207e49837'),
('trg_users_identity_password_update_prd093', 'users', 'CREATE TRIGGER trg_users_identity_password_update_prd093
AFTER UPDATE OF password_hash ON users FOR EACH ROW WHEN NEW.password_hash!=OLD.password_hash
BEGIN
  UPDATE account_credentials
  SET secret_hash=NEW.password_hash,
      algorithm=coalesce(metahub_password_hash_algorithm(NEW.password_hash),''unknown''),
      version=version+1,updated_at=NEW.updated_at,rotated_at=NEW.updated_at
  WHERE account_id=(SELECT account_id FROM account_identity_links
    WHERE source_type=''legacy_user'' AND legacy_tenant_id=NEW.tenant_id
      AND legacy_user_id=NEW.user_id);
  UPDATE global_accounts
  SET credential_revision=credential_revision+1,session_revision=session_revision+1,
      updated_at=NEW.updated_at,
      status=CASE WHEN metahub_password_hash_algorithm(NEW.password_hash) IS NOT NULL
        THEN CASE WHEN login_enabled=1 THEN NEW.status ELSE status END
        ELSE ''migration_conflict'' END,
      login_enabled=CASE WHEN metahub_password_hash_algorithm(NEW.password_hash) IS NOT NULL
        THEN login_enabled ELSE 0 END
  WHERE account_id=(SELECT account_id FROM account_identity_links
    WHERE source_type=''legacy_user'' AND legacy_tenant_id=NEW.tenant_id
      AND legacy_user_id=NEW.user_id);
  UPDATE global_sessions
  SET status=''revoked'',revoked_at=NEW.updated_at,revoked_reason=''credential_rotated'',
      updated_at=NEW.updated_at
  WHERE account_id=(SELECT account_id FROM account_identity_links
    WHERE source_type=''legacy_user'' AND legacy_tenant_id=NEW.tenant_id
      AND legacy_user_id=NEW.user_id) AND status=''active'';
  UPDATE users
  SET password_hash=NEW.password_hash,updated_at=NEW.updated_at
  WHERE (tenant_id,user_id) IN(
    SELECT legacy_tenant_id,legacy_user_id FROM account_identity_links
    WHERE account_id=(SELECT account_id FROM account_identity_links
      WHERE source_type=''legacy_user'' AND legacy_tenant_id=NEW.tenant_id
        AND legacy_user_id=NEW.user_id)
      AND source_type=''legacy_user'' AND status=''active''
  ) AND NOT(tenant_id=NEW.tenant_id AND user_id=NEW.user_id)
    AND password_hash!=NEW.password_hash;
END', '0213021111580c8e7621fdd03fb818d0e21886d9ac489ac120a6932e47d64a28'),
('trg_users_identity_status_update_prd091', 'users', 'CREATE TRIGGER trg_users_identity_status_update_prd091
AFTER UPDATE OF status ON users FOR EACH ROW WHEN NEW.status!=OLD.status
BEGIN
  UPDATE global_accounts
  SET status=CASE WHEN login_enabled=1 THEN NEW.status ELSE status END,
      session_revision=session_revision+1,updated_at=NEW.updated_at
  WHERE account_id=(SELECT account_id FROM account_identity_links
    WHERE source_type=''legacy_user'' AND legacy_tenant_id=NEW.tenant_id
      AND legacy_user_id=NEW.user_id);
  UPDATE global_sessions
  SET status=''revoked'',revoked_at=NEW.updated_at,revoked_reason=''account_disabled'',
      updated_at=NEW.updated_at
  WHERE account_id=(SELECT account_id FROM account_identity_links
    WHERE source_type=''legacy_user'' AND legacy_tenant_id=NEW.tenant_id
      AND legacy_user_id=NEW.user_id) AND status=''active'' AND NEW.status=''disabled'';
END', '5b564799488a505831b99ff284b1a3d09d843638ef5d1adfa97a16f5acb9e7f9'),
('trg_users_projection_claim_validate_prd093', 'users', 'CREATE TRIGGER trg_users_projection_claim_validate_prd093
BEFORE INSERT ON users FOR EACH ROW
WHEN EXISTS(SELECT 1 FROM workspace_user_projection_claims c
    WHERE c.tenant_id=NEW.tenant_id AND c.legacy_user_id=NEW.user_id
      AND c.status=''pending'')
 AND NOT EXISTS(
    SELECT 1 FROM workspace_user_projection_claims c
    JOIN global_accounts a ON a.account_id=c.account_id
    JOIN account_credentials credential ON credential.account_id=a.account_id
      AND credential.credential_type=''password'' AND credential.status=''active''
    WHERE c.tenant_id=NEW.tenant_id AND c.legacy_user_id=NEW.user_id
      AND c.status=''pending'' AND c.expires_at>=strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'')
      AND c.credential_revision=a.credential_revision
      AND c.email_normalized=lower(trim(NEW.email))
      AND credential.secret_hash=NEW.password_hash
      AND a.status=''active'' AND a.login_enabled=1
      AND EXISTS(SELECT 1 FROM account_verifications verification
        WHERE verification.account_id=a.account_id)
 )
BEGIN SELECT RAISE(ABORT,''workspace_projection_claim_invalid''); END', '2b4babb327a171a45bb5bb5b50d550373aaad2949ef5ca16884f75a5dd57b8c6'),
('trg_users_role_owner_insert_prd059', 'users', 'CREATE TRIGGER trg_users_role_owner_insert_prd059
BEFORE INSERT ON users FOR EACH ROW
WHEN NOT EXISTS (
  SELECT 1 FROM roles role
  WHERE role.tenant_id=NEW.tenant_id AND role.code=NEW.role AND role.status=''active''
)
BEGIN SELECT RAISE(ABORT,''rbac_user_role_owner_mismatch''); END', 'de26a0c7a8cb2d0edf9858ed8a27198610c71e01ac634e923459603e7597a457'),
('trg_users_role_owner_update_prd059', 'users', 'CREATE TRIGGER trg_users_role_owner_update_prd059
BEFORE UPDATE OF tenant_id,role,status ON users FOR EACH ROW
WHEN NOT EXISTS (
