    OR(OLD.status=''verified'' AND NEW.status=''suspended''))
BEGIN SELECT RAISE(ABORT,''verified_domain_transition_invalid''); END', '7a2024118315af90692ecf915c8bff08a0d4c61246275edb710e5669eccd98ec'),
('trg_virtual_keys_scope_delete_prd075', 'virtual_keys', 'CREATE TRIGGER trg_virtual_keys_scope_delete_prd075
