BEGIN SELECT RAISE(ABORT,''experiment_scope_parent_immutable''); END', '7e93c2e8b7e29638b185531747a48ee2b7f1ae15a6aa9b7c9de9b7d03252f852'),
('trg_webhook_dead_letters_conflict_insert_prd057', 'webhook_dead_letter_events', 'CREATE TRIGGER trg_webhook_dead_letters_conflict_insert_prd057
BEFORE INSERT ON webhook_dead_letter_events FOR EACH ROW
