     OR (NEW.rowid!=-1 AND current.rowid=NEW.rowid)
)
BEGIN SELECT RAISE(ABORT,''webhook_dead_letter_immutable''); END', '4680f720b342d4730f297f8472c629b1a027b3899dca41a3cbf7b4fc8cc4e6b5'),
('trg_webhook_dead_letters_delete_prd057', 'webhook_dead_letter_events', 'CREATE TRIGGER trg_webhook_dead_letters_delete_prd057
BEFORE DELETE ON webhook_dead_letter_events FOR EACH ROW
BEGIN SELECT RAISE(ABORT,''webhook_dead_letter_immutable''); END', '5c43430167158b57d85294b07ff3f2a4dc5866b18ed147fdab7062d231fb14e5'),
('trg_webhook_dead_letters_identity_immutable_prd057', 'webhook_dead_letter_events', 'CREATE TRIGGER trg_webhook_dead_letters_identity_immutable_prd057
BEFORE UPDATE ON webhook_dead_letter_events FOR EACH ROW
WHEN NEW.dead_letter_event_id IS NOT OLD.dead_letter_event_id
