  OR NEW.webhook_endpoint_id IS NOT OLD.webhook_endpoint_id
  OR NEW.event_id IS NOT OLD.event_id OR NEW.event_type IS NOT OLD.event_type
  OR NEW.failure_error_code IS NOT OLD.failure_error_code
  OR NEW.failure_http_status IS NOT OLD.failure_http_status
  OR NEW.failed_at IS NOT OLD.failed_at OR NEW.expires_at IS NOT OLD.expires_at
  OR NEW.created_at IS NOT OLD.created_at
BEGIN SELECT RAISE(ABORT,''webhook_dead_letter_identity_immutable''); END', '60a4909850a925fb8ffd70488b1700a85016fb48e0ff9ff583f5459a33f74c36'),
('trg_webhook_dead_letters_owner_insert_prd057', 'webhook_dead_letter_events', 'CREATE TRIGGER trg_webhook_dead_letters_owner_insert_prd057
BEFORE INSERT ON webhook_dead_letter_events FOR EACH ROW
WHEN NEW.dead_letter_event_id!=''whdl_'' || substr(NEW.webhook_delivery_id,5)
  OR NOT EXISTS (
    SELECT 1 FROM webhook_deliveries source
    WHERE source.tenant_id=NEW.tenant_id
      AND source.webhook_delivery_id=NEW.webhook_delivery_id
      AND source.webhook_endpoint_id=NEW.webhook_endpoint_id
      AND source.event_id=NEW.event_id AND source.event_type=NEW.event_type
      AND source.status=''failed'' AND source.delivery_kind=''original''
  )
  OR (
    NEW.current_replay_delivery_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM webhook_deliveries replay
      WHERE replay.tenant_id=NEW.tenant_id
        AND replay.webhook_endpoint_id=NEW.webhook_endpoint_id
        AND replay.webhook_delivery_id=NEW.current_replay_delivery_id
        AND replay.delivery_kind=''replay''
        AND replay.replayed_from_delivery_id=NEW.webhook_delivery_id
        AND replay.event_id=NEW.event_id AND replay.event_type=NEW.event_type
        AND replay.replayed_by=NEW.replay_requested_by
        AND replay.replayed_at=NEW.replay_requested_at
        AND (
          (NEW.status=''replay_pending'' AND replay.status IN (''pending'',''success'',''failed''))
          OR (NEW.status=''replayed'' AND replay.status=''success'')
          OR (NEW.status=''dead_letter'' AND replay.status=''failed'')
          OR (NEW.status IN (''archived'',''expired'') AND (
            (replay.status=''success'' AND NEW.replayed_at IS NOT NULL)
            OR (replay.status=''failed'' AND NEW.replayed_at IS NULL)
          ))
        )
    )
  )
  OR (
    NEW.replay_requested_by IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM users actor
      WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.replay_requested_by
    )
  )
  OR (
    NEW.archived_by IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM users actor
      WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.archived_by
    )
  )
BEGIN SELECT RAISE(ABORT,''webhook_dead_letter_owner_mismatch''); END', '8bad7d1817e2183e4d55a4bf3596e10665ab8c61cc4211f55bd47fde8d75b9be'),
('trg_webhook_dead_letters_owner_update_prd057', 'webhook_dead_letter_events', 'CREATE TRIGGER trg_webhook_dead_letters_owner_update_prd057
BEFORE UPDATE ON webhook_dead_letter_events FOR EACH ROW
WHEN (
    NEW.current_replay_delivery_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM webhook_deliveries replay
      WHERE replay.tenant_id=NEW.tenant_id
        AND replay.webhook_endpoint_id=NEW.webhook_endpoint_id
        AND replay.webhook_delivery_id=NEW.current_replay_delivery_id
        AND replay.delivery_kind=''replay''
        AND replay.replayed_from_delivery_id=NEW.webhook_delivery_id
        AND replay.event_id=NEW.event_id AND replay.event_type=NEW.event_type
        AND replay.replayed_by=NEW.replay_requested_by
        AND replay.replayed_at=NEW.replay_requested_at
        AND (
          (NEW.status=''replay_pending'' AND replay.status IN (''pending'',''success'',''failed''))
          OR (NEW.status=''replayed'' AND replay.status=''success'')
          OR (NEW.status=''dead_letter'' AND replay.status=''failed'')
          OR (NEW.status IN (''archived'',''expired'') AND (
            (replay.status=''success'' AND NEW.replayed_at IS NOT NULL)
            OR (replay.status=''failed'' AND NEW.replayed_at IS NULL)
          ))
        )
    )
  )
  OR (
    NEW.replay_requested_by IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM users actor
      WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.replay_requested_by
    )
  )
  OR (
    NEW.archived_by IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM users actor
      WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.archived_by
    )
  )
BEGIN SELECT RAISE(ABORT,''webhook_dead_letter_owner_mismatch''); END', '2c6ab8ce9700150d4d19283113b77de89ad667bab81ad19806ebc55d868d2acd'),
('trg_webhook_dead_letters_rowid_insert_prd057', 'webhook_dead_letter_events', 'CREATE TRIGGER trg_webhook_dead_letters_rowid_insert_prd057
AFTER INSERT ON webhook_dead_letter_events FOR EACH ROW WHEN NEW.rowid<0
BEGIN SELECT RAISE(ABORT,''webhook_dead_letter_immutable''); END', 'febafa9906870604dd0057ee96b1d165fdce636fc13ebc6e0587a8afe3dd36cc'),
('trg_webhook_dead_letters_state_transition_prd057', 'webhook_dead_letter_events', 'CREATE TRIGGER trg_webhook_dead_letters_state_transition_prd057
BEFORE UPDATE OF status ON webhook_dead_letter_events FOR EACH ROW
WHEN NEW.status IS NOT OLD.status AND NOT (
  (OLD.status=''dead_letter'' AND NEW.status IN (''replay_pending'',''archived'',''expired''))
  OR (OLD.status=''replay_pending'' AND NEW.status IN (''replayed'',''dead_letter''))
  OR (OLD.status=''replayed'' AND NEW.status IN (''archived'',''expired''))
)
BEGIN SELECT RAISE(ABORT,''webhook_dead_letter_state_invalid''); END', 'da84f47a3bc6d4a00e4be12419c44904d1062a92e4087f3ea0424e901e64e52a'),
('trg_webhook_dead_letters_delivery_failed_insert_prd057', 'webhook_deliveries', 'CREATE TRIGGER trg_webhook_dead_letters_delivery_failed_insert_prd057
AFTER INSERT ON webhook_deliveries FOR EACH ROW
WHEN NEW.status=''failed'' AND NEW.delivery_kind=''original''
BEGIN
  -- 直接插入最终失败 delivery 时同样生成唯一根死信，保持两个写入入口事务语义一致。
  INSERT INTO webhook_dead_letter_events(
    dead_letter_event_id,tenant_id,webhook_delivery_id,webhook_endpoint_id,event_id,event_type,
    status,failure_error_code,failure_http_status,failed_at,expires_at,created_at,updated_at
  ) VALUES(
    ''whdl_'' || substr(NEW.webhook_delivery_id,5),NEW.tenant_id,NEW.webhook_delivery_id,
    NEW.webhook_endpoint_id,NEW.event_id,NEW.event_type,''dead_letter'',NEW.error_code,NEW.http_status,
    NEW.updated_at,strftime(''%Y-%m-%dT%H:%M:%SZ'',NEW.updated_at,''+30 days''),NEW.updated_at,NEW.updated_at
  );
END', '206cb2a22f05cfbcc16476a79907c91f55729d38ad564d21ab047830aaf858e6'),
('trg_webhook_dead_letters_delivery_failed_update_prd057', 'webhook_deliveries', 'CREATE TRIGGER trg_webhook_dead_letters_delivery_failed_update_prd057
AFTER UPDATE OF status ON webhook_deliveries FOR EACH ROW
WHEN NEW.status=''failed'' AND NEW.delivery_kind=''original'' AND OLD.status IS NOT NEW.status
BEGIN
  -- 更新终结路径只复制安全失败摘要和租户引用，不复制 Endpoint URL、Secret 或响应正文。
  INSERT INTO webhook_dead_letter_events(
    dead_letter_event_id,tenant_id,webhook_delivery_id,webhook_endpoint_id,event_id,event_type,
    status,failure_error_code,failure_http_status,failed_at,expires_at,created_at,updated_at
  ) VALUES(
    ''whdl_'' || substr(NEW.webhook_delivery_id,5),NEW.tenant_id,NEW.webhook_delivery_id,
    NEW.webhook_endpoint_id,NEW.event_id,NEW.event_type,''dead_letter'',NEW.error_code,NEW.http_status,
    NEW.updated_at,strftime(''%Y-%m-%dT%H:%M:%SZ'',NEW.updated_at,''+30 days''),NEW.updated_at,NEW.updated_at
  );
END', '6308d2d89ec9e4a2af5931d3812a757010859de46f3550767ca73620e9595a42'),
('trg_webhook_deliveries_prd042_owner_immutable', 'webhook_deliveries', 'CREATE TRIGGER trg_webhook_deliveries_prd042_owner_immutable
BEFORE UPDATE OF tenant_id, webhook_endpoint_id, delivery_kind,
  replayed_from_delivery_id, replay_idempotency_key, replayed_by, replayed_at
ON webhook_deliveries
FOR EACH ROW
WHEN
  NEW.tenant_id IS NOT OLD.tenant_id
  OR NEW.webhook_endpoint_id IS NOT OLD.webhook_endpoint_id
  OR NEW.delivery_kind IS NOT OLD.delivery_kind
  OR NEW.replayed_from_delivery_id IS NOT OLD.replayed_from_delivery_id
  OR NEW.replay_idempotency_key IS NOT OLD.replay_idempotency_key
  OR NEW.replayed_by IS NOT OLD.replayed_by
  OR NEW.replayed_at IS NOT OLD.replayed_at
BEGIN
  SELECT RAISE(ABORT, ''webhook_delivery_owner_immutable'');
END', 'b46aa517b0da16d8ab38ab6fd173eb9147268b16f3d3e32f331f4c3f994a793e'),
('trg_webhook_deliveries_prd042_owner_insert', 'webhook_deliveries', 'CREATE TRIGGER trg_webhook_deliveries_prd042_owner_insert
BEFORE INSERT ON webhook_deliveries
FOR EACH ROW
WHEN
  NOT EXISTS (
    SELECT 1 FROM webhook_endpoints e
    WHERE e.webhook_endpoint_id=NEW.webhook_endpoint_id AND e.tenant_id=NEW.tenant_id
  )
  OR (
    NEW.delivery_kind=''replay'' AND (
      NOT EXISTS (
        SELECT 1 FROM webhook_deliveries source
        WHERE source.webhook_delivery_id=NEW.replayed_from_delivery_id
          AND source.tenant_id=NEW.tenant_id
          AND source.webhook_endpoint_id=NEW.webhook_endpoint_id
      )
      OR NOT EXISTS (
        SELECT 1 FROM users u
        WHERE u.user_id=NEW.replayed_by AND u.tenant_id=NEW.tenant_id
      )
    )
  )
BEGIN
  SELECT RAISE(ABORT, ''webhook_delivery_owner_mismatch'');
END', '08571162e2f44f5a482d0fc8732762be12963579852169832819258510a13b31'),
('trg_webhook_deliveries_request_link_insert_prd054', 'webhook_deliveries', 'CREATE TRIGGER trg_webhook_deliveries_request_link_insert_prd054
AFTER INSERT ON webhook_deliveries
FOR EACH ROW
BEGIN
  -- 原始投递只有在 payload 白名单和同租户请求归属同时成立时才建立可解释性关联。
  INSERT INTO request_webhook_delivery_links(
    request_webhook_delivery_link_id, tenant_id, source_request_id,
    webhook_delivery_id, event_id, event_type, delivery_kind, created_at
  )
  SELECT
    ''rwdl_'' || lower(hex(randomblob(16))),
    NEW.tenant_id,
    extracted.source_request_id,
    NEW.webhook_delivery_id,
    NEW.event_id,
    NEW.event_type,
    NEW.delivery_kind,
    NEW.created_at
  FROM (
    SELECT CASE
      WHEN json_type(NEW.payload_json, ''$.payload.source_request_id'')=''text''
        AND (
          (
            NEW.event_type=''request.explanation_viewed''
            AND EXISTS (
              SELECT 1 FROM request_explanations explanation
              WHERE explanation.tenant_id=NEW.tenant_id
                AND explanation.event_id=NEW.event_id
                AND explanation.request_explanation_id=
                    json_extract(NEW.payload_json, ''$.object_id'')
                AND explanation.request_explanation_id=
                    json_extract(NEW.payload_json, ''$.payload.request_explanation_id'')
                AND explanation.source_request_id=
                    json_extract(NEW.payload_json, ''$.payload.source_request_id'')
            )
          )
          OR (
            NEW.event_type=''ledger.entry_created''
            AND EXISTS (
              SELECT 1 FROM finops_ledger_entries entry
              WHERE entry.tenant_id=NEW.tenant_id
                AND entry.event_id=NEW.event_id
                AND entry.finops_ledger_entry_id=
                    json_extract(NEW.payload_json, ''$.object_id'')
                AND entry.finops_ledger_entry_id=
                    json_extract(NEW.payload_json, ''$.payload.ledger_entry_id'')
                AND entry.source_request_id=
                    json_extract(NEW.payload_json, ''$.payload.source_request_id'')
            )
          )
        )
        THEN json_extract(NEW.payload_json, ''$.payload.source_request_id'')
      WHEN json_type(NEW.payload_json, ''$.payload.request_id'')=''text''
        AND (
          NEW.event_type IN (
            ''gateway.request_failed'', ''security.dlp_matched'', ''security.dlp_unavailable'',
            ''usage.normalized'', ''stream.timeout'', ''route.fallback_triggered'',
            ''budget.threshold_reached'', ''budget.exhausted'', ''budget.scope_exceeded'',
            ''budget.blocked'', ''budget.unblocked''
          )
          OR (
            NEW.event_type IN (''route.policy_selected'', ''cache.affinity_selected'')
            AND json_extract(NEW.payload_json, ''$.payload.trigger'')=''request_selected''
          )
        )
        THEN json_extract(NEW.payload_json, ''$.payload.request_id'')
      ELSE NULL
    END AS source_request_id
  ) extracted
  WHERE NEW.delivery_kind=''original''
    AND json_valid(NEW.payload_json)
    AND typeof(extracted.source_request_id)=''text''
    AND length(extracted.source_request_id) BETWEEN 1 AND 128
    AND extracted.source_request_id NOT GLOB ''*[^A-Za-z0-9_.:-]*''
    AND EXISTS (
      SELECT 1 FROM request_logs request
      WHERE request.tenant_id=NEW.tenant_id
        AND request.request_id=extracted.source_request_id
    );

  -- 重放投递只能继承同租户原始关联，禁止重新解析任意 payload 来伪造来源请求。
  INSERT INTO request_webhook_delivery_links(
    request_webhook_delivery_link_id, tenant_id, source_request_id,
    webhook_delivery_id, event_id, event_type, delivery_kind, created_at
  )
  SELECT
    ''rwdl_'' || lower(hex(randomblob(16))),
    NEW.tenant_id,
    source.source_request_id,
    NEW.webhook_delivery_id,
    NEW.event_id,
    NEW.event_type,
    NEW.delivery_kind,
    NEW.created_at
  FROM request_webhook_delivery_links source
  WHERE NEW.delivery_kind=''replay''
    AND source.tenant_id=NEW.tenant_id
    AND source.webhook_delivery_id=NEW.replayed_from_delivery_id;
END', '4c888c96cc3745bff4f3aaa99867ad0979b5a3fd7381644f87ee5605a05eac12'),
('trg_webhook_deliveries_siem_immutable_prd081', 'webhook_deliveries', 'CREATE TRIGGER trg_webhook_deliveries_siem_immutable_prd081
BEFORE UPDATE OF event_id,event_type,event_timestamp,payload_json,payload_format,
  wire_body_text,security_event_rate_limit_per_minute
ON webhook_deliveries FOR EACH ROW
WHEN NEW.event_id IS NOT OLD.event_id OR NEW.event_type IS NOT OLD.event_type
  OR NEW.event_timestamp IS NOT OLD.event_timestamp
  OR NEW.payload_json IS NOT OLD.payload_json OR NEW.payload_format IS NOT OLD.payload_format
  OR (NEW.wire_body_text IS NOT OLD.wire_body_text
    AND NOT (OLD.payload_format=''json'' AND OLD.wire_body_text=''''
      AND NEW.wire_body_text=OLD.payload_json))
  OR NEW.security_event_rate_limit_per_minute IS NOT OLD.security_event_rate_limit_per_minute
BEGIN SELECT RAISE(ABORT,''webhook_delivery_wire_immutable''); END', '32e6740287481334978d31b5d579e219a81f4cb9c72e024591d8d25dde0c2d4e'),
('trg_webhook_deliveries_siem_insert_prd081', 'webhook_deliveries', 'CREATE TRIGGER trg_webhook_deliveries_siem_insert_prd081
BEFORE INSERT ON webhook_deliveries FOR EACH ROW
WHEN NOT json_valid(NEW.payload_json) OR json_type(NEW.payload_json)!=''object''
  OR (NEW.payload_format=''json''
    AND NEW.wire_body_text NOT IN(NEW.payload_json,''''))
  OR (NEW.payload_format=''cef'' AND (
    NEW.event_type NOT IN(''security.event_pushed'',''webhook.test'')
    OR length(CAST(NEW.wire_body_text AS BLOB)) NOT BETWEEN 1 AND 16384
    OR instr(NEW.wire_body_text,char(10))!=0 OR instr(NEW.wire_body_text,char(13))!=0
    OR substr(NEW.wire_body_text,1,length(''CEF:0|MetaHub|AI Gateway|1|''))
      !=''CEF:0|MetaHub|AI Gateway|1|''
  ))
  OR (NEW.delivery_kind=''original'' AND NOT EXISTS(
    SELECT 1 FROM webhook_endpoints endpoint
    WHERE endpoint.tenant_id=NEW.tenant_id
      AND endpoint.webhook_endpoint_id=NEW.webhook_endpoint_id
      AND endpoint.payload_format=NEW.payload_format
      AND endpoint.security_event_rate_limit_per_minute=
          NEW.security_event_rate_limit_per_minute
  ))
  OR (NEW.delivery_kind=''replay'' AND NOT EXISTS(
    SELECT 1 FROM webhook_deliveries source
    WHERE source.tenant_id=NEW.tenant_id
      AND source.webhook_endpoint_id=NEW.webhook_endpoint_id
      AND source.webhook_delivery_id=NEW.replayed_from_delivery_id
      AND source.event_id=NEW.event_id AND source.event_type=NEW.event_type
      AND source.event_timestamp=NEW.event_timestamp
      AND source.payload_json=NEW.payload_json
      AND source.payload_format=NEW.payload_format
      AND source.wire_body_text=NEW.wire_body_text
      AND source.security_event_rate_limit_per_minute=
          NEW.security_event_rate_limit_per_minute
  ))
BEGIN SELECT RAISE(ABORT,''webhook_delivery_wire_invalid''); END', '248035d98700fa21bbe2c98b23fcb2830c17387ec7f8bd8ac0fe8f6958f00bc8'),
('trg_webhook_deliveries_siem_legacy_fill_prd081', 'webhook_deliveries', 'CREATE TRIGGER trg_webhook_deliveries_siem_legacy_fill_prd081
