  OR NEW.tag_code!=OLD.tag_code OR NEW.created_by_operator_id!=OLD.created_by_operator_id
  OR NEW.created_at!=OLD.created_at OR NEW.revision!=OLD.revision+1
  OR NEW.status=OLD.status OR unixepoch(NEW.updated_at)<unixepoch(OLD.updated_at)
BEGIN SELECT RAISE(ABORT,''workspace_risk_transition_invalid''); END', 'c3af2ddab00deb65fc89cb0d941a4acc4cd6df7980d39c0852b5e0b1d8ad3d19'),
('trg_workspace_session_operational_insert_prd096', 'workspace_sessions', 'CREATE TRIGGER trg_workspace_session_operational_insert_prd096
BEFORE INSERT ON workspace_sessions FOR EACH ROW
WHEN NEW.status=''active'' AND NOT EXISTS(
