BEGIN SELECT RAISE(ABORT,''workspace_operational_inactive''); END', '3b155aa1c0d209713a54788135a69c411d43c814ac9109382fae828805d102fb'),
('trg_workspace_session_operational_update_prd096', 'workspace_sessions', 'CREATE TRIGGER trg_workspace_session_operational_update_prd096
BEFORE UPDATE ON workspace_sessions FOR EACH ROW
WHEN NEW.status=''active'' AND NOT EXISTS(
  SELECT 1 FROM workspace_operational_states state
