BEGIN;
SET LOCAL client_min_messages = warning;
-- SQLite row guards and side effects translated to native trigger functions.
CREATE OR REPLACE FUNCTION "fn_trg_tenants_default_environment"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  INSERT INTO environments( environment_id, tenant_id, code, name, description, status, created_by, updated_by, created_at, updated_at ) VALUES( 'env_' || lower(hex(randomblob(16))), NEW.tenant_id, 'dev', '开发环境', '租户创建时自动生成的默认开发环境。', 'active', NULL, NULL, strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), strftime('%Y-%m-%dT%H:%M:%SZ', 'now') ) ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_tenants_default_environment" AFTER INSERT ON "tenants" FOR EACH ROW EXECUTE FUNCTION "fn_trg_tenants_default_environment"();
CREATE OR REPLACE FUNCTION "fn_trg_budget_block_events_owner_insert"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM budget_blocks b WHERE b.budget_block_id=NEW.budget_block_id AND b.tenant_id=NEW.tenant_id AND b.environment_id=NEW.environment_id AND b.budget_rule_id=NEW.budget_rule_id )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='budget_block_event_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_budget_block_events_owner_insert" BEFORE INSERT ON "budget_block_events" FOR EACH ROW EXECUTE FUNCTION "fn_trg_budget_block_events_owner_insert"();
CREATE OR REPLACE FUNCTION "fn_trg_budget_block_events_owner_update"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM budget_blocks b WHERE b.budget_block_id=NEW.budget_block_id AND b.tenant_id=NEW.tenant_id AND b.environment_id=NEW.environment_id AND b.budget_rule_id=NEW.budget_rule_id )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='budget_block_event_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_budget_block_events_owner_update" BEFORE UPDATE OF "tenant_id", "environment_id", "budget_block_id", "budget_rule_id" ON "budget_block_events" FOR EACH ROW EXECUTE FUNCTION "fn_trg_budget_block_events_owner_update"();
CREATE OR REPLACE FUNCTION "fn_trg_budget_reservations_owner_insert"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM budget_rules r JOIN environments e ON e.environment_id=r.environment_id AND e.tenant_id=r.tenant_id WHERE r.budget_rule_id=NEW.budget_rule_id AND r.tenant_id=NEW.tenant_id AND r.environment_id=NEW.environment_id )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='budget_reservation_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_budget_reservations_owner_insert" BEFORE INSERT ON "budget_reservations" FOR EACH ROW EXECUTE FUNCTION "fn_trg_budget_reservations_owner_insert"();
CREATE OR REPLACE FUNCTION "fn_trg_budget_reservations_owner_update"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM budget_rules r JOIN environments e ON e.environment_id=r.environment_id AND e.tenant_id=r.tenant_id WHERE r.budget_rule_id=NEW.budget_rule_id AND r.tenant_id=NEW.tenant_id AND r.environment_id=NEW.environment_id )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='budget_reservation_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_budget_reservations_owner_update" BEFORE UPDATE OF "tenant_id", "environment_id", "budget_rule_id" ON "budget_reservations" FOR EACH ROW EXECUTE FUNCTION "fn_trg_budget_reservations_owner_update"();
CREATE OR REPLACE FUNCTION "fn_trg_provider_health_log_tenant_insert"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF NOT EXISTS ( SELECT 1 FROM providers p WHERE p.provider_id=NEW.provider_id AND p.tenant_id=NEW.tenant_id ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='provider_health_tenant_mismatch';
  END IF;
  IF NEW.provider_credential_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM provider_credentials c WHERE c.provider_credential_id=NEW.provider_credential_id AND c.provider_id=NEW.provider_id AND c.tenant_id=NEW.tenant_id ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='provider_health_credential_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_provider_health_log_tenant_insert" BEFORE INSERT ON "provider_health_probe_logs" FOR EACH ROW EXECUTE FUNCTION "fn_trg_provider_health_log_tenant_insert"();
CREATE OR REPLACE FUNCTION "fn_trg_fallback_policy_tenant_insert"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM model_aliases a WHERE a.model_alias_id=NEW.model_alias_id AND a.tenant_id=NEW.tenant_id )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='fallback_policy_tenant_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_fallback_policy_tenant_insert" BEFORE INSERT ON "fallback_policies" FOR EACH ROW EXECUTE FUNCTION "fn_trg_fallback_policy_tenant_insert"();
CREATE OR REPLACE FUNCTION "fn_trg_fallback_policy_tenant_update"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM model_aliases a WHERE a.model_alias_id=NEW.model_alias_id AND a.tenant_id=NEW.tenant_id )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='fallback_policy_tenant_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_fallback_policy_tenant_update" BEFORE UPDATE OF "tenant_id", "model_alias_id" ON "fallback_policies" FOR EACH ROW EXECUTE FUNCTION "fn_trg_fallback_policy_tenant_update"();
CREATE OR REPLACE FUNCTION "fn_trg_routing_attempt_tenant_insert"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF NOT EXISTS ( SELECT 1 FROM models m WHERE m.model_id=NEW.model_id AND m.tenant_id=NEW.tenant_id ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='routing_attempt_model_tenant_mismatch';
  END IF;
  IF NOT EXISTS ( SELECT 1 FROM providers p WHERE p.provider_id=NEW.provider_id AND p.tenant_id=NEW.tenant_id ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='routing_attempt_provider_tenant_mismatch';
  END IF;
  IF NEW.model_alias_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM model_aliases a WHERE a.model_alias_id=NEW.model_alias_id AND a.tenant_id=NEW.tenant_id ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='routing_attempt_alias_tenant_mismatch';
  END IF;
