CREATE OR REPLACE FUNCTION "fn_trg_policy_snapshots_sequence_insert"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.state <> 'building' OR ( NEW.snapshot_version = 1 AND EXISTS ( SELECT 1 FROM policy_snapshot_heads h WHERE h.tenant_id = NEW.tenant_id ) ) OR ( NEW.snapshot_version > 1 AND NOT EXISTS ( SELECT 1 FROM policy_snapshot_heads h WHERE h.tenant_id = NEW.tenant_id AND h.current_snapshot_id = NEW.previous_snapshot_id AND h.current_snapshot_version = NEW.previous_snapshot_version ) ) OR ( NEW.operation = 'rollback' AND NOT EXISTS ( SELECT 1 FROM policy_snapshot_heads h JOIN policy_snapshots current_snapshot ON current_snapshot.tenant_id = h.tenant_id AND current_snapshot.policy_snapshot_id = h.current_snapshot_id AND current_snapshot.snapshot_version = h.current_snapshot_version WHERE h.tenant_id = NEW.tenant_id AND current_snapshot.previous_snapshot_id = NEW.rollback_source_snapshot_id AND current_snapshot.previous_snapshot_version = NEW.rollback_source_snapshot_version ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='policy_snapshot_sequence_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
