CREATE OR REPLACE FUNCTION "fn_trg_policy_snapshot_items_publish_insert"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (EXISTS ( SELECT 1 FROM policy_snapshots snapshot WHERE snapshot.tenant_id = NEW.tenant_id AND snapshot.policy_snapshot_id = NEW.policy_snapshot_id AND snapshot.operation = 'publish' ) AND NOT EXISTS ( SELECT 1 FROM policies p JOIN policy_rules r ON r.tenant_id = p.tenant_id AND r.policy_id = p.policy_id JOIN policy_actions a ON a.tenant_id = p.tenant_id AND a.policy_id = p.policy_id WHERE p.tenant_id = NEW.tenant_id AND p.policy_id = NEW.source_policy_id AND p.status = 'active' AND p.version = NEW.source_policy_version AND p.priority = NEW.priority AND p.dsl_version = NEW.dsl_version AND r.policy_rule_id = NEW.policy_rule_id AND r.condition_hash = NEW.condition_hash AND metahub_json(r.variables_json) = metahub_json(NEW.variables_json) AND a.policy_action_id = NEW.policy_action_id AND a.action_type = NEW.action_type AND a.target_model_id IS NOT DISTINCT FROM NEW.target_model_id )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='policy_snapshot_item_source_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
