LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (EXISTS ( SELECT 1 FROM policy_snapshots snapshot WHERE snapshot.tenant_id = NEW.tenant_id AND snapshot.policy_snapshot_id = NEW.policy_snapshot_id AND snapshot.operation = 'rollback' ) AND NOT EXISTS ( SELECT 1 FROM policy_snapshots snapshot JOIN policy_snapshot_items source ON source.tenant_id = snapshot.tenant_id AND source.policy_snapshot_id = snapshot.rollback_source_snapshot_id WHERE snapshot.tenant_id = NEW.tenant_id AND snapshot.policy_snapshot_id = NEW.policy_snapshot_id AND source.evaluation_order = NEW.evaluation_order AND source.source_policy_id = NEW.source_policy_id AND source.source_policy_version = NEW.source_policy_version AND source.policy_rule_id = NEW.policy_rule_id AND source.policy_action_id = NEW.policy_action_id AND source.priority = NEW.priority AND source.dsl_version = NEW.dsl_version AND source.canonical_expression = NEW.canonical_expression AND source.condition_hash = NEW.condition_hash AND metahub_json(source.variables_json) = metahub_json(NEW.variables_json) AND source.action_type = NEW.action_type AND source.target_model_id IS NOT DISTINCT FROM NEW.target_model_id )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='policy_snapshot_rollback_item_mismatch';
  END IF;
  RETURN NEW;
