LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT ( OLD.state = 'building' AND NEW.state = 'published' AND NEW.policy_snapshot_id IS NOT DISTINCT FROM OLD.policy_snapshot_id AND NEW.tenant_id IS NOT DISTINCT FROM OLD.tenant_id AND NEW.snapshot_version IS NOT DISTINCT FROM OLD.snapshot_version AND NEW.schema_version IS NOT DISTINCT FROM OLD.schema_version AND NEW.operation IS NOT DISTINCT FROM OLD.operation AND NEW.previous_snapshot_id IS NOT DISTINCT FROM OLD.previous_snapshot_id AND NEW.previous_snapshot_version IS NOT DISTINCT FROM OLD.previous_snapshot_version AND NEW.rollback_source_snapshot_id IS NOT DISTINCT FROM OLD.rollback_source_snapshot_id AND NEW.rollback_source_snapshot_version IS NOT DISTINCT FROM OLD.rollback_source_snapshot_version AND NEW.request_id IS NOT DISTINCT FROM OLD.request_id AND NEW.trace_id IS NOT DISTINCT FROM OLD.trace_id AND NEW.request_fingerprint IS NOT DISTINCT FROM OLD.request_fingerprint AND NEW.change_reason IS NOT DISTINCT FROM OLD.change_reason AND NEW.approval_status IS NOT DISTINCT FROM OLD.approval_status AND NEW.created_by IS NOT DISTINCT FROM OLD.created_by AND NEW.created_at IS NOT DISTINCT FROM OLD.created_at AND NEW.policy_count = ( SELECT COUNT(*) FROM policy_snapshot_items item WHERE item.tenant_id = OLD.tenant_id AND item.policy_snapshot_id = OLD.policy_snapshot_id ) AND ( NEW.policy_count = 0 OR ( (SELECT MIN(item.evaluation_order) FROM policy_snapshot_items item WHERE item.tenant_id = OLD.tenant_id AND item.policy_snapshot_id = OLD.policy_snapshot_id) = 0 AND (SELECT MAX(item.evaluation_order) FROM policy_snapshot_items item WHERE item.tenant_id = OLD.tenant_id AND item.policy_snapshot_id = OLD.policy_snapshot_id) = NEW.policy_count - 1 AND (SELECT COUNT(DISTINCT item.evaluation_order) FROM policy_snapshot_items item WHERE item.tenant_id = OLD.tenant_id AND item.policy_snapshot_id = OLD.policy_snapshot_id) = NEW.policy_count ) ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='policy_snapshot_immutable';
  END IF;
  RETURN NEW;
END;
$trigger$;
