  IF (NOT ( ( NEW.sample_count=OLD.sample_count+1 AND NEW.statistics_version=OLD.statistics_version+1 AND ( (NEW.success_count=OLD.success_count+1 AND NEW.error_count=OLD.error_count) OR (NEW.success_count=OLD.success_count AND NEW.error_count=OLD.error_count+1) ) AND ( (NEW.latency_sample_count=OLD.latency_sample_count AND NEW.total_latency_ms=OLD.total_latency_ms) OR (NEW.latency_sample_count=OLD.latency_sample_count+1 AND NEW.total_latency_ms>=OLD.total_latency_ms) ) AND NEW.feedback_version=OLD.feedback_version AND NEW.manual_quality_bps IS NOT DISTINCT FROM OLD.manual_quality_bps AND NEW.feedback_updated_by IS NOT DISTINCT FROM OLD.feedback_updated_by AND NEW.feedback_updated_at IS NOT DISTINCT FROM OLD.feedback_updated_at AND NEW.first_observed_at IS NOT NULL AND NEW.last_observed_at IS NOT NULL AND NEW.first_observed_at<=NEW.last_observed_at AND ( (OLD.sample_count=0 AND NEW.first_observed_at=NEW.last_observed_at) OR ( OLD.sample_count>0 AND NEW.first_observed_at<=OLD.first_observed_at AND NEW.last_observed_at>=OLD.last_observed_at AND ( NEW.first_observed_at=OLD.first_observed_at OR NEW.last_observed_at=OLD.last_observed_at ) ) ) AND NEW.updated_at>=OLD.updated_at AND ( NEW.updated_at=OLD.updated_at OR NEW.updated_at=NEW.last_observed_at ) ) OR ( NEW.sample_count=OLD.sample_count AND NEW.success_count=OLD.success_count AND NEW.error_count=OLD.error_count AND NEW.latency_sample_count=OLD.latency_sample_count AND NEW.total_latency_ms=OLD.total_latency_ms AND NEW.statistics_version=OLD.statistics_version AND NEW.first_observed_at IS NOT DISTINCT FROM OLD.first_observed_at AND NEW.last_observed_at IS NOT DISTINCT FROM OLD.last_observed_at AND NEW.feedback_version=OLD.feedback_version+1 AND NEW.manual_quality_bps IS DISTINCT FROM OLD.manual_quality_bps AND NEW.feedback_updated_by IS NOT NULL AND NEW.feedback_updated_at IS NOT NULL ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='model_quality_score_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
