LANGUAGE plpgsql AS $trigger$
BEGIN
  IF NEW.alias IS DISTINCT FROM OLD.alias OR NEW.environment IS DISTINCT FROM OLD.environment OR NEW.environment_id IS DISTINCT FROM OLD.environment_id OR NEW.status IS DISTINCT FROM OLD.status OR NEW.default_model_id IS DISTINCT FROM OLD.default_model_id OR NEW.fallback_model_id IS DISTINCT FROM OLD.fallback_model_id THEN
