CREATE OR REPLACE FUNCTION "fn_trg_routing_decisions_prd048_owner_update"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF ((NEW.virtual_key_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM virtual_keys vk WHERE vk.tenant_id=NEW.tenant_id AND vk.virtual_key_id=NEW.virtual_key_id AND ( (vk.environment_id IS NOT NULL AND vk.environment_id=NEW.environment_id) OR (vk.environment_id IS NULL AND vk.environment=NEW.environment AND EXISTS ( SELECT 1 FROM environments ve WHERE ve.tenant_id=NEW.tenant_id AND ve.environment_id=NEW.environment_id AND ve.code=NEW.environment )) ) )) OR (NEW.environment_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM environments e WHERE e.tenant_id=NEW.tenant_id AND e.environment_id=NEW.environment_id AND e.code=NEW.environment )) OR (NEW.model_alias_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM model_aliases a WHERE a.tenant_id=NEW.tenant_id AND a.model_alias_id=NEW.model_alias_id AND a.environment_id IS NOT DISTINCT FROM NEW.environment_id )) OR ((NEW.selected_model_id IS NULL)<>(NEW.provider_id IS NULL)) OR (NEW.selected_model_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM models m WHERE m.tenant_id=NEW.tenant_id AND m.model_id=NEW.selected_model_id AND m.provider_id=NEW.provider_id )) OR (NEW.routing_policy_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM model_alias_routing_policies rp WHERE rp.tenant_id=NEW.tenant_id AND rp.routing_policy_id=NEW.routing_policy_id AND rp.model_alias_id=NEW.model_alias_id AND rp.version=NEW.routing_policy_version AND rp.routing_mode=NEW.routing_mode AND ( NEW.quality_weight_bps IS NULL OR ( NEW.routing_mode='quality_cost' AND rp.quality_weight_bps=NEW.quality_weight_bps AND rp.cost_weight_bps=NEW.cost_weight_bps AND rp.latency_weight_bps=NEW.latency_weight_bps AND rp.quality_floor_bps=NEW.quality_floor_bps AND rp.minimum_sample_count=NEW.minimum_sample_count ) ) ))) THEN
