LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.payload_schema_version<>2) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='routing_policy_event_schema_version_invalid';
  END IF;
  RETURN NEW;
