$trigger$;
CREATE TRIGGER "trg_routing_policy_events_prd048_schema_insert" BEFORE INSERT ON "routing_policy_events" FOR EACH ROW EXECUTE FUNCTION "fn_trg_routing_policy_events_prd048_schema_insert"();
CREATE OR REPLACE FUNCTION "fn_trg_routing_policy_events_prd048_payload_insert"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.payload_schema_version=2 AND ((CASE WHEN EXISTS ( SELECT 1 FROM json_each(NEW.payload_json, '$.change_kinds') item WHERE item.type<>'text' OR item.value NOT IN ('created', 'mode', 'quality_cost', 'candidates', 'alias_state') ) THEN 1 WHEN EXISTS ( SELECT 1 FROM json_each(NEW.payload_json, '$.changed_routing_fields') item WHERE item.type<>'text' OR item.value NOT IN ( 'alias', 'environment', 'environment_id', 'status', 'default_model_id', 'fallback_model_id', 'routing_mode', 'quality_cost_config' ) ) THEN 1 WHEN EXISTS ( SELECT 1 FROM json_each(NEW.payload_json, '$.change_kinds') earlier JOIN json_each(NEW.payload_json, '$.change_kinds') later ON CAST(earlier.key AS INTEGER)<CAST(later.key AS INTEGER) WHERE CASE earlier.value WHEN 'created' THEN 0 WHEN 'mode' THEN 1 WHEN 'quality_cost' THEN 2 WHEN 'candidates' THEN 3 WHEN 'alias_state' THEN 4 ELSE 99 END >= CASE later.value WHEN 'created' THEN 0 WHEN 'mode' THEN 1 WHEN 'quality_cost' THEN 2 WHEN 'candidates' THEN 3 WHEN 'alias_state' THEN 4 ELSE 99 END ) THEN 1 WHEN EXISTS ( SELECT 1 FROM json_each(NEW.payload_json, '$.changed_routing_fields') earlier JOIN json_each(NEW.payload_json, '$.changed_routing_fields') later ON CAST(earlier.key AS INTEGER)<CAST(later.key AS INTEGER) WHERE CASE earlier.value WHEN 'alias' THEN 0 WHEN 'environment' THEN 1 WHEN 'environment_id' THEN 2 WHEN 'status' THEN 3 WHEN 'default_model_id' THEN 4 WHEN 'fallback_model_id' THEN 5 WHEN 'routing_mode' THEN 6 WHEN 'quality_cost_config' THEN 7 ELSE 99 END >= CASE later.value WHEN 'alias' THEN 0 WHEN 'environment' THEN 1 WHEN 'environment_id' THEN 2 WHEN 'status' THEN 3 WHEN 'default_model_id' THEN 4 WHEN 'fallback_model_id' THEN 5 WHEN 'routing_mode' THEN 6 WHEN 'quality_cost_config' THEN 7 ELSE 99 END ) THEN 1 WHEN EXISTS ( SELECT 1 FROM json_each(NEW.payload_json, '$.change_kinds') WHERE value='created' ) THEN CASE WHEN NEW.routing_policy_version<>1 THEN 1 WHEN json_type(NEW.payload_json, '$.previous_mode') IS DISTINCT FROM 'null' THEN 1 WHEN json_array_length(NEW.payload_json, '$.change_kinds')<>1 THEN 1 WHEN json_array_length(NEW.payload_json, '$.changed_routing_fields')<>8 THEN 1 ELSE 0 END WHEN json_type(NEW.payload_json, '$.previous_mode') IS NOT DISTINCT FROM 'null' THEN 1 WHEN ( EXISTS (SELECT 1 FROM json_each(NEW.payload_json, '$.change_kinds') WHERE value='mode') <> EXISTS (SELECT 1 FROM json_each(NEW.payload_json, '$.changed_routing_fields') WHERE value='routing_mode') ) THEN 1 WHEN ( EXISTS (SELECT 1 FROM json_each(NEW.payload_json, '$.change_kinds') WHERE value='quality_cost') <> EXISTS (SELECT 1 FROM json_each(NEW.payload_json, '$.changed_routing_fields') WHERE value='quality_cost_config') ) THEN 1 WHEN ( EXISTS (SELECT 1 FROM json_each(NEW.payload_json, '$.change_kinds') WHERE value='candidates') <> EXISTS (SELECT 1 FROM json_each(NEW.payload_json, '$.changed_routing_fields') WHERE value IN ('default_model_id', 'fallback_model_id')) ) THEN 1 WHEN ( EXISTS (SELECT 1 FROM json_each(NEW.payload_json, '$.change_kinds') WHERE value='alias_state') <> EXISTS (SELECT 1 FROM json_each(NEW.payload_json, '$.changed_routing_fields') WHERE value IN ('alias', 'environment', 'environment_id', 'status')) ) THEN 1 WHEN EXISTS ( SELECT 1 FROM json_each(NEW.payload_json, '$.change_kinds') WHERE value='mode' ) AND json_extract(NEW.payload_json, '$.previous_mode') IS NOT DISTINCT FROM json_extract(NEW.payload_json, '$.routing_mode') THEN 1 WHEN NOT EXISTS ( SELECT 1 FROM json_each(NEW.payload_json, '$.change_kinds') WHERE value='mode' ) AND json_extract(NEW.payload_json, '$.previous_mode') IS DISTINCT FROM json_extract(NEW.payload_json, '$.routing_mode') THEN 1 ELSE 0 END)<>0)) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='routing_policy_event_payload_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_routing_policy_events_prd048_payload_insert" BEFORE INSERT ON "routing_policy_events" FOR EACH ROW EXECUTE FUNCTION "fn_trg_routing_policy_events_prd048_payload_insert"();
CREATE OR REPLACE FUNCTION "fn_trg_routing_policy_events_prd048_graph_insert"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
