  IF (NOT EXISTS ( SELECT 1 FROM model_alias_routing_policies rp WHERE rp.tenant_id=NEW.tenant_id AND rp.routing_policy_id=NEW.routing_policy_id AND rp.model_alias_id=NEW.model_alias_id AND rp.version=NEW.routing_policy_version AND rp.routing_mode=json_extract(NEW.payload_json, '$.routing_mode') AND rp.quality_weight_bps= (json_extract(NEW.payload_json, '$.quality_cost_config.quality_weight_bps'))::NUMERIC AND rp.cost_weight_bps= (json_extract(NEW.payload_json, '$.quality_cost_config.cost_weight_bps'))::NUMERIC AND rp.latency_weight_bps= (json_extract(NEW.payload_json, '$.quality_cost_config.latency_weight_bps'))::NUMERIC AND rp.quality_floor_bps= (json_extract(NEW.payload_json, '$.quality_cost_config.quality_floor_bps'))::NUMERIC AND rp.minimum_sample_count= (json_extract(NEW.payload_json, '$.quality_cost_config.minimum_sample_count'))::NUMERIC )) THEN
