CREATE OR REPLACE FUNCTION "fn_trg_request_feedback_tags_insert_prd049"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (EXISTS ( SELECT 1 FROM json_each(NEW.tags_json) item WHERE item.type<>'text' OR item.value NOT IN ( 'accurate', 'relevant', 'complete', 'helpful', 'clear', 'inaccurate', 'irrelevant', 'incomplete', 'unsafe', 'slow' ) ) OR (SELECT COUNT(*) FROM json_each(NEW.tags_json)) <> (SELECT COUNT(DISTINCT value) FROM json_each(NEW.tags_json)) OR NEW.tags_json <> COALESCE(( SELECT json_group_array(value) FROM ( SELECT value FROM json_each(NEW.tags_json) ORDER BY CASE value WHEN 'accurate' THEN 1 WHEN 'relevant' THEN 2 WHEN 'complete' THEN 3 WHEN 'helpful' THEN 4 WHEN 'clear' THEN 5 WHEN 'inaccurate' THEN 6 WHEN 'irrelevant' THEN 7 WHEN 'incomplete' THEN 8 WHEN 'unsafe' THEN 9 WHEN 'slow' THEN 10 ELSE 99 END ) ), '[]') OR ( EXISTS (SELECT 1 FROM json_each(NEW.tags_json) WHERE value='accurate') AND EXISTS (SELECT 1 FROM json_each(NEW.tags_json) WHERE value='inaccurate') ) OR ( EXISTS (SELECT 1 FROM json_each(NEW.tags_json) WHERE value='relevant') AND EXISTS (SELECT 1 FROM json_each(NEW.tags_json) WHERE value='irrelevant') ) OR ( EXISTS (SELECT 1 FROM json_each(NEW.tags_json) WHERE value='complete') AND EXISTS (SELECT 1 FROM json_each(NEW.tags_json) WHERE value='incomplete') )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='request_feedback_tags_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
