CREATE OR REPLACE FUNCTION "fn_trg_model_feedback_statistics_validate_insert_prd049"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (EXISTS ( SELECT 1 FROM model_feedback_statistics current WHERE current.tenant_id=NEW.tenant_id AND current.model_id=NEW.model_id ) OR NEW.feedback_count IS DISTINCT FROM ( SELECT COUNT(*) FROM request_feedbacks source WHERE source.tenant_id=NEW.tenant_id AND source.model_id=NEW.model_id ) OR NEW.rating_sum IS DISTINCT FROM ( SELECT COALESCE(SUM(rating), 0) FROM request_feedbacks source WHERE source.tenant_id=NEW.tenant_id AND source.model_id=NEW.model_id ) OR NEW.rating_1_count IS DISTINCT FROM ( SELECT COUNT(*) FROM request_feedbacks source WHERE source.tenant_id=NEW.tenant_id AND source.model_id=NEW.model_id AND source.rating=1 ) OR NEW.rating_2_count IS DISTINCT FROM ( SELECT COUNT(*) FROM request_feedbacks source WHERE source.tenant_id=NEW.tenant_id AND source.model_id=NEW.model_id AND source.rating=2 ) OR NEW.rating_3_count IS DISTINCT FROM ( SELECT COUNT(*) FROM request_feedbacks source WHERE source.tenant_id=NEW.tenant_id AND source.model_id=NEW.model_id AND source.rating=3 ) OR NEW.rating_4_count IS DISTINCT FROM ( SELECT COUNT(*) FROM request_feedbacks source WHERE source.tenant_id=NEW.tenant_id AND source.model_id=NEW.model_id AND source.rating=4 ) OR NEW.rating_5_count IS DISTINCT FROM ( SELECT COUNT(*) FROM request_feedbacks source WHERE source.tenant_id=NEW.tenant_id AND source.model_id=NEW.model_id AND source.rating=5 ) OR NEW.accepted_count IS DISTINCT FROM ( SELECT COALESCE(SUM(accepted), 0) FROM request_feedbacks source WHERE source.tenant_id=NEW.tenant_id AND source.model_id=NEW.model_id ) OR NEW.feedback_statistics_version IS DISTINCT FROM NEW.feedback_count OR NEW.updated_at IS DISTINCT FROM ( SELECT MAX(created_at) FROM request_feedbacks source WHERE source.tenant_id=NEW.tenant_id AND source.model_id=NEW.model_id )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='model_feedback_statistics_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
