CREATE OR REPLACE FUNCTION "fn_trg_request_feedback_aggregate_insert_prd049"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  UPDATE model_feedback_statistics SET feedback_count=( SELECT COUNT(*) FROM request_feedbacks source WHERE source.tenant_id=NEW.tenant_id AND source.model_id=NEW.model_id ), rating_sum=( SELECT COALESCE(SUM(rating), 0) FROM request_feedbacks source WHERE source.tenant_id=NEW.tenant_id AND source.model_id=NEW.model_id ), rating_1_count=( SELECT COUNT(*) FROM request_feedbacks source WHERE source.tenant_id=NEW.tenant_id AND source.model_id=NEW.model_id AND source.rating=1 ), rating_2_count=( SELECT COUNT(*) FROM request_feedbacks source WHERE source.tenant_id=NEW.tenant_id AND source.model_id=NEW.model_id AND source.rating=2 ), rating_3_count=( SELECT COUNT(*) FROM request_feedbacks source WHERE source.tenant_id=NEW.tenant_id AND source.model_id=NEW.model_id AND source.rating=3 ), rating_4_count=( SELECT COUNT(*) FROM request_feedbacks source WHERE source.tenant_id=NEW.tenant_id AND source.model_id=NEW.model_id AND source.rating=4 ), rating_5_count=( SELECT COUNT(*) FROM request_feedbacks source WHERE source.tenant_id=NEW.tenant_id AND source.model_id=NEW.model_id AND source.rating=5 ), accepted_count=( SELECT COALESCE(SUM(accepted), 0) FROM request_feedbacks source WHERE source.tenant_id=NEW.tenant_id AND source.model_id=NEW.model_id ), feedback_statistics_version=( SELECT COUNT(*) FROM request_feedbacks source WHERE source.tenant_id=NEW.tenant_id AND source.model_id=NEW.model_id ), updated_at=( SELECT MAX(created_at) FROM request_feedbacks source WHERE source.tenant_id=NEW.tenant_id AND source.model_id=NEW.model_id ) WHERE tenant_id=NEW.tenant_id AND model_id=NEW.model_id;
  INSERT INTO model_feedback_statistics( tenant_id, model_id, feedback_count, rating_sum, rating_1_count, rating_2_count, rating_3_count, rating_4_count, rating_5_count, accepted_count, feedback_statistics_version, updated_at ) SELECT NEW.tenant_id, NEW.model_id, COUNT(*), COALESCE(SUM(rating), 0), COUNT(CASE WHEN rating=1 THEN 1 END), COUNT(CASE WHEN rating=2 THEN 1 END), COUNT(CASE WHEN rating=3 THEN 1 END), COUNT(CASE WHEN rating=4 THEN 1 END), COUNT(CASE WHEN rating=5 THEN 1 END), COALESCE(SUM(accepted), 0), COUNT(*), MAX(created_at) FROM request_feedbacks source WHERE source.tenant_id=NEW.tenant_id AND source.model_id=NEW.model_id HAVING NOT EXISTS ( SELECT 1 FROM model_feedback_statistics current WHERE current.tenant_id=NEW.tenant_id AND current.model_id=NEW.model_id );
  RETURN NEW;
END;
$trigger$;
