CREATE OR REPLACE FUNCTION "fn_trg_request_feedback_event_payload_insert_prd049"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF ((SELECT COUNT(*) FROM json_each(NEW.payload_json)) <> 7 OR EXISTS ( SELECT 1 FROM json_each(NEW.payload_json) item WHERE item.key NOT IN ( 'request_feedback_id', 'request_id', 'model_id', 'actor_type', 'rating', 'accepted', 'tags' ) ) OR json_type(NEW.payload_json, '$.request_feedback_id')<>'text' OR json_type(NEW.payload_json, '$.request_id')<>'text' OR json_type(NEW.payload_json, '$.model_id')<>'text' OR json_type(NEW.payload_json, '$.actor_type')<>'text' OR json_type(NEW.payload_json, '$.rating')<>'integer' OR json_type(NEW.payload_json, '$.accepted') NOT IN ('true', 'false') OR json_type(NEW.payload_json, '$.tags')<>'array' OR NOT EXISTS ( SELECT 1 FROM request_feedbacks feedback WHERE feedback.tenant_id=NEW.tenant_id AND feedback.request_feedback_id=NEW.request_feedback_id AND json_extract(NEW.payload_json, '$.request_feedback_id')=feedback.request_feedback_id AND json_extract(NEW.payload_json, '$.request_id')=feedback.source_request_id AND json_extract(NEW.payload_json, '$.model_id')=feedback.model_id AND json_extract(NEW.payload_json, '$.actor_type')=feedback.actor_type AND (json_extract(NEW.payload_json, '$.rating'))::NUMERIC=feedback.rating AND (json_extract(NEW.payload_json, '$.accepted'))::NUMERIC=feedback.accepted AND metahub_json(json_extract(NEW.payload_json, '$.tags'))=metahub_json(feedback.tags_json) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='request_feedback_event_payload_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
