CREATE OR REPLACE FUNCTION "fn_trg_cache_affinity_bindings_prd050_transition_update"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (( NEW.target_kind IS NOT DISTINCT FROM OLD.target_kind AND NEW.provider_credential_id IS NOT DISTINCT FROM OLD.provider_credential_id AND NEW.target_generation<>OLD.target_generation ) OR ( NOT ( NEW.target_kind IS NOT DISTINCT FROM OLD.target_kind AND NEW.provider_credential_id IS NOT DISTINCT FROM OLD.provider_credential_id ) AND ( NEW.target_generation<>OLD.target_generation+1 OR NEW.last_success_at IS NOT NULL OR NEW.pending_lease_generation<>OLD.pending_lease_generation+1 OR NEW.active_selection_count<>0 ) ) OR NEW.pending_lease_generation NOT IN ( OLD.pending_lease_generation, OLD.pending_lease_generation+1 ) OR ( NEW.pending_lease_generation=OLD.pending_lease_generation+1 AND ( NEW.active_selection_count<>0 OR NEW.pending_lease_started_at<OLD.pending_lease_started_at ) ) OR NEW.selection_count<OLD.selection_count OR NEW.estimated_hit_count<OLD.estimated_hit_count OR ( NEW.target_generation=OLD.target_generation AND OLD.last_success_at IS NOT NULL AND (NEW.last_success_at IS NULL OR NEW.last_success_at<OLD.last_success_at) ) OR NEW.last_selected_at<OLD.last_selected_at OR NEW.updated_at<OLD.updated_at OR ( NEW.target_kind='managed' AND ( OLD.target_kind<>'managed' OR NEW.provider_credential_id IS DISTINCT FROM OLD.provider_credential_id ) AND NOT EXISTS ( SELECT 1 FROM provider_credentials credential WHERE credential.tenant_id=NEW.tenant_id AND credential.provider_id=NEW.provider_id AND credential.provider_credential_id=NEW.provider_credential_id ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='cache_affinity_binding_transition_invalid';
  END IF;
  RETURN NEW;
END;
