CREATE OR REPLACE FUNCTION "fn_trg_cache_affinity_selections_prd050_graph_insert"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM gateway_request_claims claim JOIN cache_affinity_scopes scope ON scope.tenant_id=claim.tenant_id AND scope.virtual_key_id=claim.virtual_key_id AND scope.cache_affinity_scope_id=NEW.cache_affinity_scope_id_snapshot WHERE claim.tenant_id=NEW.tenant_id AND claim.request_id=NEW.request_id AND claim.trace_id=NEW.trace_id ) OR NOT EXISTS ( SELECT 1 FROM cache_affinities affinity WHERE affinity.tenant_id=NEW.tenant_id AND affinity.cache_affinity_id=NEW.cache_affinity_id AND affinity.model_alias_id=NEW.model_alias_id AND affinity.version=NEW.cache_affinity_version AND affinity.status='enabled' ) OR NOT EXISTS ( SELECT 1 FROM cache_affinity_bindings binding JOIN providers provider ON provider.tenant_id=binding.tenant_id AND provider.provider_id=binding.provider_id WHERE binding.tenant_id=NEW.tenant_id AND binding.cache_affinity_scope_id=NEW.cache_affinity_scope_id_snapshot AND binding.cache_affinity_binding_id=NEW.cache_affinity_binding_id_snapshot AND binding.model_endpoint_id=NEW.model_endpoint_id AND binding.endpoint_revision_digest=NEW.endpoint_revision_digest_snapshot AND binding.provider_id=NEW.provider_id AND provider.provider_code=NEW.provider_code_snapshot AND binding.provider_credential_id IS NOT DISTINCT FROM NEW.provider_credential_id_snapshot AND binding.target_kind=NEW.target_kind AND binding.target_generation=NEW.target_generation AND binding.pending_lease_generation=NEW.pending_lease_generation_snapshot AND binding.last_success_at IS NOT DISTINCT FROM NEW.warm_evidence_at_snapshot ) OR ( NEW.routing_attempt_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM routing_attempts attempt WHERE attempt.tenant_id=NEW.tenant_id AND attempt.routing_attempt_id=NEW.routing_attempt_id AND attempt.request_id=NEW.request_id AND attempt.trace_id=NEW.trace_id AND attempt.attempt_sequence=NEW.attempt_sequence AND attempt.model_alias_id=NEW.model_alias_id AND attempt.model_id=NEW.model_endpoint_id AND attempt.provider_id=NEW.provider_id AND attempt.provider_code=NEW.provider_code_snapshot AND attempt.status='started' ) ) OR ( NEW.stream_session_id IS NOT NULL AND ( NEW.attempt_sequence<>1 OR NOT EXISTS ( SELECT 1 FROM stream_sessions session WHERE session.tenant_id=NEW.tenant_id AND session.stream_session_id=NEW.stream_session_id AND session.request_id=NEW.request_id AND session.trace_id=NEW.trace_id AND session.model_id=NEW.model_endpoint_id AND session.provider_id=NEW.provider_id AND session.provider_code=NEW.provider_code_snapshot AND session.status='starting' ) ) ) OR ( NEW.estimated_hit=1 AND NOT EXISTS ( SELECT 1 FROM cache_affinity_bindings binding WHERE binding.tenant_id=NEW.tenant_id AND binding.cache_affinity_binding_id=NEW.cache_affinity_binding_id_snapshot AND binding.target_generation=NEW.target_generation AND binding.last_success_at IS NOT NULL AND datetime(NEW.created_at)<datetime( binding.last_success_at, '+' || NEW.ttl_seconds_snapshot || ' seconds' ) ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='cache_affinity_selection_graph_invalid';
  END IF;
  RETURN NEW;
END;
