CREATE OR REPLACE FUNCTION "fn_trg_cache_affinity_config_events_prd050_graph_insert"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM users actor WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.actor_user_id ) OR NOT EXISTS ( SELECT 1 FROM cache_affinities affinity WHERE affinity.tenant_id=NEW.tenant_id AND affinity.cache_affinity_id=NEW.cache_affinity_id AND affinity.model_alias_id=NEW.model_alias_id AND affinity.version=NEW.cache_affinity_version AND json_remove( NEW.after_json, '$.status', '$.data_class', '$.minimum_prefix_chars', '$.ttl_seconds', '$.version' )='{}' AND COALESCE(json_type(NEW.after_json, '$.status'), 'missing')='text' AND COALESCE(json_type(NEW.after_json, '$.data_class'), 'missing') IN ('text', 'null') AND COALESCE(json_type(NEW.after_json, '$.minimum_prefix_chars'), 'missing')='integer' AND COALESCE(json_type(NEW.after_json, '$.ttl_seconds'), 'missing')='integer' AND COALESCE(json_type(NEW.after_json, '$.version'), 'missing')='integer' AND json_extract(NEW.after_json, '$.status')=affinity.status AND json_extract(NEW.after_json, '$.data_class') IS NOT DISTINCT FROM affinity.data_class AND (json_extract(NEW.after_json, '$.minimum_prefix_chars'))::NUMERIC=affinity.minimum_prefix_chars AND (json_extract(NEW.after_json, '$.ttl_seconds'))::NUMERIC=affinity.ttl_seconds AND (json_extract(NEW.after_json, '$.version'))::NUMERIC=affinity.version ) OR ( NEW.event_type IN ('updated', 'noop') AND ( json_remove( NEW.before_json, '$.status', '$.data_class', '$.minimum_prefix_chars', '$.ttl_seconds', '$.version' )<>'{}' OR COALESCE(json_type(NEW.before_json, '$.status'), 'missing')<>'text' OR COALESCE(json_type(NEW.before_json, '$.minimum_prefix_chars'), 'missing')<>'integer' OR COALESCE(json_type(NEW.before_json, '$.ttl_seconds'), 'missing')<>'integer' OR COALESCE(json_type(NEW.before_json, '$.version'), 'missing')<>'integer' OR COALESCE(json_type(NEW.before_json, '$.data_class'), 'missing') NOT IN ('text', 'null') OR ( NEW.event_type='updated' AND (json_extract(NEW.before_json, '$.version'))::NUMERIC<>NEW.cache_affinity_version-1 ) ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='cache_affinity_config_event_graph_invalid';
  END IF;
  RETURN NEW;
END;
