CREATE OR REPLACE FUNCTION "fn_trg_finops_adjustments_owner_insert_prd051"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM users user_row WHERE user_row.user_id=NEW.actor_user_id AND user_row.tenant_id=NEW.tenant_id ) OR ( NEW.related_request_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM finops_ledger_entries entry WHERE entry.tenant_id=NEW.tenant_id AND entry.entry_type='usage_charge' AND entry.source_request_id=NEW.related_request_id ) ) OR ( NEW.adjustment_type='reversal' AND NOT EXISTS ( SELECT 1 FROM finops_ledger_entries target WHERE target.tenant_id=NEW.tenant_id AND target.finops_ledger_entry_id=NEW.reversal_of_entry_id AND target.entry_type<>'reversal' AND target.amount_micros>0 AND target.currency=NEW.currency AND NEW.amount_micros <= target.amount_micros - COALESCE(( SELECT SUM(reversal.amount_micros) FROM finops_ledger_entries reversal WHERE reversal.tenant_id=target.tenant_id AND reversal.entry_type='reversal' AND reversal.reversal_of_entry_id=target.finops_ledger_entry_id ), 0) ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='finops_adjustment_owner_mismatch';
  END IF;
  RETURN NEW;
END;
