LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM tenants tenant WHERE tenant.tenant_id=NEW.tenant_id ) OR ( NEW.request_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM request_logs request WHERE request.tenant_id=NEW.tenant_id AND request.request_id=NEW.request_id ) ) OR ( NEW.model_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM models model WHERE model.tenant_id=NEW.tenant_id AND model.model_id=NEW.model_id ) ) OR ( NEW.provider_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM providers provider WHERE provider.tenant_id=NEW.tenant_id AND provider.provider_id=NEW.provider_id ) ) OR ( NEW.price_plan_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM model_price_plans plan WHERE plan.tenant_id=NEW.tenant_id AND plan.price_plan_id=NEW.price_plan_id ) ) OR NOT json_valid(NEW.billing_dimensions) OR json_type(NEW.billing_dimensions)<>'object' OR NOT json_valid(NEW.provider_raw_mapping) OR json_type(NEW.provider_raw_mapping)<>'object' OR ( NEW.source='finops_unpriced' AND ( NEW.request_id IS NULL OR NEW.price_schema_version<>'unpriced-v1' OR NEW.input_price_per_1k<>0 OR NEW.output_price_per_1k<>0 OR NULLIF(json_extract( NEW.billing_dimensions, '$.finops_usage_ledger_id' ), '') IS NULL ) ) OR ( NEW.source='finops_legacy_backfill' AND ( NEW.request_id IS NULL OR NEW.price_schema_version<>'legacy-unversioned-v1' OR NULLIF(json_extract( NEW.billing_dimensions, '$.finops_usage_ledger_id' ), '') IS NULL ) ) OR ( NEW.source NOT IN ('finops_unpriced', 'finops_legacy_backfill') AND NULLIF(trim(NEW.price_schema_version), '') IS NULL )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='price_snapshot_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
