CREATE OR REPLACE FUNCTION "fn_trg_cost_anomaly_runs_owner_insert_prd053"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM environments environment WHERE environment.tenant_id=NEW.tenant_id AND environment.environment_id=NEW.environment_id ) OR NOT EXISTS ( SELECT 1 FROM finops_ledger_entries entry WHERE entry.tenant_id=NEW.tenant_id AND entry.environment_id=NEW.environment_id AND entry.entry_type='usage_charge' AND entry.direction='debit' AND entry.status='posted' AND unixepoch(entry.created_at)>=unixepoch(NEW.window_start) AND unixepoch(entry.created_at)<unixepoch(NEW.window_end) ) OR NEW.ledger_watermark IS DISTINCT FROM ( SELECT MAX(entry.ledger_sequence) FROM finops_ledger_entries entry WHERE entry.tenant_id=NEW.tenant_id AND entry.environment_id=NEW.environment_id AND entry.entry_type='usage_charge' AND entry.direction='debit' AND entry.status='posted' AND unixepoch(entry.created_at)>=unixepoch(NEW.baseline_start) AND unixepoch(entry.created_at)<unixepoch(NEW.window_end) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='cost_anomaly_run_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
