CREATE OR REPLACE FUNCTION "fn_trg_cost_anomaly_runs_state_update_prd053"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT ( NEW.detection_run_id=OLD.detection_run_id AND NEW.tenant_id=OLD.tenant_id AND NEW.environment_id=OLD.environment_id AND NEW.window_start=OLD.window_start AND NEW.window_end=OLD.window_end AND NEW.baseline_start=OLD.baseline_start AND NEW.baseline_end=OLD.baseline_end AND NEW.operation_request_id=OLD.operation_request_id AND NEW.operation_trace_id=OLD.operation_trace_id AND NEW.created_at=OLD.created_at AND unixepoch(NEW.updated_at)>=unixepoch(OLD.updated_at) AND ( ( OLD.status IN ('completed', 'partial', 'failed') AND NEW.status='processing' AND NEW.evaluation_revision=OLD.evaluation_revision+1 AND NEW.ledger_watermark>OLD.ledger_watermark AND NEW.ledger_watermark=( SELECT MAX(entry.ledger_sequence) FROM finops_ledger_entries entry WHERE entry.tenant_id=NEW.tenant_id AND entry.environment_id=NEW.environment_id AND entry.entry_type='usage_charge' AND entry.direction='debit' AND entry.status='posted' AND unixepoch(entry.created_at)>=unixepoch(NEW.baseline_start) AND unixepoch(entry.created_at)<unixepoch(NEW.window_end) ) AND NEW.claim_token IS DISTINCT FROM OLD.claim_token AND unixepoch(NEW.started_at)>=unixepoch(OLD.updated_at) ) OR ( OLD.status='processing' AND NEW.status='processing' AND NEW.evaluation_revision=OLD.evaluation_revision+1 AND NEW.ledger_watermark>=OLD.ledger_watermark AND NEW.ledger_watermark=( SELECT MAX(entry.ledger_sequence) FROM finops_ledger_entries entry WHERE entry.tenant_id=NEW.tenant_id AND entry.environment_id=NEW.environment_id AND entry.entry_type='usage_charge' AND entry.direction='debit' AND entry.status='posted' AND unixepoch(entry.created_at)>=unixepoch(NEW.baseline_start) AND unixepoch(entry.created_at)<unixepoch(NEW.window_end) ) AND NEW.claim_token IS DISTINCT FROM OLD.claim_token AND unixepoch(OLD.lease_expires_at)<=unixepoch(NEW.started_at) AND unixepoch(NEW.started_at)>=unixepoch(OLD.started_at) ) OR ( OLD.status='processing' AND NEW.status IN ('completed', 'partial', 'failed') AND NEW.evaluation_revision=OLD.evaluation_revision AND NEW.ledger_watermark=OLD.ledger_watermark AND NEW.operation_request_id=OLD.operation_request_id AND NEW.operation_trace_id=OLD.operation_trace_id AND NEW.started_at=OLD.started_at AND NEW.completed_at IS NOT NULL ) ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='cost_anomaly_run_cas_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
