LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM cost_anomaly_detection_runs run WHERE run.tenant_id=NEW.tenant_id AND run.environment_id=NEW.environment_id AND run.detection_run_id=NEW.detection_run_id AND run.status='processing' AND run.window_start=NEW.window_start AND run.window_end=NEW.window_end AND run.baseline_start=NEW.baseline_start AND run.baseline_end=NEW.baseline_end AND NEW.source_ledger_sequence_max<=run.ledger_watermark ) OR NOT EXISTS ( SELECT 1 FROM finops_ledger_entries entry WHERE entry.ledger_sequence=NEW.source_ledger_sequence_min AND entry.tenant_id=NEW.tenant_id AND entry.environment_id=NEW.environment_id AND entry.entry_type='usage_charge' AND entry.direction='debit' AND entry.status='posted' AND entry.created_at>=NEW.baseline_start AND entry.created_at<NEW.window_end AND (NEW.scope_type='tenant' OR entry.virtual_key_id=NEW.virtual_key_id) ) OR NOT EXISTS ( SELECT 1 FROM finops_ledger_entries entry WHERE entry.ledger_sequence=NEW.source_ledger_sequence_max AND entry.tenant_id=NEW.tenant_id AND entry.environment_id=NEW.environment_id AND entry.entry_type='usage_charge' AND entry.direction='debit' AND entry.status='posted' AND entry.created_at>=NEW.baseline_start AND entry.created_at<NEW.window_end AND (NEW.scope_type='tenant' OR entry.virtual_key_id=NEW.virtual_key_id) ) OR NOT EXISTS ( SELECT 1 FROM finops_ledger_entries entry WHERE entry.tenant_id=NEW.tenant_id AND entry.environment_id=NEW.environment_id AND entry.source_request_id=NEW.representative_request_id AND entry.source_trace_id=NEW.representative_trace_id AND entry.entry_type='usage_charge' AND entry.direction='debit' AND entry.status='posted' AND entry.cny_normalization_status='normalized' AND entry.price_evidence_status IN ('priced', 'legacy_amount_only') AND typeof(entry.normalized_cny_micros)='integer' AND entry.created_at>=NEW.window_start AND entry.created_at<NEW.window_end AND entry.ledger_sequence BETWEEN NEW.source_ledger_sequence_min AND NEW.source_ledger_sequence_max AND (NEW.scope_type='tenant' OR entry.virtual_key_id=NEW.virtual_key_id) AND entry.project_id IS NOT DISTINCT FROM NEW.project_id_snapshot AND entry.application_id IS NOT DISTINCT FROM NEW.application_id_snapshot ) OR ( NEW.top_virtual_key_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM finops_ledger_entries entry WHERE entry.tenant_id=NEW.tenant_id AND entry.environment_id=NEW.environment_id AND entry.virtual_key_id=NEW.top_virtual_key_id AND entry.entry_type='usage_charge' AND entry.direction='debit' AND entry.status='posted' AND entry.created_at>=NEW.window_start AND entry.created_at<NEW.window_end AND entry.ledger_sequence<=NEW.source_ledger_sequence_max ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='cost_anomaly_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_cost_anomalies_owner_insert_prd053" BEFORE INSERT ON "cost_anomalies" FOR EACH ROW EXECUTE FUNCTION "fn_trg_cost_anomalies_owner_insert_prd053"();
