CREATE OR REPLACE FUNCTION "fn_trg_cost_anomalies_state_update_prd053"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT ( NEW.anomaly_sequence=OLD.anomaly_sequence AND NEW.cost_anomaly_id=OLD.cost_anomaly_id AND NEW.event_id=OLD.event_id AND NEW.tenant_id=OLD.tenant_id AND NEW.environment_id=OLD.environment_id AND NEW.detection_run_id=OLD.detection_run_id AND NEW.rule_type=OLD.rule_type AND NEW.severity=OLD.severity AND NEW.scope_type=OLD.scope_type AND NEW.scope_id=OLD.scope_id AND NEW.virtual_key_id IS NOT DISTINCT FROM OLD.virtual_key_id AND NEW.top_virtual_key_id IS NOT DISTINCT FROM OLD.top_virtual_key_id AND NEW.project_id_snapshot IS NOT DISTINCT FROM OLD.project_id_snapshot AND NEW.application_id_snapshot IS NOT DISTINCT FROM OLD.application_id_snapshot AND NEW.window_start=OLD.window_start AND NEW.window_end=OLD.window_end AND NEW.baseline_start=OLD.baseline_start AND NEW.baseline_end=OLD.baseline_end AND NEW.current_cost_micros=OLD.current_cost_micros AND NEW.baseline_total_micros=OLD.baseline_total_micros AND NEW.baseline_bucket_count=OLD.baseline_bucket_count AND NEW.observed_ratio_millis IS NOT DISTINCT FROM OLD.observed_ratio_millis AND NEW.threshold_multiplier_millis=OLD.threshold_multiplier_millis AND NEW.minimum_cost_micros=OLD.minimum_cost_micros AND NEW.cooldown_minutes=OLD.cooldown_minutes AND NEW.source_entry_count=OLD.source_entry_count AND NEW.estimated_entry_count=OLD.estimated_entry_count AND NEW.legacy_entry_count=OLD.legacy_entry_count AND NEW.affected_virtual_key_count=OLD.affected_virtual_key_count AND NEW.representative_request_id=OLD.representative_request_id AND NEW.representative_trace_id=OLD.representative_trace_id AND NEW.source_ledger_sequence_min=OLD.source_ledger_sequence_min AND NEW.source_ledger_sequence_max=OLD.source_ledger_sequence_max AND NEW.recommended_action=OLD.recommended_action AND NEW.detection_version=OLD.detection_version AND NEW.detected_at=OLD.detected_at AND NEW.mitigation_eligible_until=OLD.mitigation_eligible_until AND NEW.created_at=OLD.created_at AND unixepoch(NEW.updated_at)>unixepoch(OLD.updated_at) AND ( ( NEW.event_dispatch_status=OLD.event_dispatch_status AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts AND NEW.event_next_attempt_at IS NOT DISTINCT FROM OLD.event_next_attempt_at AND NEW.event_dispatched_at IS NOT DISTINCT FROM OLD.event_dispatched_at AND NEW.event_claim_token IS NOT DISTINCT FROM OLD.event_claim_token AND NEW.event_lease_owner_id IS NOT DISTINCT FROM OLD.event_lease_owner_id AND NEW.event_lease_expires_at IS NOT DISTINCT FROM OLD.event_lease_expires_at AND NEW.event_last_error_code IS NOT DISTINCT FROM OLD.event_last_error_code AND ( (OLD.status='open' AND NEW.status IN ('acknowledged', 'dismissed', 'mitigated')) OR (OLD.status='acknowledged' AND NEW.status IN ('dismissed', 'mitigated')) ) ) OR ( NEW.status=OLD.status AND ( (OLD.event_dispatch_status='pending' AND NEW.event_dispatch_status='processing' AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts+1 AND unixepoch(OLD.event_next_attempt_at)<=unixepoch(NEW.updated_at) AND NEW.event_claim_token IS DISTINCT FROM OLD.event_claim_token) OR (OLD.event_dispatch_status='processing' AND NEW.event_dispatch_status='processing' AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts+1 AND unixepoch(OLD.event_lease_expires_at)<=unixepoch(NEW.updated_at) AND NEW.event_claim_token IS DISTINCT FROM OLD.event_claim_token) OR (OLD.event_dispatch_status='processing' AND NEW.event_dispatch_status='pending' AND OLD.event_dispatch_attempts<10 AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts AND NEW.event_last_error_code IS NOT NULL AND unixepoch(NEW.event_next_attempt_at)>unixepoch(NEW.updated_at)) OR (OLD.event_dispatch_status='processing' AND NEW.event_dispatch_status='dispatched' AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts AND NEW.event_dispatched_at IS NOT NULL) OR (OLD.event_dispatch_status='processing' AND NEW.event_dispatch_status='failed' AND NEW.event_dispatch_attempts=10 AND NEW.event_last_error_code IS NOT NULL) ) ) ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='cost_anomaly_state_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
