CREATE OR REPLACE FUNCTION "fn_trg_cost_anomaly_actions_owner_insert_prd053"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM users actor WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.actor_user_id ) OR NOT EXISTS ( SELECT 1 FROM cost_anomalies anomaly WHERE anomaly.tenant_id=NEW.tenant_id AND anomaly.cost_anomaly_id=NEW.cost_anomaly_id AND anomaly.status=NEW.status_before ) OR ( NEW.action_type='apply_temporary_rate_limit' AND NOT EXISTS ( SELECT 1 FROM cost_anomalies anomaly JOIN virtual_keys key ON key.tenant_id=anomaly.tenant_id AND key.virtual_key_id=anomaly.virtual_key_id WHERE anomaly.tenant_id=NEW.tenant_id AND anomaly.cost_anomaly_id=NEW.cost_anomaly_id AND anomaly.scope_type='virtual_key' AND key.status='active' AND key.environment_id=anomaly.environment_id AND unixepoch(NEW.created_at)<=unixepoch(anomaly.mitigation_eligible_until) AND NOT EXISTS ( SELECT 1 FROM temporary_rate_limit_overrides existing WHERE existing.tenant_id=anomaly.tenant_id AND existing.source_id=anomaly.cost_anomaly_id ) ) ) OR ( NEW.action_type='apply_temporary_rate_limit' AND NOT ( (NEW.rpm_limit IS NULL AND NEW.effective_rpm_after IS NOT DISTINCT FROM NEW.effective_rpm_before) OR (NEW.rpm_limit IS NOT NULL AND NEW.effective_rpm_after=CASE WHEN NEW.effective_rpm_before IS NULL OR NEW.rpm_limit<NEW.effective_rpm_before THEN NEW.rpm_limit ELSE NEW.effective_rpm_before END) ) ) OR ( NEW.action_type='apply_temporary_rate_limit' AND NOT ( (NEW.tpm_limit IS NULL AND NEW.effective_tpm_after IS NOT DISTINCT FROM NEW.effective_tpm_before) OR (NEW.tpm_limit IS NOT NULL AND NEW.effective_tpm_after=CASE WHEN NEW.effective_tpm_before IS NULL OR NEW.tpm_limit<NEW.effective_tpm_before THEN NEW.tpm_limit ELSE NEW.effective_tpm_before END) ) ) OR ( NEW.action_type='apply_temporary_rate_limit' AND NOT ( (NEW.concurrency_limit IS NULL AND NEW.effective_concurrency_after IS NOT DISTINCT FROM NEW.effective_concurrency_before) OR (NEW.concurrency_limit IS NOT NULL AND NEW.effective_concurrency_after=CASE WHEN NEW.effective_concurrency_before IS NULL OR NEW.concurrency_limit<NEW.effective_concurrency_before THEN NEW.concurrency_limit ELSE NEW.effective_concurrency_before END) ) ) OR ( NEW.action_type='apply_temporary_rate_limit' AND NOT ( (NEW.effective_rpm_before IS NULL AND NEW.effective_rpm_after IS NOT NULL) OR (NEW.effective_rpm_before IS NOT NULL AND NEW.effective_rpm_after<NEW.effective_rpm_before) OR (NEW.effective_tpm_before IS NULL AND NEW.effective_tpm_after IS NOT NULL) OR (NEW.effective_tpm_before IS NOT NULL AND NEW.effective_tpm_after<NEW.effective_tpm_before) OR (NEW.effective_concurrency_before IS NULL AND NEW.effective_concurrency_after IS NOT NULL) OR (NEW.effective_concurrency_before IS NOT NULL AND NEW.effective_concurrency_after<NEW.effective_concurrency_before) ) ) OR ( NEW.action_type='release_temporary_rate_limit' AND NOT EXISTS ( SELECT 1 FROM temporary_rate_limit_overrides override WHERE override.tenant_id=NEW.tenant_id AND override.temporary_rate_limit_override_id=NEW.target_override_id AND override.source_id=NEW.cost_anomaly_id AND override.status='active' AND unixepoch(NEW.created_at)<unixepoch(override.expires_at) ) ) OR ( NEW.action_type='release_temporary_rate_limit' AND ( (NEW.effective_rpm_before IS NULL AND NEW.effective_rpm_after IS NOT NULL) OR (NEW.effective_rpm_before IS NOT NULL AND NEW.effective_rpm_after IS NOT NULL AND NEW.effective_rpm_after<NEW.effective_rpm_before) OR (NEW.effective_tpm_before IS NULL AND NEW.effective_tpm_after IS NOT NULL) OR (NEW.effective_tpm_before IS NOT NULL AND NEW.effective_tpm_after IS NOT NULL AND NEW.effective_tpm_after<NEW.effective_tpm_before) OR (NEW.effective_concurrency_before IS NULL AND NEW.effective_concurrency_after IS NOT NULL) OR (NEW.effective_concurrency_before IS NOT NULL AND NEW.effective_concurrency_after IS NOT NULL AND NEW.effective_concurrency_after<NEW.effective_concurrency_before) ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='cost_anomaly_action_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
