CREATE OR REPLACE FUNCTION "fn_trg_temporary_rate_limit_overrides_owner_insert_prd053"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM cost_anomalies anomaly JOIN virtual_keys key ON key.tenant_id=anomaly.tenant_id AND key.virtual_key_id=anomaly.virtual_key_id JOIN cost_anomaly_actions action ON action.tenant_id=anomaly.tenant_id AND action.cost_anomaly_id=anomaly.cost_anomaly_id AND action.cost_anomaly_action_id=NEW.source_action_id WHERE anomaly.tenant_id=NEW.tenant_id AND anomaly.cost_anomaly_id=NEW.source_id AND anomaly.scope_type='virtual_key' AND anomaly.virtual_key_id=NEW.virtual_key_id AND anomaly.status IN ('open', 'acknowledged', 'mitigated') AND key.status='active' AND key.environment_id=anomaly.environment_id AND action.action_type='apply_temporary_rate_limit' AND action.status_after='mitigated' AND action.actor_user_id=NEW.created_by AND action.rpm_limit IS NOT DISTINCT FROM NEW.rpm_limit AND action.tpm_limit IS NOT DISTINCT FROM NEW.tpm_limit AND action.concurrency_limit IS NOT DISTINCT FROM NEW.concurrency_limit AND action.operation_request_id=NEW.operation_request_id AND action.operation_trace_id=NEW.operation_trace_id AND action.created_at=NEW.starts_at AND NEW.created_at=NEW.starts_at AND action.duration_minutes=(unixepoch(NEW.expires_at)-unixepoch(NEW.starts_at))/60 )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='temporary_rate_limit_override_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
