CREATE OR REPLACE FUNCTION "fn_trg_temporary_rate_limit_overrides_release_update_prd053"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT ( OLD.status='active' AND NEW.status='released' AND NEW.temporary_rate_limit_override_id=OLD.temporary_rate_limit_override_id AND NEW.tenant_id=OLD.tenant_id AND NEW.virtual_key_id=OLD.virtual_key_id AND NEW.source_type=OLD.source_type AND NEW.source_id=OLD.source_id AND NEW.source_action_id=OLD.source_action_id AND NEW.rpm_limit IS NOT DISTINCT FROM OLD.rpm_limit AND NEW.tpm_limit IS NOT DISTINCT FROM OLD.tpm_limit AND NEW.concurrency_limit IS NOT DISTINCT FROM OLD.concurrency_limit AND NEW.starts_at=OLD.starts_at AND NEW.expires_at=OLD.expires_at AND NEW.created_by=OLD.created_by AND NEW.operation_request_id=OLD.operation_request_id AND NEW.operation_trace_id=OLD.operation_trace_id AND NEW.created_at=OLD.created_at AND NEW.updated_at=NEW.released_at AND unixepoch(NEW.released_at)<unixepoch(OLD.expires_at) AND EXISTS ( SELECT 1 FROM cost_anomaly_actions action WHERE action.tenant_id=OLD.tenant_id AND action.cost_anomaly_id=OLD.source_id AND action.cost_anomaly_action_id=NEW.release_action_id AND action.actor_user_id=NEW.released_by AND action.action_type='release_temporary_rate_limit' AND action.target_override_id=OLD.temporary_rate_limit_override_id AND action.created_at=NEW.released_at ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='temporary_rate_limit_override_release_invalid';
  END IF;
  RETURN NEW;
END;
