CREATE OR REPLACE FUNCTION "fn_trg_request_explanations_owner_insert_prd054"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM request_logs request WHERE request.tenant_id=NEW.tenant_id AND request.request_id=NEW.source_request_id AND request.trace_id=NEW.source_trace_id AND request.status=NEW.source_status AND request.created_at=NEW.source_created_at AND coalesce(request.updated_at, request.created_at)=NEW.source_updated_at ) OR NOT EXISTS ( SELECT 1 FROM users user_row WHERE user_row.tenant_id=NEW.tenant_id AND user_row.user_id=NEW.actor_user_id ) OR NOT EXISTS ( SELECT 1 FROM sessions session WHERE session.tenant_id=NEW.tenant_id AND session.user_id=NEW.actor_user_id AND session.session_id=NEW.actor_session_id ) OR (SELECT COUNT(*) FROM json_each(NEW.section_status_json))<>11 OR EXISTS ( SELECT 1 FROM json_each(NEW.section_status_json) section WHERE section.key NOT IN ( 'authentication', 'rate_limit', 'budget', 'dlp', 'policy', 'routing', 'keypool', 'provider_response', 'usage_and_finops', 'logs', 'webhooks' ) OR section.type<>'text' OR section.value NOT IN ('complete', 'partial', 'not_recorded', 'not_applicable', 'pending') ) OR EXISTS ( SELECT 1 FROM json_each(NEW.missing_sections_json) section WHERE section.type<>'text' OR section.value NOT IN ( 'authentication', 'rate_limit', 'budget', 'dlp', 'policy', 'routing', 'keypool', 'provider_response', 'usage_and_finops', 'logs', 'webhooks' ) ) OR EXISTS ( SELECT 1 FROM json_each(NEW.truncated_sections_json) section WHERE section.type<>'text' OR section.value NOT IN ( 'authentication', 'rate_limit', 'budget', 'dlp', 'policy', 'routing', 'keypool', 'provider_response', 'usage_and_finops', 'logs', 'webhooks' ) ) OR (SELECT COUNT(*) FROM json_each(NEW.missing_sections_json)) <>(SELECT COUNT(DISTINCT value) FROM json_each(NEW.missing_sections_json)) OR (SELECT COUNT(*) FROM json_each(NEW.truncated_sections_json)) <>(SELECT COUNT(DISTINCT value) FROM json_each(NEW.truncated_sections_json)) OR EXISTS ( SELECT 1 FROM json_each(NEW.missing_sections_json) missing JOIN json_each(NEW.truncated_sections_json) truncated ON truncated.value=missing.value ) OR ( NEW.status='complete' AND ( json_array_length(NEW.missing_sections_json)<>0 OR json_array_length(NEW.truncated_sections_json)<>0 ) ) OR ( NEW.status='partial' AND json_array_length(NEW.missing_sections_json)=0 AND json_array_length(NEW.truncated_sections_json)=0 )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='request_explanation_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_request_explanations_owner_insert_prd054" BEFORE INSERT ON "request_explanations" FOR EACH ROW EXECUTE FUNCTION "fn_trg_request_explanations_owner_insert_prd054"();
