CREATE OR REPLACE FUNCTION "fn_trg_request_explanations_state_update_prd054"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT ( NEW.ctid=OLD.ctid AND NEW.request_explanation_id=OLD.request_explanation_id AND NEW.event_id=OLD.event_id AND NEW.tenant_id=OLD.tenant_id AND NEW.source_request_id=OLD.source_request_id AND NEW.source_trace_id=OLD.source_trace_id AND NEW.actor_user_id=OLD.actor_user_id AND NEW.actor_session_id=OLD.actor_session_id AND NEW.source_status=OLD.source_status AND NEW.status=OLD.status AND NEW.evidence_version=OLD.evidence_version AND NEW.section_status_json=OLD.section_status_json AND NEW.missing_sections_json=OLD.missing_sections_json AND NEW.truncated_sections_json=OLD.truncated_sections_json AND NEW.source_created_at=OLD.source_created_at AND NEW.source_updated_at=OLD.source_updated_at AND NEW.operation_request_id=OLD.operation_request_id AND NEW.operation_trace_id=OLD.operation_trace_id AND NEW.viewed_at=OLD.viewed_at AND NEW.created_at=OLD.created_at AND unixepoch(NEW.updated_at)>=unixepoch(OLD.updated_at) AND ( (OLD.event_dispatch_status='pending' AND NEW.event_dispatch_status='processing' AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts+1 AND unixepoch(OLD.event_next_attempt_at)<=unixepoch(NEW.updated_at) AND NEW.event_next_attempt_at IS NULL AND NEW.event_claim_token IS DISTINCT FROM OLD.event_claim_token) OR (OLD.event_dispatch_status='processing' AND NEW.event_dispatch_status='processing' AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts+1 AND unixepoch(OLD.event_lease_expires_at)<=unixepoch(NEW.updated_at) AND NEW.event_next_attempt_at IS NULL AND NEW.event_claim_token IS DISTINCT FROM OLD.event_claim_token) OR (OLD.event_dispatch_status='processing' AND NEW.event_dispatch_status='pending' AND OLD.event_dispatch_attempts<10 AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts AND NEW.event_next_attempt_at IS NOT NULL AND unixepoch(NEW.event_next_attempt_at)>unixepoch(NEW.updated_at) AND NEW.event_claim_token IS NULL AND NEW.event_lease_owner_id IS NULL AND NEW.event_lease_expires_at IS NULL AND NEW.event_last_error_code IS NOT NULL) OR (OLD.event_dispatch_status='processing' AND NEW.event_dispatch_status='dispatched' AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts AND NEW.event_dispatched_at IS NOT NULL AND NEW.event_next_attempt_at IS NULL AND NEW.event_claim_token IS NULL AND NEW.event_lease_owner_id IS NULL AND NEW.event_lease_expires_at IS NULL AND NEW.event_last_error_code IS NULL) OR (OLD.event_dispatch_status='processing' AND NEW.event_dispatch_status='failed' AND NEW.event_dispatch_attempts=10 AND NEW.event_next_attempt_at IS NULL AND NEW.event_claim_token IS NULL AND NEW.event_lease_owner_id IS NULL AND NEW.event_lease_expires_at IS NULL AND NEW.event_last_error_code IS NOT NULL) ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='request_explanation_state_invalid';
  END IF;
  RETURN NEW;
END;
