CREATE OR REPLACE FUNCTION "fn_trg_request_webhook_links_owner_insert_prd054"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM webhook_deliveries delivery JOIN request_logs request ON request.tenant_id=delivery.tenant_id AND request.request_id=NEW.source_request_id WHERE delivery.webhook_delivery_id=NEW.webhook_delivery_id AND delivery.tenant_id=NEW.tenant_id AND delivery.event_id=NEW.event_id AND delivery.event_type=NEW.event_type AND delivery.delivery_kind=NEW.delivery_kind AND json_valid(delivery.payload_json) AND json_extract(delivery.payload_json, '$.tenant_id')=NEW.tenant_id AND json_extract(delivery.payload_json, '$.event_id')=NEW.event_id AND json_extract(delivery.payload_json, '$.event_type')=NEW.event_type AND ( ( delivery.delivery_kind='original' AND ( ( delivery.event_type='request.explanation_viewed' AND json_type(delivery.payload_json, '$.payload.source_request_id')='text' AND json_extract(delivery.payload_json, '$.payload.source_request_id')= NEW.source_request_id AND EXISTS ( SELECT 1 FROM request_explanations explanation WHERE explanation.tenant_id=delivery.tenant_id AND explanation.event_id=delivery.event_id AND explanation.request_explanation_id= json_extract(delivery.payload_json, '$.object_id') AND explanation.request_explanation_id= json_extract(delivery.payload_json, '$.payload.request_explanation_id') AND explanation.source_request_id=NEW.source_request_id ) ) OR ( delivery.event_type='ledger.entry_created' AND json_type(delivery.payload_json, '$.payload.source_request_id')='text' AND json_extract(delivery.payload_json, '$.payload.source_request_id')= NEW.source_request_id AND EXISTS ( SELECT 1 FROM finops_ledger_entries entry WHERE entry.tenant_id=delivery.tenant_id AND entry.event_id=delivery.event_id AND entry.finops_ledger_entry_id= json_extract(delivery.payload_json, '$.object_id') AND entry.finops_ledger_entry_id= json_extract(delivery.payload_json, '$.payload.ledger_entry_id') AND entry.source_request_id=NEW.source_request_id ) ) OR ( json_type(delivery.payload_json, '$.payload.request_id')='text' AND json_extract(delivery.payload_json, '$.payload.request_id')= NEW.source_request_id AND ( delivery.event_type IN ( 'gateway.request_failed', 'security.dlp_matched', 'security.dlp_unavailable', 'usage.normalized', 'stream.timeout', 'route.fallback_triggered', 'budget.threshold_reached', 'budget.exhausted', 'budget.scope_exceeded', 'budget.blocked', 'budget.unblocked' ) OR ( delivery.event_type IN ('route.policy_selected', 'cache.affinity_selected') AND json_extract(delivery.payload_json, '$.payload.trigger')='request_selected' ) ) ) ) ) OR ( delivery.delivery_kind='replay' AND EXISTS ( SELECT 1 FROM request_webhook_delivery_links source WHERE source.tenant_id=delivery.tenant_id AND source.webhook_delivery_id=delivery.replayed_from_delivery_id AND source.source_request_id=NEW.source_request_id AND source.event_id=NEW.event_id AND source.event_type=NEW.event_type AND source.delivery_kind='original' ) ) ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='request_webhook_link_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
