CREATE OR REPLACE FUNCTION "fn_trg_webhook_deliveries_request_link_insert_prd054"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  INSERT INTO request_webhook_delivery_links( request_webhook_delivery_link_id, tenant_id, source_request_id, webhook_delivery_id, event_id, event_type, delivery_kind, created_at ) SELECT 'rwdl_' || lower(hex(randomblob(16))), NEW.tenant_id, extracted.source_request_id, NEW.webhook_delivery_id, NEW.event_id, NEW.event_type, NEW.delivery_kind, NEW.created_at FROM ( SELECT CASE WHEN json_type(NEW.payload_json, '$.payload.source_request_id')='text' AND ( ( NEW.event_type='request.explanation_viewed' AND EXISTS ( SELECT 1 FROM request_explanations explanation WHERE explanation.tenant_id=NEW.tenant_id AND explanation.event_id=NEW.event_id AND explanation.request_explanation_id= json_extract(NEW.payload_json, '$.object_id') AND explanation.request_explanation_id= json_extract(NEW.payload_json, '$.payload.request_explanation_id') AND explanation.source_request_id= json_extract(NEW.payload_json, '$.payload.source_request_id') ) ) OR ( NEW.event_type='ledger.entry_created' AND EXISTS ( SELECT 1 FROM finops_ledger_entries entry WHERE entry.tenant_id=NEW.tenant_id AND entry.event_id=NEW.event_id AND entry.finops_ledger_entry_id= json_extract(NEW.payload_json, '$.object_id') AND entry.finops_ledger_entry_id= json_extract(NEW.payload_json, '$.payload.ledger_entry_id') AND entry.source_request_id= json_extract(NEW.payload_json, '$.payload.source_request_id') ) ) ) THEN json_extract(NEW.payload_json, '$.payload.source_request_id') WHEN json_type(NEW.payload_json, '$.payload.request_id')='text' AND ( NEW.event_type IN ( 'gateway.request_failed', 'security.dlp_matched', 'security.dlp_unavailable', 'usage.normalized', 'stream.timeout', 'route.fallback_triggered', 'budget.threshold_reached', 'budget.exhausted', 'budget.scope_exceeded', 'budget.blocked', 'budget.unblocked' ) OR ( NEW.event_type IN ('route.policy_selected', 'cache.affinity_selected') AND json_extract(NEW.payload_json, '$.payload.trigger')='request_selected' ) ) THEN json_extract(NEW.payload_json, '$.payload.request_id') ELSE NULL END AS source_request_id ) extracted WHERE NEW.delivery_kind='original' AND json_valid(NEW.payload_json) AND typeof(extracted.source_request_id)='text' AND length(extracted.source_request_id) BETWEEN 1 AND 128 AND extracted.source_request_id OPERATOR(public.!@@) '*[^A-Za-z0-9_.:-]*' AND EXISTS ( SELECT 1 FROM request_logs request WHERE request.tenant_id=NEW.tenant_id AND request.request_id=extracted.source_request_id );
  INSERT INTO request_webhook_delivery_links( request_webhook_delivery_link_id, tenant_id, source_request_id, webhook_delivery_id, event_id, event_type, delivery_kind, created_at ) SELECT 'rwdl_' || lower(hex(randomblob(16))), NEW.tenant_id, source.source_request_id, NEW.webhook_delivery_id, NEW.event_id, NEW.event_type, NEW.delivery_kind, NEW.created_at FROM request_webhook_delivery_links source WHERE NEW.delivery_kind='replay' AND source.tenant_id=NEW.tenant_id AND source.webhook_delivery_id=NEW.replayed_from_delivery_id;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_webhook_deliveries_request_link_insert_prd054" AFTER INSERT ON "webhook_deliveries" FOR EACH ROW EXECUTE FUNCTION "fn_trg_webhook_deliveries_request_link_insert_prd054"();
