LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT ( json_valid(NEW.filter_json) AND CASE WHEN json_valid(NEW.filter_json) THEN json_type(NEW.filter_json) END='object' AND (SELECT COUNT(*) FROM json_each( CASE WHEN json_valid(NEW.filter_json) THEN NEW.filter_json ELSE '{}' END )) BETWEEN 1 AND 24 AND ( SELECT COUNT(*) FROM json_each( CASE WHEN json_valid(NEW.filter_json) THEN NEW.filter_json ELSE '{}' END ) WHERE key='v' AND type='integer' AND atom=1 )=1 AND ( SELECT COUNT(*) FROM json_each( CASE WHEN json_valid(NEW.filter_json) THEN NEW.filter_json ELSE '{}' END ) )=( SELECT COUNT(DISTINCT key) FROM json_each( CASE WHEN json_valid(NEW.filter_json) THEN NEW.filter_json ELSE '{}' END ) ) AND NOT EXISTS ( SELECT 1 FROM json_each( CASE WHEN json_valid(NEW.filter_json) THEN NEW.filter_json ELSE '{}' END ) item WHERE item.key NOT IN ( 'v','request_id','trace_id','status','request_model','resolved_model', 'provider_code','virtual_key_id','environment_id','project_id','application_id', 'snapshot_version','error_code','created_from','created_to','latency_ms_min', 'latency_ms_max','total_tokens_min','total_tokens_max','cost_amount_min', 'cost_amount_max','currency','terminal_stage' ) OR item.type NOT IN ('text','integer') OR ( item.key IN ( 'v','snapshot_version','latency_ms_min','latency_ms_max', 'total_tokens_min','total_tokens_max' ) AND item.type<>'integer' ) OR ( item.key NOT IN ( 'v','snapshot_version','latency_ms_min','latency_ms_max', 'total_tokens_min','total_tokens_max' ) AND item.type<>'text' ) OR (item.key='snapshot_version' AND item.atom<1) OR ( item.key IN ('latency_ms_min','latency_ms_max','total_tokens_min','total_tokens_max') AND item.atom<0 ) ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='saved_filter_payload_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
