CREATE OR REPLACE FUNCTION "fn_trg_provider_error_map_versions_validate_insert_prd056"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT ( json_valid(NEW.http_statuses_json) AND CASE WHEN json_valid(NEW.http_statuses_json) THEN json_type(NEW.http_statuses_json) END='array' AND (SELECT COUNT(*) FROM json_each( CASE WHEN json_valid(NEW.http_statuses_json) THEN NEW.http_statuses_json ELSE '[]' END )) BETWEEN 0 AND 16 AND NOT EXISTS ( SELECT 1 FROM json_each( CASE WHEN json_valid(NEW.http_statuses_json) THEN NEW.http_statuses_json ELSE '[]' END ) item WHERE item.type<>'integer' OR item.atom NOT BETWEEN 400 AND 499 OR item.atom IN (401,403,408) ) AND NOT EXISTS ( SELECT 1 FROM json_each( CASE WHEN json_valid(NEW.http_statuses_json) THEN NEW.http_statuses_json ELSE '[]' END ) item GROUP BY item.atom HAVING COUNT(*)>1 ) AND NEW.http_statuses_json=( SELECT CASE WHEN COUNT(*)=0 THEN '[]' ELSE '['||string_agg(CAST(atom AS TEXT),',')||']' END FROM ( SELECT atom FROM json_each( CASE WHEN json_valid(NEW.http_statuses_json) THEN NEW.http_statuses_json ELSE '[]' END ) ORDER BY atom ) ) AND NOT EXISTS ( SELECT 1 FROM json_each( CASE WHEN json_valid(NEW.http_statuses_json) THEN NEW.http_statuses_json ELSE '[]' END ) item WHERE CASE WHEN item.atom=402 THEN NEW.output_error_code<>'gateway.upstream_quota_exceeded' WHEN item.atom=404 THEN NEW.output_error_code NOT IN ( 'gateway.upstream_model_not_found','gateway.upstream_resource_not_found' ) WHEN item.atom=429 THEN NEW.output_error_code NOT IN ( 'gateway.upstream_rate_limited','gateway.upstream_quota_exceeded' ) WHEN item.atom IN (400,422) THEN NEW.output_error_code NOT IN ( 'gateway.upstream_request_invalid','gateway.upstream_model_not_found', 'gateway.upstream_quota_exceeded' ) ELSE NEW.output_error_code NOT IN ( 'gateway.upstream_request_invalid','gateway.upstream_quota_exceeded' ) END ) AND (NEW.http_status_class IS NULL OR NEW.output_error_code IN ( 'gateway.upstream_request_invalid','gateway.upstream_quota_exceeded' )) AND (NEW.http_statuses_json<>'[]' OR NEW.http_status_class IS NOT NULL OR NEW.output_error_code IN ( 'gateway.upstream_quota_exceeded','gateway.upstream_model_not_found', 'gateway.upstream_request_invalid','gateway.upstream_resource_not_found' )) AND EXISTS ( SELECT 1 FROM users actor WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.created_by ) AND EXISTS ( SELECT 1 FROM users actor WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.updated_by ) AND (NEW.provider_id IS NULL OR EXISTS ( SELECT 1 FROM providers provider WHERE provider.tenant_id=NEW.tenant_id AND provider.provider_id=NEW.provider_id )) AND NEW.head_revision=COALESCE(( SELECT head.revision FROM provider_error_map_heads head WHERE head.tenant_id=NEW.tenant_id ),0)+1 AND ( (NEW.version=1 AND NOT EXISTS ( SELECT 1 FROM provider_error_map_versions prior WHERE prior.tenant_id=NEW.tenant_id AND prior.provider_error_map_id=NEW.provider_error_map_id )) OR (NEW.version>1 AND EXISTS ( SELECT 1 FROM provider_error_maps current WHERE current.tenant_id=NEW.tenant_id AND current.provider_error_map_id=NEW.provider_error_map_id AND current.current_version=NEW.version-1 AND current.created_by=NEW.created_by )) ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='provider_error_map_version_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
