verlay_content_hash='994a863c694e05021d65d0f8b862f24a28da461080286b7b35d1695ee0775fdc' AND NEW.matched_rule_source IN ('guard','builtin')) OR (NEW.error_map_revision>0 AND NEW.error_map_snapshot_source<>'builtin_fallback' AND EXISTS ( SELECT 1 FROM provider_error_map_head_versions history WHERE history.tenant_id=NEW.tenant_id AND history.revision=NEW.error_map_revision AND history.content_hash=NEW.overlay_content_hash AND history.builtin_catalog_version=NEW.builtin_catalog_version AND ( NEW.matched_rule_source<>'tenant' OR EXISTS ( SELECT 1 FROM json_each(history.active_rule_refs_json) ref WHERE json_extract(ref.value,'$.error_map_id')=NEW.matched_error_map_id AND (json_extract(ref.value,'$.version'))::NUMERIC=NEW.matched_rule_version ) ) )) ) AND ( (NEW.matched_rule_source IN ('guard','builtin') AND EXISTS ( SELECT 1 FROM provider_error_builtin_rule_versions builtin WHERE builtin.builtin_catalog_version=NEW.builtin_catalog_version AND builtin.error_map_id=NEW.matched_error_map_id AND builtin.source=NEW.matched_rule_source AND builtin.pattern_hash=NEW.matched_pattern_hash AND builtin.output_error_code=NEW.normalized_output_error_code )) OR (NEW.matched_rule_source='tenant' AND NEW.error_map_revision>0 AND EXISTS ( SELECT 1 FROM provider_error_map_versions version WHERE version.tenant_id=NEW.tenant_id AND version.provider_error_map_id=NEW.matched_error_map_id AND version.version=NEW.matched_rule_version AND version.status='active' AND version.pattern_hash=NEW.matched_pattern_hash AND version.output_error_code=NEW.normalized_output_error_code AND (version.provider_id IS NULL OR version.provider_id=NEW.provider_id) )) ) )) THEN
