LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.status<>'pending' OR NEW.accepted_user_id IS NOT NULL OR NEW.accepted_at IS NOT NULL OR NEW.updated_at<>NEW.created_at OR unixepoch(NEW.expires_at)<=unixepoch(NEW.created_at) OR unixepoch(NEW.expires_at)>unixepoch(NEW.created_at,'+168 hours') OR NOT EXISTS ( SELECT 1 FROM tenants tenant WHERE tenant.tenant_id=NEW.tenant_id AND tenant.status='active' ) OR NOT EXISTS ( SELECT 1 FROM roles role WHERE role.tenant_id=NEW.tenant_id AND role.code=NEW.role_code AND role.status='active' ) OR NOT EXISTS ( SELECT 1 FROM users actor WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.invited_by AND actor.status='active' ) OR NOT EXISTS ( SELECT 1 FROM users actor JOIN roles actor_role ON actor_role.tenant_id=actor.tenant_id AND actor_role.code=actor.role JOIN role_permissions relation ON relation.tenant_id=actor_role.tenant_id AND relation.role_id=actor_role.role_id JOIN permissions permission ON permission.tenant_id=relation.tenant_id AND permission.permission_id=relation.permission_id WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.invited_by AND actor.status='active' AND actor_role.status='active' AND permission.code='user_row.manage' AND permission.status='active' ) OR EXISTS ( SELECT 1 FROM users user_row WHERE user_row.tenant_id=NEW.tenant_id AND user_row.email=NEW.email )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='invitation_owner_mismatch';
