vent_payload_json,'$.status')=NEW.status AND json_extract(NEW.event_payload_json,'$.format')=NEW.format AND json_type(NEW.event_payload_json,'$.schema_version')='integer' AND (json_extract(NEW.event_payload_json,'$.schema_version'))::NUMERIC=NEW.schema_version AND json_type(NEW.event_payload_json,'$.row_count')='integer' AND (json_extract(NEW.event_payload_json,'$.row_count'))::NUMERIC=NEW.row_count AND json_type(NEW.event_payload_json,'$.content_size_bytes')='integer' AND (json_extract(NEW.event_payload_json,'$.content_size_bytes'))::NUMERIC=NEW.content_size_bytes AND json_extract(NEW.event_payload_json,'$.content_sha256')=NEW.content_sha256 AND json_extract(NEW.event_payload_json,'$.filter_fingerprint')=NEW.filter_fingerprint )) THEN
