CREATE OR REPLACE FUNCTION "fn_trg_role_permission_events_owner_insert_prd059"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM roles role WHERE role.tenant_id=NEW.tenant_id AND role.role_id=NEW.role_id AND role.code<>'admin' AND role.status='active' AND role.permission_revision=NEW.after_revision AND role.matrix_sha256=NEW.after_sha256 ) OR NOT EXISTS ( SELECT 1 FROM users actor WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.actor_user_id AND actor.status='active' AND actor.role=NEW.actor_role ) OR NOT EXISTS ( SELECT 1 FROM audit_logs audit WHERE audit.tenant_id=NEW.tenant_id AND audit.audit_log_id=NEW.audit_log_id AND audit.actor_user_id=NEW.actor_user_id AND audit.actor_role=NEW.actor_role AND audit.action='role.permission_changed' AND audit.object_type='role_permission' AND audit.object_id=NEW.role_id AND audit.request_id=NEW.request_id AND audit.trace_id=NEW.trace_id AND audit.created_at=NEW.created_at AND (json_extract(audit.before_summary_json,'$.permission_revision'))::NUMERIC=NEW.before_revision AND json_extract(audit.before_summary_json,'$.matrix_sha256')=NEW.before_sha256 AND (json_extract(audit.after_summary_json,'$.permission_revision'))::NUMERIC=NEW.after_revision AND json_extract(audit.after_summary_json,'$.matrix_sha256')=NEW.after_sha256 AND (json_extract(audit.after_summary_json,'$.permission_count'))::NUMERIC=( SELECT COUNT(*) FROM role_permissions relation WHERE relation.tenant_id=NEW.tenant_id AND relation.role_id=NEW.role_id ) AND (json_extract(audit.before_summary_json,'$.permission_count'))::NUMERIC=( SELECT COUNT(*) FROM role_permissions relation WHERE relation.tenant_id=NEW.tenant_id AND relation.role_id=NEW.role_id )-(SELECT COUNT(*) FROM json_each(NEW.added_permissions_json)) +(SELECT COUNT(*) FROM json_each(NEW.removed_permissions_json)) ) OR NEW.delivery_status<>'pending' OR NEW.last_error_code IS NOT NULL OR NEW.dispatched_at IS NOT NULL OR NEW.updated_at<>NEW.created_at OR (SELECT COUNT(*) FROM json_each(NEW.added_permissions_json)) +(SELECT COUNT(*) FROM json_each(NEW.removed_permissions_json))=0 OR EXISTS ( SELECT 1 FROM json_each(NEW.added_permissions_json) item WHERE item.type<>'text' OR NOT EXISTS ( SELECT 1 FROM rbac_role_permission_templates role_template JOIN roles role ON role.code=role_template.role_code WHERE role.tenant_id=NEW.tenant_id AND role.role_id=NEW.role_id AND role_template.permission_code=item.value ) OR NOT EXISTS ( SELECT 1 FROM role_permissions relation JOIN permissions permission ON permission.tenant_id=relation.tenant_id AND permission.permission_id=relation.permission_id WHERE relation.tenant_id=NEW.tenant_id AND relation.role_id=NEW.role_id AND permission.code=item.value ) ) OR EXISTS ( SELECT 1 FROM json_each(NEW.removed_permissions_json) item WHERE item.type<>'text' OR NOT EXISTS ( SELECT 1 FROM rbac_role_permission_templates role_template JOIN roles role ON role.code=role_template.role_code WHERE role.tenant_id=NEW.tenant_id AND role.role_id=NEW.role_id AND role_template.permission_code=item.value ) OR EXISTS ( SELECT 1 FROM role_permissions relation JOIN permissions permission ON permission.tenant_id=relation.tenant_id AND permission.permission_id=relation.permission_id WHERE relation.tenant_id=NEW.tenant_id AND relation.role_id=NEW.role_id AND permission.code=item.value ) ) OR (SELECT COUNT(*) FROM json_each(NEW.added_permissions_json)) <>(SELECT COUNT(DISTINCT value) FROM json_each(NEW.added_permissions_json)) OR (SELECT COUNT(*) FROM json_each(NEW.removed_permissions_json)) <>(SELECT COUNT(DISTINCT value) FROM json_each(NEW.removed_permissions_json)) OR EXISTS ( SELECT 1 FROM json_each(NEW.added_permissions_json) added JOIN json_each(NEW.removed_permissions_json) removed ON removed.value=added.value ) OR EXISTS ( SELECT 1 FROM json_each(NEW.added_permissions_json) item JOIN json_each(NEW.added_permissions_json) next ON (next.key)::BIGINT=(item.key)::BIGINT+1 WHERE CAST(item.value AS TEXT)>=CAST(next.value AS TEXT) ) OR EXISTS ( SELECT 1 FROM json_each(NEW.removed_permissions_json) item JOIN json_each(NEW.removed_permissions_json) next ON (next.key)::BIGINT=(item.key)::BIGINT+1 WHERE CAST(item.value AS TEXT)>=CAST(next.value AS TEXT) ) OR (SELECT COUNT(*) FROM json_each(NEW.payload_json))<>9 OR EXISTS ( SELECT 1 FROM json_each(NEW.payload_json) field WHERE field.key NOT IN ( 'schema_version','role_id','role_code','before_revision','after_revision', 'before_sha256','after_sha256','added_permissions','removed_permissions' ) ) OR (json_extract(NEW.payload_json,'$.schema_version'))::NUMERIC<>1 OR json_extract(NEW.payload_json,'$.role_id')<>NEW.role_id OR (json_extract(NEW.payload_json,'$.before_revision'))::NUMERIC<>NEW.before_revision OR (json_extract(NEW.payload_json,'$.after_revision'))::NUMERIC<>NEW.after_revision OR json_extract(NEW.payload_json,'$.before_sha256')<>NEW.before_sha256 OR json_extract(NEW.payload_json,'$.after_sha256')<>NEW.after_sha256 OR metahub_json(json_extract(NEW.payload_json,'$.added_permissions')) <>metahub_json(NEW.added_permissions_json) OR metahub_json(json_extract(NEW.payload_json,'$.removed_permissions')) <>metahub_json(NEW.removed_permissions_json) OR NOT EXISTS ( SELECT 1 FROM roles role WHERE role.tenant_id=NEW.tenant_id AND role.role_id=NEW.role_id AND role.code=json_extract(NEW.payload_json,'$.role_code') ) OR EXISTS ( SELECT 1 FROM role_permission_events current WHERE current.event_id=NEW.event_id OR (current.tenant_id=NEW.tenant_id AND current.actor_user_id=NEW.actor_user_id AND current.request_id=NEW.request_id) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='rbac_role_permission_event_invalid';
  END IF;
  RETURN NEW;
END;
