CREATE OR REPLACE FUNCTION "fn_trg_invitation_events_owner_insert_prd060"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.delivery_status<>'pending' OR NEW.last_error_code IS NOT NULL OR NEW.dispatched_at IS NOT NULL OR NEW.updated_at<>NEW.created_at OR NOT EXISTS ( SELECT 1 FROM users actor WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.actor_user_id AND actor.role=NEW.actor_role AND actor.status='active' ) OR NOT EXISTS ( SELECT 1 FROM audit_logs audit WHERE audit.tenant_id=NEW.tenant_id AND audit.audit_log_id=NEW.audit_log_id AND audit.actor_user_id=NEW.actor_user_id AND audit.actor_role=NEW.actor_role AND audit.action=NEW.event_type AND audit.object_type='invitation' AND audit.object_id=NEW.invitation_id AND audit.object_name IS NULL AND audit.request_id=NEW.request_id AND audit.trace_id=NEW.trace_id AND audit.created_at=NEW.created_at ) OR NOT EXISTS ( SELECT 1 FROM invitations invitation WHERE invitation.tenant_id=NEW.tenant_id AND invitation.invitation_id=NEW.invitation_id AND ( ( NEW.event_type='user_row.invited' AND invitation.status='pending' AND invitation.invited_by=NEW.actor_user_id AND invitation.created_at=NEW.created_at AND (SELECT COUNT(*) FROM json_each(NEW.payload_json))=6 AND (SELECT COUNT(DISTINCT key) FROM json_each(NEW.payload_json))=6 AND NOT EXISTS ( SELECT 1 FROM json_each(NEW.payload_json) field WHERE field.key NOT IN ( 'schema_version','invitation_id','email_fingerprint', 'role_code','expires_at','invited_at' ) ) AND json_type(NEW.payload_json,'$.schema_version')='integer' AND (json_extract(NEW.payload_json,'$.schema_version'))::NUMERIC=1 AND json_extract(NEW.payload_json,'$.invitation_id')=invitation.invitation_id AND json_extract(NEW.payload_json,'$.email_fingerprint') =invitation.email_fingerprint AND json_extract(NEW.payload_json,'$.role_code')=invitation.role_code AND json_extract(NEW.payload_json,'$.expires_at')=invitation.expires_at AND json_extract(NEW.payload_json,'$.invited_at')=invitation.created_at ) OR ( NEW.event_type='invitation.accepted' AND invitation.status='accepted' AND invitation.accepted_user_id=NEW.actor_user_id AND invitation.accepted_at=NEW.created_at AND (SELECT COUNT(*) FROM json_each(NEW.payload_json))=6 AND (SELECT COUNT(DISTINCT key) FROM json_each(NEW.payload_json))=6 AND NOT EXISTS ( SELECT 1 FROM json_each(NEW.payload_json) field WHERE field.key NOT IN ( 'schema_version','invitation_id','user_id', 'email_fingerprint','role_code','accepted_at' ) ) AND json_type(NEW.payload_json,'$.schema_version')='integer' AND (json_extract(NEW.payload_json,'$.schema_version'))::NUMERIC=1 AND json_extract(NEW.payload_json,'$.invitation_id')=invitation.invitation_id AND json_extract(NEW.payload_json,'$.user_id')=invitation.accepted_user_id AND json_extract(NEW.payload_json,'$.email_fingerprint') =invitation.email_fingerprint AND json_extract(NEW.payload_json,'$.role_code')=invitation.role_code AND json_extract(NEW.payload_json,'$.accepted_at')=invitation.accepted_at ) ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='invitation_event_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
