CREATE OR REPLACE FUNCTION "fn_trg_adapter_contract_runs_failure_codes_insert_prd064"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (CASE WHEN json_valid(NEW.failure_codes_json) AND json_type(NEW.failure_codes_json)='array' AND json_array_length(NEW.failure_codes_json) BETWEEN 0 AND 16 THEN EXISTS ( SELECT 1 FROM json_each(NEW.failure_codes_json) item WHERE item.type<>'text' OR item.value NOT IN ( 'adapter.contract_fixture_missing','adapter.contract_fixture_unexpected', 'adapter.contract_fixture_invalid','adapter.contract_coverage_mismatch', 'adapter.contract_request_failed','adapter.contract_non_stream_failed', 'adapter.contract_stream_failed','adapter.contract_error_mapping_failed', 'adapter.contract_usage_failed','adapter.contract_probe_failed' ) ) OR (SELECT COUNT(*) FROM json_each(NEW.failure_codes_json))<>( SELECT COUNT(DISTINCT value) FROM json_each(NEW.failure_codes_json) ) OR NEW.failure_codes_json<>( SELECT json_group_array(value) FROM ( SELECT value FROM json_each(NEW.failure_codes_json) ORDER BY value ) ) ELSE TRUE END) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='adapter_contract_failure_codes_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
