LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT ( NEW.dispatch_status='pending' AND NEW.dispatch_attempts=0 AND NEW.next_attempt_at=NEW.created_at AND NEW.updated_at=NEW.created_at AND NEW.dispatched_at IS NULL AND NEW.claim_token IS NULL AND NEW.lease_owner_id IS NULL AND NEW.lease_expires_at IS NULL AND NEW.last_error_code IS NULL AND EXISTS ( SELECT 1 FROM adapter_contract_runs run WHERE run.tenant_id=NEW.tenant_id AND run.adapter_contract_run_id=NEW.adapter_contract_run_id AND run.status='failed' AND run.failed_cases>0 ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='adapter_contract_event_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_adapter_contract_event_validate_insert_prd064" BEFORE INSERT ON "adapter_contract_event_outbox" FOR EACH ROW EXECUTE FUNCTION "fn_trg_adapter_contract_event_validate_insert_prd064"();
CREATE OR REPLACE FUNCTION "fn_trg_adapter_contract_event_state_update_prd064"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT ( NEW.ctid=OLD.ctid AND NEW.event_id=OLD.event_id AND NEW.tenant_id=OLD.tenant_id AND NEW.adapter_contract_run_id=OLD.adapter_contract_run_id AND NEW.created_at=OLD.created_at AND unixepoch(NEW.updated_at)>=unixepoch(OLD.updated_at) AND ( ( ( (OLD.dispatch_status='pending' AND unixepoch(OLD.next_attempt_at)<=unixepoch(NEW.updated_at)) OR (OLD.dispatch_status='processing' AND OLD.dispatch_attempts BETWEEN 1 AND 9 AND unixepoch(OLD.lease_expires_at)<=unixepoch(NEW.updated_at)) ) AND NEW.dispatch_status='processing' AND NEW.dispatch_attempts=OLD.dispatch_attempts+1 AND NEW.next_attempt_at IS NULL AND NEW.dispatched_at IS NULL AND NEW.claim_token IS NOT NULL AND length(NEW.claim_token)=32 AND NEW.claim_token OPERATOR(public.!@@) '*[^0-9a-f]*' AND NEW.lease_owner_id IS NOT NULL AND length(NEW.lease_owner_id) BETWEEN 1 AND 128 AND NEW.lease_owner_id OPERATOR(public.!@@) '*[^A-Za-z0-9._:-]*' AND unixepoch(NEW.lease_expires_at)=unixepoch(NEW.updated_at)+30 AND NEW.last_error_code IS NULL ) OR ( OLD.dispatch_status='processing' AND NEW.dispatch_attempts=OLD.dispatch_attempts AND NEW.claim_token IS NULL AND NEW.lease_owner_id IS NULL AND NEW.lease_expires_at IS NULL AND ( ( unixepoch(OLD.lease_expires_at)>unixepoch(NEW.updated_at) AND ( (NEW.dispatch_status='dispatched' AND NEW.dispatched_at=NEW.updated_at AND NEW.next_attempt_at IS NULL AND NEW.last_error_code IS NULL) OR (OLD.dispatch_attempts<10 AND NEW.dispatch_status='pending' AND NEW.dispatched_at IS NULL AND NEW.last_error_code IS NOT NULL AND unixepoch(NEW.next_attempt_at)=unixepoch(NEW.updated_at)+CASE WHEN OLD.dispatch_attempts=1 THEN 5 WHEN OLD.dispatch_attempts=2 THEN 30 ELSE 300 END) OR (OLD.dispatch_attempts=10 AND NEW.dispatch_status='failed' AND NEW.next_attempt_at IS NULL AND NEW.dispatched_at IS NULL AND NEW.last_error_code IS NOT NULL) ) ) OR ( OLD.dispatch_attempts=10 AND unixepoch(OLD.lease_expires_at)<=unixepoch(NEW.updated_at) AND NEW.dispatch_status='failed' AND NEW.next_attempt_at IS NULL AND NEW.dispatched_at IS NULL AND NEW.last_error_code IS NOT NULL ) ) ) ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='adapter_contract_event_state_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_adapter_contract_event_state_update_prd064" BEFORE UPDATE ON "adapter_contract_event_outbox" FOR EACH ROW EXECUTE FUNCTION "fn_trg_adapter_contract_event_state_update_prd064"();
