CREATE OR REPLACE FUNCTION "fn_trg_role_dashboard_configs_insert_prd065"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (typeof(NEW.role_dashboard_config_id)<>'text' OR length(NEW.role_dashboard_config_id)<>36 OR substr(NEW.role_dashboard_config_id,1,4)<>'rdc_' OR substr(NEW.role_dashboard_config_id,5) OPERATOR(public.@@) '*[^0-9a-f]*' OR NEW.role_code NOT IN ( 'admin','developer','viewer','finance_admin','security_admin','ops_admin' ) OR NEW.default_view_code IS DISTINCT FROM CASE NEW.role_code WHEN 'admin' THEN 'executive' WHEN 'developer' THEN 'developer' WHEN 'viewer' THEN 'executive' WHEN 'finance_admin' THEN 'finance' WHEN 'security_admin' THEN 'security' WHEN 'ops_admin' THEN 'operations' END OR NEW.allowed_view_codes_json IS DISTINCT FROM CASE NEW.role_code WHEN 'admin' THEN '["executive","finance","security","developer","operations"]' WHEN 'developer' THEN '["developer","operations","executive"]' WHEN 'viewer' THEN '["executive"]' WHEN 'finance_admin' THEN '["finance","executive"]' WHEN 'security_admin' THEN '["security","executive"]' WHEN 'ops_admin' THEN '["operations","executive"]' END OR typeof(NEW.config_revision)<>'integer' OR NEW.config_revision<>1 OR NEW.status<>'active' OR NEW.created_at IS DISTINCT FROM NEW.updated_at OR EXISTS ( SELECT 1 FROM role_dashboard_configs current WHERE current.role_dashboard_config_id=NEW.role_dashboard_config_id OR (current.tenant_id=NEW.tenant_id AND current.role_code=NEW.role_code) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='role_dashboard_config_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_role_dashboard_configs_insert_prd065" BEFORE INSERT ON "role_dashboard_configs" FOR EACH ROW EXECUTE FUNCTION "fn_trg_role_dashboard_configs_insert_prd065"();
CREATE OR REPLACE FUNCTION "fn_trg_role_dashboard_configs_update_prd065"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.role_dashboard_config_id IS DISTINCT FROM OLD.role_dashboard_config_id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.role_code IS DISTINCT FROM OLD.role_code OR NEW.created_at IS DISTINCT FROM OLD.created_at OR typeof(NEW.config_revision)<>'integer' OR NEW.config_revision<>OLD.config_revision+1 OR unixepoch(NEW.updated_at)<=unixepoch(OLD.updated_at) OR ( NEW.default_view_code IS NOT DISTINCT FROM OLD.default_view_code AND NEW.allowed_view_codes_json IS NOT DISTINCT FROM OLD.allowed_view_codes_json AND NEW.status IS NOT DISTINCT FROM OLD.status ) OR CASE WHEN json_valid(NEW.allowed_view_codes_json) THEN CASE WHEN json_type(NEW.allowed_view_codes_json)='array' AND json_array_length(NEW.allowed_view_codes_json) BETWEEN 1 AND 5 THEN EXISTS ( SELECT 1 FROM json_each(NEW.allowed_view_codes_json) item WHERE item.type<>'text' OR item.value NOT IN ( 'executive','finance','security','developer','operations' ) ) OR (SELECT COUNT(*) FROM json_each(NEW.allowed_view_codes_json)) <>(SELECT COUNT(DISTINCT value) FROM json_each(NEW.allowed_view_codes_json)) OR NOT EXISTS ( SELECT 1 FROM json_each(NEW.allowed_view_codes_json) item WHERE item.type='text' AND item.value=NEW.default_view_code ) ELSE TRUE END ELSE TRUE END) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='role_dashboard_config_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_role_dashboard_configs_update_prd065" BEFORE UPDATE ON "role_dashboard_configs" FOR EACH ROW EXECUTE FUNCTION "fn_trg_role_dashboard_configs_update_prd065"();
CREATE OR REPLACE FUNCTION "fn_trg_role_dashboard_configs_delete_prd065"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
