CREATE OR REPLACE FUNCTION "fn_trg_tenants_role_dashboard_initialize_prd065"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  INSERT INTO role_dashboard_configs( role_dashboard_config_id,tenant_id,role_code,default_view_code, allowed_view_codes_json,config_revision,status,created_at,updated_at ) SELECT 'rdc_'||lower(hex(randomblob(16))),NEW.tenant_id,catalog.role_code, catalog.default_view_code,catalog.allowed_view_codes_json,1,'active', strftime('%Y-%m-%dT%H:%M:%SZ','now'),strftime('%Y-%m-%dT%H:%M:%SZ','now') FROM ( SELECT 'admin' AS role_code,'executive' AS default_view_code, '["executive","finance","security","developer","operations"]' AS allowed_view_codes_json UNION ALL SELECT 'developer','developer','["developer","operations","executive"]' UNION ALL SELECT 'viewer','executive','["executive"]' UNION ALL SELECT 'finance_admin','finance','["finance","executive"]' UNION ALL SELECT 'security_admin','security','["security","executive"]' UNION ALL SELECT 'ops_admin','operations','["operations","executive"]' ) catalog;
  RETURN NEW;
END;
$trigger$;
