CREATE OR REPLACE FUNCTION "fn_trg_chat_sessions_owner_insert_prd066"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.status<>'active' OR NEW.message_sequence<>0 OR NEW.state_revision<>1 OR NEW.cleared_at IS NOT NULL OR NEW.created_at IS DISTINCT FROM NEW.updated_at OR julianday(NEW.created_at) IS NULL OR julianday(NEW.expires_at) IS NULL OR julianday(NEW.expires_at)<=julianday(NEW.created_at) OR julianday(NEW.expires_at)>julianday(NEW.created_at,'+8 hours') OR NOT EXISTS ( SELECT 1 FROM users user_row WHERE user_row.tenant_id=NEW.tenant_id AND user_row.user_id=NEW.owner_user_id AND user_row.status='active' ) OR NOT EXISTS ( SELECT 1 FROM sessions session WHERE session.tenant_id=NEW.tenant_id AND session.session_id=NEW.owner_auth_session_id AND session.user_id=NEW.owner_user_id AND session.status='active' AND julianday(session.expires_at)>julianday(NEW.created_at) ) OR NOT EXISTS ( SELECT 1 FROM projects project WHERE project.tenant_id=NEW.tenant_id AND project.project_id=NEW.project_id AND project.status='active' ) OR NOT EXISTS ( SELECT 1 FROM environments environment WHERE environment.tenant_id=NEW.tenant_id AND environment.environment_id=NEW.environment_id AND environment.status='active' ) OR NOT EXISTS ( SELECT 1 FROM model_aliases alias JOIN environments environment ON environment.tenant_id=alias.tenant_id AND environment.environment_id=NEW.environment_id WHERE alias.tenant_id=NEW.tenant_id AND alias.model_alias_id=NEW.model_alias_id AND alias.alias=NEW.model_alias AND alias.status='active' AND environment.status='active' AND (alias.environment_id=NEW.environment_id OR (alias.environment_id IS NULL AND alias.environment=environment.code)) ) OR NOT EXISTS ( SELECT 1 FROM virtual_keys virtual_key JOIN environments environment ON environment.tenant_id=virtual_key.tenant_id AND environment.environment_id=NEW.environment_id WHERE virtual_key.tenant_id=NEW.tenant_id AND virtual_key.virtual_key_id=NEW.virtual_key_id AND virtual_key.project_id=NEW.project_id AND virtual_key.status='active' AND environment.status='active' AND (virtual_key.environment_id=NEW.environment_id OR (virtual_key.environment_id IS NULL AND virtual_key.environment=environment.code)) ) OR ( SELECT COUNT(*) FROM virtual_keys virtual_key JOIN environments environment ON environment.tenant_id=virtual_key.tenant_id AND environment.environment_id=NEW.environment_id WHERE virtual_key.tenant_id=NEW.tenant_id AND virtual_key.project_id=NEW.project_id AND virtual_key.status='active' AND environment.status='active' AND (virtual_key.environment_id=NEW.environment_id OR (virtual_key.environment_id IS NULL AND virtual_key.environment=environment.code)) )<>1 OR EXISTS ( SELECT 1 FROM chat_sessions current WHERE current.chat_session_id=NEW.chat_session_id OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='chat_session_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_chat_sessions_owner_insert_prd066" BEFORE INSERT ON "chat_sessions" FOR EACH ROW EXECUTE FUNCTION "fn_trg_chat_sessions_owner_insert_prd066"();
CREATE OR REPLACE FUNCTION "fn_trg_chat_sessions_state_update_prd066"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (OLD.status<>'active' OR NEW.ctid<>OLD.ctid OR NEW.chat_session_id<>OLD.chat_session_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.owner_user_id<>OLD.owner_user_id OR NEW.owner_auth_session_id<>OLD.owner_auth_session_id OR NEW.project_id<>OLD.project_id OR NEW.environment_id<>OLD.environment_id OR NEW.model_alias_id<>OLD.model_alias_id OR NEW.model_alias<>OLD.model_alias OR NEW.virtual_key_id<>OLD.virtual_key_id OR NEW.expires_at<>OLD.expires_at OR NEW.created_at<>OLD.created_at OR NEW.updated_at<OLD.updated_at OR NEW.state_revision<>OLD.state_revision+1 OR NEW.message_sequence NOT IN (OLD.message_sequence,OLD.message_sequence+1) OR NEW.status NOT IN ('active','cleared','expired') OR (NEW.status='active' AND NEW.cleared_at IS NOT NULL) OR (NEW.status='cleared' AND NEW.cleared_at IS NULL) OR (NEW.status='expired' AND NEW.cleared_at IS NOT NULL)) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='chat_session_state_conflict';
  END IF;
  RETURN NEW;
END;
$trigger$;
