CREATE OR REPLACE FUNCTION "fn_trg_chat_messages_owner_insert_prd066"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.status<>'in_flight' OR NEW.completed_at IS NOT NULL OR julianday(NEW.started_at) IS NULL OR NOT EXISTS ( SELECT 1 FROM chat_sessions session WHERE session.tenant_id=NEW.tenant_id AND session.chat_session_id=NEW.chat_session_id AND session.owner_user_id=NEW.owner_user_id AND session.status='active' AND session.message_sequence=NEW.message_sequence AND julianday(session.expires_at)>julianday(NEW.started_at) ) OR EXISTS ( SELECT 1 FROM chat_messages current WHERE current.chat_message_id=NEW.chat_message_id OR current.webhook_event_id=NEW.webhook_event_id OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) )) THEN
