  IF (OLD.status<>'in_flight' OR NEW.status NOT IN ('succeeded','failed') OR NEW.ctid<>OLD.ctid OR NEW.chat_message_id<>OLD.chat_message_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.chat_session_id<>OLD.chat_session_id OR NEW.owner_user_id<>OLD.owner_user_id OR NEW.client_message_id<>OLD.client_message_id OR NEW.message_sequence<>OLD.message_sequence OR NEW.gateway_request_id<>OLD.gateway_request_id OR NEW.gateway_trace_id<>OLD.gateway_trace_id OR NEW.webhook_event_id<>OLD.webhook_event_id OR NEW.started_at<>OLD.started_at OR NEW.completed_at IS NULL OR julianday(NEW.completed_at) IS NULL OR julianday(NEW.completed_at)<julianday(OLD.started_at) OR (NEW.status='succeeded' AND NEW.error_code IS NOT NULL) OR (NEW.status='failed' AND NEW.error_code IS NULL)) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='chat_message_state_conflict';
  END IF;
  RETURN NEW;
END;
