CREATE OR REPLACE FUNCTION "fn_trg_chat_execution_grants_owner_insert_prd066"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.status<>'issued' OR NEW.consumed_at IS NOT NULL OR NEW.revoked_at IS NOT NULL OR julianday(NEW.issued_at) IS NULL OR julianday(NEW.expires_at) IS NULL OR julianday(NEW.expires_at)<=julianday(NEW.issued_at) OR julianday(NEW.expires_at)>julianday(NEW.issued_at,'+30 seconds') OR NOT EXISTS ( SELECT 1 FROM chat_sessions session JOIN chat_messages message ON message.tenant_id=session.tenant_id AND message.chat_session_id=session.chat_session_id WHERE session.tenant_id=NEW.tenant_id AND session.chat_session_id=NEW.chat_session_id AND session.owner_user_id=NEW.owner_user_id AND session.owner_auth_session_id=NEW.owner_auth_session_id AND session.project_id=NEW.project_id AND session.environment_id=NEW.environment_id AND session.model_alias_id=NEW.model_alias_id AND session.virtual_key_id=NEW.virtual_key_id AND session.status='active' AND julianday(session.expires_at)>julianday(NEW.issued_at) AND message.chat_message_id=NEW.chat_message_id AND message.owner_user_id=NEW.owner_user_id AND message.gateway_request_id=NEW.gateway_request_id AND message.gateway_trace_id=NEW.gateway_trace_id AND message.status='in_flight' ) OR NOT EXISTS ( SELECT 1 FROM sessions auth_session WHERE auth_session.tenant_id=NEW.tenant_id AND auth_session.session_id=NEW.owner_auth_session_id AND auth_session.user_id=NEW.owner_user_id AND auth_session.status='active' AND julianday(auth_session.expires_at)>julianday(NEW.issued_at) ) OR EXISTS ( SELECT 1 FROM chat_execution_grants current WHERE current.chat_execution_grant_id=NEW.chat_execution_grant_id OR current.grant_hash=NEW.grant_hash OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='chat_grant_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_chat_execution_grants_owner_insert_prd066" BEFORE INSERT ON "chat_execution_grants" FOR EACH ROW EXECUTE FUNCTION "fn_trg_chat_execution_grants_owner_insert_prd066"();
CREATE OR REPLACE FUNCTION "fn_trg_chat_execution_grants_state_update_prd066"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (OLD.status<>'issued' OR NEW.status NOT IN ('consumed','revoked') OR NEW.ctid<>OLD.ctid OR NEW.chat_execution_grant_id<>OLD.chat_execution_grant_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.grant_hash<>OLD.grant_hash OR NEW.chat_session_id<>OLD.chat_session_id OR NEW.chat_message_id<>OLD.chat_message_id OR NEW.owner_user_id<>OLD.owner_user_id OR NEW.owner_auth_session_id<>OLD.owner_auth_session_id OR NEW.project_id<>OLD.project_id OR NEW.environment_id<>OLD.environment_id OR NEW.model_alias_id<>OLD.model_alias_id OR NEW.virtual_key_id<>OLD.virtual_key_id OR NEW.gateway_request_id<>OLD.gateway_request_id OR NEW.gateway_trace_id<>OLD.gateway_trace_id OR NEW.expires_at<>OLD.expires_at OR NEW.issued_at<>OLD.issued_at OR (NEW.status='consumed' AND ( NEW.consumed_at IS NULL OR NEW.revoked_at IS NOT NULL OR julianday(NEW.consumed_at) IS NULL OR julianday(NEW.consumed_at)<julianday(OLD.issued_at) OR julianday(NEW.consumed_at)>julianday(OLD.expires_at) )) OR (NEW.status='revoked' AND ( NEW.revoked_at IS NULL OR NEW.consumed_at IS NOT NULL OR julianday(NEW.revoked_at) IS NULL OR julianday(NEW.revoked_at)<julianday(OLD.issued_at) ))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='chat_grant_state_conflict';
  END IF;
  RETURN NEW;
END;
$trigger$;
