BEGIN
  IF (OLD.state<>'building' OR NEW.state<>'published' OR NEW.published_at IS NULL OR NEW.ctid<>OLD.ctid OR NEW.prompt_template_version_id<>OLD.prompt_template_version_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.prompt_template_id<>OLD.prompt_template_id OR NEW.version_number<>OLD.version_number OR NEW.definition_schema_version<>OLD.definition_schema_version OR NEW.definition_ciphertext<>OLD.definition_ciphertext OR NEW.definition_size_bytes<>OLD.definition_size_bytes OR NEW.variable_count<>OLD.variable_count OR NEW.project_scope<>OLD.project_scope OR NEW.recommended_model_count<>OLD.recommended_model_count OR NEW.change_summary_hmac<>OLD.change_summary_hmac OR NEW.created_by<>OLD.created_by OR NEW.created_at<>OLD.created_at OR NEW.request_id<>OLD.request_id OR NEW.trace_id<>OLD.trace_id OR unixepoch(NEW.published_at)<unixepoch(OLD.created_at) OR NOT EXISTS ( SELECT 1 FROM prompt_templates template WHERE template.tenant_id=NEW.tenant_id AND template.prompt_template_id=NEW.prompt_template_id AND template.current_version_id=NEW.prompt_template_version_id AND template.current_version_state='published' ) OR ( NEW.project_scope='all' AND EXISTS ( SELECT 1 FROM prompt_template_version_projects binding WHERE binding.tenant_id=NEW.tenant_id AND binding.prompt_template_id=NEW.prompt_template_id AND binding.prompt_template_version_id=NEW.prompt_template_version_id ) ) OR ( NEW.project_scope='selected' AND NOT EXISTS ( SELECT 1 FROM prompt_template_version_projects binding JOIN projects project ON project.tenant_id=binding.tenant_id AND project.project_id=binding.project_id WHERE binding.tenant_id=NEW.tenant_id AND binding.prompt_template_id=NEW.prompt_template_id AND binding.prompt_template_version_id=NEW.prompt_template_version_id AND project.status='active' ) ) OR EXISTS ( SELECT 1 FROM prompt_template_version_projects binding LEFT JOIN projects project ON project.tenant_id=binding.tenant_id AND project.project_id=binding.project_id WHERE binding.tenant_id=NEW.tenant_id AND binding.prompt_template_id=NEW.prompt_template_id AND binding.prompt_template_version_id=NEW.prompt_template_version_id AND (project.project_id IS NULL OR project.status<>'active') ) OR NEW.recommended_model_count<>( SELECT COUNT(*) FROM prompt_template_version_models binding WHERE binding.tenant_id=NEW.tenant_id AND binding.prompt_template_id=NEW.prompt_template_id AND binding.prompt_template_version_id=NEW.prompt_template_version_id ) OR EXISTS ( SELECT 1 FROM prompt_template_version_models binding LEFT JOIN model_aliases alias ON alias.tenant_id=binding.tenant_id AND alias.model_alias_id=binding.model_alias_id WHERE binding.tenant_id=NEW.tenant_id AND binding.prompt_template_id=NEW.prompt_template_id AND binding.prompt_template_version_id=NEW.prompt_template_version_id AND (alias.model_alias_id IS NULL OR alias.status<>'active') )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='prompt_template_version_seal_conflict';
  END IF;
  RETURN NEW;
END;
