CREATE OR REPLACE FUNCTION "fn_trg_chat_prompt_invocations_owner_insert_prd067"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.status<>'in_flight' OR NEW.failure_code IS NOT NULL OR NEW.completed_at IS NOT NULL OR NOT EXISTS ( SELECT 1 FROM prompt_template_versions version JOIN prompt_templates template ON template.tenant_id=version.tenant_id AND template.prompt_template_id=version.prompt_template_id AND template.current_version_id=version.prompt_template_version_id AND template.current_version_state=version.state JOIN chat_sessions chat_session ON chat_session.tenant_id=NEW.tenant_id AND chat_session.chat_session_id=NEW.chat_session_id AND chat_session.owner_user_id=NEW.actor_user_id AND chat_session.owner_auth_session_id=NEW.actor_auth_session_id JOIN chat_messages message ON message.tenant_id=chat_session.tenant_id AND message.chat_session_id=chat_session.chat_session_id AND message.chat_message_id=NEW.chat_message_id AND message.owner_user_id=NEW.actor_user_id AND message.gateway_request_id=NEW.gateway_request_id AND message.gateway_trace_id=NEW.gateway_trace_id WHERE version.tenant_id=NEW.tenant_id AND version.prompt_template_id=NEW.prompt_template_id AND version.prompt_template_version_id=NEW.prompt_template_version_id AND version.version_number=NEW.version_number AND version.state='published' AND template.status='active' AND chat_session.status='active' AND message.status='in_flight' AND ( version.project_scope='all' OR EXISTS ( SELECT 1 FROM prompt_template_version_projects binding WHERE binding.tenant_id=version.tenant_id AND binding.prompt_template_id=version.prompt_template_id AND binding.prompt_template_version_id=version.prompt_template_version_id AND binding.project_id=chat_session.project_id ) ) ) OR EXISTS ( SELECT 1 FROM chat_prompt_template_invocations current WHERE current.prompt_template_invocation_id=NEW.prompt_template_invocation_id OR (current.tenant_id=NEW.tenant_id AND current.chat_session_id=NEW.chat_session_id AND current.chat_message_id=NEW.chat_message_id) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='prompt_template_invocation_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_chat_prompt_invocations_owner_insert_prd067" BEFORE INSERT ON "chat_prompt_template_invocations" FOR EACH ROW EXECUTE FUNCTION "fn_trg_chat_prompt_invocations_owner_insert_prd067"();
CREATE OR REPLACE FUNCTION "fn_trg_chat_prompt_invocations_state_update_prd067"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (OLD.status<>'in_flight' OR NEW.status NOT IN ('succeeded','failed') OR NEW.ctid<>OLD.ctid OR NEW.prompt_template_invocation_id<>OLD.prompt_template_invocation_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.prompt_template_id<>OLD.prompt_template_id OR NEW.prompt_template_version_id<>OLD.prompt_template_version_id OR NEW.version_number<>OLD.version_number OR NEW.chat_session_id<>OLD.chat_session_id OR NEW.chat_message_id<>OLD.chat_message_id OR NEW.actor_user_id<>OLD.actor_user_id OR NEW.actor_auth_session_id<>OLD.actor_auth_session_id OR NEW.gateway_request_id<>OLD.gateway_request_id OR NEW.gateway_trace_id<>OLD.gateway_trace_id OR NEW.created_at<>OLD.created_at OR NEW.completed_at IS NULL OR unixepoch(NEW.completed_at)<unixepoch(OLD.created_at) OR (NEW.status='succeeded' AND NEW.failure_code IS NOT NULL) OR (NEW.status='failed' AND NEW.failure_code IS NULL) OR NOT EXISTS ( SELECT 1 FROM chat_messages message WHERE message.tenant_id=NEW.tenant_id AND message.chat_session_id=NEW.chat_session_id AND message.chat_message_id=NEW.chat_message_id AND message.owner_user_id=NEW.actor_user_id AND message.gateway_request_id=NEW.gateway_request_id AND message.gateway_trace_id=NEW.gateway_trace_id AND message.status=NEW.status AND message.completed_at=NEW.completed_at AND ( (NEW.status='succeeded' AND message.error_code IS NULL) OR (NEW.status='failed' AND message.error_code=NEW.failure_code) ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='prompt_template_invocation_state_conflict';
  END IF;
  RETURN NEW;
END;
