CREATE OR REPLACE FUNCTION "fn_trg_prompt_template_events_owner_insert_prd067"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.delivery_status<>'pending' OR NEW.last_error_code IS NOT NULL OR NEW.dispatched_at IS NOT NULL OR NEW.updated_at<>NEW.created_at OR NOT EXISTS ( SELECT 1 FROM prompt_template_versions version JOIN prompt_templates template ON template.tenant_id=version.tenant_id AND template.prompt_template_id=version.prompt_template_id AND template.current_version_id=version.prompt_template_version_id JOIN users actor ON actor.tenant_id=version.tenant_id AND actor.user_id=NEW.actor_user_id JOIN audit_logs audit ON audit.tenant_id=version.tenant_id AND audit.audit_log_id=NEW.publication_audit_log_id WHERE version.tenant_id=NEW.tenant_id AND version.prompt_template_id=NEW.prompt_template_id AND version.prompt_template_version_id=NEW.prompt_template_version_id AND version.version_number=NEW.version_number AND version.state='published' AND actor.status='active' AND audit.action='prompt_template.version_published' AND audit.object_type='prompt_template_version' AND audit.object_id=NEW.prompt_template_version_id AND audit.actor_user_id=NEW.actor_user_id AND audit.request_id=NEW.request_id AND audit.trace_id=NEW.trace_id AND audit.created_at=NEW.created_at AND (SELECT COUNT(*) FROM json_each(NEW.payload_json))=7 AND NOT EXISTS ( SELECT 1 FROM json_each(NEW.payload_json) field WHERE field.key NOT IN ( 'template_id','version_id','version_number','template_revision', 'project_scope','project_count','recommended_model_count' ) ) AND json_extract(NEW.payload_json,'$.template_id')=NEW.prompt_template_id AND json_extract(NEW.payload_json,'$.version_id')=NEW.prompt_template_version_id AND (json_extract(NEW.payload_json,'$.version_number'))::NUMERIC=NEW.version_number AND (json_extract(NEW.payload_json,'$.template_revision'))::NUMERIC=template.revision AND json_extract(NEW.payload_json,'$.project_scope')=version.project_scope AND (json_extract(NEW.payload_json,'$.project_count'))::NUMERIC=( SELECT COUNT(*) FROM prompt_template_version_projects binding WHERE binding.tenant_id=version.tenant_id AND binding.prompt_template_version_id=version.prompt_template_version_id ) AND (json_extract(NEW.payload_json,'$.recommended_model_count'))::NUMERIC =version.recommended_model_count ) OR EXISTS ( SELECT 1 FROM prompt_template_events current WHERE current.prompt_template_event_id=NEW.prompt_template_event_id OR current.publication_audit_log_id=NEW.publication_audit_log_id OR (current.tenant_id=NEW.tenant_id AND current.prompt_template_version_id=NEW.prompt_template_version_id AND current.event_type=NEW.event_type) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='prompt_template_event_owner_mismatch';
  END IF;
  RETURN NEW;
END;
