CREATE OR REPLACE FUNCTION "fn_trg_prompt_template_operations_owner_insert_prd067"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM prompt_templates template JOIN users actor ON actor.tenant_id=template.tenant_id AND actor.user_id=NEW.actor_user_id JOIN audit_logs audit ON audit.tenant_id=template.tenant_id AND audit.audit_log_id=NEW.result_audit_log_id WHERE template.tenant_id=NEW.tenant_id AND template.prompt_template_id=NEW.prompt_template_id AND template.revision=NEW.result_template_revision AND actor.status='active' AND audit.actor_user_id=NEW.actor_user_id AND audit.request_id=NEW.request_id AND audit.trace_id=NEW.trace_id AND audit.created_at=NEW.created_at AND audit.action=CASE NEW.operation WHEN 'create' THEN 'prompt_template.created' WHEN 'patch' THEN 'prompt_template.updated' WHEN 'publish' THEN 'prompt_template.version_published' END AND audit.object_type=CASE NEW.operation WHEN 'publish' THEN 'prompt_template_version' ELSE 'prompt_template' END AND audit.object_id=CASE NEW.operation WHEN 'publish' THEN NEW.prompt_template_version_id ELSE NEW.prompt_template_id END ) OR ( NEW.operation IN ('create','publish') AND NOT EXISTS ( SELECT 1 FROM prompt_template_versions version WHERE version.tenant_id=NEW.tenant_id AND version.prompt_template_id=NEW.prompt_template_id AND version.prompt_template_version_id=NEW.prompt_template_version_id AND version.version_number=NEW.version_number AND version.state='published' ) ) OR EXISTS ( SELECT 1 FROM prompt_template_operations current WHERE current.prompt_template_operation_id=NEW.prompt_template_operation_id OR (current.tenant_id=NEW.tenant_id AND current.request_id=NEW.request_id) OR current.result_audit_log_id=NEW.result_audit_log_id OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='prompt_template_operation_owner_mismatch';
  END IF;
  RETURN NEW;
END;
