CREATE OR REPLACE FUNCTION "fn_trg_policy_template_applications_owner_insert_prd068"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.status<>'applied' OR NOT EXISTS ( SELECT 1 FROM projects project WHERE project.tenant_id=NEW.tenant_id AND project.project_id=NEW.project_id AND project.status='active' ) OR NOT EXISTS ( SELECT 1 FROM users actor WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.actor_user_id AND actor.status='active' ) OR NOT EXISTS ( SELECT 1 FROM policies policy WHERE policy.tenant_id=NEW.tenant_id AND policy.policy_id=NEW.generated_policy_id AND policy.version=1 AND policy.status='active' AND policy.created_by=NEW.actor_user_id ) OR NOT EXISTS ( SELECT 1 FROM policy_snapshots previous WHERE previous.tenant_id=NEW.tenant_id AND previous.policy_snapshot_id=NEW.previous_snapshot_id AND previous.snapshot_version=NEW.previous_snapshot_version AND previous.state='published' ) OR NOT EXISTS ( SELECT 1 FROM policy_snapshots result WHERE result.tenant_id=NEW.tenant_id AND result.policy_snapshot_id=NEW.result_snapshot_id AND result.snapshot_version=NEW.result_snapshot_version AND result.state='published' AND result.operation='publish' AND result.previous_snapshot_id=NEW.previous_snapshot_id AND result.previous_snapshot_version=NEW.previous_snapshot_version AND result.request_id=NEW.request_id AND result.trace_id=NEW.trace_id AND result.created_by=NEW.actor_user_id ) OR EXISTS ( SELECT 1 FROM policy_template_applications current WHERE current.application_id=NEW.application_id OR (current.tenant_id=NEW.tenant_id AND current.request_id=NEW.request_id) OR (current.tenant_id=NEW.tenant_id AND current.preview_nonce=NEW.preview_nonce) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='policy_template_application_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
