CREATE OR REPLACE FUNCTION "fn_trg_policy_template_applications_state_update_prd068"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT ( OLD.status='applied' AND NEW.status='rolled_back' AND NEW.ctid=OLD.ctid AND NEW.application_id=OLD.application_id AND NEW.tenant_id=OLD.tenant_id AND NEW.policy_template_id=OLD.policy_template_id AND NEW.template_version=OLD.template_version AND NEW.template_definition_hash=OLD.template_definition_hash AND NEW.project_id=OLD.project_id AND NEW.actor_user_id=OLD.actor_user_id AND NEW.request_id=OLD.request_id AND NEW.trace_id=OLD.trace_id AND NEW.request_fingerprint=OLD.request_fingerprint AND NEW.preview_nonce=OLD.preview_nonce AND NEW.preview_as_of=OLD.preview_as_of AND NEW.applied_as_of=OLD.applied_as_of AND NEW.bindings_json=OLD.bindings_json AND NEW.bindings_hash=OLD.bindings_hash AND NEW.impact_hash=OLD.impact_hash AND NEW.applicability_fingerprint=OLD.applicability_fingerprint AND NEW.before_candidate_hash=OLD.before_candidate_hash AND NEW.after_candidate_hash=OLD.after_candidate_hash AND NEW.previous_snapshot_id=OLD.previous_snapshot_id AND NEW.previous_snapshot_version=OLD.previous_snapshot_version AND NEW.result_snapshot_id=OLD.result_snapshot_id AND NEW.result_snapshot_version=OLD.result_snapshot_version AND NEW.generated_policy_id=OLD.generated_policy_id AND NEW.generated_policy_version=OLD.generated_policy_version AND NEW.policy_audit_log_id=OLD.policy_audit_log_id AND NEW.policy_event_id=OLD.policy_event_id AND NEW.snapshot_audit_log_id=OLD.snapshot_audit_log_id AND NEW.snapshot_event_id=OLD.snapshot_event_id AND NEW.apply_audit_log_id=OLD.apply_audit_log_id AND NEW.template_event_id=OLD.template_event_id AND NEW.created_at=OLD.created_at AND EXISTS ( SELECT 1 FROM policies policy WHERE policy.tenant_id=OLD.tenant_id AND policy.policy_id=OLD.generated_policy_id AND policy.status='active' AND policy.version=1 ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='policy_template_application_immutable';
  END IF;
  RETURN NEW;
END;
$trigger$;
