CREATE OR REPLACE FUNCTION "fn_trg_policy_template_dependencies_owner_insert_prd068"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM policy_template_applications application WHERE application.tenant_id=NEW.tenant_id AND application.application_id=NEW.application_id ) OR NOT ( (NEW.resource_type='project' AND EXISTS ( SELECT 1 FROM projects resource WHERE resource.tenant_id=NEW.tenant_id AND resource.project_id=NEW.resource_id )) OR (NEW.resource_type='environment' AND EXISTS ( SELECT 1 FROM environments resource WHERE resource.tenant_id=NEW.tenant_id AND resource.environment_id=NEW.resource_id )) OR (NEW.resource_type='model_alias' AND EXISTS ( SELECT 1 FROM model_aliases resource WHERE resource.tenant_id=NEW.tenant_id AND resource.model_alias_id=NEW.resource_id AND NEW.resource_name=resource.alias )) OR (NEW.resource_type='model' AND EXISTS ( SELECT 1 FROM models resource WHERE resource.tenant_id=NEW.tenant_id AND resource.model_id=NEW.resource_id )) OR (NEW.resource_type='provider' AND EXISTS ( SELECT 1 FROM providers resource WHERE resource.tenant_id=NEW.tenant_id AND resource.provider_id=NEW.resource_id )) OR (NEW.resource_type='price_plan' AND EXISTS ( SELECT 1 FROM model_price_plans resource WHERE resource.tenant_id=NEW.tenant_id AND resource.price_plan_id=NEW.resource_id )) OR (NEW.resource_type='budget_rule' AND EXISTS ( SELECT 1 FROM budget_rules resource WHERE resource.tenant_id=NEW.tenant_id AND resource.budget_rule_id=NEW.resource_id )) OR (NEW.resource_type='virtual_key' AND EXISTS ( SELECT 1 FROM virtual_keys resource WHERE resource.tenant_id=NEW.tenant_id AND resource.virtual_key_id=NEW.resource_id )) OR (NEW.resource_type='runtime_capability' AND NEW.resource_id='policy-mask-v1') ) OR EXISTS ( SELECT 1 FROM policy_template_application_dependencies current WHERE current.application_dependency_id=NEW.application_dependency_id OR (current.tenant_id=NEW.tenant_id AND current.application_id=NEW.application_id AND current.resource_type=NEW.resource_type AND current.resource_id=NEW.resource_id AND current.relation=NEW.relation) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='policy_template_dependency_owner_mismatch';
  END IF;
  RETURN NEW;
END;
