CREATE OR REPLACE FUNCTION "fn_trg_policy_template_events_owner_insert_prd068"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM policy_template_applications application JOIN policy_templates template ON template.tenant_id=application.tenant_id AND template.policy_template_id=application.policy_template_id WHERE application.tenant_id=NEW.tenant_id AND application.application_id=NEW.application_id AND application.policy_template_id=NEW.policy_template_id AND application.template_version=NEW.template_version AND application.result_snapshot_id=NEW.result_snapshot_id AND application.result_snapshot_version=NEW.result_snapshot_version AND application.actor_user_id=NEW.actor_user_id AND application.apply_audit_log_id=NEW.audit_log_id AND application.request_id=NEW.request_id AND application.trace_id=NEW.trace_id AND application.template_event_id=NEW.policy_template_event_id AND json_extract(NEW.payload_json,'$.template_code')=template.template_code AND (json_extract(NEW.payload_json,'$.template_version'))::NUMERIC=application.template_version AND json_extract(NEW.payload_json,'$.application_id')=application.application_id AND json_extract(NEW.payload_json,'$.generated_policy_id')=application.generated_policy_id AND (json_extract(NEW.payload_json,'$.previous_snapshot_version'))::NUMERIC =application.previous_snapshot_version AND (json_extract(NEW.payload_json,'$.result_snapshot_version'))::NUMERIC =application.result_snapshot_version AND json_extract(NEW.payload_json,'$.impact_hash')=application.impact_hash AND json_extract(NEW.payload_json,'$.bindings_hash')=application.bindings_hash ) OR EXISTS ( SELECT 1 FROM policy_template_events current WHERE current.policy_template_event_id=NEW.policy_template_event_id OR (current.tenant_id=NEW.tenant_id AND current.application_id=NEW.application_id) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='policy_template_event_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
