CREATE OR REPLACE FUNCTION "fn_trg_intent_risk_results_owner_insert_prd069"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF ((NEW.source_kind='gateway' AND NOT EXISTS ( SELECT 1 FROM gateway_request_claims claim WHERE claim.tenant_id=NEW.tenant_id AND claim.request_id=NEW.source_request_id AND claim.trace_id=NEW.source_trace_id AND claim.virtual_key_id IS NOT DISTINCT FROM NEW.actor_id )) OR (NEW.source_kind='manual' AND NOT EXISTS ( SELECT 1 FROM users actor WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.actor_id AND actor.status='active' )) OR EXISTS ( SELECT 1 FROM intent_risk_results current WHERE current.intent_risk_result_id=NEW.intent_risk_result_id OR (current.tenant_id=NEW.tenant_id AND current.source_kind=NEW.source_kind AND current.source_request_id=NEW.source_request_id) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='intent_risk_result_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
