CREATE OR REPLACE FUNCTION "fn_trg_intent_risk_events_owner_insert_prd069"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM intent_risk_results result WHERE result.tenant_id=NEW.tenant_id AND result.intent_risk_result_id=NEW.intent_risk_result_id AND result.status IN ('detected','blocked') AND result.source_request_id=NEW.source_request_id AND result.source_trace_id=NEW.source_trace_id AND result.source_kind=NEW.source_kind AND result.classification_mode=NEW.classification_mode AND result.risk_type=NEW.risk_type AND result.risk_score=NEW.risk_score AND result.risk_score_scale=NEW.risk_score_scale AND result.action=NEW.action AND result.reason_code=NEW.reason_code AND result.detector_version=NEW.detector_version AND result.ruleset_version=NEW.ruleset_version AND result.input_truncated=NEW.input_truncated AND result.actor_type=NEW.actor_type AND result.actor_id=NEW.actor_id AND result.completed_at=NEW.created_at ) OR EXISTS ( SELECT 1 FROM intent_risk_events current WHERE current.intent_risk_event_id=NEW.intent_risk_event_id OR (current.tenant_id=NEW.tenant_id AND current.intent_risk_result_id=NEW.intent_risk_result_id) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='intent_risk_event_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
