CREATE OR REPLACE FUNCTION "fn_trg_request_logs_intent_insert_prd069"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (( ( (NEW.intent_risk_schedule_status='disabled' AND NEW.intent_risk_result_id IS NULL AND NEW.intent_risk_mode IS NULL AND NEW.intent_risk_type IS NULL AND NEW.intent_risk_score IS NULL AND NEW.intent_risk_action IS NULL AND NEW.intent_risk_reason_code IS NULL AND NEW.intent_risk_detector_version IS NULL AND NEW.intent_risk_input_truncated=0) OR (NEW.intent_risk_schedule_status='queued' AND NEW.intent_risk_result_id IS NOT NULL AND NEW.intent_risk_mode='async_light' AND NEW.intent_risk_type IS NULL AND NEW.intent_risk_score IS NULL AND NEW.intent_risk_action IS NULL AND NEW.intent_risk_reason_code='queued' AND NEW.intent_risk_detector_version IS NOT NULL) OR (NEW.intent_risk_schedule_status='skipped' AND NEW.intent_risk_result_id IS NOT NULL AND NEW.intent_risk_mode='async_light' AND NEW.intent_risk_type IS NULL AND NEW.intent_risk_score IS NULL AND NEW.intent_risk_action IS NULL AND NEW.intent_risk_reason_code IN ('queue_full','worker_unavailable') AND NEW.intent_risk_detector_version IS NOT NULL) OR (NEW.intent_risk_schedule_status='blocked' AND NEW.intent_risk_result_id IS NOT NULL AND NEW.intent_risk_mode='sync_strong' AND NEW.intent_risk_type IS NOT NULL AND NEW.intent_risk_score BETWEEN 9500 AND 10000 AND NEW.intent_risk_action='block' AND NEW.intent_risk_detector_version IS NOT NULL AND EXISTS ( SELECT 1 FROM intent_risk_results result WHERE result.tenant_id=NEW.tenant_id AND result.source_kind='gateway' AND result.source_request_id=NEW.request_id AND result.intent_risk_result_id=NEW.intent_risk_result_id AND result.status='blocked' AND result.classification_mode=NEW.intent_risk_mode AND result.risk_type=NEW.intent_risk_type AND result.risk_score=NEW.intent_risk_score AND result.action=NEW.intent_risk_action AND result.reason_code=NEW.intent_risk_reason_code AND result.detector_version=NEW.intent_risk_detector_version AND result.input_truncated=NEW.intent_risk_input_truncated )) OR (NEW.intent_risk_schedule_status='completed' AND NEW.intent_risk_result_id IS NOT NULL AND NEW.intent_risk_mode='sync_session' AND EXISTS ( SELECT 1 FROM intent_risk_results result WHERE result.tenant_id=NEW.tenant_id AND result.source_kind='gateway' AND result.source_request_id=NEW.request_id AND result.intent_risk_result_id=NEW.intent_risk_result_id AND result.classification_mode='sync_session' AND result.status IN ('clean','detected','blocked') AND NEW.intent_risk_type IS NOT DISTINCT FROM CASE WHEN result.risk_type='none' THEN NULL ELSE result.risk_type END AND NEW.intent_risk_score=result.risk_score AND NEW.intent_risk_action=result.action AND NEW.intent_risk_reason_code=result.reason_code AND NEW.intent_risk_detector_version=result.detector_version AND NEW.intent_risk_input_truncated=result.input_truncated )) OR (NEW.intent_risk_schedule_status='failed_closed' AND NEW.intent_risk_mode IN ('sync_strong','sync_session') AND NEW.intent_risk_type IS NULL AND NEW.intent_risk_score IS NULL AND NEW.intent_risk_action='none' AND NEW.intent_risk_reason_code IN ('classifier_failed','result_store_unavailable') AND NEW.intent_risk_detector_version IS NOT NULL AND ( (NEW.intent_risk_reason_code='result_store_unavailable' AND NEW.intent_risk_result_id IS NULL) OR (NEW.intent_risk_reason_code='classifier_failed' AND (NEW.intent_risk_result_id IS NULL OR EXISTS ( SELECT 1 FROM intent_risk_results result WHERE result.tenant_id=NEW.tenant_id AND result.source_kind='gateway' AND result.source_request_id=NEW.request_id AND result.intent_risk_result_id=NEW.intent_risk_result_id AND result.status='failed' AND result.classification_mode=NEW.intent_risk_mode AND result.detector_version=NEW.intent_risk_detector_version AND result.input_truncated=NEW.intent_risk_input_truncated ))) )) ) AND ( (NEW.session_risk_status='not_applicable' AND NEW.session_risk_score_id IS NULL AND NEW.session_risk_scope_type IS NULL AND NEW.session_risk_state IS NULL AND NEW.session_risk_reason_code IS NULL) OR (NEW.session_risk_status='disabled' AND NEW.session_risk_score_id IS NULL AND NEW.session_risk_scope_type IS NULL AND NEW.session_risk_state IS NULL AND NEW.session_risk_reason_code IN ('feature_disabled','no_session_identifiers')) OR (NEW.session_risk_status='clean' AND NEW.session_risk_score_id IS NULL AND NEW.session_risk_scope_type IS NOT NULL AND NEW.session_risk_state IS NULL AND NEW.session_risk_reason_code='clean_turn') OR (NEW.session_risk_status IN ('monitoring','high_risk','frozen') AND NEW.session_risk_score_id IS NOT NULL AND NEW.session_risk_scope_type IS NOT NULL AND NEW.session_risk_state=NEW.session_risk_status AND NEW.session_risk_reason_code IN ('risk_accumulated','session_frozen','key_frozen')) OR (NEW.session_risk_status='duplicate' AND NEW.session_risk_scope_type IS NOT NULL AND NEW.session_risk_reason_code='duplicate_turn') OR (NEW.session_risk_status='degraded' AND NEW.session_risk_score_id IS NULL AND NEW.session_risk_scope_type IS NOT NULL AND NEW.session_risk_state IS NULL AND NEW.session_risk_reason_code='store_degraded') OR (NEW.session_risk_status='failed' AND NEW.session_risk_reason_code IN ( 'store_unavailable','evidence_unavailable','session_frozen','key_frozen', 'turn_conflict','hmac_version_unavailable' )) ) ) IS NOT TRUE) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='request_log_session_risk_state_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_request_logs_intent_insert_prd069" BEFORE INSERT ON "request_logs" FOR EACH ROW EXECUTE FUNCTION "fn_trg_request_logs_intent_insert_prd069"();
CREATE OR REPLACE FUNCTION "fn_trg_session_risk_scores_owner_insert_prd070"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM virtual_keys key WHERE key.tenant_id=NEW.tenant_id AND key.virtual_key_id=NEW.virtual_key_id ) OR (NEW.scope_type='enterprise_chat' AND NOT EXISTS ( SELECT 1 FROM chat_sessions session WHERE session.tenant_id=NEW.tenant_id AND session.chat_session_id=NEW.chat_session_id AND session.virtual_key_id=NEW.virtual_key_id )) OR NOT EXISTS ( SELECT 1 FROM gateway_request_claims claim WHERE claim.tenant_id=NEW.tenant_id AND claim.request_id=NEW.last_source_request_id AND claim.trace_id=NEW.last_source_trace_id AND claim.virtual_key_id=NEW.virtual_key_id ) OR EXISTS ( SELECT 1 FROM session_risk_scores current WHERE current.session_risk_score_id=NEW.session_risk_score_id OR (current.tenant_id=NEW.tenant_id AND current.scope_type=NEW.scope_type AND current.scope_key=NEW.scope_key AND current.status IN ('monitoring','high_risk','frozen')) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='session_risk_score_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_session_risk_scores_owner_insert_prd070" BEFORE INSERT ON "session_risk_scores" FOR EACH ROW EXECUTE FUNCTION "fn_trg_session_risk_scores_owner_insert_prd070"();
CREATE OR REPLACE FUNCTION "fn_trg_session_risk_scores_state_update_prd070"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.session_risk_score_id<>OLD.session_risk_score_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.scope_type<>OLD.scope_type OR NEW.scope_key<>OLD.scope_key OR NEW.hmac_key_version<>OLD.hmac_key_version OR NEW.virtual_key_id<>OLD.virtual_key_id OR NEW.chat_session_id IS DISTINCT FROM OLD.chat_session_id OR NEW.score_scale<>OLD.score_scale OR NEW.threshold_version<>OLD.threshold_version OR NEW.created_at<>OLD.created_at OR NEW.state_revision<>OLD.state_revision+1 OR NEW.score<OLD.score OR NEW.risky_turn_count<OLD.risky_turn_count OR NEW.jailbreak_count<OLD.jailbreak_count OR NEW.sensitive_count<OLD.sensitive_count OR NEW.tool_inducement_count<OLD.tool_inducement_count OR NOT ( (OLD.status='monitoring' AND NEW.status IN ('monitoring','high_risk','frozen','expired')) OR (OLD.status='high_risk' AND NEW.status IN ('high_risk','frozen','resolved')) OR (OLD.status='frozen' AND NEW.status IN ('frozen','resolved')) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='session_risk_score_state_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_session_risk_scores_state_update_prd070" BEFORE UPDATE ON "session_risk_scores" FOR EACH ROW EXECUTE FUNCTION "fn_trg_session_risk_scores_state_update_prd070"();
