CREATE OR REPLACE FUNCTION "fn_trg_session_risk_observations_owner_insert_prd070"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM session_risk_scores score WHERE score.tenant_id=NEW.tenant_id AND score.session_risk_score_id=NEW.session_risk_score_id AND score.hmac_key_version=NEW.hmac_key_version AND score.score=NEW.score_after AND score.risky_turn_count=NEW.risky_turn_index AND score.state_revision=NEW.state_revision AND score.last_source_request_id=NEW.source_request_id AND score.last_source_trace_id=NEW.source_trace_id ) OR (NEW.turn_identity_type='chat_message' AND NOT EXISTS ( SELECT 1 FROM session_risk_scores score JOIN chat_messages message ON message.tenant_id=score.tenant_id AND message.chat_session_id=score.chat_session_id WHERE score.tenant_id=NEW.tenant_id AND score.session_risk_score_id=NEW.session_risk_score_id AND message.chat_message_id=NEW.chat_message_id AND message.gateway_request_id=NEW.source_request_id AND message.gateway_trace_id=NEW.source_trace_id )) OR (NEW.intent_risk_result_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM intent_risk_results result WHERE result.tenant_id=NEW.tenant_id AND result.intent_risk_result_id=NEW.intent_risk_result_id AND result.source_request_id=NEW.source_request_id AND result.risk_type=NEW.intent_risk_type AND result.risk_score=NEW.intent_risk_score AND result.risk_score_scale=NEW.intent_risk_score_scale )) OR EXISTS ( SELECT 1 FROM session_risk_observations current WHERE current.session_risk_observation_id=NEW.session_risk_observation_id OR (current.tenant_id=NEW.tenant_id AND current.session_risk_score_id=NEW.session_risk_score_id AND current.turn_key_digest=NEW.turn_key_digest) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='session_risk_observation_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
