CREATE OR REPLACE FUNCTION "fn_trg_session_risk_freezes_owner_insert_prd070"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM session_risk_scores score WHERE score.tenant_id=NEW.tenant_id AND score.session_risk_score_id=NEW.source_session_risk_score_id AND score.scope_type=NEW.target_scope_type AND score.scope_key=NEW.target_scope_key AND score.virtual_key_id=NEW.virtual_key_id AND score.status IN ('high_risk','frozen') AND score.score>=7000 AND score.risky_turn_count>=2 ) OR (NEW.created_by_type='system' AND ( NEW.target_type<>'session' OR NEW.created_by_id<>'session-risk-engine' )) OR (NEW.created_by_type='user' AND NOT EXISTS ( SELECT 1 FROM users actor WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.created_by_id AND actor.status='active' )) OR EXISTS ( SELECT 1 FROM session_risk_freezes current WHERE current.session_risk_freeze_id=NEW.session_risk_freeze_id OR (current.tenant_id=NEW.tenant_id AND current.source_session_risk_score_id=NEW.source_session_risk_score_id AND current.target_type=NEW.target_type AND current.status='active') OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='session_risk_freeze_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
