CREATE OR REPLACE FUNCTION "fn_trg_session_risk_freezes_release_update_prd070"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (OLD.status<>'active' OR NEW.status<>'released' OR NEW.ctid<>OLD.ctid OR NEW.session_risk_freeze_id<>OLD.session_risk_freeze_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.source_session_risk_score_id<>OLD.source_session_risk_score_id OR NEW.target_type<>OLD.target_type OR NEW.target_scope_type<>OLD.target_scope_type OR NEW.target_scope_key<>OLD.target_scope_key OR NEW.virtual_key_id<>OLD.virtual_key_id OR NEW.created_by_type<>OLD.created_by_type OR NEW.created_by_id<>OLD.created_by_id OR NEW.created_source_request_id<>OLD.created_source_request_id OR NEW.created_source_trace_id<>OLD.created_source_trace_id OR NEW.created_at<>OLD.created_at OR NEW.state_revision<>OLD.state_revision+1 OR NEW.released_by_type<>'user' OR NOT EXISTS ( SELECT 1 FROM users actor WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.released_by_id AND actor.status='active' )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='session_risk_freeze_state_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
