CREATE TRIGGER "trg_session_risk_freezes_delete_prd070" BEFORE DELETE ON "session_risk_freezes" FOR EACH ROW EXECUTE FUNCTION "fn_trg_session_risk_freezes_delete_prd070"();
CREATE OR REPLACE FUNCTION "fn_trg_session_risk_actions_owner_insert_prd070"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM session_risk_scores score WHERE score.tenant_id=NEW.tenant_id AND score.session_risk_score_id=NEW.session_risk_score_id AND score.score=NEW.score_snapshot AND score.state_revision=NEW.state_revision AND score.status=NEW.status_after ) OR (NEW.session_risk_freeze_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM session_risk_freezes freeze_row WHERE freeze_row.tenant_id=NEW.tenant_id AND freeze_row.session_risk_freeze_id=NEW.session_risk_freeze_id AND freeze_row.source_session_risk_score_id=NEW.session_risk_score_id AND ((NEW.action IN ('freeze_session','release_session') AND freeze_row.target_type='session') OR (NEW.action IN ('freeze_virtual_key','release_virtual_key') AND freeze_row.target_type='virtual_key')) )) OR (NEW.actor_type='user' AND NOT EXISTS ( SELECT 1 FROM users actor WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.actor_id AND actor.status='active' )) OR EXISTS ( SELECT 1 FROM session_risk_actions current WHERE current.session_risk_action_id=NEW.session_risk_action_id OR (NEW.idempotency_key_digest IS NOT NULL AND current.tenant_id=NEW.tenant_id AND current.actor_id=NEW.actor_id AND current.digest_key_version=NEW.digest_key_version AND current.idempotency_key_digest=NEW.idempotency_key_digest AND julianday(current.idempotency_expires_at)>julianday(NEW.created_at)) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='session_risk_action_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
