CREATE OR REPLACE FUNCTION "fn_trg_session_risk_events_owner_insert_prd070"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM session_risk_scores score JOIN session_risk_actions action ON action.tenant_id=score.tenant_id AND action.session_risk_score_id=score.session_risk_score_id WHERE score.tenant_id=NEW.tenant_id AND score.session_risk_score_id=NEW.session_risk_score_id AND action.session_risk_action_id=NEW.session_risk_action_id AND score.scope_type=NEW.scope_type AND score.scope_key=NEW.scope_key AND score.status=NEW.status AND score.score=NEW.score AND score.score_scale=NEW.score_scale AND score.risky_turn_count=NEW.risky_turn_count AND score.jailbreak_count=NEW.jailbreak_count AND score.sensitive_count=NEW.sensitive_count AND score.tool_inducement_count=NEW.tool_inducement_count AND score.state_revision=NEW.state_revision AND score.threshold_version=NEW.threshold_version AND action.state_revision=NEW.state_revision AND action.actor_type=NEW.actor_type AND action.actor_id=NEW.actor_id AND action.source_request_id=NEW.source_request_id AND action.source_trace_id=NEW.source_trace_id AND action.created_at=NEW.occurred_at ) OR (NEW.session_risk_freeze_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM session_risk_freezes freeze_row WHERE freeze_row.tenant_id=NEW.tenant_id AND freeze_row.session_risk_freeze_id=NEW.session_risk_freeze_id AND freeze_row.source_session_risk_score_id=NEW.session_risk_score_id AND freeze_row.target_type=NEW.target_type )) OR EXISTS ( SELECT 1 FROM session_risk_events current WHERE current.session_risk_event_id=NEW.session_risk_event_id OR (current.tenant_id=NEW.tenant_id AND current.session_risk_score_id=NEW.session_risk_score_id AND current.state_revision=NEW.state_revision) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='session_risk_event_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
