CREATE OR REPLACE FUNCTION "fn_trg_request_logs_intent_update_prd069"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF ((OLD.intent_risk_result_id IS NOT NULL AND NEW.intent_risk_result_id IS DISTINCT FROM OLD.intent_risk_result_id) OR (OLD.intent_risk_schedule_status<>'disabled' AND NEW.intent_risk_schedule_status IS DISTINCT FROM OLD.intent_risk_schedule_status) OR (OLD.intent_risk_mode IS NOT NULL AND NEW.intent_risk_mode IS DISTINCT FROM OLD.intent_risk_mode) OR (OLD.intent_risk_detector_version IS NOT NULL AND NEW.intent_risk_detector_version IS DISTINCT FROM OLD.intent_risk_detector_version) OR (OLD.session_risk_status<>'not_applicable' AND NEW.session_risk_status IS DISTINCT FROM OLD.session_risk_status) OR (OLD.session_risk_score_id IS NOT NULL AND NEW.session_risk_score_id IS DISTINCT FROM OLD.session_risk_score_id) OR (OLD.session_risk_scope_type IS NOT NULL AND NEW.session_risk_scope_type IS DISTINCT FROM OLD.session_risk_scope_type) OR (OLD.session_risk_state IS NOT NULL AND NEW.session_risk_state IS DISTINCT FROM OLD.session_risk_state) OR ( ( (NEW.intent_risk_schedule_status='disabled' AND NEW.intent_risk_result_id IS NULL AND NEW.intent_risk_mode IS NULL AND NEW.intent_risk_type IS NULL AND NEW.intent_risk_score IS NULL AND NEW.intent_risk_action IS NULL AND NEW.intent_risk_reason_code IS NULL AND NEW.intent_risk_detector_version IS NULL AND NEW.intent_risk_input_truncated=0) OR (NEW.intent_risk_schedule_status='queued' AND NEW.intent_risk_result_id IS NOT NULL AND NEW.intent_risk_mode='async_light' AND NEW.intent_risk_type IS NULL AND NEW.intent_risk_score IS NULL AND NEW.intent_risk_action IS NULL AND NEW.intent_risk_reason_code='queued' AND NEW.intent_risk_detector_version IS NOT NULL) OR (NEW.intent_risk_schedule_status='skipped' AND NEW.intent_risk_result_id IS NOT NULL AND NEW.intent_risk_mode='async_light' AND NEW.intent_risk_type IS NULL AND NEW.intent_risk_score IS NULL AND NEW.intent_risk_action IS NULL AND NEW.intent_risk_reason_code IN ('queue_full','worker_unavailable') AND NEW.intent_risk_detector_version IS NOT NULL) OR (NEW.intent_risk_schedule_status='blocked' AND NEW.intent_risk_result_id IS NOT NULL AND NEW.intent_risk_mode='sync_strong' AND NEW.intent_risk_type IS NOT NULL AND NEW.intent_risk_score BETWEEN 9500 AND 10000 AND NEW.intent_risk_action='block' AND NEW.intent_risk_detector_version IS NOT NULL) OR (NEW.intent_risk_schedule_status='completed' AND NEW.intent_risk_result_id IS NOT NULL AND NEW.intent_risk_mode='sync_session' AND EXISTS ( SELECT 1 FROM intent_risk_results result WHERE result.tenant_id=NEW.tenant_id AND result.source_kind='gateway' AND result.source_request_id=NEW.request_id AND result.intent_risk_result_id=NEW.intent_risk_result_id AND result.classification_mode='sync_session' AND NEW.intent_risk_type IS NOT DISTINCT FROM CASE WHEN result.risk_type='none' THEN NULL ELSE result.risk_type END AND NEW.intent_risk_score=result.risk_score AND NEW.intent_risk_action=result.action AND NEW.intent_risk_reason_code=result.reason_code AND NEW.intent_risk_detector_version=result.detector_version AND NEW.intent_risk_input_truncated=result.input_truncated )) OR (NEW.intent_risk_schedule_status='failed_closed' AND NEW.intent_risk_mode IN ('sync_strong','sync_session') AND NEW.intent_risk_type IS NULL AND NEW.intent_risk_score IS NULL AND NEW.intent_risk_action='none' AND NEW.intent_risk_reason_code IN ('classifier_failed','result_store_unavailable') AND NEW.intent_risk_detector_version IS NOT NULL) ) AND ( (NEW.session_risk_status='not_applicable' AND NEW.session_risk_score_id IS NULL AND NEW.session_risk_scope_type IS NULL AND NEW.session_risk_state IS NULL AND NEW.session_risk_reason_code IS NULL) OR (NEW.session_risk_status='disabled' AND NEW.session_risk_score_id IS NULL AND NEW.session_risk_scope_type IS NULL AND NEW.session_risk_state IS NULL AND NEW.session_risk_reason_code IN ('feature_disabled','no_session_identifiers')) OR (NEW.session_risk_status='clean' AND NEW.session_risk_score_id IS NULL AND NEW.session_risk_scope_type IS NOT NULL AND NEW.session_risk_state IS NULL AND NEW.session_risk_reason_code='clean_turn') OR (NEW.session_risk_status IN ('monitoring','high_risk','frozen') AND NEW.session_risk_score_id IS NOT NULL AND NEW.session_risk_scope_type IS NOT NULL AND NEW.session_risk_state=NEW.session_risk_status AND NEW.session_risk_reason_code IN ('risk_accumulated','session_frozen','key_frozen')) OR (NEW.session_risk_status='duplicate' AND NEW.session_risk_scope_type IS NOT NULL AND NEW.session_risk_reason_code='duplicate_turn') OR (NEW.session_risk_status='degraded' AND NEW.session_risk_score_id IS NULL AND NEW.session_risk_scope_type IS NOT NULL AND NEW.session_risk_state IS NULL AND NEW.session_risk_reason_code='store_degraded') OR (NEW.session_risk_status='failed' AND NEW.session_risk_reason_code IN ( 'store_unavailable','evidence_unavailable','session_frozen','key_frozen', 'turn_conflict','hmac_version_unavailable' )) ) ) IS NOT TRUE) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='request_log_session_risk_state_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_request_logs_intent_update_prd069" BEFORE UPDATE OF "tenant_id", "request_id", "intent_risk_result_id", "intent_risk_schedule_status", "intent_risk_mode", "intent_risk_type", "intent_risk_score", "intent_risk_action", "intent_risk_reason_code", "intent_risk_detector_version", "intent_risk_input_truncated", "session_risk_status", "session_risk_score_id", "session_risk_scope_type", "session_risk_state", "session_risk_reason_code" ON "request_logs" FOR EACH ROW EXECUTE FUNCTION "fn_trg_request_logs_intent_update_prd069"();
CREATE OR REPLACE FUNCTION "fn_trg_stream_session_tenant_insert"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF NEW.virtual_key_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM virtual_keys owner WHERE owner.virtual_key_id=NEW.virtual_key_id AND owner.tenant_id=NEW.tenant_id ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='stream_session_virtual_key_tenant_mismatch';
  END IF;
  IF NEW.environment_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM environments owner WHERE owner.environment_id=NEW.environment_id AND owner.tenant_id=NEW.tenant_id ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='stream_session_environment_tenant_mismatch';
  END IF;
  IF NEW.environment_id IS NOT NULL AND NEW.environment_code IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM environments owner WHERE owner.environment_id=NEW.environment_id AND owner.tenant_id=NEW.tenant_id AND owner.code=NEW.environment_code ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='stream_session_environment_snapshot_mismatch';
  END IF;
  IF NEW.project_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM projects owner WHERE owner.project_id=NEW.project_id AND owner.tenant_id=NEW.tenant_id ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='stream_session_project_tenant_mismatch';
  END IF;
  IF NEW.application_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM applications owner WHERE owner.application_id=NEW.application_id AND owner.tenant_id=NEW.tenant_id AND (NEW.project_id IS NULL OR owner.project_id=NEW.project_id) ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='stream_session_application_tenant_mismatch';
  END IF;
  IF NOT EXISTS ( SELECT 1 FROM models owner WHERE owner.model_id=NEW.model_id AND owner.tenant_id=NEW.tenant_id ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='stream_session_model_tenant_mismatch';
  END IF;
  IF NOT EXISTS ( SELECT 1 FROM providers owner WHERE owner.provider_id=NEW.provider_id AND owner.tenant_id=NEW.tenant_id AND owner.provider_code=NEW.provider_code ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='stream_session_provider_tenant_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_stream_session_tenant_insert" BEFORE INSERT ON "stream_sessions" FOR EACH ROW EXECUTE FUNCTION "fn_trg_stream_session_tenant_insert"();
CREATE OR REPLACE FUNCTION "fn_trg_stream_session_tenant_update"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF NEW.tenant_id<>OLD.tenant_id THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='stream_session_tenant_immutable';
  END IF;
  IF NEW.virtual_key_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM virtual_keys owner WHERE owner.virtual_key_id=NEW.virtual_key_id AND owner.tenant_id=NEW.tenant_id ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='stream_session_virtual_key_tenant_mismatch';
  END IF;
  IF NEW.environment_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM environments owner WHERE owner.environment_id=NEW.environment_id AND owner.tenant_id=NEW.tenant_id ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='stream_session_environment_tenant_mismatch';
  END IF;
  IF NEW.environment_id IS NOT NULL AND NEW.environment_code IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM environments owner WHERE owner.environment_id=NEW.environment_id AND owner.tenant_id=NEW.tenant_id AND owner.code=NEW.environment_code ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='stream_session_environment_snapshot_mismatch';
  END IF;
  IF NEW.project_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM projects owner WHERE owner.project_id=NEW.project_id AND owner.tenant_id=NEW.tenant_id ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='stream_session_project_tenant_mismatch';
  END IF;
  IF NEW.application_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM applications owner WHERE owner.application_id=NEW.application_id AND owner.tenant_id=NEW.tenant_id AND (NEW.project_id IS NULL OR owner.project_id=NEW.project_id) ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='stream_session_application_tenant_mismatch';
  END IF;
  IF NOT EXISTS ( SELECT 1 FROM models owner WHERE owner.model_id=NEW.model_id AND owner.tenant_id=NEW.tenant_id ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='stream_session_model_tenant_mismatch';
  END IF;
  IF NOT EXISTS ( SELECT 1 FROM providers owner WHERE owner.provider_id=NEW.provider_id AND owner.tenant_id=NEW.tenant_id AND owner.provider_code=NEW.provider_code ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='stream_session_provider_tenant_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_stream_session_tenant_update" BEFORE UPDATE OF "tenant_id", "virtual_key_id", "environment_id", "environment_code", "project_id", "application_id", "model_id", "provider_id", "provider_code" ON "stream_sessions" FOR EACH ROW EXECUTE FUNCTION "fn_trg_stream_session_tenant_update"();
CREATE OR REPLACE FUNCTION "fn_trg_stream_session_status_transition"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT ( NEW.status=OLD.status OR (OLD.status='starting' AND NEW.status IN ('active','upstream_failed')) OR (OLD.status='active' AND NEW.status IN ( 'completed','timed_out','client_disconnected','upstream_failed', 'output_blocked','output_safety_unavailable' )) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='stream_session_status_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_stream_session_status_transition" BEFORE UPDATE OF "status" ON "stream_sessions" FOR EACH ROW EXECUTE FUNCTION "fn_trg_stream_session_status_transition"();
CREATE OR REPLACE FUNCTION "fn_trg_stream_session_output_safety_insert_prd071"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.status IN ('output_blocked','output_safety_unavailable')) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='stream_session_output_safety_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_stream_session_output_safety_insert_prd071" BEFORE INSERT ON "stream_sessions" FOR EACH ROW EXECUTE FUNCTION "fn_trg_stream_session_output_safety_insert_prd071"();
CREATE OR REPLACE FUNCTION "fn_trg_stream_session_output_safety_update_prd071"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF ((NEW.status='output_blocked' AND (NEW.error_code IS DISTINCT FROM 'content_policy_violation' OR NEW.retryable<>0 OR NEW.completed_at IS NULL)) OR (NEW.status='output_safety_unavailable' AND (NEW.error_code IS DISTINCT FROM 'gateway.output_safety_unavailable' OR NEW.retryable<>0 OR NEW.completed_at IS NULL))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='stream_session_output_safety_state_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_stream_session_output_safety_update_prd071" BEFORE UPDATE OF "status", "error_code", "retryable" ON "stream_sessions" FOR EACH ROW EXECUTE FUNCTION "fn_trg_stream_session_output_safety_update_prd071"();
CREATE OR REPLACE FUNCTION "fn_trg_stream_session_provider_error_fact_update_prd056"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
