CREATE OR REPLACE FUNCTION "fn_trg_request_log_stream_insert"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.stream_session_id IS NULL)<>(NEW.stream_status IS NULL) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='request_log_stream_fields_incomplete';
  END IF;
  IF NEW.stream_session_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM stream_sessions owner WHERE owner.stream_session_id=NEW.stream_session_id AND owner.tenant_id=NEW.tenant_id AND owner.request_id=NEW.request_id AND owner.status=NEW.stream_status ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='request_log_stream_session_mismatch';
  END IF;
  IF NEW.stream_status IS NOT NULL AND NOT ( (NEW.stream_status='completed' AND NEW.status='success') OR (NEW.stream_status<>'completed' AND NEW.status='failed') ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='request_log_stream_status_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
