CREATE OR REPLACE FUNCTION "fn_trg_request_log_query_events_keys_insert_prd055"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT ( json_valid(NEW.filter_keys_json) AND CASE WHEN json_valid(NEW.filter_keys_json) THEN json_type(NEW.filter_keys_json) END='array' AND (SELECT COUNT(*) FROM json_each( CASE WHEN json_valid(NEW.filter_keys_json) THEN NEW.filter_keys_json ELSE '[]' END ))<=28 AND NOT EXISTS ( SELECT 1 FROM json_each( CASE WHEN json_valid(NEW.filter_keys_json) THEN NEW.filter_keys_json ELSE '[]' END ) item WHERE item.type<>'text' OR item.value NOT IN ( 'request_id','trace_id','status','model','request_model','resolved_model', 'provider_code','virtual_key_id','environment_id','project_id','application_id', 'snapshot_version','error_code','created_from','created_to','latency_ms_min', 'latency_ms_max','total_tokens_min','total_tokens_max','cost_amount_min', 'cost_amount_max','currency','terminal_stage','output_safety_status', 'output_safety_mode','output_safety_exposure','output_safety_billing' ) ) AND NOT EXISTS ( SELECT 1 FROM json_each( CASE WHEN json_valid(NEW.filter_keys_json) THEN NEW.filter_keys_json ELSE '[]' END ) earlier JOIN json_each( CASE WHEN json_valid(NEW.filter_keys_json) THEN NEW.filter_keys_json ELSE '[]' END ) later ON CAST(earlier.key AS INTEGER)<CAST(later.key AS INTEGER) WHERE CAST(earlier.value AS TEXT)>=CAST(later.value AS TEXT) ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='request_log_query_event_keys_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
