LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM uploaded_files file JOIN file_extracts extract ON extract.tenant_id=file.tenant_id AND extract.file_id=file.file_id JOIN users actor ON actor.tenant_id=file.tenant_id AND actor.user_id=NEW.requested_by WHERE file.tenant_id=NEW.tenant_id AND file.file_id=NEW.file_id AND file.status='ready' AND file.content_fingerprint=NEW.content_fingerprint AND extract.file_extract_id=NEW.file_extract_id AND extract.status='ready' AND extract.text_fingerprint=NEW.extract_fingerprint ) OR NEW.finding_count<>( SELECT COUNT(*) FROM file_security_findings finding WHERE finding.tenant_id=NEW.tenant_id AND finding.scan_id=NEW.scan_id AND finding.file_id=NEW.file_id ) OR NEW.high_finding_count<>( SELECT COUNT(*) FROM file_security_findings finding WHERE finding.tenant_id=NEW.tenant_id AND finding.scan_id=NEW.scan_id AND finding.file_id=NEW.file_id AND finding.severity IN ('high','critical') ) OR EXISTS ( SELECT 1 FROM file_security_findings finding WHERE finding.tenant_id=NEW.tenant_id AND finding.scan_id=NEW.scan_id AND finding.file_id=NEW.file_id AND (finding.created_at<>NEW.completed_at OR finding.updated_at<>NEW.completed_at) ) OR ( NEW.status='failed' AND ( SELECT COUNT(*) FROM file_security_findings finding WHERE finding.tenant_id=NEW.tenant_id AND finding.scan_id=NEW.scan_id )<>0 ) OR ( NEW.status<>'failed' AND NEW.risk_level<>CASE WHEN EXISTS ( SELECT 1 FROM file_security_findings finding WHERE finding.tenant_id=NEW.tenant_id AND finding.scan_id=NEW.scan_id AND finding.severity='critical' ) THEN 'critical' WHEN EXISTS ( SELECT 1 FROM file_security_findings finding WHERE finding.tenant_id=NEW.tenant_id AND finding.scan_id=NEW.scan_id AND finding.severity='high' ) THEN 'high' WHEN EXISTS ( SELECT 1 FROM file_security_findings finding WHERE finding.tenant_id=NEW.tenant_id AND finding.scan_id=NEW.scan_id AND finding.severity='medium' ) THEN 'medium' WHEN EXISTS ( SELECT 1 FROM file_security_findings finding WHERE finding.tenant_id=NEW.tenant_id AND finding.scan_id=NEW.scan_id AND finding.severity IN ('low','info') ) THEN 'low' ELSE 'none' END )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='file_security_scan_integrity_failed';
  END IF;
  RETURN NEW;
END;
