  IF (NOT ( NEW.ctid=OLD.ctid AND NEW.file_security_event_id=OLD.file_security_event_id AND NEW.tenant_id=OLD.tenant_id AND NEW.created_at=OLD.created_at AND unixepoch(NEW.updated_at)>=unixepoch(OLD.updated_at) AND ( NEW.dispatch_status NOT IN ('dispatched','failed') OR NOT EXISTS ( SELECT 1 FROM webhook_deliveries delivery WHERE delivery.tenant_id=NEW.tenant_id AND delivery.event_id=NEW.file_security_event_id AND delivery.event_type='file.prompt_injection_detected' AND delivery.delivery_kind='original' AND delivery.status='pending' ) ) AND ( ( ( (OLD.dispatch_status='pending' AND unixepoch(OLD.next_attempt_at)<=unixepoch(NEW.updated_at)) OR (OLD.dispatch_status='processing' AND OLD.dispatch_attempts BETWEEN 1 AND 9 AND unixepoch(OLD.lease_expires_at)<=unixepoch(NEW.updated_at)) ) AND NEW.dispatch_status='processing' AND NEW.dispatch_attempts=OLD.dispatch_attempts+1 AND NEW.next_attempt_at IS NULL AND NEW.dispatched_at IS NULL AND NEW.claim_token IS NOT NULL AND length(NEW.claim_token)=32 AND NEW.claim_token OPERATOR(public.!@@) '*[^0-9a-f]*' AND NEW.lease_owner_id IS NOT NULL AND length(NEW.lease_owner_id) BETWEEN 1 AND 128 AND NEW.lease_owner_id OPERATOR(public.!@@) '*[^A-Za-z0-9_.:-]*' AND unixepoch(NEW.lease_expires_at)=unixepoch(NEW.updated_at)+90 AND NEW.delivery_snapshot_frozen_at IS NOT DISTINCT FROM OLD.delivery_snapshot_frozen_at AND NEW.last_error_code IS NULL ) OR ( OLD.dispatch_status='processing' AND OLD.dispatch_attempts BETWEEN 1 AND 10 AND unixepoch(OLD.lease_expires_at)>unixepoch(NEW.updated_at) AND NEW.dispatch_status='failed' AND NEW.dispatch_attempts=OLD.dispatch_attempts AND NEW.next_attempt_at IS NULL AND NEW.dispatched_at IS NULL AND NEW.claim_token IS NULL AND NEW.lease_owner_id IS NULL AND NEW.lease_expires_at IS NULL AND NEW.delivery_snapshot_frozen_at IS NOT DISTINCT FROM OLD.delivery_snapshot_frozen_at AND NEW.last_error_code='webhook.payload_invalid' ) OR ( OLD.dispatch_status='processing' AND NEW.dispatch_status='processing' AND NEW.dispatch_attempts=OLD.dispatch_attempts AND NEW.next_attempt_at IS NULL AND NEW.dispatched_at IS NULL AND NEW.claim_token=OLD.claim_token AND NEW.lease_owner_id=OLD.lease_owner_id AND unixepoch(OLD.lease_expires_at)>unixepoch(NEW.updated_at) AND unixepoch(NEW.lease_expires_at)>=unixepoch(OLD.lease_expires_at) AND unixepoch(NEW.lease_expires_at)=unixepoch(NEW.updated_at)+90 AND NEW.delivery_snapshot_frozen_at IS NOT DISTINCT FROM OLD.delivery_snapshot_frozen_at AND NEW.last_error_code IS NULL ) OR ( OLD.dispatch_status='processing' AND NEW.dispatch_status='processing' AND NEW.dispatch_attempts=OLD.dispatch_attempts AND NEW.next_attempt_at IS NULL AND NEW.dispatched_at IS NULL AND NEW.claim_token=OLD.claim_token AND NEW.lease_owner_id=OLD.lease_owner_id AND OLD.delivery_snapshot_frozen_at IS NULL AND NEW.delivery_snapshot_frozen_at=NEW.updated_at AND unixepoch(OLD.lease_expires_at)>unixepoch(NEW.updated_at) AND unixepoch(NEW.lease_expires_at)>=unixepoch(OLD.lease_expires_at) AND unixepoch(NEW.lease_expires_at)=unixepoch(NEW.updated_at)+90 AND NEW.last_error_code IS NULL ) OR ( OLD.dispatch_status='processing' AND NEW.dispatch_attempts=OLD.dispatch_attempts AND NEW.claim_token IS NULL AND NEW.lease_owner_id IS NULL AND NEW.lease_expires_at IS NULL AND NEW.delivery_snapshot_frozen_at IS NOT DISTINCT FROM OLD.delivery_snapshot_frozen_at AND ( ( unixepoch(OLD.lease_expires_at)>unixepoch(NEW.updated_at) AND ( (NEW.dispatch_status='dispatched' AND NEW.dispatched_at=NEW.updated_at AND NEW.next_attempt_at IS NULL AND NEW.last_error_code IS NULL) OR (OLD.dispatch_attempts<10 AND NEW.dispatch_status='pending' AND NEW.dispatched_at IS NULL AND NEW.last_error_code='webhook.delivery_unavailable' AND unixepoch(NEW.next_attempt_at)=unixepoch(NEW.updated_at)+CASE WHEN OLD.dispatch_attempts=1 THEN 5 WHEN OLD.dispatch_attempts=2 THEN 30 ELSE 300 END) OR (OLD.dispatch_attempts=10 AND NEW.dispatch_status='failed' AND NEW.next_attempt_at IS NULL AND NEW.dispatched_at IS NULL AND NEW.last_error_code='webhook.delivery_unavailable') ) ) OR ( OLD.dispatch_attempts=10 AND unixepoch(OLD.lease_expires_at)<=unixepoch(NEW.updated_at) AND NEW.dispatch_status='failed' AND NEW.next_attempt_at IS NULL AND NEW.dispatched_at IS NULL AND NEW.last_error_code='webhook.delivery_unavailable' ) ) ) ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='file_security_event_outbox_state_invalid';
