CREATE OR REPLACE FUNCTION "fn_trg_model_experiments_owner_insert_prd075"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS(SELECT 1 FROM tenants WHERE tenant_id=NEW.tenant_id AND status='active') OR NOT EXISTS(SELECT 1 FROM users WHERE tenant_id=NEW.tenant_id AND user_id=NEW.created_by AND status='active') OR NOT EXISTS(SELECT 1 FROM projects WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND status='active') OR NOT EXISTS(SELECT 1 FROM environments WHERE tenant_id=NEW.tenant_id AND environment_id=NEW.environment_id AND status='active') OR NOT EXISTS(SELECT 1 FROM model_aliases WHERE tenant_id=NEW.tenant_id AND model_alias_id=NEW.model_alias_id AND environment_id=NEW.environment_id AND status='active') OR NOT EXISTS(SELECT 1 FROM models model JOIN providers provider ON provider.tenant_id=model.tenant_id AND provider.provider_id=model.provider_id WHERE model.tenant_id=NEW.tenant_id AND model.model_id=NEW.model_a_id AND model.provider_id=NEW.model_a_provider_id AND model.status='active' AND provider.status='active' AND provider.provider_code=NEW.model_a_provider_code AND json_valid(model.capabilities) AND (json_extract(model.capabilities,'$.chat'))::NUMERIC=1) OR NOT EXISTS(SELECT 1 FROM models model JOIN providers provider ON provider.tenant_id=model.tenant_id AND provider.provider_id=model.provider_id WHERE model.tenant_id=NEW.tenant_id AND model.model_id=NEW.model_b_id AND model.provider_id=NEW.model_b_provider_id AND model.status='active' AND provider.status='active' AND provider.provider_code=NEW.model_b_provider_code AND json_valid(model.capabilities) AND (json_extract(model.capabilities,'$.chat'))::NUMERIC=1) OR NEW.model_a_target_count<>(NEW.target_sample_count*NEW.model_a_allocation_bps+5000)/10000 OR NEW.model_b_target_count<>NEW.target_sample_count-NEW.model_a_target_count OR NEW.status<>'active' OR NEW.assigned_count<>0 OR NEW.model_a_assigned_count<>0 OR NEW.model_b_assigned_count<>0 OR NEW.facts_version<>0 OR NEW.finalization_generation<>0 OR NEW.started_at<>NEW.created_at OR unixepoch(NEW.sampling_deadline_at)<>unixepoch(NEW.started_at)+NEW.sampling_duration_seconds OR EXISTS(SELECT 1 FROM model_experiments current WHERE current.experiment_id=NEW.experiment_id OR (current.tenant_id=NEW.tenant_id AND current.created_by=NEW.created_by AND current.idempotency_key_hash=NEW.idempotency_key_hash) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='experiment_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
