CREATE OR REPLACE FUNCTION "fn_trg_model_experiments_immutable_update_prd075"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.experiment_id<>OLD.experiment_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.name<>OLD.name OR NEW.project_id<>OLD.project_id OR NEW.environment_id<>OLD.environment_id OR NEW.model_alias_id<>OLD.model_alias_id OR NEW.model_a_id<>OLD.model_a_id OR NEW.model_a_provider_id<>OLD.model_a_provider_id OR NEW.model_a_provider_code<>OLD.model_a_provider_code OR NEW.model_a_route_config_fingerprint<>OLD.model_a_route_config_fingerprint OR NEW.model_b_id<>OLD.model_b_id OR NEW.model_b_provider_id<>OLD.model_b_provider_id OR NEW.model_b_provider_code<>OLD.model_b_provider_code OR NEW.model_b_route_config_fingerprint<>OLD.model_b_route_config_fingerprint OR NEW.target_sample_count<>OLD.target_sample_count OR NEW.traffic_sample_bps<>OLD.traffic_sample_bps OR NEW.model_a_allocation_bps<>OLD.model_a_allocation_bps OR NEW.model_b_allocation_bps<>OLD.model_b_allocation_bps OR NEW.model_a_target_count<>OLD.model_a_target_count OR NEW.model_b_target_count<>OLD.model_b_target_count OR NEW.sampling_duration_seconds<>OLD.sampling_duration_seconds OR NEW.feedback_collection_enabled<>OLD.feedback_collection_enabled OR NEW.feedback_window_seconds<>OLD.feedback_window_seconds OR NEW.allocation_algorithm_version<>OLD.allocation_algorithm_version OR NEW.sampling_key_fingerprint<>OLD.sampling_key_fingerprint OR NEW.created_by<>OLD.created_by OR NEW.idempotency_key_hash<>OLD.idempotency_key_hash OR NEW.request_fingerprint<>OLD.request_fingerprint OR NEW.operation_request_id<>OLD.operation_request_id OR NEW.operation_trace_id<>OLD.operation_trace_id OR NEW.execution_max_seconds<>OLD.execution_max_seconds OR NEW.settlement_grace_seconds<>OLD.settlement_grace_seconds OR NEW.started_at<>OLD.started_at OR NEW.sampling_deadline_at<>OLD.sampling_deadline_at OR NEW.created_at<>OLD.created_at) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='experiment_immutable';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_model_experiments_immutable_update_prd075" BEFORE UPDATE ON "model_experiments" FOR EACH ROW EXECUTE FUNCTION "fn_trg_model_experiments_immutable_update_prd075"();
CREATE OR REPLACE FUNCTION "fn_trg_model_experiments_state_update_prd075"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.assigned_count<OLD.assigned_count OR NEW.model_a_assigned_count<OLD.model_a_assigned_count OR NEW.model_b_assigned_count<OLD.model_b_assigned_count OR NEW.assigned_count>OLD.assigned_count+1 OR NEW.model_a_assigned_count>OLD.model_a_assigned_count+1 OR NEW.model_b_assigned_count>OLD.model_b_assigned_count+1 OR NEW.facts_version<OLD.facts_version OR NEW.facts_version>OLD.facts_version+1 OR NEW.finalization_generation<OLD.finalization_generation OR (OLD.status='active' AND NEW.status NOT IN ('active','collecting_feedback')) OR (OLD.status='collecting_feedback' AND NEW.status NOT IN ('collecting_feedback','completed')) OR (OLD.status='completed' AND ( NEW.status<>'completed' OR NEW.facts_version<>OLD.facts_version OR NEW.assigned_count<>OLD.assigned_count OR NEW.model_a_assigned_count<>OLD.model_a_assigned_count OR NEW.model_b_assigned_count<>OLD.model_b_assigned_count OR NEW.feedback_fence_closed_at IS DISTINCT FROM OLD.feedback_fence_closed_at OR NEW.completed_at IS DISTINCT FROM OLD.completed_at)) OR (NEW.assigned_count<>OLD.assigned_count AND NEW.facts_version<>OLD.facts_version+1) OR (NEW.feedback_fence_closed_at IS DISTINCT FROM OLD.feedback_fence_closed_at AND NOT (OLD.feedback_fence_closed_at IS NULL AND NEW.feedback_fence_closed_at IS NOT NULL AND NEW.facts_version=OLD.facts_version)) OR (NEW.status='completed' AND ( (SELECT COUNT(*) FROM experiment_results result WHERE result.tenant_id=NEW.tenant_id AND result.experiment_id=NEW.experiment_id)<>2 OR NOT EXISTS(SELECT 1 FROM experiment_events event WHERE event.tenant_id=NEW.tenant_id AND event.experiment_id=NEW.experiment_id AND event.event_type='experiment.completed')))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='experiment_state_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_model_experiments_state_update_prd075" BEFORE UPDATE ON "model_experiments" FOR EACH ROW EXECUTE FUNCTION "fn_trg_model_experiments_state_update_prd075"();
CREATE OR REPLACE FUNCTION "fn_trg_model_experiments_finalization_update_prd075"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT ( (NEW.finalization_generation=OLD.finalization_generation AND NEW.finalization_owner_id IS NOT DISTINCT FROM OLD.finalization_owner_id AND NEW.finalization_lease_token IS NOT DISTINCT FROM OLD.finalization_lease_token AND NEW.finalization_lease_expires_at IS NOT DISTINCT FROM OLD.finalization_lease_expires_at AND (OLD.finalization_lease_token IS NULL OR ( NEW.status=OLD.status AND NEW.assigned_count=OLD.assigned_count AND NEW.model_a_assigned_count=OLD.model_a_assigned_count AND NEW.model_b_assigned_count=OLD.model_b_assigned_count AND NEW.facts_version=OLD.facts_version AND NEW.feedback_fence_closed_at IS NOT DISTINCT FROM OLD.feedback_fence_closed_at AND NEW.sampling_ended_at IS NOT DISTINCT FROM OLD.sampling_ended_at AND NEW.feedback_deadline_at IS NOT DISTINCT FROM OLD.feedback_deadline_at AND NEW.settlement_deadline_at IS NOT DISTINCT FROM OLD.settlement_deadline_at AND NEW.completion_reason IS NOT DISTINCT FROM OLD.completion_reason AND NEW.completed_at IS NOT DISTINCT FROM OLD.completed_at AND NEW.updated_at=OLD.updated_at))) OR ( OLD.status='collecting_feedback' AND NEW.status='collecting_feedback' AND NEW.feedback_fence_closed_at IS NOT NULL AND NEW.finalization_generation=OLD.finalization_generation+1 AND (OLD.finalization_lease_token IS NULL OR unixepoch(OLD.finalization_lease_expires_at)<=unixepoch('now')) AND NEW.finalization_owner_id IS NOT NULL AND NEW.finalization_lease_token IS NOT NULL AND NEW.finalization_lease_expires_at IS NOT NULL AND unixepoch(NEW.finalization_lease_expires_at)>unixepoch('now') AND unixepoch(NEW.finalization_lease_expires_at)<=unixepoch('now')+300 AND EXISTS(SELECT 1 FROM experiment_scheduler_tenants scheduler WHERE scheduler.tenant_id=NEW.tenant_id AND scheduler.lease_owner_id=NEW.finalization_owner_id AND scheduler.lease_token IS NOT NULL AND unixepoch(scheduler.lease_expires_at)>unixepoch('now') AND unixepoch(scheduler.lease_expires_at) >=unixepoch(NEW.finalization_lease_expires_at)) AND (SELECT COUNT(*) FROM experiment_request_executions execution WHERE execution.tenant_id=NEW.tenant_id AND execution.experiment_id=NEW.experiment_id AND execution.status='terminal')=NEW.assigned_count AND (SELECT COUNT(*) FROM experiment_request_outcomes outcome WHERE outcome.tenant_id=NEW.tenant_id AND outcome.experiment_id=NEW.experiment_id)=NEW.assigned_count AND (SELECT COUNT(*) FROM experiment_usage_settlements settlement WHERE settlement.tenant_id=NEW.tenant_id AND settlement.experiment_id=NEW.experiment_id AND settlement.status<>'pending')=NEW.assigned_count ) OR ( OLD.status='collecting_feedback' AND NEW.status='completed' AND NEW.finalization_generation=OLD.finalization_generation AND OLD.finalization_owner_id IS NOT NULL AND OLD.finalization_lease_token IS NOT NULL AND unixepoch(OLD.finalization_lease_expires_at)>unixepoch('now') AND NEW.finalization_owner_id IS NULL AND NEW.finalization_lease_token IS NULL AND NEW.finalization_lease_expires_at IS NULL AND EXISTS(SELECT 1 FROM experiment_scheduler_tenants scheduler WHERE scheduler.tenant_id=OLD.tenant_id AND scheduler.lease_owner_id=OLD.finalization_owner_id AND scheduler.lease_token IS NOT NULL AND unixepoch(scheduler.lease_expires_at)>unixepoch('now')) ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='experiment_finalization_state_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_model_experiments_finalization_update_prd075" BEFORE UPDATE ON "model_experiments" FOR EACH ROW EXECUTE FUNCTION "fn_trg_model_experiments_finalization_update_prd075"();
