CREATE OR REPLACE FUNCTION "fn_trg_model_experiments_feedback_fence_facts_prd075"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
DECLARE
  metahub_row_count BIGINT;
BEGIN
  IF OLD.feedback_fence_closed_at IS NULL AND NEW.feedback_fence_closed_at IS NOT NULL THEN
    UPDATE model_experiments SET facts_version=facts_version+1 WHERE tenant_id=NEW.tenant_id AND experiment_id=NEW.experiment_id AND facts_version<9223372036854775807;
    GET DIAGNOSTICS metahub_row_count = ROW_COUNT;
    IF metahub_row_count<>1 THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='experiment_facts_version_invalid';
    END IF;
  END IF;
  RETURN NEW;
END;
