LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS(SELECT 1 FROM gateway_request_claims claim WHERE claim.tenant_id=NEW.tenant_id AND claim.request_id=NEW.request_id AND claim.trace_id=NEW.trace_id AND claim.virtual_key_id IS NOT DISTINCT FROM NEW.virtual_key_id) OR (NEW.virtual_key_id IS NOT NULL AND NOT EXISTS( SELECT 1 FROM virtual_keys key WHERE key.tenant_id=NEW.tenant_id AND key.virtual_key_id=NEW.virtual_key_id AND key.project_id IS NOT DISTINCT FROM NEW.project_id AND key.application_id IS NOT DISTINCT FROM NEW.application_id AND key.environment IS NOT DISTINCT FROM NEW.environment_code AND ( key.environment_id IS NOT DISTINCT FROM NEW.environment_id OR ( key.environment_id IS NULL AND NEW.environment_id IS NOT NULL AND EXISTS(SELECT 1 FROM environments legacy_environment WHERE legacy_environment.tenant_id=key.tenant_id AND legacy_environment.environment_id=NEW.environment_id AND legacy_environment.code=key.environment) ) ))) OR (NEW.application_id IS NOT NULL AND NOT EXISTS( SELECT 1 FROM applications application WHERE application.tenant_id=NEW.tenant_id AND application.application_id=NEW.application_id AND application.project_id=NEW.project_id)) OR (NEW.environment_id IS NOT NULL AND NOT EXISTS( SELECT 1 FROM environments environment WHERE environment.tenant_id=NEW.tenant_id AND environment.environment_id=NEW.environment_id AND environment.code=NEW.environment_code)) OR EXISTS(SELECT 1 FROM gateway_request_scope_claims current WHERE (current.tenant_id=NEW.tenant_id AND current.request_id=NEW.request_id) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='experiment_scope_claim_owner_mismatch';
  END IF;
  RETURN NEW;
END;
