CREATE OR REPLACE FUNCTION "fn_trg_experiment_assignments_owner_insert_prd075"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS( SELECT 1 FROM model_experiments experiment JOIN gateway_request_scope_claims scope ON scope.tenant_id=experiment.tenant_id AND scope.project_id=experiment.project_id AND scope.environment_id=experiment.environment_id JOIN gateway_request_claims claim ON claim.tenant_id=scope.tenant_id AND claim.request_id=scope.request_id JOIN routing_decisions decision ON decision.tenant_id=scope.tenant_id AND decision.request_id=scope.request_id WHERE experiment.tenant_id=NEW.tenant_id AND experiment.experiment_id=NEW.experiment_id AND experiment.status='active' AND experiment.assigned_count<experiment.target_sample_count AND NEW.assignment_sequence=experiment.assigned_count+1 AND NEW.sample_bucket<experiment.traffic_sample_bps AND NEW.algorithm_version=experiment.allocation_algorithm_version AND scope.request_id=NEW.request_id AND scope.trace_id=NEW.trace_id AND scope.virtual_key_id=NEW.virtual_key_id AND claim.trace_id=NEW.trace_id AND claim.virtual_key_id=NEW.virtual_key_id AND decision.routing_decision_id=NEW.routing_decision_id AND decision.trace_id=NEW.trace_id AND decision.virtual_key_id=NEW.virtual_key_id AND decision.model_alias_id=experiment.model_alias_id AND decision.selected_model_id=NEW.model_id AND decision.provider_id=NEW.provider_id AND decision.provider_code=NEW.provider_code AND decision.decision_reason=CASE NEW.variant WHEN 'a' THEN 'experiment.variant_a' ELSE 'experiment.variant_b' END AND ((decision.decision_status='selected' AND decision.error_code IS NULL) OR (decision.decision_status='failed' AND decision.error_code='gateway.experiment_variant_unavailable')) AND json_valid(decision.candidate_summary) AND (SELECT COUNT(*) FROM json_each(decision.candidate_summary))=5 AND NOT EXISTS(SELECT 1 FROM json_each(decision.candidate_summary) field WHERE field.key NOT IN ('experiment_id','assignment_id','variant', 'assignment_reason','algorithm_version')) AND json_extract(decision.candidate_summary,'$.experiment_id')=NEW.experiment_id AND json_extract(decision.candidate_summary,'$.assignment_id')=NEW.assignment_id AND json_extract(decision.candidate_summary,'$.variant')=NEW.variant AND json_extract(decision.candidate_summary,'$.assignment_reason')=NEW.assignment_reason AND (json_extract(decision.candidate_summary,'$.algorithm_version'))::NUMERIC=NEW.algorithm_version AND NEW.model_id=CASE NEW.variant WHEN 'a' THEN experiment.model_a_id ELSE experiment.model_b_id END AND NEW.provider_id=CASE NEW.variant WHEN 'a' THEN experiment.model_a_provider_id ELSE experiment.model_b_provider_id END AND NEW.provider_code=CASE NEW.variant WHEN 'a' THEN experiment.model_a_provider_code ELSE experiment.model_b_provider_code END AND ( (NEW.assignment_reason='floor_forced' AND NEW.variant='a' AND ( experiment.model_a_assigned_count< (NEW.assignment_sequence*experiment.model_a_target_count)/experiment.target_sample_count OR experiment.model_b_assigned_count>=experiment.model_b_target_count)) OR (NEW.assignment_reason='ceiling_forced' AND NEW.variant='b' AND ( experiment.model_a_assigned_count>= (NEW.assignment_sequence*experiment.model_a_target_count +experiment.target_sample_count-1)/experiment.target_sample_count OR experiment.model_a_assigned_count>=experiment.model_a_target_count)) OR (NEW.assignment_reason='hmac_preferred' AND experiment.model_a_assigned_count>= (NEW.assignment_sequence*experiment.model_a_target_count)/experiment.target_sample_count AND experiment.model_a_assigned_count< (NEW.assignment_sequence*experiment.model_a_target_count +experiment.target_sample_count-1)/experiment.target_sample_count AND NEW.variant=CASE WHEN NEW.variant_bucket<experiment.model_a_allocation_bps THEN 'a' ELSE 'b' END) ) AND experiment.model_a_assigned_count+CASE WHEN NEW.variant='a' THEN 1 ELSE 0 END BETWEEN (NEW.assignment_sequence*experiment.model_a_target_count)/experiment.target_sample_count AND (NEW.assignment_sequence*experiment.model_a_target_count +experiment.target_sample_count-1)/experiment.target_sample_count ) OR EXISTS(SELECT 1 FROM experiment_assignments current WHERE current.assignment_id=NEW.assignment_id OR (current.tenant_id=NEW.tenant_id AND current.request_id=NEW.request_id) OR (current.tenant_id=NEW.tenant_id AND current.experiment_id=NEW.experiment_id AND current.assignment_sequence=NEW.assignment_sequence) OR (current.tenant_id=NEW.tenant_id AND current.routing_decision_id=NEW.routing_decision_id) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='experiment_assignment_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
