CREATE OR REPLACE FUNCTION "fn_trg_experiment_assignments_count_prd075"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
DECLARE
  metahub_row_count BIGINT;
BEGIN
  UPDATE model_experiments SET assigned_count=assigned_count+1, model_a_assigned_count=model_a_assigned_count+CASE WHEN NEW.variant='a' THEN 1 ELSE 0 END, model_b_assigned_count=model_b_assigned_count+CASE WHEN NEW.variant='b' THEN 1 ELSE 0 END, facts_version=facts_version+1, status=CASE WHEN assigned_count+1=target_sample_count THEN 'collecting_feedback' ELSE status END, sampling_ended_at=CASE WHEN assigned_count+1=target_sample_count THEN NEW.created_at ELSE sampling_ended_at END, feedback_deadline_at=CASE WHEN assigned_count+1=target_sample_count THEN strftime('%Y-%m-%dT%H:%M:%SZ',NEW.created_at, '+'||feedback_window_seconds||' seconds') ELSE feedback_deadline_at END, settlement_deadline_at=CASE WHEN assigned_count+1=target_sample_count THEN GREATEST( strftime('%Y-%m-%dT%H:%M:%SZ',NEW.created_at, '+'||feedback_window_seconds||' seconds'), strftime('%Y-%m-%dT%H:%M:%SZ',NEW.created_at, '+'||(execution_max_seconds+settlement_grace_seconds)||' seconds') ) ELSE settlement_deadline_at END, updated_at=NEW.created_at WHERE tenant_id=NEW.tenant_id AND experiment_id=NEW.experiment_id AND facts_version<9223372036854775807;
  GET DIAGNOSTICS metahub_row_count = ROW_COUNT;
  IF metahub_row_count<>1 THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='experiment_counter_overflow';
  END IF;
  RETURN NEW;
END;
$trigger$;
