CREATE OR REPLACE FUNCTION "fn_trg_experiment_executions_owner_insert_prd075"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS( SELECT 1 FROM experiment_assignments assignment JOIN model_experiments experiment ON experiment.tenant_id=assignment.tenant_id AND experiment.experiment_id=assignment.experiment_id WHERE assignment.tenant_id=NEW.tenant_id AND assignment.assignment_id=NEW.assignment_id AND assignment.execution_id=NEW.execution_id AND assignment.experiment_id=NEW.experiment_id AND assignment.request_id=NEW.request_id AND NEW.status='assigned' AND NEW.generation=1 AND unixepoch(NEW.absolute_deadline_at) =unixepoch(assignment.created_at)+experiment.execution_max_seconds AND unixepoch(NEW.lease_expires_at)>unixepoch(assignment.created_at) ) OR EXISTS(SELECT 1 FROM experiment_request_executions current WHERE current.execution_id=NEW.execution_id OR (current.tenant_id=NEW.tenant_id AND current.assignment_id=NEW.assignment_id) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='experiment_execution_owner_mismatch';
  END IF;
  RETURN NEW;
