CREATE OR REPLACE FUNCTION "fn_trg_experiment_executions_update_prd075"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.execution_id<>OLD.execution_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.experiment_id<>OLD.experiment_id OR NEW.assignment_id<>OLD.assignment_id OR NEW.request_id<>OLD.request_id OR NEW.absolute_deadline_at<>OLD.absolute_deadline_at OR NEW.created_at<>OLD.created_at OR NEW.generation<OLD.generation OR NEW.generation>OLD.generation+1 OR (NEW.generation=OLD.generation AND ( NEW.lease_owner_id<>OLD.lease_owner_id OR NEW.lease_token<>OLD.lease_token)) OR (NEW.generation=OLD.generation+1 AND unixepoch(OLD.lease_expires_at)>unixepoch('now')) OR (NEW.generation=OLD.generation+1 AND ( NEW.status<>OLD.status OR NEW.send_fence_at IS DISTINCT FROM OLD.send_fence_at)) OR (NEW.generation=OLD.generation AND OLD.status<>'terminal' AND (unixepoch(OLD.lease_expires_at)<=unixepoch('now') OR unixepoch(OLD.absolute_deadline_at)<=unixepoch('now')) AND NOT (NEW.status='terminal' AND length(OLD.lease_owner_id)=50 AND substr(OLD.lease_owner_id,1,18)='experiment-reaper-' AND substr(OLD.lease_owner_id,19) OPERATOR(public.!@@) '*[^0-9a-f]*' AND EXISTS(SELECT 1 FROM experiment_request_outcomes outcome WHERE outcome.tenant_id=NEW.tenant_id AND outcome.execution_id=NEW.execution_id AND outcome.recovery_generation=NEW.generation AND outcome.outcome_reason IN ( 'abandoned_before_provider','provider_outcome_unknown','recovered_terminal' ) AND unixepoch(outcome.facts_at)=unixepoch(NEW.updated_at)))) OR (OLD.status='assigned' AND NEW.status NOT IN ('assigned','provider_calling','terminal')) OR (OLD.status='provider_calling' AND NEW.status NOT IN ('provider_calling','terminal')) OR OLD.status='terminal' OR (OLD.send_fence_at IS NOT NULL AND NEW.send_fence_at IS DISTINCT FROM OLD.send_fence_at) OR (OLD.send_fence_at IS NULL AND NEW.send_fence_at IS NOT NULL AND NEW.status NOT IN ('provider_calling','terminal')) OR (NEW.status='terminal' AND NOT EXISTS( SELECT 1 FROM experiment_request_outcomes outcome WHERE outcome.tenant_id=NEW.tenant_id AND outcome.execution_id=NEW.execution_id AND outcome.assignment_id=NEW.assignment_id AND outcome.recovery_generation=NEW.generation AND unixepoch(outcome.facts_at)=unixepoch(NEW.updated_at)))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='experiment_execution_state_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
