CREATE OR REPLACE FUNCTION "fn_trg_experiment_outcomes_owner_insert_prd075"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS( SELECT 1 FROM experiment_assignments assignment JOIN experiment_request_executions execution ON execution.tenant_id=assignment.tenant_id AND execution.assignment_id=assignment.assignment_id AND execution.execution_id=assignment.execution_id WHERE assignment.tenant_id=NEW.tenant_id AND assignment.assignment_id=NEW.assignment_id AND assignment.experiment_id=NEW.experiment_id AND assignment.request_id=NEW.request_id AND assignment.variant=NEW.variant AND assignment.model_id=NEW.model_id AND assignment.provider_id=NEW.provider_id AND execution.execution_id=NEW.execution_id AND execution.status<>'terminal' AND execution.generation=NEW.recovery_generation AND unixepoch(NEW.facts_at)=unixepoch(NEW.created_at) AND unixepoch(NEW.facts_at)>=unixepoch(execution.created_at) AND ( (NEW.outcome_reason IN ( 'completed','gateway_failed','variant_unavailable', 'execution_timeout','cancelled' ) AND unixepoch(execution.lease_expires_at)>unixepoch('now') AND unixepoch(execution.absolute_deadline_at)>unixepoch('now') AND unixepoch(execution.lease_expires_at)>unixepoch(NEW.facts_at) AND unixepoch(execution.absolute_deadline_at)>unixepoch(NEW.facts_at) AND ( (NEW.outcome_reason='variant_unavailable' AND execution.status='assigned' AND execution.send_fence_at IS NULL) OR (NEW.outcome_reason='completed' AND execution.status='provider_calling' AND execution.send_fence_at IS NOT NULL) OR (NEW.outcome_reason IN ('gateway_failed','execution_timeout','cancelled') AND ( (execution.status='assigned' AND execution.send_fence_at IS NULL AND NEW.exposure_status='not_exposed' AND NEW.quality_eligible=0) OR (execution.status='provider_calling' AND execution.send_fence_at IS NOT NULL) )) )) OR ((unixepoch(execution.lease_expires_at)<=unixepoch(NEW.facts_at) OR unixepoch(execution.absolute_deadline_at)<=unixepoch(NEW.facts_at)) AND (unixepoch(execution.lease_expires_at)<=unixepoch('now') OR unixepoch(execution.absolute_deadline_at)<=unixepoch('now')) AND ( (NEW.outcome_reason='abandoned_before_provider' AND execution.status='assigned' AND execution.send_fence_at IS NULL) OR (NEW.outcome_reason IN ('provider_outcome_unknown','recovered_terminal') AND execution.status='provider_calling' AND execution.send_fence_at IS NOT NULL) )) ) AND (NEW.routing_attempt_id IS NULL OR EXISTS( SELECT 1 FROM routing_attempts attempt WHERE attempt.tenant_id=NEW.tenant_id AND attempt.routing_attempt_id=NEW.routing_attempt_id AND attempt.request_id=NEW.request_id AND attempt.model_id=NEW.model_id AND attempt.provider_id=NEW.provider_id AND attempt.attempt_sequence=1 AND attempt.attempt_role='primary' AND attempt.fallback_policy_id IS NULL AND attempt.status IN ('succeeded','failed') AND attempt.completed_at IS NOT NULL AND (NEW.gateway_status<>'success' OR attempt.status='succeeded'))) AND (NEW.stream_session_id IS NULL OR EXISTS( SELECT 1 FROM stream_sessions stream WHERE stream.tenant_id=NEW.tenant_id AND stream.stream_session_id=NEW.stream_session_id AND stream.request_id=NEW.request_id AND stream.model_id=NEW.model_id AND stream.provider_id=NEW.provider_id AND stream.status NOT IN ('starting','active') AND stream.completed_at IS NOT NULL AND (NEW.gateway_status<>'success' OR stream.status='completed'))) AND (NEW.outcome_reason<>'recovered_terminal' OR EXISTS( SELECT 1 FROM request_logs request_log WHERE request_log.tenant_id=NEW.tenant_id AND request_log.request_id=NEW.request_id AND request_log.model_id=NEW.model_id AND request_log.provider_id=NEW.provider_id AND request_log.status=NEW.gateway_status)) AND (NEW.outcome_reason<>'recovered_terminal' OR NEW.gateway_status<>'success' OR EXISTS(SELECT 1 FROM experiment_usage_settlements settlement WHERE settlement.tenant_id=NEW.tenant_id AND settlement.assignment_id=NEW.assignment_id AND settlement.status='recorded')) ) OR EXISTS(SELECT 1 FROM experiment_request_outcomes current WHERE current.outcome_id=NEW.outcome_id OR (current.tenant_id=NEW.tenant_id AND current.assignment_id=NEW.assignment_id) OR (current.tenant_id=NEW.tenant_id AND current.execution_id=NEW.execution_id) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='experiment_outcome_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
