LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS( SELECT 1 FROM experiment_assignments assignment WHERE assignment.tenant_id=NEW.tenant_id AND assignment.assignment_id=NEW.assignment_id AND assignment.usage_settlement_id=NEW.usage_settlement_id AND assignment.experiment_id=NEW.experiment_id AND assignment.request_id=NEW.request_id AND assignment.variant=NEW.variant AND assignment.model_id=NEW.model_id AND assignment.provider_id=NEW.provider_id AND (NEW.status='pending' OR (NEW.status='not_exposed' AND NEW.settlement_reason='variant_unavailable')) ) OR EXISTS(SELECT 1 FROM experiment_usage_settlements current WHERE current.usage_settlement_id=NEW.usage_settlement_id OR (current.tenant_id=NEW.tenant_id AND current.assignment_id=NEW.assignment_id) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='experiment_settlement_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_experiment_settlements_owner_insert_prd075" BEFORE INSERT ON "experiment_usage_settlements" FOR EACH ROW EXECUTE FUNCTION "fn_trg_experiment_settlements_owner_insert_prd075"();
CREATE OR REPLACE FUNCTION "fn_trg_experiment_settlements_update_prd075"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.usage_settlement_id<>OLD.usage_settlement_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.experiment_id<>OLD.experiment_id OR NEW.assignment_id<>OLD.assignment_id OR NEW.request_id<>OLD.request_id OR NEW.variant<>OLD.variant OR NEW.model_id<>OLD.model_id OR NEW.provider_id<>OLD.provider_id OR NEW.settlement_version<>OLD.settlement_version OR NEW.created_at<>OLD.created_at OR OLD.status<>'pending' OR NEW.status NOT IN ('recorded','not_exposed','unavailable') OR (NEW.status='recorded' AND NOT EXISTS( SELECT 1 FROM finops_ledger_entries entry WHERE entry.tenant_id=NEW.tenant_id AND entry.finops_ledger_entry_id=NEW.finops_ledger_entry_id AND entry.entry_type='usage_charge' AND entry.direction='debit' AND entry.quota_type='paid' AND entry.status='posted' AND entry.posting_source IN ('direct','spool_replay') AND entry.usage_ledger_id=NEW.usage_ledger_id AND entry.source_request_id=NEW.request_id AND entry.model_id=NEW.model_id AND entry.provider_id=NEW.provider_id AND NEW.normalization_status=CASE entry.cny_normalization_status WHEN 'normalized' THEN 'normalized' ELSE 'unavailable' END AND NEW.gross_cny_micros IS NOT DISTINCT FROM entry.normalized_cny_micros AND NEW.settled_at=entry.created_at AND NEW.updated_at=entry.created_at)) OR (NEW.status='not_exposed' AND NOT EXISTS( SELECT 1 FROM experiment_request_outcomes outcome WHERE outcome.tenant_id=NEW.tenant_id AND outcome.assignment_id=NEW.assignment_id AND outcome.exposure_status='not_exposed')) OR EXISTS(SELECT 1 FROM model_experiments experiment WHERE experiment.tenant_id=OLD.tenant_id AND experiment.experiment_id=OLD.experiment_id AND experiment.status='completed')) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='experiment_settlement_immutable';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_experiment_settlements_update_prd075" BEFORE UPDATE ON "experiment_usage_settlements" FOR EACH ROW EXECUTE FUNCTION "fn_trg_experiment_settlements_update_prd075"();
