CREATE OR REPLACE FUNCTION "fn_trg_experiment_settlements_facts_prd075"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
DECLARE
  metahub_row_count BIGINT;
BEGIN
  IF NEW.status<>OLD.status THEN
    UPDATE model_experiments SET facts_version=facts_version+1,updated_at=NEW.updated_at WHERE tenant_id=NEW.tenant_id AND experiment_id=NEW.experiment_id AND status<>'completed' AND facts_version<9223372036854775807;
    GET DIAGNOSTICS metahub_row_count = ROW_COUNT;
    IF metahub_row_count<>1 THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='experiment_facts_version_invalid';
    END IF;
  END IF;
