BEGIN
  IF (NOT EXISTS( SELECT 1 FROM experiment_assignments assignment JOIN request_feedbacks feedback ON feedback.tenant_id=assignment.tenant_id AND feedback.source_request_id=assignment.request_id JOIN model_experiments experiment ON experiment.tenant_id=assignment.tenant_id AND experiment.experiment_id=assignment.experiment_id WHERE assignment.tenant_id=NEW.tenant_id AND assignment.assignment_id=NEW.assignment_id AND assignment.experiment_id=NEW.experiment_id AND assignment.variant=NEW.variant AND assignment.request_id=NEW.source_request_id AND feedback.request_feedback_id=NEW.request_feedback_id AND feedback.model_id=assignment.model_id AND feedback.provider_id=assignment.provider_id AND feedback.rating=NEW.rating AND feedback.accepted=NEW.accepted AND experiment.feedback_collection_enabled=1 AND experiment.feedback_fence_closed_at IS NULL AND experiment.status<>'completed' AND (experiment.sampling_ended_at IS NULL OR unixepoch(NEW.attributed_at)<unixepoch(experiment.feedback_deadline_at)) ) OR EXISTS(SELECT 1 FROM experiment_feedback_attributions current WHERE current.feedback_attribution_id=NEW.feedback_attribution_id OR (current.tenant_id=NEW.tenant_id AND current.assignment_id=NEW.assignment_id) OR (current.tenant_id=NEW.tenant_id AND current.request_feedback_id=NEW.request_feedback_id) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='experiment_feedback_owner_mismatch';
