CREATE OR REPLACE FUNCTION "fn_trg_request_feedbacks_experiment_attribution_prd075"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  INSERT INTO experiment_feedback_attributions( feedback_attribution_id,tenant_id,experiment_id,assignment_id, request_feedback_id,source_request_id,variant,rating,accepted,attributed_at,created_at ) SELECT 'exfa_'||lower(hex(randomblob(16))),assignment.tenant_id, assignment.experiment_id,assignment.assignment_id,NEW.request_feedback_id, NEW.source_request_id,assignment.variant,NEW.rating,NEW.accepted, strftime('%Y-%m-%dT%H:%M:%SZ','now'),strftime('%Y-%m-%dT%H:%M:%SZ','now') FROM experiment_assignments assignment JOIN model_experiments experiment ON experiment.tenant_id=assignment.tenant_id AND experiment.experiment_id=assignment.experiment_id WHERE assignment.tenant_id=NEW.tenant_id AND assignment.request_id=NEW.source_request_id AND assignment.model_id=NEW.model_id AND assignment.provider_id=NEW.provider_id AND experiment.feedback_collection_enabled=1 AND experiment.feedback_fence_closed_at IS NULL AND experiment.status<>'completed' AND (experiment.sampling_ended_at IS NULL OR unixepoch('now')<unixepoch(experiment.feedback_deadline_at));
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_request_feedbacks_experiment_attribution_prd075" AFTER INSERT ON "request_feedbacks" FOR EACH ROW EXECUTE FUNCTION "fn_trg_request_feedbacks_experiment_attribution_prd075"();
CREATE OR REPLACE FUNCTION "fn_trg_experiment_results_owner_insert_prd075"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS( WITH arm_facts AS ( SELECT assignment.assignment_id,outcome.outcome_id, outcome.gateway_status,outcome.exposure_status, outcome.quality_eligible,outcome.quality_succeeded,outcome.latency_ms, settlement.status AS settlement_status, settlement.normalization_status,settlement.gross_cny_micros, attribution.rating,attribution.accepted FROM experiment_assignments assignment JOIN experiment_request_executions execution ON execution.tenant_id=assignment.tenant_id AND execution.assignment_id=assignment.assignment_id AND execution.execution_id=assignment.execution_id JOIN experiment_request_outcomes outcome ON outcome.tenant_id=assignment.tenant_id AND outcome.assignment_id=assignment.assignment_id AND outcome.execution_id=assignment.execution_id JOIN experiment_usage_settlements settlement ON settlement.tenant_id=assignment.tenant_id AND settlement.assignment_id=assignment.assignment_id AND settlement.usage_settlement_id=assignment.usage_settlement_id LEFT JOIN experiment_feedback_attributions attribution ON attribution.tenant_id=assignment.tenant_id AND attribution.assignment_id=assignment.assignment_id WHERE assignment.tenant_id=NEW.tenant_id AND assignment.experiment_id=NEW.experiment_id AND assignment.variant=NEW.variant ), latency_ranked AS ( SELECT latency_ms, row_number() OVER (ORDER BY latency_ms,outcome_id) AS latency_rank, count(*) OVER () AS latency_count FROM arm_facts WHERE quality_eligible=1 ), arm_totals AS ( SELECT COUNT(*) AS assigned_count, COALESCE(SUM(gateway_status='success'),0) AS gateway_success_count, COALESCE(SUM(gateway_status='failed'),0) AS gateway_failure_count, COALESCE(SUM(gateway_status='unresolved'),0) AS unresolved_count, COALESCE(SUM(exposure_status='exposed'),0) AS exposed_count, COALESCE(SUM(exposure_status='not_exposed'),0) AS not_exposed_count, COALESCE(SUM(exposure_status='unknown'),0) AS exposure_unknown_count, COALESCE(SUM(quality_eligible=1 AND quality_succeeded=1),0) AS quality_success_count, COALESCE(SUM(quality_eligible=1 AND quality_succeeded=0),0) AS quality_failure_count, COALESCE(SUM(CASE WHEN quality_eligible=1 THEN latency_ms ELSE 0 END),0) AS total_latency_ms, COALESCE(SUM(settlement_status='recorded'),0) AS settlement_recorded_count, COALESCE(SUM(settlement_status='not_exposed'),0) AS settlement_not_exposed_count, COALESCE(SUM(settlement_status='unavailable'),0) AS settlement_unavailable_count, COALESCE(SUM(CASE WHEN settlement_status='recorded' AND normalization_status='normalized' THEN gross_cny_micros ELSE 0 END),0) AS gross_normalized_cny_micros, COALESCE(SUM(settlement_status='recorded' AND normalization_status='normalized'),0) AS cost_known_count, COALESCE(SUM(exposure_status='unknown' OR settlement_status='unavailable' OR (settlement_status='recorded' AND gross_cny_micros IS NULL)),0) AS cost_unknown_count, COALESCE(SUM(rating IS NOT NULL),0) AS feedback_count, COALESCE(SUM(CASE WHEN rating IS NOT NULL THEN rating ELSE 0 END),0) AS rating_sum, COALESCE(SUM(rating IS NOT NULL AND accepted=1),0) AS accepted_count FROM arm_facts ), expected AS ( SELECT arm_totals.*, quality_success_count+quality_failure_count AS latency_sample_count, CASE WHEN gateway_success_count+gateway_failure_count=0 THEN NULL ELSE (2*gateway_success_count*10000 +gateway_success_count+gateway_failure_count) /(2*(gateway_success_count+gateway_failure_count)) END AS gateway_success_rate_bps, CASE WHEN quality_success_count+quality_failure_count=0 THEN NULL ELSE (2*quality_success_count*10000 +quality_success_count+quality_failure_count) /(2*(quality_success_count+quality_failure_count)) END AS quality_success_rate_bps, CASE WHEN quality_success_count+quality_failure_count=0 THEN NULL ELSE (total_latency_ms/(quality_success_count+quality_failure_count))*1000 +(2*(total_latency_ms%(quality_success_count+quality_failure_count))*1000 +quality_success_count+quality_failure_count) /(2*(quality_success_count+quality_failure_count)) END AS average_latency_micros, (SELECT latency_ms FROM latency_ranked WHERE latency_rank=(95*latency_count+99)/100) AS p95_latency_ms, CASE WHEN cost_known_count=0 THEN NULL ELSE gross_normalized_cny_micros/cost_known_count +(2*(gross_normalized_cny_micros%cost_known_count)+cost_known_count) /(2*cost_known_count) END AS average_cost_cny_micros, CASE WHEN feedback_count=0 THEN 0 ELSE (2*rating_sum*1000+feedback_count)/(2*feedback_count) END AS average_rating_milli, CASE WHEN feedback_count=0 THEN 0 ELSE (2*accepted_count*10000+feedback_count)/(2*feedback_count) END AS adoption_rate_bps FROM arm_totals ) SELECT 1 FROM model_experiments experiment JOIN experiment_scheduler_tenants scheduler ON scheduler.tenant_id=experiment.tenant_id AND scheduler.lease_owner_id=experiment.finalization_owner_id AND scheduler.lease_token IS NOT NULL AND unixepoch(scheduler.lease_expires_at)>unixepoch('now') AND unixepoch(scheduler.lease_expires_at) >=unixepoch(experiment.finalization_lease_expires_at) CROSS JOIN expected WHERE experiment.tenant_id=NEW.tenant_id AND experiment.experiment_id=NEW.experiment_id AND experiment.status='collecting_feedback' AND experiment.feedback_fence_closed_at IS NOT NULL AND experiment.facts_version=NEW.facts_version AND experiment.finalization_generation>=1 AND experiment.finalization_owner_id IS NOT NULL AND experiment.finalization_lease_token IS NOT NULL AND experiment.finalization_lease_expires_at IS NOT NULL AND unixepoch(experiment.finalization_lease_expires_at)>unixepoch('now') AND NEW.statistics_version=1 AND NEW.model_id=CASE NEW.variant WHEN 'a' THEN experiment.model_a_id ELSE experiment.model_b_id END AND NEW.provider_id=CASE NEW.variant WHEN 'a' THEN experiment.model_a_provider_id ELSE experiment.model_b_provider_id END AND NEW.provider_code=CASE NEW.variant WHEN 'a' THEN experiment.model_a_provider_code ELSE experiment.model_b_provider_code END AND NEW.route_config_fingerprint=CASE NEW.variant WHEN 'a' THEN experiment.model_a_route_config_fingerprint ELSE experiment.model_b_route_config_fingerprint END AND NEW.assigned_count=CASE NEW.variant WHEN 'a' THEN experiment.model_a_assigned_count ELSE experiment.model_b_assigned_count END AND NEW.feedback_enabled=experiment.feedback_collection_enabled AND NEW.assigned_count=expected.assigned_count AND NEW.gateway_success_count=expected.gateway_success_count AND NEW.gateway_failure_count=expected.gateway_failure_count AND NEW.unresolved_count=expected.unresolved_count AND NEW.exposed_count=expected.exposed_count AND NEW.not_exposed_count=expected.not_exposed_count AND NEW.exposure_unknown_count=expected.exposure_unknown_count AND NEW.quality_success_count=expected.quality_success_count AND NEW.quality_failure_count=expected.quality_failure_count AND NEW.gateway_success_rate_bps IS NOT DISTINCT FROM expected.gateway_success_rate_bps AND NEW.quality_success_rate_bps IS NOT DISTINCT FROM expected.quality_success_rate_bps AND NEW.latency_sample_count=expected.latency_sample_count AND NEW.total_latency_ms=expected.total_latency_ms AND NEW.average_latency_micros IS NOT DISTINCT FROM expected.average_latency_micros AND NEW.p95_latency_ms IS NOT DISTINCT FROM expected.p95_latency_ms AND NEW.settlement_recorded_count=expected.settlement_recorded_count AND NEW.settlement_not_exposed_count=expected.settlement_not_exposed_count AND NEW.settlement_unavailable_count=expected.settlement_unavailable_count AND NEW.gross_normalized_cny_micros=expected.gross_normalized_cny_micros AND NEW.cost_known_count=expected.cost_known_count AND NEW.cost_unknown_count=expected.cost_unknown_count AND NEW.average_cost_cny_micros IS NOT DISTINCT FROM expected.average_cost_cny_micros AND NEW.feedback_count=expected.feedback_count AND NEW.rating_sum=expected.rating_sum AND NEW.average_rating_milli=expected.average_rating_milli AND NEW.accepted_count=expected.accepted_count AND NEW.adoption_rate_bps=expected.adoption_rate_bps AND (expected.latency_sample_count=0 OR expected.total_latency_ms/expected.latency_sample_count<9223372036854775 OR (expected.total_latency_ms/expected.latency_sample_count=9223372036854775 AND (2*(expected.total_latency_ms%expected.latency_sample_count)*1000 +expected.latency_sample_count)/(2*expected.latency_sample_count)<=807)) AND NEW.facts_through_at=experiment.updated_at AND unixepoch(NEW.facts_through_at)>=unixepoch(experiment.feedback_fence_closed_at) AND unixepoch(NEW.facts_through_at)<=unixepoch(NEW.created_at) AND unixepoch(NEW.created_at)<unixepoch(experiment.finalization_lease_expires_at) AND NOT EXISTS(SELECT 1 FROM experiment_assignments assignment WHERE assignment.tenant_id=NEW.tenant_id AND assignment.experiment_id=NEW.experiment_id AND unixepoch(assignment.created_at)>unixepoch(NEW.facts_through_at)) AND NOT EXISTS(SELECT 1 FROM experiment_request_executions execution WHERE execution.tenant_id=NEW.tenant_id AND execution.experiment_id=NEW.experiment_id AND unixepoch(execution.updated_at)>unixepoch(NEW.facts_through_at)) AND NOT EXISTS(SELECT 1 FROM experiment_request_outcomes outcome WHERE outcome.tenant_id=NEW.tenant_id AND outcome.experiment_id=NEW.experiment_id AND unixepoch(outcome.facts_at)>unixepoch(NEW.facts_through_at)) AND NOT EXISTS(SELECT 1 FROM experiment_usage_settlements settlement WHERE settlement.tenant_id=NEW.tenant_id AND settlement.experiment_id=NEW.experiment_id AND unixepoch(settlement.updated_at)>unixepoch(NEW.facts_through_at)) AND NOT EXISTS(SELECT 1 FROM experiment_feedback_attributions attribution WHERE attribution.tenant_id=NEW.tenant_id AND attribution.experiment_id=NEW.experiment_id AND unixepoch(attribution.attributed_at)>unixepoch(NEW.facts_through_at)) AND (SELECT COUNT(*) FROM experiment_request_executions execution WHERE execution.tenant_id=NEW.tenant_id AND execution.experiment_id=NEW.experiment_id AND execution.status='terminal')=experiment.assigned_count AND (SELECT COUNT(*) FROM experiment_request_outcomes outcome WHERE outcome.tenant_id=NEW.tenant_id AND outcome.experiment_id=NEW.experiment_id)=experiment.assigned_count AND (SELECT COUNT(*) FROM experiment_usage_settlements settlement WHERE settlement.tenant_id=NEW.tenant_id AND settlement.experiment_id=NEW.experiment_id AND settlement.status<>'pending')=experiment.assigned_count AND NOT EXISTS(SELECT 1 FROM experiment_results current WHERE current.tenant_id=NEW.tenant_id AND current.experiment_id=NEW.experiment_id AND (current.facts_version<>NEW.facts_version OR current.facts_through_at<>NEW.facts_through_at OR current.created_at<>NEW.created_at)) ) OR EXISTS(SELECT 1 FROM experiment_results current WHERE current.experiment_result_id=NEW.experiment_result_id OR (current.tenant_id=NEW.tenant_id AND current.experiment_id=NEW.experiment_id AND current.variant=NEW.variant) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='experiment_result_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
