CREATE OR REPLACE FUNCTION "fn_trg_experiment_events_owner_insert_prd075"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS( SELECT 1 FROM model_experiments experiment WHERE experiment.tenant_id=NEW.tenant_id AND experiment.experiment_id=NEW.experiment_id AND experiment.status='collecting_feedback' AND experiment.feedback_fence_closed_at IS NOT NULL AND experiment.finalization_owner_id IS NOT NULL AND experiment.finalization_lease_token IS NOT NULL AND unixepoch(experiment.finalization_lease_expires_at)>unixepoch('now') AND EXISTS(SELECT 1 FROM experiment_scheduler_tenants scheduler WHERE scheduler.tenant_id=experiment.tenant_id AND scheduler.lease_owner_id=experiment.finalization_owner_id AND scheduler.lease_token IS NOT NULL AND unixepoch(scheduler.lease_expires_at)>unixepoch('now') AND unixepoch(scheduler.lease_expires_at) >=unixepoch(experiment.finalization_lease_expires_at)) AND NEW.actor_id=experiment.created_by AND NEW.object_id=experiment.experiment_id AND NEW.source_request_id=experiment.operation_request_id AND NEW.source_trace_id=experiment.operation_trace_id AND (SELECT COUNT(*) FROM experiment_results result WHERE result.tenant_id=experiment.tenant_id AND result.experiment_id=experiment.experiment_id)=2 AND json_valid(NEW.payload_json) AND (SELECT COUNT(*) FROM json_each(NEW.payload_json))=19 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.payload_json) field WHERE field.key NOT IN ( 'schema_version','experiment_id','project_id','environment_id','model_alias_id', 'model_a_id','model_b_id','status','completion_reason','assigned_count', 'model_a_assigned_count','model_b_assigned_count','gateway_success_count', 'gateway_failure_count','unresolved_count','cost_unknown_count','feedback_count', 'facts_version','facts_through_at')) AND (json_extract(NEW.payload_json,'$.schema_version'))::NUMERIC=1 AND json_extract(NEW.payload_json,'$.experiment_id')=experiment.experiment_id AND json_extract(NEW.payload_json,'$.project_id')=experiment.project_id AND json_extract(NEW.payload_json,'$.environment_id')=experiment.environment_id AND json_extract(NEW.payload_json,'$.model_alias_id')=experiment.model_alias_id AND json_extract(NEW.payload_json,'$.model_a_id')=experiment.model_a_id AND json_extract(NEW.payload_json,'$.model_b_id')=experiment.model_b_id AND json_extract(NEW.payload_json,'$.status')='completed' AND json_extract(NEW.payload_json,'$.completion_reason')=CASE WHEN experiment.assigned_count=experiment.target_sample_count THEN 'target_reached' ELSE 'sampling_deadline_reached' END AND (json_extract(NEW.payload_json,'$.assigned_count'))::NUMERIC=experiment.assigned_count AND (json_extract(NEW.payload_json,'$.model_a_assigned_count'))::NUMERIC=experiment.model_a_assigned_count AND (json_extract(NEW.payload_json,'$.model_b_assigned_count'))::NUMERIC=experiment.model_b_assigned_count AND (json_extract(NEW.payload_json,'$.gateway_success_count'))::NUMERIC=( SELECT SUM(gateway_success_count) FROM experiment_results result WHERE result.tenant_id=experiment.tenant_id AND result.experiment_id=experiment.experiment_id) AND (json_extract(NEW.payload_json,'$.gateway_failure_count'))::NUMERIC=( SELECT SUM(gateway_failure_count) FROM experiment_results result WHERE result.tenant_id=experiment.tenant_id AND result.experiment_id=experiment.experiment_id) AND (json_extract(NEW.payload_json,'$.unresolved_count'))::NUMERIC=( SELECT SUM(unresolved_count) FROM experiment_results result WHERE result.tenant_id=experiment.tenant_id AND result.experiment_id=experiment.experiment_id) AND (json_extract(NEW.payload_json,'$.cost_unknown_count'))::NUMERIC=( SELECT SUM(cost_unknown_count) FROM experiment_results result WHERE result.tenant_id=experiment.tenant_id AND result.experiment_id=experiment.experiment_id) AND (json_extract(NEW.payload_json,'$.feedback_count'))::NUMERIC=( SELECT SUM(feedback_count) FROM experiment_results result WHERE result.tenant_id=experiment.tenant_id AND result.experiment_id=experiment.experiment_id) AND (json_extract(NEW.payload_json,'$.facts_version'))::NUMERIC=experiment.facts_version AND json_extract(NEW.payload_json,'$.facts_through_at')=( SELECT MIN(facts_through_at) FROM experiment_results result WHERE result.tenant_id=experiment.tenant_id AND result.experiment_id=experiment.experiment_id) ) OR EXISTS(SELECT 1 FROM experiment_events current WHERE current.experiment_event_id=NEW.experiment_event_id OR (current.tenant_id=NEW.tenant_id AND current.experiment_id=NEW.experiment_id AND current.event_type=NEW.event_type) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='experiment_event_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
