LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS(SELECT 1 FROM experiment_events event WHERE event.tenant_id=NEW.tenant_id AND event.experiment_event_id=NEW.experiment_event_id AND event.experiment_id=NEW.experiment_id) OR NEW.experiment_event_outbox_id<>'exob_'||substr(NEW.experiment_event_id,6) OR NEW.dispatch_status<>'pending' OR NEW.dispatch_attempts<>0 OR NEW.lease_generation<>0 OR NEW.next_attempt_at<>NEW.created_at OR NEW.updated_at<>NEW.created_at OR EXISTS(SELECT 1 FROM experiment_event_outbox current WHERE current.experiment_event_outbox_id=NEW.experiment_event_outbox_id OR (current.tenant_id=NEW.tenant_id AND current.experiment_event_id=NEW.experiment_event_id) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
