CREATE OR REPLACE FUNCTION "fn_trg_experiment_outbox_update_prd075"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.experiment_event_outbox_id<>OLD.experiment_event_outbox_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.experiment_event_id<>OLD.experiment_event_id OR NEW.experiment_id<>OLD.experiment_id OR NEW.created_at<>OLD.created_at OR unixepoch(NEW.updated_at)<unixepoch(OLD.updated_at) OR NEW.dispatch_attempts<OLD.dispatch_attempts OR NEW.dispatch_attempts>OLD.dispatch_attempts+1 OR NEW.lease_generation<OLD.lease_generation OR NEW.lease_generation>OLD.lease_generation+1 OR (OLD.dispatch_status='pending' AND NEW.dispatch_status NOT IN ('pending','processing')) OR (OLD.dispatch_status='processing' AND NEW.dispatch_status NOT IN ('processing','pending','dispatched','failed')) OR OLD.dispatch_status IN ('dispatched','failed') OR (NEW.dispatch_status='processing' AND ( unixepoch(NEW.lease_expires_at)>unixepoch(NEW.updated_at)+90 OR (OLD.dispatch_status<>'processing' AND ( NEW.dispatch_attempts<>OLD.dispatch_attempts+1 OR NEW.lease_generation<>OLD.lease_generation+1)) OR (OLD.dispatch_status='processing' AND NOT ( (NEW.dispatch_attempts=OLD.dispatch_attempts AND NEW.lease_generation=OLD.lease_generation AND NEW.claim_token=OLD.claim_token AND NEW.lease_owner_id=OLD.lease_owner_id AND unixepoch(NEW.lease_expires_at)>=unixepoch(OLD.lease_expires_at)) OR (unixepoch(OLD.lease_expires_at)<=unixepoch(NEW.updated_at) AND NEW.dispatch_attempts=OLD.dispatch_attempts+1 AND NEW.lease_generation=OLD.lease_generation+1 AND NEW.claim_token<>OLD.claim_token) )) ))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='experiment_outbox_state_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
