LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.tenant_id<>OLD.tenant_id OR NEW.created_at<>OLD.created_at OR NOT ( (NEW.lease_generation=OLD.lease_generation AND NEW.lease_token IS NOT DISTINCT FROM OLD.lease_token AND NEW.lease_owner_id IS NOT DISTINCT FROM OLD.lease_owner_id AND NEW.lease_expires_at IS NOT DISTINCT FROM OLD.lease_expires_at) OR (NEW.lease_generation=OLD.lease_generation AND OLD.lease_token IS NOT NULL AND OLD.lease_owner_id IS NOT NULL AND OLD.lease_expires_at IS NOT NULL AND NEW.lease_token IS NULL AND NEW.lease_owner_id IS NULL AND NEW.lease_expires_at IS NULL) OR (NEW.lease_generation=OLD.lease_generation+1 AND (OLD.lease_token IS NULL OR unixepoch(OLD.lease_expires_at)<=unixepoch('now')) AND NEW.lease_token IS NOT NULL AND NEW.lease_owner_id IS NOT NULL AND unixepoch(NEW.lease_expires_at)>unixepoch('now') AND unixepoch(NEW.lease_expires_at)<=unixepoch('now')+300) )) THEN
