CREATE OR REPLACE FUNCTION "fn_trg_finops_ledger_owner_insert_prd051"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (( NEW.entry_type='usage_charge' AND NOT EXISTS ( SELECT 1 FROM usage_ledger usage JOIN request_logs request ON request.tenant_id=usage.tenant_id AND request.request_id=usage.request_id JOIN price_snapshots snapshot ON snapshot.tenant_id=usage.tenant_id AND snapshot.price_snapshot_id=NEW.price_snapshot_id AND snapshot.request_id=usage.request_id WHERE usage.tenant_id=NEW.tenant_id AND usage.usage_ledger_id=NEW.usage_ledger_id AND usage.request_id=NEW.source_request_id AND request.trace_id=NEW.source_trace_id AND NEW.operation_request_id=NEW.source_request_id AND NEW.operation_trace_id=NEW.source_trace_id AND snapshot.currency=NEW.currency AND snapshot.price_schema_version=NEW.price_schema_version AND snapshot.source=NEW.price_snapshot_source AND ( usage.price_snapshot_id=snapshot.price_snapshot_id OR ( snapshot.source IN ('finops_unpriced', 'finops_legacy_backfill') AND json_extract( snapshot.billing_dimensions, '$.finops_usage_ledger_id' )=usage.usage_ledger_id ) ) AND NEW.amount_micros=( SELECT CAST(parts.integer_text AS INTEGER) * 1000000 + CASE WHEN parts.fraction_text='' THEN 0 ELSE CAST(substr(parts.fraction_text || '000000', 1, 6) AS INTEGER) END FROM ( SELECT CASE WHEN instr(value.amount_text, '.')=0 THEN value.amount_text ELSE substr(value.amount_text, 1, instr(value.amount_text, '.')-1) END AS integer_text, CASE WHEN instr(value.amount_text, '.')=0 THEN '' ELSE substr(value.amount_text, instr(value.amount_text, '.')+1) END AS fraction_text FROM ( SELECT CASE WHEN json_type(usage.normalized_usage, '$.cost_amount')='text' THEN json_extract(usage.normalized_usage, '$.cost_amount') ELSE printf('%.6f', usage.cost_amount) END AS amount_text ) value ) parts ) AND NEW.input_tokens=usage.input_tokens AND NEW.output_tokens=usage.output_tokens AND NEW.total_tokens=usage.total_tokens AND NEW.cache_tokens=usage.cache_tokens AND NEW.model_id IS NOT DISTINCT FROM usage.model_id AND NEW.provider_id IS NOT DISTINCT FROM usage.provider_id AND NEW.virtual_key_id IS NOT DISTINCT FROM usage.virtual_key_id AND NEW.environment_id IS NOT DISTINCT FROM usage.environment_id AND NEW.project_id IS NOT DISTINCT FROM usage.project_id AND NEW.application_id IS NOT DISTINCT FROM usage.application_id AND NEW.estimated=usage.estimated AND NEW.price_evidence_status=CASE WHEN snapshot.source='finops_unpriced' THEN 'unpriced' WHEN snapshot.source='finops_legacy_backfill' THEN 'legacy_amount_only' WHEN snapshot.source='response_cache_reference' AND snapshot.price_schema_version='unpriced-v1' THEN 'unpriced' ELSE 'priced' END ) ) OR ( NEW.entry_type<>'usage_charge' AND NOT EXISTS ( SELECT 1 FROM finops_adjustments adjustment LEFT JOIN request_logs request ON request.tenant_id=adjustment.tenant_id AND request.request_id=adjustment.related_request_id LEFT JOIN finops_ledger_entries target ON target.tenant_id=adjustment.tenant_id AND target.finops_ledger_entry_id=adjustment.reversal_of_entry_id LEFT JOIN finops_ledger_entries related_usage ON related_usage.tenant_id=adjustment.tenant_id AND related_usage.entry_type='usage_charge' AND related_usage.source_request_id=adjustment.related_request_id WHERE adjustment.tenant_id=NEW.tenant_id AND adjustment.finops_adjustment_id=NEW.finops_adjustment_id AND adjustment.adjustment_type=NEW.entry_type AND adjustment.amount_micros=NEW.amount_micros AND adjustment.currency=NEW.currency AND adjustment.actor_user_id=NEW.actor_user_id AND adjustment.operation_request_id=NEW.operation_request_id AND adjustment.operation_trace_id=NEW.operation_trace_id AND adjustment.reversal_of_entry_id IS NOT DISTINCT FROM NEW.reversal_of_entry_id AND ( ( adjustment.adjustment_type='reversal' AND target.source_request_id IS NOT DISTINCT FROM NEW.source_request_id AND target.source_trace_id IS NOT DISTINCT FROM NEW.source_trace_id ) OR ( adjustment.adjustment_type<>'reversal' AND adjustment.related_request_id IS NOT DISTINCT FROM NEW.source_request_id AND request.trace_id IS NOT DISTINCT FROM NEW.source_trace_id ) ) AND NEW.posting_source='direct' AND ( (adjustment.adjustment_type='manual_debit' AND NEW.direction='debit') OR (adjustment.adjustment_type IN ( 'manual_credit', 'gift_credit', 'trial_credit' ) AND NEW.direction='credit') OR ( adjustment.adjustment_type='reversal' AND target.entry_type<>'reversal' AND NEW.direction=CASE target.direction WHEN 'debit' THEN 'credit' ELSE 'debit' END AND NEW.quota_type=target.quota_type AND NEW.price_evidence_status=target.price_evidence_status AND NEW.price_snapshot_source IS NOT DISTINCT FROM target.price_snapshot_source AND NEW.price_snapshot_id IS NOT DISTINCT FROM target.price_snapshot_id AND NEW.price_schema_version IS NOT DISTINCT FROM target.price_schema_version AND NEW.model_id IS NOT DISTINCT FROM target.model_id AND NEW.provider_id IS NOT DISTINCT FROM target.provider_id AND NEW.virtual_key_id IS NOT DISTINCT FROM target.virtual_key_id AND NEW.environment_id IS NOT DISTINCT FROM target.environment_id AND NEW.project_id IS NOT DISTINCT FROM target.project_id AND NEW.application_id IS NOT DISTINCT FROM target.application_id ) ) AND ( adjustment.adjustment_type='reversal' OR ( NEW.price_evidence_status='not_applicable' AND ( (adjustment.related_request_id IS NULL AND NEW.model_id IS NULL AND NEW.provider_id IS NULL AND NEW.virtual_key_id IS NULL AND NEW.environment_id IS NULL AND NEW.project_id IS NULL AND NEW.application_id IS NULL) OR ( adjustment.related_request_id IS NOT NULL AND NEW.model_id IS NOT DISTINCT FROM related_usage.model_id AND NEW.provider_id IS NOT DISTINCT FROM related_usage.provider_id AND NEW.virtual_key_id IS NOT DISTINCT FROM related_usage.virtual_key_id AND NEW.environment_id IS NOT DISTINCT FROM related_usage.environment_id AND NEW.project_id IS NOT DISTINCT FROM related_usage.project_id AND NEW.application_id IS NOT DISTINCT FROM related_usage.application_id ) ) ) ) ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='finops_ledger_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
