CREATE OR REPLACE FUNCTION "fn_trg_finops_experiment_settlement_prd075"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF NEW.entry_type='usage_charge' AND NEW.direction='debit' AND NEW.quota_type='paid' AND NEW.status='posted' AND NEW.posting_source IN ('direct','spool_replay') THEN
    UPDATE experiment_usage_settlements SET status='recorded',usage_ledger_id=NEW.usage_ledger_id, finops_ledger_entry_id=NEW.finops_ledger_entry_id, gross_cny_micros=NEW.normalized_cny_micros, normalization_status=CASE NEW.cny_normalization_status WHEN 'normalized' THEN 'normalized' ELSE 'unavailable' END, settlement_reason='usage_charge_recorded',settled_at=NEW.created_at, updated_at=NEW.created_at WHERE status='pending' AND tenant_id=NEW.tenant_id AND EXISTS( SELECT 1 FROM experiment_assignments assignment JOIN model_experiments experiment ON experiment.tenant_id=assignment.tenant_id AND experiment.experiment_id=assignment.experiment_id WHERE assignment.tenant_id=NEW.tenant_id AND assignment.assignment_id=experiment_usage_settlements.assignment_id AND assignment.request_id=NEW.source_request_id AND assignment.model_id=NEW.model_id AND assignment.provider_id=NEW.provider_id AND experiment.status<>'completed' );
  END IF;
  RETURN NEW;
END;
$trigger$;
