LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.key_state_id<>OLD.key_state_id OR NEW.key_schema_version<>OLD.key_schema_version OR NEW.active_hmac_key_version<OLD.active_hmac_key_version OR NEW.active_encryption_key_version<OLD.active_encryption_key_version OR NEW.generation<>OLD.generation+1 OR unixepoch(NEW.updated_at)<unixepoch(OLD.updated_at) OR ( NEW.active_hmac_key_version=OLD.active_hmac_key_version AND NEW.active_encryption_key_version=OLD.active_encryption_key_version AND NEW.hmac_secret_fingerprint=OLD.hmac_secret_fingerprint AND NEW.encryption_secret_fingerprint=OLD.encryption_secret_fingerprint )) THEN
