CREATE OR REPLACE FUNCTION "fn_trg_response_cache_policies_owner_insert_prd076"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.version<>1 OR NEW.invalidation_generation<>1 OR NOT EXISTS( SELECT 1 FROM model_aliases alias WHERE alias.tenant_id=NEW.tenant_id AND alias.model_alias_id=NEW.model_alias_id ) OR NOT EXISTS( SELECT 1 FROM users actor WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.created_by AND actor.status='active' ) OR NOT EXISTS( SELECT 1 FROM users actor WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.updated_by AND actor.status='active' ) OR NEW.created_by<>NEW.updated_by OR EXISTS( SELECT 1 FROM json_each(NEW.tags_json) tag WHERE tag.type<>'text' OR length(tag.value) NOT BETWEEN 1 AND 64 OR tag.value<>lower(tag.value) OR tag.value OPERATOR(public.@@) '*[^a-z0-9._-]*' ) OR (SELECT COUNT(*) FROM json_each(NEW.tags_json)) <>(SELECT COUNT(DISTINCT value) FROM json_each(NEW.tags_json)) OR EXISTS( SELECT 1 FROM json_each(NEW.tags_json) current_tag JOIN json_each(NEW.tags_json) next_tag ON (next_tag.key)::BIGINT=(current_tag.key)::BIGINT+1 WHERE current_tag.value>=next_tag.value ) OR EXISTS( SELECT 1 FROM response_cache_policies current WHERE current.cache_policy_id=NEW.cache_policy_id OR (current.tenant_id=NEW.tenant_id AND current.model_alias_id=NEW.model_alias_id) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='response_cache_policy_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
