LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.cache_policy_id<>OLD.cache_policy_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.model_alias_id<>OLD.model_alias_id OR NEW.created_by<>OLD.created_by OR NEW.created_at<>OLD.created_at OR NEW.version<>OLD.version+1 OR NEW.invalidation_generation<>OLD.invalidation_generation+1 OR unixepoch(NEW.updated_at)<unixepoch(OLD.updated_at) OR NOT EXISTS( SELECT 1 FROM users actor WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.updated_by AND actor.status='active' ) OR EXISTS( SELECT 1 FROM json_each(NEW.tags_json) tag WHERE tag.type<>'text' OR length(tag.value) NOT BETWEEN 1 AND 64 OR tag.value<>lower(tag.value) OR tag.value OPERATOR(public.@@) '*[^a-z0-9._-]*' ) OR (SELECT COUNT(*) FROM json_each(NEW.tags_json)) <>(SELECT COUNT(DISTINCT value) FROM json_each(NEW.tags_json)) OR EXISTS( SELECT 1 FROM json_each(NEW.tags_json) current_tag JOIN json_each(NEW.tags_json) next_tag ON (next_tag.key)::BIGINT=(current_tag.key)::BIGINT+1 WHERE current_tag.value>=next_tag.value ) OR ( NEW.status=OLD.status AND NEW.data_class IS NOT DISTINCT FROM OLD.data_class AND NEW.ttl_seconds=OLD.ttl_seconds AND NEW.charge_cache_hits=OLD.charge_cache_hits AND NEW.tags_json=OLD.tags_json AND NEW.single_data_class_confirmed=OLD.single_data_class_confirmed AND NEW.data_class_confirmed_by IS NOT DISTINCT FROM OLD.data_class_confirmed_by AND NEW.data_class_confirmed_version IS NOT DISTINCT FROM OLD.data_class_confirmed_version )) THEN
