CREATE OR REPLACE FUNCTION "fn_trg_response_cache_policy_events_owner_insert_prd076"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS( SELECT 1 FROM response_cache_policies policy JOIN users actor ON actor.tenant_id=policy.tenant_id AND actor.user_id=NEW.actor_user_id AND actor.status='active' WHERE policy.tenant_id=NEW.tenant_id AND policy.cache_policy_id=NEW.cache_policy_id AND policy.version=NEW.result_version AND ( (NEW.event_type='policy_created' AND policy.version=1 AND policy.created_by=NEW.actor_user_id) OR (NEW.event_type='policy_updated' AND policy.updated_by=NEW.actor_user_id) OR NEW.event_type='policy_noop' ) ) OR EXISTS( SELECT 1 FROM response_cache_policy_events current WHERE current.response_cache_policy_event_id =NEW.response_cache_policy_event_id OR (current.tenant_id=NEW.tenant_id AND current.actor_user_id=NEW.actor_user_id AND current.idempotency_hmac_version=NEW.idempotency_hmac_version AND current.idempotency_key_hmac=NEW.idempotency_key_hmac) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) ) OR EXISTS( SELECT 1 FROM json_each(NEW.response_json) field WHERE field.key NOT IN( 'tenant_id','cache_policy','idempotent_replay','request_id','trace_id' ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='response_cache_policy_event_owner_mismatch';
