CREATE OR REPLACE FUNCTION "fn_trg_response_cache_hits_owner_insert_prd076"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS( SELECT 1 FROM response_cache_entries entry WHERE entry.tenant_id=NEW.tenant_id AND entry.response_cache_entry_id=NEW.source_response_cache_entry_id AND entry.cache_policy_id=NEW.cache_policy_id AND entry.cache_policy_version=NEW.cache_policy_version AND entry.model_id=NEW.model_id AND entry.provider_id=NEW.provider_id AND entry.source_request_id=NEW.source_request_id AND entry.source_trace_id=NEW.source_trace_id AND entry.source_usage_ledger_id=NEW.source_usage_ledger_id AND entry.source_finops_ledger_entry_id=NEW.source_finops_ledger_entry_id AND entry.source_generation_cost_status=NEW.source_generation_cost_status AND entry.source_generation_cost_cny_micros IS NOT DISTINCT FROM NEW.source_generation_cost_cny_micros ) OR NOT EXISTS( SELECT 1 FROM request_logs request WHERE request.tenant_id=NEW.tenant_id AND request.request_id=NEW.request_id AND request.trace_id=NEW.trace_id AND request.status='success' AND request.virtual_key_id=NEW.virtual_key_id AND request.model_id=NEW.model_id AND request.provider_id=NEW.provider_id ) OR NOT EXISTS( SELECT 1 FROM price_snapshots source_price JOIN price_snapshots reference_price ON reference_price.tenant_id=source_price.tenant_id JOIN price_snapshots billed_price ON billed_price.tenant_id=source_price.tenant_id WHERE source_price.tenant_id=NEW.tenant_id AND source_price.price_snapshot_id=NEW.source_price_snapshot_id AND source_price.request_id=NEW.source_request_id AND reference_price.price_snapshot_id =NEW.current_reference_price_snapshot_id AND reference_price.request_id=NEW.request_id AND reference_price.source='response_cache_reference' AND reference_price.created_at=NEW.pricing_observed_at AND billed_price.price_snapshot_id=NEW.billed_price_snapshot_id AND billed_price.request_id=NEW.request_id AND billed_price.created_at=NEW.pricing_observed_at AND billed_price.source IN( 'response_cache_reference','response_cache_no_charge' ) ) OR NOT EXISTS( SELECT 1 FROM usage_ledger usage WHERE usage.tenant_id=NEW.tenant_id AND usage.usage_ledger_id=NEW.usage_ledger_id AND usage.request_id=NEW.request_id AND usage.usage_source='response_cache' AND usage.cache_tokens=0 AND usage.price_snapshot_id=NEW.billed_price_snapshot_id ) OR NOT EXISTS( SELECT 1 FROM finops_ledger_entries charge WHERE charge.tenant_id=NEW.tenant_id AND charge.finops_ledger_entry_id=NEW.finops_ledger_entry_id AND charge.usage_ledger_id=NEW.usage_ledger_id AND charge.source_request_id=NEW.request_id AND charge.source_trace_id=NEW.trace_id AND charge.entry_type='usage_charge' AND ( (NEW.billed_cost_status='known' AND charge.cny_normalization_status='normalized' AND charge.normalized_cny_micros=NEW.billed_cost_cny_micros) OR (NEW.billed_cost_status='unavailable' AND charge.cny_normalization_status='unavailable' AND charge.normalized_cny_micros IS NULL AND charge.price_evidence_status='unpriced') ) ) OR EXISTS( SELECT 1 FROM response_cache_hits current WHERE current.response_cache_hit_id=NEW.response_cache_hit_id OR (current.tenant_id=NEW.tenant_id AND current.request_id=NEW.request_id) OR (current.tenant_id=NEW.tenant_id AND current.usage_ledger_id=NEW.usage_ledger_id) OR (current.tenant_id=NEW.tenant_id AND current.finops_ledger_entry_id=NEW.finops_ledger_entry_id) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='response_cache_hit_owner_mismatch';
  END IF;
  RETURN NEW;
END;
