CREATE OR REPLACE FUNCTION "fn_trg_response_cache_events_owner_insert_prd076"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (( NEW.event_type='cache.hit' AND ( NEW.actor_user_id IS NOT NULL OR NOT EXISTS( SELECT 1 FROM response_cache_hits hit WHERE hit.tenant_id=NEW.tenant_id AND hit.response_cache_hit_id=NEW.object_id AND hit.trace_id=NEW.trace_id AND hit.created_at=NEW.occurred_at AND (SELECT COUNT(*) FROM json_each(NEW.payload_json))=13 AND NOT EXISTS( SELECT 1 FROM json_each(NEW.payload_json) field WHERE field.key NOT IN( 'schema_version','cache_hit_id','cache_policy_id', 'cache_policy_version','charge_cache_hits', 'source_generation_cost_status','source_generation_cost_cny', 'current_reference_cost_status','current_reference_cost_cny', 'saved_cost_status','saved_cost_cny','billed_cost_status', 'billed_cost_cny' ) ) AND (json_extract(NEW.payload_json,'$.schema_version'))::NUMERIC=1 AND json_extract(NEW.payload_json,'$.cache_hit_id') =hit.response_cache_hit_id AND json_extract(NEW.payload_json,'$.cache_policy_id') =hit.cache_policy_id AND (json_extract(NEW.payload_json,'$.cache_policy_version'))::NUMERIC =hit.cache_policy_version AND (json_extract(NEW.payload_json,'$.charge_cache_hits'))::NUMERIC =hit.charge_cache_hits AND json_type(NEW.payload_json,'$.schema_version')='integer' AND json_type(NEW.payload_json,'$.cache_hit_id')='text' AND json_type(NEW.payload_json,'$.cache_policy_id')='text' AND json_type(NEW.payload_json,'$.cache_policy_version')='integer' AND json_type(NEW.payload_json,'$.charge_cache_hits') IN('true','false') AND json_type(NEW.payload_json,'$.source_generation_cost_status')='text' AND json_extract(NEW.payload_json,'$.source_generation_cost_status') =hit.source_generation_cost_status AND ( (hit.source_generation_cost_status='known' AND json_type(NEW.payload_json,'$.source_generation_cost_cny')='text' AND json_extract(NEW.payload_json,'$.source_generation_cost_cny') =printf('%d.%06d',hit.source_generation_cost_cny_micros/1000000, hit.source_generation_cost_cny_micros%1000000)) OR (hit.source_generation_cost_status='unavailable' AND json_type(NEW.payload_json,'$.source_generation_cost_cny')='null') ) AND json_type(NEW.payload_json,'$.current_reference_cost_status')='text' AND json_extract(NEW.payload_json,'$.current_reference_cost_status') =hit.current_reference_cost_status AND ( (hit.current_reference_cost_status='known' AND json_type(NEW.payload_json,'$.current_reference_cost_cny')='text' AND json_extract(NEW.payload_json,'$.current_reference_cost_cny') =printf('%d.%06d',hit.current_reference_cost_cny_micros/1000000, hit.current_reference_cost_cny_micros%1000000)) OR (hit.current_reference_cost_status='unavailable' AND json_type(NEW.payload_json,'$.current_reference_cost_cny')='null') ) AND json_type(NEW.payload_json,'$.saved_cost_status')='text' AND json_extract(NEW.payload_json,'$.saved_cost_status')=hit.saved_cost_status AND ( (hit.saved_cost_status='known' AND json_type(NEW.payload_json,'$.saved_cost_cny')='text' AND json_extract(NEW.payload_json,'$.saved_cost_cny') =printf('%d.%06d',hit.saved_cost_cny_micros/1000000, hit.saved_cost_cny_micros%1000000)) OR (hit.saved_cost_status='unavailable' AND json_type(NEW.payload_json,'$.saved_cost_cny')='null') ) AND json_type(NEW.payload_json,'$.billed_cost_status')='text' AND json_extract(NEW.payload_json,'$.billed_cost_status')=hit.billed_cost_status AND ( (hit.billed_cost_status='known' AND json_type(NEW.payload_json,'$.billed_cost_cny')='text' AND json_extract(NEW.payload_json,'$.billed_cost_cny') =printf('%d.%06d',hit.billed_cost_cny_micros/1000000, hit.billed_cost_cny_micros%1000000)) OR (hit.billed_cost_status='unavailable' AND json_type(NEW.payload_json,'$.billed_cost_cny')='null') ) ) ) ) OR ( NEW.event_type='cache.invalidated' AND NOT EXISTS( SELECT 1 FROM response_cache_invalidations invalidation WHERE invalidation.tenant_id=NEW.tenant_id AND invalidation.cache_invalidation_id=NEW.object_id AND invalidation.actor_user_id IS NOT DISTINCT FROM NEW.actor_user_id AND invalidation.operation_trace_id=NEW.trace_id AND invalidation.created_at=NEW.occurred_at AND (SELECT COUNT(*) FROM json_each(NEW.payload_json))=9 AND NOT EXISTS( SELECT 1 FROM json_each(NEW.payload_json) field WHERE field.key NOT IN( 'schema_version','cache_invalidation_id','scope','match_mode', 'tag_count','matched_entry_count','deleted_entry_count', 'fenced_fill_count','reason_code' ) ) AND (json_extract(NEW.payload_json,'$.schema_version'))::NUMERIC=1 AND json_extract(NEW.payload_json,'$.cache_invalidation_id') =invalidation.cache_invalidation_id AND json_extract(NEW.payload_json,'$.scope')=invalidation.scope AND json_extract(NEW.payload_json,'$.match_mode')=invalidation.match_mode AND (json_extract(NEW.payload_json,'$.tag_count'))::NUMERIC=invalidation.tag_count AND (json_extract(NEW.payload_json,'$.matched_entry_count'))::NUMERIC =invalidation.matched_entry_count AND (json_extract(NEW.payload_json,'$.deleted_entry_count'))::NUMERIC =invalidation.deleted_entry_count AND (json_extract(NEW.payload_json,'$.fenced_fill_count'))::NUMERIC =invalidation.fenced_fill_count AND json_extract(NEW.payload_json,'$.reason_code') =invalidation.reason_code ) ) OR EXISTS( SELECT 1 FROM response_cache_events current WHERE current.response_cache_event_id=NEW.response_cache_event_id OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='response_cache_event_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
