  IF (NEW.status<>'pending' OR NEW.attempt_count<>0 OR NEW.generation<>1 OR NOT EXISTS( SELECT 1 FROM response_cache_events event WHERE event.tenant_id=NEW.tenant_id AND event.response_cache_event_id=NEW.response_cache_event_id AND event.occurred_at=NEW.created_at )) THEN
