CREATE OR REPLACE FUNCTION "fn_trg_response_cache_event_outbox_update_prd076"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.tenant_id<>OLD.tenant_id OR NEW.response_cache_event_id<>OLD.response_cache_event_id OR NEW.created_at<>OLD.created_at OR NEW.generation<>OLD.generation+1 OR unixepoch(NEW.updated_at)<unixepoch(OLD.updated_at) OR NOT ( (OLD.status='pending' AND NEW.status='leased' AND NEW.attempt_count=OLD.attempt_count) OR (OLD.status='leased' AND NEW.status='leased' AND NEW.attempt_count=OLD.attempt_count AND NEW.lease_token<>OLD.lease_token) OR (OLD.status='leased' AND NEW.status='dispatched' AND NEW.attempt_count=OLD.attempt_count+1) OR (OLD.status='leased' AND NEW.status='pending' AND NEW.attempt_count=OLD.attempt_count+1 AND NEW.attempt_count<10) OR (OLD.status='leased' AND NEW.status='dead_letter' AND NEW.attempt_count=10) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='response_cache_event_outbox_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
