CREATE OR REPLACE FUNCTION "fn_trg_usage_ledger_finops_amount_insert_prd051"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF NOT json_valid(NEW.normalized_usage) OR json_type(NEW.normalized_usage)<>'object' THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='usage_finops_amount_invalid';
  END IF;
  IF NEW.usage_source='response_cache' AND ( json_type(NEW.normalized_usage,'$.finops_ledger_entry_id')<>'text' OR length(json_extract(NEW.normalized_usage,'$.finops_ledger_entry_id'))<>36 OR substr(json_extract(NEW.normalized_usage,'$.finops_ledger_entry_id'),1,4)<>'fle_' OR substr(json_extract(NEW.normalized_usage,'$.finops_ledger_entry_id'),5) OPERATOR(public.@@) '*[^0-9a-f]*' OR json_type(NEW.normalized_usage,'$.finops_event_id')<>'text' OR length(json_extract(NEW.normalized_usage,'$.finops_event_id'))<>38 OR substr(json_extract(NEW.normalized_usage,'$.finops_event_id'),1,6)<>'flevt_' OR substr(json_extract(NEW.normalized_usage,'$.finops_event_id'),7) OPERATOR(public.@@) '*[^0-9a-f]*' ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='usage_finops_owner_mismatch';
  END IF;
  IF NEW.usage_source<>'response_cache' AND ( json_type(NEW.normalized_usage,'$.finops_ledger_entry_id') IS NOT NULL OR json_type(NEW.normalized_usage,'$.finops_event_id') IS NOT NULL ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='usage_finops_owner_mismatch';
  END IF;
  IF json_type(NEW.normalized_usage, '$.cost_amount') NOT IN ('text') AND json_type(NEW.normalized_usage, '$.cost_amount') IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='usage_finops_amount_invalid';
  END IF;
  IF EXISTS ( SELECT 1 FROM ( SELECT value.amount_text, CASE WHEN instr(value.amount_text, '.')=0 THEN value.amount_text ELSE substr(value.amount_text, 1, instr(value.amount_text, '.')-1) END AS integer_text, CASE WHEN instr(value.amount_text, '.')=0 THEN '' ELSE substr(value.amount_text, instr(value.amount_text, '.')+1) END AS fraction_text FROM ( SELECT CASE WHEN json_type(NEW.normalized_usage, '$.cost_amount')='text' THEN json_extract(NEW.normalized_usage, '$.cost_amount') ELSE printf('%.6f', NEW.cost_amount) END AS amount_text ) value ) parts WHERE parts.amount_text='' OR parts.amount_text OPERATOR(public.@@) '*[^0-9.]*' OR parts.integer_text='' OR parts.integer_text OPERATOR(public.@@) '*[^0-9]*' OR length(parts.integer_text) NOT BETWEEN 1 AND 10 OR (length(parts.integer_text)>1 AND substr(parts.integer_text, 1, 1)='0') OR ( instr(parts.amount_text, '.')>0 AND ( parts.fraction_text='' OR parts.fraction_text OPERATOR(public.@@) '*[^0-9]*' OR length(parts.fraction_text) NOT BETWEEN 1 AND 6 ) ) OR instr(substr(parts.amount_text, instr(parts.amount_text, '.')+1), '.')>0 OR CAST(parts.integer_text AS INTEGER) * 1000000 + CASE WHEN parts.fraction_text='' THEN 0 ELSE CAST(substr(parts.fraction_text || '000000', 1, 6) AS INTEGER) END > 1000000000000000 ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='usage_finops_amount_invalid';
  END IF;
  IF json_type(NEW.normalized_usage, '$.cost_amount')='text' AND printf('%.6f', NEW.cost_amount) <> ( SELECT parts.integer_text || '.' || substr(parts.fraction_text || '000000', 1, 6) FROM ( SELECT CASE WHEN instr(value.amount_text, '.')=0 THEN value.amount_text ELSE substr(value.amount_text, 1, instr(value.amount_text, '.')-1) END AS integer_text, CASE WHEN instr(value.amount_text, '.')=0 THEN '' ELSE substr(value.amount_text, instr(value.amount_text, '.')+1) END AS fraction_text FROM ( SELECT json_extract(NEW.normalized_usage, '$.cost_amount') AS amount_text ) value ) parts ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='usage_finops_amount_mismatch';
  END IF;
  IF NEW.currency NOT IN ('CNY', 'USD') THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='usage_finops_currency_invalid';
  END IF;
  IF json_type(NEW.normalized_usage, '$.currency') IS NOT NULL AND ( json_type(NEW.normalized_usage, '$.currency')<>'text' OR json_extract(NEW.normalized_usage, '$.currency')<>NEW.currency ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='usage_finops_currency_invalid';
  END IF;
  IF NEW.currency='CNY' AND json_type(NEW.normalized_usage, '$.cost_amount')='text' AND ( json_type(NEW.normalized_usage, '$.cost_cny')<>'text' OR json_extract(NEW.normalized_usage, '$.cost_cny') <>json_extract(NEW.normalized_usage, '$.cost_amount') ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='usage_finops_cny_mismatch';
  END IF;
  IF NEW.currency='USD' AND json_type(NEW.normalized_usage, '$.cost_cny') NOT IN ('null') AND json_type(NEW.normalized_usage, '$.cost_cny') IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='usage_finops_cny_unavailable';
  END IF;
  IF json_type(NEW.normalized_usage, '$.posting_source') IS NOT NULL AND ( json_type(NEW.normalized_usage, '$.posting_source')<>'text' OR json_extract(NEW.normalized_usage, '$.posting_source') NOT IN ('direct', 'spool_replay') ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='usage_finops_posting_source_invalid';
  END IF;
  IF json_type(NEW.normalized_usage, '$.price_snapshot_id')='text' AND json_extract(NEW.normalized_usage, '$.price_snapshot_id') IS DISTINCT FROM NEW.price_snapshot_id THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='usage_finops_snapshot_mismatch';
  END IF;
  IF json_type(NEW.normalized_usage, '$.price_schema_version')='text' AND json_extract(NEW.normalized_usage, '$.price_schema_version') IS DISTINCT FROM NEW.price_schema_version THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='usage_finops_snapshot_mismatch';
  END IF;
  IF json_type(NEW.normalized_usage, '$.cost_amount')='text' AND ( SELECT CAST(parts.integer_text AS INTEGER) * 1000000 + CASE WHEN parts.fraction_text='' THEN 0 ELSE CAST(substr(parts.fraction_text || '000000', 1, 6) AS INTEGER) END FROM ( SELECT CASE WHEN instr(value.amount_text, '.')=0 THEN value.amount_text ELSE substr(value.amount_text, 1, instr(value.amount_text, '.')-1) END AS integer_text, CASE WHEN instr(value.amount_text, '.')=0 THEN '' ELSE substr(value.amount_text, instr(value.amount_text, '.')+1) END AS fraction_text FROM ( SELECT json_extract(NEW.normalized_usage, '$.cost_amount') AS amount_text ) value ) parts )>0 AND NOT EXISTS ( SELECT 1 FROM price_snapshots snapshot WHERE snapshot.price_snapshot_id=NEW.price_snapshot_id AND snapshot.tenant_id=NEW.tenant_id AND snapshot.request_id=NEW.request_id AND snapshot.currency=NEW.currency AND NULLIF(trim(snapshot.price_schema_version), '') IS NOT NULL AND snapshot.price_schema_version=NEW.price_schema_version ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='usage_finops_price_evidence_missing';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_usage_ledger_finops_amount_insert_prd051" BEFORE INSERT ON "usage_ledger" FOR EACH ROW EXECUTE FUNCTION "fn_trg_usage_ledger_finops_amount_insert_prd051"();
