CREATE OR REPLACE FUNCTION "fn_trg_usage_ledger_finops_owner_insert_prd051"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM request_logs request WHERE request.tenant_id=NEW.tenant_id AND request.request_id=NEW.request_id ) OR ( NEW.price_snapshot_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM price_snapshots snapshot WHERE snapshot.price_snapshot_id=NEW.price_snapshot_id AND snapshot.tenant_id=NEW.tenant_id AND snapshot.request_id=NEW.request_id AND snapshot.currency=NEW.currency ) ) OR ( NEW.model_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM models model WHERE model.model_id=NEW.model_id AND model.tenant_id=NEW.tenant_id ) ) OR ( NEW.provider_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM providers provider WHERE provider.provider_id=NEW.provider_id AND provider.tenant_id=NEW.tenant_id ) ) OR ( NEW.virtual_key_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM virtual_keys key WHERE key.virtual_key_id=NEW.virtual_key_id AND key.tenant_id=NEW.tenant_id ) ) OR ( NEW.environment_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM environments environment WHERE environment.environment_id=NEW.environment_id AND environment.tenant_id=NEW.tenant_id ) ) OR ( NEW.project_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM projects project WHERE project.project_id=NEW.project_id AND project.tenant_id=NEW.tenant_id ) ) OR ( NEW.application_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM applications application WHERE application.application_id=NEW.application_id AND application.tenant_id=NEW.tenant_id AND (NEW.project_id IS NULL OR application.project_id=NEW.project_id) ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='usage_finops_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_usage_ledger_finops_owner_insert_prd051" BEFORE INSERT ON "usage_ledger" FOR EACH ROW EXECUTE FUNCTION "fn_trg_usage_ledger_finops_owner_insert_prd051"();
CREATE OR REPLACE FUNCTION "fn_trg_usage_ledger_finops_projection_insert_prd051"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  INSERT INTO price_snapshots( price_snapshot_id, tenant_id, request_id, model_id, provider_id, provider_code, currency, input_price_per_1k, output_price_per_1k, price_schema_version, billing_dimensions, provider_raw_mapping, source, status, created_at, updated_at, price_plan_id, effective_from ) SELECT 'prs_' || lower(hex(randomblob(16))), NEW.tenant_id, NEW.request_id, NEW.model_id, NEW.provider_id, NEW.provider_code, NEW.currency, CASE WHEN json_type(NEW.normalized_usage, '$.cost_amount') IS NULL THEN COALESCE(( SELECT snapshot.input_price_per_1k FROM price_snapshots snapshot WHERE snapshot.price_snapshot_id=NEW.price_snapshot_id ), 0) ELSE 0 END, CASE WHEN json_type(NEW.normalized_usage, '$.cost_amount') IS NULL THEN COALESCE(( SELECT snapshot.output_price_per_1k FROM price_snapshots snapshot WHERE snapshot.price_snapshot_id=NEW.price_snapshot_id ), 0) ELSE 0 END, CASE WHEN json_type(NEW.normalized_usage, '$.cost_amount') IS NULL THEN 'legacy-unversioned-v1' ELSE 'unpriced-v1' END, (jsonb_build_object( 'finops_usage_ledger_id', NEW.usage_ledger_id, 'price_evidence_status', CASE WHEN json_type(NEW.normalized_usage, '$.cost_amount') IS NULL THEN 'legacy_amount_only' ELSE 'unpriced' END )::TEXT), '{}', CASE WHEN json_type(NEW.normalized_usage, '$.cost_amount') IS NULL THEN 'finops_legacy_backfill' ELSE 'finops_unpriced' END, 'active', NEW.created_at, NEW.created_at, NULL, NEW.created_at WHERE NOT EXISTS ( SELECT 1 FROM price_snapshots snapshot WHERE snapshot.price_snapshot_id=NEW.price_snapshot_id AND snapshot.tenant_id=NEW.tenant_id AND snapshot.request_id=NEW.request_id AND snapshot.currency=NEW.currency AND NULLIF(trim(snapshot.price_schema_version), '') IS NOT NULL AND snapshot.price_schema_version=NEW.price_schema_version );
  INSERT INTO finops_ledger_entries( finops_ledger_entry_id, event_id, tenant_id, entry_type, direction, amount_micros, currency, normalized_cny_micros, cny_normalization_status, price_evidence_status, price_snapshot_source, posting_source, quota_type, usage_ledger_id, finops_adjustment_id, source_request_id, source_trace_id, operation_request_id, operation_trace_id, price_snapshot_id, price_schema_version, reversal_of_entry_id, actor_user_id, input_tokens, output_tokens, total_tokens, cache_tokens, model_id, provider_id, virtual_key_id, environment_id, project_id, application_id, estimated, status, created_at, updated_at ) SELECT CASE WHEN NEW.usage_source='response_cache' THEN json_extract(NEW.normalized_usage,'$.finops_ledger_entry_id') ELSE 'fle_' || lower(hex(randomblob(16))) END, CASE WHEN NEW.usage_source='response_cache' THEN json_extract(NEW.normalized_usage,'$.finops_event_id') ELSE 'flevt_' || lower(hex(randomblob(16))) END, NEW.tenant_id, 'usage_charge', 'debit', amount.amount_micros, NEW.currency, CASE WHEN NEW.currency='CNY' AND NOT ( snapshot.source='response_cache_reference' AND snapshot.price_schema_version='unpriced-v1' ) THEN amount.amount_micros ELSE NULL END, CASE WHEN NEW.currency='CNY' AND NOT ( snapshot.source='response_cache_reference' AND snapshot.price_schema_version='unpriced-v1' ) THEN 'normalized' ELSE 'unavailable' END, CASE WHEN snapshot.source='finops_unpriced' THEN 'unpriced' WHEN snapshot.source='finops_legacy_backfill' THEN 'legacy_amount_only' WHEN snapshot.source='response_cache_reference' AND snapshot.price_schema_version='unpriced-v1' THEN 'unpriced' ELSE 'priced' END, snapshot.source, CASE WHEN json_extract(NEW.normalized_usage, '$.posting_source')='spool_replay' THEN 'spool_replay' ELSE 'direct' END, 'paid', NEW.usage_ledger_id, NULL, NEW.request_id, request.trace_id, NEW.request_id, request.trace_id, snapshot.price_snapshot_id, snapshot.price_schema_version, NULL, NULL, NEW.input_tokens, NEW.output_tokens, NEW.total_tokens, NEW.cache_tokens, NEW.model_id, NEW.provider_id, NEW.virtual_key_id, NEW.environment_id, NEW.project_id, NEW.application_id, NEW.estimated, 'posted', NEW.created_at, NEW.created_at FROM ( SELECT CAST(parts.integer_text AS INTEGER) * 1000000 + CASE WHEN parts.fraction_text='' THEN 0 ELSE CAST(substr(parts.fraction_text || '000000', 1, 6) AS INTEGER) END AS amount_micros FROM ( SELECT CASE WHEN instr(value.amount_text, '.')=0 THEN value.amount_text ELSE substr(value.amount_text, 1, instr(value.amount_text, '.')-1) END AS integer_text, CASE WHEN instr(value.amount_text, '.')=0 THEN '' ELSE substr(value.amount_text, instr(value.amount_text, '.')+1) END AS fraction_text FROM ( SELECT CASE WHEN json_type(NEW.normalized_usage, '$.cost_amount')='text' THEN json_extract(NEW.normalized_usage, '$.cost_amount') ELSE printf('%.6f', NEW.cost_amount) END AS amount_text ) value ) parts ) amount JOIN request_logs request ON request.tenant_id=NEW.tenant_id AND request.request_id=NEW.request_id JOIN price_snapshots snapshot ON snapshot.tenant_id=NEW.tenant_id AND snapshot.price_snapshot_id=COALESCE( ( SELECT trusted.price_snapshot_id FROM price_snapshots trusted WHERE trusted.price_snapshot_id=NEW.price_snapshot_id AND trusted.tenant_id=NEW.tenant_id AND trusted.request_id=NEW.request_id AND trusted.currency=NEW.currency AND NULLIF(trim(trusted.price_schema_version), '') IS NOT NULL AND trusted.price_schema_version=NEW.price_schema_version ), ( SELECT synthetic.price_snapshot_id FROM price_snapshots synthetic WHERE synthetic.tenant_id=NEW.tenant_id AND synthetic.source IN ('finops_unpriced', 'finops_legacy_backfill') AND json_extract( synthetic.billing_dimensions, '$.finops_usage_ledger_id' )=NEW.usage_ledger_id ) );
  RETURN NEW;
END;
$trigger$;
