CREATE OR REPLACE FUNCTION "fn_trg_output_safety_scans_transition_prd071"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT ( (NEW.ctid IS NOT DISTINCT FROM OLD.ctid AND NEW.output_safety_scan_id IS NOT DISTINCT FROM OLD.output_safety_scan_id AND NEW.tenant_id IS NOT DISTINCT FROM OLD.tenant_id AND NEW.request_id IS NOT DISTINCT FROM OLD.request_id AND NEW.trace_id IS NOT DISTINCT FROM OLD.trace_id AND NEW.stream_session_id IS NOT DISTINCT FROM OLD.stream_session_id AND NEW.scan_mode IS NOT DISTINCT FROM OLD.scan_mode AND NEW.scan_status IS NOT DISTINCT FROM OLD.scan_status AND NEW.decision IS NOT DISTINCT FROM OLD.decision AND NEW.action IS NOT DISTINCT FROM OLD.action AND NEW.dlp_rule_id IS NOT DISTINCT FROM OLD.dlp_rule_id AND NEW.rule_type IS NOT DISTINCT FROM OLD.rule_type AND NEW.match_count IS NOT DISTINCT FROM OLD.match_count AND NEW.ruleset_fingerprint IS NOT DISTINCT FROM OLD.ruleset_fingerprint AND NEW.detector_version IS NOT DISTINCT FROM OLD.detector_version AND NEW.interval_tokens IS NOT DISTINCT FROM OLD.interval_tokens AND NEW.window_tokens IS NOT DISTINCT FROM OLD.window_tokens AND NEW.checkpoint_count IS NOT DISTINCT FROM OLD.checkpoint_count AND NEW.observed_output_token_count IS NOT DISTINCT FROM OLD.observed_output_token_count AND NEW.scanned_token_count IS NOT DISTINCT FROM OLD.scanned_token_count AND NEW.emitted_token_count IS NOT DISTINCT FROM OLD.emitted_token_count AND NEW.emitted_sse_event_count IS NOT DISTINCT FROM OLD.emitted_sse_event_count AND NEW.emitted_bytes IS NOT DISTINCT FROM OLD.emitted_bytes AND NEW.exposure_state IS NOT DISTINCT FROM OLD.exposure_state AND NEW.billing_disposition IS NOT DISTINCT FROM OLD.billing_disposition AND NEW.failure_reason_code IS NOT DISTINCT FROM OLD.failure_reason_code AND NEW.started_at IS NOT DISTINCT FROM OLD.started_at AND NEW.completed_at IS NOT DISTINCT FROM OLD.completed_at) OR (OLD.scan_status='pending' AND NEW.scan_status IN ( 'not_configured','completed','unavailable','not_applicable' )) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='output_safety_scan_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_output_safety_scans_transition_prd071" BEFORE UPDATE ON "output_safety_scans" FOR EACH ROW EXECUTE FUNCTION "fn_trg_output_safety_scans_transition_prd071"();
