LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS( SELECT 1 FROM assistant_queries query WHERE query.tenant_id=NEW.tenant_id AND query.assistant_query_id=NEW.assistant_query_id AND query.actor_user_id=NEW.actor_user_id AND query.actor_session_id=NEW.actor_session_id AND query.outcome=NEW.outcome AND query.claim_count=NEW.claim_count AND query.source_count=NEW.source_count AND query.redaction_count=NEW.redaction_count AND query.query_duration_ms=NEW.query_duration_ms AND query.operation_request_id=NEW.operation_request_id AND query.operation_trace_id=NEW.operation_trace_id AND query.execution_mode=NEW.execution_mode AND query.model_call_count=NEW.model_call_count AND query.model_input_tokens=NEW.model_input_tokens AND query.model_output_tokens=NEW.model_output_tokens AND query.model_cost_cny_micros=NEW.model_cost_cny_micros AND query.model_cost_status=NEW.model_cost_status AND query.created_at=NEW.created_at AND NEW.required_permissions_json=CASE query.query_type WHEN 'usage_statistics' THEN '["admin_assistant.query","billing.usage.read","dashboard.read"]' WHEN 'error_explanation' THEN '["admin_assistant.query","request_log.read"]' WHEN 'cost_advice' THEN '["admin_assistant.query","billing.anomaly.read","billing.budget.read",' || '"billing.finops.read","billing.usage.read","dashboard.read","model_price.read"]' WHEN 'policy_explanation' THEN CASE WHEN query.target_request_id IS NULL THEN '["admin_assistant.query","policy.read"]' ELSE '["admin_assistant.query","policy.read","request_explanation.read"]' END WHEN 'unknown' THEN '["admin_assistant.query"]' END AND ( (query.outcome<>'answered' AND NEW.source_types_json='[]') OR ( query.outcome='answered' AND json_array_length(NEW.source_types_json)=NEW.source_count AND NOT EXISTS( SELECT 1 FROM json_each(NEW.source_types_json) source WHERE source.type<>'text' OR source.value NOT IN( 'overview','request_logs','request_explanations','usage', 'finops_ledger','budgets','cost_anomalies','model_prices', 'policies','policy_snapshots' ) OR ( query.query_type='usage_statistics' AND source.value NOT IN('overview','usage') ) OR ( query.query_type='error_explanation' AND source.value<>'request_logs' ) OR ( query.query_type='cost_advice' AND source.value NOT IN( 'overview','usage','finops_ledger','budgets', 'cost_anomalies','model_prices' ) ) OR ( query.query_type='policy_explanation' AND source.value NOT IN( 'policies','policy_snapshots','request_explanations' ) ) ) ) ) ) OR EXISTS( SELECT 1 FROM json_each(NEW.required_permissions_json) left_value JOIN json_each(NEW.required_permissions_json) right_value ON right_value.key>left_value.key AND right_value.value<=left_value.value ) OR EXISTS( SELECT 1 FROM json_each(NEW.source_types_json) left_value JOIN json_each(NEW.source_types_json) right_value ON right_value.key>left_value.key AND right_value.value<=left_value.value ) OR EXISTS( SELECT 1 FROM assistant_audits current WHERE current.assistant_audit_id=NEW.assistant_audit_id OR current.assistant_event_id=NEW.assistant_event_id OR current.assistant_query_id=NEW.assistant_query_id OR current.audit_log_id=NEW.audit_log_id OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='assistant_audit_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
