CREATE OR REPLACE FUNCTION "fn_trg_approval_events_owner_insert_prd078"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS(SELECT 1 FROM approval_tasks task WHERE task.tenant_id=NEW.tenant_id AND task.approval_task_id=NEW.approval_task_id AND (json_extract(NEW.payload_json,'$.schema_version'))::NUMERIC=1 AND json_extract(NEW.payload_json,'$.approval_id')=task.approval_task_id AND json_extract(NEW.payload_json,'$.status')=task.status AND json_extract(NEW.payload_json,'$.target_type')=task.target_type AND json_extract(NEW.payload_json,'$.target_action')=task.target_action AND ((NEW.event_type='approval.created' AND (SELECT COUNT(*) FROM json_each(NEW.payload_json))=9 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.payload_json) field WHERE field.key NOT IN( 'schema_version','approval_id','status','target_type','target_action','risk_level', 'requires_step_up','expires_at','entry')) AND task.status='pending' AND NEW.actor_type=task.created_by_type AND NEW.actor_id=task.created_by_id AND NEW.source_request_id=task.source_request_id AND NEW.source_trace_id=task.source_trace_id AND NEW.occurred_at=task.created_at AND json_extract(NEW.payload_json,'$.risk_level')=task.risk_level AND (json_extract(NEW.payload_json,'$.requires_step_up'))::NUMERIC=CASE task.risk_level WHEN 'high' THEN 1 ELSE 0 END AND json_extract(NEW.payload_json,'$.expires_at')=task.expires_at AND json_extract(NEW.payload_json,'$.entry')='approval-card') OR (NEW.event_type='approval.timeout' AND (SELECT COUNT(*) FROM json_each(NEW.payload_json))=7 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.payload_json) field WHERE field.key NOT IN( 'schema_version','approval_id','status','target_type','target_action', 'resolution_reason','decided_at')) AND task.status='rejected' AND task.resolution_reason='timeout' AND NEW.actor_type='system' AND NEW.actor_id='approval-timeout-scheduler' AND NEW.source_request_id=task.decision_request_id AND NEW.source_trace_id=task.decision_trace_id AND NEW.occurred_at=task.decided_at AND json_extract(NEW.payload_json,'$.resolution_reason')='timeout' AND json_extract(NEW.payload_json,'$.decided_at')=task.decided_at))) OR EXISTS(SELECT 1 FROM approval_events current WHERE current.approval_event_id=NEW.approval_event_id OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='approval_event_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
