LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.status<>'pending' OR NEW.attempt_count<>0 OR NEW.lease_generation<>0 OR NEW.lease_owner_id IS NOT NULL OR NEW.lease_token IS NOT NULL OR NEW.lease_expires_at IS NOT NULL OR NEW.last_error_code IS NOT NULL OR NEW.delivered_at IS NOT NULL OR NEW.created_at<>NEW.updated_at OR NEW.next_attempt_at<>NEW.created_at OR NEW.subscription_snapshot_json IS NULL OR NEW.snapshot_frozen_at<>NEW.created_at OR NOT EXISTS(SELECT 1 FROM approval_events event WHERE event.tenant_id=NEW.tenant_id AND event.approval_event_id=NEW.approval_event_id AND event.created_at=NEW.created_at)) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='approval_outbox_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_approval_outbox_owner_insert_prd078" BEFORE INSERT ON "approval_event_outbox" FOR EACH ROW EXECUTE FUNCTION "fn_trg_approval_outbox_owner_insert_prd078"();
CREATE OR REPLACE FUNCTION "fn_trg_approval_outbox_transition_prd078"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.approval_outbox_id<>OLD.approval_outbox_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.approval_event_id<>OLD.approval_event_id OR NEW.created_at<>OLD.created_at OR NEW.lease_generation<>OLD.lease_generation+1 OR unixepoch(NEW.updated_at)<unixepoch(OLD.updated_at) OR (OLD.subscription_snapshot_json IS NOT NULL AND (NEW.subscription_snapshot_json<>OLD.subscription_snapshot_json OR NEW.snapshot_frozen_at<>OLD.snapshot_frozen_at)) OR (OLD.subscription_snapshot_json IS NULL AND NEW.subscription_snapshot_json IS NOT NULL AND NEW.snapshot_frozen_at<>NEW.updated_at) OR NOT ( (OLD.status='pending' AND NEW.status='processing' AND NEW.attempt_count=OLD.attempt_count+1 AND NEW.lease_owner_id IS NOT NULL AND length(NEW.lease_owner_id) BETWEEN 1 AND 160 AND NEW.lease_token IS NOT NULL AND length(NEW.lease_token)=64 AND NEW.lease_token OPERATOR(public.!@@) '*[^0-9a-f]*' AND unixepoch(NEW.lease_expires_at)=unixepoch(NEW.updated_at)+90) OR (OLD.status='processing' AND NEW.status='processing' AND unixepoch(NEW.updated_at)>=unixepoch(OLD.lease_expires_at) AND NEW.attempt_count=OLD.attempt_count+1 AND NEW.lease_token<>OLD.lease_token AND NEW.lease_owner_id IS NOT NULL AND length(NEW.lease_owner_id) BETWEEN 1 AND 160 AND NEW.lease_token IS NOT NULL AND length(NEW.lease_token)=64 AND NEW.lease_token OPERATOR(public.!@@) '*[^0-9a-f]*' AND unixepoch(NEW.lease_expires_at)=unixepoch(NEW.updated_at)+90) OR (OLD.status='processing' AND NEW.status='processing' AND NEW.attempt_count=OLD.attempt_count AND NEW.lease_owner_id=OLD.lease_owner_id AND NEW.lease_token=OLD.lease_token AND unixepoch(NEW.updated_at)>unixepoch(OLD.updated_at) AND unixepoch(OLD.lease_expires_at)>unixepoch(NEW.updated_at) AND unixepoch(NEW.lease_expires_at)=unixepoch(NEW.updated_at)+90) OR (OLD.status='processing' AND NEW.status='pending' AND NEW.attempt_count=OLD.attempt_count AND NEW.attempt_count<10 AND NEW.last_error_code='webhook.delivery_unavailable' AND unixepoch(NEW.next_attempt_at)=unixepoch(NEW.updated_at)+CASE NEW.attempt_count WHEN 1 THEN 5 WHEN 2 THEN 30 ELSE 300 END) OR (OLD.status='processing' AND NEW.status='delivered' AND NEW.attempt_count=OLD.attempt_count AND NEW.delivered_at=NEW.updated_at AND NEW.subscription_snapshot_json IS NOT NULL) OR (OLD.status='processing' AND NEW.status='failed' AND NEW.attempt_count=OLD.attempt_count AND ((NEW.last_error_code='webhook.payload_invalid') OR (NEW.attempt_count=10 AND NEW.last_error_code='webhook.delivery_unavailable'))) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='approval_outbox_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
