CREATE OR REPLACE FUNCTION "fn_trg_quota_settlements_owner_insert_prd079"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS(SELECT 1 FROM quota_reservations reservation JOIN usage_ledger usage ON usage.tenant_id=reservation.tenant_id AND usage.request_id=reservation.request_id JOIN finops_ledger_entries ledger ON ledger.tenant_id=usage.tenant_id AND ledger.usage_ledger_id=usage.usage_ledger_id WHERE reservation.tenant_id=NEW.tenant_id AND reservation.plan_id=NEW.plan_id AND reservation.quota_reservation_id=NEW.quota_reservation_id AND reservation.request_id=NEW.request_id AND reservation.trace_id=NEW.trace_id AND usage.usage_ledger_id=NEW.usage_ledger_id AND ledger.finops_ledger_entry_id=NEW.finops_ledger_entry_id AND ledger.source_request_id=reservation.request_id AND ledger.source_trace_id=reservation.trace_id AND ledger.entry_type='usage_charge' AND ledger.direction='debit' AND ( (NEW.amount_basis='actual_cny' AND ledger.cny_normalization_status='normalized' AND ledger.normalized_cny_micros=NEW.amount_micros) OR (NEW.amount_basis='admission_estimate' AND ledger.cny_normalization_status='unavailable' AND ledger.normalized_cny_micros IS NULL AND NEW.amount_micros=( reservation.estimated_micros-NEW.exposure_outstanding_micros)) ) AND NOT EXISTS(SELECT 1 FROM quota_usage_settlements existing WHERE existing.tenant_id=reservation.tenant_id AND existing.quota_reservation_id=reservation.quota_reservation_id) AND ( (reservation.status='exposure_pending' AND reservation.actual_micros=NEW.amount_micros AND reservation.unallocated_micros=NEW.unallocated_micros AND reservation.outstanding_micros=NEW.exposure_outstanding_micros AND NEW.exposure_outstanding_micros>0) OR (reservation.status IN('settled','overage') AND reservation.actual_micros=NEW.amount_micros AND reservation.unallocated_micros=NEW.unallocated_micros AND reservation.outstanding_micros=0 AND NEW.exposure_outstanding_micros=0) OR (reservation.status IN('released','reconciliation_required') AND NEW.exposure_outstanding_micros=0 AND NEW.allocated_micros=0 AND NEW.unallocated_micros=NEW.amount_micros AND ((NEW.amount_micros=0 AND NEW.status='settled') OR (NEW.amount_micros>0 AND NEW.status='overage'))) ))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='quota_settlement_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
