CREATE OR REPLACE FUNCTION "fn_trg_billing_disputes_transition_prd080"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.billing_dispute_sequence<>OLD.billing_dispute_sequence OR NEW.billing_dispute_id<>OLD.billing_dispute_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.scope_type<>OLD.scope_type OR NEW.period_start IS DISTINCT FROM OLD.period_start OR NEW.period_end IS DISTINCT FROM OLD.period_end OR NEW.item_count<>OLD.item_count OR NEW.reason<>OLD.reason OR NEW.reason_sha256<>OLD.reason_sha256 OR NEW.created_by_user_id<>OLD.created_by_user_id OR NEW.create_request_id<>OLD.create_request_id OR NEW.create_trace_id<>OLD.create_trace_id OR NEW.create_idempotency_sha256<>OLD.create_idempotency_sha256 OR NEW.payload_sha256<>OLD.payload_sha256 OR NEW.created_at<>OLD.created_at OR NEW.state_revision<>OLD.state_revision+1 OR unixepoch(NEW.updated_at)<unixepoch(OLD.updated_at) OR (OLD.status='submitted' AND NEW.status NOT IN('under_review','cancelled')) OR (OLD.status='under_review' AND NEW.status NOT IN('approved','rejected')) OR OLD.status IN('approved','rejected','cancelled') OR (NEW.status IN('under_review','approved','rejected') AND (NEW.reviewer_user_id=NEW.created_by_user_id OR NOT EXISTS( SELECT 1 FROM users user_row WHERE user_row.tenant_id=NEW.tenant_id AND user_row.user_id=NEW.reviewer_user_id AND user_row.status='active'))) OR (NEW.decision_reason IS NOT NULL AND NEW.decision_reason_sha256<>metahub_sha256(NEW.decision_reason))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='billing_dispute_transition_invalid';
  END IF;
  RETURN NEW;
END;
