CREATE OR REPLACE FUNCTION "fn_trg_billing_dispute_items_owner_insert_prd080"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS( SELECT 1 FROM billing_disputes dispute JOIN finops_ledger_entries entry ON entry.tenant_id=dispute.tenant_id AND entry.finops_ledger_entry_id=NEW.finops_ledger_entry_id JOIN usage_ledger usage ON usage.tenant_id=entry.tenant_id AND usage.usage_ledger_id=entry.usage_ledger_id JOIN price_snapshots snapshot ON snapshot.tenant_id=entry.tenant_id AND snapshot.price_snapshot_id=entry.price_snapshot_id WHERE dispute.tenant_id=NEW.tenant_id AND dispute.billing_dispute_id=NEW.billing_dispute_id AND dispute.status='submitted' AND dispute.state_revision=1 AND entry.entry_type='usage_charge' AND entry.status='posted' AND entry.amount_micros>0 AND entry.ledger_sequence=NEW.ledger_sequence AND entry.usage_ledger_id=NEW.usage_ledger_id AND entry.source_request_id=NEW.source_request_id AND entry.source_trace_id=NEW.source_trace_id AND usage.request_id=NEW.source_request_id AND entry.currency=NEW.currency AND entry.amount_micros=NEW.amount_micros AND entry.price_snapshot_id=NEW.price_snapshot_id AND entry.price_schema_version=NEW.price_schema_version AND entry.price_snapshot_source=NEW.price_snapshot_source AND entry.price_evidence_status=NEW.price_evidence_status AND snapshot.request_id=NEW.source_request_id AND snapshot.currency=NEW.currency AND snapshot.price_schema_version=NEW.price_schema_version AND snapshot.source=NEW.price_snapshot_source AND NEW.disputable_micros=entry.amount_micros-COALESCE(( SELECT SUM(reversal.amount_micros) FROM finops_ledger_entries reversal WHERE reversal.tenant_id=entry.tenant_id AND reversal.entry_type='reversal' AND reversal.reversal_of_entry_id=entry.finops_ledger_entry_id),0) AND (SELECT COUNT(*) FROM billing_dispute_items current WHERE current.tenant_id=dispute.tenant_id AND current.billing_dispute_id=dispute.billing_dispute_id)<dispute.item_count )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='billing_dispute_item_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
