CREATE OR REPLACE FUNCTION "fn_trg_billing_dispute_transitions_owner_insert_prd080"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS( SELECT 1 FROM billing_disputes dispute JOIN users actor ON actor.tenant_id=dispute.tenant_id AND actor.user_id=NEW.actor_user_id WHERE dispute.tenant_id=NEW.tenant_id AND dispute.billing_dispute_id=NEW.billing_dispute_id AND actor.status='active' AND dispute.status=NEW.to_status AND dispute.state_revision=NEW.new_revision AND ( (NEW.action='create' AND NEW.actor_user_id=dispute.created_by_user_id AND NEW.operation_request_id=dispute.create_request_id AND NEW.operation_trace_id=dispute.create_trace_id AND NEW.idempotency_key_sha256=dispute.create_idempotency_sha256 AND NEW.payload_sha256=dispute.payload_sha256 AND NEW.created_at=dispute.created_at) OR (NEW.action='start_review' AND NEW.actor_user_id<>dispute.created_by_user_id AND NEW.actor_user_id=dispute.reviewer_user_id AND NEW.created_at=dispute.review_started_at AND NEW.created_at=dispute.updated_at) OR (NEW.action IN('approve','reject') AND NEW.actor_user_id<>dispute.created_by_user_id AND NEW.actor_user_id=dispute.reviewer_user_id AND NEW.decision_reason_sha256=dispute.decision_reason_sha256 AND NEW.created_at=dispute.resolved_at AND NEW.created_at=dispute.updated_at) OR (NEW.action='cancel' AND NEW.actor_user_id=dispute.created_by_user_id AND dispute.reviewer_user_id IS NULL AND NEW.decision_reason_sha256=dispute.decision_reason_sha256 AND NEW.created_at=dispute.resolved_at AND NEW.created_at=dispute.updated_at) ) AND (NEW.action<>'approve' OR NEW.approved_item_count<=dispute.item_count) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='billing_dispute_transition_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
