  IF (NOT EXISTS( SELECT 1 FROM billing_dispute_items item JOIN billing_disputes dispute ON dispute.tenant_id=item.tenant_id AND dispute.billing_dispute_id=item.billing_dispute_id JOIN billing_dispute_transitions transition ON transition.tenant_id=item.tenant_id AND transition.billing_dispute_transition_id=NEW.created_transition_id WHERE item.tenant_id=NEW.tenant_id AND item.billing_dispute_item_id=NEW.billing_dispute_item_id AND item.billing_dispute_id=NEW.billing_dispute_id AND item.finops_ledger_entry_id=NEW.finops_ledger_entry_id AND dispute.status='submitted' AND transition.billing_dispute_id=item.billing_dispute_id AND transition.action='create' AND transition.new_revision=1 AND NEW.status='active' AND NEW.state_revision=1 AND NEW.created_at=transition.created_at AND NEW.updated_at=NEW.created_at )) THEN
