CREATE OR REPLACE FUNCTION "fn_trg_billing_settlement_holds_transition_prd080"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.billing_settlement_hold_id<>OLD.billing_settlement_hold_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.billing_dispute_id<>OLD.billing_dispute_id OR NEW.billing_dispute_item_id<>OLD.billing_dispute_item_id OR NEW.finops_ledger_entry_id<>OLD.finops_ledger_entry_id OR NEW.created_transition_id<>OLD.created_transition_id OR NEW.created_at<>OLD.created_at OR OLD.status<>'active' OR NEW.status<>'released' OR NEW.state_revision<>OLD.state_revision+1 OR NOT EXISTS( SELECT 1 FROM billing_disputes dispute JOIN billing_dispute_transitions transition ON transition.tenant_id=dispute.tenant_id AND transition.billing_dispute_transition_id=NEW.released_transition_id WHERE dispute.tenant_id=NEW.tenant_id AND dispute.billing_dispute_id=NEW.billing_dispute_id AND dispute.status=NEW.release_reason AND dispute.state_revision=transition.new_revision AND transition.billing_dispute_id=dispute.billing_dispute_id AND transition.action=CASE NEW.release_reason WHEN 'approved' THEN 'approve' WHEN 'rejected' THEN 'reject' ELSE 'cancel' END AND transition.to_status=NEW.release_reason AND NEW.released_at=transition.created_at AND NEW.updated_at=NEW.released_at )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='billing_settlement_hold_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
