CREATE OR REPLACE FUNCTION "fn_trg_billing_dispute_adjustment_links_owner_insert_prd080"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS( SELECT 1 FROM billing_dispute_items item JOIN billing_disputes dispute ON dispute.tenant_id=item.tenant_id AND dispute.billing_dispute_id=item.billing_dispute_id JOIN billing_dispute_transitions transition ON transition.tenant_id=item.tenant_id AND transition.billing_dispute_transition_id=NEW.billing_dispute_transition_id JOIN finops_adjustments adjustment ON adjustment.tenant_id=item.tenant_id AND adjustment.finops_adjustment_id=NEW.finops_adjustment_id JOIN finops_ledger_entries reversal ON reversal.tenant_id=item.tenant_id AND reversal.finops_ledger_entry_id=NEW.reversal_finops_ledger_entry_id WHERE item.tenant_id=NEW.tenant_id AND item.billing_dispute_item_id=NEW.billing_dispute_item_id AND item.billing_dispute_id=NEW.billing_dispute_id AND dispute.status='approved' AND dispute.state_revision=transition.new_revision AND transition.billing_dispute_id=dispute.billing_dispute_id AND transition.action='approve' AND transition.to_status='approved' AND adjustment.adjustment_type='reversal' AND adjustment.reversal_of_entry_id=item.finops_ledger_entry_id AND adjustment.amount_micros=NEW.amount_micros AND adjustment.currency=NEW.currency AND adjustment.actor_user_id=transition.actor_user_id AND adjustment.operation_request_id=transition.operation_request_id AND adjustment.operation_trace_id=transition.operation_trace_id AND reversal.entry_type='reversal' AND reversal.finops_adjustment_id=adjustment.finops_adjustment_id AND reversal.reversal_of_entry_id=item.finops_ledger_entry_id AND reversal.amount_micros=NEW.amount_micros AND reversal.currency=NEW.currency AND reversal.actor_user_id=transition.actor_user_id AND reversal.operation_request_id=transition.operation_request_id AND reversal.operation_trace_id=transition.operation_trace_id AND NEW.currency=item.currency AND NEW.amount_micros<=item.disputable_micros AND NEW.created_at=transition.created_at )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='billing_dispute_adjustment_link_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
