CREATE OR REPLACE FUNCTION "fn_trg_billing_dispute_events_owner_insert_prd080"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS( SELECT 1 FROM billing_disputes dispute WHERE dispute.tenant_id=NEW.tenant_id AND dispute.billing_dispute_id=NEW.billing_dispute_id AND dispute.status='submitted' AND dispute.state_revision=1 AND dispute.created_by_user_id=NEW.actor_user_id AND dispute.create_request_id=NEW.source_request_id AND dispute.create_trace_id=NEW.source_trace_id AND dispute.created_at=NEW.occurred_at AND (SELECT COUNT(*) FROM billing_dispute_items item WHERE item.tenant_id=dispute.tenant_id AND item.billing_dispute_id=dispute.billing_dispute_id)=dispute.item_count AND (SELECT COUNT(*) FROM json_each(NEW.payload_json))=7 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.payload_json) field WHERE field.key NOT IN('schema_version','billing_dispute_id','scope_type', 'item_count','currency_totals','status','created_at')) AND json_type(NEW.payload_json,'$.schema_version')='integer' AND (json_extract(NEW.payload_json,'$.schema_version'))::NUMERIC=1 AND json_extract(NEW.payload_json,'$.billing_dispute_id')=dispute.billing_dispute_id AND json_extract(NEW.payload_json,'$.scope_type')=dispute.scope_type AND (json_extract(NEW.payload_json,'$.item_count'))::NUMERIC=dispute.item_count AND json_extract(NEW.payload_json,'$.status')='submitted' AND json_extract(NEW.payload_json,'$.created_at')=dispute.created_at AND json_type(NEW.payload_json,'$.currency_totals')='object' AND NOT EXISTS(SELECT 1 FROM json_each(NEW.payload_json,'$.currency_totals') total WHERE total.key NOT IN('CNY','USD') OR total.type<>'text') AND (SELECT COUNT(*) FROM json_each(NEW.payload_json,'$.currency_totals')) =(SELECT COUNT(DISTINCT item.currency) FROM billing_dispute_items item WHERE item.tenant_id=dispute.tenant_id AND item.billing_dispute_id=dispute.billing_dispute_id) AND ((NOT EXISTS(SELECT 1 FROM billing_dispute_items item WHERE item.tenant_id=dispute.tenant_id AND item.billing_dispute_id=dispute.billing_dispute_id AND item.currency='CNY') AND json_type(NEW.payload_json,'$.currency_totals.CNY') IS NULL) OR json_extract(NEW.payload_json,'$.currency_totals.CNY')=( SELECT printf('%d.%06d',SUM(item.disputable_micros)/1000000, SUM(item.disputable_micros)%1000000) FROM billing_dispute_items item WHERE item.tenant_id=dispute.tenant_id AND item.billing_dispute_id=dispute.billing_dispute_id AND item.currency='CNY')) AND ((NOT EXISTS(SELECT 1 FROM billing_dispute_items item WHERE item.tenant_id=dispute.tenant_id AND item.billing_dispute_id=dispute.billing_dispute_id AND item.currency='USD') AND json_type(NEW.payload_json,'$.currency_totals.USD') IS NULL) OR json_extract(NEW.payload_json,'$.currency_totals.USD')=( SELECT printf('%d.%06d',SUM(item.disputable_micros)/1000000, SUM(item.disputable_micros)%1000000) FROM billing_dispute_items item WHERE item.tenant_id=dispute.tenant_id AND item.billing_dispute_id=dispute.billing_dispute_id AND item.currency='USD')) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='billing_dispute_event_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
