BEGIN
  IF (NOT ( (NEW.source_event_type='security.dlp_matched' AND EXISTS( SELECT 1 FROM dlp_matches source WHERE source.tenant_id=NEW.tenant_id AND source.dlp_match_id=NEW.source_object_id AND length(source.dlp_match_id)=37 AND substr(source.dlp_match_id,1,5)='dlpm_' AND substr(source.dlp_match_id,6) OPERATOR(public.!@@) '*[^0-9a-f]*' AND NEW.security_event_source_id='sesrc_'||substr(source.dlp_match_id,-32) AND NEW.category='data_loss_prevention' AND NEW.severity=CASE source.action WHEN 'allow' THEN 'low' WHEN 'log_only' THEN 'medium' ELSE 'high' END AND NEW.severity_score=CASE source.action WHEN 'allow' THEN 3 WHEN 'log_only' THEN 5 ELSE 8 END AND NEW.action=source.action AND NEW.outcome=CASE WHEN source.action='block' THEN 'blocked' ELSE 'observed' END AND NEW.resource_type='dlp_rule' AND NEW.resource_id=source.dlp_rule_id AND NEW.source_request_id=source.request_id AND NEW.source_trace_id=COALESCE(source.trace_id,source.request_id) AND NEW.occurrence_count=1 AND NEW.occurred_at=source.created_at AND NEW.created_at=source.created_at )) OR (NEW.source_event_type='security.session_high_risk' AND EXISTS( SELECT 1 FROM session_risk_events source JOIN session_risk_actions action ON action.tenant_id=source.tenant_id AND action.session_risk_action_id=source.session_risk_action_id WHERE source.tenant_id=NEW.tenant_id AND source.session_risk_event_id=NEW.source_object_id AND length(source.session_risk_event_id)=38 AND substr(source.session_risk_event_id,1,6)='srevt_' AND substr(source.session_risk_event_id,7) OPERATOR(public.!@@) '*[^0-9a-f]*' AND NEW.security_event_source_id='sesrc_'||substr(source.session_risk_event_id,-32) AND NEW.category='session_risk' AND NEW.severity=CASE WHEN action.action IN('freeze_session','freeze_virtual_key') THEN 'critical' WHEN action.action='high_risk' THEN 'high' ELSE 'medium' END AND NEW.severity_score=CASE WHEN action.action IN('freeze_session','freeze_virtual_key') THEN 10 WHEN action.action='high_risk' THEN 8 ELSE 4 END AND NEW.action=action.action AND NEW.outcome=CASE action.action WHEN 'high_risk' THEN 'detected' WHEN 'freeze_session' THEN 'frozen' WHEN 'freeze_virtual_key' THEN 'frozen' WHEN 'dismiss' THEN 'resolved' WHEN 'release_session' THEN 'released' WHEN 'release_virtual_key' THEN 'released' ELSE 'expired' END AND NEW.resource_type='session_risk_score' AND NEW.resource_id=source.session_risk_score_id AND NEW.source_request_id=source.source_request_id AND NEW.source_trace_id=source.source_trace_id AND NEW.occurrence_count=source.risky_turn_count AND NEW.occurred_at=source.occurred_at AND NEW.created_at=source.occurred_at )) OR (NEW.source_event_type='security.provider_key_anomaly' AND NEW.action='authentication_failed' AND EXISTS( SELECT 1 FROM provider_error_facts source WHERE source.tenant_id=NEW.tenant_id AND source.provider_error_fact_id=NEW.source_object_id AND source.normalized_output_error_code='gateway.upstream_auth_failed' AND length(source.provider_error_fact_id)=36 AND substr(source.provider_error_fact_id,1,4)='pef_' AND substr(source.provider_error_fact_id,5) OPERATOR(public.!@@) '*[^0-9a-f]*' AND NEW.security_event_source_id='sesrc_'||substr(source.provider_error_fact_id,-32) AND NEW.category='provider_credential' AND NEW.severity='critical' AND NEW.severity_score=9 AND NEW.outcome='rejected' AND NEW.resource_type='provider' AND NEW.resource_id=source.provider_id AND NEW.source_request_id=source.request_id AND NEW.source_trace_id=source.trace_id AND NEW.occurrence_count=1 AND NEW.occurred_at=source.created_at AND NEW.created_at=source.created_at )) OR (NEW.source_event_type='security.provider_key_anomaly' AND NEW.action='decrypt_failed' AND EXISTS( SELECT 1 FROM provider_key_anomaly_events source WHERE source.tenant_id=NEW.tenant_id AND source.provider_key_anomaly_event_id=NEW.source_object_id AND NEW.security_event_source_id= 'sesrc_'||substr(source.provider_key_anomaly_event_id,-32) AND NEW.category='provider_credential' AND NEW.severity='critical' AND NEW.severity_score=9 AND NEW.outcome='rejected' AND NEW.resource_type='provider' AND NEW.resource_id=source.provider_id AND NEW.source_request_id=source.request_id AND NEW.source_trace_id=source.trace_id AND NEW.occurrence_count=source.candidate_count AND NEW.occurred_at=source.occurred_at AND NEW.created_at=source.created_at )) ) OR EXISTS(SELECT 1 FROM security_event_sources current WHERE current.security_event_source_id=NEW.security_event_source_id OR (current.tenant_id=NEW.tenant_id AND current.source_event_type=NEW.source_event_type AND current.source_object_id=NEW.source_object_id) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
