BEGIN
  IF (NEW.security_event_id<>OLD.security_event_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.source_event_type<>OLD.source_event_type OR NEW.category<>OLD.category OR NEW.severity<>OLD.severity OR NEW.severity_score<>OLD.severity_score OR NEW.action<>OLD.action OR NEW.outcome<>OLD.outcome OR NEW.resource_type<>OLD.resource_type OR NEW.resource_id<>OLD.resource_id OR NEW.window_started_at<>OLD.window_started_at OR NEW.window_ended_at<>OLD.window_ended_at OR NEW.generation<>OLD.generation OR NEW.created_at<>OLD.created_at OR NOT EXISTS(SELECT 1 FROM security_event_outbox outbox WHERE outbox.tenant_id=OLD.tenant_id AND outbox.security_event_id=OLD.security_event_id AND outbox.status='pending') OR NEW.source_event_count<>(SELECT COUNT(*) FROM security_event_aggregate_members member WHERE member.tenant_id=OLD.tenant_id AND member.security_event_id=OLD.security_event_id) OR NEW.event_count<>(SELECT COALESCE(SUM(source.occurrence_count),0) FROM security_event_aggregate_members member JOIN security_event_sources source ON source.tenant_id=member.tenant_id AND source.security_event_source_id=member.security_event_source_id WHERE member.tenant_id=OLD.tenant_id AND member.security_event_id=OLD.security_event_id) OR NEW.first_seen_at<>(SELECT source.occurred_at FROM security_event_aggregate_members member JOIN security_event_sources source ON source.tenant_id=member.tenant_id AND source.security_event_source_id=member.security_event_source_id WHERE member.tenant_id=OLD.tenant_id AND member.security_event_id=OLD.security_event_id ORDER BY source.occurred_at,source.security_event_source_id LIMIT 1) OR NEW.last_seen_at<>(SELECT source.occurred_at FROM security_event_aggregate_members member JOIN security_event_sources source ON source.tenant_id=member.tenant_id AND source.security_event_source_id=member.security_event_source_id WHERE member.tenant_id=OLD.tenant_id AND member.security_event_id=OLD.security_event_id ORDER BY source.occurred_at DESC,source.security_event_source_id DESC LIMIT 1) OR NEW.first_request_id<>(SELECT source.source_request_id FROM security_event_aggregate_members member JOIN security_event_sources source ON source.tenant_id=member.tenant_id AND source.security_event_source_id=member.security_event_source_id WHERE member.tenant_id=OLD.tenant_id AND member.security_event_id=OLD.security_event_id ORDER BY source.occurred_at,source.security_event_source_id LIMIT 1) OR NEW.last_request_id<>(SELECT source.source_request_id FROM security_event_aggregate_members member JOIN security_event_sources source ON source.tenant_id=member.tenant_id AND source.security_event_source_id=member.security_event_source_id WHERE member.tenant_id=OLD.tenant_id AND member.security_event_id=OLD.security_event_id ORDER BY source.occurred_at DESC,source.security_event_source_id DESC LIMIT 1) OR NEW.first_trace_id<>(SELECT source.source_trace_id FROM security_event_aggregate_members member JOIN security_event_sources source ON source.tenant_id=member.tenant_id AND source.security_event_source_id=member.security_event_source_id WHERE member.tenant_id=OLD.tenant_id AND member.security_event_id=OLD.security_event_id ORDER BY source.occurred_at,source.security_event_source_id LIMIT 1) OR NEW.last_trace_id<>(SELECT source.source_trace_id FROM security_event_aggregate_members member JOIN security_event_sources source ON source.tenant_id=member.tenant_id AND source.security_event_source_id=member.security_event_source_id WHERE member.tenant_id=OLD.tenant_id AND member.security_event_id=OLD.security_event_id ORDER BY source.occurred_at DESC,source.security_event_source_id DESC LIMIT 1) OR NEW.updated_at<>(SELECT MAX(source.created_at) FROM security_event_aggregate_members member JOIN security_event_sources source ON source.tenant_id=member.tenant_id AND source.security_event_source_id=member.security_event_source_id WHERE member.tenant_id=OLD.tenant_id AND member.security_event_id=OLD.security_event_id)) THEN
