CREATE OR REPLACE FUNCTION "fn_trg_security_event_sources_aggregate_prd081"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  INSERT INTO security_event_aggregates( security_event_id,tenant_id,source_event_type,category,severity,severity_score, action,outcome,resource_type,resource_id,window_started_at,window_ended_at,generation, event_count,source_event_count,first_seen_at,last_seen_at,first_request_id,last_request_id, first_trace_id,last_trace_id,created_at,updated_at ) SELECT 'sevt_'||substr(NEW.source_object_id,-32),NEW.tenant_id,NEW.source_event_type, NEW.category,NEW.severity,NEW.severity_score,NEW.action,NEW.outcome, NEW.resource_type,NEW.resource_id, strftime('%Y-%m-%dT%H:%M:',NEW.occurred_at) ||printf('%02d',(CAST(strftime('%S',NEW.occurred_at) AS INTEGER)/5)*5)||'Z', strftime('%Y-%m-%dT%H:%M:%SZ', strftime('%Y-%m-%dT%H:%M:',NEW.occurred_at) ||printf('%02d',(CAST(strftime('%S',NEW.occurred_at) AS INTEGER)/5)*5)||'Z', '+5 seconds'), (SELECT COALESCE(MAX(current.generation),-1)+1 FROM security_event_aggregates current WHERE current.tenant_id=NEW.tenant_id AND current.source_event_type=NEW.source_event_type AND current.category=NEW.category AND current.severity=NEW.severity AND current.severity_score=NEW.severity_score AND current.action=NEW.action AND current.outcome=NEW.outcome AND current.resource_type=NEW.resource_type AND current.resource_id=NEW.resource_id AND current.window_started_at= strftime('%Y-%m-%dT%H:%M:',NEW.occurred_at) ||printf('%02d',(CAST(strftime('%S',NEW.occurred_at) AS INTEGER)/5)*5)||'Z'), 0,0,NEW.occurred_at,NEW.occurred_at,NEW.source_request_id,NEW.source_request_id, NEW.source_trace_id,NEW.source_trace_id,NEW.created_at,NEW.created_at WHERE NOT EXISTS( SELECT 1 FROM security_event_aggregates aggregate JOIN security_event_outbox outbox ON outbox.tenant_id=aggregate.tenant_id AND outbox.security_event_id=aggregate.security_event_id WHERE aggregate.tenant_id=NEW.tenant_id AND aggregate.source_event_type=NEW.source_event_type AND aggregate.category=NEW.category AND aggregate.severity=NEW.severity AND aggregate.severity_score=NEW.severity_score AND aggregate.action=NEW.action AND aggregate.outcome=NEW.outcome AND aggregate.resource_type=NEW.resource_type AND aggregate.resource_id=NEW.resource_id AND aggregate.window_started_at= strftime('%Y-%m-%dT%H:%M:',NEW.occurred_at) ||printf('%02d',(CAST(strftime('%S',NEW.occurred_at) AS INTEGER)/5)*5)||'Z' AND outbox.status='pending' AND aggregate.source_event_count<1000 );
  INSERT INTO security_event_outbox( security_event_outbox_id,tenant_id,security_event_id,status,attempt_count, lease_generation,lease_token,lease_owner_id,lease_expires_at,next_attempt_at, snapshot_source_count,snapshot_endpoint_count,last_error_code,created_at,updated_at, succeeded_at,failed_at ) SELECT 'seob_'||substr(aggregate.security_event_id,-32),aggregate.tenant_id, aggregate.security_event_id,'pending',0,0,NULL,NULL,NULL,aggregate.window_ended_at, NULL,NULL,NULL,aggregate.created_at,aggregate.created_at,NULL,NULL FROM security_event_aggregates aggregate WHERE aggregate.tenant_id=NEW.tenant_id AND aggregate.source_event_type=NEW.source_event_type AND aggregate.category=NEW.category AND aggregate.severity=NEW.severity AND aggregate.severity_score=NEW.severity_score AND aggregate.action=NEW.action AND aggregate.outcome=NEW.outcome AND aggregate.resource_type=NEW.resource_type AND aggregate.resource_id=NEW.resource_id AND aggregate.window_started_at= strftime('%Y-%m-%dT%H:%M:',NEW.occurred_at) ||printf('%02d',(CAST(strftime('%S',NEW.occurred_at) AS INTEGER)/5)*5)||'Z' AND NOT EXISTS(SELECT 1 FROM security_event_outbox outbox WHERE outbox.tenant_id=aggregate.tenant_id AND outbox.security_event_id=aggregate.security_event_id);
  INSERT INTO security_event_aggregate_members( security_event_aggregate_member_id,tenant_id,security_event_id, security_event_source_id,joined_at ) SELECT 'sembr_'||substr(NEW.security_event_source_id,-32),NEW.tenant_id, aggregate.security_event_id,NEW.security_event_source_id,NEW.created_at FROM security_event_aggregates aggregate JOIN security_event_outbox outbox ON outbox.tenant_id=aggregate.tenant_id AND outbox.security_event_id=aggregate.security_event_id WHERE aggregate.tenant_id=NEW.tenant_id AND aggregate.source_event_type=NEW.source_event_type AND aggregate.category=NEW.category AND aggregate.severity=NEW.severity AND aggregate.severity_score=NEW.severity_score AND aggregate.action=NEW.action AND aggregate.outcome=NEW.outcome AND aggregate.resource_type=NEW.resource_type AND aggregate.resource_id=NEW.resource_id AND aggregate.window_started_at= strftime('%Y-%m-%dT%H:%M:',NEW.occurred_at) ||printf('%02d',(CAST(strftime('%S',NEW.occurred_at) AS INTEGER)/5)*5)||'Z' AND outbox.status='pending' AND aggregate.source_event_count<1000 ORDER BY aggregate.generation DESC LIMIT 1;
  UPDATE security_event_aggregates SET event_count=(SELECT SUM(source.occurrence_count) FROM security_event_aggregate_members member JOIN security_event_sources source ON source.tenant_id=member.tenant_id AND source.security_event_source_id=member.security_event_source_id WHERE member.tenant_id=NEW.tenant_id AND member.security_event_id=security_event_aggregates.security_event_id), source_event_count=(SELECT COUNT(*) FROM security_event_aggregate_members member WHERE member.tenant_id=NEW.tenant_id AND member.security_event_id=security_event_aggregates.security_event_id), first_seen_at=(SELECT source.occurred_at FROM security_event_aggregate_members member JOIN security_event_sources source ON source.tenant_id=member.tenant_id AND source.security_event_source_id=member.security_event_source_id WHERE member.tenant_id=NEW.tenant_id AND member.security_event_id=security_event_aggregates.security_event_id ORDER BY source.occurred_at,source.security_event_source_id LIMIT 1), last_seen_at=(SELECT source.occurred_at FROM security_event_aggregate_members member JOIN security_event_sources source ON source.tenant_id=member.tenant_id AND source.security_event_source_id=member.security_event_source_id WHERE member.tenant_id=NEW.tenant_id AND member.security_event_id=security_event_aggregates.security_event_id ORDER BY source.occurred_at DESC,source.security_event_source_id DESC LIMIT 1), first_request_id=(SELECT source.source_request_id FROM security_event_aggregate_members member JOIN security_event_sources source ON source.tenant_id=member.tenant_id AND source.security_event_source_id=member.security_event_source_id WHERE member.tenant_id=NEW.tenant_id AND member.security_event_id=security_event_aggregates.security_event_id ORDER BY source.occurred_at,source.security_event_source_id LIMIT 1), last_request_id=(SELECT source.source_request_id FROM security_event_aggregate_members member JOIN security_event_sources source ON source.tenant_id=member.tenant_id AND source.security_event_source_id=member.security_event_source_id WHERE member.tenant_id=NEW.tenant_id AND member.security_event_id=security_event_aggregates.security_event_id ORDER BY source.occurred_at DESC,source.security_event_source_id DESC LIMIT 1), first_trace_id=(SELECT source.source_trace_id FROM security_event_aggregate_members member JOIN security_event_sources source ON source.tenant_id=member.tenant_id AND source.security_event_source_id=member.security_event_source_id WHERE member.tenant_id=NEW.tenant_id AND member.security_event_id=security_event_aggregates.security_event_id ORDER BY source.occurred_at,source.security_event_source_id LIMIT 1), last_trace_id=(SELECT source.source_trace_id FROM security_event_aggregate_members member JOIN security_event_sources source ON source.tenant_id=member.tenant_id AND source.security_event_source_id=member.security_event_source_id WHERE member.tenant_id=NEW.tenant_id AND member.security_event_id=security_event_aggregates.security_event_id ORDER BY source.occurred_at DESC,source.security_event_source_id DESC LIMIT 1), updated_at=(SELECT MAX(source.created_at) FROM security_event_aggregate_members member JOIN security_event_sources source ON source.tenant_id=member.tenant_id AND source.security_event_source_id=member.security_event_source_id WHERE member.tenant_id=NEW.tenant_id AND member.security_event_id=security_event_aggregates.security_event_id) WHERE tenant_id=NEW.tenant_id AND security_event_id=( SELECT member.security_event_id FROM security_event_aggregate_members member WHERE member.tenant_id=NEW.tenant_id AND member.security_event_source_id=NEW.security_event_source_id );
  RETURN NEW;
END;
$trigger$;
