CREATE OR REPLACE FUNCTION "fn_trg_dlp_matches_security_source_prd081"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF length(NEW.dlp_match_id)=37 AND substr(NEW.dlp_match_id,1,5)='dlpm_' AND substr(NEW.dlp_match_id,6) OPERATOR(public.!@@) '*[^0-9a-f]*' AND length(NEW.request_id) BETWEEN 1 AND 128 AND NEW.request_id OPERATOR(public.!@@) '*[^A-Za-z0-9_.:-]*' AND (NEW.trace_id IS NULL OR (length(NEW.trace_id) BETWEEN 1 AND 128 AND NEW.trace_id OPERATOR(public.!@@) '*[^A-Za-z0-9_.:-]*')) AND length(NEW.dlp_rule_id) BETWEEN 1 AND 160 AND NEW.dlp_rule_id OPERATOR(public.!@@) '*[^A-Za-z0-9_.:-]*' AND unixepoch(NEW.created_at) IS NOT NULL THEN
    INSERT INTO security_event_sources( security_event_source_id,tenant_id,source_event_type,source_object_id,category, severity,severity_score,action,outcome,resource_type,resource_id, source_request_id,source_trace_id,occurrence_count,occurred_at,created_at ) VALUES( 'sesrc_'||substr(NEW.dlp_match_id,-32),NEW.tenant_id,'security.dlp_matched', NEW.dlp_match_id,'data_loss_prevention', CASE NEW.action WHEN 'allow' THEN 'low' WHEN 'log_only' THEN 'medium' ELSE 'high' END, CASE NEW.action WHEN 'allow' THEN 3 WHEN 'log_only' THEN 5 ELSE 8 END, NEW.action,CASE WHEN NEW.action='block' THEN 'blocked' ELSE 'observed' END, 'dlp_rule',NEW.dlp_rule_id,NEW.request_id,COALESCE(NEW.trace_id,NEW.request_id), 1,NEW.created_at,NEW.created_at );
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_dlp_matches_security_source_prd081" AFTER INSERT ON "dlp_matches" FOR EACH ROW EXECUTE FUNCTION "fn_trg_dlp_matches_security_source_prd081"();
