    INSERT INTO security_event_sources( security_event_source_id,tenant_id,source_event_type,source_object_id,category, severity,severity_score,action,outcome,resource_type,resource_id, source_request_id,source_trace_id,occurrence_count,occurred_at,created_at ) SELECT 'sesrc_'||substr(NEW.session_risk_event_id,-32),NEW.tenant_id, 'security.session_high_risk',NEW.session_risk_event_id,'session_risk', CASE WHEN action.action IN('freeze_session','freeze_virtual_key') THEN 'critical' WHEN action.action='high_risk' THEN 'high' ELSE 'medium' END, CASE WHEN action.action IN('freeze_session','freeze_virtual_key') THEN 10 WHEN action.action='high_risk' THEN 8 ELSE 4 END, action.action,CASE action.action WHEN 'high_risk' THEN 'detected' WHEN 'freeze_session' THEN 'frozen' WHEN 'freeze_virtual_key' THEN 'frozen' WHEN 'dismiss' THEN 'resolved' WHEN 'release_session' THEN 'released' WHEN 'release_virtual_key' THEN 'released' ELSE 'expired' END, 'session_risk_score',NEW.session_risk_score_id,NEW.source_request_id, NEW.source_trace_id,NEW.risky_turn_count,NEW.occurred_at,NEW.occurred_at FROM session_risk_actions action WHERE action.tenant_id=NEW.tenant_id AND action.session_risk_action_id=NEW.session_risk_action_id;
