END;
$trigger$;
CREATE TRIGGER "trg_session_risk_events_security_source_prd081" AFTER INSERT ON "session_risk_events" FOR EACH ROW EXECUTE FUNCTION "fn_trg_session_risk_events_security_source_prd081"();
