CREATE OR REPLACE FUNCTION "fn_trg_provider_key_anomaly_security_source_prd081"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  INSERT INTO security_event_sources( security_event_source_id,tenant_id,source_event_type,source_object_id,category, severity,severity_score,action,outcome,resource_type,resource_id, source_request_id,source_trace_id,occurrence_count,occurred_at,created_at ) VALUES( 'sesrc_'||substr(NEW.provider_key_anomaly_event_id,-32),NEW.tenant_id, 'security.provider_key_anomaly',NEW.provider_key_anomaly_event_id,'provider_credential', 'critical',9,'decrypt_failed','rejected','provider',NEW.provider_id, NEW.request_id,NEW.trace_id,NEW.candidate_count,NEW.occurred_at,NEW.created_at );
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_provider_key_anomaly_security_source_prd081" AFTER INSERT ON "provider_key_anomaly_events" FOR EACH ROW EXECUTE FUNCTION "fn_trg_provider_key_anomaly_security_source_prd081"();
CREATE OR REPLACE FUNCTION "fn_trg_webhook_security_rate_claim_owner_prd081"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.webhook_security_rate_claim_id<>'wsrc_'||substr(NEW.webhook_delivery_id,-32) OR strftime('%Y-%m-%dT%H:%M:00Z',NEW.created_at)<>NEW.bucket_started_at OR NEW.bucket_ended_at<>strftime('%Y-%m-%dT%H:%M:%SZ',NEW.bucket_started_at,'+1 minute') OR NEW.expires_at<>strftime('%Y-%m-%dT%H:%M:%SZ',NEW.bucket_ended_at,'+30 days') OR NOT EXISTS(SELECT 1 FROM webhook_deliveries delivery WHERE delivery.tenant_id=NEW.tenant_id AND delivery.webhook_endpoint_id=NEW.webhook_endpoint_id AND delivery.webhook_delivery_id=NEW.webhook_delivery_id AND delivery.event_type='security.event_pushed' AND delivery.status='pending' AND delivery.security_event_rate_limit_per_minute=NEW.rate_limit_per_minute) OR NEW.slot_number<>(SELECT COALESCE(MAX(current.slot_number),0)+1 FROM webhook_security_rate_claims current WHERE current.tenant_id=NEW.tenant_id AND current.webhook_endpoint_id=NEW.webhook_endpoint_id AND current.bucket_started_at=NEW.bucket_started_at) OR EXISTS(SELECT 1 FROM webhook_security_rate_claims current WHERE current.webhook_security_rate_claim_id=NEW.webhook_security_rate_claim_id OR (current.tenant_id=NEW.tenant_id AND current.webhook_delivery_id=NEW.webhook_delivery_id) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='webhook_security_rate_claim_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_webhook_security_rate_claim_owner_prd081" BEFORE INSERT ON "webhook_security_rate_claims" FOR EACH ROW EXECUTE FUNCTION "fn_trg_webhook_security_rate_claim_owner_prd081"();
