LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (unixepoch(OLD.expires_at)>unixepoch('now') OR EXISTS( SELECT 1 FROM webhook_deliveries delivery WHERE delivery.tenant_id=OLD.tenant_id AND delivery.webhook_delivery_id=OLD.webhook_delivery_id AND delivery.status='pending' )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='webhook_security_rate_claim_immutable';
  END IF;
