LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.status<>'pending_sync' OR NEW.state_revision<>1 OR NEW.created_at<>NEW.updated_at OR NEW.created_by<>NEW.updated_by OR NEW.active_credential_revision IS NOT NULL OR NEW.protocol_version IS NOT NULL OR NEW.capabilities_sha256 IS NOT NULL OR NOT EXISTS(SELECT 1 FROM tenants tenant JOIN users actor ON actor.tenant_id=tenant.tenant_id WHERE tenant.tenant_id=NEW.tenant_id AND tenant.status='active' AND actor.user_id=NEW.created_by AND actor.status='active') OR EXISTS(SELECT 1 FROM mcp_servers current WHERE current.mcp_server_id=NEW.mcp_server_id OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='mcp_server_owner_mismatch';
