CREATE OR REPLACE FUNCTION "fn_trg_mcp_servers_transition_prd082"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.mcp_server_id<>OLD.mcp_server_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.transport<>OLD.transport OR NEW.endpoint_ciphertext<>OLD.endpoint_ciphertext OR NEW.endpoint_encryption_key_version<>OLD.endpoint_encryption_key_version OR NEW.endpoint_hmac<>OLD.endpoint_hmac OR NEW.endpoint_hmac_key_version<>OLD.endpoint_hmac_key_version OR NEW.endpoint_scheme<>OLD.endpoint_scheme OR NEW.endpoint_host_hint<>OLD.endpoint_host_hint OR NEW.endpoint_has_path<>OLD.endpoint_has_path OR NEW.created_by<>OLD.created_by OR NEW.created_at<>OLD.created_at OR NEW.state_revision<>OLD.state_revision+1 OR unixepoch(NEW.updated_at)<unixepoch(OLD.updated_at) OR NOT EXISTS(SELECT 1 FROM users actor WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.updated_by AND actor.status='active') OR (NEW.active_credential_revision IS NOT NULL AND NOT EXISTS( SELECT 1 FROM mcp_server_credentials credential WHERE credential.tenant_id=NEW.tenant_id AND credential.mcp_server_id=NEW.mcp_server_id AND credential.credential_revision=NEW.active_credential_revision AND credential.status='active')) OR NOT ((OLD.status='pending_sync' AND NEW.status IN( 'pending_sync','active','sync_failed','disabled')) OR (OLD.status='active' AND NEW.status IN('pending_sync','active','disabled')) OR (OLD.status='sync_failed' AND NEW.status IN('pending_sync','sync_failed','disabled')) OR (OLD.status='disabled' AND NEW.status IN('disabled','active')))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='mcp_server_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_mcp_servers_transition_prd082" BEFORE UPDATE ON "mcp_servers" FOR EACH ROW EXECUTE FUNCTION "fn_trg_mcp_servers_transition_prd082"();
