  IF (NEW.ctid<>OLD.ctid OR NEW.mcp_server_credential_id<>OLD.mcp_server_credential_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.mcp_server_id<>OLD.mcp_server_id OR NEW.credential_revision<>OLD.credential_revision OR NEW.auth_type<>OLD.auth_type OR NEW.credential_ciphertext IS DISTINCT FROM OLD.credential_ciphertext OR NEW.credential_encryption_key_version IS DISTINCT FROM OLD.credential_encryption_key_version OR NEW.credential_hmac IS DISTINCT FROM OLD.credential_hmac OR NEW.credential_hmac_key_version IS DISTINCT FROM OLD.credential_hmac_key_version OR NEW.probe_operation_id IS DISTINCT FROM OLD.probe_operation_id OR NEW.created_by<>OLD.created_by OR NEW.created_at<>OLD.created_at OR OLD.status<>'candidate' OR NEW.status NOT IN('active','rejected')) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='mcp_credential_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
