LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.schema_revision<>1 OR NEW.policy_revision<>1 OR NEW.status<>'review_required' OR NEW.created_by<>NEW.updated_by OR NEW.created_at<>NEW.updated_at OR NOT EXISTS(SELECT 1 FROM mcp_servers server JOIN users actor ON actor.tenant_id=server.tenant_id WHERE server.tenant_id=NEW.tenant_id AND server.mcp_server_id=NEW.mcp_server_id AND actor.user_id=NEW.created_by AND actor.status='active') OR EXISTS(SELECT 1 FROM mcp_tools current WHERE current.mcp_tool_id=NEW.mcp_tool_id OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
