CREATE OR REPLACE FUNCTION "fn_trg_mcp_events_owner_insert_prd082"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS(SELECT 1 FROM mcp_invocations invocation WHERE invocation.tenant_id=NEW.tenant_id AND invocation.mcp_invocation_id=NEW.mcp_invocation_id AND invocation.mcp_server_id=NEW.mcp_server_id AND invocation.mcp_tool_id=NEW.mcp_tool_id AND invocation.status=NEW.status AND invocation.risk_level=NEW.risk_level AND invocation.approval_required=NEW.approval_required AND invocation.input_dlp_status=NEW.input_dlp_status AND invocation.input_dlp_match_count=NEW.input_dlp_match_count AND coalesce(invocation.output_dlp_status,'not_scanned')=NEW.output_dlp_status AND coalesce(invocation.output_dlp_match_count,0)=NEW.output_dlp_match_count AND coalesce(invocation.result_redaction_count,0)=NEW.redaction_count AND invocation.probe_attempt_count=NEW.probe_attempt_count AND invocation.call_attempt_count=NEW.call_attempt_count AND invocation.duration_ms=NEW.duration_ms AND invocation.request_bytes=NEW.request_bytes AND invocation.response_bytes IS NOT DISTINCT FROM NEW.response_bytes AND invocation.execution_status=NEW.execution_status AND invocation.invocation_count=NEW.invocation_count AND invocation.tool_call_count IS NOT DISTINCT FROM NEW.tool_call_count AND invocation.cost_status=NEW.cost_status AND invocation.error_code IS NOT DISTINCT FROM NEW.error_code AND invocation.completed_at=NEW.completed_at AND invocation.execution_status IN('called','unknown')) OR EXISTS(SELECT 1 FROM mcp_invocation_events current WHERE current.mcp_invocation_event_id=NEW.mcp_invocation_event_id OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='mcp_event_owner_mismatch';
  END IF;
  RETURN NEW;
