_code IS NULL AND NEW.subscription_snapshot_json IS NOT DISTINCT FROM OLD.subscription_snapshot_json AND NEW.snapshot_frozen_at IS NOT DISTINCT FROM OLD.snapshot_frozen_at) OR (OLD.status='processing' AND NEW.status IN('succeeded','failed') AND unixepoch(NEW.updated_at)<unixepoch(OLD.lease_expires_at) AND NEW.attempt_count=OLD.attempt_count AND NEW.subscription_snapshot_json IS NOT DISTINCT FROM OLD.subscription_snapshot_json AND NEW.snapshot_frozen_at IS NOT DISTINCT FROM OLD.snapshot_frozen_at) OR (OLD.status='processing' AND NEW.status='failed' AND OLD.attempt_count=10 AND NEW.attempt_count=OLD.attempt_count AND unixepoch(NEW.updated_at)>=unixepoch(OLD.lease_expires_at) AND NEW.error_code='webhook.delivery_unavailable' AND NEW.subscription_snapshot_json IS NOT DISTINCT FROM OLD.subscription_snapshot_json AND NEW.snapshot_frozen_at IS NOT DISTINCT FROM OLD.snapshot_frozen_at))) THEN
