CREATE OR REPLACE FUNCTION "fn_trg_approval_tasks_owner_insert_prd078"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.status<>'pending' OR NEW.state_revision<>1 OR NEW.writeback_status<>'pending' OR NEW.created_at<>NEW.updated_at OR NOT EXISTS(SELECT 1 FROM tenants tenant WHERE tenant.tenant_id=NEW.tenant_id AND tenant.status='active') OR (NEW.created_by_type='user' AND NOT EXISTS(SELECT 1 FROM users actor WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.created_by_id AND actor.status='active')) OR (NEW.target_type='budget_block_release' AND NOT EXISTS( SELECT 1 FROM budget_blocks block JOIN budget_rules rule ON rule.tenant_id=block.tenant_id AND rule.budget_rule_id=block.budget_rule_id WHERE block.tenant_id=NEW.tenant_id AND block.budget_block_id=NEW.source_id AND block.budget_rule_id=NEW.target_id AND block.status='active')) OR (NEW.target_type='session_risk_action' AND NOT EXISTS( SELECT 1 FROM session_risk_scores score WHERE score.tenant_id=NEW.tenant_id AND score.session_risk_score_id=NEW.target_id AND score.status IN('high_risk','frozen'))) OR (NEW.target_type='mcp_tool_invocation' AND ( NEW.mcp_invocation_id IS NULL OR NEW.mcp_invocation_id<>NEW.target_id OR NEW.source_id<>NEW.target_id OR NEW.created_by_type<>'user' OR (EXISTS(SELECT 1 FROM mcp_invocations invocation WHERE invocation.tenant_id=NEW.tenant_id AND invocation.mcp_invocation_id=NEW.mcp_invocation_id) AND NOT EXISTS(SELECT 1 FROM mcp_invocations invocation WHERE invocation.tenant_id=NEW.tenant_id AND invocation.mcp_invocation_id=NEW.mcp_invocation_id AND invocation.approval_task_id=NEW.approval_task_id AND invocation.requested_by=NEW.created_by_id AND invocation.status='approval_pending' AND CAST(invocation.server_state_revision AS TEXT)||':' ||CAST(invocation.credential_revision AS TEXT)||':' ||CAST(invocation.schema_revision AS TEXT)||':' ||CAST(invocation.policy_revision AS TEXT)=NEW.target_version AND invocation.policy_fingerprint=NEW.target_fingerprint AND invocation.risk_level='high' AND invocation.approval_required=1 AND invocation.approval_deadline_at=NEW.expires_at)))) OR EXISTS(SELECT 1 FROM approval_tasks current WHERE current.approval_task_id=NEW.approval_task_id OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='approval_task_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
