LL) OR (NEW.resolution_reason='timeout' AND NEW.decided_by_user_id IS NULL))))) OR (OLD.status='approved' AND NEW.status='approved' AND OLD.target_type='session_risk_action' AND OLD.writeback_status='pending' AND NEW.writeback_status IN('completed','failed') AND NEW.state_revision=OLD.state_revision AND NEW.resolution_reason=OLD.resolution_reason AND NEW.decided_by_user_id=OLD.decided_by_user_id AND NEW.decided_at=OLD.decided_at AND NEW.decision_request_id=OLD.decision_request_id AND NEW.decision_trace_id=OLD.decision_trace_id AND unixepoch(NEW.updated_at)>=unixepoch(OLD.updated_at)) )) THEN
