CREATE OR REPLACE FUNCTION "fn_trg_approval_decisions_owner_insert_prd078"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS( SELECT 1 FROM approval_tasks task WHERE task.tenant_id=NEW.tenant_id AND task.approval_task_id=NEW.approval_task_id AND task.state_revision=NEW.revision_after AND task.writeback_status=NEW.writeback_status AND task.decision_request_id=NEW.request_id AND task.decision_trace_id=NEW.trace_id AND task.decided_at=NEW.decided_at AND ((NEW.decision='approve' AND task.status='approved' AND task.resolution_reason='approved' AND NEW.actor_type='user' AND task.decided_by_user_id=NEW.actor_id) OR (NEW.decision='reject' AND task.status='rejected' AND task.resolution_reason='user_rejected' AND NEW.actor_type='user' AND task.decided_by_user_id=NEW.actor_id) OR (NEW.decision='timeout' AND task.status='rejected' AND task.resolution_reason='timeout' AND NEW.actor_type='system' AND task.decided_by_user_id IS NULL)) AND ((NEW.actor_type='system' AND task.risk_level IN('standard','high')) OR (NEW.actor_type='user' AND EXISTS(SELECT 1 FROM users actor WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.actor_id AND actor.status='active') AND NEW.step_up_used=CASE task.risk_level WHEN 'high' THEN 1 ELSE 0 END)) AND (task.target_type<>'mcp_tool_invocation' OR NEW.actor_type<>'user' OR NOT EXISTS(SELECT 1 FROM mcp_invocations invocation WHERE invocation.tenant_id=task.tenant_id AND invocation.mcp_invocation_id=task.mcp_invocation_id AND invocation.requested_by=NEW.actor_id)) ) OR EXISTS(SELECT 1 FROM approval_decisions current WHERE current.approval_decision_id=NEW.approval_decision_id OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='approval_decision_owner_mismatch';
