CREATE OR REPLACE FUNCTION "fn_trg_approval_writebacks_owner_insert_prd078"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.attempt_count<>0 OR NEW.lease_generation<>0 OR NEW.created_at<>NEW.updated_at OR NOT EXISTS(SELECT 1 FROM approval_tasks task JOIN approval_decisions decision ON decision.tenant_id=task.tenant_id AND decision.approval_task_id=task.approval_task_id WHERE task.tenant_id=NEW.tenant_id AND task.approval_task_id=NEW.approval_task_id AND decision.writeback_status=task.writeback_status AND ((decision.decision='approve' AND task.target_type='budget_block_release' AND NEW.adapter_kind='budget_block_release' AND NEW.status='completed' AND task.writeback_status='completed' AND NEW.completed_at=NEW.created_at) OR (decision.decision='approve' AND task.target_type='session_risk_action' AND NEW.adapter_kind='session_risk_store_sync' AND NEW.status='pending' AND task.writeback_status='pending' AND NEW.next_attempt_at=NEW.created_at AND EXISTS(SELECT 1 FROM session_risk_actions action WHERE action.tenant_id=NEW.tenant_id AND action.session_risk_action_id=NEW.target_fact_id AND action.session_risk_score_id=task.target_id AND action.state_revision=NEW.target_revision)) OR (decision.decision='approve' AND task.target_type='mcp_tool_invocation' AND NEW.adapter_kind='mcp_invocation_enqueue' AND NEW.status='completed' AND task.writeback_status='completed' AND NEW.completed_at=NEW.created_at AND NEW.target_fact_id=task.mcp_invocation_id AND EXISTS(SELECT 1 FROM mcp_invocations invocation WHERE invocation.tenant_id=task.tenant_id AND invocation.mcp_invocation_id=task.mcp_invocation_id AND invocation.status='queued' AND invocation.policy_revision=NEW.target_revision)) OR (decision.decision IN('reject','timeout') AND NEW.adapter_kind='no_effect' AND NEW.status='completed' AND task.writeback_status='completed' AND NEW.completed_at=NEW.created_at))) OR EXISTS(SELECT 1 FROM approval_writebacks current WHERE current.approval_writeback_id=NEW.approval_writeback_id OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='approval_writeback_owner_mismatch';
  END IF;
  RETURN NEW;
