$trigger$;
CREATE TRIGGER "trg_approval_writebacks_owner_insert_prd078" BEFORE INSERT ON "approval_writebacks" FOR EACH ROW EXECUTE FUNCTION "fn_trg_approval_writebacks_owner_insert_prd078"();
CREATE OR REPLACE FUNCTION "fn_trg_approval_writebacks_transition_prd078"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.approval_writeback_id<>OLD.approval_writeback_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.approval_task_id<>OLD.approval_task_id OR NEW.adapter_kind<>OLD.adapter_kind OR NEW.target_fact_id IS DISTINCT FROM OLD.target_fact_id OR NEW.target_revision IS DISTINCT FROM OLD.target_revision OR NEW.created_at<>OLD.created_at OR OLD.adapter_kind<>'session_risk_store_sync' OR NEW.lease_generation<>OLD.lease_generation+1 OR unixepoch(NEW.updated_at)<unixepoch(OLD.updated_at) OR NOT ( (OLD.status='pending' AND NEW.status='processing' AND NEW.attempt_count=OLD.attempt_count+1 AND NEW.lease_owner_id IS NOT NULL AND length(NEW.lease_owner_id) BETWEEN 1 AND 160 AND NEW.lease_token IS NOT NULL AND length(NEW.lease_token)=64 AND NEW.lease_token OPERATOR(public.!@@) '*[^0-9a-f]*' AND unixepoch(NEW.lease_expires_at)=unixepoch(NEW.updated_at)+90) OR (OLD.status='processing' AND NEW.status='processing' AND unixepoch(NEW.updated_at)>=unixepoch(OLD.lease_expires_at) AND NEW.attempt_count=OLD.attempt_count+1 AND NEW.lease_token<>OLD.lease_token AND NEW.lease_owner_id IS NOT NULL AND length(NEW.lease_owner_id) BETWEEN 1 AND 160 AND NEW.lease_token IS NOT NULL AND length(NEW.lease_token)=64 AND NEW.lease_token OPERATOR(public.!@@) '*[^0-9a-f]*' AND unixepoch(NEW.lease_expires_at)=unixepoch(NEW.updated_at)+90) OR (OLD.status='processing' AND NEW.status='pending' AND NEW.attempt_count=OLD.attempt_count AND NEW.attempt_count<10 AND NEW.last_error_code='approval.writeback_unavailable' AND unixepoch(NEW.next_attempt_at)=unixepoch(NEW.updated_at)+CASE NEW.attempt_count WHEN 1 THEN 5 WHEN 2 THEN 30 ELSE 300 END) OR (OLD.status='processing' AND NEW.status='completed' AND NEW.attempt_count=OLD.attempt_count AND NEW.completed_at=NEW.updated_at) OR (OLD.status='processing' AND NEW.status='failed' AND NEW.attempt_count=10 AND NEW.last_error_code='approval.writeback_unavailable') )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='approval_writeback_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
