CREATE OR REPLACE FUNCTION "fn_trg_mcp_operations_transition_prd082"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.mcp_server_operation_id<>OLD.mcp_server_operation_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.mcp_server_id<>OLD.mcp_server_id OR NEW.operation_type<>OLD.operation_type OR NEW.idempotency_key_hmac<>OLD.idempotency_key_hmac OR NEW.idempotency_key_hmac_version<>OLD.idempotency_key_hmac_version OR NEW.intent_hmac<>OLD.intent_hmac OR NEW.intent_hmac_version<>OLD.intent_hmac_version OR NEW.actor_user_id<>OLD.actor_user_id OR NEW.start_server_revision<>OLD.start_server_revision OR NEW.start_credential_revision IS DISTINCT FROM OLD.start_credential_revision OR NEW.candidate_credential_revision IS DISTINCT FROM OLD.candidate_credential_revision OR NEW.request_id<>OLD.request_id OR NEW.trace_id<>OLD.trace_id OR NEW.created_at<>OLD.created_at OR unixepoch(NEW.updated_at)<unixepoch(OLD.updated_at) OR NOT ((OLD.status='queued' AND NEW.status IN('processing','succeeded','failed')) OR (OLD.status='processing' AND NEW.status IN('succeeded','failed')))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='mcp_operation_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
