CREATE OR REPLACE FUNCTION "fn_trg_mcp_sync_jobs_owner_insert_prd082"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.attempt_count<>0 OR NEW.lease_generation<>0 OR NEW.created_at<>NEW.updated_at OR NEW.started_at IS NOT NULL OR NEW.completed_at IS NOT NULL OR NEW.error_code IS NOT NULL OR NOT ( (NEW.status='waiting_policy' AND NEW.next_attempt_at IS NULL AND NEW.deadline_at IS NULL AND NEW.lease_owner_id IS NULL AND NEW.lease_token IS NULL AND NEW.lease_expires_at IS NULL) OR (NEW.status='pending' AND NEW.next_attempt_at=NEW.created_at AND NEW.deadline_at IS NOT NULL AND NEW.lease_owner_id IS NULL AND NEW.lease_token IS NULL AND NEW.lease_expires_at IS NULL)) OR NOT EXISTS(SELECT 1 FROM mcp_server_operations operation WHERE operation.tenant_id=NEW.tenant_id AND operation.mcp_server_id=NEW.mcp_server_id AND operation.mcp_server_operation_id=NEW.mcp_server_operation_id AND operation.status='queued') OR EXISTS(SELECT 1 FROM mcp_server_sync_jobs current WHERE current.mcp_server_sync_job_id=NEW.mcp_server_sync_job_id OR (current.tenant_id=NEW.tenant_id AND current.mcp_server_id=NEW.mcp_server_id AND current.status IN('waiting_policy','pending','processing')) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='mcp_sync_job_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_mcp_sync_jobs_owner_insert_prd082" BEFORE INSERT ON "mcp_server_sync_jobs" FOR EACH ROW EXECUTE FUNCTION "fn_trg_mcp_sync_jobs_owner_insert_prd082"();
CREATE OR REPLACE FUNCTION "fn_trg_mcp_sync_jobs_transition_prd082"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.mcp_server_sync_job_id<>OLD.mcp_server_sync_job_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.mcp_server_id<>OLD.mcp_server_id OR NEW.mcp_server_operation_id<>OLD.mcp_server_operation_id OR NEW.candidate_credential_revision IS DISTINCT FROM OLD.candidate_credential_revision OR NEW.job_type<>OLD.job_type OR NEW.created_at<>OLD.created_at OR unixepoch(NEW.updated_at)<unixepoch(OLD.updated_at) OR NOT ( (OLD.status='waiting_policy' AND NEW.status='pending' AND OLD.attempt_count=0 AND NEW.attempt_count=0 AND OLD.lease_generation=0 AND NEW.lease_generation=0 AND OLD.deadline_at IS NULL AND NEW.deadline_at IS NOT NULL AND unixepoch(NEW.deadline_at)>unixepoch(NEW.updated_at) AND NEW.next_attempt_at=NEW.updated_at AND NEW.started_at IS NULL AND NEW.completed_at IS NULL AND NEW.error_code IS NULL AND NEW.lease_owner_id IS NULL AND NEW.lease_token IS NULL AND NEW.lease_expires_at IS NULL) OR (OLD.status='pending' AND NEW.status='processing' AND NEW.deadline_at=OLD.deadline_at AND NEW.lease_generation=OLD.lease_generation+1 AND NEW.attempt_count=OLD.attempt_count+1 AND NEW.started_at=NEW.updated_at AND unixepoch(NEW.updated_at)>=unixepoch(OLD.next_attempt_at) AND unixepoch(NEW.lease_expires_at)-unixepoch(NEW.updated_at) BETWEEN 30 AND 3600) OR (OLD.status='processing' AND NEW.status='processing' AND NEW.deadline_at=OLD.deadline_at AND NEW.lease_generation=OLD.lease_generation+1 AND unixepoch(NEW.updated_at)>=unixepoch(OLD.lease_expires_at) AND NEW.attempt_count=OLD.attempt_count+1 AND NEW.lease_token<>OLD.lease_token AND NEW.started_at IS NOT DISTINCT FROM OLD.started_at AND unixepoch(NEW.lease_expires_at)-unixepoch(NEW.updated_at) BETWEEN 30 AND 3600) OR (OLD.status='processing' AND NEW.status='pending' AND NEW.deadline_at=OLD.deadline_at AND NEW.lease_generation=OLD.lease_generation+1 AND unixepoch(NEW.updated_at)<unixepoch(OLD.lease_expires_at) AND NEW.attempt_count=OLD.attempt_count AND NEW.attempt_count<10 AND NEW.started_at IS NOT DISTINCT FROM OLD.started_at AND unixepoch(NEW.next_attempt_at)>=unixepoch(NEW.updated_at)) OR (OLD.status='processing' AND NEW.status IN('succeeded','failed') AND NEW.deadline_at=OLD.deadline_at AND NEW.lease_generation=OLD.lease_generation+1 AND unixepoch(NEW.updated_at)<unixepoch(OLD.lease_expires_at) AND NEW.attempt_count=OLD.attempt_count AND NEW.started_at IS NOT DISTINCT FROM OLD.started_at))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='mcp_sync_job_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
