CREATE OR REPLACE FUNCTION "fn_trg_mcp_invocations_owner_insert_prd082"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.state_revision<>1 OR NEW.created_at<>NEW.updated_at OR NEW.probe_attempt_count<>0 OR NEW.call_attempt_count<>0 OR NEW.status NOT IN('approval_pending','queued','blocked','failed') OR (NEW.status='approval_pending' AND (NEW.queued_at IS NOT NULL OR NEW.next_attempt_at IS NOT NULL OR NEW.completed_at IS NOT NULL)) OR (NEW.status='queued' AND (NEW.queued_at<>NEW.created_at OR NEW.next_attempt_at<>NEW.created_at OR NEW.completed_at IS NOT NULL)) OR (NEW.status IN('blocked','failed') AND NEW.completed_at<>NEW.created_at) OR NOT EXISTS(SELECT 1 FROM mcp_tools tool JOIN mcp_servers server ON server.tenant_id=tool.tenant_id AND server.mcp_server_id=tool.mcp_server_id JOIN mcp_server_credentials credential ON credential.tenant_id=server.tenant_id AND credential.mcp_server_id=server.mcp_server_id AND credential.credential_revision=server.active_credential_revision JOIN users actor ON actor.tenant_id=tool.tenant_id WHERE tool.tenant_id=NEW.tenant_id AND tool.mcp_server_id=NEW.mcp_server_id AND tool.mcp_tool_id=NEW.mcp_tool_id AND tool.status='active' AND server.status='active' AND server.state_revision=NEW.server_state_revision AND credential.credential_revision=NEW.credential_revision AND credential.status='active' AND actor.user_id=NEW.requested_by AND actor.status='active' AND tool.schema_revision=NEW.schema_revision AND tool.policy_revision=NEW.policy_revision AND tool.input_schema_original_sha256=NEW.input_schema_original_sha256 AND tool.input_schema_effective_sha256=NEW.input_schema_effective_sha256 AND tool.output_schema_original_sha256 IS NOT DISTINCT FROM NEW.output_schema_original_sha256 AND tool.output_schema_effective_sha256 IS NOT DISTINCT FROM NEW.output_schema_effective_sha256 AND tool.risk_level=NEW.risk_level AND tool.approval_required=NEW.approval_required AND tool.result_redaction_pointers_json=NEW.result_redaction_pointers_json) OR (NEW.approval_task_id IS NOT NULL AND EXISTS( SELECT 1 FROM approval_tasks task WHERE task.tenant_id=NEW.tenant_id AND task.approval_task_id=NEW.approval_task_id AND NOT (task.source_type='mcp' AND task.source_id=NEW.mcp_invocation_id AND task.target_type='mcp_tool_invocation' AND task.target_id=NEW.mcp_invocation_id AND task.target_action='invoke' AND task.target_reason_code IS NULL AND task.target_version=CAST(NEW.server_state_revision AS TEXT)||':' ||CAST(NEW.credential_revision AS TEXT)||':' ||CAST(NEW.schema_revision AS TEXT)||':' ||CAST(NEW.policy_revision AS TEXT) AND task.target_fingerprint=NEW.policy_fingerprint AND task.risk_level='high' AND task.status='pending' AND task.required_permission_code='mcp.approve' AND task.created_by_type='user' AND task.created_by_id=NEW.requested_by AND task.mcp_invocation_id=NEW.mcp_invocation_id AND task.expires_at=NEW.approval_deadline_at))) OR EXISTS(SELECT 1 FROM mcp_invocations current WHERE current.mcp_invocation_id=NEW.mcp_invocation_id OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='mcp_invocation_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_mcp_invocations_owner_insert_prd082" BEFORE INSERT ON "mcp_invocations" FOR EACH ROW EXECUTE FUNCTION "fn_trg_mcp_invocations_owner_insert_prd082"();
CREATE OR REPLACE FUNCTION "fn_trg_mcp_invocations_transition_prd082"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.mcp_invocation_id<>OLD.mcp_invocation_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.mcp_server_id<>OLD.mcp_server_id OR NEW.mcp_tool_id<>OLD.mcp_tool_id OR NEW.requested_by<>OLD.requested_by OR NEW.request_id<>OLD.request_id OR NEW.trace_id<>OLD.trace_id OR NEW.idempotency_key_hmac<>OLD.idempotency_key_hmac OR NEW.idempotency_key_hmac_version<>OLD.idempotency_key_hmac_version OR NEW.intent_hmac<>OLD.intent_hmac OR NEW.intent_hmac_version<>OLD.intent_hmac_version OR NEW.server_state_revision<>OLD.server_state_revision OR NEW.credential_revision<>OLD.credential_revision OR NEW.schema_revision<>OLD.schema_revision OR NEW.policy_revision<>OLD.policy_revision OR NEW.policy_fingerprint<>OLD.policy_fingerprint OR NEW.input_schema_original_sha256<>OLD.input_schema_original_sha256 OR NEW.input_schema_effective_sha256<>OLD.input_schema_effective_sha256 OR NEW.output_schema_original_sha256 IS DISTINCT FROM OLD.output_schema_original_sha256 OR NEW.output_schema_effective_sha256 IS DISTINCT FROM OLD.output_schema_effective_sha256 OR NEW.risk_level<>OLD.risk_level OR NEW.approval_required<>OLD.approval_required OR NEW.required_permissions_sha256<>OLD.required_permissions_sha256 OR NEW.grant_sha256<>OLD.grant_sha256 OR NEW.result_redaction_pointers_json<>OLD.result_redaction_pointers_json OR NEW.arguments_ciphertext<>OLD.arguments_ciphertext OR NEW.arguments_encryption_key_version<>OLD.arguments_encryption_key_version OR NEW.arguments_bytes<>OLD.arguments_bytes OR NEW.arguments_hmac<>OLD.arguments_hmac OR NEW.arguments_hmac_key_version<>OLD.arguments_hmac_key_version OR NEW.approval_task_id IS DISTINCT FROM OLD.approval_task_id OR NEW.approval_deadline_at IS DISTINCT FROM OLD.approval_deadline_at OR (NEW.request_bytes IS DISTINCT FROM OLD.request_bytes AND NOT (OLD.status='calling' AND NEW.status IN('succeeded','failed','blocked'))) OR NEW.invocation_count<>OLD.invocation_count OR NEW.cost_micros IS DISTINCT FROM OLD.cost_micros OR NEW.created_at<>OLD.created_at OR NEW.state_revision<>OLD.state_revision+1 OR unixepoch(NEW.updated_at)<unixepoch(OLD.updated_at) OR NEW.probe_attempt_count<OLD.probe_attempt_count OR NEW.probe_attempt_count>OLD.probe_attempt_count+1 OR NEW.call_attempt_count<OLD.call_attempt_count OR NEW.call_attempt_count>OLD.call_attempt_count+1 OR ((OLD.status IN('queued','probing') AND NEW.status='probing') AND (NEW.probe_attempt_count<>OLD.probe_attempt_count+1 OR NEW.lease_generation<>OLD.lease_generation+1 OR unixepoch(NEW.lease_expires_at)-unixepoch(NEW.updated_at) NOT BETWEEN 30 AND 3600 OR (OLD.status='queued' AND unixepoch(NEW.updated_at)<unixepoch(OLD.next_attempt_at)) OR (OLD.status='probing' AND (unixepoch(NEW.updated_at)<unixepoch(OLD.lease_expires_at) OR NEW.lease_token=OLD.lease_token)))) OR (NOT (OLD.status IN('queued','probing') AND NEW.status='probing') AND NEW.probe_attempt_count<>OLD.probe_attempt_count) OR NOT ( (OLD.status='approval_pending' AND NEW.status IN('queued','rejected') AND NEW.lease_generation=OLD.lease_generation) OR (OLD.status='queued' AND NEW.status IN('blocked','failed') AND NEW.lease_generation=OLD.lease_generation) OR (OLD.status='queued' AND NEW.status='probing' AND NEW.lease_generation=OLD.lease_generation+1) OR (OLD.status='probing' AND NEW.status IN( 'probing','queued','calling','blocked','failed') AND NEW.lease_generation=OLD.lease_generation+1) OR (OLD.status='calling' AND NEW.status IN( 'succeeded','failed','blocked','outcome_unknown') AND NEW.lease_generation=OLD.lease_generation+1)) OR ((OLD.status='probing' AND NEW.status='calling') AND (NEW.call_attempt_count<>OLD.call_attempt_count+1 OR unixepoch(NEW.updated_at)>=unixepoch(OLD.lease_expires_at) OR NEW.lease_owner_id<>OLD.lease_owner_id OR NEW.lease_token=OLD.lease_token OR unixepoch(NEW.lease_expires_at)-unixepoch(NEW.updated_at) NOT BETWEEN 30 AND 3600 OR NEW.execution_status<>'unknown' OR NEW.tool_call_count IS NOT NULL OR NEW.cost_status<>'unknown' OR NEW.call_started_at<>NEW.updated_at OR NEW.response_bytes IS DISTINCT FROM OLD.response_bytes OR NEW.duration_ms IS DISTINCT FROM OLD.duration_ms OR NEW.error_code IS DISTINCT FROM OLD.error_code)) OR (NOT (OLD.status='probing' AND NEW.status='calling') AND NEW.call_attempt_count<>OLD.call_attempt_count) OR ((NEW.input_dlp_status<>OLD.input_dlp_status OR NEW.input_dlp_match_count<>OLD.input_dlp_match_count OR NEW.input_dlp_rule_id IS DISTINCT FROM OLD.input_dlp_rule_id OR NEW.input_dlp_ruleset_hmac<>OLD.input_dlp_ruleset_hmac OR NEW.input_dlp_ruleset_hmac_key_version<>OLD.input_dlp_ruleset_hmac_key_version OR NEW.input_dlp_scanned_at<>OLD.input_dlp_scanned_at) AND NOT (OLD.status IN('queued','probing') AND NEW.status IN('probing','calling','blocked','failed') AND unixepoch(NEW.input_dlp_scanned_at)>=unixepoch(OLD.input_dlp_scanned_at))) OR ((NEW.output_dlp_status IS DISTINCT FROM OLD.output_dlp_status OR NEW.output_dlp_match_count IS DISTINCT FROM OLD.output_dlp_match_count OR NEW.output_dlp_rule_id IS DISTINCT FROM OLD.output_dlp_rule_id OR NEW.output_dlp_ruleset_hmac IS DISTINCT FROM OLD.output_dlp_ruleset_hmac OR NEW.output_dlp_ruleset_hmac_key_version IS DISTINCT FROM OLD.output_dlp_ruleset_hmac_key_version OR NEW.output_dlp_scanned_at IS DISTINCT FROM OLD.output_dlp_scanned_at OR NEW.result_ciphertext IS DISTINCT FROM OLD.result_ciphertext OR NEW.result_encryption_key_version IS DISTINCT FROM OLD.result_encryption_key_version OR NEW.result_hmac IS DISTINCT FROM OLD.result_hmac OR NEW.result_hmac_key_version IS DISTINCT FROM OLD.result_hmac_key_version OR NEW.result_bytes IS DISTINCT FROM OLD.result_bytes OR NEW.result_redaction_count IS DISTINCT FROM OLD.result_redaction_count) AND NOT (OLD.status='calling' AND NEW.status IN( 'succeeded','failed','blocked','outcome_unknown'))) OR (NEW.queued_at IS DISTINCT FROM OLD.queued_at AND NOT (OLD.status='approval_pending' AND NEW.status='queued' AND NEW.queued_at=NEW.updated_at)) OR (NEW.started_at IS DISTINCT FROM OLD.started_at AND NOT (OLD.status='queued' AND NEW.status='probing' AND NEW.started_at=NEW.updated_at)) OR (NEW.call_started_at IS DISTINCT FROM OLD.call_started_at AND NOT (OLD.status='probing' AND NEW.status='calling' AND NEW.call_started_at=NEW.updated_at)) OR (NEW.completed_at IS DISTINCT FROM OLD.completed_at AND NOT (NEW.status IN('succeeded','failed','blocked','rejected','outcome_unknown') AND NEW.completed_at=NEW.updated_at)) OR ((NEW.response_bytes IS DISTINCT FROM OLD.response_bytes OR NEW.duration_ms IS DISTINCT FROM OLD.duration_ms OR NEW.execution_status<>OLD.execution_status OR NEW.tool_call_count IS DISTINCT FROM OLD.tool_call_count OR NEW.cost_status<>OLD.cost_status OR NEW.error_code IS DISTINCT FROM OLD.error_code) AND NOT (NEW.status IN('succeeded','failed','blocked','rejected','outcome_unknown') OR (OLD.status='probing' AND NEW.status='calling'))) OR (OLD.status<>'calling' AND NEW.status IN('blocked','failed','rejected') AND (NEW.execution_status<>'not_called' OR NEW.tool_call_count<>0 OR NEW.cost_status<>'not_applicable' OR NEW.call_attempt_count<>0 OR NEW.call_started_at IS NOT NULL OR NEW.error_code IS NULL)) OR (NEW.status='blocked' AND OLD.status<>'calling' AND NOT ((NEW.error_code='mcp.arguments_blocked' AND NEW.input_dlp_status='blocked') OR (NEW.error_code='mcp.network_blocked' AND NEW.input_dlp_status IN('clean','log_only')))) OR (NEW.status='failed' AND OLD.status<>'calling' AND NEW.error_code NOT IN('mcp.executor_disabled','mcp.authorization_revoked', 'mcp.server_unavailable','mcp.state_conflict','mcp.unavailable', 'mcp.sandbox_unavailable')) OR (NEW.status='probing' AND NEW.input_dlp_status NOT IN('clean','log_only')) OR (NEW.status='failed' AND NEW.input_dlp_status='unavailable' AND NEW.error_code<>'mcp.unavailable') OR (OLD.status='approval_pending' AND NEW.status='queued' AND NEW.next_attempt_at<>NEW.updated_at) OR (OLD.status IN('queued','probing') AND NEW.status='probing' AND NEW.next_attempt_at IS NOT NULL) OR (OLD.status='probing' AND NEW.status='queued' AND (NEW.next_attempt_at IS NULL OR unixepoch(NEW.next_attempt_at)<unixepoch(NEW.updated_at) OR unixepoch(NEW.updated_at)>=unixepoch(OLD.lease_expires_at))) OR (OLD.status='probing' AND NEW.status='calling' AND NEW.next_attempt_at IS NOT NULL) OR (OLD.status='probing' AND NEW.status IN('blocked','failed') AND NOT (unixepoch(NEW.updated_at)<unixepoch(OLD.lease_expires_at) OR (NEW.status='failed' AND OLD.probe_attempt_count>=4 AND NEW.error_code='mcp.server_unavailable' AND unixepoch(NEW.updated_at)>=unixepoch(OLD.lease_expires_at)))) OR (OLD.status='calling' AND NEW.status IN('succeeded','failed','blocked') AND (unixepoch(NEW.updated_at)>=unixepoch(OLD.lease_expires_at) OR NEW.execution_status<>'called' OR NEW.tool_call_count<>1 OR NEW.cost_status<>'not_reported')) OR (OLD.status='calling' AND NEW.status='failed' AND NEW.error_code IS NULL) OR NOT ((OLD.status='approval_pending' AND NEW.status IN('queued','rejected')) OR (OLD.status='queued' AND NEW.status IN('probing','blocked','failed')) OR (OLD.status='probing' AND NEW.status IN( 'probing','queued','calling','blocked','failed')) OR (OLD.status='calling' AND NEW.status IN( 'succeeded','failed','blocked','outcome_unknown')))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='mcp_invocation_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
