CREATE OR REPLACE FUNCTION "fn_trg_mcp_attempts_owner_insert_prd082"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.status<>'processing' OR NEW.error_code IS NOT NULL OR NEW.completed_at IS NOT NULL OR NEW.duration_ms IS NOT NULL OR NEW.response_bytes IS NOT NULL OR (NEW.attempt_kind='probe' AND NEW.request_bytes IS NOT NULL) OR (NEW.attempt_kind='call' AND NEW.request_bytes IS NULL) OR NOT EXISTS(SELECT 1 FROM mcp_invocations invocation WHERE invocation.tenant_id=NEW.tenant_id AND invocation.mcp_invocation_id=NEW.mcp_invocation_id AND invocation.lease_generation=NEW.lease_generation AND ((NEW.attempt_kind='probe' AND invocation.status='probing' AND NEW.attempt_number=invocation.probe_attempt_count) OR (NEW.attempt_kind='call' AND invocation.status='calling' AND NEW.attempt_number=invocation.call_attempt_count))) OR EXISTS(SELECT 1 FROM mcp_invocation_attempts current WHERE current.mcp_invocation_attempt_id=NEW.mcp_invocation_attempt_id OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='mcp_attempt_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_mcp_attempts_owner_insert_prd082" BEFORE INSERT ON "mcp_invocation_attempts" FOR EACH ROW EXECUTE FUNCTION "fn_trg_mcp_attempts_owner_insert_prd082"();
CREATE OR REPLACE FUNCTION "fn_trg_mcp_attempts_transition_prd082"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.mcp_invocation_attempt_id<>OLD.mcp_invocation_attempt_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.mcp_invocation_id<>OLD.mcp_invocation_id OR NEW.attempt_kind<>OLD.attempt_kind OR NEW.attempt_number<>OLD.attempt_number OR NEW.lease_generation<>OLD.lease_generation OR NEW.started_at<>OLD.started_at OR NEW.call_started_at IS DISTINCT FROM OLD.call_started_at OR (NEW.attempt_kind='call' AND NEW.request_bytes IS NULL) OR (NEW.attempt_kind='probe' AND OLD.request_bytes IS NOT NULL AND NEW.request_bytes IS DISTINCT FROM OLD.request_bytes) OR (NEW.attempt_kind='probe' AND NEW.status='outcome_unknown') OR (NEW.attempt_kind='probe' AND NEW.status='failed' AND NEW.error_code NOT IN('mcp.executor_disabled','mcp.arguments_blocked', 'mcp.authorization_revoked','mcp.server_unavailable','mcp.state_conflict', 'mcp.unavailable','mcp.network_blocked','mcp.sandbox_unavailable')) OR (NEW.attempt_kind='call' AND NEW.status IN('failed','outcome_unknown') AND NEW.error_code NOT IN('mcp.tool_failed','mcp.result_blocked', 'mcp.output_dlp_unavailable','mcp.result_invalid','mcp.outcome_unknown', 'mcp.state_conflict','mcp.unavailable')) OR (NEW.status='outcome_unknown' AND NEW.error_code<>'mcp.outcome_unknown') OR NOT EXISTS( SELECT 1 FROM mcp_invocations invocation WHERE invocation.tenant_id=OLD.tenant_id AND invocation.mcp_invocation_id=OLD.mcp_invocation_id AND invocation.lease_generation=OLD.lease_generation AND invocation.lease_owner_id IS NOT NULL AND invocation.lease_token IS NOT NULL AND unixepoch(NEW.completed_at)>=unixepoch(invocation.updated_at) AND ((OLD.attempt_kind='probe' AND invocation.status='probing' AND invocation.probe_attempt_count=OLD.attempt_number) OR (OLD.attempt_kind='call' AND invocation.status='calling' AND invocation.call_attempt_count=OLD.attempt_number)) AND ( unixepoch(NEW.completed_at)<unixepoch(invocation.lease_expires_at) OR (unixepoch(NEW.completed_at)>=unixepoch(invocation.lease_expires_at) AND ((OLD.attempt_kind='probe' AND NEW.status='failed' AND NEW.error_code='mcp.server_unavailable') OR (OLD.attempt_kind='call' AND NEW.status='outcome_unknown' AND NEW.error_code='mcp.outcome_unknown'))))) OR OLD.status<>'processing' OR NEW.status NOT IN('succeeded','failed','outcome_unknown')) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='mcp_attempt_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
