nixepoch(NEW.updated_at)<unixepoch(OLD.half_open_lease_expires_at) AND NOT ( (OLD.half_open_owner_type='operation' AND EXISTS( SELECT 1 FROM mcp_server_operations operation JOIN mcp_server_sync_jobs job ON job.tenant_id=operation.tenant_id AND job.mcp_server_id=operation.mcp_server_id AND job.mcp_server_operation_id=operation.mcp_server_operation_id WHERE operation.tenant_id=OLD.tenant_id AND operation.mcp_server_id=OLD.mcp_server_id AND operation.mcp_server_operation_id=OLD.half_open_owner_id AND operation.status='processing' AND job.status='processing' AND job.lease_generation=OLD.half_open_lease_generation AND job.lease_owner_id=OLD.half_open_lease_owner_id AND job.lease_token=OLD.half_open_lease_token AND job.lease_expires_at=OLD.half_open_lease_expires_at)) OR (OLD.half_open_owner_type='invocation' AND EXISTS( SELECT 1 FROM mcp_invocations invocation WHERE invocation.tenant_id=OLD.tenant_id AND invocation.mcp_server_id=OLD.mcp_server_id AND invocation.mcp_invocation_id=OLD.half_open_owner_id AND invocation.status IN('probing','calling') AND invocation.lease_generation=OLD.half_open_lease_generation AND invocation.lease_owner_id=OLD.half_open_lease_owner_id AND invocation.lease_token=OLD.half_open_lease_token AND invocation.lease_expires_at=OLD.half_open_lease_expires_at)))) OR NOT ((OLD.state='closed' AND NEW.state IN('closed','open')) OR (OLD.state='open' AND NEW.state IN('open','half_open')) OR (OLD.state='half_open' AND NEW.state IN('closed','open')))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='mcp_network_circuit_transition_invalid';
  END IF;
  RETURN NEW;
END;
