CREATE OR REPLACE FUNCTION "fn_trg_mcp_network_events_owner_insert_prd083"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS(SELECT 1 FROM mcp_network_decisions decision WHERE decision.tenant_id=NEW.tenant_id AND decision.mcp_network_decision_id=NEW.mcp_network_decision_id AND decision.mcp_server_id=NEW.mcp_server_id AND decision.mcp_server_operation_id IS NOT DISTINCT FROM NEW.mcp_server_operation_id AND decision.mcp_invocation_id IS NOT DISTINCT FROM NEW.mcp_invocation_id AND decision.phase=NEW.phase AND decision.result='blocked' AND decision.reason_code=NEW.reason_code AND decision.policy_revision=NEW.policy_revision AND decision.address_count=NEW.address_count AND decision.attempt_number=NEW.attempt_number AND decision.request_id=NEW.request_id AND decision.trace_id=NEW.trace_id AND decision.created_at=NEW.occurred_at) OR (NEW.mcp_invocation_id IS NOT NULL AND ( EXISTS(SELECT 1 FROM mcp_network_call_intents intent WHERE intent.tenant_id=NEW.tenant_id AND intent.mcp_invocation_id=NEW.mcp_invocation_id) OR EXISTS(SELECT 1 FROM mcp_invocation_events event WHERE event.tenant_id=NEW.tenant_id AND event.mcp_invocation_id=NEW.mcp_invocation_id) OR NOT EXISTS(SELECT 1 FROM mcp_invocations invocation WHERE invocation.tenant_id=NEW.tenant_id AND invocation.mcp_invocation_id=NEW.mcp_invocation_id AND invocation.status='blocked' AND invocation.error_code='mcp.network_blocked' AND invocation.execution_status='not_called' AND invocation.tool_call_count=0 AND invocation.cost_status='not_applicable'))) OR (NEW.mcp_server_operation_id IS NOT NULL AND NOT EXISTS( SELECT 1 FROM mcp_server_operations operation WHERE operation.tenant_id=NEW.tenant_id AND operation.mcp_server_operation_id=NEW.mcp_server_operation_id AND operation.status='failed' AND operation.error_code='mcp.network_blocked')) OR EXISTS(SELECT 1 FROM mcp_network_events current WHERE current.mcp_network_event_id=NEW.mcp_network_event_id OR (current.tenant_id=NEW.tenant_id AND current.mcp_network_decision_id=NEW.mcp_network_decision_id) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='mcp_network_event_owner_mismatch';
  END IF;
  RETURN NEW;
END;
