CREATE OR REPLACE FUNCTION "fn_trg_mcp_network_event_outbox_owner_insert_prd083"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.status<>'pending' OR NEW.attempt_count<>0 OR NEW.lease_generation<>0 OR NEW.lease_owner_id IS NOT NULL OR NEW.lease_token IS NOT NULL OR NEW.lease_expires_at IS NOT NULL OR NEW.next_attempt_at<>NEW.created_at OR NEW.error_code IS NOT NULL OR NEW.delivered_at IS NOT NULL OR NEW.created_at<>NEW.updated_at OR (NEW.subscription_snapshot_json IS NOT NULL AND NEW.snapshot_frozen_at<>NEW.created_at) OR NOT EXISTS(SELECT 1 FROM mcp_network_events event WHERE event.tenant_id=NEW.tenant_id AND event.mcp_network_event_id=NEW.mcp_network_event_id AND event.occurred_at=NEW.created_at) OR EXISTS(SELECT 1 FROM mcp_network_event_outbox current WHERE current.mcp_network_event_outbox_id=NEW.mcp_network_event_outbox_id OR (current.tenant_id=NEW.tenant_id AND current.mcp_network_event_id=NEW.mcp_network_event_id) OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
