CREATE OR REPLACE FUNCTION "fn_trg_mcp_network_event_outbox_transition_prd083"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.mcp_network_event_outbox_id<>OLD.mcp_network_event_outbox_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.mcp_network_event_id<>OLD.mcp_network_event_id OR NEW.created_at<>OLD.created_at OR NEW.lease_generation<>OLD.lease_generation+1 OR unixepoch(NEW.updated_at)<unixepoch(OLD.updated_at) OR (OLD.subscription_snapshot_json IS NOT NULL AND (NEW.subscription_snapshot_json IS DISTINCT FROM OLD.subscription_snapshot_json OR NEW.snapshot_frozen_at IS DISTINCT FROM OLD.snapshot_frozen_at)) OR NOT ((OLD.status='pending' AND NEW.status='processing' AND NEW.attempt_count=OLD.attempt_count+1 AND unixepoch(NEW.updated_at)>=unixepoch(OLD.next_attempt_at) AND NEW.subscription_snapshot_json IS NOT DISTINCT FROM OLD.subscription_snapshot_json AND NEW.snapshot_frozen_at IS NOT DISTINCT FROM OLD.snapshot_frozen_at) OR (OLD.status='processing' AND NEW.status='processing' AND unixepoch(NEW.updated_at)>=unixepoch(OLD.lease_expires_at) AND NEW.attempt_count=OLD.attempt_count+1 AND NEW.lease_token<>OLD.lease_token AND NEW.subscription_snapshot_json IS NOT DISTINCT FROM OLD.subscription_snapshot_json AND NEW.snapshot_frozen_at IS NOT DISTINCT FROM OLD.snapshot_frozen_at) OR (OLD.status='processing' AND NEW.status='processing' AND unixepoch(NEW.updated_at)<unixepoch(OLD.lease_expires_at) AND NEW.attempt_count=OLD.attempt_count AND NEW.lease_owner_id=OLD.lease_owner_id AND NEW.lease_token<>OLD.lease_token AND unixepoch(NEW.lease_expires_at)>=unixepoch(OLD.lease_expires_at) AND ((OLD.subscription_snapshot_json IS NULL AND NEW.subscription_snapshot_json IS NOT NULL AND NEW.snapshot_frozen_at=NEW.updated_at) OR (NEW.subscription_snapshot_json IS NOT DISTINCT FROM OLD.subscription_snapshot_json AND NEW.snapshot_frozen_at IS NOT DISTINCT FROM OLD.snapshot_frozen_at))) OR (OLD.status='processing' AND NEW.status='pending' AND unixepoch(NEW.updated_at)<unixepoch(OLD.lease_expires_at) AND NEW.attempt_count=OLD.attempt_count AND NEW.attempt_count<10 AND unixepoch(NEW.next_attempt_at)>=unixepoch(NEW.updated_at) AND NEW.error_code IS NULL AND NEW.subscription_snapshot_json IS NOT DISTINCT FROM OLD.subscription_snapshot_json AND NEW.snapshot_frozen_at IS NOT DISTINCT FROM OLD.snapshot_frozen_at) OR (OLD.status='processing' AND NEW.status IN('succeeded','failed') AND unixepoch(NEW.updated_at)<unixepoch(OLD.lease_expires_at) AND NEW.attempt_count=OLD.attempt_count AND NEW.subscription_snapshot_json IS NOT DISTINCT FROM OLD.subscription_snapshot_json AND NEW.snapshot_frozen_at IS NOT DISTINCT FROM OLD.snapshot_frozen_at) OR (OLD.status='processing' AND NEW.status='failed' AND OLD.attempt_count=10 AND NEW.attempt_count=OLD.attempt_count AND unixepoch(NEW.updated_at)>=unixepoch(OLD.lease_expires_at) AND NEW.error_code='webhook.delivery_unavailable' AND NEW.subscription_snapshot_json IS NOT DISTINCT FROM OLD.subscription_snapshot_json AND NEW.snapshot_frozen_at IS NOT DISTINCT FROM OLD.snapshot_frozen_at))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='mcp_network_outbox_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
