CREATE OR REPLACE FUNCTION "fn_trg_audit_logs_admin_assistant_owner_insert_prd077"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (( NEW.action='admin_assistant.queried' AND ( NEW.object_type<>'assistant_query' OR NEW.object_name IS NOT NULL OR NEW.before_summary_json<>'{}' OR NOT EXISTS( SELECT 1 FROM assistant_audits assistant_audit JOIN assistant_queries query ON query.tenant_id=assistant_audit.tenant_id AND query.assistant_query_id=assistant_audit.assistant_query_id JOIN users actor ON actor.tenant_id=assistant_audit.tenant_id AND actor.user_id=assistant_audit.actor_user_id WHERE assistant_audit.tenant_id=NEW.tenant_id AND assistant_audit.assistant_query_id=NEW.object_id AND assistant_audit.audit_log_id=NEW.audit_log_id AND assistant_audit.actor_user_id=NEW.actor_user_id AND actor.email=NEW.actor_email AND actor.role=NEW.actor_role AND assistant_audit.operation_request_id=NEW.request_id AND assistant_audit.operation_trace_id=NEW.trace_id AND assistant_audit.created_at=NEW.created_at AND query.query_type=json_extract(NEW.after_summary_json,'$.query_type') AND query.outcome=json_extract(NEW.after_summary_json,'$.outcome') AND query.claim_count=(json_extract(NEW.after_summary_json,'$.claim_count'))::NUMERIC AND query.source_count=(json_extract(NEW.after_summary_json,'$.source_count'))::NUMERIC AND query.redaction_count =(json_extract(NEW.after_summary_json,'$.redaction_count'))::NUMERIC AND query.execution_mode =json_extract(NEW.after_summary_json,'$.execution_mode') AND query.model_call_count =(json_extract(NEW.after_summary_json,'$.model_call_count'))::NUMERIC AND query.model_cost_status =json_extract(NEW.after_summary_json,'$.model_cost_status') AND (SELECT COUNT(*) FROM json_each(NEW.after_summary_json))=8 AND NOT EXISTS( SELECT 1 FROM json_each(NEW.after_summary_json) field WHERE field.key NOT IN( 'query_type','outcome','claim_count','source_count', 'redaction_count','execution_mode','model_call_count', 'model_cost_status' ) ) AND json_type(NEW.after_summary_json,'$.query_type')='text' AND json_type(NEW.after_summary_json,'$.outcome')='text' AND json_type(NEW.after_summary_json,'$.claim_count')='integer' AND json_type(NEW.after_summary_json,'$.source_count')='integer' AND json_type(NEW.after_summary_json,'$.redaction_count')='integer' AND json_type(NEW.after_summary_json,'$.execution_mode')='text' AND json_type(NEW.after_summary_json,'$.model_call_count')='integer' AND json_type(NEW.after_summary_json,'$.model_cost_status')='text' AND metahub_json(NEW.changed_fields_json)=metahub_json( '["claim_count","execution_mode","model_call_count",' || '"model_cost_status","outcome","query_type","redaction_count",' || '"source_count"]' ) ) ) ) OR ( NEW.object_type='assistant_query' AND NEW.action<>'admin_assistant.queried' )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='audit_log_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
