CREATE OR REPLACE FUNCTION "fn_trg_audit_logs_billing_dispute_owner_insert_prd080"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (( NEW.action IN('billing_dispute.created','billing_dispute.review_started', 'billing_dispute.approved','billing_dispute.rejected','billing_dispute.cancelled') AND ( NEW.object_type<>'billing_dispute' OR NEW.object_name IS NOT NULL OR NOT EXISTS( SELECT 1 FROM billing_disputes dispute JOIN billing_dispute_transitions transition ON transition.tenant_id=dispute.tenant_id AND transition.billing_dispute_id=dispute.billing_dispute_id WHERE dispute.tenant_id=NEW.tenant_id AND dispute.billing_dispute_id=NEW.object_id AND transition.action=CASE NEW.action WHEN 'billing_dispute.created' THEN 'create' WHEN 'billing_dispute.review_started' THEN 'start_review' WHEN 'billing_dispute.approved' THEN 'approve' WHEN 'billing_dispute.rejected' THEN 'reject' ELSE 'cancel' END AND transition.actor_user_id=NEW.actor_user_id AND transition.operation_request_id=NEW.request_id AND transition.operation_trace_id=NEW.trace_id AND transition.to_status=dispute.status AND transition.new_revision=dispute.state_revision AND ((transition.action='create' AND NEW.before_summary_json='{}') OR (transition.action<>'create' AND (SELECT COUNT(*) FROM json_each(NEW.before_summary_json))=7 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.before_summary_json) field WHERE field.key NOT IN('status','state_revision','scope_type','item_count', 'adjustment_count','currency_totals_sha256','reason_sha256')) AND json_extract(NEW.before_summary_json,'$.status')=transition.from_status AND (json_extract(NEW.before_summary_json,'$.state_revision'))::NUMERIC =transition.expected_revision AND json_extract(NEW.before_summary_json,'$.scope_type')=dispute.scope_type AND (json_extract(NEW.before_summary_json,'$.item_count'))::NUMERIC=dispute.item_count AND (json_extract(NEW.before_summary_json,'$.adjustment_count'))::NUMERIC=0 AND json_extract(NEW.before_summary_json,'$.currency_totals_sha256') =metahub_sha256('{}') AND json_extract(NEW.before_summary_json,'$.reason_sha256') =dispute.reason_sha256)) AND (SELECT COUNT(*) FROM json_each(NEW.after_summary_json))=7 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.after_summary_json) field WHERE field.key NOT IN('status','state_revision','scope_type','item_count', 'adjustment_count','currency_totals_sha256','reason_sha256')) AND json_extract(NEW.after_summary_json,'$.status')=dispute.status AND (json_extract(NEW.after_summary_json,'$.state_revision'))::NUMERIC=dispute.state_revision AND json_extract(NEW.after_summary_json,'$.scope_type')=dispute.scope_type AND (json_extract(NEW.after_summary_json,'$.item_count'))::NUMERIC=dispute.item_count AND (json_extract(NEW.after_summary_json,'$.adjustment_count'))::NUMERIC =transition.approved_item_count AND json_extract(NEW.after_summary_json,'$.currency_totals_sha256')= CASE transition.action WHEN 'create' THEN ( SELECT metahub_sha256(json_extract(event.payload_json,'$.currency_totals')) FROM billing_dispute_events event WHERE event.tenant_id=dispute.tenant_id AND event.billing_dispute_id=dispute.billing_dispute_id AND event.event_type='billing_dispute.created') WHEN 'approve' THEN transition.approved_totals_sha256 ELSE metahub_sha256('{}') END AND json_extract(NEW.after_summary_json,'$.reason_sha256')=dispute.reason_sha256 AND NEW.changed_fields_json=CASE transition.action WHEN 'create' THEN '["adjustment_count","currency_totals_sha256","item_count","reason_sha256","scope_type","state_revision","status"]' WHEN 'approve' THEN '["adjustment_count","currency_totals_sha256","state_revision","status"]' ELSE '["state_revision","status"]' END AND (SELECT COUNT(*) FROM billing_dispute_adjustment_links link WHERE link.tenant_id=dispute.tenant_id AND link.billing_dispute_id=dispute.billing_dispute_id AND link.billing_dispute_transition_id=transition.billing_dispute_transition_id) =transition.approved_item_count AND ((transition.action IN('approve','reject','cancel') AND NOT EXISTS(SELECT 1 FROM billing_settlement_holds hold WHERE hold.tenant_id=dispute.tenant_id AND hold.billing_dispute_id=dispute.billing_dispute_id AND hold.status='active')) OR (transition.action IN('create','start_review') AND (SELECT COUNT(*) FROM billing_settlement_holds hold WHERE hold.tenant_id=dispute.tenant_id AND hold.billing_dispute_id=dispute.billing_dispute_id AND hold.status='active')=dispute.item_count)) ) ) ) OR (NEW.object_type='billing_dispute' AND NEW.action NOT IN( 'billing_dispute.created','billing_dispute.review_started','billing_dispute.approved', 'billing_dispute.rejected','billing_dispute.cancelled'))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='audit_log_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_audit_logs_billing_dispute_owner_insert_prd080" BEFORE INSERT ON "audit_logs" FOR EACH ROW EXECUTE FUNCTION "fn_trg_audit_logs_billing_dispute_owner_insert_prd080"();
