LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM users user_row WHERE user_row.user_id=NEW.actor_user_id AND user_row.tenant_id=NEW.tenant_id ) OR ( NEW.action='finops.adjustment_created' AND ( NEW.object_type<>'finops_adjustment' OR NOT EXISTS ( SELECT 1 FROM finops_adjustments adjustment WHERE adjustment.finops_adjustment_id=NEW.object_id AND adjustment.tenant_id=NEW.tenant_id AND adjustment.actor_user_id=NEW.actor_user_id ) ) ) OR (NEW.object_type='finops_adjustment' AND NEW.action<>'finops.adjustment_created') OR ( NEW.action IN ( 'cost_anomaly.acknowledged','cost_anomaly.dismissed', 'cost_anomaly.temporary_rate_limit_applied', 'cost_anomaly.temporary_rate_limit_released' ) AND ( NEW.object_type<>'cost_anomaly' OR NOT EXISTS ( SELECT 1 FROM cost_anomaly_actions action JOIN cost_anomalies anomaly ON anomaly.tenant_id=action.tenant_id AND anomaly.cost_anomaly_id=action.cost_anomaly_id WHERE action.tenant_id=NEW.tenant_id AND action.cost_anomaly_id=NEW.object_id AND action.actor_user_id=NEW.actor_user_id AND action.operation_request_id=NEW.request_id AND action.operation_trace_id=NEW.trace_id AND CASE action.action_type WHEN 'acknowledge' THEN 'cost_anomaly.acknowledged' WHEN 'dismiss' THEN 'cost_anomaly.dismissed' WHEN 'apply_temporary_rate_limit' THEN 'cost_anomaly.temporary_rate_limit_applied' WHEN 'release_temporary_rate_limit' THEN 'cost_anomaly.temporary_rate_limit_released' END=NEW.action ) ) ) OR ( NEW.object_type='cost_anomaly' AND NEW.action NOT IN ( 'cost_anomaly.acknowledged','cost_anomaly.dismissed', 'cost_anomaly.temporary_rate_limit_applied', 'cost_anomaly.temporary_rate_limit_released' ) ) OR ( NEW.action IN ('error_map.created','error_map.updated') AND ( NEW.object_type<>'provider_error_map' OR NOT EXISTS ( SELECT 1 FROM provider_error_map_events event JOIN provider_error_map_versions version ON version.tenant_id=event.tenant_id AND version.provider_error_map_version_id=event.provider_error_map_version_id JOIN provider_error_maps map ON map.tenant_id=event.tenant_id AND map.provider_error_map_id=event.provider_error_map_id AND map.current_version=event.rule_version WHERE event.tenant_id=NEW.tenant_id AND event.provider_error_map_id=NEW.object_id AND event.actor_user_id=NEW.actor_user_id AND event.request_id=NEW.request_id AND event.trace_id=NEW.trace_id AND ( (NEW.action='error_map.created' AND event.operation='create') OR (NEW.action='error_map.updated' AND event.operation IN ('update','enable','disable')) ) ) ) ) OR ( NEW.object_type='provider_error_map' AND NEW.action NOT IN ('error_map.created','error_map.updated') ) OR ( NEW.action='webhook_dead_letter.archived' AND ( NEW.object_type<>'webhook_dead_letter' OR NOT EXISTS ( SELECT 1 FROM webhook_dead_letter_events dead_letter WHERE dead_letter.tenant_id=NEW.tenant_id AND dead_letter.dead_letter_event_id=NEW.object_id AND dead_letter.status='archived' AND dead_letter.archived_by=NEW.actor_user_id ) ) ) OR ( NEW.object_type='webhook_dead_letter' AND NEW.action<>'webhook_dead_letter.archived' ) OR ( NEW.action='audit.exported' AND ( NEW.object_type<>'audit_export' OR NOT EXISTS ( SELECT 1 FROM audit_exports export WHERE export.tenant_id=NEW.tenant_id AND export.audit_export_id=NEW.object_id AND export.audit_log_id=NEW.audit_log_id AND export.requested_by=NEW.actor_user_id AND export.request_id=NEW.request_id AND export.trace_id=NEW.trace_id AND export.created_at=NEW.created_at ) ) ) OR (NEW.object_type='audit_export' AND NEW.action<>'audit.exported') OR ( EXISTS (SELECT 1 FROM audit_exports export WHERE export.audit_log_id=NEW.audit_log_id) AND NOT ( NEW.action='audit.exported' AND NEW.object_type='audit_export' AND EXISTS ( SELECT 1 FROM audit_exports export WHERE export.tenant_id=NEW.tenant_id AND export.audit_export_id=NEW.object_id AND export.audit_log_id=NEW.audit_log_id AND export.requested_by=NEW.actor_user_id AND export.request_id=NEW.request_id AND export.trace_id=NEW.trace_id AND export.created_at=NEW.created_at ) ) ) OR ( NEW.action='role.permission_changed' AND ( NEW.object_type<>'role_permission' OR NOT EXISTS ( SELECT 1 FROM roles role WHERE role.tenant_id=NEW.tenant_id AND role.role_id=NEW.object_id AND role.code<>'admin' AND role.status='active' AND role.permission_revision=(json_extract(NEW.after_summary_json,'$.permission_revision'))::NUMERIC AND role.matrix_sha256=json_extract(NEW.after_summary_json,'$.matrix_sha256') AND (json_extract(NEW.before_summary_json,'$.permission_revision'))::NUMERIC+1=role.permission_revision ) ) ) OR (NEW.object_type='role_permission' AND NEW.action<>'role.permission_changed') OR ( NEW.action='config.imported' AND ( NEW.object_type<>'config_transfer' OR NEW.object_name IS NOT NULL OR NOT EXISTS ( SELECT 1 FROM config_imports import_fact JOIN users actor ON actor.tenant_id=import_fact.tenant_id AND actor.user_id=import_fact.actor_user_id WHERE import_fact.tenant_id=NEW.tenant_id AND import_fact.config_import_id=NEW.object_id AND import_fact.actor_user_id=NEW.actor_user_id AND actor.email=NEW.actor_email AND actor.role=NEW.actor_role AND actor.status='active' AND import_fact.request_id=NEW.request_id AND import_fact.trace_id=NEW.trace_id AND import_fact.created_at=NEW.created_at AND (SELECT COUNT(*) FROM json_each(NEW.before_summary_json))=0 AND (SELECT COUNT(*) FROM json_each(NEW.after_summary_json))=12 AND NOT EXISTS ( SELECT 1 FROM json_each(NEW.after_summary_json) field WHERE field.key NOT IN ( 'schema_version','manifest_sha256', 'providers_created_count','providers_unchanged_count', 'models_created_count','models_unchanged_count', 'aliases_created_count','aliases_unchanged_count', 'virtual_keys_created_count','virtual_keys_unchanged_count', 'generated_virtual_key_count','disabled_virtual_key_count' ) ) AND json_extract(NEW.after_summary_json,'$.schema_version')=import_fact.schema_version AND json_extract(NEW.after_summary_json,'$.manifest_sha256')=import_fact.manifest_sha256 AND (json_extract(NEW.after_summary_json,'$.providers_created_count'))::NUMERIC =import_fact.providers_created_count AND (json_extract(NEW.after_summary_json,'$.providers_unchanged_count'))::NUMERIC =import_fact.providers_unchanged_count AND (json_extract(NEW.after_summary_json,'$.models_created_count'))::NUMERIC =import_fact.models_created_count AND (json_extract(NEW.after_summary_json,'$.models_unchanged_count'))::NUMERIC =import_fact.models_unchanged_count AND (json_extract(NEW.after_summary_json,'$.aliases_created_count'))::NUMERIC =import_fact.aliases_created_count AND (json_extract(NEW.after_summary_json,'$.aliases_unchanged_count'))::NUMERIC =import_fact.aliases_unchanged_count AND (json_extract(NEW.after_summary_json,'$.virtual_keys_created_count'))::NUMERIC =import_fact.virtual_keys_created_count AND (json_extract(NEW.after_summary_json,'$.virtual_keys_unchanged_count'))::NUMERIC =import_fact.virtual_keys_unchanged_count AND (json_extract(NEW.after_summary_json,'$.generated_virtual_key_count'))::NUMERIC =import_fact.generated_virtual_key_count AND (json_extract(NEW.after_summary_json,'$.disabled_virtual_key_count'))::NUMERIC =import_fact.disabled_virtual_key_count AND metahub_json(NEW.changed_fields_json)=metahub_json( '["aliases_created_count","aliases_unchanged_count",' || '"disabled_virtual_key_count","generated_virtual_key_count",' || '"manifest_sha256","models_created_count","models_unchanged_count",' || '"providers_created_count","providers_unchanged_count","schema_version",' || '"virtual_keys_created_count","virtual_keys_unchanged_count"]' ) AND (SELECT COUNT(*) FROM config_import_rows row_fact WHERE row_fact.tenant_id=import_fact.tenant_id AND row_fact.config_import_id=import_fact.config_import_id) =import_fact.providers_created_count+import_fact.providers_unchanged_count +import_fact.models_created_count+import_fact.models_unchanged_count +import_fact.aliases_created_count+import_fact.aliases_unchanged_count +import_fact.virtual_keys_created_count+import_fact.virtual_keys_unchanged_count ) ) ) OR ( NEW.action='config.exported' AND ( NEW.object_type<>'config_