N target_role.tenant_id=invitation.tenant_id AND target_role.code=invitation.role_code JOIN users actor ON actor.tenant_id=invitation.tenant_id AND actor.user_id=NEW.actor_user_id WHERE invitation.tenant_id=NEW.tenant_id AND invitation.invitation_id=NEW.object_id AND tenant.status='active' AND target_role.status='active' AND actor.role=NEW.actor_role AND actor.status='active' AND ( ( NEW.action='user_row.invited' AND NEW.actor_email=actor.email AND invitation.status='pending' AND invitation.invited_by=NEW.actor_user_id AND invitation.created_at=NEW.created_at AND (SELECT COUNT(*) FROM json_each(NEW.before_summary_json))=0 AND (SELECT COUNT(*) FROM json_each(NEW.after_summary_json))=5 AND NOT EXISTS ( SELECT 1 FROM json_each(NEW.after_summary_json) field WHERE field.key NOT IN ( 'email_fingerprint','role_code','status','expires_at','accepted_user_id' ) ) AND json_extract(NEW.after_summary_json,'$.email_fingerprint') =invitation.email_fingerprint AND json_extract(NEW.after_summary_json,'$.role_code')=invitation.role_code AND json_extract(NEW.after_summary_json,'$.status')='pending' AND json_extract(NEW.after_summary_json,'$.expires_at')=invitation.expires_at AND json_type(NEW.after_summary_json,'$.accepted_user_id')='null' AND metahub_json(NEW.changed_fields_json) =metahub_json('["email_fingerprint","expires_at","role_code","status"]') ) OR ( NEW.action='invitation.accepted' AND NEW.actor_email='invitation-acceptor@redacted.invalid' AND invitation.status='accepted' AND invitation.accepted_user_id=NEW.actor_user_id AND actor.role=invitation.role_code AND invitation.email=actor.email AND invitation.accepted_at=NEW.created_at AND (SELECT COUNT(*) FROM json_each(NEW.before_summary_json))=5 AND (SELECT COUNT(*) FROM json_each(NEW.after_summary_json))=5 AND NOT EXISTS ( SELECT 1 FROM json_each(NEW.before_summary_json) field WHERE field.key NOT IN ( 'email_fingerprint','role_code','status','expires_at','accepted_user_id' ) ) AND NOT EXISTS ( SELECT 1 FROM json_each(NEW.after_summary_json) field WHERE field.key NOT IN ( 'email_fingerprint','role_code','status','expires_at','accepted_user_id' ) ) AND json_extract(NEW.before_summary_json,'$.email_fingerprint') =invitation.email_fingerprint AND json_extract(NEW.before_summary_json,'$.role_code')=invitation.role_code AND json_extract(NEW.before_summary_json,'$.status')='pending' AND json_extract(NEW.before_summary_json,'$.expires_at')=invitation.expires_at AND json_type(NEW.before_summary_json,'$.accepted_user_id')='null' AND json_extract(NEW.after_summary_json,'$.email_fingerprint') =invitation.email_fingerprint AND json_extract(NEW.after_summary_json,'$.role_code')=invitation.role_code AND json_extract(NEW.after_summary_json,'$.status')='accepted' AND json_extract(NEW.after_summary_json,'$.expires_at')=invitation.expires_at AND json_extract(NEW.after_summary_json,'$.accepted_user_id') =invitation.accepted_user_id AND metahub_json(NEW.changed_fields_json)=metahub_json('["accepted_user_id","status"]') ) ) ) ) ) OR ( NEW.object_type='invitation' AND NEW.action NOT IN ('user_row.invited','invitation.accepted') ) OR ( NEW.action IN ('prompt_template.created','prompt_template.updated') AND ( NEW.object_type<>'prompt_template' OR NOT EXISTS ( SELECT 1 FROM prompt_templates template JOIN prompt_template_versions version ON version.tenant_id=template.tenant_id AND version.prompt_template_id=template.prompt_template_id AND version.prompt_template_version_id=template.current_version_id AND version.state='published' JOIN users actor ON actor.tenant_id=template.tenant_id AND actor.user_id=NEW.actor_user_id WHERE template.tenant_id=NEW.tenant_id AND template.prompt_template_id=NEW.object_id AND template.updated_by=NEW.actor_user_id AND actor.email=NEW.actor_email AND actor.role=NEW.actor_role AND actor.status='active' AND template.name=NEW.object_name AND json_extract(NEW.after_summary_json,'$.status')=template.status AND (json_extract(NEW.after_summary_json,'$.revision'))::NUMERIC=template.revision AND NOT EXISTS ( SELECT 1 FROM json_each(NEW.before_summary_json) field WHERE field.key NOT IN ( 'status','revision','version_number','project_scope','project_count', 'recommended_model_count','definition_size_bytes','variable_count', 'change_summary_hmac' ) ) AND NOT EXISTS ( SELECT 1 FROM json_each(NEW.after_summary_json) field WHERE field.key NOT IN ( 'status','revision','version_number','project_scope','project_count', 'recommended_model_count','definition_size_bytes','variable_count', 'change_summary_hmac' ) ) AND NOT EXISTS ( SELECT 1 FROM json_each(NEW.changed_fields_json) field WHERE field.value NOT IN ( 'status','revision','version_number','project_scope','project_count', 'recommended_model_count','definition_size_bytes','variable_count', 'change_summary_hmac' ) ) AND ( NEW.action<>'prompt_template.created' OR ( (SELECT COUNT(*) FROM json_each(NEW.before_summary_json))=0 AND (json_extract(NEW.after_summary_json,'$.version_number'))::NUMERIC =version.version_number AND json_extract(NEW.after_summary_json,'$.project_scope') =version.project_scope AND (json_extract(NEW.after_summary_json,'$.project_count'))::NUMERIC=( SELECT COUNT(*) FROM prompt_template_version_projects binding WHERE binding.tenant_id=version.tenant_id AND binding.prompt_template_version_id=version.prompt_template_version_id ) AND (json_extract(NEW.after_summary_json,'$.recommended_model_count'))::NUMERIC =version.recommended_model_count AND (json_extract(NEW.after_summary_json,'$.definition_size_bytes'))::NUMERIC =version.definition_size_bytes AND (json_extract(NEW.after_summary_json,'$.variable_count'))::NUMERIC =version.variable_count AND json_extract(NEW.after_summary_json,'$.change_summary_hmac') =version.change_summary_hmac ) ) AND ( NEW.action<>'prompt_template.updated' OR (json_extract(NEW.before_summary_json,'$.revision'))::NUMERIC=template.revision-1 ) ) ) ) OR ( NEW.action='prompt_template.version_published' AND ( NEW.object_type<>'prompt_template_version' OR NOT EXISTS ( SELECT 1 FROM prompt_template_versions version JOIN prompt_templates template ON template.tenant_id=version.tenant_id AND template.prompt_template_id=version.prompt_template_id AND template.current_version_id=version.prompt_template_version_id JOIN users actor ON actor.tenant_id=version.tenant_id AND actor.user_id=NEW.actor_user_id WHERE version.tenant_id=NEW.tenant_id AND version.prompt_template_version_id=NEW.object_id AND version.state='published' AND version.created_by=NEW.actor_user_id AND actor.email=NEW.actor_email AND actor.role=NEW.actor_role AND actor.status='active' AND template.name=NEW.object_name AND NEW.created_at=version.published_at AND json_extract(NEW.after_summary_json,'$.status')=template.status AND (json_extract(NEW.after_summary_json,'$.revision'))::NUMERIC=template.revision AND (json_extract(NEW.after_summary_json,'$.version_number'))::NUMERIC=version.version_number AND json_extract(NEW.after_summary_json,'$.project_scope')=version.project_scope AND (json_extract(NEW.after_summary_json,'$.project_count'))::NUMERIC=( SELECT COUNT(*) FROM prompt_template_version_projects binding WHERE binding.tenant_id=version.tenant_id AND binding.prompt_template_version_id=version.prompt_template_version_id ) AND (json_extract(NEW.after_summary_json,'$.recommended_model_count'))::NUMERIC =version.recommended_model_count AND (json_extract(NEW.after_summary_json,'$.definition_size_bytes'))::NUMERIC =version.definition_size_bytes AND (json_extract(NEW.after_summary_json,'$.variable_count'))::NUMERIC=version.variable_count AND json_extract(NEW.after_summary_json,'$.change_summary_hmac') =version.change_summary_hmac AND NOT EXISTS ( SELECT 1 FROM json_each(NEW.before_summary_json) field WHERE field.key NOT IN ( 'status','revision','version_number','project_scope','project_count', 'recommended_model_count','definition_size_bytes','variable_count', 'change_summary_hmac' ) ) AND NOT EXISTS ( SELECT 1 FROM json_each(NEW.after_summary_json) field WHERE field.key NOT IN ( 'status','revision','version_number','project_scope','project_count', 'recommended_model_count','definition_size_bytes','variable_count', 'change_summary_hmac' ) ) AND NOT EXISTS ( SELECT 1 FROM json_each(NEW.changed_fields_json) field WHERE field.value NOT IN ( 'status','revision','version_number','project_scope','project_count', 'recommended_model_count','definition_size_bytes','variable_count', 'change_summary_hmac' ) ) ) ) ) OR ( NEW.object_type='prompt_template' AND NEW.action NOT IN ('prompt_template.created','prompt_template.updated') ) OR ( NEW.object_type='prompt_template_version' AND NEW.action<>'prompt_template.version_published' ) OR ( NEW.action='experiment.created' AND ( NEW.object_type<>'experiment' OR NEW.object_name IS NOT NULL OR NOT EXISTS ( SELECT 1 FROM model_experiments experiment JOIN users actor ON actor.tenant_id=experiment.tenant_id AND actor.user_id=experiment.created_by WHERE experiment.tenant_id=NEW.tenant_id AND experiment.experiment_id=NEW.object_id AND experiment.created_by=NEW.actor_user_id AND actor.email=NEW.actor_email AND actor.role=NEW.actor_role AND actor.status='active' AND experiment.operation_request_id=NEW.request_id AND experiment.operation_trace_id=NEW.trace_id AND (SELECT COUNT(*) FROM json_each(NEW.before_summary_json))=0 AND (SELECT COUNT(*) FROM json_each(NEW.after_summary_json))=12 AND NOT EXISTS ( SELECT 1 FROM json_each(NEW.after_summary_json) field WHERE field.key NOT IN ( 'experiment_id','project_id','environment_id','model_alias_id', 'model_a_id','model_b_id','target_sample_count','traffic_sample_bps', 'model_a_allocation_bps','sampling_duration_seconds', 'feedback_collection_enabled','feedback_window_seconds' ) ) AND json_extract(NEW.after_summary_json,'$.experiment_id') =experiment.experiment_id AND json_extract(NEW.after_summary_json,'$.project_id')=experiment.project_id AND json_extract(NEW.after_summary_json,'$.environment_id') =experiment.environment_id AND json_extract(NEW.after_summary_json,'$.model_alias_id') =experiment.model_alias_id AND json_extract(NEW.after_summary_json,'$.model_a_id')=experiment.model_a_id AND json_extract(NEW.after_summary_json,'$.model_b_id')=experiment.model_b_id AND (json_extract(NEW.after_summary_json,'$.target_sample_count'))::NUMERIC =experiment.target_sample_count AND (json_extract(NEW.after_summary_json,'$.traffic_sample_bps'))::NUMERIC =experiment.traffic_sample_bps AND (json_extract(NEW.after_summary_json,'$.model_a_allocation_bps'))::NUMERIC =experiment.model_a_allocation_bps AND (json_extract(NEW.after_summary_json,'$.sampling_duration_seconds'))::NUMERIC =experiment.sampling_duration_seconds AND (json_extract(NEW.after_summary_json,'$.feedback_collection_enabled'))::NUMERIC =experiment.feedback_collection_enabled AND (json_extract(NEW.after_summary_json,'$.feedback_window_seconds'))::NUMERIC =experiment.feedback_window_seconds AND metahub_json(NEW.changed_fields_json)=metahub_json( '["environment_id","experiment_id","feedback_collection_enabled",' || '"feedback_window_seconds","model_a_allocation_bps","model_a_id",' || '"model_alias_id","model_b_id","project_id","sampling_duration_seconds",' || '"target_sample_count","traffic_sample_bps"]' ) ) ) ) OR (NEW.object_type='experiment' AND NEW.action<>'experiment.created')) THEN
