CREATE OR REPLACE FUNCTION "fn_trg_audit_logs_plan_billing_owner_insert_prd079"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (( NEW.action IN('plan.created','plan.updated') AND ( NEW.object_type<>'plan' OR NOT EXISTS( SELECT 1 FROM plans plan WHERE plan.tenant_id=NEW.tenant_id AND plan.plan_id=NEW.object_id AND plan.display_name=NEW.object_name AND (SELECT COUNT(*) FROM json_each(NEW.after_summary_json))=9 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.after_summary_json) field WHERE field.key NOT IN( 'display_name','base_tier','status','trial_status','trial_started_at', 'trial_ends_at','trial_cycle','state_revision','quota_generation')) AND json_extract(NEW.after_summary_json,'$.display_name')=plan.display_name AND json_extract(NEW.after_summary_json,'$.base_tier')=plan.base_tier AND json_extract(NEW.after_summary_json,'$.status')=plan.status AND json_extract(NEW.after_summary_json,'$.trial_status')=plan.trial_status AND json_extract(NEW.after_summary_json,'$.trial_started_at') IS NOT DISTINCT FROM plan.trial_started_at AND json_extract(NEW.after_summary_json,'$.trial_ends_at') IS NOT DISTINCT FROM plan.trial_ends_at AND (json_extract(NEW.after_summary_json,'$.trial_cycle'))::NUMERIC=plan.trial_cycle AND (json_extract(NEW.after_summary_json,'$.state_revision'))::NUMERIC=plan.state_revision AND (json_extract(NEW.after_summary_json,'$.quota_generation'))::NUMERIC=plan.quota_generation AND ( (NEW.action='plan.created' AND NEW.before_summary_json='{}' AND plan.state_revision=1) OR (NEW.action='plan.updated' AND (SELECT COUNT(*) FROM json_each(NEW.before_summary_json))=9 AND (json_extract(NEW.before_summary_json,'$.state_revision'))::NUMERIC+1 =plan.state_revision) ) ) ) ) OR (NEW.object_type='plan' AND NEW.action NOT IN('plan.created','plan.updated')) OR ( NEW.action='quota.adjustment_created' AND ( NEW.object_type<>'quota_adjustment' OR NEW.object_name IS NOT NULL OR NEW.before_summary_json<>'{}' OR NOT EXISTS( SELECT 1 FROM quota_adjustments adjustment WHERE adjustment.tenant_id=NEW.tenant_id AND adjustment.quota_adjustment_id=NEW.object_id AND adjustment.actor_user_id=NEW.actor_user_id AND adjustment.operation_request_id=NEW.request_id AND adjustment.operation_trace_id=NEW.trace_id AND adjustment.created_at=NEW.created_at AND (SELECT COUNT(*) FROM json_each(NEW.after_summary_json))=8 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.after_summary_json) field WHERE field.key NOT IN( 'plan_id','quota_bucket_id','quota_type','direction','amount', 'expected_bucket_revision','resulting_bucket_revision','reason_sha256')) AND json_extract(NEW.after_summary_json,'$.plan_id')=adjustment.plan_id AND json_extract(NEW.after_summary_json,'$.quota_bucket_id') =adjustment.quota_bucket_id AND json_extract(NEW.after_summary_json,'$.quota_type')=adjustment.quota_type AND json_extract(NEW.after_summary_json,'$.direction')=adjustment.direction AND json_extract(NEW.after_summary_json,'$.amount')= printf('%d.%06d',adjustment.amount_micros/1000000, adjustment.amount_micros%1000000) AND (json_extract(NEW.after_summary_json,'$.expected_bucket_revision'))::NUMERIC =adjustment.expected_bucket_revision AND (json_extract(NEW.after_summary_json,'$.resulting_bucket_revision'))::NUMERIC =adjustment.resulting_bucket_revision AND json_extract(NEW.after_summary_json,'$.reason_sha256') =metahub_sha256(adjustment.reason) ) ) ) OR (NEW.object_type='quota_adjustment' AND NEW.action<>'quota.adjustment_created')) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='audit_log_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
