CREATE OR REPLACE FUNCTION "fn_trg_audit_logs_policy_template_owner_insert_prd068"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (( NEW.action IN ('policy_template.applied','policy_template.rolled_back') AND ( NEW.object_type<>'policy_template_application' OR NEW.object_name IS NOT NULL OR NOT EXISTS ( SELECT 1 FROM policy_template_applications application JOIN policy_templates template ON template.tenant_id=application.tenant_id AND template.policy_template_id=application.policy_template_id WHERE application.tenant_id=NEW.tenant_id AND application.application_id=NEW.object_id AND ( (NEW.action='policy_template.applied' AND application.status IN ('applied','rolled_back') AND application.apply_audit_log_id=NEW.audit_log_id AND application.actor_user_id=NEW.actor_user_id AND application.request_id=NEW.request_id AND application.trace_id=NEW.trace_id AND application.applied_as_of=NEW.created_at) OR (NEW.action='policy_template.rolled_back' AND application.status='rolled_back' AND application.rollback_apply_audit_log_id=NEW.audit_log_id AND application.rollback_actor_user_id=NEW.actor_user_id AND application.rollback_request_id=NEW.request_id AND application.rollback_trace_id=NEW.trace_id AND application.rolled_back_at=NEW.created_at) ) AND NOT EXISTS ( SELECT 1 FROM json_each(NEW.before_summary_json) field WHERE field.key NOT IN ( 'status','template_code','template_version','application_id', 'generated_policy_id','previous_snapshot_version','result_snapshot_version', 'rollback_snapshot_version','impact_hash','bindings_hash','changed_resource_types' ) ) AND NOT EXISTS ( SELECT 1 FROM json_each(NEW.after_summary_json) field WHERE field.key NOT IN ( 'status','template_code','template_version','application_id', 'generated_policy_id','previous_snapshot_version','result_snapshot_version', 'rollback_snapshot_version','impact_hash','bindings_hash','changed_resource_types' ) ) AND NOT EXISTS ( SELECT 1 FROM json_each(NEW.changed_fields_json) field WHERE field.value NOT IN ( 'status','template_code','template_version','application_id', 'generated_policy_id','previous_snapshot_version','result_snapshot_version', 'rollback_snapshot_version','impact_hash','bindings_hash','changed_resource_types' ) ) AND json_extract(NEW.after_summary_json,'$.template_code')=template.template_code AND (json_extract(NEW.after_summary_json,'$.template_version'))::NUMERIC=application.template_version AND json_extract(NEW.after_summary_json,'$.application_id')=application.application_id AND json_extract(NEW.after_summary_json,'$.generated_policy_id')=application.generated_policy_id AND (json_extract(NEW.after_summary_json,'$.previous_snapshot_version'))::NUMERIC =application.previous_snapshot_version AND (json_extract(NEW.after_summary_json,'$.result_snapshot_version'))::NUMERIC =application.result_snapshot_version AND json_extract(NEW.after_summary_json,'$.impact_hash')=application.impact_hash AND json_extract(NEW.after_summary_json,'$.bindings_hash')=application.bindings_hash AND json_extract(NEW.after_summary_json,'$.changed_resource_types') ='policy,policy_snapshot' AND ( ( NEW.action='policy_template.applied' AND NEW.before_summary_json='{}' AND json_extract(NEW.after_summary_json,'$.status')='applied' AND json_type(NEW.after_summary_json,'$.rollback_snapshot_version') IS NULL ) OR ( NEW.action='policy_template.rolled_back' AND json_extract(NEW.before_summary_json,'$.status')='applied' AND json_extract(NEW.before_summary_json,'$.template_code')=template.template_code AND (json_extract(NEW.before_summary_json,'$.template_version'))::NUMERIC =application.template_version AND json_extract(NEW.before_summary_json,'$.application_id') =application.application_id AND json_extract(NEW.before_summary_json,'$.generated_policy_id') =application.generated_policy_id AND (json_extract(NEW.before_summary_json,'$.previous_snapshot_version'))::NUMERIC =application.previous_snapshot_version AND (json_extract(NEW.before_summary_json,'$.result_snapshot_version'))::NUMERIC =application.result_snapshot_version AND json_extract(NEW.before_summary_json,'$.impact_hash')=application.impact_hash AND json_extract(NEW.before_summary_json,'$.bindings_hash')=application.bindings_hash AND json_extract(NEW.before_summary_json,'$.changed_resource_types') ='policy,policy_snapshot' AND json_type(NEW.before_summary_json,'$.rollback_snapshot_version') IS NULL AND json_extract(NEW.after_summary_json,'$.status')='rolled_back' AND (json_extract(NEW.after_summary_json,'$.rollback_snapshot_version'))::NUMERIC =application.rollback_snapshot_version ) ) ) ) ) OR ( NEW.object_type='policy_template_application' AND NEW.action NOT IN ('policy_template.applied','policy_template.rolled_back') )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='audit_log_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_audit_logs_policy_template_owner_insert_prd068" BEFORE INSERT ON "audit_logs" FOR EACH ROW EXECUTE FUNCTION "fn_trg_audit_logs_policy_template_owner_insert_prd068"();
CREATE OR REPLACE FUNCTION "fn_trg_audit_logs_prd050_conflict_insert"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (EXISTS ( SELECT 1 FROM audit_logs current WHERE current.audit_log_id=NEW.audit_log_id OR (NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid) OR ( NEW.action IN ('policy.dry_run_executed','model_quality_score.updated') AND current.action=NEW.action AND current.tenant_id=NEW.tenant_id AND current.actor_user_id=NEW.actor_user_id AND current.request_id=NEW.request_id ) OR ( NEW.action='finops.adjustment_created' AND current.action='finops.adjustment_created' AND current.tenant_id=NEW.tenant_id AND current.object_id=NEW.object_id ) OR ( NEW.action IN ( 'cost_anomaly.acknowledged','cost_anomaly.dismissed', 'cost_anomaly.temporary_rate_limit_applied', 'cost_anomaly.temporary_rate_limit_released' ) AND current.action=NEW.action AND current.tenant_id=NEW.tenant_id AND current.actor_user_id=NEW.actor_user_id AND current.request_id=NEW.request_id ) OR ( NEW.action IN ('error_map.created','error_map.updated') AND current.action=NEW.action AND current.tenant_id=NEW.tenant_id AND current.actor_user_id=NEW.actor_user_id AND current.request_id=NEW.request_id ) OR ( NEW.action IN ('user_row.invited','invitation.accepted') AND current.action IN ('user_row.invited','invitation.accepted') AND current.tenant_id=NEW.tenant_id AND current.actor_user_id=NEW.actor_user_id AND current.request_id=NEW.request_id ) OR ( NEW.action IN ('config.imported','config.exported') AND current.action=NEW.action AND current.tenant_id=NEW.tenant_id AND current.actor_user_id=NEW.actor_user_id AND current.request_id=NEW.request_id ) OR ( NEW.action IN ( 'prompt_template.created','prompt_template.updated', 'prompt_template.version_published' ) AND current.action=NEW.action AND current.tenant_id=NEW.tenant_id AND current.request_id=NEW.request_id ) OR ( NEW.action='experiment.created' AND current.action=NEW.action AND current.tenant_id=NEW.tenant_id AND current.object_id=NEW.object_id ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='audit_log_immutable';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_audit_logs_prd050_conflict_insert" BEFORE INSERT ON "audit_logs" FOR EACH ROW EXECUTE FUNCTION "fn_trg_audit_logs_prd050_conflict_insert"();
