CREATE OR REPLACE FUNCTION "fn_trg_audit_logs_response_cache_owner_insert_prd076"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (( NEW.action IN ( 'response_cache.policy_created','response_cache.policy_updated' ) AND ( NEW.object_type<>'response_cache_policy' OR NEW.object_name IS NOT NULL OR NOT EXISTS( SELECT 1 FROM response_cache_policy_events event JOIN response_cache_policies policy ON policy.tenant_id=event.tenant_id AND policy.cache_policy_id=event.cache_policy_id JOIN users actor ON actor.tenant_id=event.tenant_id AND actor.user_id=event.actor_user_id WHERE event.tenant_id=NEW.tenant_id AND event.cache_policy_id=NEW.object_id AND event.actor_user_id=NEW.actor_user_id AND actor.email=NEW.actor_email AND actor.role=NEW.actor_role AND actor.status='active' AND event.operation_request_id=NEW.request_id AND event.operation_trace_id=NEW.trace_id AND event.created_at=NEW.created_at AND event.event_type=CASE NEW.action WHEN 'response_cache.policy_created' THEN 'policy_created' ELSE 'policy_updated' END AND event.before_json=NEW.before_summary_json AND event.after_json=NEW.after_summary_json AND event.changed=1 AND NOT EXISTS( SELECT 1 FROM json_each(NEW.before_summary_json) field WHERE field.key NOT IN( 'tenant_id','cache_policy_id','model_alias_id','status','data_class', 'ttl_seconds','charge_cache_hits','tags','version', 'invalidation_generation' ) ) AND NOT EXISTS( SELECT 1 FROM json_each(NEW.after_summary_json) field WHERE field.key NOT IN( 'tenant_id','cache_policy_id','model_alias_id','status','data_class', 'ttl_seconds','charge_cache_hits','tags','version', 'invalidation_generation' ) ) AND NOT EXISTS( SELECT 1 FROM json_each(NEW.changed_fields_json) field WHERE field.type<>'text' OR field.value NOT IN( 'status','data_class','ttl_seconds','charge_cache_hits','tags', 'version','invalidation_generation' ) ) ) ) ) OR ( NEW.action='response_cache.invalidated' AND ( NEW.object_type<>'response_cache_invalidation' OR NEW.object_name IS NOT NULL OR NEW.before_summary_json<>'{}' OR NOT EXISTS( SELECT 1 FROM response_cache_invalidations invalidation JOIN users actor ON actor.tenant_id=invalidation.tenant_id AND actor.user_id=invalidation.actor_user_id WHERE invalidation.tenant_id=NEW.tenant_id AND invalidation.cache_invalidation_id=NEW.object_id AND invalidation.actor_type='user' AND invalidation.actor_user_id=NEW.actor_user_id AND actor.email=NEW.actor_email AND actor.role=NEW.actor_role AND actor.status='active' AND invalidation.operation_request_id=NEW.request_id AND invalidation.operation_trace_id=NEW.trace_id AND invalidation.created_at=NEW.created_at AND (SELECT COUNT(*) FROM json_each(NEW.after_summary_json))=8 AND NOT EXISTS( SELECT 1 FROM json_each(NEW.after_summary_json) field WHERE field.key NOT IN( 'cache_invalidation_id','scope','match_mode','tag_count', 'matched_entry_count','deleted_entry_count','fenced_fill_count', 'reason_code' ) ) AND json_extract(NEW.after_summary_json,'$.cache_invalidation_id') =invalidation.cache_invalidation_id AND json_extract(NEW.after_summary_json,'$.scope')=invalidation.scope AND json_extract(NEW.after_summary_json,'$.match_mode') =invalidation.match_mode AND (json_extract(NEW.after_summary_json,'$.tag_count'))::NUMERIC =invalidation.tag_count AND (json_extract(NEW.after_summary_json,'$.matched_entry_count'))::NUMERIC =invalidation.matched_entry_count AND (json_extract(NEW.after_summary_json,'$.deleted_entry_count'))::NUMERIC =invalidation.deleted_entry_count AND (json_extract(NEW.after_summary_json,'$.fenced_fill_count'))::NUMERIC =invalidation.fenced_fill_count AND json_extract(NEW.after_summary_json,'$.reason_code') =invalidation.reason_code ) ) ) OR ( NEW.object_type='response_cache_policy' AND NEW.action NOT IN( 'response_cache.policy_created','response_cache.policy_updated' ) ) OR ( NEW.object_type='response_cache_invalidation' AND NEW.action<>'response_cache.invalidated' )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='audit_log_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_audit_logs_response_cache_owner_insert_prd076" BEFORE INSERT ON "audit_logs" FOR EACH ROW EXECUTE FUNCTION "fn_trg_audit_logs_response_cache_owner_insert_prd076"();
CREATE OR REPLACE FUNCTION "fn_trg_audit_logs_session_risk_owner_insert_prd070"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (( NEW.action IN ( 'session_risk.freeze_session','session_risk.freeze_virtual_key', 'session_risk.dismiss','session_risk.release_session', 'session_risk.release_virtual_key' ) AND ( NEW.object_type<>'session_risk' OR NEW.object_name NOT IN ('enterprise_chat','api_session') OR NOT EXISTS ( SELECT 1 FROM session_risk_actions action JOIN session_risk_scores score ON score.tenant_id=action.tenant_id AND score.session_risk_score_id=action.session_risk_score_id JOIN session_risk_events event ON event.tenant_id=action.tenant_id AND event.session_risk_action_id=action.session_risk_action_id WHERE action.tenant_id=NEW.tenant_id AND action.session_risk_score_id=NEW.object_id AND action.actor_type='user' AND action.actor_id=NEW.actor_user_id AND action.source_request_id=NEW.request_id AND action.source_trace_id=NEW.trace_id AND action.created_at=NEW.created_at AND 'session_risk.' || action.action=NEW.action AND score.scope_type=NEW.object_name AND event.session_risk_score_id=action.session_risk_score_id AND event.session_risk_freeze_id IS NOT DISTINCT FROM action.session_risk_freeze_id AND event.event_type='security.session_high_risk' AND event.scope_type=score.scope_type AND event.scope_key=score.scope_key AND event.status=action.status_after AND event.target_type IS NOT DISTINCT FROM CASE action.action WHEN 'freeze_session' THEN 'session' WHEN 'release_session' THEN 'session' WHEN 'freeze_virtual_key' THEN 'virtual_key' WHEN 'release_virtual_key' THEN 'virtual_key' ELSE NULL END AND event.score=action.score_snapshot AND event.score_scale=score.score_scale AND event.state_revision=action.state_revision AND event.threshold_version=score.threshold_version AND event.actor_type='user' AND event.actor_id=action.actor_id AND event.source_request_id=action.source_request_id AND event.source_trace_id=action.source_trace_id AND event.occurred_at=action.created_at AND (SELECT COUNT(*) FROM json_each(NEW.before_summary_json))=6 AND (SELECT COUNT(*) FROM json_each(NEW.after_summary_json))=6 AND NOT EXISTS ( SELECT 1 FROM json_each(NEW.before_summary_json) field WHERE field.key NOT IN ( 'scope_type','status','score','state_revision', 'session_risk_freeze_id','target_type' ) ) AND NOT EXISTS ( SELECT 1 FROM json_each(NEW.after_summary_json) field WHERE field.key NOT IN ( 'scope_type','status','score','state_revision', 'session_risk_freeze_id','target_type' ) ) AND json_extract(NEW.before_summary_json,'$.scope_type')=score.scope_type AND json_extract(NEW.after_summary_json,'$.scope_type')=score.scope_type AND json_extract(NEW.before_summary_json,'$.status')=action.status_before AND json_extract(NEW.after_summary_json,'$.status')=action.status_after AND (json_extract(NEW.before_summary_json,'$.score'))::NUMERIC=action.score_snapshot AND (json_extract(NEW.after_summary_json,'$.score'))::NUMERIC=action.score_snapshot AND (json_extract(NEW.before_summary_json,'$.state_revision'))::NUMERIC=action.state_revision-1 AND (json_extract(NEW.after_summary_json,'$.state_revision'))::NUMERIC=action.state_revision AND json_extract(NEW.before_summary_json,'$.session_risk_freeze_id') IS NOT DISTINCT FROM CASE WHEN action.action IN ('release_session','release_virtual_key') THEN action.session_risk_freeze_id ELSE NULL END AND json_extract(NEW.after_summary_json,'$.session_risk_freeze_id') IS NOT DISTINCT FROM action.session_risk_freeze_id AND json_extract(NEW.before_summary_json,'$.target_type') IS NOT DISTINCT FROM CASE action.action WHEN 'release_session' THEN 'session' WHEN 'release_virtual_key' THEN 'virtual_key' ELSE NULL END AND json_extract(NEW.after_summary_json,'$.target_type') IS NOT DISTINCT FROM CASE action.action WHEN 'freeze_session' THEN 'session' WHEN 'release_session' THEN 'session' WHEN 'freeze_virtual_key' THEN 'virtual_key' WHEN 'release_virtual_key' THEN 'virtual_key' ELSE NULL END AND (SELECT COUNT(*) FROM json_each(NEW.changed_fields_json)) =(SELECT COUNT(DISTINCT value) FROM json_each(NEW.changed_fields_json)) AND NOT EXISTS ( SELECT 1 FROM json_each(NEW.changed_fields_json) field WHERE field.type<>'text' OR field.value NOT IN ( 'scope_type','status','score','state_revision', 'session_risk_freeze_id','target_type' ) ) AND NOT EXISTS ( SELECT 1 FROM json_each( '["scope_type","status","score","state_revision",' || '"session_risk_freeze_id","target_type"]' ) expected WHERE ( json_extract(NEW.before_summary_json,'$.' || expected.value) IS DISTINCT FROM json_extract(NEW.after_summary_json,'$.' || expected.value) ) <> EXISTS ( SELECT 1 FROM json_each(NEW.changed_fields_json) actual WHERE actual.value=expected.value ) ) ) ) ) OR ( NEW.object_type='session_risk' AND NEW.action NOT IN ( 'session_risk.freeze_session','session_risk.freeze_virtual_key', 'session_risk.dismiss','session_risk.release_session', 'session_risk.release_virtual_key' ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='audit_log_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_audit_logs_session_risk_owner_insert_prd070" BEFORE INSERT ON "audit_logs" FOR EACH ROW EXECUTE FUNCTION "fn_trg_audit_logs_session_risk_owner_insert_prd070"();
CREATE OR REPLACE FUNCTION "fn_trg_audit_logs_mcp_owner_insert_prd082"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF ((NEW.action LIKE 'mcp.%' AND NEW.action<>'mcp.network_policy_updated' AND ( NEW.object_name IS NOT NULL OR (SELECT COUNT(*) FROM json_each(NEW.before_summary_json)) <>(SELECT COUNT(DISTINCT key) FROM json_each(NEW.before_summary_json)) OR (SELECT COUNT(*) FROM json_each(NEW.after_summary_json)) <>(SELECT COUNT(DISTINCT key) FROM json_each(NEW.after_summary_json)) OR (SELECT COUNT(*) FROM json_each(NEW.changed_fields_json)) <>(SELECT COUNT(DISTINCT value) FROM json_each(NEW.changed_fields_json)) OR EXISTS(SELECT 1 FROM json_each(NEW.before_summary_json) field WHERE (NEW.object_type='mcp_server' AND field.key NOT IN( 'mcp_server_id','status','state_revision','active_credential_revision', 'tool_count','active_tool_count')) OR (NEW.object_type='mcp_server_operation' AND field.key NOT IN( 'mcp_server_operation_id','mcp_server_id','operation_type','status', 'start_server_revision','candidate_credential_revision','error_code')) OR (NEW.object_type='mcp_tool' AND field.key NOT IN( 'mcp_tool_id','mcp_server_id','status','schema_revision','policy_revision', 'risk_level','approval_required','required_permission_count', 'role_grant_count','user_grant_count','redaction_count'))) OR EXISTS(SELECT 1 FROM json_each(NEW.after_summary_json) field WHERE (NEW.object_type='mcp_server' AND field.key NOT IN( 'mcp_server_id','status','state_revision','active_credential_revision', 'tool_count','active_tool_count')) OR (NEW.object_type='mcp_server_operation' AND field.key NOT IN( 'mcp_server_operation_id','mcp_server_id','operation_type','status', 'start_server_revision','candidate_credential_revision','error_code')) OR (NEW.object_type='mcp_tool' AND field.key NOT IN( 'mcp_tool_id','mcp_server_id','status','schema_revision','policy_revision', 'risk_level','approval_required','required_permission_count', 'role_grant_count','user_grant_count','redaction_count'))) OR EXISTS(SELECT 1 FROM json_each(NEW.changed_fields_json) field WHERE field.type<>'text' OR (NEW.object_type='mcp_server' AND field.value NOT IN( 'mcp_server_id','status','state_revision','active_credential_revision', 'tool_count','active_tool_count')) OR (NEW.object_type='mcp_server_operation' AND field.value NOT IN( 'mcp_server_operation_id','mcp_server_id','operation_type','status', 'start_server_revision','candidate_credential_revision','error_code')) OR (NEW.object_type='mcp_tool' AND field.value NOT IN( 'mcp_tool_id','mcp_server_id','status','schema_revision','policy_revision', 'risk_level','approval_required','required_permission_count', 'role_grant_count','user_grant_count','redaction_count'))) OR EXISTS( SELECT 1 FROM json_each(CASE NEW.object_type WHEN 'mcp_server' THEN '["mcp_server_id","status","state_revision","active_credential_revision",' || '"tool_count","active_tool_count"]' WHEN 'mcp_server_operation' THEN '["mcp_server_operation_id","mcp_server_id","operation_type","status",' || '"start_server_revision","candidate_credential_revision","error_code"]' WHEN 'mcp_tool' THEN '["mcp_tool_id","mcp_server_id","status","schema_revision",' || '"policy_revision","risk_level","approval_required",' || '"required_permission_count","role_grant_count","user_grant_count",' || '"redaction_count"]' ELSE '[]' END) expected WHERE (json_extract(NEW.before_summary_json,'$.'||expected.value) IS DISTINCT FROM json_extract(NEW.after_summary_json,'$.'||expected.value)) <>EXISTS(SELECT 1 FROM json_each(NEW.changed_fields_json) actual WHERE actual.value=expected.value) ) OR (NEW.object_type='mcp_server' AND NOT EXISTS( SELECT 1 FROM mcp_servers server WHERE server.tenant_id=NEW.tenant_id AND server.mcp_server_id=NEW.object_id)) OR (NEW.object_type='mcp_server_operation' AND NOT EXISTS( SELECT 1 FROM mcp_server_operations operation WHERE operation.tenant_id=NEW.tenant_id AND operation.mcp_server_operation_id=NEW.object_id)) OR (NEW.object_type='mcp_tool' AND NOT EXISTS( SELECT 1 FROM mcp_tools tool WHERE tool.tenant_id=NEW.tenant_id AND tool.mcp_tool_id=NEW.object_id)) OR (NEW.action IN('mcp.server_registered','mcp.server_refreshed', 'mcp.server_credential_rotated','mcp.server_updated', 'mcp.server_disabled','mcp.server_enabled') AND NEW.object_type<>'mcp_server') OR (NEW.action='mcp.server_operation_completed' AND NEW.object_type<>'mcp_server_operation') OR (NEW.action IN('mcp.tool_refreshed','mcp.tool_policy_updated', 'mcp.tool_grants_updated') AND NEW.object_type<>'mcp_tool') )) OR (NEW.object_type IN('mcp_server','mcp_server_operation','mcp_tool') AND NEW.action NOT LIKE 'mcp.%')) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='audit_log_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_audit_logs_mcp_owner_insert_prd082" BEFORE INSERT ON "audit_logs" FOR EACH ROW EXECUTE FUNCTION "fn_trg_audit_logs_mcp_owner_insert_prd082"();
CREATE OR REPLACE FUNCTION "fn_trg_audit_logs_mcp_operation_insert_prd082"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.action='mcp.server_operation_completed' AND ( (SELECT COUNT(*) FROM json_each(NEW.before_summary_json))<>7 OR (SELECT COUNT(*) FROM json_each(NEW.after_summary_json))<>7 OR NOT EXISTS( SELECT 1 FROM mcp_server_operations operation JOIN users actor ON actor.tenant_id=operation.tenant_id AND actor.user_id=operation.actor_user_id WHERE operation.tenant_id=NEW.tenant_id AND operation.mcp_server_operation_id=NEW.object_id AND operation.status IN('succeeded','failed') AND (operation.status='failed' OR actor.status='active') AND NEW.actor_user_id=actor.user_id AND NEW.actor_email=actor.email AND NEW.actor_role=actor.role AND NEW.request_id=operation.request_id AND NEW.trace_id=operation.trace_id AND NEW.created_at=operation.completed_at AND json_type(NEW.before_summary_json,'$.mcp_server_operation_id')='text' AND json_extract(NEW.before_summary_json,'$.mcp_server_operation_id') =operation.mcp_server_operation_id AND json_type(NEW.before_summary_json,'$.mcp_server_id')='text' AND json_extract(NEW.before_summary_json,'$.mcp_server_id')=operation.mcp_server_id AND json_type(NEW.before_summary_json,'$.operation_type')='text' AND json_extract(NEW.before_summary_json,'$.operation_type')=operation.operation_type AND json_type(NEW.before_summary_json,'$.status')='text' AND json_extract(NEW.before_summary_json,'$.status')='processing' AND json_type(NEW.before_summary_json,'$.start_server_revision')='integer' AND (json_extract(NEW.before_summary_json,'$.start_server_revision'))::NUMERIC =operation.start_server_revision AND json_type(NEW.before_summary_json,'$.candidate_credential_revision') IN('integer','null') AND (json_extract(NEW.before_summary_json,'$.candidate_credential_revision'))::NUMERIC IS NOT DISTINCT FROM operation.candidate_credential_revision AND json_type(NEW.before_summary_json,'$.error_code')='null' AND json_type(NEW.after_summary_json,'$.mcp_server_operation_id')='text' AND json_extract(NEW.after_summary_json,'$.mcp_server_operation_id') =operation.mcp_server_operation_id AND json_type(NEW.after_summary_json,'$.mcp_server_id')='text' AND json_extract(NEW.after_summary_json,'$.mcp_server_id')=operation.mcp_server_id AND json_type(NEW.after_summary_json,'$.operation_type')='text' AND json_extract(NEW.after_summary_json,'$.operation_type')=operation.operation_type AND json_type(NEW.after_summary_json,'$.status')='text' AND json_extract(NEW.after_summary_json,'$.status')=operation.status AND json_type(NEW.after_summary_json,'$.start_server_revision')='integer' AND (json_extract(NEW.after_summary_json,'$.start_server_revision'))::NUMERIC =operation.start_server_revision AND json_type(NEW.after_summary_json,'$.candidate_credential_revision') IN('integer','null') AND (json_extract(NEW.after_summary_json,'$.candidate_credential_revision'))::NUMERIC IS NOT DISTINCT FROM operation.candidate_credential_revision AND json_type(NEW.after_summary_json,'$.error_code') =CASE WHEN operation.error_code IS NULL THEN 'null' ELSE 'text' END AND json_extract(NEW.after_summary_json,'$.error_code') IS NOT DISTINCT FROM operation.error_code ) )) THEN
