CREATE OR REPLACE FUNCTION "fn_trg_audit_logs_mcp_server_insert_prd082"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.action IN( 'mcp.server_registered','mcp.server_refreshed','mcp.server_credential_rotated', 'mcp.server_updated','mcp.server_disabled','mcp.server_enabled' ) AND ( (SELECT COUNT(*) FROM json_each(NEW.after_summary_json))<>6 OR (NEW.action='mcp.server_registered' AND (SELECT COUNT(*) FROM json_each(NEW.before_summary_json))<>0) OR (NEW.action<>'mcp.server_registered' AND (SELECT COUNT(*) FROM json_each(NEW.before_summary_json))<>6) OR NOT EXISTS( SELECT 1 FROM mcp_servers server JOIN mcp_server_operations operation ON operation.tenant_id=server.tenant_id AND operation.mcp_server_id=server.mcp_server_id JOIN users actor ON actor.tenant_id=operation.tenant_id AND actor.user_id=operation.actor_user_id WHERE server.tenant_id=NEW.tenant_id AND server.mcp_server_id=NEW.object_id AND actor.status='active' AND NEW.actor_user_id=actor.user_id AND NEW.actor_email=actor.email AND NEW.actor_role=actor.role AND server.updated_by=operation.actor_user_id AND NEW.request_id=operation.request_id AND NEW.trace_id=operation.trace_id AND operation.operation_type=CASE NEW.action WHEN 'mcp.server_registered' THEN 'register' WHEN 'mcp.server_refreshed' THEN 'refresh' WHEN 'mcp.server_credential_rotated' THEN 'rotate' WHEN 'mcp.server_updated' THEN 'update' WHEN 'mcp.server_disabled' THEN 'disable' WHEN 'mcp.server_enabled' THEN 'enable' END AND json_type(NEW.after_summary_json,'$.mcp_server_id')='text' AND json_extract(NEW.after_summary_json,'$.mcp_server_id')=server.mcp_server_id AND json_type(NEW.after_summary_json,'$.status')='text' AND json_extract(NEW.after_summary_json,'$.status')=server.status AND json_type(NEW.after_summary_json,'$.state_revision')='integer' AND (json_extract(NEW.after_summary_json,'$.state_revision'))::NUMERIC=server.state_revision AND json_type(NEW.after_summary_json,'$.active_credential_revision') IN('integer','null') AND (json_extract(NEW.after_summary_json,'$.active_credential_revision'))::NUMERIC IS NOT DISTINCT FROM server.active_credential_revision AND json_type(NEW.after_summary_json,'$.tool_count')='integer' AND (json_extract(NEW.after_summary_json,'$.tool_count'))::NUMERIC=( SELECT COUNT(*) FROM mcp_tools tool WHERE tool.tenant_id=server.tenant_id AND tool.mcp_server_id=server.mcp_server_id) AND json_type(NEW.after_summary_json,'$.active_tool_count')='integer' AND (json_extract(NEW.after_summary_json,'$.active_tool_count'))::NUMERIC=( SELECT COUNT(*) FROM mcp_tools tool WHERE tool.tenant_id=server.tenant_id AND tool.mcp_server_id=server.mcp_server_id AND tool.status='active') AND ( (NEW.action='mcp.server_registered' AND operation.status='queued' AND NEW.created_at=operation.created_at AND server.created_at=operation.created_at AND server.updated_at=operation.created_at AND server.created_by=operation.actor_user_id AND operation.start_server_revision=1 AND server.state_revision=1 AND server.status='pending_sync' AND server.active_credential_revision IS NULL AND operation.candidate_credential_revision=1) OR (NEW.action<>'mcp.server_registered' AND operation.status='succeeded' AND NEW.created_at=operation.completed_at AND server.updated_at=operation.completed_at AND json_type(NEW.before_summary_json,'$.mcp_server_id')='text' AND json_extract(NEW.before_summary_json,'$.mcp_server_id')=server.mcp_server_id AND json_type(NEW.before_summary_json,'$.status')='text' AND json_extract(NEW.before_summary_json,'$.status') IN('pending_sync','active','sync_failed','disabled') AND json_type(NEW.before_summary_json,'$.state_revision')='integer' AND (json_extract(NEW.before_summary_json,'$.state_revision'))::NUMERIC =operation.start_server_revision AND server.state_revision=operation.start_server_revision+1 AND json_type(NEW.before_summary_json,'$.active_credential_revision') IN('integer','null') AND (json_extract(NEW.before_summary_json,'$.active_credential_revision'))::NUMERIC IS NOT DISTINCT FROM operation.start_credential_revision AND json_type(NEW.before_summary_json,'$.tool_count')='integer' AND (json_extract(NEW.before_summary_json,'$.tool_count'))::NUMERIC>=0 AND json_type(NEW.before_summary_json,'$.active_tool_count')='integer' AND (json_extract(NEW.before_summary_json,'$.active_tool_count'))::NUMERIC>=0 AND (NEW.action<>'mcp.server_disabled' OR server.status='disabled') AND (NEW.action<>'mcp.server_enabled' OR server.status='active') AND (NEW.action NOT IN('mcp.server_refreshed','mcp.server_credential_rotated') OR server.status='active') AND (NEW.action<>'mcp.server_credential_rotated' OR server.active_credential_revision=operation.candidate_credential_revision) AND (NEW.action='mcp.server_credential_rotated' OR operation.candidate_credential_revision IS NULL) AND (NEW.action IN('mcp.server_credential_rotated','mcp.server_registered') OR server.active_credential_revision IS NOT DISTINCT FROM operation.start_credential_revision)) ) ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='audit_log_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
