_type(NEW.before_summary_json,'$.schema_revision')='integer' AND json_type(NEW.before_summary_json,'$.policy_revision')='integer' AND json_type(NEW.before_summary_json,'$.risk_level')='text' AND json_extract(NEW.before_summary_json,'$.risk_level') IN('standard','high') AND json_type(NEW.before_summary_json,'$.approval_required') IN('true','false') AND json_type(NEW.before_summary_json,'$.required_permission_count') ='integer' AND (json_extract(NEW.before_summary_json,'$.required_permission_count'))::NUMERIC>=0 AND json_type(NEW.before_summary_json,'$.role_grant_count')='integer' AND (json_extract(NEW.before_summary_json,'$.role_grant_count'))::NUMERIC>=0 AND json_type(NEW.before_summary_json,'$.user_grant_count')='integer' AND (json_extract(NEW.before_summary_json,'$.user_grant_count'))::NUMERIC>=0 AND json_type(NEW.before_summary_json,'$.redaction_count')='integer' AND (json_extract(NEW.before_summary_json,'$.redaction_count'))::NUMERIC>=0 AND ((tool.schema_revision =(json_extract(NEW.before_summary_json,'$.schema_revision'))::NUMERIC+1 AND tool.policy_revision =(json_extract(NEW.before_summary_json,'$.policy_revision'))::NUMERIC+1 AND tool.status='review_required') OR (tool.schema_revision =(json_extract(NEW.before_summary_json,'$.schema_revision'))::NUMERIC AND tool.policy_revision =(json_extract(NEW.before_summary_json,'$.policy_revision'))::NUMERIC AND tool.status='disabled'))))) ) OR (NEW.action='mcp.tool_policy_updated' AND json_type(NEW.before_summary_json,'$.mcp_tool_id')='text' AND json_extract(NEW.before_summary_json,'$.mcp_tool_id')=tool.mcp_tool_id AND json_type(NEW.before_summary_json,'$.mcp_server_id')='text' AND json_extract(NEW.before_summary_json,'$.mcp_server_id')=tool.mcp_server_id AND json_type(NEW.before_summary_json,'$.policy_revision')='integer' AND (json_extract(NEW.before_summary_json,'$.policy_revision'))::NUMERIC+1 =tool.policy_revision AND json_type(NEW.before_summary_json,'$.schema_revision')='integer' AND (json_extract(NEW.before_summary_json,'$.schema_revision'))::NUMERIC =tool.schema_revision AND json_type(NEW.before_summary_json,'$.status')='text' AND json_extract(NEW.before_summary_json,'$.status') IN('review_required','active','disabled') AND json_type(NEW.before_summary_json,'$.risk_level')='text' AND json_extract(NEW.before_summary_json,'$.risk_level') IN('standard','high') AND json_type(NEW.before_summary_json,'$.approval_required') IN('true','false') AND json_type(NEW.before_summary_json,'$.required_permission_count')='integer' AND (json_extract(NEW.before_summary_json,'$.required_permission_count'))::NUMERIC>=0 AND json_type(NEW.before_summary_json,'$.redaction_count')='integer' AND (json_extract(NEW.before_summary_json,'$.redaction_count'))::NUMERIC>=0 AND json_type(NEW.after_summary_json,'$.status')='text' AND json_extract(NEW.after_summary_json,'$.status')=tool.status AND json_type(NEW.after_summary_json,'$.schema_revision')='integer' AND (json_extract(NEW.after_summary_json,'$.schema_revision'))::NUMERIC=tool.schema_revision AND json_type(NEW.after_summary_json,'$.risk_level')='text' AND json_extract(NEW.after_summary_json,'$.risk_level')=tool.risk_level AND json_type(NEW.after_summary_json,'$.approval_required') IN('true','false') AND (json_extract(NEW.after_summary_json,'$.approval_required'))::NUMERIC =tool.approval_required AND json_type(NEW.after_summary_json,'$.required_permission_count')='integer' AND (json_extract(NEW.after_summary_json,'$.required_permission_count'))::NUMERIC =json_array_length(tool.required_permission_codes_json) AND json_type(NEW.after_summary_json,'$.redaction_count')='integer' AND (json_extract(NEW.after_summary_json,'$.redaction_count'))::NUMERIC =json_array_length(tool.result_redaction_pointers_json)) OR (NEW.action='mcp.tool_grants_updated' AND json_type(NEW.before_summary_json,'$.mcp_tool_id')='text' AND json_extract(NEW.before_summary_json,'$.mcp_tool_id')=tool.mcp_tool_id AND json_type(NEW.before_summary_json,'$.mcp_server_id')='text' AND json_extract(NEW.before_summary_json,'$.mcp_server_id')=tool.mcp_server_id AND json_type(NEW.before_summary_json,'$.policy_revision')='integer' AND (json_extract(NEW.before_summary_json,'$.policy_revision'))::NUMERIC+1 =tool.policy_revision AND json_type(NEW.before_summary_json,'$.role_grant_count')='integer' AND (json_extract(NEW.before_summary_json,'$.role_grant_count'))::NUMERIC>=0 AND json_type(NEW.before_summary_json,'$.user_grant_count')='integer' AND (json_extract(NEW.before_summary_json,'$.user_grant_count'))::NUMERIC>=0 AND json_type(NEW.after_summary_json,'$.role_grant_count')='integer' AND (json_extract(NEW.after_summary_json,'$.role_grant_count'))::NUMERIC=( SELECT COUNT(*) FROM mcp_tool_role_grants role_grant WHERE role_grant.tenant_id=tool.tenant_id AND role_grant.mcp_tool_id=tool.mcp_tool_id) AND json_type(NEW.after_summary_json,'$.user_grant_count')='integer' AND (json_extract(NEW.after_summary_json,'$.user_grant_count'))::NUMERIC=( SELECT COUNT(*) FROM mcp_tool_user_grants user_grant WHERE user_grant.tenant_id=tool.tenant_id AND user_grant.mcp_tool_id=tool.mcp_tool_id)) ) ) )) THEN
