CREATE OR REPLACE FUNCTION "fn_trg_audit_logs_mcp_network_policy_insert_prd083"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF ((NEW.action='mcp.network_policy_updated' AND ( NEW.object_type<>'mcp_network_policy' OR NEW.object_name IS NOT NULL OR (SELECT COUNT(*) FROM json_each(NEW.before_summary_json))<>11 OR (SELECT COUNT(*) FROM json_each(NEW.after_summary_json))<>11 OR (SELECT COUNT(*) FROM json_each(NEW.before_summary_json)) <>(SELECT COUNT(DISTINCT key) FROM json_each(NEW.before_summary_json)) OR (SELECT COUNT(*) FROM json_each(NEW.after_summary_json)) <>(SELECT COUNT(DISTINCT key) FROM json_each(NEW.after_summary_json)) OR (SELECT COUNT(*) FROM json_each(NEW.changed_fields_json)) <>(SELECT COUNT(DISTINCT value) FROM json_each(NEW.changed_fields_json)) OR EXISTS(SELECT 1 FROM json_each(NEW.before_summary_json) field WHERE field.key NOT IN( 'mcp_server_id','status','revision','egress_mode','destination_count', 'connect_timeout_seconds','probe_timeout_seconds','call_timeout_seconds', 'failure_threshold','open_seconds','waiting_job_resume_count')) OR EXISTS(SELECT 1 FROM json_each(NEW.after_summary_json) field WHERE field.key NOT IN( 'mcp_server_id','status','revision','egress_mode','destination_count', 'connect_timeout_seconds','probe_timeout_seconds','call_timeout_seconds', 'failure_threshold','open_seconds','waiting_job_resume_count')) OR EXISTS(SELECT 1 FROM json_each(NEW.changed_fields_json) field WHERE field.type<>'text' OR field.value NOT IN( 'mcp_server_id','status','revision','egress_mode','destination_count', 'connect_timeout_seconds','probe_timeout_seconds','call_timeout_seconds', 'failure_threshold','open_seconds','waiting_job_resume_count')) OR NOT EXISTS( SELECT 1 FROM mcp_network_policies policy JOIN mcp_network_policy_revisions current ON current.tenant_id=policy.tenant_id AND current.mcp_network_policy_id=policy.mcp_network_policy_id AND current.policy_revision=policy.current_revision JOIN mcp_network_policy_revisions previous ON previous.tenant_id=current.tenant_id AND previous.mcp_network_policy_id=current.mcp_network_policy_id AND previous.policy_revision=current.policy_revision-1 JOIN users actor ON actor.tenant_id=current.tenant_id AND actor.user_id=current.updated_by WHERE policy.tenant_id=NEW.tenant_id AND policy.mcp_network_policy_id=NEW.object_id AND actor.status='active' AND NEW.actor_user_id=actor.user_id AND NEW.actor_email=actor.email AND NEW.actor_role=actor.role AND NEW.request_id=current.request_id AND NEW.trace_id=current.trace_id AND NEW.created_at=current.created_at AND policy.updated_at=current.created_at AND json_extract(NEW.before_summary_json,'$.mcp_server_id')=previous.mcp_server_id AND json_extract(NEW.after_summary_json,'$.mcp_server_id')=current.mcp_server_id AND json_extract(NEW.before_summary_json,'$.status')=previous.status AND json_extract(NEW.after_summary_json,'$.status')=current.status AND (json_extract(NEW.before_summary_json,'$.revision'))::NUMERIC=previous.policy_revision AND (json_extract(NEW.after_summary_json,'$.revision'))::NUMERIC=current.policy_revision AND json_extract(NEW.before_summary_json,'$.egress_mode')=previous.egress_mode AND json_extract(NEW.after_summary_json,'$.egress_mode')=current.egress_mode AND (json_extract(NEW.before_summary_json,'$.destination_count'))::NUMERIC =CASE previous.status WHEN 'active' THEN 1 ELSE 0 END AND (json_extract(NEW.after_summary_json,'$.destination_count'))::NUMERIC =CASE current.status WHEN 'active' THEN 1 ELSE 0 END AND (json_extract(NEW.before_summary_json,'$.connect_timeout_seconds'))::NUMERIC =previous.connect_timeout_seconds AND (json_extract(NEW.after_summary_json,'$.connect_timeout_seconds'))::NUMERIC =current.connect_timeout_seconds AND (json_extract(NEW.before_summary_json,'$.probe_timeout_seconds'))::NUMERIC =previous.probe_timeout_seconds AND (json_extract(NEW.after_summary_json,'$.probe_timeout_seconds'))::NUMERIC =current.probe_timeout_seconds AND (json_extract(NEW.before_summary_json,'$.call_timeout_seconds'))::NUMERIC =previous.call_timeout_seconds AND (json_extract(NEW.after_summary_json,'$.call_timeout_seconds'))::NUMERIC =current.call_timeout_seconds AND (json_extract(NEW.before_summary_json,'$.failure_threshold'))::NUMERIC =previous.failure_threshold AND (json_extract(NEW.after_summary_json,'$.failure_threshold'))::NUMERIC =current.failure_threshold AND (json_extract(NEW.before_summary_json,'$.open_seconds'))::NUMERIC=previous.open_seconds AND (json_extract(NEW.after_summary_json,'$.open_seconds'))::NUMERIC=current.open_seconds AND (json_extract(NEW.before_summary_json,'$.waiting_job_resume_count'))::NUMERIC=0 AND (json_extract(NEW.after_summary_json,'$.waiting_job_resume_count'))::NUMERIC=CASE WHEN previous.status='disabled' AND current.status='active' AND EXISTS(SELECT 1 FROM mcp_server_sync_jobs job WHERE job.tenant_id=current.tenant_id AND job.mcp_server_id=current.mcp_server_id AND job.status='pending' AND job.attempt_count=0 AND job.next_attempt_at=current.created_at AND job.updated_at=current.created_at) THEN 1 ELSE 0 END ) OR EXISTS( SELECT 1 FROM json_each( '["mcp_server_id","status","revision","egress_mode","destination_count",' ||'"connect_timeout_seconds","probe_timeout_seconds","call_timeout_seconds",' ||'"failure_threshold","open_seconds","waiting_job_resume_count"]' ) expected WHERE (json_extract(NEW.before_summary_json,'$.'||expected.value) IS DISTINCT FROM json_extract(NEW.after_summary_json,'$.'||expected.value)) <>EXISTS(SELECT 1 FROM json_each(NEW.changed_fields_json) actual WHERE actual.value=expected.value) ) )) OR (NEW.object_type='mcp_network_policy' AND NEW.action<>'mcp.network_policy_updated')) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='audit_log_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
