CREATE OR REPLACE FUNCTION "fn_trg_local_model_call_events_owner_insert_prd084"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.local_model_call_event_id<>'lmce_'||substr(metahub_sha256(NEW.routing_attempt_id),1,32) OR NOT EXISTS( SELECT 1 FROM routing_attempts attempt JOIN local_model_endpoints endpoint ON endpoint.tenant_id=attempt.tenant_id AND endpoint.provider_id=attempt.provider_id WHERE attempt.tenant_id=NEW.tenant_id AND attempt.routing_attempt_id=NEW.routing_attempt_id AND attempt.request_id=NEW.request_id AND attempt.trace_id=NEW.trace_id AND attempt.model_id=NEW.model_id AND attempt.provider_id=NEW.provider_id AND endpoint.local_endpoint_id=NEW.local_endpoint_id AND attempt.attempt_sequence=NEW.attempt_sequence AND attempt.attempt_role=NEW.attempt_role AND attempt.provider_call_status='called' AND NEW.execution_status='called' AND attempt.status IN('succeeded','failed') AND NEW.outcome=CASE WHEN attempt.error_code='gateway.local_endpoint_outcome_unknown' THEN 'outcome_unknown' ELSE attempt.status END AND NEW.error_code IS NOT DISTINCT FROM attempt.error_code AND NEW.error_category IS NOT DISTINCT FROM attempt.error_category AND NEW.http_status IS NOT DISTINCT FROM attempt.upstream_http_status AND NEW.retryable=attempt.retryable AND NEW.latency_ms IS NOT DISTINCT FROM attempt.latency_ms AND NEW.usage_status=attempt.usage_status AND NEW.completed_at=attempt.completed_at) OR EXISTS(SELECT 1 FROM local_model_call_events current WHERE current.local_model_call_event_id=NEW.local_model_call_event_id OR(current.tenant_id=NEW.tenant_id AND current.routing_attempt_id=NEW.routing_attempt_id) OR(NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='local_model_call_event_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
