  IF (NEW.local_model_call_event_outbox_id<>'lmco_'|| substr(metahub_sha256(NEW.local_model_call_event_id),1,32) OR NEW.status<>'pending' OR NEW.attempt_count<>0 OR NEW.lease_generation<>0 OR NEW.created_at<>NEW.updated_at OR NEW.next_attempt_at<NEW.created_at OR NOT EXISTS(SELECT 1 FROM local_model_call_events event WHERE event.tenant_id=NEW.tenant_id AND event.local_model_call_event_id=NEW.local_model_call_event_id) OR EXISTS(SELECT 1 FROM local_model_call_event_outbox current WHERE current.local_model_call_event_outbox_id=NEW.local_model_call_event_outbox_id OR(current.tenant_id=NEW.tenant_id AND current.local_model_call_event_id=NEW.local_model_call_event_id) OR(NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
