CREATE OR REPLACE FUNCTION "fn_trg_local_model_call_outbox_transition_prd084"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.local_model_call_event_outbox_id<>OLD.local_model_call_event_outbox_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.local_model_call_event_id<>OLD.local_model_call_event_id OR NEW.created_at<>OLD.created_at OR NEW.updated_at<OLD.updated_at OR NOT( (OLD.status='pending' AND NEW.status='leased' AND NEW.attempt_count=OLD.attempt_count+1 AND NEW.lease_generation=OLD.lease_generation+1) OR(OLD.status='leased' AND NEW.status='leased' AND NEW.attempt_count=OLD.attempt_count AND NEW.lease_generation=OLD.lease_generation+1) OR(OLD.status='leased' AND NEW.status='pending' AND NEW.attempt_count=OLD.attempt_count AND NEW.lease_generation=OLD.lease_generation+1) OR(OLD.status='leased' AND NEW.status IN('sent','failed') AND NEW.attempt_count=OLD.attempt_count AND NEW.lease_generation=OLD.lease_generation+1))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='local_model_call_outbox_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
