CREATE OR REPLACE FUNCTION "fn_trg_routing_attempt_local_owner_insert_prd084"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (( EXISTS(SELECT 1 FROM providers provider WHERE provider.tenant_id=NEW.tenant_id AND provider.provider_id=NEW.provider_id AND provider.provider_type='local_endpoint') AND(length(NEW.routing_attempt_id)<>36 OR substr(NEW.routing_attempt_id,1,4)<>'rta_' OR substr(NEW.routing_attempt_id,5) OPERATOR(public.@@) '*[^0-9a-f]*' OR NEW.status<>'started' OR NEW.provider_call_status<>'not_called' OR NEW.provider_call_started_at IS NOT NULL OR NOT EXISTS(SELECT 1 FROM local_model_endpoints endpoint JOIN models model ON model.tenant_id=endpoint.tenant_id AND model.provider_id=endpoint.provider_id WHERE endpoint.tenant_id=NEW.tenant_id AND endpoint.provider_id=NEW.provider_id AND endpoint.status='active' AND endpoint.local_endpoint_id IS NOT NULL AND model.model_id=NEW.model_id)) ) OR( NOT EXISTS(SELECT 1 FROM providers provider WHERE provider.tenant_id=NEW.tenant_id AND provider.provider_id=NEW.provider_id AND provider.provider_type='local_endpoint') AND(NEW.provider_call_status<>'not_applicable' OR NEW.provider_call_started_at IS NOT NULL))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='routing_attempt_local_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
