BEGIN
  IF (NEW.product_event_id<>'pev_'||substr(metahub_sha256((jsonb_build_array( NEW.tenant_id,NEW.event_type,NEW.source_kind,NEW.source_id)::TEXT)),1,32) OR NEW.status<>'recorded' OR NEW.updated_at<>NEW.created_at OR EXISTS(SELECT 1 FROM product_events current WHERE current.product_event_id=NEW.product_event_id OR(current.tenant_id=NEW.tenant_id AND current.source_kind=NEW.source_kind AND current.source_id=NEW.source_id AND current.event_type=NEW.event_type) OR(NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid)) OR NOT( (NEW.source_kind='tenant' AND NEW.event_type='tenant.registered' AND NEW.capture_mode='backfill' AND NEW.actor_user_id IS NULL AND NEW.source_id=NEW.tenant_id AND NEW.operation_request_id IS NULL AND NEW.operation_trace_id IS NULL AND EXISTS(SELECT 1 FROM tenants source WHERE source.tenant_id=NEW.tenant_id AND source.created_at=NEW.occurred_at)) OR(NEW.source_kind='seed_run' AND NEW.event_type='tenant.registered' AND NEW.capture_mode='backfill' AND NEW.actor_user_id IS NULL AND NEW.operation_request_id IS NULL AND NEW.operation_trace_id IS NULL AND EXISTS(SELECT 1 FROM seed_runs source WHERE source.seed_run_id=NEW.source_id AND source.tenant_id=NEW.tenant_id AND source.status='applied' AND source.created_at=NEW.occurred_at)) OR(NEW.source_kind='audit_log' AND NEW.capture_mode='live' AND EXISTS(SELECT 1 FROM audit_logs source WHERE source.audit_log_id=NEW.source_id AND source.tenant_id=NEW.tenant_id AND source.actor_user_id=NEW.actor_user_id AND source.request_id=NEW.operation_request_id AND source.trace_id=NEW.operation_trace_id AND source.created_at=NEW.occurred_at AND( (NEW.event_type='provider.created' AND( source.action='provider.created' OR(source.action='config.imported' AND json_type(source.after_summary_json,'$.providers_created_count')='integer' AND (json_extract(source.after_summary_json,'$.providers_created_count'))::NUMERIC>0))) OR(NEW.event_type='virtual_key.created' AND( source.action='virtual_key.created' OR(source.action='config.imported' AND json_type(source.after_summary_json,'$.virtual_keys_created_count')='integer' AND (json_extract(source.after_summary_json,'$.virtual_keys_created_count'))::NUMERIC>0))) OR(NEW.event_type='budget.configured' AND source.action IN('budget_rule.created','budget_rule.updated')) OR(NEW.event_type='teammate.invited' AND source.action='user_row.invited')))) OR(NEW.source_kind='request_log' AND NEW.event_type='gateway.first_call_succeeded' AND NEW.capture_mode='live' AND NEW.actor_user_id IS NULL AND NEW.source_id=NEW.operation_request_id AND EXISTS(SELECT 1 FROM request_logs source WHERE source.tenant_id=NEW.tenant_id AND source.request_id=NEW.source_id AND source.status='success' AND source.trace_id=NEW.operation_trace_id AND NEW.occurred_at IN(source.created_at,COALESCE(source.updated_at,source.created_at)))) OR(NEW.source_kind='request_log_query' AND NEW.event_type='request_logs.viewed' AND NEW.capture_mode='live' AND EXISTS(SELECT 1 FROM request_log_query_events source WHERE source.query_event_id=NEW.source_id AND source.tenant_id=NEW.tenant_id AND source.actor_user_id=NEW.actor_user_id AND source.operation_request_id=NEW.operation_request_id AND source.operation_trace_id=NEW.operation_trace_id AND source.executed_at=NEW.occurred_at)))) THEN
