CREATE OR REPLACE FUNCTION "fn_trg_customer_health_scheduler_transition_prd086"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.tenant_id<>OLD.tenant_id OR NEW.created_at<>OLD.created_at OR unixepoch(NEW.updated_at)<unixepoch(OLD.updated_at) OR NOT( (OLD.status='pending' AND NEW.status='leased' AND NEW.generation=OLD.generation+1 AND NEW.consecutive_failure_count=OLD.consecutive_failure_count AND NEW.next_evaluation_at=OLD.next_evaluation_at AND NEW.last_completed_window_end IS NOT DISTINCT FROM OLD.last_completed_window_end AND NEW.last_error_code IS NULL AND unixepoch(NEW.lease_expires_at)>unixepoch(NEW.updated_at)) OR(OLD.status='leased' AND NEW.status='leased' AND unixepoch(OLD.lease_expires_at)<=unixepoch(NEW.updated_at) AND NEW.generation=OLD.generation+1 AND NEW.consecutive_failure_count=OLD.consecutive_failure_count AND NEW.next_evaluation_at=OLD.next_evaluation_at AND NEW.last_completed_window_end IS NOT DISTINCT FROM OLD.last_completed_window_end AND NEW.last_error_code IS NULL AND NEW.lease_token<>OLD.lease_token AND unixepoch(NEW.lease_expires_at)>unixepoch(NEW.updated_at)) OR(OLD.status='leased' AND NEW.status='leased' AND unixepoch(OLD.lease_expires_at)>unixepoch(NEW.updated_at) AND NEW.generation=OLD.generation+1 AND NEW.consecutive_failure_count=OLD.consecutive_failure_count AND NEW.next_evaluation_at=OLD.next_evaluation_at AND NEW.last_completed_window_end IS NOT DISTINCT FROM OLD.last_completed_window_end AND NEW.last_error_code IS NULL AND NEW.lease_owner_id=OLD.lease_owner_id AND NEW.lease_token<>OLD.lease_token AND unixepoch(NEW.lease_expires_at)>unixepoch(OLD.lease_expires_at)) OR(OLD.status='leased' AND NEW.status='pending' AND NEW.generation=OLD.generation+1 AND NEW.consecutive_failure_count=0 AND NEW.last_error_code IS NULL AND unixepoch(OLD.lease_expires_at)>unixepoch(NEW.updated_at) AND NEW.last_completed_window_end IS NOT NULL AND(OLD.last_completed_window_end IS NULL OR unixepoch(NEW.last_completed_window_end)>=unixepoch(OLD.last_completed_window_end)) AND unixepoch(NEW.next_evaluation_at)>unixepoch(NEW.updated_at)) OR(OLD.status='leased' AND NEW.status='pending' AND NEW.generation=OLD.generation+1 AND NEW.consecutive_failure_count=OLD.consecutive_failure_count+1 AND NEW.last_completed_window_end IS NOT DISTINCT FROM OLD.last_completed_window_end AND NEW.last_error_code='customer_health.unavailable' AND unixepoch(OLD.lease_expires_at)>unixepoch(NEW.updated_at) AND unixepoch(NEW.next_evaluation_at)>unixepoch(NEW.updated_at)))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='customer_health_scheduler_transition_invalid';
  END IF;
  RETURN NEW;
END;
