CREATE OR REPLACE FUNCTION "fn_trg_customer_health_scores_owner_insert_prd086"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.customer_health_score_id<>'chs_'||substr(metahub_sha256((jsonb_build_array( 'customer-health-score-v1',NEW.tenant_id,NEW.score_version, NEW.window_end,NEW.source_fingerprint)::TEXT)),1,32) OR NEW.source_fingerprint<>metahub_sha256((jsonb_build_array( 'customer-health-source-v1',NEW.tenant_id,NEW.score_version, NEW.window_start,NEW.window_end,NEW.comparison_start,NEW.comparison_end, NEW.current_request_count,NEW.previous_request_count, NEW.successful_request_count,NEW.failed_request_count, NEW.unresolved_cost_anomaly_count,NEW.critical_cost_anomaly_count, NEW.active_budget_rule_count,NEW.eligible_user_count, NEW.recently_active_user_count,NEW.ticket_source_status, NEW.activation_stage_count)::TEXT)) OR NEW.operation_request_id<>'req_chs_'||substr(metahub_sha256((jsonb_build_array( 'customer-health-operation-v1',NEW.tenant_id,NEW.window_end, NEW.source_fingerprint)::TEXT)),1,32) OR NEW.operation_trace_id<>'trc_chs_'||substr(metahub_sha256((jsonb_build_array( 'customer-health-operation-v1',NEW.tenant_id,NEW.window_end, NEW.source_fingerprint)::TEXT)),1,32) OR NEW.usage_trend_score_bps<>CASE WHEN NEW.current_request_count=0 THEN 0 WHEN NEW.previous_request_count=0 THEN 10000 WHEN (NEW.current_request_count*10000)/NEW.previous_request_count>10000 THEN 10000 ELSE (NEW.current_request_count*10000)/NEW.previous_request_count END OR NEW.reliability_score_bps<>CASE WHEN NEW.current_request_count=0 THEN 5000 ELSE (NEW.successful_request_count*10000)/NEW.current_request_count +CASE WHEN ((NEW.successful_request_count*10000)%NEW.current_request_count)*2 >=NEW.current_request_count THEN 1 ELSE 0 END END OR NEW.cost_anomaly_health_score_bps<>CASE WHEN NEW.critical_cost_anomaly_count>0 THEN 0 WHEN NEW.unresolved_cost_anomaly_count>0 THEN 4000 ELSE 10000 END OR NEW.budget_readiness_score_bps<>CASE WHEN NEW.active_budget_rule_count>0 THEN 10000 ELSE 3000 END OR NEW.team_activity_score_bps<>CASE WHEN NEW.eligible_user_count=0 THEN 0 ELSE (NEW.recently_active_user_count*10000)/NEW.eligible_user_count +CASE WHEN ((NEW.recently_active_user_count*10000)%NEW.eligible_user_count)*2 >=NEW.eligible_user_count THEN 1 ELSE 0 END END OR NEW.score_bps<>( NEW.usage_trend_score_bps*2500+NEW.reliability_score_bps*2500+ NEW.cost_anomaly_health_score_bps*1500+NEW.budget_readiness_score_bps*1000+ NEW.team_activity_score_bps*1500+4500)/9000 OR EXISTS( WITH components(ordinal,score,weight,contribution) AS(VALUES (1,NEW.usage_trend_score_bps,2500,NEW.usage_trend_contribution_bps), (2,NEW.reliability_score_bps,2500,NEW.reliability_contribution_bps), (3,NEW.cost_anomaly_health_score_bps,1500,NEW.cost_anomaly_health_contribution_bps), (4,NEW.budget_readiness_score_bps,1000,NEW.budget_readiness_contribution_bps), (5,NEW.team_activity_score_bps,1500,NEW.team_activity_contribution_bps)), calculated AS(SELECT ordinal,contribution,(score*weight)/9000 AS base, (score*weight)%9000 AS remainder FROM components), totals AS(SELECT NEW.score_bps-SUM(base) AS extras FROM calculated) SELECT 1 FROM calculated candidate,totals WHERE candidate.contribution<>candidate.base+CASE WHEN( SELECT COUNT(*) FROM calculated ahead WHERE ahead.remainder>candidate.remainder OR(ahead.remainder=candidate.remainder AND ahead.ordinal<candidate.ordinal) )<totals.extras THEN 1 ELSE 0 END) OR NEW.usage_declining<>CASE WHEN NEW.current_request_count=0 OR(NEW.previous_request_count>0 AND (NEW.current_request_count*10000)/NEW.previous_request_count<5000) THEN 1 ELSE 0 END OR NEW.high_error_rate<>CASE WHEN NEW.current_request_count>=5 AND 10000-NEW.reliability_score_bps>=500 THEN 1 ELSE 0 END OR NEW.cost_anomaly_open<>CASE WHEN NEW.unresolved_cost_anomaly_count>0 THEN 1 ELSE 0 END OR NEW.budget_missing<>CASE WHEN NEW.active_budget_rule_count=0 THEN 1 ELSE 0 END OR NEW.team_inactive<>CASE WHEN NEW.recently_active_user_count=0 OR(NEW.eligible_user_count>=2 AND NEW.team_activity_score_bps<5000) THEN 1 ELSE 0 END OR NEW.risk_level<>CASE WHEN NEW.score_bps<3000 OR NEW.critical_cost_anomaly_count>0 THEN 'critical' WHEN NEW.score_bps<6000 OR NEW.current_request_count=0 OR(NEW.current_request_count>=5 AND 10000-NEW.reliability_score_bps>=1000) THEN 'at_risk' WHEN NEW.score_bps<8000 OR NEW.unresolved_cost_anomaly_count>0 OR(NEW.current_request_count>=5 AND 10000-NEW.reliability_score_bps>=500) THEN 'watch' ELSE 'healthy' END OR NEW.health_projection_sha256<>metahub_sha256((jsonb_build_array( 'customer-health-projection-v1',NEW.score_version, NEW.usage_trend_score_bps,NEW.usage_trend_contribution_bps, CASE WHEN NEW.current_request_count=0 AND NEW.previous_request_count=0 THEN 'no_samples' ELSE 'available' END, CASE WHEN NEW.usage_trend_score_bps>=8000 THEN 'healthy' WHEN NEW.usage_trend_score_bps>=6000 THEN 'watch' WHEN NEW.usage_trend_score_bps>=3000 THEN 'at_risk' ELSE 'critical' END, NEW.reliability_score_bps,NEW.reliability_contribution_bps, CASE WHEN NEW.current_request_count=0 THEN 'no_samples' ELSE 'available' END, CASE WHEN NEW.current_request_count=0 THEN 'unknown' WHEN NEW.reliability_score_bps>=8000 THEN 'healthy' WHEN NEW.reliability_score_bps>=6000 THEN 'watch' WHEN NEW.reliability_score_bps>=3000 THEN 'at_risk' ELSE 'critical' END, NEW.cost_anomaly_health_score_bps,NEW.cost_anomaly_health_contribution_bps,'available', CASE WHEN NEW.cost_anomaly_health_score_bps>=8000 THEN 'healthy' WHEN NEW.cost_anomaly_health_score_bps>=6000 THEN 'watch' WHEN NEW.cost_anomaly_health_score_bps>=3000 THEN 'at_risk' ELSE 'critical' END, NEW.budget_readiness_score_bps,NEW.budget_readiness_contribution_bps,'available', CASE WHEN NEW.budget_readiness_score_bps>=8000 THEN 'healthy' WHEN NEW.budget_readiness_score_bps>=6000 THEN 'watch' WHEN NEW.budget_readiness_score_bps>=3000 THEN 'at_risk' ELSE 'critical' END, NEW.team_activity_score_bps,NEW.team_activity_contribution_bps, CASE WHEN NEW.eligible_user_count=0 THEN 'no_samples' ELSE 'available' END, CASE WHEN NEW.team_activity_score_bps>=8000 THEN 'healthy' WHEN NEW.team_activity_score_bps>=6000 THEN 'watch' WHEN NEW.team_activity_score_bps>=3000 THEN 'at_risk' ELSE 'critical' END, NULL,0,'unavailable','unknown',NEW.effective_weight_bps,NEW.score_bps,NEW.risk_level, NEW.usage_declining,NEW.high_error_rate,NEW.cost_anomaly_open, NEW.budget_missing,NEW.team_inactive,'ticket_health')::TEXT)) OR NOT EXISTS(SELECT 1 FROM customer_health_scheduler_tenants scheduler WHERE scheduler.tenant_id=NEW.tenant_id AND scheduler.status='leased' AND unixepoch(scheduler.lease_expires_at)>unixepoch(NEW.evaluated_at)) OR EXISTS(SELECT 1 FROM customer_health_scores current WHERE current.customer_health_score_id=NEW.customer_health_score_id OR(current.tenant_id=NEW.tenant_id AND current.window_end=NEW.window_end AND current.source_fingerprint=NEW.source_fingerprint) OR(NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='customer_health_score_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
