CREATE OR REPLACE FUNCTION "fn_trg_customer_health_outbox_owner_insert_prd086"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.customer_health_score_outbox_id<>'chso_'|| substr(metahub_sha256(NEW.customer_health_score_id),1,32) OR NEW.webhook_event_id<>'evt_chs_'|| substr(metahub_sha256(NEW.customer_health_score_id),1,32) OR NEW.status<>'pending' OR NEW.attempt_count<>0 OR NEW.generation<>0 OR NEW.lease_owner_id IS NOT NULL OR NEW.lease_token IS NOT NULL OR NEW.lease_expires_at IS NOT NULL OR NEW.last_error_code IS NOT NULL OR NEW.delivered_at IS NOT NULL OR NEW.subscription_snapshot_json IS NOT NULL OR NEW.snapshot_frozen_at IS NOT NULL OR NEW.next_attempt_at<>NEW.created_at OR NEW.updated_at<>NEW.created_at OR NOT EXISTS(SELECT 1 FROM customer_health_scores score WHERE score.tenant_id=NEW.tenant_id AND score.customer_health_score_id=NEW.customer_health_score_id AND score.created_at=NEW.created_at) OR NOT EXISTS(SELECT 1 FROM customer_health_scores score WHERE score.tenant_id=NEW.tenant_id AND score.customer_health_score_id=NEW.customer_health_score_id AND(NOT EXISTS(SELECT 1 FROM customer_health_scores previous WHERE previous.tenant_id=score.tenant_id AND previous.customer_health_score_sequence<score.customer_health_score_sequence) OR score.health_projection_sha256<>( SELECT previous.health_projection_sha256 FROM customer_health_scores previous WHERE previous.tenant_id=score.tenant_id AND previous.customer_health_score_sequence<score.customer_health_score_sequence ORDER BY previous.customer_health_score_sequence DESC LIMIT 1))) OR EXISTS(SELECT 1 FROM customer_health_score_outbox current WHERE current.customer_health_score_outbox_id=NEW.customer_health_score_outbox_id OR(current.tenant_id=NEW.tenant_id AND current.customer_health_score_id=NEW.customer_health_score_id) OR(current.tenant_id=NEW.tenant_id AND current.webhook_event_id=NEW.webhook_event_id) OR(NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='customer_health_outbox_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
