CREATE OR REPLACE FUNCTION "fn_trg_customer_health_outbox_transition_prd086"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.customer_health_score_outbox_id<>OLD.customer_health_score_outbox_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.customer_health_score_id<>OLD.customer_health_score_id OR NEW.webhook_event_id<>OLD.webhook_event_id OR NEW.created_at<>OLD.created_at OR unixepoch(NEW.updated_at)<unixepoch(OLD.updated_at) OR NOT((NEW.subscription_snapshot_json IS NOT DISTINCT FROM OLD.subscription_snapshot_json AND NEW.snapshot_frozen_at IS NOT DISTINCT FROM OLD.snapshot_frozen_at) OR(OLD.status='pending' AND NEW.status='leased' AND OLD.subscription_snapshot_json IS NULL AND OLD.snapshot_frozen_at IS NULL AND NEW.subscription_snapshot_json IS NOT NULL AND NEW.snapshot_frozen_at IS NOT NULL)) OR NOT( (OLD.status='pending' AND NEW.status='leased' AND NEW.attempt_count=OLD.attempt_count+1 AND NEW.generation=OLD.generation+1 AND unixepoch(NEW.lease_expires_at)>unixepoch(NEW.updated_at)) OR(OLD.status='leased' AND NEW.status='leased' AND NEW.attempt_count=OLD.attempt_count AND NEW.generation=OLD.generation+1 AND unixepoch(OLD.lease_expires_at)<=unixepoch(NEW.updated_at) AND NEW.lease_token<>OLD.lease_token AND unixepoch(NEW.lease_expires_at)>unixepoch(NEW.updated_at)) OR(OLD.status='leased' AND NEW.status='leased' AND NEW.attempt_count=OLD.attempt_count AND NEW.generation=OLD.generation+1 AND unixepoch(OLD.lease_expires_at)>unixepoch(NEW.updated_at) AND NEW.lease_owner_id=OLD.lease_owner_id AND NEW.lease_token<>OLD.lease_token AND unixepoch(NEW.lease_expires_at)>unixepoch(OLD.lease_expires_at)) OR(OLD.status='leased' AND NEW.status='pending' AND NEW.attempt_count=OLD.attempt_count AND NEW.generation=OLD.generation+1 AND unixepoch(OLD.lease_expires_at)>unixepoch(NEW.updated_at)) OR(OLD.status='leased' AND NEW.status IN('sent','failed') AND NEW.attempt_count=OLD.attempt_count AND NEW.generation=OLD.generation+1 AND unixepoch(OLD.lease_expires_at)>unixepoch(NEW.updated_at)))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='customer_health_outbox_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
