LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.status<>'pending' OR NEW.generation<>0 OR NEW.scan_upper_sequence IS NOT NULL OR NEW.lease_owner_id IS NOT NULL OR NEW.lease_token IS NOT NULL OR NEW.lease_expires_at IS NOT NULL OR NEW.last_error_code IS NOT NULL OR NEW.consecutive_failure_count<>0 OR NEW.next_run_at<>NEW.created_at OR NEW.updated_at<>NEW.created_at OR NOT EXISTS(SELECT 1 FROM partner_customers customer WHERE customer.tenant_id=NEW.tenant_id AND customer.partner_customer_id=NEW.partner_customer_id AND customer.partner_id=NEW.partner_id AND customer.project_id=NEW.project_id AND customer.status='active' AND customer.linked_from_ledger_sequence=NEW.last_scanned_ledger_sequence) OR EXISTS(SELECT 1 FROM partner_commission_cursors current WHERE(current.tenant_id=NEW.tenant_id AND current.partner_customer_id=NEW.partner_customer_id) OR(NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
