CREATE OR REPLACE FUNCTION "fn_trg_partner_commission_cursor_transition_prd087"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.tenant_id<>OLD.tenant_id OR NEW.partner_customer_id<>OLD.partner_customer_id OR NEW.partner_id<>OLD.partner_id OR NEW.project_id<>OLD.project_id OR NEW.created_at<>OLD.created_at OR unixepoch(NEW.updated_at)<unixepoch(OLD.updated_at) OR NOT EXISTS(SELECT 1 FROM partner_customers customer WHERE customer.tenant_id=NEW.tenant_id AND customer.partner_customer_id=NEW.partner_customer_id AND customer.partner_id=NEW.partner_id AND customer.project_id=NEW.project_id) OR NOT( (OLD.status='pending' AND NEW.status='leased' AND NEW.generation=OLD.generation+1 AND NEW.last_scanned_ledger_sequence=OLD.last_scanned_ledger_sequence AND NEW.consecutive_failure_count=OLD.consecutive_failure_count AND NEW.scan_upper_sequence>=OLD.last_scanned_ledger_sequence AND NEW.scan_upper_sequence=(SELECT CASE WHEN customer.commission_cutoff_sequence IS NOT NULL AND customer.commission_cutoff_sequence<( SELECT COALESCE(MAX(entry.ledger_sequence),0) FROM finops_ledger_entries entry WHERE entry.tenant_id=NEW.tenant_id) THEN customer.commission_cutoff_sequence ELSE(SELECT COALESCE(MAX(entry.ledger_sequence),0) FROM finops_ledger_entries entry WHERE entry.tenant_id=NEW.tenant_id) END FROM partner_customers customer WHERE customer.tenant_id=NEW.tenant_id AND customer.partner_customer_id=NEW.partner_customer_id) AND unixepoch(NEW.lease_expires_at)>unixepoch(NEW.updated_at)) OR(OLD.status='leased' AND NEW.status='leased' AND NEW.generation=OLD.generation+1 AND NEW.last_scanned_ledger_sequence=OLD.last_scanned_ledger_sequence AND NEW.scan_upper_sequence=OLD.scan_upper_sequence AND NEW.consecutive_failure_count=OLD.consecutive_failure_count AND NEW.lease_token<>OLD.lease_token AND unixepoch(NEW.lease_expires_at)>unixepoch(NEW.updated_at) AND((unixepoch(OLD.lease_expires_at)<=unixepoch(NEW.updated_at)) OR(NEW.lease_owner_id=OLD.lease_owner_id AND unixepoch(NEW.lease_expires_at)>unixepoch(OLD.lease_expires_at)))) OR(OLD.status='leased' AND NEW.status='pending' AND NEW.generation=OLD.generation+1 AND unixepoch(OLD.lease_expires_at)>unixepoch(NEW.updated_at) AND NEW.last_scanned_ledger_sequence BETWEEN OLD.last_scanned_ledger_sequence AND OLD.scan_upper_sequence AND((NEW.last_error_code IS NULL AND NEW.consecutive_failure_count=0) OR(NEW.last_error_code='partner.commission_unavailable' AND NEW.last_scanned_ledger_sequence=OLD.last_scanned_ledger_sequence AND NEW.consecutive_failure_count=OLD.consecutive_failure_count+1))) OR(OLD.status='leased' AND NEW.status='complete' AND NEW.generation=OLD.generation+1 AND unixepoch(OLD.lease_expires_at)>unixepoch(NEW.updated_at) AND NEW.last_error_code IS NULL AND NEW.consecutive_failure_count=0 AND NEW.last_scanned_ledger_sequence=OLD.scan_upper_sequence AND EXISTS(SELECT 1 FROM partner_customers customer WHERE customer.tenant_id=NEW.tenant_id AND customer.partner_customer_id=NEW.partner_customer_id AND customer.status='disabled' AND customer.commission_cutoff_sequence=NEW.last_scanned_ledger_sequence)))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='partner_commission_cursor_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
