CREATE OR REPLACE FUNCTION "fn_trg_partner_customer_outbox_owner_insert_prd087"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.partner_customer_outbox_id<>'pco_'||substr(metahub_sha256( NEW.partner_customer_id),1,32) OR NEW.webhook_event_id<>'evt_pcu_'||substr(metahub_sha256( NEW.partner_customer_id),1,32) OR NEW.status<>'pending' OR NEW.attempt_count<>0 OR NEW.generation<>0 OR NEW.lease_owner_id IS NOT NULL OR NEW.lease_token IS NOT NULL OR NEW.lease_expires_at IS NOT NULL OR NEW.last_error_code IS NOT NULL OR NEW.delivered_at IS NOT NULL OR NEW.subscription_snapshot_json IS NOT NULL OR NEW.snapshot_frozen_at IS NOT NULL OR NEW.next_attempt_at<>NEW.created_at OR NEW.updated_at<>NEW.created_at OR NEW.event_timestamp<>NEW.created_at OR NEW.payload_sha256<>metahub_sha256(NEW.payload_json) OR(SELECT COUNT(*) FROM json_each(NEW.payload_json))<>7 OR EXISTS(SELECT 1 FROM json_each(NEW.payload_json) WHERE key NOT IN('schema_version','partner_id','partner_customer_id','customer_code', 'project_id','status','commission_rate_bps')) OR NOT EXISTS(SELECT 1 FROM partner_customers customer WHERE customer.tenant_id=NEW.tenant_id AND customer.partner_id=NEW.partner_id AND customer.partner_customer_id=NEW.partner_customer_id AND customer.created_by_user_id=NEW.actor_user_id AND customer.operation_request_id=NEW.source_request_id AND customer.operation_trace_id=NEW.source_trace_id AND customer.created_at=NEW.created_at AND customer.status='active' AND json_extract(NEW.payload_json,'$.schema_version')='1.0' AND json_extract(NEW.payload_json,'$.partner_id')=customer.partner_id AND json_extract(NEW.payload_json,'$.partner_customer_id')=customer.partner_customer_id AND json_extract(NEW.payload_json,'$.customer_code')=customer.customer_code AND json_extract(NEW.payload_json,'$.project_id')=customer.project_id AND json_extract(NEW.payload_json,'$.status')='active' AND (json_extract(NEW.payload_json,'$.commission_rate_bps'))::NUMERIC=customer.commission_rate_bps) OR EXISTS(SELECT 1 FROM partner_customer_outbox current WHERE current.partner_customer_outbox_id=NEW.partner_customer_outbox_id OR(current.tenant_id=NEW.tenant_id AND current.partner_customer_id=NEW.partner_customer_id) OR(current.tenant_id=NEW.tenant_id AND current.webhook_event_id=NEW.webhook_event_id) OR(NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='partner_customer_outbox_owner_mismatch';
  END IF;
  RETURN NEW;
END;
