CREATE OR REPLACE FUNCTION "fn_trg_partner_customer_outbox_transition_prd087"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.partner_customer_outbox_id<>OLD.partner_customer_outbox_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.partner_id<>OLD.partner_id OR NEW.partner_customer_id<>OLD.partner_customer_id OR NEW.webhook_event_id<>OLD.webhook_event_id OR NEW.actor_user_id<>OLD.actor_user_id OR NEW.source_request_id<>OLD.source_request_id OR NEW.source_trace_id<>OLD.source_trace_id OR NEW.event_timestamp<>OLD.event_timestamp OR NEW.payload_json<>OLD.payload_json OR NEW.payload_sha256<>OLD.payload_sha256 OR NEW.created_at<>OLD.created_at OR unixepoch(NEW.updated_at)<unixepoch(OLD.updated_at) OR NOT((NEW.subscription_snapshot_json IS NOT DISTINCT FROM OLD.subscription_snapshot_json AND NEW.snapshot_frozen_at IS NOT DISTINCT FROM OLD.snapshot_frozen_at) OR(OLD.status='pending' AND NEW.status='leased' AND OLD.subscription_snapshot_json IS NULL AND OLD.snapshot_frozen_at IS NULL AND NEW.subscription_snapshot_json IS NOT NULL AND NEW.snapshot_frozen_at IS NOT NULL)) OR NOT( (OLD.status='pending' AND NEW.status='leased' AND NEW.attempt_count=OLD.attempt_count+1 AND NEW.generation=OLD.generation+1 AND unixepoch(NEW.lease_expires_at)>unixepoch(NEW.updated_at)) OR(OLD.status='leased' AND NEW.status='leased' AND NEW.attempt_count=OLD.attempt_count AND NEW.generation=OLD.generation+1 AND NEW.lease_token<>OLD.lease_token AND unixepoch(NEW.lease_expires_at)>unixepoch(NEW.updated_at) AND((unixepoch(OLD.lease_expires_at)<=unixepoch(NEW.updated_at)) OR(NEW.lease_owner_id=OLD.lease_owner_id AND unixepoch(NEW.lease_expires_at)>unixepoch(OLD.lease_expires_at)))) OR(OLD.status='leased' AND NEW.status='pending' AND NEW.attempt_count=OLD.attempt_count AND NEW.generation=OLD.generation+1 AND unixepoch(OLD.lease_expires_at)>unixepoch(NEW.updated_at)) OR(OLD.status='leased' AND NEW.status IN('sent','failed') AND NEW.attempt_count=OLD.attempt_count AND NEW.generation=OLD.generation+1 AND unixepoch(OLD.lease_expires_at)>unixepoch(NEW.updated_at)))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='partner_customer_outbox_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
