CREATE TRIGGER "trg_branding_events_delete_prd088" BEFORE DELETE ON "branding_events" FOR EACH ROW EXECUTE FUNCTION "fn_trg_branding_events_delete_prd088"();
CREATE OR REPLACE FUNCTION "fn_trg_branding_events_owner_insert_prd088"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS(SELECT 1 FROM branding_configs config WHERE config.tenant_id=NEW.tenant_id AND config.branding_config_id=NEW.branding_config_id AND config.revision=NEW.revision) OR NOT EXISTS(SELECT 1 FROM users actor WHERE actor.tenant_id=NEW.tenant_id AND actor.user_id=NEW.actor_user_id) OR NOT EXISTS(SELECT 1 FROM audit_logs audit WHERE audit.tenant_id=NEW.tenant_id AND audit.audit_log_id=NEW.audit_log_id) OR NEW.branding_event_id<>'bev_'||substr(metahub_sha256( NEW.branding_config_id||chr(31)||NEW.revision),1,32) OR NOT EXISTS(SELECT 1 FROM audit_logs audit WHERE audit.tenant_id=NEW.tenant_id AND audit.audit_log_id=NEW.audit_log_id AND audit.action='branding.updated' AND audit.object_type='branding_config' AND audit.object_id=NEW.branding_config_id AND audit.actor_user_id=NEW.actor_user_id AND audit.request_id=NEW.request_id AND audit.trace_id=NEW.trace_id AND audit.created_at=NEW.created_at) OR NEW.payload_sha256<>metahub_sha256(NEW.payload_json) OR NOT json_valid(NEW.changed_fields_json) OR json_type(NEW.changed_fields_json)<>'array' OR NOT json_valid(NEW.payload_json) OR json_type(NEW.payload_json)<>'object' OR EXISTS(SELECT 1 FROM branding_events current WHERE current.branding_event_id=NEW.branding_event_id OR(NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='branding_event_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_branding_events_owner_insert_prd088" BEFORE INSERT ON "branding_events" FOR EACH ROW EXECUTE FUNCTION "fn_trg_branding_events_owner_insert_prd088"();
CREATE OR REPLACE FUNCTION "fn_trg_branding_event_outbox_owner_insert_prd088"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS(SELECT 1 FROM branding_events event WHERE event.tenant_id=NEW.tenant_id AND event.branding_event_id=NEW.branding_event_id AND NEW.branding_event_outbox_id='bro_'||substr(event.branding_event_id,5) AND NEW.webhook_event_id='evt_brd_'||substr(event.branding_event_id,5) AND event.payload_json=NEW.payload_json AND event.payload_sha256=NEW.payload_sha256) OR NEW.status<>'pending' OR NEW.attempt_count<>0 OR NEW.generation<>0 OR NEW.lease_owner_id IS NOT NULL OR NEW.lease_token IS NOT NULL OR NEW.lease_expires_at IS NOT NULL OR NEW.last_error_code IS NOT NULL OR NEW.delivered_at IS NOT NULL OR NEW.next_attempt_at<>NEW.created_at OR NEW.updated_at<>NEW.created_at OR NEW.snapshot_frozen_at IS NULL OR NEW.snapshot_frozen_at<>NEW.created_at OR NOT json_valid(NEW.subscription_snapshot_json) OR json_type(NEW.subscription_snapshot_json)<>'array' OR metahub_json(NEW.subscription_snapshot_json)<>NEW.subscription_snapshot_json OR EXISTS(SELECT 1 FROM json_each(NEW.subscription_snapshot_json) WHERE type<>'text' OR value OPERATOR(public.!@@) 'whd_[0-9a-f]*') OR EXISTS(SELECT 1 FROM json_each(NEW.subscription_snapshot_json) item WHERE NOT EXISTS(SELECT 1 FROM webhook_deliveries delivery WHERE delivery.tenant_id=NEW.tenant_id AND delivery.webhook_delivery_id=item.value AND delivery.event_id=NEW.webhook_event_id AND delivery.delivery_kind='original')) OR (SELECT COUNT(*) FROM json_each(NEW.subscription_snapshot_json)) <>(SELECT COUNT(DISTINCT value) FROM json_each(NEW.subscription_snapshot_json)) OR EXISTS(SELECT 1 FROM branding_event_outbox current WHERE current.branding_event_outbox_id=NEW.branding_event_outbox_id OR(current.tenant_id=NEW.tenant_id AND current.branding_event_id=NEW.branding_event_id) OR(NEW.ctid IS NOT NULL AND current.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='branding_outbox_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_branding_event_outbox_owner_insert_prd088" BEFORE INSERT ON "branding_event_outbox" FOR EACH ROW EXECUTE FUNCTION "fn_trg_branding_event_outbox_owner_insert_prd088"();
CREATE OR REPLACE FUNCTION "fn_trg_branding_event_outbox_transition_prd088"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.ctid<>OLD.ctid OR NEW.branding_event_outbox_id<>OLD.branding_event_outbox_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.branding_event_id<>OLD.branding_event_id OR NEW.webhook_event_id<>OLD.webhook_event_id OR NEW.payload_json<>OLD.payload_json OR NEW.payload_sha256<>OLD.payload_sha256 OR NEW.created_at<>OLD.created_at OR NEW.subscription_snapshot_json IS DISTINCT FROM OLD.subscription_snapshot_json OR NEW.snapshot_frozen_at IS DISTINCT FROM OLD.snapshot_frozen_at OR unixepoch(NEW.updated_at)<unixepoch(OLD.updated_at) OR NOT((OLD.status='pending' AND NEW.status='leased' AND NEW.attempt_count=OLD.attempt_count+1 AND NEW.generation=OLD.generation+1 AND NEW.lease_owner_id IS NOT NULL AND NEW.lease_token IS NOT NULL AND NEW.lease_expires_at IS NOT NULL AND NEW.next_attempt_at IS NULL AND NEW.delivered_at IS NULL) OR(OLD.status='leased' AND NEW.status='leased' AND NEW.attempt_count=OLD.attempt_count AND NEW.generation=OLD.generation+1 AND NEW.lease_owner_id=OLD.lease_owner_id AND NEW.lease_token<>OLD.lease_token AND NEW.lease_expires_at IS NOT NULL AND NEW.delivered_at IS NULL) OR(OLD.status='leased' AND NEW.status='pending' AND NEW.attempt_count=OLD.attempt_count AND NEW.generation=OLD.generation+1 AND NEW.lease_owner_id IS NULL AND NEW.lease_token IS NULL AND NEW.lease_expires_at IS NULL AND NEW.next_attempt_at IS NOT NULL AND NEW.delivered_at IS NULL) OR(OLD.status='leased' AND NEW.status IN('delivered','no_subscription','failed') AND NEW.attempt_count=OLD.attempt_count AND NEW.generation=OLD.generation+1 AND NEW.lease_owner_id IS NULL AND NEW.lease_token IS NULL AND NEW.lease_expires_at IS NULL AND ((NEW.status IN('delivered','no_subscription') AND NEW.delivered_at IS NOT NULL) OR(NEW.status='failed' AND NEW.attempt_count=10 AND NEW.delivered_at IS NULL))))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='branding_outbox_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_branding_event_outbox_transition_prd088" BEFORE UPDATE ON "branding_event_outbox" FOR EACH ROW EXECUTE FUNCTION "fn_trg_branding_event_outbox_transition_prd088"();
