CREATE OR REPLACE FUNCTION "fn_trg_users_identity_status_update_prd091"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF NEW.status<>OLD.status THEN
    UPDATE global_accounts SET status=CASE WHEN login_enabled=1 THEN NEW.status ELSE status END, session_revision=session_revision+1,updated_at=NEW.updated_at WHERE account_id=(SELECT account_id FROM account_identity_links WHERE source_type='legacy_user' AND legacy_tenant_id=NEW.tenant_id AND legacy_user_id=NEW.user_id);
    UPDATE global_sessions SET status='revoked',revoked_at=NEW.updated_at,revoked_reason='account_disabled', updated_at=NEW.updated_at WHERE account_id=(SELECT account_id FROM account_identity_links WHERE source_type='legacy_user' AND legacy_tenant_id=NEW.tenant_id AND legacy_user_id=NEW.user_id) AND status='active' AND NEW.status='disabled';
  END IF;
  RETURN NEW;
END;
$trigger$;
