LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT ( OLD.status='pending' AND NEW.status='consumed' AND NEW.consumed_at IS NOT NULL AND NEW.workspace_user_projection_claim_id=OLD.workspace_user_projection_claim_id AND NEW.workspace_id=OLD.workspace_id AND NEW.tenant_id=OLD.tenant_id AND NEW.account_id=OLD.account_id AND NEW.legacy_user_id=OLD.legacy_user_id AND NEW.credential_revision=OLD.credential_revision AND NEW.email_normalized=OLD.email_normalized AND NEW.expires_at=OLD.expires_at AND NEW.created_at=OLD.created_at )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='workspace_projection_claim_immutable';
  END IF;
  RETURN NEW;
END;
$trigger$;
