CREATE OR REPLACE FUNCTION "fn_trg_tenants_workspace_backfill_prd093"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM workspace_tenant_creation_claims c WHERE c.tenant_id=NEW.tenant_id AND c.status='pending' AND c.expires_at>=strftime('%Y-%m-%dT%H:%M:%SZ','now')) THEN
    INSERT INTO workspaces( workspace_id,kind,status,profile_state,creation_source,revision, created_by_account_id,created_at,updated_at) VALUES( 'wsp_'||substr(metahub_sha256(NEW.tenant_id),1,32),'organization', 'migration_conflict','migration_conflict', CASE WHEN NEW.slug='default' THEN 'legacy_bootstrap' ELSE 'legacy_backfill' END, 1,NULL,NEW.created_at,NEW.updated_at);
    INSERT INTO workspace_tenant_bindings( workspace_tenant_binding_id,workspace_id,tenant_id,status,created_at) VALUES('wtb_'||substr(metahub_sha256(NEW.tenant_id),1,32), 'wsp_'||substr(metahub_sha256(NEW.tenant_id),1,32),NEW.tenant_id, 'active',NEW.created_at);
    INSERT INTO workspace_regions( workspace_region_id,workspace_id,tenant_id,region_code, residency_policy_version,status,created_at) VALUES('wrg_'||substr(metahub_sha256(NEW.tenant_id),1,32), 'wsp_'||substr(metahub_sha256(NEW.tenant_id),1,32),NEW.tenant_id, 'cn-north-1','legacy-domestic-v1','active',NEW.created_at);
    INSERT INTO organization_profiles( organization_profile_id,workspace_id,name,slug_normalized,profile_state, revision,created_at,updated_at) VALUES('org_'||substr(metahub_sha256(NEW.tenant_id),1,32), 'wsp_'||substr(metahub_sha256(NEW.tenant_id),1,32),NEW.name,lower(NEW.slug), 'migration_conflict',1,NEW.created_at,NEW.updated_at);
    INSERT INTO workspace_provisioning_jobs( workspace_provisioning_job_id,workspace_id,tenant_id,generation,status, attempt_count,error_code,next_attempt_at,created_at,updated_at) VALUES('wpj_'||substr(metahub_sha256(NEW.tenant_id),1,32), 'wsp_'||substr(metahub_sha256(NEW.tenant_id),1,32),NEW.tenant_id,1,'failed',0, 'workspace.migration_conflict',NULL,NEW.created_at,NEW.updated_at);
    INSERT INTO workspace_environment_origins( workspace_environment_origin_id,workspace_id,tenant_id,environment_id,origin,created_at) SELECT 'weo_'||substr(metahub_sha256(e.tenant_id||chr(31)||e.environment_id),1,32), 'wsp_'||substr(metahub_sha256(e.tenant_id),1,32),e.tenant_id,e.environment_id, 'legacy_existing',e.created_at FROM environments e WHERE e.tenant_id=NEW.tenant_id ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_tenants_workspace_backfill_prd093" AFTER INSERT ON "tenants" FOR EACH ROW EXECUTE FUNCTION "fn_trg_tenants_workspace_backfill_prd093"();
CREATE OR REPLACE FUNCTION "fn_trg_environments_workspace_origin_prd093"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  INSERT INTO workspace_environment_origins( workspace_environment_origin_id,workspace_id,tenant_id,environment_id,origin,created_at) SELECT 'weo_'||substr(metahub_sha256(NEW.tenant_id||chr(31)||NEW.environment_id),1,32), b.workspace_id,NEW.tenant_id,NEW.environment_id,'legacy_existing',NEW.created_at FROM workspace_tenant_bindings b JOIN workspaces w ON w.workspace_id=b.workspace_id WHERE b.tenant_id=NEW.tenant_id AND w.creation_source<>'user_created' ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_environments_workspace_origin_prd093" AFTER INSERT ON "environments" FOR EACH ROW EXECUTE FUNCTION "fn_trg_environments_workspace_origin_prd093"();
CREATE OR REPLACE FUNCTION "fn_trg_users_projection_claim_validate_prd093"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (EXISTS(SELECT 1 FROM workspace_user_projection_claims c WHERE c.tenant_id=NEW.tenant_id AND c.legacy_user_id=NEW.user_id AND c.status='pending') AND NOT EXISTS( SELECT 1 FROM workspace_user_projection_claims c JOIN global_accounts a ON a.account_id=c.account_id JOIN account_credentials credential ON credential.account_id=a.account_id AND credential.credential_type='password' AND credential.status='active' WHERE c.tenant_id=NEW.tenant_id AND c.legacy_user_id=NEW.user_id AND c.status='pending' AND c.expires_at>=strftime('%Y-%m-%dT%H:%M:%SZ','now') AND c.credential_revision=a.credential_revision AND c.email_normalized=lower(trim(NEW.email)) AND credential.secret_hash=NEW.password_hash AND a.status='active' AND a.login_enabled=1 AND EXISTS(SELECT 1 FROM account_verifications verification WHERE verification.account_id=a.account_id) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='workspace_projection_claim_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_users_projection_claim_validate_prd093" BEFORE INSERT ON "users" FOR EACH ROW EXECUTE FUNCTION "fn_trg_users_projection_claim_validate_prd093"();
CREATE OR REPLACE FUNCTION "fn_trg_users_identity_insert_prd093"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  INSERT INTO global_accounts( account_id,email_normalized,phone_e164,display_name,status,login_enabled, credential_revision,session_revision,mfa_state,failed_login_count,locked_until, last_login_at,created_at,updated_at) SELECT 'gac_'||substr(metahub_sha256(NEW.tenant_id||chr(31)||NEW.user_id),1,32), lower(trim(NEW.email)),NULL,NEW.display_name, CASE WHEN length(trim(NEW.email))<>octet_length(convert_to(trim(NEW.email),'UTF8')) OR length(trim(NEW.email)) NOT BETWEEN 3 AND 320 OR instr(trim(NEW.email),'@')<=1 OR instr(substr(trim(NEW.email),instr(trim(NEW.email),'@')+1),'@')>0 OR instr(trim(NEW.email),' ')>0 OR metahub_password_hash_algorithm(NEW.password_hash) IS NULL OR (SELECT COUNT(*) FROM users x WHERE lower(trim(x.email))=lower(trim(NEW.email)))<>1 THEN 'migration_conflict' ELSE NEW.status END, CASE WHEN length(trim(NEW.email))=octet_length(convert_to(trim(NEW.email),'UTF8')) AND length(trim(NEW.email)) BETWEEN 3 AND 320 AND instr(trim(NEW.email),'@')>1 AND instr(substr(trim(NEW.email),instr(trim(NEW.email),'@')+1),'@')=0 AND instr(trim(NEW.email),' ')=0 AND metahub_password_hash_algorithm(NEW.password_hash) IS NOT NULL AND (SELECT COUNT(*) FROM users x WHERE lower(trim(x.email))=lower(trim(NEW.email)))=1 THEN 1 ELSE 0 END, 1,1,'not_enrolled',NEW.failed_login_count,NEW.locked_until,NEW.last_login_at, NEW.created_at,NEW.updated_at WHERE NOT EXISTS(SELECT 1 FROM workspace_user_projection_claims c WHERE c.tenant_id=NEW.tenant_id AND c.legacy_user_id=NEW.user_id AND c.status='pending');
  INSERT INTO account_credentials( credential_id,account_id,credential_type,algorithm,secret_hash,status,version, created_at,updated_at,rotated_at) SELECT 'acr_'||substr(metahub_sha256(NEW.tenant_id||chr(31)||NEW.user_id),1,32), 'gac_'||substr(metahub_sha256(NEW.tenant_id||chr(31)||NEW.user_id),1,32), 'password',coalesce(metahub_password_hash_algorithm(NEW.password_hash),'unknown'), NEW.password_hash,'active',1,NEW.created_at,NEW.updated_at,NULL WHERE NOT EXISTS(SELECT 1 FROM workspace_user_projection_claims c WHERE c.tenant_id=NEW.tenant_id AND c.legacy_user_id=NEW.user_id AND c.status='pending');
  INSERT INTO account_identity_links( identity_link_id,account_id,source_type,legacy_tenant_id,legacy_user_id,status,linked_at) SELECT 'ail_'||substr(metahub_sha256(NEW.tenant_id||chr(31)||NEW.user_id),1,32), 'gac_'||substr(metahub_sha256(NEW.tenant_id||chr(31)||NEW.user_id),1,32), 'legacy_user',NEW.tenant_id,NEW.user_id,'active',NEW.created_at WHERE NOT EXISTS(SELECT 1 FROM workspace_user_projection_claims c WHERE c.tenant_id=NEW.tenant_id AND c.legacy_user_id=NEW.user_id AND c.status='pending');
  INSERT INTO account_identity_links( identity_link_id,account_id,source_type,legacy_tenant_id,legacy_user_id,status,linked_at) SELECT 'ail_'||substr(metahub_sha256(NEW.tenant_id||chr(31)||NEW.user_id),1,32), c.account_id,'legacy_user',NEW.tenant_id,NEW.user_id,'active',NEW.created_at FROM workspace_user_projection_claims c WHERE c.tenant_id=NEW.tenant_id AND c.legacy_user_id=NEW.user_id AND c.status='pending';
  INSERT INTO workspace_memberships( workspace_membership_id,workspace_id,tenant_id,account_id,legacy_user_id, role_code,status,source,revision,created_at,updated_at) SELECT 'wmb_'||substr(metahub_sha256(NEW.tenant_id),1,32),w.workspace_id,NEW.tenant_id, l.account_id,NEW.user_id,'owner','active','legacy_backfill',1,NEW.created_at,NEW.updated_at FROM workspaces w JOIN workspace_tenant_bindings b ON b.workspace_id=w.workspace_id JOIN account_identity_links l ON l.legacy_tenant_id=NEW.tenant_id AND l.legacy_user_id=NEW.user_id AND l.status='active' JOIN global_accounts a ON a.account_id=l.account_id WHERE b.tenant_id=NEW.tenant_id AND w.creation_source<>'user_created' AND NEW.role='admin' AND NEW.status='active' AND a.status='active' AND a.login_enabled=1 AND EXISTS(SELECT 1 FROM environments e WHERE e.tenant_id=NEW.tenant_id AND e.code='dev' AND e.status='active') AND NOT EXISTS(SELECT 1 FROM workspace_memberships existing WHERE existing.workspace_id=w.workspace_id) ON CONFLICT DO NOTHING;
  UPDATE workspaces SET status='active',profile_state='confirmed',created_by_account_id=( SELECT l.account_id FROM account_identity_links l WHERE l.legacy_tenant_id=NEW.tenant_id AND l.legacy_user_id=NEW.user_id), updated_at=NEW.updated_at WHERE workspace_id='wsp_'||substr(metahub_sha256(NEW.tenant_id),1,32) AND creation_source<>'user_created' AND EXISTS(SELECT 1 FROM workspace_memberships m WHERE m.workspace_id=workspaces.workspace_id AND m.legacy_user_id=NEW.user_id);
  UPDATE organization_profiles SET profile_state='confirmed',updated_at=NEW.updated_at WHERE workspace_id='wsp_'||substr(metahub_sha256(NEW.tenant_id),1,32) AND EXISTS(SELECT 1 FROM workspace_memberships m WHERE m.workspace_id=organization_profiles.workspace_id AND m.legacy_user_id=NEW.user_id);
  UPDATE workspace_provisioning_jobs SET status='ready',error_code=NULL,updated_at=NEW.updated_at WHERE tenant_id=NEW.tenant_id AND EXISTS(SELECT 1 FROM workspace_memberships m WHERE m.workspace_id=workspace_provisioning_jobs.workspace_id AND m.legacy_user_id=NEW.user_id);
  UPDATE global_accounts SET status='migration_conflict',login_enabled=0,updated_at=NEW.updated_at WHERE account_id IN( SELECT l.account_id FROM account_identity_links l JOIN users u ON u.tenant_id=l.legacy_tenant_id AND u.user_id=l.legacy_user_id WHERE lower(trim(u.email))=lower(trim(NEW.email)) ) AND (SELECT COUNT(*) FROM users x WHERE lower(trim(x.email))=lower(trim(NEW.email)))>1 AND NOT EXISTS(SELECT 1 FROM workspace_user_projection_claims c WHERE c.tenant_id=NEW.tenant_id AND c.legacy_user_id=NEW.user_id AND c.status='pending');
  INSERT INTO identity_migration_conflicts( conflict_id,account_id,identifier_fingerprint,reason_code,status,detected_at) SELECT 'icf_'||substr(metahub_sha256(l.legacy_tenant_id||chr(31)||l.legacy_user_id),1,32), l.account_id,metahub_sha256(lower(trim(NEW.email))),'duplicate_identifier','open', strftime('%Y-%m-%dT%H:%M:%SZ','now') FROM account_identity_links l JOIN users u ON u.tenant_id=l.legacy_tenant_id AND u.user_id=l.legacy_user_id WHERE lower(trim(u.email))=lower(trim(NEW.email)) AND (SELECT COUNT(*) FROM users x WHERE lower(trim(x.email))=lower(trim(NEW.email)))>1 AND NOT EXISTS(SELECT 1 FROM workspace_user_projection_claims c WHERE c.tenant_id=NEW.tenant_id AND c.legacy_user_id=NEW.user_id AND c.status='pending') ON CONFLICT DO NOTHING;
  INSERT INTO identity_migration_conflicts( conflict_id,account_id,identifier_fingerprint,reason_code,status,detected_at) SELECT 'icf_'||substr(metahub_sha256(NEW.tenant_id||chr(31)||NEW.user_id),1,32), 'gac_'||substr(metahub_sha256(NEW.tenant_id||chr(31)||NEW.user_id),1,32), metahub_sha256(lower(trim(NEW.email))), CASE WHEN length(trim(NEW.email))<>octet_length(convert_to(trim(NEW.email),'UTF8')) THEN 'identifier_requires_claim' WHEN metahub_password_hash_algorithm(NEW.password_hash) IS NULL THEN 'credential_unrecognized' ELSE 'identifier_invalid' END, 'open',strftime('%Y-%m-%dT%H:%M:%SZ','now') WHERE (SELECT status FROM global_accounts WHERE account_id= 'gac_'||substr(metahub_sha256(NEW.tenant_id||chr(31)||NEW.user_id),1,32)) ='migration_conflict' AND NOT EXISTS(SELECT 1 FROM workspace_user_projection_claims c WHERE c.tenant_id=NEW.tenant_id AND c.legacy_user_id=NEW.user_id AND c.status='pending') ON CONFLICT DO NOTHING;
  UPDATE workspace_user_projection_claims SET status='consumed',consumed_at=NEW.created_at WHERE tenant_id=NEW.tenant_id AND legacy_user_id=NEW.user_id AND status='pending';
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_users_identity_insert_prd093" AFTER INSERT ON "users" FOR EACH ROW EXECUTE FUNCTION "fn_trg_users_identity_insert_prd093"();
CREATE OR REPLACE FUNCTION "fn_trg_users_identity_password_update_prd093"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF NEW.password_hash<>OLD.password_hash THEN
    UPDATE account_credentials SET secret_hash=NEW.password_hash, algorithm=coalesce(metahub_password_hash_algorithm(NEW.password_hash),'unknown'), version=version+1,updated_at=NEW.updated_at,rotated_at=NEW.updated_at WHERE account_id=(SELECT account_id FROM account_identity_links WHERE source_type='legacy_user' AND legacy_tenant_id=NEW.tenant_id AND legacy_user_id=NEW.user_id);
    UPDATE global_accounts SET credential_revision=credential_revision+1,session_revision=session_revision+1, updated_at=NEW.updated_at, status=CASE WHEN metahub_password_hash_algorithm(NEW.password_hash) IS NOT NULL THEN CASE WHEN login_enabled=1 THEN NEW.status ELSE status END ELSE 'migration_conflict' END, login_enabled=CASE WHEN metahub_password_hash_algorithm(NEW.password_hash) IS NOT NULL THEN login_enabled ELSE 0 END WHERE account_id=(SELECT account_id FROM account_identity_links WHERE source_type='legacy_user' AND legacy_tenant_id=NEW.tenant_id AND legacy_user_id=NEW.user_id);
    UPDATE global_sessions SET status='revoked',revoked_at=NEW.updated_at,revoked_reason='credential_rotated', updated_at=NEW.updated_at WHERE account_id=(SELECT account_id FROM account_identity_links WHERE source_type='legacy_user' AND legacy_tenant_id=NEW.tenant_id AND legacy_user_id=NEW.user_id) AND status='active';
    UPDATE users SET password_hash=NEW.password_hash,updated_at=NEW.updated_at WHERE (tenant_id,user_id) IN( SELECT legacy_tenant_id,legacy_user_id FROM account_identity_links WHERE account_id=(SELECT account_id FROM account_identity_links WHERE source_type='legacy_user' AND legacy_tenant_id=NEW.tenant_id AND legacy_user_id=NEW.user_id) AND source_type='legacy_user' AND status='active' ) AND NOT(tenant_id=NEW.tenant_id AND user_id=NEW.user_id) AND password_hash<>NEW.password_hash;
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_users_identity_password_update_prd093" AFTER UPDATE OF "password_hash" ON "users" FOR EACH ROW EXECUTE FUNCTION "fn_trg_users_identity_password_update_prd093"();
