CREATE OR REPLACE FUNCTION "fn_trg_workspaces_owner_update_prd093"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF NEW.workspace_id<>OLD.workspace_id OR NEW.kind<>OLD.kind OR NEW.creation_source<>OLD.creation_source OR (NEW.created_by_account_id IS DISTINCT FROM OLD.created_by_account_id AND NOT ( OLD.creation_source IN('legacy_bootstrap','legacy_backfill') AND OLD.status='migration_conflict' AND NEW.status='active' AND OLD.created_by_account_id IS NULL AND NEW.created_by_account_id IS NOT NULL )) OR NEW.created_at<>OLD.created_at THEN
    IF NEW.workspace_id=OLD.workspace_id AND NEW.kind=OLD.kind AND NEW.creation_source=OLD.creation_source AND NEW.created_at=OLD.created_at AND OLD.creation_source IN('legacy_bootstrap','legacy_backfill') AND OLD.status='active' AND NEW.status='active' AND OLD.profile_state='confirmed' AND NEW.profile_state='confirmed' AND OLD.created_by_account_id IS NOT NULL AND NEW.created_by_account_id IS DISTINCT FROM OLD.created_by_account_id AND EXISTS(SELECT 1 FROM workspace_memberships owner_member WHERE owner_member.workspace_id=OLD.workspace_id AND owner_member.account_id=OLD.created_by_account_id AND owner_member.role_code='owner' AND owner_member.status='active') AND EXISTS(SELECT 1 FROM workspace_memberships projected_member WHERE projected_member.workspace_id=OLD.workspace_id AND projected_member.account_id=NEW.created_by_account_id AND projected_member.role_code<>'owner' AND projected_member.status='active') THEN
      RETURN NULL;
    ELSE
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='workspace_owner_immutable';
    END IF;
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_workspaces_owner_update_prd093" BEFORE UPDATE ON "workspaces" FOR EACH ROW EXECUTE FUNCTION "fn_trg_workspaces_owner_update_prd093"();
