CREATE OR REPLACE FUNCTION "fn_trg_account_links_membership_backfill_prd094"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF NEW.source_type='legacy_user' AND NEW.status='active' AND NOT EXISTS(SELECT 1 FROM workspace_user_projection_claims claim WHERE claim.tenant_id=NEW.legacy_tenant_id AND claim.legacy_user_id=NEW.legacy_user_id AND claim.status='pending') AND NOT EXISTS( SELECT 1 FROM membership_invitations membership_invitation JOIN invitations invitation ON invitation.tenant_id=membership_invitation.tenant_id AND invitation.invitation_id=membership_invitation.legacy_invitation_id JOIN users invited_user ON invited_user.tenant_id=invitation.tenant_id AND invited_user.user_id=NEW.legacy_user_id WHERE membership_invitation.status='pending' AND invitation.status='pending' AND invitation.tenant_id=NEW.legacy_tenant_id AND lower(invitation.email)=lower(invited_user.email)) THEN
    INSERT INTO workspace_memberships( workspace_membership_id,workspace_id,tenant_id,account_id,legacy_user_id, role_code,status,source,revision,created_by_account_id,updated_by_account_id, created_at,updated_at) SELECT 'wmb_'||lower(hex(randomblob(16))),binding.workspace_id,NEW.legacy_tenant_id, NEW.account_id,NEW.legacy_user_id, CASE WHEN user_row.role='admin' AND user_row.status='active' AND NOT EXISTS(SELECT 1 FROM workspace_memberships current WHERE current.workspace_id=binding.workspace_id) AND workspace.creation_source<>'user_created' THEN 'owner' WHEN user_row.role IN('admin','ops_admin') THEN 'admin' WHEN user_row.role='developer' THEN 'developer' WHEN user_row.role='security_admin' THEN 'security_admin' WHEN user_row.role='finance_admin' THEN 'finance_admin' ELSE 'viewer' END, CASE WHEN user_row.status='active' THEN 'active' ELSE 'disabled' END, 'legacy_backfill',1,NEW.account_id,NEW.account_id,user_row.created_at,user_row.updated_at FROM workspace_tenant_bindings binding JOIN workspaces workspace ON workspace.workspace_id=binding.workspace_id JOIN users user_row ON user_row.tenant_id=NEW.legacy_tenant_id AND user_row.user_id=NEW.legacy_user_id WHERE binding.tenant_id=NEW.legacy_tenant_id AND workspace.workspace_id NOT IN( SELECT conflict.workspace_id FROM workspace_membership_migration_conflicts conflict) AND NOT EXISTS(SELECT 1 FROM workspace_memberships current WHERE current.workspace_id=binding.workspace_id AND current.account_id=NEW.account_id) ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_account_links_membership_backfill_prd094" AFTER INSERT ON "account_identity_links" FOR EACH ROW EXECUTE FUNCTION "fn_trg_account_links_membership_backfill_prd094"();
CREATE OR REPLACE FUNCTION "fn_trg_global_sessions_revoke_workspace_prd094"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
