CREATE OR REPLACE FUNCTION "fn_trg_platform_operator_revoke_prd095"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  UPDATE platform_sessions SET status='revoked',revoked_at=NEW.updated_at, revoked_reason='operator_changed',updated_at=NEW.updated_at WHERE operator_id=NEW.operator_id AND status='active';
  UPDATE support_sessions SET status='revoked',revoked_at=NEW.updated_at,updated_at=NEW.updated_at WHERE operator_id=NEW.operator_id AND status='active';
