CREATE OR REPLACE FUNCTION "fn_trg_workspace_binding_operational_initialize_prd096"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  INSERT INTO workspace_operational_states( workspace_operational_state_id,workspace_id,tenant_id,status,revision,risk_revision, source,suspended_reason_code,suspended_by_operator_id,suspended_at,created_at,updated_at) SELECT 'wos_'||lower(hex(randomblob(16))),NEW.workspace_id,NEW.tenant_id, CASE WHEN workspace.status='active' AND NEW.status='active' AND tenant.status='active' AND data_state.lifecycle_status='active' THEN 'active' ELSE 'migration_conflict' END, 1,1,'workspace_creation',NULL,NULL,NULL, strftime('%Y-%m-%dT%H:%M:%SZ','now'),strftime('%Y-%m-%dT%H:%M:%SZ','now') FROM workspaces workspace JOIN tenants tenant ON tenant.tenant_id=NEW.tenant_id JOIN tenant_data_states data_state ON data_state.tenant_id=NEW.tenant_id WHERE workspace.workspace_id=NEW.workspace_id;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_workspace_binding_operational_initialize_prd096" AFTER INSERT ON "workspace_tenant_bindings" FOR EACH ROW EXECUTE FUNCTION "fn_trg_workspace_binding_operational_initialize_prd096"();
CREATE OR REPLACE FUNCTION "fn_trg_tenant_data_operational_transition_prd096"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF NEW.lifecycle_status<>OLD.lifecycle_status THEN
    UPDATE workspace_operational_states SET status=CASE WHEN NEW.lifecycle_status='deleted' AND (SELECT status FROM tenants WHERE tenant_id=NEW.tenant_id)='disabled' THEN 'deleted' ELSE 'deletion_pending' END, revision=revision+1,source='data_lifecycle', suspended_reason_code=NULL,suspended_by_operator_id=NULL,suspended_at=NULL, updated_at=NEW.updated_at WHERE tenant_id=NEW.tenant_id AND status<>'deleted';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_tenant_data_operational_transition_prd096" AFTER UPDATE OF "lifecycle_status" ON "tenant_data_states" FOR EACH ROW EXECUTE FUNCTION "fn_trg_tenant_data_operational_transition_prd096"();
