CREATE OR REPLACE FUNCTION "fn_trg_workspace_binding_onboarding_initialize_prd097"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  INSERT INTO onboarding_progress( onboarding_progress_id,workspace_id,tenant_id,workspace_kind,initialization_source, generation,completed_steps,status,projection_sha256,evaluated_at,activated_at, revision,created_at,updated_at) SELECT 'onp_'||substr(metahub_sha256(NEW.workspace_id||chr(31)||'progress'),1,32), NEW.workspace_id,NEW.tenant_id,workspace.kind,'workspace_created',0,0,'incomplete', metahub_sha256('onboarding-v1'||chr(31)||workspace.kind||chr(31)||'00000000'), NEW.created_at,NULL,1,NEW.created_at,NEW.created_at FROM workspaces workspace WHERE workspace.workspace_id=NEW.workspace_id;
  INSERT INTO onboarding_step_facts( onboarding_step_fact_id,workspace_id,tenant_id,step_id,status,source,evidence_kind, evidence_sha256,source_generation,first_satisfied_at,last_satisfied_at,last_checked_at, revision,created_at,updated_at) SELECT 'ons_'||substr(metahub_sha256(NEW.workspace_id||chr(31)||step.step_id),1,32), NEW.workspace_id,NEW.tenant_id,step.step_id, CASE WHEN step.step_order=1 THEN 'current' ELSE 'blocked' END, CASE WHEN step.step_id='workspace_profile' THEN 'system_created' ELSE 'none' END, step.evidence_kind, metahub_sha256('onboarding-v1'||chr(31)||step.step_id||chr(31)||'incomplete'), 0,NULL,NULL,NEW.created_at,1,NEW.created_at,NEW.created_at FROM ( SELECT 1 step_order,'workspace_profile' step_id,'profile_confirmation' evidence_kind UNION ALL SELECT 2,'environment','environment_confirmation' UNION ALL SELECT 3,'provider','provider_probe' UNION ALL SELECT 4,'model','model_binding' UNION ALL SELECT 5,'model_alias','alias_binding' UNION ALL SELECT 6,'project_application','project_application_binding' UNION ALL SELECT 7,'virtual_key','virtual_key_binding' UNION ALL SELECT 8,'first_call','gateway_usage' ) step;
  RETURN NEW;
END;
$trigger$;
