LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.platform_alert_id<>OLD.platform_alert_id OR NEW.dedupe_sha256<>OLD.dedupe_sha256 OR NEW.service_level_objective_id<>OLD.service_level_objective_id OR NEW.slo_version<>OLD.slo_version OR NEW.service_code<>OLD.service_code OR NEW.region_code<>OLD.region_code OR NEW.safe_reason_code<>OLD.safe_reason_code OR NEW.source_watermark<OLD.source_watermark OR NEW.first_seen_at<>OLD.first_seen_at OR NEW.created_at<>OLD.created_at OR NEW.revision<>OLD.revision+1 OR NEW.updated_at<=OLD.updated_at OR NOT((OLD.state='firing' AND NEW.state IN('firing','suppressed','resolved')) OR(OLD.state='suppressed' AND NEW.state IN('firing','suppressed','resolved')) OR(OLD.state='resolved' AND NEW.state IN('resolved','firing')))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='platform_alert_transition_invalid';
  END IF;
  RETURN NEW;
END;
