CREATE OR REPLACE FUNCTION "fn_trg_workspace_memberships_insert_prd115"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.revision<>1 OR (NEW.role_code<>'service_account' AND NOT EXISTS( SELECT 1 FROM account_identity_links link WHERE link.account_id=NEW.account_id AND link.legacy_tenant_id=NEW.tenant_id AND link.legacy_user_id=NEW.legacy_user_id AND link.status='active')) OR (NEW.lifecycle_source='scim' AND (NEW.role_code IN('owner','service_account') OR NEW.source<>'membership_invitation'))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='workspace_membership_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
