LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.workspace_membership_id<>OLD.workspace_membership_id OR NEW.workspace_id<>OLD.workspace_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.account_id<>OLD.account_id OR NEW.legacy_user_id IS DISTINCT FROM OLD.legacy_user_id OR NEW.source<>OLD.source OR NEW.lifecycle_source<>OLD.lifecycle_source OR NEW.created_by_account_id IS DISTINCT FROM OLD.created_by_account_id OR NEW.created_at<>OLD.created_at OR NEW.revision<>OLD.revision+1 OR (OLD.lifecycle_source='scim' AND OLD.status='disabled' AND NEW.status='active') OR ((OLD.role_code='owner' OR NEW.role_code='owner') AND NOT EXISTS( SELECT 1 FROM owner_transfers transfer WHERE transfer.workspace_id=OLD.workspace_id AND transfer.status='pending' AND (transfer.source_membership_id=OLD.workspace_membership_id OR transfer.target_membership_id=OLD.workspace_membership_id))) OR (OLD.role_code='owner' AND (NEW.role_code<>'owner' OR NEW.status<>'active') AND (SELECT COUNT(*) FROM workspace_memberships member WHERE member.workspace_id=OLD.workspace_id AND member.role_code='owner' AND member.status='active')<=1)) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='workspace_membership_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
