CREATE OR REPLACE FUNCTION "fn_trg_workspace_regions_governance_seed_prd117"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF NEW.status='active' THEN
    INSERT INTO data_classifications( data_classification_id,workspace_id,tenant_id,code,sensitivity_level, allowed_purposes_json,default_retention_days,catalog_revision,status,created_at) SELECT 'dcl_'||lower(hex(randomblob(16))),NEW.workspace_id,NEW.tenant_id,value, CASE value WHEN 'identity' THEN 'restricted' WHEN 'billing' THEN 'confidential' WHEN 'audit' THEN 'confidential' ELSE 'restricted' END, CASE value WHEN 'identity' THEN (jsonb_build_array('authentication','security')::TEXT) WHEN 'billing' THEN (jsonb_build_array('billing','compliance')::TEXT) WHEN 'audit' THEN (jsonb_build_array('security','compliance')::TEXT) ELSE (jsonb_build_array('service_delivery','security')::TEXT) END, CASE value WHEN 'prompt' THEN 30 WHEN 'response' THEN 30 WHEN 'file' THEN 90 WHEN 'audit' THEN 365 WHEN 'identity' THEN 365 WHEN 'billing' THEN 2555 END, 1,'active',strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM json_each((jsonb_build_array('prompt','response','file','audit','identity','billing')::TEXT));
    INSERT INTO data_governance_fences VALUES( 'dgf_'||lower(hex(randomblob(16))),NEW.workspace_id,NEW.tenant_id,1,0,0,1, strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now'));
    INSERT INTO residency_policies( residency_policy_id,workspace_id,tenant_id,allowed_residency_groups_json, primary_residency_group,cross_region_mode,status,revision,generation,policy_sha256, reason_code,updated_by_account_id,valid_until,superseded_at,created_at,updated_at) SELECT 'rgp_'||lower(hex(randomblob(16))),NEW.workspace_id,NEW.tenant_id, (jsonb_build_array(region.residency_group)::TEXT),region.residency_group,'same_group','active',1,1, metahub_sha256((jsonb_build_object('workspace_id',NEW.workspace_id,'tenant_id',NEW.tenant_id, 'generation',1,'allowed_residency_groups',(jsonb_build_array(region.residency_group)::TEXT), 'primary_residency_group',region.residency_group,'cross_region_mode','same_group')::TEXT)), 'initial_policy',NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now','+3650 days'),NULL, strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM platform_regions region WHERE region.region_code=NEW.region_code;
    INSERT INTO retention_policies( retention_policy_id,workspace_id,tenant_id,data_classification_id,classification_code, retention_days,deletion_mode,backup_grace_days,status,revision,generation, superseded_at,created_at,updated_at) SELECT 'rtp_'||lower(hex(randomblob(16))),classification.workspace_id, classification.tenant_id,classification.data_classification_id,classification.code, classification.default_retention_days, CASE WHEN classification.code IN('audit','billing') THEN 'archive_then_delete' WHEN classification.code='identity' THEN 'anonymize' ELSE 'hard_delete' END, CASE WHEN classification.code IN('audit','billing') THEN 30 ELSE 7 END, 'active',1,1,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM data_classifications classification WHERE classification.workspace_id=NEW.workspace_id;
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_workspace_regions_governance_seed_prd117" AFTER INSERT ON "workspace_regions" FOR EACH ROW EXECUTE FUNCTION "fn_trg_workspace_regions_governance_seed_prd117"();
