CREATE OR REPLACE FUNCTION "fn_trg_client_credentials_insert_prd118"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.status<>'active' OR NOT EXISTS( SELECT 1 FROM oauth_clients client WHERE client.oauth_client_id=NEW.oauth_client_id AND client.workspace_id=NEW.workspace_id AND client.tenant_id=NEW.tenant_id AND client.status='active' AND ( NEW.generation=client.credential_generation OR(NEW.generation=client.credential_generation+1 AND NOT EXISTS(SELECT 1 FROM client_credentials active WHERE active.oauth_client_id=client.oauth_client_id AND active.status='active') AND EXISTS(SELECT 1 FROM client_credentials previous WHERE previous.oauth_client_id=client.oauth_client_id AND previous.generation=client.credential_generation AND previous.status='grace'))))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='client_credential_owner_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_client_credentials_insert_prd118" BEFORE INSERT ON "client_credentials" FOR EACH ROW EXECUTE FUNCTION "fn_trg_client_credentials_insert_prd118"();
CREATE OR REPLACE FUNCTION "fn_trg_client_credentials_update_prd118"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.client_credential_id<>OLD.client_credential_id OR NEW.oauth_client_id<>OLD.oauth_client_id OR NEW.workspace_id<>OLD.workspace_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.generation<>OLD.generation OR NEW.secret_hash<>OLD.secret_hash OR NEW.secret_prefix<>OLD.secret_prefix OR NEW.expires_at<>OLD.expires_at OR NEW.created_at<>OLD.created_at OR OLD.status='revoked' OR (OLD.last_used_at IS NOT NULL AND (NEW.last_used_at IS NULL OR NEW.last_used_at<OLD.last_used_at)) OR NEW.updated_at<OLD.updated_at OR NOT( (NEW.status=OLD.status AND NEW.grace_expires_at IS NOT DISTINCT FROM OLD.grace_expires_at AND NEW.revoked_at IS NOT DISTINCT FROM OLD.revoked_at) OR(OLD.status='active' AND NEW.status='grace' AND OLD.grace_expires_at IS NULL AND NEW.grace_expires_at IS NOT NULL AND NEW.revoked_at IS NOT DISTINCT FROM OLD.revoked_at AND NEW.last_used_at IS NOT DISTINCT FROM OLD.last_used_at) OR(OLD.status IN('active','grace') AND NEW.status='revoked' AND NEW.grace_expires_at IS NOT DISTINCT FROM OLD.grace_expires_at AND OLD.revoked_at IS NULL AND NEW.revoked_at IS NOT NULL AND NEW.last_used_at IS NOT DISTINCT FROM OLD.last_used_at))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='client_credential_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
