CREATE OR REPLACE FUNCTION "fn_trg_oauth_clients_update_prd118"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.oauth_client_id<>OLD.oauth_client_id OR NEW.client_id<>OLD.client_id OR NEW.service_account_id<>OLD.service_account_id OR NEW.workspace_id<>OLD.workspace_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.audience<>OLD.audience OR NEW.created_at<>OLD.created_at OR OLD.status='revoked' OR NEW.revision NOT IN(OLD.revision,OLD.revision+1) OR NEW.credential_generation NOT IN( OLD.credential_generation,OLD.credential_generation+1) OR (OLD.last_used_at IS NOT NULL AND (NEW.last_used_at IS NULL OR NEW.last_used_at<OLD.last_used_at)) OR NEW.updated_at<OLD.updated_at OR (NEW.revision=OLD.revision AND ( NEW.status<>OLD.status OR NEW.credential_generation<>OLD.credential_generation OR NEW.revoked_at IS DISTINCT FROM OLD.revoked_at)) OR (NEW.revision=OLD.revision+1 AND NOT( (OLD.status='active' AND NEW.status='active' AND NEW.credential_generation=OLD.credential_generation+1 AND NEW.revoked_at IS NOT DISTINCT FROM OLD.revoked_at AND NEW.last_used_at IS NOT DISTINCT FROM OLD.last_used_at AND EXISTS(SELECT 1 FROM client_credentials credential WHERE credential.oauth_client_id=OLD.oauth_client_id AND credential.generation=NEW.credential_generation AND credential.status='active')) OR(OLD.status IN('active','rotating') AND NEW.status='revoked' AND NEW.credential_generation=OLD.credential_generation AND OLD.revoked_at IS NULL AND NEW.revoked_at IS NOT NULL AND NEW.last_used_at IS NOT DISTINCT FROM OLD.last_used_at)))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='oauth_client_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_oauth_clients_update_prd118" BEFORE UPDATE ON "oauth_clients" FOR EACH ROW EXECUTE FUNCTION "fn_trg_oauth_clients_update_prd118"();
CREATE OR REPLACE FUNCTION "fn_trg_access_token_grants_insert_prd118"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (json_array_length(NEW.scopes_json)<1 OR NOT EXISTS( SELECT 1 FROM oauth_clients client JOIN service_accounts account ON account.service_account_id=client.service_account_id AND account.workspace_id=client.workspace_id AND account.tenant_id=client.tenant_id JOIN client_credentials credential ON credential.oauth_client_id=client.oauth_client_id AND credential.generation=NEW.credential_generation WHERE client.oauth_client_id=NEW.oauth_client_id AND account.service_account_id=NEW.service_account_id AND client.workspace_id=NEW.workspace_id AND client.tenant_id=NEW.tenant_id AND client.status='active' AND account.status='active' AND credential.status IN('active','grace')) OR EXISTS(SELECT 1 FROM json_each(NEW.scopes_json) requested WHERE requested.type<>'text' OR NOT EXISTS( SELECT 1 FROM service_account_scopes assigned JOIN machine_permission_catalog catalog ON catalog.permission_code=assigned.permission_code AND catalog.status='active' WHERE assigned.service_account_id=NEW.service_account_id AND assigned.permission_code=requested.value))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='access_token_grant_owner_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_access_token_grants_insert_prd118" BEFORE INSERT ON "access_token_grants" FOR EACH ROW EXECUTE FUNCTION "fn_trg_access_token_grants_insert_prd118"();
