CREATE OR REPLACE FUNCTION "fn_trg_machine_identity_outbox_insert_prd118"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS( SELECT 1 FROM machine_identity_audits audit JOIN service_accounts account ON account.workspace_id=audit.workspace_id AND account.tenant_id=audit.tenant_id AND account.service_account_id=NEW.aggregate_id WHERE audit.machine_identity_audit_id=NEW.machine_identity_audit_id AND audit.workspace_id=NEW.workspace_id AND audit.tenant_id=NEW.tenant_id AND audit.action_code=NEW.event_type AND audit.subject_type='human' AND audit.resource_type='service_account' AND audit.resource_id=NEW.aggregate_id AND audit.outcome='success' AND audit.resource_revision=NEW.aggregate_revision) OR (SELECT COUNT(*) FROM json_each(NEW.payload_json))<>CASE NEW.event_type WHEN 'service_account.revoked' THEN 3 ELSE 4 END OR EXISTS(SELECT 1 FROM json_each(NEW.payload_json) item WHERE item.key NOT IN( 'service_account_id','revision','status','constraint_generation', 'credential_generation')) OR json_extract(NEW.payload_json,'$.service_account_id')<>NEW.aggregate_id OR (json_extract(NEW.payload_json,'$.revision'))::NUMERIC<>NEW.aggregate_revision OR json_extract(NEW.payload_json,'$.status') NOT IN('active','revoked') OR (NEW.event_type='service_account.created' AND ( json_extract(NEW.payload_json,'$.status')<>'active' OR json_type(NEW.payload_json,'$.constraint_generation')<>'integer' OR json_type(NEW.payload_json,'$.credential_generation') IS NOT NULL)) OR (NEW.event_type='service_account.credential_rotated' AND ( json_extract(NEW.payload_json,'$.status')<>'active' OR json_type(NEW.payload_json,'$.credential_generation')<>'integer' OR json_type(NEW.payload_json,'$.constraint_generation') IS NOT NULL)) OR (NEW.event_type='service_account.revoked' AND ( json_extract(NEW.payload_json,'$.status')<>'revoked' OR json_type(NEW.payload_json,'$.credential_generation') IS NOT NULL OR json_type(NEW.payload_json,'$.constraint_generation') IS NOT NULL))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='machine_identity_outbox_owner_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_machine_identity_outbox_insert_prd118" BEFORE INSERT ON "machine_identity_event_outbox" FOR EACH ROW EXECUTE FUNCTION "fn_trg_machine_identity_outbox_insert_prd118"();
CREATE OR REPLACE FUNCTION "fn_trg_machine_identity_outbox_update_prd118"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.machine_identity_outbox_id<>OLD.machine_identity_outbox_id OR NEW.machine_identity_audit_id<>OLD.machine_identity_audit_id OR NEW.workspace_id<>OLD.workspace_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.event_type<>OLD.event_type OR NEW.aggregate_id<>OLD.aggregate_id OR NEW.aggregate_revision<>OLD.aggregate_revision OR NEW.payload_json<>OLD.payload_json OR NEW.created_at<>OLD.created_at OR NEW.updated_at<=OLD.updated_at OR NOT( (OLD.status='pending' AND NEW.status='delivering' AND NEW.attempt_count=OLD.attempt_count+1 AND NEW.next_attempt_at IS NOT DISTINCT FROM OLD.next_attempt_at) OR(OLD.status='delivering' AND NEW.status='delivering' AND NEW.attempt_count=OLD.attempt_count AND NEW.next_attempt_at IS NOT DISTINCT FROM OLD.next_attempt_at AND NEW.lease_owner_id=OLD.lease_owner_id AND NEW.lease_token=OLD.lease_token AND NEW.lease_expires_at>OLD.lease_expires_at) OR(OLD.status='delivering' AND NEW.status='delivered' AND NEW.attempt_count=OLD.attempt_count AND NEW.next_attempt_at IS NOT DISTINCT FROM OLD.next_attempt_at) OR(OLD.status='delivering' AND NEW.status IN('pending','failed') AND NEW.attempt_count=OLD.attempt_count AND NEW.next_attempt_at IS NOT NULL) OR(OLD.status='failed' AND NEW.status='pending' AND NEW.attempt_count=OLD.attempt_count AND NEW.next_attempt_at IS NOT NULL))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='machine_identity_outbox_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_machine_identity_outbox_update_prd118" BEFORE UPDATE ON "machine_identity_event_outbox" FOR EACH ROW EXECUTE FUNCTION "fn_trg_machine_identity_outbox_update_prd118"();
