CREATE OR REPLACE FUNCTION "fn_trg_machine_identity_commands_insert_prd118"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT( (NEW.subject_type='human' AND EXISTS( SELECT 1 FROM workspace_memberships member WHERE member.workspace_id=NEW.workspace_id AND member.tenant_id=NEW.tenant_id AND member.account_id=NEW.subject_id AND member.status='active')) OR(NEW.subject_type='service_account' AND EXISTS( SELECT 1 FROM service_accounts account WHERE account.workspace_id=NEW.workspace_id AND account.tenant_id=NEW.tenant_id AND account.service_account_id=NEW.subject_id))) OR NOT( (NEW.action_code IN('service_account.create','service_account.revoke') AND NEW.resource_type='service_account' AND NEW.result_generation=0 AND EXISTS(SELECT 1 FROM service_accounts account WHERE account.workspace_id=NEW.workspace_id AND account.tenant_id=NEW.tenant_id AND account.service_account_id=NEW.resource_id AND account.revision=NEW.result_revision)) OR(NEW.action_code IN('oauth_client.create','oauth_client.rotate') AND NEW.resource_type='oauth_client' AND NEW.result_generation>=1 AND EXISTS(SELECT 1 FROM oauth_clients client WHERE client.workspace_id=NEW.workspace_id AND client.tenant_id=NEW.tenant_id AND client.oauth_client_id=NEW.resource_id AND client.revision=NEW.result_revision AND client.credential_generation=NEW.result_generation)) OR(NEW.action_code='oauth.token.issue' AND NEW.subject_type='service_account' AND NEW.resource_type='access_token_grant' AND NEW.result_generation>=1 AND EXISTS(SELECT 1 FROM access_token_grants grant_row WHERE grant_row.workspace_id=NEW.workspace_id AND grant_row.tenant_id=NEW.tenant_id AND grant_row.access_token_grant_id=NEW.resource_id AND grant_row.service_account_id=NEW.subject_id AND grant_row.credential_generation=NEW.result_generation)))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='machine_identity_command_owner_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
