CREATE OR REPLACE FUNCTION "fn_trg_installer_releases_insert_prd124"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.status<>'approval_pending' OR NEW.revision<>1) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='installer_release_insert_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
