CREATE OR REPLACE FUNCTION "fn_trg_installer_releases_update_prd124"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.installer_release_id<>OLD.installer_release_id OR NEW.version<>OLD.version OR NEW.channel<>OLD.channel OR NEW.manifest_sha256<>OLD.manifest_sha256 OR NEW.sbom_sha256<>OLD.sbom_sha256 OR NEW.signature_algorithm<>OLD.signature_algorithm OR NEW.signature_key_id<>OLD.signature_key_id OR NEW.signature_value<>OLD.signature_value OR NEW.signature_purpose<>OLD.signature_purpose OR NEW.supported_os_json<>OLD.supported_os_json OR NEW.supported_arch_json<>OLD.supported_arch_json OR NEW.schema_min<>OLD.schema_min OR NEW.schema_max<>OLD.schema_max OR NEW.agent_min_version<>OLD.agent_min_version OR NEW.agent_max_version<>OLD.agent_max_version OR NEW.control_min_version<>OLD.control_min_version OR NEW.control_max_version<>OLD.control_max_version OR NEW.n_minus_one<>OLD.n_minus_one OR NEW.submitted_by_account_id<>OLD.submitted_by_account_id OR NEW.submitted_at<>OLD.submitted_at OR NEW.revision<>OLD.revision+1 OR (OLD.status='approval_pending' AND NEW.status NOT IN('released','withdrawn')) OR (OLD.status='released' AND NEW.status<>'withdrawn') OR OLD.status='withdrawn') THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='installer_release_transition_invalid';
  END IF;
  RETURN NEW;
END;
