CREATE OR REPLACE FUNCTION "fn_trg_migration_runs_update_prd131"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.migration_run_id<>OLD.migration_run_id OR NEW.workspace_id<>OLD.workspace_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.migration_assessment_id<>OLD.migration_assessment_id OR NEW.migration_plan_id<>OLD.migration_plan_id OR NEW.generation<>OLD.generation OR NEW.freeze_generation<>OLD.freeze_generation OR NEW.source_manifest_sha256<>OLD.source_manifest_sha256 OR NEW.authorization_fingerprint_sha256<>OLD.authorization_fingerprint_sha256 OR NEW.requested_by_account_id<>OLD.requested_by_account_id OR NEW.started_at<>OLD.started_at OR NEW.revision<>OLD.revision+1 OR NEW.updated_at<=OLD.updated_at OR NOT ((OLD.status='observing' AND NEW.status IN('completed','failed','rolling_back')) OR(OLD.status IN('completed','failed') AND NEW.status='rolling_back') OR(OLD.status='rolling_back' AND NEW.status IN('rolled_back','failed')))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='migration_run_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
