CREATE OR REPLACE FUNCTION "fn_trg_service_accounts_update_prd118"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.service_account_id<>OLD.service_account_id OR NEW.workspace_id<>OLD.workspace_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.name<>OLD.name OR NEW.display_name<>OLD.display_name OR NEW.scope_template<>OLD.scope_template OR NEW.catalog_revision<>OLD.catalog_revision OR NEW.constraint_sha256<>OLD.constraint_sha256 OR NEW.ip_allowlist_json<>OLD.ip_allowlist_json OR NEW.mtls_fingerprint_sha256 IS DISTINCT FROM OLD.mtls_fingerprint_sha256 OR NEW.token_ttl_seconds<>OLD.token_ttl_seconds OR NEW.created_by_account_id<>OLD.created_by_account_id OR NEW.created_at<>OLD.created_at OR NEW.revision NOT IN(OLD.revision,OLD.revision+1) OR NEW.constraint_generation NOT IN(OLD.constraint_generation,OLD.constraint_generation+1) OR (NEW.revision=OLD.revision AND NEW.constraint_generation<>OLD.constraint_generation) OR (NEW.revision=OLD.revision+1 AND NEW.constraint_generation<>OLD.constraint_generation+1) OR (NEW.revision=OLD.revision AND (NEW.status<>OLD.status OR NEW.updated_by_account_id<>OLD.updated_by_account_id OR NEW.revoked_at IS DISTINCT FROM OLD.revoked_at)) OR (NEW.revision=OLD.revision+1 AND NOT( OLD.status IN('active','disabled') AND NEW.status='revoked' AND OLD.revoked_at IS NULL AND NEW.revoked_at IS NOT NULL)) OR (NEW.last_used_at IS NOT NULL AND OLD.last_used_at IS NOT NULL AND NEW.last_used_at<OLD.last_used_at) OR NEW.updated_at<OLD.updated_at) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='service_account_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_service_accounts_update_prd118" BEFORE UPDATE ON "service_accounts" FOR EACH ROW EXECUTE FUNCTION "fn_trg_service_accounts_update_prd118"();
