CREATE OR REPLACE FUNCTION "fn_trg_machine_identity_audits_insert_prd118"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS(SELECT 1 FROM workspace_tenant_bindings binding WHERE binding.workspace_id=NEW.workspace_id AND binding.tenant_id=NEW.tenant_id) OR (NEW.subject_type='human' AND NOT EXISTS( SELECT 1 FROM workspace_memberships member WHERE member.workspace_id=NEW.workspace_id AND member.tenant_id=NEW.tenant_id AND member.account_id=NEW.subject_id AND member.status='active' AND member.role_code<>'service_account')) OR (NEW.subject_type='service_account' AND NOT EXISTS( SELECT 1 FROM service_accounts account WHERE account.workspace_id=NEW.workspace_id AND account.tenant_id=NEW.tenant_id AND account.service_account_id=NEW.subject_id)) OR NOT( (NEW.subject_type='human' AND NEW.outcome='success' AND NEW.action_code='service_account.created' AND NEW.resource_type='service_account' AND EXISTS( SELECT 1 FROM service_accounts account WHERE account.workspace_id=NEW.workspace_id AND account.tenant_id=NEW.tenant_id AND account.service_account_id=NEW.resource_id AND account.revision=NEW.resource_revision)) OR(NEW.subject_type='human' AND NEW.outcome='success' AND NEW.action_code='oauth_client.created' AND NEW.resource_type='oauth_client' AND EXISTS( SELECT 1 FROM oauth_clients client WHERE client.workspace_id=NEW.workspace_id AND client.tenant_id=NEW.tenant_id AND client.oauth_client_id=NEW.resource_id AND client.revision=NEW.resource_revision)) OR(NEW.subject_type='human' AND NEW.outcome='success' AND NEW.action_code IN( 'service_account.credential_rotated','service_account.revoked') AND NEW.resource_type='service_account' AND EXISTS( SELECT 1 FROM service_accounts account WHERE account.workspace_id=NEW.workspace_id AND account.tenant_id=NEW.tenant_id AND account.service_account_id=NEW.resource_id)) OR(NEW.subject_type='service_account' AND NEW.outcome='success' AND NEW.action_code='oauth.token_issued' AND NEW.resource_type='access_token_grant' AND EXISTS( SELECT 1 FROM access_token_grants grant_record WHERE grant_record.workspace_id=NEW.workspace_id AND grant_record.tenant_id=NEW.tenant_id AND grant_record.service_account_id=NEW.subject_id AND grant_record.access_token_grant_id=NEW.resource_id)) OR(NEW.subject_type='service_account' AND NEW.action_code='machine.provider_listed' AND NEW.resource_type='provider_collection' AND NEW.resource_id='/providers') OR(NEW.subject_type='service_account' AND NEW.action_code='machine.request_log_listed' AND NEW.resource_type='request_log_collection' AND NEW.resource_id='/request-logs') OR(NEW.subject_type='service_account' AND NEW.action_code='machine.compliance_evidence_submitted' AND NEW.resource_type='compliance_evidence_collection' AND NEW.resource_id='/platform/compliance/evidence'))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='machine_identity_audit_owner_invalid';
  END IF;
  RETURN NEW;
