CREATE OR REPLACE FUNCTION "fn_trg_compliance_evidence_insert_prd135"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS(SELECT 1 FROM workspace_tenant_bindings binding WHERE binding.workspace_id=NEW.workspace_id AND binding.tenant_id=NEW.tenant_id AND binding.status='active') OR NOT EXISTS(SELECT 1 FROM service_accounts account JOIN service_account_scopes scope ON scope.service_account_id=account.service_account_id AND scope.permission_code='compliance.collect' WHERE account.workspace_id=NEW.workspace_id AND account.tenant_id=NEW.tenant_id AND account.service_account_id=NEW.collector_service_account_id AND account.status='active' AND account.scope_template='compliance_collector') OR NOT EXISTS(SELECT 1 FROM compliance_controls control WHERE control.compliance_control_id=NEW.compliance_control_id AND control.status='active' AND control.evidence_kind=NEW.evidence_kind AND control.collector_schema_version=NEW.schema_version)) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='compliance_evidence_owner_invalid';
  END IF;
  RETURN NEW;
END;
