LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.compliance_exception_id<>OLD.compliance_exception_id OR NEW.workspace_id<>OLD.workspace_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.compliance_control_id<>OLD.compliance_control_id OR NEW.evidence_generation<>OLD.evidence_generation OR NEW.reason_code<>OLD.reason_code OR NEW.compensating_controls<>OLD.compensating_controls OR NEW.requester_account_id<>OLD.requester_account_id OR NEW.starts_at<>OLD.starts_at OR NEW.expires_at<>OLD.expires_at OR NEW.created_at<>OLD.created_at OR NEW.revision<>OLD.revision+1 OR NEW.updated_at<=OLD.updated_at OR NEW.review_generation<OLD.review_generation OR NOT((OLD.status='pending' AND NEW.status IN('active','expired')) OR(OLD.status='active' AND NEW.status='expired')) OR (NEW.status='active' AND (NEW.approver_account_id IS NULL OR NEW.approver_account_id=OLD.requester_account_id OR NEW.approved_at IS NULL OR NEW.review_generation<>OLD.review_generation+1))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='compliance_exception_transition_invalid';
  END IF;
  RETURN NEW;
END;
