LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS(SELECT 1 FROM compliance_evidence evidence WHERE evidence.workspace_id=NEW.workspace_id AND evidence.tenant_id=NEW.tenant_id AND evidence.compliance_evidence_id=NEW.failed_evidence_id AND evidence.compliance_control_id=NEW.compliance_control_id AND evidence.evidence_generation=NEW.failed_evidence_generation AND evidence.outcome='failed')) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='compliance_remediation_owner_invalid';
  END IF;
  RETURN NEW;
END;
