BEGIN;
SET LOCAL client_min_messages = warning;
CREATE OR REPLACE FUNCTION "fn_trg_compliance_remediation_update_prd135"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.remediation_task_id<>OLD.remediation_task_id OR NEW.workspace_id<>OLD.workspace_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.compliance_control_id<>OLD.compliance_control_id OR NEW.failed_evidence_id<>OLD.failed_evidence_id OR NEW.failed_evidence_generation<>OLD.failed_evidence_generation OR NEW.owner_code<>OLD.owner_code OR NEW.due_at<>OLD.due_at OR NEW.created_at<>OLD.created_at OR NEW.revision<>OLD.revision+1 OR NEW.updated_at<=OLD.updated_at OR NOT((OLD.status='open' AND NEW.status IN('in_progress','blocked','verified')) OR(OLD.status='in_progress' AND NEW.status IN('blocked','verified')) OR(OLD.status='blocked' AND NEW.status IN('in_progress','verified')) OR(OLD.status='verified' AND NEW.status='closed')) OR (NEW.status IN('verified','closed') AND NOT EXISTS( SELECT 1 FROM compliance_evidence evidence WHERE evidence.workspace_id=NEW.workspace_id AND evidence.tenant_id=NEW.tenant_id AND evidence.compliance_evidence_id=NEW.verified_evidence_id AND evidence.compliance_control_id=NEW.compliance_control_id AND evidence.evidence_generation=NEW.verified_evidence_generation AND evidence.evidence_generation>NEW.failed_evidence_generation AND evidence.outcome='passed'))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='compliance_remediation_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
