CREATE OR REPLACE FUNCTION "fn_trg_patch_release_insert_prd136"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.rollback_artifact_sha256<>NEW.affected_artifact_sha256 OR NOT EXISTS( SELECT 1 FROM vulnerability_findings finding JOIN sdk_releases affected ON affected.sdk_release_id=finding.sdk_release_id JOIN sdk_releases fixed ON fixed.sdk_release_id=NEW.fixed_sdk_release_id JOIN release_artifact_signatures signature ON signature.sdk_release_id=fixed.sdk_release_id WHERE finding.vulnerability_finding_id=NEW.vulnerability_finding_id AND finding.status='active' AND finding.affected_artifact_sha256=NEW.affected_artifact_sha256 AND affected.language=fixed.language AND fixed.status='published' AND fixed.artifact_sha256=NEW.fixed_artifact_sha256 AND signature.verification_outcome='passed')) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='patch_release_scope_invalid';
  END IF;
  RETURN NEW;
END;
