CREATE OR REPLACE FUNCTION "fn_trg_launch_candidate_update_prd138"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.launch_candidate_id<>OLD.launch_candidate_id OR NEW.candidate_sha256<>OLD.candidate_sha256 OR NEW.code_tree_sha256<>OLD.code_tree_sha256 OR NEW.migration_set_sha256<>OLD.migration_set_sha256 OR NEW.contract_set_sha256<>OLD.contract_set_sha256 OR NEW.artifact_set_sha256<>OLD.artifact_set_sha256 OR NEW.test_manifest_sha256<>OLD.test_manifest_sha256 OR NEW.gate_policy_set_sha256<>OLD.gate_policy_set_sha256 OR NEW.generation<>OLD.generation OR NEW.requested_by_operator_id<>OLD.requested_by_operator_id OR NEW.requested_permission_revision<>OLD.requested_permission_revision OR NEW.created_at<>OLD.created_at OR NEW.revision<>OLD.revision+1 OR NEW.updated_at<=OLD.updated_at OR NOT( (OLD.status='collecting' AND NEW.status IN('collecting','signing','failed','stale')) OR (OLD.status='signing' AND NEW.status IN('signing','ready','failed','stale')) OR (OLD.status='ready' AND NEW.status IN('ready','launching','failed','stale')) OR (OLD.status='launching' AND NEW.status IN( 'launching','paused','review_pending','rollback_pending','failed')) OR (OLD.status='paused' AND NEW.status IN('paused','launching','rollback_pending','failed')) OR (OLD.status='review_pending' AND NEW.status IN( 'review_pending','release_candidate','rollback_pending','failed')) OR (OLD.status='release_candidate' AND NEW.status IN( 'release_candidate','rollback_pending','stale')) OR (OLD.status='rollback_pending' AND NEW.status IN( 'rollback_pending','rolled_back','failed')) OR (OLD.status='rolled_back' AND NEW.status='rolled_back') OR (OLD.status='failed' AND NEW.status='failed') OR (OLD.status='stale' AND NEW.status='stale'))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='launch_candidate_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
