CREATE OR REPLACE FUNCTION "fn_trg_roles_owner_insert_prd059"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS(SELECT 1 FROM tenants WHERE tenant_id=NEW.tenant_id) OR NEW.code NOT IN('admin','developer','viewer','finance_admin','security_admin','ops_admin') OR NEW.permission_revision<>1 OR NEW.matrix_sha256<>CASE NEW.code WHEN 'admin' THEN 'a9ceca1ab103efaaa8b6f2ba23713e0fa2c46e18be8709bef25ef607ed329c1c' WHEN 'developer' THEN 'ee1bc616db2e67a2ddf1e984b938c92033ed3d486ea0b9f52300c2579dc943b1' WHEN 'viewer' THEN '612465d72c402e7d35c56779b4644d0603571f56b4714053d2b30bc3fb2a769e' WHEN 'finance_admin' THEN '86b64ca3b997f5fa252f027ecf07430e677252e6d2c17677b72ac049130cba8c' WHEN 'security_admin' THEN '8365be2449480db94f2075bbb4925ac40b9cdd8fad4cb9629e2b5c291daf8a75' WHEN 'ops_admin' THEN 'aae41c1ea441876e4b810ba4f80f0de4ac7b1d8cb2a6386c07e3564ab7e44dba' END OR NEW.is_permission_immutable<>CASE WHEN NEW.code='admin' THEN 1 ELSE 0 END) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='rbac_role_immutable';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_roles_owner_insert_prd059" BEFORE INSERT ON "roles" FOR EACH ROW EXECUTE FUNCTION "fn_trg_roles_owner_insert_prd059"();
CREATE OR REPLACE FUNCTION "fn_trg_roles_matrix_update_prd059"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (OLD.code='admin' OR NEW.ctid<>OLD.ctid OR NEW.role_id<>OLD.role_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.code<>OLD.code OR NEW.name<>OLD.name OR NEW.description<>OLD.description OR NEW.status<>OLD.status OR NEW.created_at<>OLD.created_at OR NEW.is_permission_immutable<>OLD.is_permission_immutable OR NEW.permission_revision<>OLD.permission_revision+1 OR NEW.matrix_sha256=OLD.matrix_sha256 OR length(NEW.matrix_sha256)<>64 OR NEW.matrix_sha256 OPERATOR(public.@@) '*[^0-9a-f]*') THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='rbac_role_immutable';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_roles_matrix_update_prd059" BEFORE UPDATE ON "roles" FOR EACH ROW EXECUTE FUNCTION "fn_trg_roles_matrix_update_prd059"();
CREATE OR REPLACE FUNCTION "fn_trg_role_permissions_owner_insert_prd059"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS(SELECT 1 FROM roles r JOIN permissions p ON p.tenant_id=r.tenant_id JOIN rbac_role_permission_templates t ON t.role_code=r.code AND t.permission_code=p.code WHERE r.tenant_id=NEW.tenant_id AND r.role_id=NEW.role_id AND r.status='active' AND p.permission_id=NEW.permission_id AND p.status='active') OR EXISTS(SELECT 1 FROM role_permissions x WHERE x.role_permission_id=NEW.role_permission_id OR(x.tenant_id=NEW.tenant_id AND x.role_id=NEW.role_id AND x.permission_id=NEW.permission_id) OR(NEW.ctid IS NOT NULL AND x.ctid=NEW.ctid))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='rbac_role_permission_owner_mismatch';
  END IF;
  RETURN NEW;
END;
$trigger$;
