CREATE OR REPLACE FUNCTION "fn_trg_routing_candidates_prd050_conflict_insert"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (EXISTS ( SELECT 1 FROM routing_candidates current WHERE current.routing_candidate_id=NEW.routing_candidate_id OR current.ctid=NEW.ctid ) OR EXISTS ( SELECT 1 FROM routing_candidates current WHERE current.tenant_id=NEW.tenant_id AND current.routing_decision_id=NEW.routing_decision_id AND current.candidate_role=NEW.candidate_role ) OR ( NEW.rank IS NOT NULL AND EXISTS ( SELECT 1 FROM routing_candidates current WHERE current.tenant_id=NEW.tenant_id AND current.routing_decision_id=NEW.routing_decision_id AND current.rank=NEW.rank ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='routing_candidate_immutable';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_routing_candidates_prd050_conflict_insert" BEFORE INSERT ON "routing_candidates" FOR EACH ROW EXECUTE FUNCTION "fn_trg_routing_candidates_prd050_conflict_insert"();
CREATE OR REPLACE FUNCTION "fn_trg_routing_candidates_prd048_graph_insert"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NOT EXISTS ( SELECT 1 FROM routing_decisions d WHERE d.tenant_id=NEW.tenant_id AND d.routing_decision_id=NEW.routing_decision_id AND d.model_alias_id=NEW.model_alias_id AND d.routing_policy_id IS NOT DISTINCT FROM NEW.routing_policy_id ) OR ( NEW.routing_policy_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM routing_decisions d JOIN model_alias_routing_policies rp ON rp.tenant_id=d.tenant_id AND rp.routing_policy_id=d.routing_policy_id WHERE d.tenant_id=NEW.tenant_id AND d.routing_decision_id=NEW.routing_decision_id AND rp.model_alias_id=d.model_alias_id AND rp.version=d.routing_policy_version AND rp.routing_mode=d.routing_mode ) ) OR NOT EXISTS ( SELECT 1 FROM model_aliases a WHERE a.tenant_id=NEW.tenant_id AND a.model_alias_id=NEW.model_alias_id AND ( (NEW.candidate_role='default' AND a.default_model_id=NEW.model_id) OR (NEW.candidate_role='fallback' AND a.fallback_model_id IS NOT NULL AND a.fallback_model_id=NEW.model_id) ) ) OR NOT EXISTS ( SELECT 1 FROM models m WHERE m.tenant_id=NEW.tenant_id AND m.model_id=NEW.model_id AND m.provider_id=NEW.provider_id ) OR ( NEW.status='selected' AND NOT EXISTS ( SELECT 1 FROM routing_decisions d WHERE d.tenant_id=NEW.tenant_id AND d.routing_decision_id=NEW.routing_decision_id AND d.decision_status='selected' AND d.selected_model_id=NEW.model_id AND d.provider_id=NEW.provider_id ) ) OR ( EXISTS ( SELECT 1 FROM routing_decisions d WHERE d.tenant_id=NEW.tenant_id AND d.routing_decision_id=NEW.routing_decision_id AND d.decision_status='failed' ) AND NEW.status<>'rejected' ) OR ( NEW.quality_evidence_state<>'not_evaluated' AND NOT EXISTS ( SELECT 1 FROM model_quality_scores qs JOIN routing_decisions d ON d.tenant_id=NEW.tenant_id AND d.routing_decision_id=NEW.routing_decision_id WHERE qs.tenant_id=NEW.tenant_id AND qs.model_quality_score_id=NEW.model_quality_score_id AND qs.model_id=NEW.model_id AND qs.statistics_version=NEW.quality_statistics_version AND qs.feedback_version=NEW.quality_feedback_version AND qs.sample_count=NEW.quality_sample_count AND qs.success_count=NEW.quality_success_count AND qs.error_count=NEW.quality_error_count AND qs.manual_quality_bps IS NOT DISTINCT FROM NEW.manual_quality_bps AND d.routing_mode='quality_cost' AND ( (NEW.quality_evidence_state='ready' AND (qs.manual_quality_bps IS NOT NULL OR qs.sample_count>=d.minimum_sample_count)) OR (NEW.quality_evidence_state='cold' AND qs.manual_quality_bps IS NULL AND qs.sample_count<d.minimum_sample_count) ) ) ) OR ( NEW.quality_evidence_state='not_evaluated' AND EXISTS ( SELECT 1 FROM routing_decisions d WHERE d.tenant_id=NEW.tenant_id AND d.routing_decision_id=NEW.routing_decision_id AND d.quality_scoring_performed=1 ) ) OR ( NEW.quality_evidence_state<>'not_evaluated' AND EXISTS ( SELECT 1 FROM routing_decisions d WHERE d.tenant_id=NEW.tenant_id AND d.routing_decision_id=NEW.routing_decision_id AND ( (d.quality_scoring_performed=1 AND ( NEW.weighted_score_bps IS NULL OR (d.cost_weight_bps>0 AND NEW.cost_component_bps IS NULL) OR (d.cost_weight_bps=0 AND NEW.cost_component_bps IS NOT NULL) OR (d.latency_weight_bps>0 AND NEW.latency_component_bps IS NULL) OR (d.latency_weight_bps=0 AND NEW.latency_component_bps IS NOT NULL) )) OR (d.quality_scoring_performed=0 AND ( NEW.weighted_score_bps IS NOT NULL OR NEW.cost_component_bps IS NOT NULL OR NEW.latency_component_bps IS NOT NULL )) ) ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='routing_candidate_graph_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_routing_candidates_prd048_graph_insert" BEFORE INSERT ON "routing_candidates" FOR EACH ROW EXECUTE FUNCTION "fn_trg_routing_candidates_prd048_graph_insert"();
