CREATE OR REPLACE FUNCTION "fn_trg_billing_domain_reconciliation_difference_update_prd144"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.billing_domain_reconciliation_difference_id <>OLD.billing_domain_reconciliation_difference_id OR NEW.billing_domain_reconciliation_id<>OLD.billing_domain_reconciliation_id OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.difference_type<>OLD.difference_type OR NEW.left_source_ref<>OLD.left_source_ref OR NEW.right_source_ref IS DISTINCT FROM OLD.right_source_ref OR NEW.currency<>OLD.currency OR NEW.amount_difference_minor<>OLD.amount_difference_minor OR NEW.detected_at<>OLD.detected_at OR NOT((OLD.status='open' AND NEW.status IN('acknowledged','adjusted')) OR(OLD.status='acknowledged' AND NEW.status='adjusted'))) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='billing_domain_reconciliation_difference_state_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
