CREATE OR REPLACE FUNCTION "fn_trg_global_account_preference_insert_prd145"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  INSERT INTO account_preferences( account_preference_id,account_id,locale,status,revision,source, confirmation_state,created_at,updated_at) VALUES( 'acp_'||substr(metahub_sha256('account-preference:'||NEW.account_id),1,32), NEW.account_id,'zh-CN','active',1,'identity','confirmed', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));
  RETURN NEW;
END;
