CREATE OR REPLACE FUNCTION "fn_trg_workspace_navigation_preference_owner_prd146"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.workspace_id<>OLD.workspace_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.account_id<>OLD.account_id OR NEW.workspace_membership_id<>OLD.workspace_membership_id OR NEW.created_at<>OLD.created_at) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='workspace_navigation_preference_owner_immutable';
  END IF;
  RETURN NEW;
END;
