CREATE OR REPLACE FUNCTION "fn_trg_workspace_membership_revoke_navigation_prd146"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF NEW.status<>'active' OR NEW.revision<>OLD.revision THEN
    UPDATE workspace_navigation_preferences SET status='membership_revoked',revision=revision+1, updated_at=NEW.updated_at WHERE workspace_membership_id=NEW.workspace_membership_id AND status='active';
    DELETE FROM workspace_navigation_member_states WHERE workspace_membership_id=NEW.workspace_membership_id;
  END IF;
  RETURN NEW;
END;
$trigger$;
CREATE TRIGGER "trg_workspace_membership_revoke_navigation_prd146" AFTER UPDATE OF "status", "revision" ON "workspace_memberships" FOR EACH ROW EXECUTE FUNCTION "fn_trg_workspace_membership_revoke_navigation_prd146"();
