CREATE OR REPLACE FUNCTION "fn_trg_console_migration_state_prd147"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.operation_generation<>OLD.operation_generation OR NEW.revision<>OLD.revision+1 OR NOT ( NEW.state=OLD.state OR (OLD.state='inventoried' AND NEW.state IN('backfill_queued','blocked')) OR (OLD.state='backfill_queued' AND NEW.state IN('backfilling','blocked')) OR (OLD.state='backfilling' AND NEW.state IN('shadowing','blocked')) OR (OLD.state='shadowing' AND NEW.state IN('ready','blocked')) OR (OLD.state='ready' AND NEW.state IN('quiescing','rollback_queued','blocked')) OR (OLD.state='quiescing' AND NEW.state IN('cutting_over','rollback_queued','blocked')) OR (OLD.state='cutting_over' AND NEW.state IN('validating','rollback_queued','blocked')) OR (OLD.state='validating' AND NEW.state IN('active','rollback_queued','blocked')) OR (OLD.state='active' AND NEW.state='rollback_queued') OR (OLD.state='rollback_queued' AND NEW.state IN('rolling_back','blocked')) OR (OLD.state='rolling_back' AND NEW.state IN('rolled_back','blocked')) OR (OLD.state='blocked' AND NEW.state IN( 'inventoried','backfill_queued','backfilling','shadowing','ready','quiescing', 'cutting_over','validating','rollback_queued','rolling_back')) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='console_domain_migration_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
